if (isset($_GET['drawing'])) {
    $pid = trim($_GET['drawing'] ?? '');
    $db2 = new DBConnection(); $pdo2 = $db2->getPDO();
    $files = [];
    $scan_dir = 'Z:/BOM/'; $url_dir = '/nas/';
    if ($pid) {
        $s2 = $pdo2->prepare("SELECT bom, sqty FROM bom WHERE d_id = ? ORDER BY Created_At DESC");
        $s2->execute([$pid]);
        $bom_rows2 = $s2->fetchAll(PDO::FETCH_ASSOC);
        if (is_dir($scan_dir)) {
            $allF = scandir($scan_dir);
            foreach ($bom_rows2 as $br) {
                foreach ($allF as $fn) {
                    if ($fn==='.'||$fn==='..') continue;
                    if (strpos($fn, $br['bom'])===0) {
                        $ext = strtolower(pathinfo($fn, PATHINFO_EXTENSION));
                        if (in_array($ext, ['jpg','jpeg','png','pdf','stp','step']))
                            $files[] = ['bom'=>$br['bom'].($br['sqty']!==null?' (Qty:'.$br['sqty'].')':''), 'name'=>$fn, 'path'=>$url_dir.$fn, 'type'=>$ext];
                    }
                }
            }
        }
    }
