        ?>
            <div class="dv-item<?=$i===0?' active':''?>" onclick="showDv(this,'<?=addslashes($f['path'])?>','<?=$f['type']?>')">
                <h5><i class="fa <?=$icon?>"></i> <?=safe_html($f['bom'])?><?=$badge?></h5>
