    <script src="../../resource/js/o3dv.min.js"></script>
    <script>
    var st={scale:1,x:0,y:0,drag:false,sx:0,sy:0};
    var _dv3dViewer = null;

    function showDv(el,path,type){
        document.querySelectorAll('.dv-item').forEach(function(c){c.classList.remove('active');});
        el.classList.add('active');
        var v=document.getElementById('dv-viewer');
        _dv3dViewer = null;
        if(type==='pdf'){
            v.innerHTML='<iframe id="dv-iframe" src="'+path+'" style="width:100%;height:100%;border:none;"></iframe>';
        } else if(type==='stp'||type==='step'){
            v.innerHTML='<div id="dv-3d" style="width:100%;height:100%;"></div>'
                +'<div class="dv-3d-tip"><i class="fa fa-mouse-pointer"></i> 左鍵旋轉 &nbsp;|&nbsp; 右鍵平移 &nbsp;|&nbsp; 滾輪縮放</div>';
            init3DViewer(path);
        } else {
            st={scale:1,x:0,y:0,drag:false,sx:0,sy:0};
            v.innerHTML='<img id="dv-img" src="'+path+'" style="max-width:90%;max-height:90%;cursor:grab;transform-origin:center center;transition:transform .05s linear;" ondragstart="return false;">';
            bindImgEvents();
        }
    }

    function init3DViewer(path){
        var container = document.getElementById('dv-3d');
        if(!container || typeof OV === 'undefined') return;
        _dv3dViewer = new OV.EmbeddedViewer(container, {
            backgroundColor: new OV.RGBAColor(44, 44, 44, 255),
            defaultColor:    new OV.RGBColor(200, 200, 200),
            edgeSettings:    new OV.EdgeSettings(false, new OV.RGBColor(0,0,0), 1)
        });
        _dv3dViewer.LoadModelFromUrlList([path]);
    }

    function bindImgEvents(){
        var img=document.getElementById('dv-img');
        if(!img)return;
        document.getElementById('dv-viewer').addEventListener('wheel',function(e){
            e.preventDefault();
            st.scale+=e.deltaY<0?.1:-.1; if(st.scale<.1)st.scale=.1;
            applyT();
        },{passive:false});
        img.addEventListener('mousedown',function(e){st.drag=true;st.sx=e.clientX-st.x;st.sy=e.clientY-st.y;img.style.cursor='grabbing';img.style.transition='none';});
        document.addEventListener('mousemove',function(e){if(!st.drag)return;st.x=e.clientX-st.sx;st.y=e.clientY-st.sy;applyT();});
        document.addEventListener('mouseup',function(){if(st.drag){st.drag=false;var i=document.getElementById('dv-img');if(i){i.style.cursor='grab';i.style.transition='transform .05s linear';}}});
    }
    function applyT(){var img=document.getElementById('dv-img');if(img)img.style.transform='translate('+st.x+'px,'+st.y+'px) scale('+st.scale+')';}

    // 初始化第一個檔案
    <?php if($files && in_array($files[0]['type'],['stp','step'])): ?>
    window.addEventListener('load', function(){ init3DViewer('<?=addslashes($files[0]['path'])?>'); });
    <?php else: ?>
    bindImgEvents();
    <?php endif; ?>
    </script></body></html>
    <?php exit;
}

