    try { $pdo->exec("ALTER TABLE dict_workpiece_type ADD COLUMN show_part_no TINYINT(1) NOT NULL DEFAULT 0 COMMENT '料號表單是否顯示專用料號欄位(多選現有 d_setting 料號 → d_setting_dedicated_part_map)'"); } catch(Exception $e){}
