    try { $pdo->exec("ALTER TABLE maker_proc_label_map ADD COLUMN parent_map_id INT NULL DEFAULT NULL COMMENT '父對應ID (多組時關聯父行)'"); } catch(Exception $e){}
    $pdo->exec("CREATE TABLE IF NOT EXISTS dict_maker_proc_label_parent_map (
        id              INT AUTO_INCREMENT PRIMARY KEY,
