        INDEX idx_parent (parent_label_id)
    ) COMMENT='廠商加工限制標籤 子↔父 多對多對應'");
    try { $pdo->exec("INSERT IGNORE INTO dict_maker_proc_label_parent_map (sub_label_id, parent_label_id) SELECT proc_label_id, parent_label_id FROM dict_maker_proc_label WHERE parent_label_id IS NOT NULL AND is_active=1"); } catch(Exception $e){}
    // ── 廠商大類→製程設定（廠商大類標籤的子標籤來源設定） ───────────────────────
    $pdo->exec("CREATE TABLE IF NOT EXISTS dict_maker_main_cat_process_config (
