        INDEX idx_main_cat (main_cat_id)
    ) COMMENT='廠商大類可選製程設定：設定該大類廠商的子標籤可選哪些製程大類/小類'");
    $pdo->exec("CREATE TABLE IF NOT EXISTS maker_main_cat_process_tag (
        id            INT AUTO_INCREMENT PRIMARY KEY,
        maker_id_no   VARCHAR(11) NOT NULL        COMMENT 'FK → maker_list.maker_id_no',
        main_cat_id   INT NOT NULL               COMMENT 'FK → dict_maker_main_category.main_cat_id',
        ref_type      ENUM('type','no') NOT NULL COMMENT 'type=製程大類 no=製程小類',
        ref_id        INT NOT NULL               COMMENT '製程大類ID或製程小類ProcessNo',
        UNIQUE KEY uq_tag (maker_id_no, main_cat_id, ref_type, ref_id),
        INDEX idx_maker (maker_id_no),
        INDEX idx_main_cat (main_cat_id)
    ) COMMENT='廠商製程標籤：廠商在各大類底下選擇的製程大類/小類'");
    // ── maker_sub_category_mapping: 確保欄位名稱為 maker_id_no VARCHAR(11) ──
    try {
        // 1. 若表不存在，直接建立正確版本
        $pdo->exec("CREATE TABLE IF NOT EXISTS maker_sub_category_mapping (
            maker_id_no VARCHAR(11) NOT NULL COMMENT '對應 maker_list.maker_id_no',
            sub_cat_id  INT NOT NULL,
            PRIMARY KEY (maker_id_no, sub_cat_id),
            INDEX idx_maker (maker_id_no),
            INDEX idx_sub   (sub_cat_id)
        ) COMMENT='廠商能力標籤映射'");

        // 2. 若表已存在但欄位仍為舊名 maker_id (INT)，自動遷移
        $col = $pdo->query("SELECT COLUMN_NAME, DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME   = 'maker_sub_category_mapping'
              AND COLUMN_NAME  = 'maker_id'")->fetch(PDO::FETCH_ASSOC);

        if ($col) {
            // 舊欄位存在：先備份資料到暫存表，重建表，再還原
            $pdo->exec("CREATE TABLE IF NOT EXISTS _msm_backup AS
                SELECT CAST(maker_id AS CHAR) AS maker_id_no, sub_cat_id
                FROM maker_sub_category_mapping");
            $pdo->exec("DROP TABLE maker_sub_category_mapping");
            $pdo->exec("CREATE TABLE maker_sub_category_mapping (
                maker_id_no VARCHAR(11) NOT NULL,
                sub_cat_id  INT NOT NULL,
                PRIMARY KEY (maker_id_no, sub_cat_id),
                INDEX idx_maker (maker_id_no),
                INDEX idx_sub   (sub_cat_id)
            )");
            // 嘗試從備份還原（舊 INT maker_id → VARCHAR maker_id_no 可能無法對應，保守跳過）
            try {
                $pdo->exec("INSERT IGNORE INTO maker_sub_category_mapping (maker_id_no, sub_cat_id)
                    SELECT b.maker_id_no, b.sub_cat_id FROM _msm_backup b
                    JOIN maker_list ml ON ml.maker_id_no = b.maker_id_no");
            } catch(Exception $e2) {}
            try { $pdo->exec("DROP TABLE _msm_backup"); } catch(Exception $e3) {}
        }
    } catch(Exception $e){}
    // ── 一次性同步 process_type → dict_maker_sub_category（初始化用，有即跳過） ──
    try {
        $pdo->exec("INSERT IGNORE INTO dict_maker_sub_category (sub_cat_id, sub_cat_name, sub_cat_group, ref_process_type_id, is_active, sort_order)
            SELECT process_type_id, process_type, 'PROCESS', process_type_id, 1,
                   ROW_NUMBER() OVER (ORDER BY process_type_id)
            FROM process_type WHERE process_type IS NOT NULL");
    } catch(Exception $e){}

    // ── 標籤字典 dict_label ──────────────────────────────────────────────────
