    try { $pdo->exec("ALTER TABLE dict_label ADD COLUMN has_draw_lathe TINYINT NOT NULL DEFAULT 0 COMMENT '是否有圖面與車床尺寸 1=是 0=否'"); } catch(Exception $e){}
    try { $pdo->exec("ALTER TABLE dict_label ADD COLUMN lathe_optional TINYINT NOT NULL DEFAULT 0 COMMENT '車床尺寸可省略（has_draw_lathe=1時有效）'"); } catch(Exception $e){}
    try { $pdo->exec("ALTER TABLE dict_label ADD COLUMN has_draw_lathe_depth TINYINT NOT NULL DEFAULT 0 COMMENT '圖面+車床×深度 1=是 0=否'"); } catch(Exception $e){}
    try { $pdo->exec("ALTER TABLE dict_label ADD COLUMN is_triple_dim TINYINT NOT NULL DEFAULT 0 COMMENT '前綴小圓×前綴大圓×深度後綴 1=是 0=否'"); } catch(Exception $e){}
    try { $pdo->exec("ALTER TABLE dict_label ADD COLUMN calc_base_name VARCHAR(50) NULL COMMENT '計算差異基準項名稱'"); } catch(Exception $e){}
    try { $pdo->exec("ALTER TABLE dict_label ADD COLUMN calc_sub_name VARCHAR(50) NULL COMMENT '計算差異減項名稱'"); } catch(Exception $e){}
    // 修正新式計算差異 calc_value（套用公差修正公式）
    try {
        $recalc_rows = $pdo->query("SELECT ilm.map_id, ilm.draw_dim, ilm.lathe_dim, ilm.tol_upper, l.tolerance_std_upper FROM item_label_map ilm JOIN dict_label l ON l.label_id=ilm.label_id WHERE l.is_calc_diff=1 AND (l.calc_base_label_id IS NULL OR l.calc_base_label_id=0) AND ilm.draw_dim IS NOT NULL AND ilm.lathe_dim IS NOT NULL")->fetchAll(PDO::FETCH_ASSOC);
        $upd_c = $pdo->prepare("UPDATE item_label_map SET calc_value=? WHERE map_id=?");
        foreach ($recalc_rows as $row) {
            $tol_std_r = ($row['tolerance_std_upper'] !== null && $row['tolerance_std_upper'] !== '') ? floatval($row['tolerance_std_upper']) : null;
            $sub_c_r   = floatval($row['lathe_dim']);
            if ($row['tol_upper'] !== null && $tol_std_r !== null) {
                $sub_c_r = $sub_c_r + (floatval($row['tol_upper']) - $tol_std_r);
            }
            $upd_c->execute([round(floatval($row['draw_dim']) - $sub_c_r, 4), $row['map_id']]);
        }
    } catch (Exception $e) {}
    // is_list 出貨統計索引
    try { $pdo->exec("ALTER TABLE is_list ADD INDEX idx_ship_stats (Product_id, Order_date)"); } catch(Exception $e){}
