        input_value    VARCHAR(200) NULL                   COMMENT '輸入的值',
        draw_dim       DECIMAL(10,4) NULL                  COMMENT '圖面尺寸',
        lathe_dim      DECIMAL(10,4) NULL                  COMMENT '車床尺寸',
        created_at     TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
        INDEX idx_parent(parent_map_id),
        INDEX idx_sub(sub_id)
    ) COMMENT='料號子標籤對應'");

    // ── 齒輪類型欄位設定 dict_gear_type_fields ────────────────────────────────
    $pdo->exec("CREATE TABLE IF NOT EXISTS dict_gear_type_fields (
        field_id       INT AUTO_INCREMENT PRIMARY KEY,
        gear_type_id   INT          NOT NULL               COMMENT 'FK → dict_gear_type.gear_type_id',
        field_code     VARCHAR(30)  NOT NULL               COMMENT '欄位代碼，對應 d_setting_gear 欄位名',
        is_visible     TINYINT      NOT NULL DEFAULT 1     COMMENT '是否顯示 1=顯示 0=隱藏',
        is_required    TINYINT      NOT NULL DEFAULT 0     COMMENT '是否必填',
        sort_order     INT          NOT NULL DEFAULT 0,
        UNIQUE KEY uk_type_field (gear_type_id, field_code),
        INDEX idx_gear_type(gear_type_id)
    ) COMMENT='齒輪類型欄位設定：控制各齒輪類型需顯示哪些規格欄位'");

    // ── 齒輪等級對照表 dict_gear_quality_ref ──────────────────────────────
    $pdo->exec("CREATE TABLE IF NOT EXISTS dict_gear_quality_ref (
        quality_ref_id  INT AUTO_INCREMENT PRIMARY KEY,
        iso_grade       TINYINT NULL  COMMENT 'ISO 1328-1 等級 (1-12)',
        din_grade       TINYINT NULL  COMMENT 'DIN 3961 等級 (1-12)',
        jis_grade       TINYINT NULL  COMMENT 'JIS B 1702 等級 (0-12)',
        agma_grade      TINYINT NULL  COMMENT 'AGMA 2000 精度等級 (3-15)',
        sort_order      INT NOT NULL DEFAULT 0
    ) COMMENT='齒輪等級對照表：JIS/ISO/DIN/AGMA 四種標準等級對照'");
    $cnt_ref = $pdo->query("SELECT COUNT(*) FROM dict_gear_quality_ref")->fetchColumn();
    if ((int)$cnt_ref === 0) {
        $ins_ref = $pdo->prepare("INSERT INTO dict_gear_quality_ref (iso_grade,din_grade,jis_grade,agma_grade,sort_order) VALUES (?,?,?,?,?)");
        foreach ([[3,3,3,12,1],[4,4,4,11,2],[5,5,5,10,3],[6,6,6,9,4],[7,7,7,8,5],[8,8,8,7,6],[9,9,9,6,7],[10,10,10,5,8],[11,11,11,4,9],[12,12,12,3,10]] as $r) {
            $ins_ref->execute($r);
        }
    }
    // 齒輪等級欄位加到 d_setting_gear
    try { $pdo->exec("ALTER TABLE d_setting_gear ADD COLUMN gear_quality_std VARCHAR(10) NULL COMMENT '齒輪等級標準 JIS/ISO/DIN/AGMA'"); } catch(Exception $e){}
    try { $pdo->exec("ALTER TABLE d_setting_gear ADD COLUMN gear_quality_grade TINYINT NULL COMMENT '齒輪等級值'"); } catch(Exception $e){}
    // 排除QC檢驗
    try { $pdo->exec("ALTER TABLE process_no ADD COLUMN is_exclude_qc TINYINT(1) NOT NULL DEFAULT 0 COMMENT '排除QC檢驗 1=是 0=否'"); } catch(Exception $e){}
} catch (Exception $e) {}

