// ── 操作紀錄輔助函數 ──
function _get_setting($pdo, $key, $default='') {
    try { $s=$pdo->prepare("SELECT setting_value FROM system_settings WHERE setting_key=?"); $s->execute([$key]); $v=$s->fetchColumn(); return ($v!==false&&$v!==null&&$v!=='') ? $v : $default; } catch(Exception $e){ return $default; }
}
function _save_setting($pdo, $key, $value, $uid, $op) {
    try { $pdo->prepare("INSERT INTO system_settings (setting_key,setting_value,updated_by_id,updated_by,updated_at) VALUES (?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by_id=VALUES(updated_by_id),updated_by=VALUES(updated_by),updated_at=NOW()")->execute([$key,$value,$uid,$op]); } catch(Exception $e){}
}
function _get_operator($pdo, $uid) {
    try { $s=$pdo->prepare("SELECT user_cname FROM user WHERE id=?"); $s->execute([$uid]); $n=$s->fetchColumn(); return $n?:('uid:'.$uid); } catch(Exception $e){ return 'uid:'.$uid; }
}
function _log_audit($pdo, $action, $ttype, $tid, $tname, $changes, $uid, $op) {
    try { $pdo->prepare("INSERT INTO audit_log (action_type,target_type,target_id,target_name,changes,user_id,operator) VALUES (?,?,?,?,?,?,?)")->execute([$action,$ttype,(string)$tid,$tname,is_array($changes)?json_encode($changes,JSON_UNESCAPED_UNICODE):null,$uid,$op]); } catch(Throwable $e){}
}
// 取得顯示用目標名稱（用於 audit_log.target_name）
// ttype='part'   → D_Setting_Id 本身即料號
// ttype='customer' → 客戶簡稱(id)
// ttype='process'  → ProcessName（製程ProcessNo）
function _target_display_name($pdo, $ttype, $tid) {
    try {
        if ($ttype === 'part') return (string)$tid;
        if ($ttype === 'customer') {
            $q = $pdo->prepare("SELECT customer FROM customer_list WHERE customer_id=? LIMIT 1");
            $q->execute([(string)$tid]); $n = $q->fetchColumn();
            return $n ? $n.'('.$tid.')' : (string)$tid;
        }
        if ($ttype === 'process') {
            // $tid 可能是整數 ProcessNo，也可能是 'process:X' 或 'note:pno:X'
            $pno = intval(preg_replace('/\D+/','',$tid));
            if ($pno) {
                $q = $pdo->prepare("SELECT ProcessName FROM process_no WHERE ProcessNo=? LIMIT 1");
                $q->execute([$pno]); $n = $q->fetchColumn();
                return ($n ? $n : '製程'.$pno).'（'.$pno.'）';
            }
        }
    } catch(Throwable $e){}
    return (string)$tid;
}
// 設計備註通知：通知原建立者（若操作者不是建立者）
function _notify_design_note($pdo, $creator_id, $note_id, $ttype, $tid, $type, $operator_id, $operator, $old_text, $new_text=null) {
    if (!$creator_id || $creator_id === intval($operator_id)) return;
    try {
        $target_pk = null;
        if ($ttype === 'part') {
            $pkq = $pdo->prepare("SELECT d_id FROM d_setting WHERE D_Setting_Id=? LIMIT 1");
            $pkq->execute([$tid]);
            $pk = $pkq->fetchColumn();
            $target_pk = ($pk !== false) ? intval($pk) : null;
        }
        $tname = $tid;
        if ($ttype === 'customer') {
            $cnq = $pdo->prepare("SELECT customer FROM customer_list WHERE customer_id=? LIMIT 1");
            $cnq->execute([$tid]);
            $cn = $cnq->fetchColumn();
            if ($cn !== false) $tname = $cn . '(' . $tid . ')';
        }
        $pdo->prepare("INSERT INTO design_note_notifications (user_id,note_id,target_type,target_id,target_name,target_pk,type,operator_id,operator,old_text,new_text) VALUES (?,?,?,?,?,?,?,?,?,?,?)")
            ->execute([$creator_id, intval($note_id), $ttype, $tid, $tname, $target_pk, $type, $operator_id, $operator, $old_text, $new_text]);
    } catch(Throwable $e){}
}
function _zh_field($f) {
    static $m = [
        'D_Setting_Id'=>'料號','Spec_No'=>'規格','Revision'=>'版次','Issue_Date'=>'發行日',
        'Type'=>'種類','Is_Assembly'=>'組合件','Customer_Id'=>'客戶','Remark'=>'備註',
