        'has_tolerance'=>'公差','is_calc_diff'=>'計算差異',
        'calc_base_label_id'=>'計算基準標籤','calc_sub_label_id'=>'計算減項標籤',
        'tolerance_std_upper'=>'上公差標準值',
    ];
    return $m[$f] ?? $f;
}
function _diff_rows($old, $new, $fields) {
    $ch=[]; foreach($fields as $f){ $ov=isset($old[$f])&&$old[$f]!==null?(string)$old[$f]:''; $nv=isset($new[$f])&&$new[$f]!==null?(string)$new[$f]:''; if($ov!==$nv) $ch[]=['field'=>_zh_field($f),'old'=>$ov,'new'=>$nv]; } return $ch;
}
function _recalc_diff_labels($pdo, $d_id) {
    try {
        // 取此料號所有 calc_diff 標籤實例
        $cq = $pdo->prepare("SELECT m.map_id, l.calc_base_label_id, l.calc_sub_label_id, l.tolerance_std_upper FROM item_label_map m JOIN dict_label l ON l.label_id=m.label_id WHERE m.d_id=? AND l.is_calc_diff=1 AND l.is_active=1 AND l.calc_base_label_id IS NOT NULL");
        $cq->execute([$d_id]);
        $calcs = $cq->fetchAll(PDO::FETCH_ASSOC);
        if (empty($calcs)) return;
        // 取此料號所有非 calc_diff 標籤實例（供查 base/sub）
        $aq = $pdo->prepare("SELECT m.label_id, m.input_value, m.value_min, m.value_max, m.tol_upper, l.is_range, l.has_tolerance FROM item_label_map m JOIN dict_label l ON l.label_id=m.label_id WHERE m.d_id=? AND l.is_active=1");
        $aq->execute([$d_id]);
        $allMap = [];
        foreach ($aq->fetchAll(PDO::FETCH_ASSOC) as $r) $allMap[intval($r['label_id'])] = $r;
        $upd = $pdo->prepare("UPDATE item_label_map SET calc_value=?, calc_value_min=?, calc_value_max=? WHERE map_id=?");
        foreach ($calcs as $c) {
            $base = $allMap[intval($c['calc_base_label_id'])] ?? null;
            $sub  = $allMap[intval($c['calc_sub_label_id'])] ?? null;
            if (!$base || !$sub) { $upd->execute([null,null,null,$c['map_id']]); continue; }
            $std_upper  = ($c['tolerance_std_upper'] !== null) ? floatval($c['tolerance_std_upper']) : null;
            $base_range = intval($base['is_range']);
            $sub_range  = intval($sub['is_range']);
            $sub_tol    = intval($sub['has_tolerance']);
            if ($base_range && $sub_range) {
                // 兩者都是範圍：result = (base_min - sub_max) ~ (base_max - sub_min)
                $bmin = ($base['value_min'] !== null) ? floatval($base['value_min']) : null;
                $bmax = ($base['value_max'] !== null) ? floatval($base['value_max']) : null;
                $smin = ($sub['value_min']  !== null) ? floatval($sub['value_min'])  : null;
                $smax = ($sub['value_max']  !== null) ? floatval($sub['value_max'])  : null;
                if ($bmin===null||$bmax===null||$smin===null||$smax===null) { $upd->execute([null,null,null,$c['map_id']]); continue; }
                $rmin = round($bmin - $smax, 4);
                $rmax = round($bmax - $smin, 4);
                $upd->execute([null, $rmin, $rmax, $c['map_id']]);
            } else {
                // 單值計算（含減項公差修正：以減項實際上公差與標準值的差修正減項值）
                $base_val = ($base['value_min']!==null&&$base_range) ? floatval($base['value_min']) : (($base['input_value']!==null&&$base['input_value']!=='') ? floatval($base['input_value']) : null);
                $sub_val  = ($sub['value_min']!==null&&$sub_range)   ? floatval($sub['value_min'])  : (($sub['input_value']!==null&&$sub['input_value']!=='')   ? floatval($sub['input_value'])  : null);
                if ($base_val===null||$sub_val===null) { $upd->execute([null,null,null,$c['map_id']]); continue; }
                if ($sub_tol && $std_upper!==null && $sub['tol_upper']!==null) {
                    $sub_val = round($sub_val + (floatval($sub['tol_upper']) - $std_upper), 4);
                }
                $result = round($base_val - $sub_val, 4);
                $upd->execute([$result, null, null, $c['map_id']]);
            }
        }
    } catch(Exception $e){}
}

