$user_id = $_SESSION['id'] ?? $_SESSION['user_id'] ?? 0;
$permission_code = null;
$current_script  = $_SERVER['PHP_SELF'];
try {
    $sp = $pdo->prepare("
        SELECT smp.page_id, smp.group_id
        FROM system_module_pages smp
        WHERE :script LIKE CONCAT('%', smp.page_url) AND smp.page_url IS NOT NULL AND smp.page_url != ''
        LIMIT 1");
    $sp->execute([':script' => $current_script]);
    $page_info = $sp->fetch(PDO::FETCH_ASSOC);
    if ($page_info) {
        $page_id  = $page_info['page_id'];
        $group_id = $page_info['group_id'];
        $group_code = null;
        if (!empty($group_id)) {
            $sg = $pdo->prepare("SELECT module_code FROM system_modules WHERE group_id=:gid LIMIT 1");
            $sg->execute([':gid' => $group_id]);
            $group_code = $sg->fetchColumn();
        }
        $user_perms = [];
        $spp = $pdo->prepare("SELECT permission FROM user_module_permissions WHERE user_id=:uid AND scope='page' AND module_code=:pid");
        $spp->execute([':uid' => $user_id, ':pid' => $page_id]);
        $page_perms = $spp->fetchAll(PDO::FETCH_COLUMN);
        if (!empty($page_perms)) { $user_perms = $page_perms; }
        elseif (!empty($group_code)) {
            $sgp = $pdo->prepare("SELECT permission FROM user_module_permissions WHERE user_id=:uid AND scope='group' AND module_code=:mc");
            $sgp->execute([':uid' => $user_id, ':mc' => $group_code]);
            $user_perms = $sgp->fetchAll(PDO::FETCH_COLUMN);
        }
        $all_chars = [];
        foreach ($user_perms as $p) $all_chars = array_merge($all_chars, str_split($p));
        $unique = array_unique($all_chars);
        if (in_array('A', $unique)) $permission_code = 'A';
        elseif (!empty($unique)) { sort($unique); $permission_code = implode('', $unique); }
    }
} catch (Exception $e) { /* ignore */ }

