if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action'])) {
    header('Content-Type: application/json; charset=utf-8');

    // ── 帳號/權限再驗一次 ──
    $uid     = $_SESSION['id'] ?? $_SESSION['user_id'] ?? 0;
    $_nas_dir = _get_setting($pdo, 'notes_nas_dir', 'Z:/BOM/ERP/技術/');

    // ─── 料號 ─────────────────────────────────────────────────────────────
    if ($_POST['action'] === 'list_parts') {
        try {
            $lmt_req     = intval($_POST['lmt'] ?? 0);
            $ftype_raw   = trim($_POST['filter_type'] ?? '');
            $fgear       = intval($_POST['filter_gear'] ?? 0);
            $fsub        = intval($_POST['filter_sub'] ?? 0);
            $flabels_raw = trim($_POST['filter_labels'] ?? '');
            $pg  = max(1, intval($_POST['page'] ?? 1));
            $lmt = ($lmt_req > 0 && $lmt_req <= 9999) ? $lmt_req : 10;
            $off = ($pg - 1) * 10;
            $where = '1=1';
            $params = [];
            $kws_p = trim($_POST['keywords_p'] ?? '');
            $kw_fb = trim($_POST['keyword'] ?? '');
            $kws = $kws_p !== '' ? array_values(array_filter(array_map('trim', explode('||', $kws_p)))) : ($kw_fb !== '' ? [$kw_fb] : []);
            // 僅主查詢 SELECT 使用的參數（count 查詢不可帶入，否則參數數量不符）
            $params_sel = [];
            $kw_direct_sql     = '1';    // 是否直接命中關鍵字（無關鍵字搜尋時恆為 1）
            $kw_parent_src_sql = 'NULL'; // 命中關鍵字的所屬組合件料號清單（供前端標示「由組合件帶出」）
            if (!empty($kws)) {
                $kw_ors = []; $kw_direct_ors = []; $kw_parent_ors = [];
                foreach ($kws as $ki => $kw_i) {
                    $kk = ":kw$ki";
                    // 直接欄位命中，或身為「命中關鍵字之組合件」的子件（d_setting_bom 反查）亦納入
                    $kw_ors[] = "((d.D_Setting_Id LIKE $kk OR d.Drawing_No LIKE $kk OR d.Spec_No LIKE $kk OR d.Remark LIKE $kk OR d.Customer_Id LIKE $kk OR c.customer LIKE $kk)"
                              . " OR EXISTS (SELECT 1 FROM d_setting_bom bkw$ki JOIN d_setting pkw$ki ON pkw$ki.d_id=bkw$ki.parent_d_id"
                              . "   WHERE bkw$ki.child_d_id=d.d_id AND pkw$ki.Is_Assembly=1"
                              . "   AND (pkw$ki.D_Setting_Id LIKE :kwp$ki OR pkw$ki.Drawing_No LIKE :kwp$ki OR pkw$ki.Spec_No LIKE :kwp$ki OR pkw$ki.Remark LIKE :kwp$ki)))";
                    $params[$kk] = "%$kw_i%";
                    $params[":kwp$ki"] = "%$kw_i%";
                    $kw_direct_ors[] = "(d.D_Setting_Id LIKE :kws$ki OR d.Drawing_No LIKE :kws$ki OR d.Spec_No LIKE :kws$ki OR d.Remark LIKE :kws$ki OR d.Customer_Id LIKE :kws$ki OR c.customer LIKE :kws$ki)";
                    $params_sel[":kws$ki"] = "%$kw_i%";
                    $kw_parent_ors[] = "(pks.D_Setting_Id LIKE :kwm$ki OR pks.Drawing_No LIKE :kwm$ki OR pks.Spec_No LIKE :kwm$ki OR pks.Remark LIKE :kwm$ki)";
                    $params_sel[":kwm$ki"] = "%$kw_i%";
                }
                $where .= " AND (" . implode(" OR ", $kw_ors) . ")";
                $kw_direct_sql     = "IF(" . implode(" OR ", $kw_direct_ors) . ", 1, 0)";
                $kw_parent_src_sql = "(SELECT GROUP_CONCAT(DISTINCT pks.D_Setting_Id ORDER BY pks.D_Setting_Id SEPARATOR ',')"
                                   . " FROM d_setting_bom bks JOIN d_setting pks ON pks.d_id=bks.parent_d_id"
                                   . " WHERE bks.child_d_id=d.d_id AND pks.Is_Assembly=1 AND (" . implode(" OR ", $kw_parent_ors) . "))";
            }
            $ftypes = array_filter(array_map('trim', explode(',', $ftype_raw)));
            if (!empty($ftypes)) {
                $phs = implode(',', array_map(function($i){ return ":ft$i"; }, array_keys($ftypes)));
                $where .= " AND d.Type IN ($phs)";
                foreach (array_values($ftypes) as $i => $tv) { $params[":ft$i"] = $tv; }
            }
            if ($fgear > 0) {
                $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear g WHERE g.d_setting_id=d.d_id AND g.Gear_Type=:fgear)";
                $params[':fgear'] = $fgear;
            }
            if ($fsub > 0) {
                $where .= " AND d.workpiece_sub_type_id = :fsub";
                $params[':fsub'] = $fsub;
            }
            // 齒部外徑篩選：依 da = m*z/cos(β) + 2m(1+x) 計算後範圍過濾
            $fda_min = trim($_POST['filter_gear_da_min'] ?? '');
            $fda_max = trim($_POST['filter_gear_da_max'] ?? '');
            if (is_numeric($fda_min) || is_numeric($fda_max)) {
                $da_mn  = "CAST(REPLACE(gda.Module,'M','') AS DECIMAL(20,8))";
                $da_expr = "$da_mn * gda.Teeth / COS(RADIANS(COALESCE(gda.Helix_Angle,0))) + 2 * $da_mn * (1 + COALESCE(gda.Profile_Shift_X,0))";
                $da_cond = '';
                if (is_numeric($fda_min) && is_numeric($fda_max)) {
                    $da_cond = "AND ($da_expr) >= :fda_min AND ($da_expr) <= :fda_max";
                    $params[':fda_min'] = $fda_min; $params[':fda_max'] = $fda_max;
                } elseif (is_numeric($fda_min)) {
                    $da_cond = "AND ($da_expr) >= :fda_min";
                    $params[':fda_min'] = $fda_min;
                } else {
                    $da_cond = "AND ($da_expr) <= :fda_max";
                    $params[':fda_max'] = $fda_max;
                }
                $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear gda WHERE gda.d_setting_id=d.d_id AND $da_mn>0 AND gda.Teeth>0 $da_cond)";
            }
            // 齒輪規格篩選
            $fgear_modules_raw = trim($_POST['filter_gear_modules'] ?? '');
            $fgear_helix_dir   = trim($_POST['filter_gear_helix_dir'] ?? '');
            $fgear_pres_raw    = trim($_POST['filter_gear_pressures'] ?? '');
            $fgear_teeth_min   = trim($_POST['filter_gear_teeth_min'] ?? '');
            $fgear_teeth_max   = trim($_POST['filter_gear_teeth_max'] ?? '');
            $fgear_fw_min      = trim($_POST['filter_gear_fw_min'] ?? '');
            $fgear_fw_max      = trim($_POST['filter_gear_fw_max'] ?? '');
            if ($fgear_modules_raw !== '' && $fgear_modules_raw !== '[]') {
                $fgear_modules = json_decode($fgear_modules_raw, true) ?: [];
                if (!empty($fgear_modules)) {
                    $mphs = implode(',', array_map(fn($i) => ":fgm$i", array_keys($fgear_modules)));
                    $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear gm2 WHERE gm2.d_setting_id=d.d_id AND gm2.module_display IN ($mphs))";
                    foreach (array_values($fgear_modules) as $i => $m) { $params[":fgm$i"] = $m; }
                }
            }
            if ($fgear_helix_dir !== '') {
                $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear ghd2 WHERE ghd2.d_setting_id=d.d_id AND ghd2.Helix_Direction=:fghd)";
                $params[':fghd'] = $fgear_helix_dir;
            }
            if ($fgear_pres_raw !== '' && $fgear_pres_raw !== '[]') {
                $fgear_pressures = json_decode($fgear_pres_raw, true) ?: [];
                if (!empty($fgear_pressures)) {
                    $pphs = implode(',', array_map(fn($i) => ":fgp$i", array_keys($fgear_pressures)));
                    $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear gp2 WHERE gp2.d_setting_id=d.d_id AND gp2.Pressure_Angle IN ($pphs))";
                    foreach (array_values($fgear_pressures) as $i => $p) { $params[":fgp$i"] = $p; }
                }
            }
            if (is_numeric($fgear_teeth_min) || is_numeric($fgear_teeth_max)) {
                if (is_numeric($fgear_teeth_min) && is_numeric($fgear_teeth_max)) {
                    $teeth_cond = "AND gtr.Teeth BETWEEN :fgtn AND :fgtx";
                    $params[':fgtn'] = (int)$fgear_teeth_min; $params[':fgtx'] = (int)$fgear_teeth_max;
                } elseif (is_numeric($fgear_teeth_min)) {
                    $teeth_cond = "AND gtr.Teeth >= :fgtn";
                    $params[':fgtn'] = (int)$fgear_teeth_min;
                } else {
                    $teeth_cond = "AND gtr.Teeth <= :fgtx";
                    $params[':fgtx'] = (int)$fgear_teeth_max;
                }
                $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear gtr WHERE gtr.d_setting_id=d.d_id $teeth_cond)";
            }
            if (is_numeric($fgear_fw_min) || is_numeric($fgear_fw_max)) {
                if (is_numeric($fgear_fw_min) && is_numeric($fgear_fw_max)) {
                    $fw_cond = "AND gfw2.Face_Width BETWEEN :fgfwn AND :fgfwx";
                    $params[':fgfwn'] = $fgear_fw_min; $params[':fgfwx'] = $fgear_fw_max;
                } elseif (is_numeric($fgear_fw_min)) {
                    $fw_cond = "AND gfw2.Face_Width >= :fgfwn";
                    $params[':fgfwn'] = $fgear_fw_min;
                } else {
                    $fw_cond = "AND gfw2.Face_Width <= :fgfwx";
                    $params[':fgfwx'] = $fgear_fw_max;
                }
                $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear gfw2 WHERE gfw2.d_setting_id=d.d_id $fw_cond)";
            }
            $fgear_ha_min = trim($_POST['filter_gear_ha_min'] ?? '');
            $fgear_ha_max = trim($_POST['filter_gear_ha_max'] ?? '');
            if (is_numeric($fgear_ha_min) || is_numeric($fgear_ha_max)) {
                if (is_numeric($fgear_ha_min) && is_numeric($fgear_ha_max)) {
                    $ha_cond = "AND gha.Helix_Angle BETWEEN :fghan AND :fghax";
                    $params[':fghan'] = $fgear_ha_min; $params[':fghax'] = $fgear_ha_max;
                } elseif (is_numeric($fgear_ha_min)) {
                    $ha_cond = "AND gha.Helix_Angle >= :fghan";
                    $params[':fghan'] = $fgear_ha_min;
                } else {
                    $ha_cond = "AND gha.Helix_Angle <= :fghax";
                    $params[':fghax'] = $fgear_ha_max;
                }
                $where .= " AND EXISTS (SELECT 1 FROM d_setting_gear gha WHERE gha.d_setting_id=d.d_id $ha_cond)";
            }
            // 標籤篩選：每個選中標籤都必須存在（AND 邏輯）
            if ($flabels_raw !== '' && $flabels_raw !== '[]') {
                $flabels = json_decode($flabels_raw, true) ?: [];
                foreach ($flabels as $fi => $fl) {
                    $flid    = intval($fl['label_id'] ?? 0);
                    if (!$flid) continue;
                    $fsid    = intval($fl['sub_id'] ?? 0);   // 0 = main label, >0 = sub-label
                    $op_key  = "flid{$fi}";
                    $val_op  = $fl['value_op'] ?? 'any';
                    $is_rng  = intval($fl['is_range'] ?? 0); // stored as min/max pair
                    $vmin    = isset($fl['vmin']) && is_numeric($fl['vmin']) ? $fl['vmin'] : null;
                    $vmax    = isset($fl['vmax']) && is_numeric($fl['vmax']) ? $fl['vmax'] : null;
                    $fval    = trim($fl['value'] ?? '');
                    $has_dl  = intval($fl['has_draw_lathe'] ?? 0);
                    // has_draw_lathe_depth（圖面+車床×深度）的數值主值同樣存在 draw_dim 欄位，
                    // 篩選時需與 has_draw_lathe 一樣改用 draw_dim 比對，否則會誤比對空的 input_value。
                    $has_dl_depth = intval($fl['has_draw_lathe_depth'] ?? 0);
                    $use_draw_col = ($has_dl || $has_dl_depth);

                    if ($fsid > 0) {
                        // ── sub-label filter: join item_sub_label_map via item_label_map ──
                        $params[":{$op_key}lid"] = $flid;
                        $params[":{$op_key}sid"] = $fsid;
                        if ($val_op === 'any' || ($vmin === null && $vmax === null && $fval === '')) {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                    . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                    . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid)";
                        } elseif ($val_op === 'range') {
                            if ($is_rng) {
                                // overlap: filter [vmin,vmax] overlaps stored [value_min,value_max]
                                if ($vmin !== null && $vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                            . "  AND islm{$fi}.value_min <= :{$op_key}max AND islm{$fi}.value_max >= :{$op_key}min)";
                                    $params[":{$op_key}min"] = $vmin; $params[":{$op_key}max"] = $vmax;
                                } elseif ($vmin !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                            . "  AND islm{$fi}.value_max >= :{$op_key}min)";
                                    $params[":{$op_key}min"] = $vmin;
                                } elseif ($vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                            . "  AND islm{$fi}.value_min <= :{$op_key}max)";
                                    $params[":{$op_key}max"] = $vmax;
                                } else {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid)";
                                }
                            } else {
                                // numeric BETWEEN on input_value（若為圖面/圖面深度類，改比對 draw_dim）
                                $cast_s = $use_draw_col ? "islm{$fi}.draw_dim" : "CAST(islm{$fi}.input_value AS DECIMAL(20,6))";
                                if ($vmin !== null && $vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                            . "  AND {$cast_s} BETWEEN :{$op_key}min AND :{$op_key}max)";
                                    $params[":{$op_key}min"] = $vmin; $params[":{$op_key}max"] = $vmax;
                                } elseif ($vmin !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                            . "  AND {$cast_s} >= :{$op_key}min)";
                                    $params[":{$op_key}min"] = $vmin;
                                } elseif ($vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                            . "  AND {$cast_s} <= :{$op_key}max)";
                                    $params[":{$op_key}max"] = $vmax;
                                } else {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                            . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                            . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid)";
                                }
                            }
                        } elseif ($val_op === 'eq' && $fval !== '') {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                    . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                    . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                    . "  AND islm{$fi}.input_value=:{$op_key}val)";
                            $params[":{$op_key}val"] = $fval;
                        } elseif ($val_op === 'like' && $fval !== '') {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                    . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                    . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid"
                                    . "  AND islm{$fi}.input_value LIKE :{$op_key}val)";
                            $params[":{$op_key}val"] = "%{$fval}%";
                        } else {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi}"
                                    . "  JOIN item_sub_label_map islm{$fi} ON islm{$fi}.parent_map_id=ilm{$fi}.map_id"
                                    . "  WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}lid AND islm{$fi}.sub_id=:{$op_key}sid)";
                        }
                    } else {
                        // ── main label filter ──
                        $params[":{$op_key}"] = $flid;
                        if ($val_op === 'any' || ($vmin === null && $vmax === null && $fval === '')) {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key})";
                        } elseif ($val_op === 'range') {
                            if ($is_rng) {
                                // overlap: filter [vmin,vmax] overlaps stored [value_min,value_max]
                                if ($vmin !== null && $vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                            . "  AND ilm{$fi}.value_min <= :{$op_key}max AND ilm{$fi}.value_max >= :{$op_key}min)";
                                    $params[":{$op_key}min"] = $vmin; $params[":{$op_key}max"] = $vmax;
                                } elseif ($vmin !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                            . "  AND ilm{$fi}.value_max >= :{$op_key}min)";
                                    $params[":{$op_key}min"] = $vmin;
                                } elseif ($vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                            . "  AND ilm{$fi}.value_min <= :{$op_key}max)";
                                    $params[":{$op_key}max"] = $vmax;
                                } else {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key})";
                                }
                            } else {
                                // numeric BETWEEN/comparison on input_value (圖面/圖面深度類改用 draw_dim)
                                $cast_expr = $use_draw_col ? "ilm{$fi}.draw_dim" : "CAST(ilm{$fi}.input_value AS DECIMAL(20,6))";
                                if ($vmin !== null && $vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                            . "  AND {$cast_expr} BETWEEN :{$op_key}min AND :{$op_key}max)";
                                    $params[":{$op_key}min"] = $vmin; $params[":{$op_key}max"] = $vmax;
                                } elseif ($vmin !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                            . "  AND {$cast_expr} >= :{$op_key}min)";
                                    $params[":{$op_key}min"] = $vmin;
                                } elseif ($vmax !== null) {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                            . "  AND {$cast_expr} <= :{$op_key}max)";
                                    $params[":{$op_key}max"] = $vmax;
                                } else {
                                    $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key})";
                                }
                            }
                        } elseif ($val_op === 'like' && $fval !== '') {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key} AND ilm{$fi}.input_value LIKE :{$op_key}val)";
                            $params[":{$op_key}val"] = "%{$fval}%";
                        } elseif ($val_op === 'dim_eq' && $fval !== '') {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key}"
                                    . "  AND CAST(ilm{$fi}.value_min AS DECIMAL(20,6)) = :{$op_key}val)";
                            $params[":{$op_key}val"] = floatval($fval);
                        } else {
                            $where .= " AND EXISTS (SELECT 1 FROM item_label_map ilm{$fi} WHERE ilm{$fi}.d_id=d.d_id AND ilm{$fi}.label_id=:{$op_key})";
                        }
                    }
                }
            }
            // ── 附件標籤篩選 ──────────────────────────────────────────────────
            $fatags_raw = trim($_POST['filter_attach_tags'] ?? '');
            if ($fatags_raw && $fatags_raw !== '[]') {
                $fatags = json_decode($fatags_raw, true) ?: [];
                foreach ($fatags as $fati => $fat) {
                    $fcat_id  = intval($fat['cat_id'] ?? 0);
                    $fvar_key = trim($fat['var_key'] ?? '');
                    $fvar_val = trim($fat['var_val'] ?? '');
                    if (!$fcat_id) continue;
                    $fat_key = "fat{$fati}";
                    if ($fvar_key !== '' && $fvar_val !== '') {
                        // 有變數值：JSON 模糊比對 tag_var_values
                        $where .= " AND EXISTS (SELECT 1 FROM part_attachments pa{$fati} WHERE pa{$fati}.d_id=d.d_id"
                                . "  AND FIND_IN_SET(:${fat_key}catid, pa{$fati}.category_ids)"
                                . "  AND pa{$fati}.tag_var_values LIKE :{$fat_key}varval)";
                        $params[":{$fat_key}catid"] = $fcat_id;
                        $params[":{$fat_key}varval"] = '%'.str_replace(['%','_'], ['\\%','\\_'], $fvar_val).'%';
                    } else {
                        // 只要有這個類別的附件
                        $where .= " AND EXISTS (SELECT 1 FROM part_attachments pa{$fati} WHERE pa{$fati}.d_id=d.d_id"
                                . "  AND FIND_IN_SET(:${fat_key}catid, pa{$fati}.category_ids))";
                        $params[":{$fat_key}catid"] = $fcat_id;
                    }
                }
            }
            // ── 客戶 / 等級 / 產業別篩選（均支援多選） ──────────────────────
            // 指定料號篩選（pinned part IDs）
            $fpinned_p_raw = trim($_POST['filter_pinned_part_ids'] ?? '');
            $fpinned_p = $fpinned_p_raw !== '' ? array_values(array_filter(array_map('trim', explode(',', $fpinned_p_raw)))) : [];
            if (!empty($fpinned_p)) {
                $phs_pp = implode(',', array_map(function($i){ return ":fpp$i"; }, range(0, count($fpinned_p)-1)));
                $where .= " AND d.D_Setting_Id IN ($phs_pp)";
                foreach ($fpinned_p as $i => $pid) { $params[":fpp$i"] = $pid; }
            }
            $fcust_ids_raw = trim($_POST['filter_customer_ids'] ?? '');
            $fgrades_raw   = trim($_POST['filter_grades_p']     ?? '');
            $finds_raw     = trim($_POST['filter_industries_p'] ?? '');
            $findsubs_raw  = trim($_POST['filter_industry_subs_p'] ?? trim($_POST['filter_industry_sub_p'] ?? ''));
            $findsubs_p    = array_values(array_filter(array_map('intval', explode(',', $findsubs_raw)), function($v){ return $v > 0; }));
            $fcust_ids = $fcust_ids_raw !== '' ? array_values(array_filter(array_map('trim', explode(',', $fcust_ids_raw)))) : [];
            if (!empty($fcust_ids)) {
                $phs_c = implode(',', array_map(function($i){ return ":fci$i"; }, range(0, count($fcust_ids)-1)));
                $where .= " AND d.Customer_Id IN ($phs_c)";
                foreach ($fcust_ids as $i => $cid) { $params[":fci$i"] = $cid; }
            }
            $fgrades = array_filter(array_map('trim', explode(',', $fgrades_raw)));
            if (!empty($fgrades)) {
                $phs = implode(',', array_map(function($i){ return ":fg$i"; }, array_keys($fgrades)));
                $where .= " AND c.customer_grade IN ($phs)";
                foreach (array_values($fgrades) as $i => $gv) { $params[":fg$i"] = $gv; }
            }
            $finds = array_filter(array_map('intval', explode(',', $finds_raw)));
            if (!empty($finds)) {
                $phs2 = implode(',', array_map(function($i){ return ":fi$i"; }, array_keys($finds)));
                $where .= " AND EXISTS (SELECT 1 FROM customer_industry_mapping cim_p WHERE cim_p.customer_id=d.Customer_Id AND cim_p.industry_id IN ($phs2))";
                foreach (array_values($finds) as $i => $iv) { $params[":fi$i"] = $iv; }
            }
            if (!empty($findsubs_p)) {
                $phs_s = implode(',', array_map(function($i){ return ":fis$i"; }, range(0, count($findsubs_p)-1)));
                $where .= " AND EXISTS (SELECT 1 FROM customer_industry_sub_mapping csm_p WHERE csm_p.customer_id=d.Customer_Id AND csm_p.sub_id IN ($phs_s))";
                foreach ($findsubs_p as $i => $sv) { $params[":fis$i"] = $sv; }
            }
            $cnt = $pdo->prepare("SELECT COUNT(*) FROM d_setting d LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id WHERE $where");
            $cnt->execute($params);
            $total = (int)$cnt->fetchColumn();
            $pdo->exec("SET SESSION group_concat_max_len = 1048576");

            $sort_by = $_POST['sort_by'] ?? '';
            switch ($sort_by) {
                case 'ship_count_asc':  $order_sql = 'ORDER BY ship_cy_count ASC, d.D_Setting_Id ASC'; break;
                case 'ship_count_desc': $order_sql = 'ORDER BY ship_cy_count DESC, d.D_Setting_Id ASC'; break;
                case 'ship_qty_asc':    $order_sql = 'ORDER BY ship_cy_qty ASC, d.D_Setting_Id ASC'; break;
                case 'ship_qty_desc':   $order_sql = 'ORDER BY ship_cy_qty DESC, d.D_Setting_Id ASC'; break;
                default:                $order_sql = 'ORDER BY d.D_Setting_Id ASC'; break;
            }
            // 關鍵字搜尋＋預設排序時：直接命中的組合件置頂（使用者選了出貨排序則尊重其排序）
            if (!empty($kws) && !in_array($sort_by, ['ship_count_asc','ship_count_desc','ship_qty_asc','ship_qty_desc'], true)) {
                $order_sql = 'ORDER BY (kw_direct=1 AND d.Is_Assembly=1) DESC, d.D_Setting_Id ASC';
            }

            // 建立巢狀 REPLACE 表達式，用於 display_template 套用
            $tmpl_replacements = [
                '{Module}'            => "COALESCE(NULLIF(g.module_display,''), IF(g.Module IS NOT NULL AND g.Module<>'', IF(LEFT(UPPER(g.Module),1)='M', g.Module, CONCAT('M',g.Module)), ''))",
                '{Teeth}'             => "COALESCE(CAST(NULLIF(g.Teeth,0) AS CHAR),'')",
                '{Face_Width}'        => "IF(g.Face_Width IS NOT NULL AND g.Face_Width>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.Face_Width AS CHAR))), '')",
                '{Pressure_Angle}'    => "COALESCE(NULLIF(TRIM(TRAILING '°' FROM TRIM(COALESCE(g.Pressure_Angle,''))),''),'20')",   // 空白＝業界預設20°，樣板的「PA」後才不會空著
                '{Helix_Direction}'   => "COALESCE(NULLIF(g.Helix_Direction,''),'')",
                '{Helix_Angle_Str}'   => "COALESCE(NULLIF(g.Helix_Angle_Str,''), IF(g.Helix_Angle IS NOT NULL AND g.Helix_Angle>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.Helix_Angle AS CHAR))), ''))",
                '{spec_starts}'       => "COALESCE(CAST(NULLIF(g.spec_starts,0) AS CHAR),'')",
                '{X_PART}'            => "IF(g.Profile_Shift_X IS NOT NULL AND g.Profile_Shift_X<>0, CONCAT('X',TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.Profile_Shift_X AS CHAR)))), '')",
                '{GRADE}'             => "IF(g.gear_quality_std IS NOT NULL AND g.gear_quality_std<>'', CONCAT(g.gear_quality_std,COALESCE(CAST(g.gear_quality_grade AS CHAR),'')), '')",
                '{spec_chain_size}'   => "COALESCE(g.spec_chain_size,'')",
                '{spec_pitch}'        => "IF(g.spec_pitch IS NOT NULL AND g.spec_pitch>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.spec_pitch AS CHAR))), '')",
                '{spec_roller_dia}'   => "IF(g.spec_roller_dia IS NOT NULL AND g.spec_roller_dia>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.spec_roller_dia AS CHAR))), '')",
                '{spec_spline_type}'  => "COALESCE(g.spec_spline_type,'')",
                '{spec_spline_major_dia}' => "IF(g.spec_spline_major_dia IS NOT NULL AND g.spec_spline_major_dia>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.spec_spline_major_dia AS CHAR))), '')",
                '{spec_spline_minor_dia}' => "IF(g.spec_spline_minor_dia IS NOT NULL AND g.spec_spline_minor_dia>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.spec_spline_minor_dia AS CHAR))), '')",
                '{spec_spline_width}' => "IF(g.spec_spline_width IS NOT NULL AND g.spec_spline_width>0, TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.spec_spline_width AS CHAR))), '')",
                '{spec_pulley_profile}' => "COALESCE(g.spec_pulley_profile,'')",
                '{Remark_Gear}'       => "COALESCE(NULLIF(g.Remark_Gear,''),'')",
            ];
            $tmpl_expr = 'dt.display_template';
            foreach ($tmpl_replacements as $token => $expr) {
                $tmpl_expr = "REPLACE($tmpl_expr, '$token', $expr)";
            }

            $stmt = $pdo->prepare("
                SELECT d.d_id, d.D_Setting_Id, d.Drawing_No, d.Spec_No, d.Revision, d.Issue_Date, d.Type, d.Remark,
                       d.Customer_Id, c.customer AS client_name, d.Is_Assembly,
                       (SELECT GROUP_CONCAT(DISTINCT pa.D_Setting_Id ORDER BY pa.D_Setting_Id SEPARATOR ',')
                        FROM d_setting_bom ba JOIN d_setting pa ON pa.d_id=ba.parent_d_id
                        WHERE ba.child_d_id=d.d_id AND pa.Is_Assembly=1) AS parent_assemblies,
                       $kw_direct_sql AS kw_direct,
                       $kw_parent_src_sql AS kw_parent_srcs,
                       d.Modified_At, d.Created_At, d.Weight_Kg,
                       (SELECT GROUP_CONCAT(
                            CASE
                              -- 套用 display_template（優先）
                              WHEN dt.display_template IS NOT NULL AND dt.display_template<>'' THEN
                                $tmpl_expr
                              -- 矩形花鍵（無模板時退用 hardcode）
                              WHEN dt.spec_category='spline' AND g.spec_spline_type='矩形' THEN
                                CONCAT(IF(g.Teeth>0, CONCAT(g.Teeth,'鍵 '),''), COALESCE(CAST(g.spec_spline_minor_dia AS CHAR),'?'), ' × ', COALESCE(CAST(g.spec_spline_major_dia AS CHAR),'?'), ' × ', COALESCE(CAST(g.spec_spline_width AS CHAR),'?'))
                              -- 其他無模板類型退用 hardcode
                              ELSE
                                CONCAT(IF(g.Module IS NOT NULL AND g.Module<>'', IF(LEFT(UPPER(g.Module),1)='M', g.Module, CONCAT('M',g.Module)), ''),
                                   IF(dt.spec_category='worm_gear' AND g.spec_starts IS NOT NULL AND g.spec_starts>0,
                                      CONCAT('×',g.spec_starts,'條'), IF(g.Teeth IS NOT NULL AND g.Teeth>0, CONCAT('×',g.Teeth,'T'), '')),
                                   IF(g.Face_Width IS NOT NULL AND g.Face_Width>0, CONCAT(' W',TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.Face_Width AS CHAR)))), ''),
                                   IF(g.Pressure_Angle IS NOT NULL AND g.Pressure_Angle<>'', CONCAT(' PA',g.Pressure_Angle,'°'), ''),
                                   IF(g.Helix_Direction IS NOT NULL AND g.Helix_Direction<>'', CONCAT(' ',g.Helix_Direction), ''),
                                   IF(g.Helix_Angle IS NOT NULL AND g.Helix_Angle>0, CONCAT(' ',COALESCE(NULLIF(g.Helix_Angle_Str,''), TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.Helix_Angle AS CHAR)))),'°'), ''),
                                   IF(g.Profile_Shift_X IS NOT NULL AND g.Profile_Shift_X<>0, CONCAT(' X',TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.Profile_Shift_X AS CHAR)))), ''))
                            END
                            ORDER BY g.gear_id SEPARATOR ' / ')
                        FROM d_setting_gear g LEFT JOIN dict_gear_type dt ON dt.gear_type_id=g.Gear_Type
                        WHERE g.d_setting_id=d.d_id) AS gear_spec_str,
                       (SELECT GROUP_CONCAT(
                            IF(CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8))>0 AND g.Teeth IS NOT NULL AND g.Teeth>0,
                               ROUND(
                                   CASE
                                       -- DIN5480 花鍵（外花鍵/花鍵）：有公稱直徑用 da=D_B-0.2m，否則短齒型 da=mz+2m(0.4+x)
                                       -- 用 spec_category='spline' 避免依賴中文 type_name 比較
                                       WHEN g.spec_spline_std='DIN5480' AND g.spec_spline_nominal_dia>0 AND dt_sp.spec_category='spline' AND dt_sp.type_name NOT LIKE '%內%'
                                           THEN g.spec_spline_nominal_dia - 0.2 * CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8))
                                       WHEN g.spec_spline_std='DIN5480' AND (g.spec_spline_nominal_dia IS NULL OR g.spec_spline_nominal_dia<=0) AND dt_sp.spec_category='spline' AND dt_sp.type_name NOT LIKE '%內%'
                                           THEN CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8)) * g.Teeth + 2 * CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8)) * (0.4 + COALESCE(g.Profile_Shift_X,0))
                                       -- DIN5480 內花鍵：有公稱直徑用 di=D_B-2m，否則一般公式
                                       WHEN g.spec_spline_std='DIN5480' AND g.spec_spline_nominal_dia>0 AND dt_sp.spec_category='spline' AND dt_sp.type_name LIKE '%內%'
                                           THEN g.spec_spline_nominal_dia - 2 * CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8))
                                       WHEN g.spec_spline_std='DIN5480' AND (g.spec_spline_nominal_dia IS NULL OR g.spec_spline_nominal_dia<=0) AND dt_sp.spec_category='spline' AND dt_sp.type_name LIKE '%內%'
                                           THEN CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8)) * g.Teeth - 2 * CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8)) * (1 + COALESCE(g.Profile_Shift_X,0))
                                       ELSE
                                           CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8)) * g.Teeth / COS(RADIANS(COALESCE(g.Helix_Angle,0))) + 2 * CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8)) * (1 + COALESCE(g.Profile_Shift_X,0))
                                   END, 2),
                               NULL)
                            ORDER BY g.gear_id SEPARATOR '/')
                        FROM d_setting_gear g LEFT JOIN dict_gear_type dt_sp ON dt_sp.gear_type_id=g.Gear_Type
                        WHERE g.d_setting_id=d.d_id AND CAST(REPLACE(g.Module,'M','') AS DECIMAL(20,8))>0 AND g.Teeth>0) AS gear_da_str,
                       (SELECT GROUP_CONCAT(
                            CONCAT(l.label_id,'|',l.label_name,'|',l.input_type,'|',COALESCE(m.input_value,''),'|',l.has_draw_lathe,'|',COALESCE(CAST(m.draw_dim AS CHAR),''),'|',COALESCE(CAST(m.lathe_dim AS CHAR),''),'|',COALESCE((SELECT GROUP_CONCAT(CONCAT(ds.sub_name,'§',COALESCE(slm.input_value,''),'§',COALESCE(CAST(slm.value_min AS CHAR),''),'§',COALESCE(CAST(slm.value_max AS CHAR),''),'§',COALESCE(ds.is_range,0),'§',COALESCE(ds.has_tolerance,0),'§',COALESCE(CAST(slm.tol_upper AS CHAR),''),'§',COALESCE(CAST(slm.tol_lower AS CHAR),''),'§',COALESCE(ds.is_dimension,0),'§',COALESCE(ds.is_qty_dim,0),'§',COALESCE(ds.prefix_char,''),'§',COALESCE(ds.suffix_char,''),'§',COALESCE(CAST(slm.qty AS CHAR),''),'§',COALESCE(ds.is_imperial_dim,0),'§',COALESCE(ds.is_enum,0),'§',COALESCE(ds.hide_name_in_display,0),'§',COALESCE(ds.is_countersink,0),'§',COALESCE(ds.has_draw_lathe_depth,0),'§',COALESCE(CAST(slm.draw_dim AS CHAR),''),'§',COALESCE(CAST(slm.lathe_dim AS CHAR),''),'§',COALESCE(ds.is_triple_dim,0),'§',COALESCE(ds.is_qty_triple_dim,0)) ORDER BY ds.sort_order SEPARATOR '~') FROM item_sub_label_map slm JOIN dict_label_sub ds ON ds.sub_id=slm.sub_id WHERE slm.parent_map_id=m.map_id AND ds.is_active=1),''),'|',COALESCE(l.is_range,0),'|',COALESCE(CAST(m.value_min AS CHAR),''),'|',COALESCE(CAST(m.value_max AS CHAR),''),'|',COALESCE(l.has_tolerance,0),'|',COALESCE(CAST(m.tol_upper AS CHAR),''),'|',COALESCE(CAST(m.tol_lower AS CHAR),''),'|',COALESCE(l.is_calc_diff,0),'|',COALESCE(l.calc_base_name,''),'|',COALESCE(l.calc_sub_name,''),'|',COALESCE(CAST(m.calc_value AS CHAR),''),'|',COALESCE(CAST(m.calc_value_min AS CHAR),''),'|',COALESCE(CAST(m.calc_value_max AS CHAR),''),'|',COALESCE(l.is_dimension,0),'|',COALESCE(l.is_qty_dim,0),'|',COALESCE(l.prefix_char,''),'|',COALESCE(l.suffix_char,''),'|',COALESCE(l.is_hidden_frontend,0),'|',COALESCE(CAST(m.qty AS CHAR),''),'|',COALESCE(l.lathe_optional,0),'|',COALESCE(l.has_draw_lathe_depth,0),'|',COALESCE(l.is_triple_dim,0))
                            ORDER BY l.sort_order, m.map_id SEPARATOR '\\n')
                        FROM item_label_map m JOIN dict_label l ON l.label_id=m.label_id
                        WHERE m.d_id=d.d_id AND l.is_active=1) AS labels_str,
                       (SELECT EXISTS(SELECT 1 FROM bom WHERE d_id=d.D_Setting_Id)) AS has_drawing,
                       (SELECT EXISTS(SELECT 1 FROM part_attachments WHERE d_id=d.d_id)) AS has_attach,
                       (SELECT EXISTS(
                           SELECT 1 FROM quotation_attachments qa
                           WHERE qa.status='active' AND (
                                 (qa.linked_parts IS NOT NULL AND JSON_CONTAINS(qa.linked_parts, JSON_QUOTE(d.D_Setting_Id)))
                              OR (qa.linked_parts IS NULL AND qa.quote_no IN (
                                   SELECT ql.quote_no FROM quotation_item qi
                                   JOIN quotation_list ql ON ql.quote_id=qi.quote_id
                                   WHERE qi.d_setting_d_id=d.d_id)))
                       )) AS has_quote,
                       COALESCE(ss.ship_cy_count,0) AS ship_cy_count,
                       COALESCE(ss.ship_cy_qty,0)   AS ship_cy_qty,
                       COALESCE(ss.ship_py_count,0) AS ship_py_count,
                       COALESCE(ss.ship_py_qty,0)   AS ship_py_qty
                FROM d_setting d
                LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id
                LEFT JOIN (
                    /* 出貨統計一律以「料號 id (d_setting.d_id)」歸戶，不可用料號字串 join——
                       同一個料號在 d_setting 可能有多列（不同版次/規格），用字串 join 會讓每一列
                       都顯示同一份統計（實際沒單據的那列也會有數字）。
                       規則：優先取 is_list.d_setting_id（2026 起 ERP 匯入已綁定）；
                             未綁定的舊資料才回退用料號字串比對，且一律歸給該料號最早建立的那一列。
                       先 DISTINCT 去重（相同 IS+料號id+Date+Qty+Price 視為重複行），再聚合 */
                    SELECT sub.eff_d_id,
                           COUNT(DISTINCT CASE WHEN YEAR(sub.Order_date)=YEAR(CURDATE())   THEN sub.IS_number END) AS ship_cy_count,
                           SUM(CASE WHEN YEAR(sub.Order_date)=YEAR(CURDATE())   THEN sub.Qty ELSE 0 END) AS ship_cy_qty,
                           COUNT(DISTINCT CASE WHEN YEAR(sub.Order_date)=YEAR(CURDATE())-1 THEN sub.IS_number END) AS ship_py_count,
                           SUM(CASE WHEN YEAR(sub.Order_date)=YEAR(CURDATE())-1 THEN sub.Qty ELSE 0 END) AS ship_py_qty
                    FROM (
                        SELECT DISTINCT COALESCE(il.d_setting_id, fb.min_d_id) AS eff_d_id,
                               il.IS_number, il.Order_date, il.Qty, il.Unit_price
                        FROM is_list il
                        LEFT JOIN is_sale_type ist ON ist.sale_type_id=il.sale_type
                        LEFT JOIN (SELECT D_Setting_Id, MIN(d_id) AS min_d_id FROM d_setting GROUP BY D_Setting_Id) fb
                               ON fb.D_Setting_Id=il.Product_id
                        WHERE (il.sale_type IS NULL OR ist.is_count=1)
                          AND il.Order_date BETWEEN DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y-01-01') AND CURDATE()
                    ) sub
                    WHERE sub.eff_d_id IS NOT NULL
                    GROUP BY sub.eff_d_id
                ) ss ON ss.eff_d_id=d.d_id
                WHERE $where
                $order_sql
                LIMIT $lmt OFFSET $off");
            $stmt->execute(array_merge($params, $params_sel));
            $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            // 設計備註（有查看權限時補上）
            if ($can_see_design && !empty($rows)) {
                try {
                    $pids = array_column($rows, 'D_Setting_Id');
                    $ph_dn = implode(',', array_fill(0, count($pids), '?'));
                    $dnq = $pdo->prepare("
                        SELECT dn.target_id, dn.note_id, dn.note_text,
                               CASE WHEN EXISTS(SELECT 1 FROM note_images ni WHERE ni.note_id=dn.note_id AND ni.note_type='part_design') THEN 1 ELSE 0 END AS has_img
                        FROM design_notes dn
                        WHERE dn.target_type='part' AND dn.target_id IN ($ph_dn)
                        ORDER BY dn.created_at ASC");
                    $dnq->execute($pids);
                    $dnmap = [];
                    foreach ($dnq->fetchAll(PDO::FETCH_ASSOC) as $dn) {
                        $tid = $dn['target_id'];
                        if (!isset($dnmap[$tid])) { $dnmap[$tid] = ['first_text'=>$dn['note_text'],'count'=>0,'has_images'=>false]; }
                        $dnmap[$tid]['count']++;
                        if ($dn['has_img']) $dnmap[$tid]['has_images'] = true;
                    }
                    foreach ($rows as &$row) { $row['design_note'] = $dnmap[$row['D_Setting_Id']] ?? null; }
                    unset($row);
                } catch(Exception $ex) {}
            }
            echo json_encode(['success'=>true,'data'=>$rows,'total'=>$total,'pages'=>ceil($total/$lmt),'page'=>$pg]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'get_part') {
        try {
            $d_id = intval($_POST['d_id']);
            $stmt = $pdo->prepare("SELECT d.*, c.customer AS client_name FROM d_setting d LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id WHERE d.d_id=?");
            $stmt->execute([$d_id]);
            $row = $stmt->fetch(PDO::FETCH_ASSOC);
            if (!$row) throw new Exception('找不到料號');
            // 齒輪資料
            $gears = [];
            if ($row['Type'] === 'G') {
                $sg = $pdo->prepare("SELECT * FROM d_setting_gear WHERE d_setting_id=? ORDER BY gear_id ASC");
                $sg->execute([$d_id]);
                $gears = $sg->fetchAll(PDO::FETCH_ASSOC);
                foreach ($gears as &$g) {
                    if (isset($g['Helix_Angle'])     && $g['Helix_Angle']     !== null) $g['Helix_Angle']     = (float)$g['Helix_Angle'];
                    if (isset($g['Profile_Shift_X']) && $g['Profile_Shift_X'] !== null) $g['Profile_Shift_X'] = (float)$g['Profile_Shift_X'];
                }
                unset($g);
            }
            $row['gears'] = $gears;
            // BOM 子件資料
            $bom_children = [];
            if ($row['Is_Assembly'] == 1) {
                $sb = $pdo->prepare("SELECT b.bom_id, b.child_d_id, b.standard_qty, b.Remark_Bom, d.D_Setting_Id AS child_part_no FROM d_setting_bom b JOIN d_setting d ON d.d_id=b.child_d_id WHERE b.parent_d_id=? ORDER BY b.bom_id ASC");
                $sb->execute([$d_id]);
                $bom_children = $sb->fetchAll(PDO::FETCH_ASSOC);
            }
            $row['bom_children'] = $bom_children;
            // 標籤資料
            $sl = $pdo->prepare("SELECT m.map_id, m.label_id, m.input_value, m.draw_dim, m.lathe_dim, m.value_min, m.value_max, m.tol_upper, m.tol_lower, m.calc_value, m.calc_value_min, m.calc_value_max, COALESCE(m.qty,NULL) AS qty, l.label_name, l.input_type, l.is_repeatable, l.has_draw_lathe, l.is_range, l.has_tolerance, l.is_calc_diff, l.calc_base_label_id, l.calc_sub_label_id, l.tolerance_std_upper, COALESCE(l.is_dimension,0) AS is_dimension, COALESCE(l.is_qty_dim,0) AS is_qty_dim, COALESCE(l.prefix_char,'') AS prefix_char, COALESCE(l.suffix_char,'') AS suffix_char, COALESCE(l.is_hidden_frontend,0) AS is_hidden_frontend FROM item_label_map m JOIN dict_label l ON l.label_id=m.label_id WHERE m.d_id=? AND l.is_active=1 ORDER BY l.sort_order, m.map_id ASC");
            $sl->execute([$d_id]);
            $labelRows = $sl->fetchAll(PDO::FETCH_ASSOC);
            // Attach sub-labels for each label instance
            $ssub = $pdo->prepare("SELECT s.sub_map_id, s.sub_id, s.input_value, s.draw_dim, s.lathe_dim, s.value_min, s.value_max, s.tol_upper, s.tol_lower, COALESCE(s.qty,NULL) AS qty, d.sub_name, d.input_type, d.is_repeatable, d.has_draw_lathe, d.is_range, d.has_tolerance, COALESCE(d.is_dimension,0) AS is_dimension, COALESCE(d.is_qty_dim,0) AS is_qty_dim, COALESCE(d.prefix_char,'') AS prefix_char, COALESCE(d.suffix_char,'') AS suffix_char FROM item_sub_label_map s JOIN dict_label_sub d ON d.sub_id=s.sub_id WHERE s.parent_map_id=? AND d.is_active=1 ORDER BY d.sort_order, s.sub_map_id ASC");
            foreach ($labelRows as &$lr) {
                $ssub->execute([$lr['map_id']]);
                $lr['sub_labels'] = $ssub->fetchAll(PDO::FETCH_ASSOC);
            }
            unset($lr);
            $row['labels'] = $labelRows;
            // 舊料號
            try {
                $olq = $pdo->prepare("SELECT o.sort_order, o.old_d_id, d.D_Setting_Id AS old_part_no, c.customer AS old_client_name, c.customer_id AS old_customer_id FROM d_setting_old_part_links o JOIN d_setting d ON d.d_id=o.old_d_id LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id WHERE o.d_id=? ORDER BY o.sort_order, o.id LIMIT 3");
                $olq->execute([$d_id]);
                $row['old_part_links'] = $olq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['old_part_links'] = []; }
            // 廠商對應（含每廠商單價）
            try {
                $vq = $pdo->prepare("SELECT vm.maker_id_no, vm.price, COALESCE(ml.maker_id,'') AS maker_short, COALESCE(ml.maker_id_all,'') AS maker_full
                                     FROM d_setting_vendor_map vm LEFT JOIN maker_list ml ON ml.maker_id_no=vm.maker_id_no
                                     WHERE vm.d_id=? ORDER BY vm.sort_order, vm.map_id");
                $vq->execute([$d_id]);
                $row['vendor_map'] = $vq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['vendor_map'] = []; }
            // 專用料號對應（指向其他 d_setting）
            try {
                $pq = $pdo->prepare("SELECT dm.ref_d_id, d.D_Setting_Id AS part_id, COALESCE(d.Spec_No,'') AS spec_no
                                     FROM d_setting_dedicated_part_map dm JOIN d_setting d ON d.d_id=dm.ref_d_id
                                     WHERE dm.d_id=? ORDER BY dm.sort_order, dm.map_id");
                $pq->execute([$d_id]);
                $row['dedicated_part_map'] = $pq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['dedicated_part_map'] = []; }
            // 專用機台對應
            try {
                $mq = $pdo->prepare("SELECT mm.machine_id, COALESCE(ml.machine,'') AS machine_name, COALESCE(mt.machine_type,'') AS machine_type
                                     FROM d_setting_machine_map mm LEFT JOIN machine_list ml ON ml.machine_id=mm.machine_id
                                     LEFT JOIN machine_type mt ON mt.machine_type_id=ml.machine_type_id
                                     WHERE mm.d_id=? ORDER BY mm.sort_order, mm.map_id");
                $mq->execute([$d_id]);
                $row['machine_map'] = $mq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['machine_map'] = []; }
            echo json_encode(['success'=>true,'data'=>$row]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 客戶簡單清單（舊料號篩選用）────────────────────────────────────────────
    if ($_POST['action'] === 'get_customers_simple') {
        try {
            $stmt = $pdo->query("SELECT customer_id, customer FROM customer_list WHERE COALESCE(is_inactive,0)=0 ORDER BY customer LIMIT 200");
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 舊料號搜尋 ────────────────────────────────────────────────────────────
    if ($_POST['action'] === 'search_old_parts') {
        try {
            $kw      = trim($_POST['keyword']    ?? '');
            $cust_id = trim($_POST['customer_id'] ?? '');
            $exclude = intval($_POST['exclude_d_id'] ?? 0);
            if (empty($kw) && empty($cust_id)) { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $where = ['d.d_id != ?']; $params = [$exclude];
            if ($kw)      { $where[] = '(d.D_Setting_Id LIKE ? OR d.Spec_No LIKE ? OR d.Drawing_No LIKE ?)'; $params[] = "%$kw%"; $params[] = "%$kw%"; $params[] = "%$kw%"; }
            if ($cust_id) { $where[] = 'd.Customer_Id = ?'; $params[] = $cust_id; }
            $stmt = $pdo->prepare("SELECT d.d_id, d.D_Setting_Id, d.Spec_No, d.Customer_Id, c.customer AS client_name FROM d_setting d LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id WHERE ".implode(' AND ', $where)." ORDER BY d.D_Setting_Id LIMIT 20");
            $stmt->execute($params);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 搜尋子件（組合件用）
    if ($_POST['action'] === 'search_child_parts') {
        try {
            $kw = trim($_POST['keyword'] ?? '');
            $exclude = intval($_POST['exclude_d_id'] ?? 0);
            if (empty($kw)) { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $stmt = $pdo->prepare("SELECT d.d_id, d.D_Setting_Id, d.Spec_No, c.customer AS client_name FROM d_setting d LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id WHERE (d.D_Setting_Id LIKE ? OR d.Spec_No LIKE ? OR d.Customer_Id LIKE ? OR d.Drawing_No LIKE ?) AND d.d_id <> ? AND d.Is_Assembly=0 LIMIT 15");
            $stmt->execute(["%$kw%", "%$kw%", "%$kw%", "%$kw%", $exclude]);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 複製標籤來源搜尋 ─────────────────────────────────────────────────────
    if ($_POST['action'] === 'search_parts_for_copy') {
        try {
            $kw      = trim($_POST['keyword']   ?? '');
            $cust_kw = trim($_POST['customer']  ?? '');
            $type_f  = trim($_POST['type_code'] ?? '');
            $excl_id = intval($_POST['exclude_d_id'] ?? 0);
            $where   = ['d.d_id != ?'];
            $params  = [$excl_id];
            if ($kw)      { $where[] = '(d.D_Setting_Id LIKE ? OR d.Spec_No LIKE ? OR d.Drawing_No LIKE ?)'; $params[] = "%$kw%"; $params[] = "%$kw%"; $params[] = "%$kw%"; }
            if ($cust_kw) { $where[] = '(c.customer LIKE ? OR d.Customer_Id LIKE ?)'; $params[] = "%$cust_kw%"; $params[] = "%$cust_kw%"; }
            if ($type_f)  { $where[] = 'd.Type = ?'; $params[] = $type_f; }
            $whereSQL = implode(' AND ', $where);
            $sql = "SELECT d.d_id, d.D_Setting_Id, d.Type, c.customer AS client_name, dst.sub_type_name,
                (SELECT COUNT(*) FROM item_label_map WHERE d_id=d.d_id) AS label_count,
                (SELECT GROUP_CONCAT(dl.label_name ORDER BY dl.sort_order SEPARATOR '、') FROM item_label_map ilm2 JOIN dict_label dl ON dl.label_id=ilm2.label_id AND dl.is_active=1 AND COALESCE(dl.is_hidden_frontend,0)=0 WHERE ilm2.d_id=d.d_id) AS label_names,
                (SELECT GROUP_CONCAT(CONCAT(IF(g2.Module IS NOT NULL,CONCAT('M',g2.Module),''),IF(g2.Teeth IS NOT NULL,CONCAT('×Z',g2.Teeth),'')) ORDER BY g2.gear_id SEPARATOR ' / ') FROM d_setting_gear g2 WHERE g2.d_setting_id=d.d_id) AS gear_summary
            FROM d_setting d LEFT JOIN customer_list c ON d.Customer_Id=c.customer_id LEFT JOIN dict_workpiece_sub_type dst ON d.workpiece_sub_type_id=dst.sub_type_id
            WHERE $whereSQL
            HAVING (label_count > 0 OR gear_summary IS NOT NULL)
            ORDER BY label_count DESC, d.D_Setting_Id LIMIT 20";
            $stmt = $pdo->prepare($sql); $stmt->execute($params);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 重量計算器：取得標籤綁定設定 ──────────────────────────────────────
    if ($_POST['action'] === 'get_weight_binding') {
        try {
            $bRows = $pdo->query("SELECT b.binding_id, b.binding_role, b.label_id, COALESCE(b.sub_id,0) AS sub_id, l.label_name, COALESCE(ls.sub_name,'') AS sub_name FROM weight_calc_binding b JOIN dict_label l ON l.label_id=b.label_id AND l.is_active=1 LEFT JOIN dict_label_sub ls ON ls.sub_id=b.sub_id AND ls.is_active=1")->fetchAll(PDO::FETCH_ASSOC);
            $bmap = []; $hole_bindings = []; $inner_bindings = [];
            foreach ($bRows as $b) {
                $entry = ['label_id'=>(int)$b['label_id'],'label_name'=>$b['label_name'],'sub_id'=>(int)$b['sub_id'],'sub_name'=>$b['sub_name']];
                if ($b['binding_role'] === 'hole')            $hole_bindings[]  = $entry;
                elseif ($b['binding_role'] === 'inner_bore')  $inner_bindings[] = $entry;
                else $bmap[$b['binding_role']] = $entry;
            }
            $allLbls = $pdo->query("SELECT label_id, label_name, type_code FROM dict_label WHERE is_active=1 ORDER BY sort_order, label_id")->fetchAll(PDO::FETCH_ASSOC);
            $dens    = $pdo->query("SELECT density_id, keyword, density_g FROM kpi_material_density ORDER BY sort_order, density_id")->fetchAll(PDO::FETCH_ASSOC);
            echo json_encode(['success'=>true,'bindings'=>$bmap,'hole_bindings'=>$hole_bindings,'inner_bindings'=>$inner_bindings,'all_labels'=>$allLbls,'densities'=>$dens]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 重量計算器：儲存標籤綁定設定 ──────────────────────────────────────
    if ($_POST['action'] === 'save_weight_binding') {
        try {
            if (!$can_update && !$can_create) throw new Exception('無修改權限');
            $roles = json_decode($_POST['bindings'] ?? '{}', true) ?: [];
            $holeArr = json_decode($_POST['hole_bindings'] ?? '[]', true) ?: [];
            $valid = ['material','length','thickness','keyway_w','keyway_l'];
            $pdo->exec("DELETE FROM weight_calc_binding");
            $ins = $pdo->prepare("INSERT INTO weight_calc_binding (binding_role, label_id, sub_id) VALUES (?,?,?)");
            foreach ($roles as $role => $data) {
                $lid = is_array($data) ? intval($data['lid']??0) : intval($data);
                $sid = is_array($data) ? (intval($data['sid']??0) ?: null) : null;
                if (in_array($role, $valid) && $lid > 0) $ins->execute([$role, $lid, $sid]);
            }
            // 孔：允許多個綁定
            foreach ($holeArr as $h) {
                $lid = intval($h['lid'] ?? 0); $sid = intval($h['sid'] ?? 0) ?: null;
                if ($lid > 0) $ins->execute(['hole', $lid, $sid]);
            }
            // 內孔：允許多個綁定（讀 draw_dim=孔徑、lathe_dim=深度）
            $innerArr = json_decode($_POST['inner_bindings'] ?? '[]', true) ?: [];
            foreach ($innerArr as $h) {
                $lid = intval($h['lid'] ?? 0); $sid = intval($h['sid'] ?? 0) ?: null;
                if ($lid > 0) $ins->execute(['inner_bore', $lid, $sid]);
            }
            echo json_encode(['success'=>true]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 重量計算器：取得料號的計算所需資料 ──────────────────────────────────
    if ($_POST['action'] === 'get_part_for_weight_calc') {
        try {
            $d_id = intval($_POST['d_id'] ?? 0);
            if (!$d_id) throw new Exception('缺少料號ID');
            $bRows = $pdo->query("SELECT b.binding_role, b.label_id, COALESCE(b.sub_id,0) AS sub_id, l.label_name, COALESCE(ls.sub_name,'') AS sub_name FROM weight_calc_binding b JOIN dict_label l ON l.label_id=b.label_id AND l.is_active=1 LEFT JOIN dict_label_sub ls ON ls.sub_id=b.sub_id AND ls.is_active=1")->fetchAll(PDO::FETCH_ASSOC);
            $bindings = []; $hole_bindings_list = []; $inner_bindings_list = [];
            foreach ($bRows as $b) {
                $entry = ['label_id'=>(int)$b['label_id'],'label_name'=>$b['label_name'],'sub_id'=>(int)$b['sub_id'],'sub_name'=>$b['sub_name']];
                if ($b['binding_role'] === 'hole')       $hole_bindings_list[]  = $entry;
                elseif ($b['binding_role'] === 'inner_bore') $inner_bindings_list[] = $entry;
                else $bindings[$b['binding_role']] = $entry;
            }
            $part_labels = [];
            foreach ($bindings as $role => $bind) {
                $lid = $bind['label_id']; $sid = intval($bind['sub_id']??0);
                $key = $lid . ($sid > 0 ? ':' . $sid : '');
                if (isset($part_labels[$key])) continue;
                $part_labels[$key] = [];
                if ($sid >= 9900) {
                    // Value slot: 9901=input_value, 9902=draw_dim（用於無子標籤的標籤如「鍵」）
                    $stmt = $pdo->prepare("SELECT m.input_value, m.draw_dim, m.map_id FROM item_label_map m WHERE m.d_id=? AND m.label_id=? ORDER BY m.map_id ASC");
                    $stmt->execute([$d_id, $lid]);
                    $useDrawDim = ($sid === 9902);
                    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $lr) {
                        if ($useDrawDim) {
                            $val = ($lr['draw_dim']!==null&&$lr['draw_dim']!=='') ? floatval($lr['draw_dim']) : null;
                        } else {
                            $val = ($lr['input_value']!==null&&$lr['input_value']!=='') ? $lr['input_value'] : null;
                        }
                        $part_labels[$key][] = ['value'=>$val,'map_id'=>(int)$lr['map_id'],'from_draw'=>$useDrawDim];
                    }
                } elseif ($sid > 0) {
                    $stmt = $pdo->prepare("SELECT islm.input_value, islm.draw_dim, ilm.map_id FROM item_label_map ilm JOIN item_sub_label_map islm ON islm.parent_map_id=ilm.map_id AND islm.sub_id=? WHERE ilm.d_id=? AND ilm.label_id=? ORDER BY ilm.map_id ASC");
                    $stmt->execute([$sid, $d_id, $lid]);
                    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $lr) {
                        $val = ($lr['draw_dim']!==null&&$lr['draw_dim']!=='') ? floatval($lr['draw_dim']) : (($lr['input_value']!==null&&$lr['input_value']!=='') ? $lr['input_value'] : null);
                        $part_labels[$key][] = ['value'=>$val,'map_id'=>(int)$lr['map_id'],'from_draw'=>($lr['draw_dim']!==null&&$lr['draw_dim']!=='')];
                    }
                } else {
                    $stmt = $pdo->prepare("SELECT m.input_value, m.draw_dim, m.map_id FROM item_label_map m WHERE m.d_id=? AND m.label_id=? ORDER BY m.map_id ASC");
                    $stmt->execute([$d_id, $lid]);
                    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $lr) {
                        $val = ($lr['draw_dim']!==null&&$lr['draw_dim']!=='') ? floatval($lr['draw_dim']) : (($lr['input_value']!==null&&$lr['input_value']!=='') ? $lr['input_value'] : null);
                        $part_labels[$key][] = ['value'=>$val,'map_id'=>(int)$lr['map_id'],'from_draw'=>($lr['draw_dim']!==null&&$lr['draw_dim']!=='')];
                    }
                }
            }
            $dens    = $pdo->query("SELECT density_id, keyword, density_g FROM kpi_material_density ORDER BY sort_order, density_id")->fetchAll(PDO::FETCH_ASSOC);
            $allLbls = $pdo->query("SELECT label_id, label_name, type_code FROM dict_label WHERE is_active=1 ORDER BY sort_order, label_id")->fetchAll(PDO::FETCH_ASSOC);
            $wRow    = $pdo->prepare("SELECT weight_source, weight_calc_json FROM d_setting WHERE d_id=?"); $wRow->execute([$d_id]); $wData = $wRow->fetch(PDO::FETCH_ASSOC);
            $existing = null;
            if ($wData && $wData['weight_source']==='calculated' && !empty($wData['weight_calc_json'])) $existing = json_decode($wData['weight_calc_json'], true);
            // 孔實例：讀子標籤的三個欄位（依序：數量input_value、孔徑draw_dim、深度lathe_dim）
            $hole_instances = [];
            $hs = $pdo->prepare("SELECT islm.input_value AS qty_raw, islm.draw_dim AS dia_raw, islm.lathe_dim AS dep_raw, ilm.map_id FROM item_label_map ilm JOIN item_sub_label_map islm ON islm.parent_map_id=ilm.map_id AND islm.sub_id=? WHERE ilm.d_id=? AND ilm.label_id=? ORDER BY ilm.map_id ASC");
            foreach ($hole_bindings_list as $hbind) {
                $hlid = $hbind['label_id']; $hsid = intval($hbind['sub_id'] ?? 0);
                if (!$hlid || $hsid <= 0 || $hsid >= 9900) continue;
                $hs->execute([$hsid, $d_id, $hlid]);
                foreach ($hs->fetchAll(PDO::FETCH_ASSOC) as $hr) {
                    $hole_instances[] = [
                        'qty'   => ($hr['qty_raw']!==null&&$hr['qty_raw']!=='') ? floatval($hr['qty_raw']) : 1,
                        'dia'   => ($hr['dia_raw']!==null&&$hr['dia_raw']!=='') ? floatval($hr['dia_raw']) : null,
                        'depth' => ($hr['dep_raw']!==null&&$hr['dep_raw']!=='') ? floatval($hr['dep_raw']) : null,
                        'map_id'=> (int)$hr['map_id']
                    ];
                }
            }
            // 內孔實例：直接讀父標籤的 draw_dim=圖面尺寸(孔徑)、lathe_dim=深度（無子標籤）
            $inner_instances = [];
            $inner_parent_stmt = $pdo->prepare("SELECT m.draw_dim AS dia_raw, m.lathe_dim AS dep_raw, m.map_id FROM item_label_map m WHERE m.d_id=? AND m.label_id=? ORDER BY m.map_id ASC");
            foreach ($inner_bindings_list as $ibind) {
                $ilid = $ibind['label_id'];
                if (!$ilid) continue;
                $inner_parent_stmt->execute([$d_id, $ilid]);
                foreach ($inner_parent_stmt->fetchAll(PDO::FETCH_ASSOC) as $ir) {
                    $dia = ($ir['dia_raw']!==null&&$ir['dia_raw']!=='') ? floatval($ir['dia_raw']) : null;
                    $dep = ($ir['dep_raw']!==null&&$ir['dep_raw']!=='') ? floatval($ir['dep_raw']) : null;
                    if ($dia !== null) $inner_instances[] = ['dia'=>$dia, 'depth'=>$dep, 'map_id'=>(int)$ir['map_id']];
                }
            }
            // 密度自動比對：子標籤名稱 OR 子標籤值 包含關鍵字
            $auto_density_id = null; $auto_density_g = null; $mat_debug = [];
            if (isset($bindings['material'])) {
                $mlid = $bindings['material']['label_id'];
                // 收集此料號材質標籤的所有子標籤名稱與值（供診斷與比對）
                $dbg = $pdo->prepare("SELECT dls.sub_name, COALESCE(islm.input_value,'') AS val FROM item_label_map ilm JOIN item_sub_label_map islm ON islm.parent_map_id=ilm.map_id JOIN dict_label_sub dls ON dls.sub_id=islm.sub_id AND dls.is_active=1 WHERE ilm.d_id=? AND ilm.label_id=? LIMIT 20");
                $dbg->execute([$d_id, $mlid]);
                $mat_debug = $dbg->fetchAll(PDO::FETCH_ASSOC);
                // 1. 嘗試子標籤名稱完全符合關鍵字
                $dm1 = $pdo->prepare("SELECT kmd.density_id, kmd.density_g FROM item_label_map ilm JOIN item_sub_label_map islm ON islm.parent_map_id=ilm.map_id JOIN dict_label_sub dls ON dls.sub_id=islm.sub_id AND dls.is_active=1 JOIN kpi_material_density kmd ON kmd.keyword!='' AND LOWER(TRIM(kmd.keyword))=LOWER(TRIM(dls.sub_name)) WHERE ilm.d_id=? AND ilm.label_id=? ORDER BY kmd.sort_order,kmd.density_id LIMIT 1");
                $dm1->execute([$d_id, $mlid]);
                if ($dr = $dm1->fetch(PDO::FETCH_ASSOC)) { $auto_density_id=(int)$dr['density_id']; $auto_density_g=(float)$dr['density_g']; }
                // 2. 嘗試子標籤值包含關鍵字（fallback）
                if (!$auto_density_id) {
                    $dm2 = $pdo->prepare("SELECT kmd.density_id, kmd.density_g FROM item_label_map ilm JOIN item_sub_label_map islm ON islm.parent_map_id=ilm.map_id JOIN kpi_material_density kmd ON kmd.keyword!='' AND islm.input_value!='' AND LOWER(islm.input_value) LIKE CONCAT('%',LOWER(TRIM(kmd.keyword)),'%') WHERE ilm.d_id=? AND ilm.label_id=? ORDER BY kmd.sort_order,kmd.density_id LIMIT 1");
                    $dm2->execute([$d_id, $mlid]);
                    if ($dr = $dm2->fetch(PDO::FETCH_ASSOC)) { $auto_density_id=(int)$dr['density_id']; $auto_density_g=(float)$dr['density_g']; }
                }
                // 3. 嘗試父標籤 input_value 包含關鍵字（再 fallback）
                if (!$auto_density_id) {
                    $dm3 = $pdo->prepare("SELECT kmd.density_id, kmd.density_g FROM item_label_map ilm JOIN kpi_material_density kmd ON kmd.keyword!='' AND ilm.input_value!='' AND ilm.input_value IS NOT NULL AND LOWER(ilm.input_value) LIKE CONCAT('%',LOWER(TRIM(kmd.keyword)),'%') WHERE ilm.d_id=? AND ilm.label_id=? ORDER BY kmd.sort_order,kmd.density_id LIMIT 1");
                    $dm3->execute([$d_id, $mlid]);
                    if ($dr = $dm3->fetch(PDO::FETCH_ASSOC)) { $auto_density_id=(int)$dr['density_id']; $auto_density_g=(float)$dr['density_g']; }
                }
            }
            echo json_encode(['success'=>true,'bindings'=>$bindings,'hole_bindings'=>$hole_bindings_list,'inner_bindings'=>$inner_bindings_list,'part_labels'=>$part_labels,'densities'=>$dens,'all_labels'=>$allLbls,'existing_calc'=>$existing,'hole_instances'=>$hole_instances,'inner_instances'=>$inner_instances,'auto_density_id'=>$auto_density_id,'auto_density_g'=>$auto_density_g,'mat_debug'=>$mat_debug]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 重量計算器：儲存計算結果 ───────────────────────────────────────────
    if ($_POST['action'] === 'save_weight_calc') {
        try {
            $d_id = intval($_POST['d_id'] ?? 0);
            if (!$d_id) throw new Exception('缺少料號ID');
            if (!$can_update) throw new Exception('無修改權限');
            $weight_g  = floatval($_POST['weight_g'] ?? 0);
            $calc_json = trim($_POST['calc_json'] ?? '') ?: null;
            $weight_kg = $weight_g / 1000;
            $pdo->prepare("UPDATE d_setting SET Weight_Kg=?, weight_source='calculated', weight_calc_json=?, Modified_By=?, Modified_At=NOW() WHERE d_id=?")
                ->execute([$weight_kg, $calc_json, $uid, $d_id]);
            echo json_encode(['success'=>true,'weight_kg'=>$weight_kg]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 料號／圖面代號 重複判定（save_part 與即時檢查共用同一份規則）────────────
    // 圖面代號必須能唯一對應到一筆料號，否則其他頁面用圖面代號綁定時會對到兩筆。
    // 慣例：圖面代號＝自身料號視為「未設定」（畫面本來就不顯示），舊資料大量如此，不列入衝突對象。
    function md_code_conflict($pdo, $d_id, $D_Setting_Id, $Drawing_No) {
        $d_id = intval($d_id);
        $D_Setting_Id = trim((string)$D_Setting_Id);
        $Drawing_No   = trim((string)$Drawing_No);
        if ($Drawing_No !== '' && $Drawing_No !== $D_Setting_Id) {
            $q = $pdo->prepare("SELECT D_Setting_Id FROM d_setting WHERE Drawing_No=? AND Drawing_No<>D_Setting_Id AND d_id<>? LIMIT 1");
            $q->execute([$Drawing_No, $d_id]);
            if ($r = $q->fetch(PDO::FETCH_ASSOC))
                return ['field'=>'Drawing_No','message'=>"圖面代號「{$Drawing_No}」已是料號「{$r['D_Setting_Id']}」的圖面代號，不可重複"];
            $q = $pdo->prepare("SELECT D_Setting_Id FROM d_setting WHERE D_Setting_Id=? AND d_id<>? LIMIT 1");
            $q->execute([$Drawing_No, $d_id]);
            if ($q->fetch())
                return ['field'=>'Drawing_No','message'=>"圖面代號「{$Drawing_No}」與現有料號同名，其他頁面會對應到兩筆資料，請改用別的代號"];
        }
        if ($D_Setting_Id !== '') {
            $q = $pdo->prepare("SELECT D_Setting_Id FROM d_setting WHERE Drawing_No=? AND Drawing_No<>D_Setting_Id AND d_id<>? LIMIT 1");
            $q->execute([$D_Setting_Id, $d_id]);
            if ($r = $q->fetch(PDO::FETCH_ASSOC))
                return ['field'=>'D_Setting_Id','message'=>"料號「{$D_Setting_Id}」已被料號「{$r['D_Setting_Id']}」拿去當圖面代號，請改用別的料號或先修改對方的圖面代號"];
        }
        return null;
    }

    // 即時檢查（輸入當下就回報原因，不必等到儲存）
    if ($_POST['action'] === 'check_code_conflict') {
        try {
            $c = md_code_conflict($pdo, intval($_POST['d_id'] ?? 0), $_POST['D_Setting_Id'] ?? '', $_POST['Drawing_No'] ?? '');
            echo json_encode(['success'=>true, 'conflict'=>$c ? true : false,
                              'field'=>$c['field'] ?? '', 'message'=>$c['message'] ?? '']);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'save_part') {
        try {
            $d_id       = intval($_POST['d_id'] ?? 0);
            $D_Setting_Id = trim($_POST['D_Setting_Id'] ?? '');
            $Drawing_No   = trim($_POST['Drawing_No']   ?? '') ?: null;
            $Spec_No    = trim($_POST['Spec_No'] ?? '');
            $Revision   = trim($_POST['Revision'] ?? '');
            $Issue_Date = trim($_POST['Issue_Date'] ?? '') ?: null;
            $Type          = trim($_POST['Type'] ?? 'N');
            $sub_raw     = trim($_POST['workpiece_sub_type_id'] ?? '');
            $sub_parts   = array_filter(explode(',', $sub_raw));
            $sub_type_id = !empty($sub_parts) ? intval($sub_parts[0]) : null;  // FK stores first selected
            $Is_Assembly= intval($_POST['Is_Assembly'] ?? 0);
            $Customer_Id= trim($_POST['Customer_Id'] ?? '') ?: null;
            $Remark     = trim($_POST['Remark'] ?? '');
            $Weight_Kg        = (isset($_POST['Weight_Kg']) && $_POST['Weight_Kg'] !== '') ? floatval($_POST['Weight_Kg']) : null;
            $weight_source    = in_array(trim($_POST['weight_source']??''), ['manual','calculated']) ? trim($_POST['weight_source']) : 'manual';
            $weight_calc_json = trim($_POST['weight_calc_json'] ?? '') ?: null;
            $gears_json  = $_POST['gears'] ?? '[]';
            $bom_json    = $_POST['bom_children'] ?? '[]';
            $labels_json = $_POST['labels'] ?? '[]';
            $gears       = json_decode($gears_json, true) ?: [];
            $bom_list    = json_decode($bom_json, true) ?: [];
            $labels_list = json_decode($labels_json, true) ?: [];

            if (empty($D_Setting_Id)) throw new Exception('料號不可為空');
            if (empty($Customer_Id))  throw new Exception('客戶為必填欄位');

            // 圖面代號＝料號本身＝沒設圖面代號，一律存 NULL（畫面本來就不顯示）
            if ($Drawing_No !== null && $Drawing_No === $D_Setting_Id) $Drawing_No = null;
            // 圖面代號不可重複（含不可與別筆料號同名），否則其他頁面用圖面代號綁不到唯一料號
            $conf = md_code_conflict($pdo, $d_id, $D_Setting_Id, $Drawing_No);
            if ($conf) throw new Exception($conf['message']);

            // 取得舊資料（用於 audit diff）
            $old_part_row = [];
            if ($d_id > 0) {
                $old_q = $pdo->prepare("SELECT D_Setting_Id,Spec_No,Revision,Issue_Date,Type,Is_Assembly,Customer_Id,Remark FROM d_setting WHERE d_id=?");
                $old_q->execute([$d_id]);
                $old_part_row = $old_q->fetch(PDO::FETCH_ASSOC) ?: [];
            }

            $pdo->beginTransaction();

            // NULL-safe: 空字串視為 NULL，避免 "" <=> NULL 失敗
            $CustIdForCheck = ($Customer_Id === '' || $Customer_Id === null) ? null : $Customer_Id;
            $SpecForCheck   = ($Spec_No   === '' || $Spec_No   === null) ? null : $Spec_No;
            $RevForCheck    = ($Revision  === '' || $Revision  === null) ? null : $Revision;

            if ($d_id > 0) {
                if (!$can_update && !$can_edit_gear) throw new Exception('無修改權限');
                $ck = $pdo->prepare("SELECT d_id FROM d_setting WHERE D_Setting_Id=? AND d_id<>? AND (Customer_Id <=> ?) AND (Spec_No <=> ?) AND (Revision <=> ?)");
                $ck->execute([$D_Setting_Id, $d_id, $CustIdForCheck, $SpecForCheck, $RevForCheck]);
                if ($ck->fetch()) throw new Exception("料號「$D_Setting_Id」已存在（同客戶、同規格、同版次）");
                $pdo->prepare("UPDATE d_setting SET D_Setting_Id=?,Drawing_No=?,Spec_No=?,Revision=?,Issue_Date=?,Type=?,Is_Assembly=?,workpiece_sub_type_id=?,Customer_Id=?,Remark=?,Weight_Kg=?,weight_source=?,weight_calc_json=?,Modified_By=?,Modified_At=NOW() WHERE d_id=?")
                    ->execute([$D_Setting_Id,$Drawing_No,$Spec_No,$Revision,$Issue_Date,$Type,$Is_Assembly,$sub_type_id,$Customer_Id,$Remark,$Weight_Kg,$weight_source,$weight_calc_json,$uid,$d_id]);
            } else {
                if (!$can_create) throw new Exception('無新增權限');
                $ck = $pdo->prepare("SELECT d_id FROM d_setting WHERE D_Setting_Id=? AND (Customer_Id <=> ?) AND (Spec_No <=> ?) AND (Revision <=> ?)");
                $ck->execute([$D_Setting_Id, $CustIdForCheck, $SpecForCheck, $RevForCheck]);
                if ($ck->fetch()) throw new Exception("料號「$D_Setting_Id」已存在（同客戶、同規格、同版次）");
                $pdo->prepare("INSERT INTO d_setting (D_Setting_Id,Drawing_No,Spec_No,Revision,Issue_Date,Type,Is_Assembly,workpiece_sub_type_id,Customer_Id,Remark,Weight_Kg,weight_source,weight_calc_json,Created_By,Created_At) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())")
                    ->execute([$D_Setting_Id,$Drawing_No,$Spec_No,$Revision,$Issue_Date,$Type,$Is_Assembly,$sub_type_id,$Customer_Id,$Remark,$Weight_Kg,$weight_source,$weight_calc_json,$uid]);
                $d_id = (int)$pdo->lastInsertId();
            }

            // ── 齒輪資料（先取舊資料供審計用）──
            $old_gears_q = $pdo->prepare("SELECT Module,Teeth,Face_Width,Helix_Angle_Str,Helix_Direction,Pressure_Angle,Profile_Shift_X,Workpiece_Length,Gear_Type,Remark_Gear,gear_quality_std,gear_quality_grade FROM d_setting_gear WHERE d_setting_id=? ORDER BY gear_id"); $old_gears_q->execute([$d_id]); $old_gears_data = $old_gears_q->fetchAll(PDO::FETCH_ASSOC);
            $pdo->prepare("DELETE FROM d_setting_gear WHERE d_setting_id=?")->execute([$d_id]);
            if ($Type === 'G' && !empty($gears)) {
                // 預先撈 gear_type spec_category，供壓力角預設值判斷
                $gearTypeCatMap = [];
                try {
                    $gtRows = $pdo->query("SELECT gear_type_id, spec_category FROM dict_gear_type")->fetchAll(PDO::FETCH_ASSOC);
                    foreach ($gtRows as $gt) $gearTypeCatMap[intval($gt['gear_type_id'])] = $gt['spec_category'];
                } catch (Exception $_ge) {}

                $sg = $pdo->prepare("INSERT INTO d_setting_gear (
                    d_setting_id,Module,Teeth,Face_Width,Helix_Angle,Helix_Angle_Str,Helix_Direction,
                    Pressure_Angle,Profile_Shift_X,Workpiece_Length,Gear_Type,Spec_No,Remark_Gear,
                    gear_quality_std,gear_quality_grade,module_input_type,module_display,
                    spec_chain_size,spec_pitch,spec_roller_dia,spec_starts,
                    spec_pulley_profile,spec_pld,
                    spec_spline_type,spec_spline_major_dia,spec_spline_minor_dia,spec_spline_width,
                    spec_spline_std,spec_spline_nominal_dia,
                    Created_By
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
                foreach ($gears as $g) {
                    $v = function($k) use ($g) { return (isset($g[$k]) && $g[$k] !== '') ? $g[$k] : null; };
                    $vf = function($k) use ($g) { $x = $g[$k] ?? null; return ($x !== null && $x !== '') ? floatval($x) : null; };
                    $mod = $v('Module');
                    if ($mod !== null) {
                        $mit = strtoupper($v('module_input_type') ?? 'M');
                        if ($mit === 'M') { $mod = 'M' . ltrim(ltrim($mod, 'm'), 'M'); }
                        // CP/DP已由前端換算為M值，直接加M前綴
                        else { $num = floatval(preg_replace('/[^\d.]/','',$mod)); $mod = ($num > 0) ? 'M'.rtrim(rtrim(sprintf('%.4f',$num),'0'),'.') : null; }
                    }
                    $qstd = $v('Gear_Quality_Std');
                    if ($qstd !== null && !in_array($qstd, ['JIS','ISO','DIN','AGMA'])) $qstd = null;
                    $qgrade = $v('Gear_Quality_Grade');
                    if ($qgrade !== null) $qgrade = intval($qgrade);
                    $pa = $v('Pressure_Angle');
                    if ($pa === null || trim($pa) === '') {
                        // 花鍵預設30度，其他齒輪預設20度
                        $gearTypeId = intval($v('Gear_Type') ?? 0);
                        $specCat = $gearTypeCatMap[$gearTypeId] ?? 'standard';
                        $pa = ($specCat === 'spline') ? '30' : '20';
                    }
                    $sg->execute([$d_id,$mod,$v('Teeth'),$vf('Face_Width'),$v('Helix_Angle'),$v('Helix_Angle_Str'),$v('Helix_Direction'),
                        $pa,$vf('Profile_Shift_X'),$vf('Workpiece_Length'),$v('Gear_Type'),$v('Spec_No'),$v('Remark_Gear'),
                        $qstd,$qgrade,$v('module_input_type'),$v('module_display') ?: null,
                        $v('spec_chain_size'),$vf('spec_pitch'),$vf('spec_roller_dia'),$v('spec_starts') ? intval($v('spec_starts')) : null,
                        $v('spec_pulley_profile'),$vf('spec_pld'),
                        $v('spec_spline_type'),$vf('spec_spline_major_dia'),$vf('spec_spline_minor_dia'),$vf('spec_spline_width'),
                        $v('spec_spline_std'),$vf('spec_spline_nominal_dia'),
                        $uid]);
                }
            }

            // ── 組合件 BOM 子件 ──
            $pdo->prepare("DELETE FROM d_setting_bom WHERE parent_d_id=?")->execute([$d_id]);
            if ($Is_Assembly && !empty($bom_list)) {
                $sb = $pdo->prepare("INSERT INTO d_setting_bom (parent_d_id,child_d_id,standard_qty,Remark_Bom,Created_By,Created_At) VALUES (?,?,?,?,?,NOW())");
                foreach ($bom_list as $b) {
                    $child_id = intval($b['child_d_id'] ?? 0);
                    $qty      = floatval($b['standard_qty'] ?? 1);
                    $remark   = trim($b['Remark_Bom'] ?? '');
                    if (!$child_id) continue;
                    $sb->execute([$d_id, $child_id, $qty, $remark ?: null, $uid]);
                }
            }

            // ── 標籤 ── (先取舊標籤名稱供審計用，再刪)
            $old_lbl_q = $pdo->prepare("SELECT dl.label_name FROM item_label_map ilm JOIN dict_label dl ON dl.label_id=ilm.label_id WHERE ilm.d_id=? ORDER BY ilm.map_id"); $old_lbl_q->execute([$d_id]); $old_label_names = $old_lbl_q->fetchAll(PDO::FETCH_COLUMN);
            $old_map_ids_q = $pdo->prepare("SELECT map_id FROM item_label_map WHERE d_id=?");
            $old_map_ids_q->execute([$d_id]);
            $old_map_ids = $old_map_ids_q->fetchAll(PDO::FETCH_COLUMN);
            if (!empty($old_map_ids)) {
                $ph2 = implode(',', array_fill(0, count($old_map_ids), '?'));
                $pdo->prepare("DELETE FROM item_sub_label_map WHERE parent_map_id IN ($ph2)")->execute(array_values($old_map_ids));
            }
            $pdo->prepare("DELETE FROM item_label_map WHERE d_id=?")->execute([$d_id]);
            if (!empty($labels_list)) {
                $sl = $pdo->prepare("INSERT INTO item_label_map (d_id, label_id, input_value, draw_dim, lathe_dim, value_min, value_max, tol_upper, tol_lower, qty) VALUES (?,?,?,?,?,?,?,?,?,?)");
                // 查各標籤的 meta 設定
                $lmeta = [];
                $lids  = array_unique(array_map(function($l){ return intval($l['label_id']??0); }, $labels_list));
                if (!empty($lids)) {
                    $ph = implode(',', array_fill(0, count($lids), '?'));
                    $lq = $pdo->prepare("SELECT label_id, is_repeatable, has_draw_lathe, COALESCE(has_draw_lathe_depth,0) AS has_draw_lathe_depth, COALESCE(is_triple_dim,0) AS is_triple_dim, is_range, has_tolerance, is_calc_diff, calc_base_label_id, calc_sub_label_id, tolerance_std_upper, COALESCE(is_dimension,0) AS is_dimension, COALESCE(is_qty_dim,0) AS is_qty_dim FROM dict_label WHERE label_id IN ($ph)");
                    $lq->execute(array_values($lids));
                    foreach ($lq->fetchAll(PDO::FETCH_ASSOC) as $lm) $lmeta[$lm['label_id']] = $lm;
                }
                // 自動補齊此料號類型的 calc_diff 標籤（若 base/sub 都在 labels_list 中）
                $submitted_lids = array_flip(array_map(function($l){ return intval($l['label_id']??0); }, $labels_list));
                $calc_q = $pdo->prepare("SELECT label_id, calc_base_label_id, calc_sub_label_id FROM dict_label WHERE FIND_IN_SET(?, type_code) AND is_calc_diff=1 AND is_active=1");
                $calc_q->execute([$Type]);
                foreach ($calc_q->fetchAll(PDO::FETCH_ASSOC) as $cd) {
                    $cid = intval($cd['label_id']);
                    if (isset($submitted_lids[$cid])) continue; // already in list
                    if (!$cd['calc_base_label_id'] || !$cd['calc_sub_label_id']) continue;
                    if (isset($submitted_lids[intval($cd['calc_base_label_id'])]) && isset($submitted_lids[intval($cd['calc_sub_label_id'])])) {
                        $labels_list[] = ['label_id'=>$cid,'input_value'=>'','draw_dim'=>'','lathe_dim'=>'','value_min'=>'','value_max'=>'','tol_upper'=>'','tol_lower'=>'','sub_labels'=>[]];
                        if (!isset($lmeta[$cid])) {
                            $lm2 = $pdo->prepare("SELECT label_id, is_repeatable, has_draw_lathe, is_range, has_tolerance, is_calc_diff, calc_base_label_id, calc_sub_label_id, tolerance_std_upper, COALESCE(is_dimension,0) AS is_dimension, COALESCE(is_qty_dim,0) AS is_qty_dim FROM dict_label WHERE label_id=?");
                            $lm2->execute([$cid]);
                            $lr2 = $lm2->fetch(PDO::FETCH_ASSOC);
                            if ($lr2) $lmeta[$cid] = $lr2;
                        }
                    }
                }
                $seen       = [];
                $sub_sl     = $pdo->prepare("INSERT INTO item_sub_label_map (parent_map_id, sub_id, input_value, draw_dim, lathe_dim, value_min, value_max, tol_upper, tol_lower, qty) VALUES (?,?,?,?,?,?,?,?,?,?)");
                foreach ($labels_list as $litem) {
                    $lid = intval($litem['label_id'] ?? 0);
                    if (!$lid) continue;
                    $lm             = $lmeta[$lid] ?? [];
                    $is_rep         = intval($lm['is_repeatable'] ?? 0);
                    $has_draw_lathe       = intval($lm['has_draw_lathe'] ?? 0);
                    $has_draw_lathe_depth = intval($lm['has_draw_lathe_depth'] ?? 0);
                    $is_triple_dim_lbl    = intval($lm['is_triple_dim'] ?? 0);
                    $is_range_lbl   = intval($lm['is_range'] ?? 0);
                    $has_tol        = intval($lm['has_tolerance'] ?? 0);
                    $is_calc        = intval($lm['is_calc_diff'] ?? 0);
                    $is_dim_lbl     = intval($lm['is_dimension'] ?? 0);
                    $is_qty_dim_lbl = intval($lm['is_qty_dim'] ?? 0);
                    if (!$is_rep && isset($seen[$lid])) continue;
                    $seen[$lid] = true;
                    $ival      = isset($litem['input_value']) && $litem['input_value'] !== '' ? trim($litem['input_value']) : null;
                    $draw_dim  = ($has_draw_lathe || $has_draw_lathe_depth || $is_calc || $is_triple_dim_lbl) && isset($litem['draw_dim'])  && is_numeric($litem['draw_dim'])  ? $litem['draw_dim']  : null;
                    $lathe_dim = ($has_draw_lathe || $has_draw_lathe_depth || $is_calc) && isset($litem['lathe_dim']) && is_numeric($litem['lathe_dim']) ? $litem['lathe_dim'] : null;
                    $value_min = ($is_range_lbl || $is_dim_lbl || $is_qty_dim_lbl || $has_draw_lathe_depth || $is_triple_dim_lbl) && isset($litem['value_min']) && is_numeric($litem['value_min']) ? $litem['value_min'] : null;
                    $value_max = ($is_range_lbl || $is_dim_lbl || $is_qty_dim_lbl || $is_triple_dim_lbl) && isset($litem['value_max']) && is_numeric($litem['value_max']) ? $litem['value_max'] : null;
                    $tol_upper = ($has_tol || $is_calc) && isset($litem['tol_upper']) && is_numeric($litem['tol_upper']) ? $litem['tol_upper'] : null;
                    $tol_lower = $has_tol && isset($litem['tol_lower']) && is_numeric($litem['tol_lower']) ? $litem['tol_lower'] : null;
                    $lbl_qty   = $is_qty_dim_lbl && isset($litem['qty']) && is_numeric($litem['qty']) ? $litem['qty'] : null;
                    $sl->execute([$d_id, $lid, $ival, $draw_dim, $lathe_dim, $value_min, $value_max, $tol_upper, $tol_lower, $lbl_qty]);
                    $new_map_id = (int)$pdo->lastInsertId();
                    // 計算差異新版：calc_value = draw_dim - (lathe_dim + (tol_upper - tol_std))
                    if ($is_calc && $draw_dim !== null && $lathe_dim !== null) {
                        $tol_std_v  = (isset($lm['tolerance_std_upper']) && $lm['tolerance_std_upper'] !== null && $lm['tolerance_std_upper'] !== '') ? floatval($lm['tolerance_std_upper']) : null;
                        $sub_c      = floatval($lathe_dim);
                        if ($tol_upper !== null && $tol_std_v !== null) {
                            $sub_c = round($sub_c + (floatval($tol_upper) - $tol_std_v), 8);
                        }
                        $pdo->prepare("UPDATE item_label_map SET calc_value=? WHERE map_id=?")->execute([round(floatval($draw_dim) - $sub_c, 4), $new_map_id]);
                    }
                    // 子標籤
                    $sub_labels = is_array($litem['sub_labels'] ?? null) ? $litem['sub_labels'] : [];
                    // 查子標籤 meta
                    $sub_ids_q = array_filter(array_map(function($si){ return intval($si['sub_id']??0); }, $sub_labels));
                    $smeta = [];
                    if (!empty($sub_ids_q)) {
                        $sph = implode(',', array_fill(0, count($sub_ids_q), '?'));
                        $smq = $pdo->prepare("SELECT sub_id, has_tolerance, COALESCE(is_dimension,0) AS is_dimension, COALESCE(is_qty_dim,0) AS is_qty_dim, COALESCE(is_qty_triple_dim,0) AS is_qty_triple_dim, COALESCE(is_imperial_dim,0) AS is_imperial_dim, COALESCE(is_countersink,0) AS is_countersink FROM dict_label_sub WHERE sub_id IN ($sph)");
                        $smq->execute(array_values($sub_ids_q));
                        foreach ($smq->fetchAll(PDO::FETCH_ASSOC) as $sm) $smeta[$sm['sub_id']] = $sm;
                    }
                    $sub_seen = [];
                    foreach ($sub_labels as $sitem) {
                        $sid = intval($sitem['sub_id'] ?? 0);
                        if (!$sid) continue;
                        $sub_seen[$sid] = ($sub_seen[$sid] ?? 0) + 1;
                        $s_has_tol    = intval($smeta[$sid]['has_tolerance'] ?? 0);
                        $s_is_dim     = intval($smeta[$sid]['is_dimension'] ?? 0);
                        $s_is_qtydim  = intval($smeta[$sid]['is_qty_dim'] ?? 0);
                        $s_is_qtytriple = intval($smeta[$sid]['is_qty_triple_dim'] ?? 0);
                        $s_is_imperial    = intval($smeta[$sid]['is_imperial_dim'] ?? 0);
                        $s_is_countersink = intval($smeta[$sid]['is_countersink'] ?? 0);
                        $sival        = isset($sitem['input_value']) && $sitem['input_value'] !== '' ? trim($sitem['input_value']) : null;
                        $s_draw_dim   = isset($sitem['draw_dim'])   && is_numeric($sitem['draw_dim'])   ? $sitem['draw_dim']   : null;
                        $s_lathe_dim  = isset($sitem['lathe_dim'])  && is_numeric($sitem['lathe_dim'])  ? $sitem['lathe_dim']  : null;
                        $s_vmin       = isset($sitem['value_min'])  && is_numeric($sitem['value_min'])  ? $sitem['value_min']  : null;
                        $s_vmax       = isset($sitem['value_max'])  && is_numeric($sitem['value_max'])  ? $sitem['value_max']  : null;
                        $s_tol_upper  = ($s_has_tol || $s_is_imperial || $s_is_countersink) && isset($sitem['tol_upper']) && is_numeric($sitem['tol_upper']) ? $sitem['tol_upper'] : null;
                        $s_tol_lower  = ($s_has_tol || $s_is_countersink) && isset($sitem['tol_lower']) && is_numeric($sitem['tol_lower']) ? $sitem['tol_lower'] : null;
                        $s_qty        = ($s_is_qtydim || $s_is_qtytriple || $s_is_imperial || $s_is_countersink) && isset($sitem['qty']) && is_numeric($sitem['qty']) ? $sitem['qty'] : null;
                        $sub_sl->execute([$new_map_id, $sid, $sival, $s_draw_dim, $s_lathe_dim, $s_vmin, $s_vmax, $s_tol_upper, $s_tol_lower, $s_qty]);
                    }
                }
            }

            // 儲存舊料號
            $old_links_raw = trim($_POST['old_part_links'] ?? '[]');
            $old_links_arr = json_decode($old_links_raw, true) ?: [];
            $pdo->prepare("DELETE FROM d_setting_old_part_links WHERE d_id=?")->execute([$d_id]);
            $ins_ol = $pdo->prepare("INSERT IGNORE INTO d_setting_old_part_links (d_id, old_d_id, sort_order) VALUES (?,?,?)");
            foreach (array_values(array_slice($old_links_arr, 0, 3)) as $k => $ol) {
                $old_did = intval($ol['old_d_id'] ?? 0);
                if ($old_did && $old_did !== $d_id) $ins_ol->execute([$d_id, $old_did, $k]);
            }

            // ── 廠商對應（含每廠商單價）── d_setting_vendor_map
            $vendor_raw = trim($_POST['vendor_map'] ?? '[]');
            $vendor_arr = json_decode($vendor_raw, true) ?: [];
            $pdo->prepare("DELETE FROM d_setting_vendor_map WHERE d_id=?")->execute([$d_id]);
            $ins_vm = $pdo->prepare("INSERT INTO d_setting_vendor_map (d_id, maker_id_no, price, sort_order) VALUES (?,?,?,?)
                                     ON DUPLICATE KEY UPDATE price=VALUES(price), sort_order=VALUES(sort_order)");
            $vm_seen = [];
            foreach (array_values($vendor_arr) as $k => $vm) {
                $mk = trim($vm['maker_id_no'] ?? '');
                if ($mk === '' || isset($vm_seen[$mk])) continue;
                $vm_seen[$mk] = true;
                $price = (isset($vm['price']) && $vm['price'] !== '' && is_numeric($vm['price'])) ? floatval($vm['price']) : null;
                $ins_vm->execute([$d_id, $mk, $price, $k]);
            }

            // ── 專用料號對應（指向其他 d_setting）── d_setting_dedicated_part_map
            $dpart_raw = trim($_POST['dedicated_part_map'] ?? '[]');
            $dpart_arr = json_decode($dpart_raw, true) ?: [];
            $pdo->prepare("DELETE FROM d_setting_dedicated_part_map WHERE d_id=?")->execute([$d_id]);
            $ins_dp = $pdo->prepare("INSERT IGNORE INTO d_setting_dedicated_part_map (d_id, ref_d_id, sort_order) VALUES (?,?,?)");
            $dp_seen = [];
            foreach (array_values($dpart_arr) as $k => $dp) {
                $ref = intval($dp['ref_d_id'] ?? 0);
                if ($ref <= 0 || $ref === $d_id || isset($dp_seen[$ref])) continue; // 排除自我關聯與重複
                $dp_seen[$ref] = true;
                $ins_dp->execute([$d_id, $ref, $k]);
            }

            // ── 專用機台對應 ── d_setting_machine_map
            $mach_raw = trim($_POST['machine_map'] ?? '[]');
            $mach_arr = json_decode($mach_raw, true) ?: [];
            $pdo->prepare("DELETE FROM d_setting_machine_map WHERE d_id=?")->execute([$d_id]);
            $ins_mm = $pdo->prepare("INSERT IGNORE INTO d_setting_machine_map (d_id, machine_id, sort_order) VALUES (?,?,?)");
            $mm_seen = [];
            foreach (array_values($mach_arr) as $k => $mm) {
                $mid = intval($mm['machine_id'] ?? 0);
                if ($mid <= 0 || isset($mm_seen[$mid])) continue;
                $mm_seen[$mid] = true;
                $ins_mm->execute([$d_id, $mid, $k]);
            }

            $pdo->commit();
            // ── 重新計算差異標籤 ──
            _recalc_diff_labels($pdo, $d_id);
            // ── audit log ──
            $op_name = _get_operator($pdo, $uid);
            $new_part_arr = ['D_Setting_Id'=>$D_Setting_Id,'Spec_No'=>$Spec_No,'Revision'=>$Revision,'Issue_Date'=>$Issue_Date,'Type'=>$Type,'Is_Assembly'=>$Is_Assembly,'Customer_Id'=>$Customer_Id,'Remark'=>$Remark];
            if (!empty($old_part_row)) {
                $ch = _diff_rows($old_part_row, $new_part_arr, array_keys($new_part_arr));
                if (!empty($ch)) _log_audit($pdo,'update','part',$D_Setting_Id,$D_Setting_Id,$ch,$uid,$op_name);
            } else {
                _log_audit($pdo,'insert','part',$D_Setting_Id,$D_Setting_Id,null,$uid,$op_name);
            }
            // ── 標籤變更審計 ──
            $new_label_names = [];
            if (!empty($labels_list)) { foreach($labels_list as $li){ $lnid=intval($li['label_id']??0); if($lnid){ $lnq=$pdo->prepare("SELECT label_name FROM dict_label WHERE label_id=?"); $lnq->execute([$lnid]); $lnv=$lnq->fetchColumn(); if($lnv) $new_label_names[]=$lnv; } } }
            $added_lbls   = array_diff($new_label_names, $old_label_names);
            $removed_lbls = array_diff($old_label_names, $new_label_names);
            $lbl_ch = [];
            foreach(array_values($added_lbls) as $ln) $lbl_ch[] = ['field'=>'標籤','old'=>'','new'=>$ln];
            foreach(array_values($removed_lbls) as $ln) $lbl_ch[] = ['field'=>'標籤','old'=>$ln,'new'=>''];
            if (!empty($lbl_ch)) _log_audit($pdo,'update','part',$D_Setting_Id,$D_Setting_Id.'(標籤)',$lbl_ch,$uid,$op_name);
            // ── 齒輪規格變更審計 ──
            if ($Type === 'G') {
                $new_gears_q = $pdo->prepare("SELECT Module,Teeth,Face_Width,Helix_Angle_Str,Helix_Direction,Pressure_Angle,Profile_Shift_X,Workpiece_Length,Gear_Type,Remark_Gear FROM d_setting_gear WHERE d_setting_id=? ORDER BY gear_id"); $new_gears_q->execute([$d_id]); $new_gears_data = $new_gears_q->fetchAll(PDO::FETCH_ASSOC);
                $gear_ch = [];
                $maxG = max(count($old_gears_data), count($new_gears_data));
                for ($gi=0; $gi<$maxG; $gi++) {
                    $og = $old_gears_data[$gi] ?? null; $ng = $new_gears_data[$gi] ?? null;
                    if (!$og && $ng) { $gear_ch[] = ['field'=>'齒型'.($gi+1),'old'=>'','new'=>implode('/',array_filter([$ng['Module'],'T'.($ng['Teeth']??'')]))]; }
                    elseif ($og && !$ng) { $gear_ch[] = ['field'=>'齒型'.($gi+1),'old'=>implode('/',array_filter([$og['Module'],'T'.($og['Teeth']??'')])),'new'=>'']; }
                    else { $flds=['Module','Teeth','Face_Width','Helix_Direction','Helix_Angle_Str','Pressure_Angle','Profile_Shift_X','Workpiece_Length','Gear_Type','Remark_Gear']; $dc=_diff_rows($og,$ng,$flds); foreach($dc as &$d2) $d2['field']='齒型'.($gi+1).'.'.$d2['field']; unset($d2); $gear_ch=array_merge($gear_ch,$dc); }
                }
                if (!empty($gear_ch)) _log_audit($pdo,'update','part',$D_Setting_Id,$D_Setting_Id.'(齒輪規格)',$gear_ch,$uid,$op_name);
            }
            echo json_encode(['success'=>true,'message'=>($_POST['d_id']>0?'修改':'新增').'成功','d_id'=>$d_id]);
        } catch (Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    if ($_POST['action'] === 'delete_part') {
        try {
            if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
            $d_id = intval($_POST['d_id']);
            $del_row_q = $pdo->prepare("SELECT D_Setting_Id FROM d_setting WHERE d_id=?");
            $del_row_q->execute([$d_id]);
            $del_row = $del_row_q->fetch(PDO::FETCH_ASSOC);
            // 逐項檢查關聯，收集所有阻擋原因後一次回傳
            $blocks = [];
            $chk = $pdo->prepare("SELECT COUNT(*) FROM order_track WHERE d_id_ID=?");
            $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "訂單 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM bom WHERE d_setting_id=?");
            $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "生產批次(BOM) {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM d_setting_bom WHERE parent_d_id=? OR child_d_id=?");
            $chk->execute([$d_id,$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "BOM組合件關聯 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM is_list WHERE d_setting_id=?");
            $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "出貨單 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM stock_items WHERE d_id=? AND is_active=1");
            $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "庫存紀錄 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM quotation_item WHERE d_setting_d_id=?");
            $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "報價單 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM ir_track WHERE d_setting_id=?");
            $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "退貨單 {$cnt} 筆";
            // 圖面變更紀錄（views/QC/drawing_change_log.php，AS 2-PD-01-07）：綁 d_id，屬品質可追溯紀錄，
            // 刪掉料號會讓「這張圖改過什麼」斷線，故一併阻擋、要求先移轉。表可能尚未建立，故包 try。
            try {
                $chk = $pdo->prepare("SELECT COUNT(*) FROM qc_drawing_change WHERE d_id=?");
                $chk->execute([$d_id]); $cnt=(int)$chk->fetchColumn();
                if ($cnt>0) $blocks[] = "圖面變更紀錄 {$cnt} 筆";
            } catch (Exception $qe) {}
            if (!empty($blocks)) throw new Exception('此料號已有關聯資料，無法刪除：' . implode('、',$blocks));
            $pdo->prepare("DELETE FROM d_setting WHERE d_id=?")->execute([$d_id]);
            _log_audit($pdo,'delete','part',$del_row['D_Setting_Id']??$d_id,null,null,$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true,'message'=>'已刪除']);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ─── 客戶 ─────────────────────────────────────────────────────────────
    // ─── 客戶 ─────────────────────────────────────────────────────────────
    if ($_POST['action'] === 'list_customers') {
        try {
            $lmt_req  = intval($_POST['lmt'] ?? 0);
            $pg  = max(1, intval($_POST['page'] ?? 1));
            $lmt = ($lmt_req > 0 && $lmt_req <= 9999) ? $lmt_req : 10;
            $off = ($pg-1)*10;
            $where = '1=1'; $params = [];
            // 多關鍵字搜尋
            $ckws_p = trim($_POST['keywords_p'] ?? '');
            $ckw_fb = trim($_POST['keyword']    ?? '');
            $ckws = $ckws_p !== '' ? array_values(array_filter(array_map('trim', explode('||', $ckws_p)))) : ($ckw_fb !== '' ? [$ckw_fb] : []);
            if (!empty($ckws)) {
                $ck_ors = [];
                foreach ($ckws as $ci => $ckw_i) {
                    $ck = ":ckw$ci";
                    $ck_ors[] = "(customer_id LIKE $ck OR customer LIKE $ck OR customer_address LIKE $ck OR EXISTS (SELECT 1 FROM customer_industry_mapping cim WHERE cim.customer_id=customer_list.customer_id AND cim.note LIKE $ck))";
                    $params[$ck] = "%$ckw_i%";
                }
                $where .= " AND (" . implode(" OR ", $ck_ors) . ")";
            }
            // 多選等級
            $fgrades_c_raw = trim($_POST['filter_grades_p'] ?? trim($_POST['filter_grade'] ?? ''));
            $fgrades_c = array_values(array_filter(array_map('trim', explode(',', $fgrades_c_raw))));
            if (!empty($fgrades_c)) {
                $phs_g = implode(',', array_map(function($i){ return ":cgr$i"; }, range(0, count($fgrades_c)-1)));
                $where .= " AND customer_grade IN ($phs_g)";
                foreach ($fgrades_c as $i => $gv) { $params[":cgr$i"] = $gv; }
            }
            // 多選產業別（-1=未分類, >0=指定）
            $finds_c_raw = trim($_POST['filter_industries_p'] ?? trim($_POST['filter_industry'] ?? '0'));
            $finds_c_all = array_filter(array_map('trim', explode(',', $finds_c_raw)), function($v){ return $v !== '' && $v !== '0'; });
            $has_uncat_c = in_array('-1', $finds_c_all);
            $pos_finds_c = array_values(array_filter($finds_c_all, function($v){ return intval($v) > 0; }));
            if ($has_uncat_c && empty($pos_finds_c)) {
                $where .= " AND NOT EXISTS (SELECT 1 FROM customer_industry_mapping cim WHERE cim.customer_id=customer_list.customer_id)";
            } elseif (!empty($pos_finds_c) && !$has_uncat_c) {
                $phs_i = implode(',', array_map(function($i){ return ":cfi$i"; }, range(0, count($pos_finds_c)-1)));
                $where .= " AND EXISTS (SELECT 1 FROM customer_industry_mapping cim WHERE cim.customer_id=customer_list.customer_id AND cim.industry_id IN ($phs_i))";
                foreach ($pos_finds_c as $i => $iv) { $params[":cfi$i"] = intval($iv); }
            } elseif ($has_uncat_c && !empty($pos_finds_c)) {
                $phs_i = implode(',', array_map(function($i){ return ":cfi$i"; }, range(0, count($pos_finds_c)-1)));
                $where .= " AND (NOT EXISTS (SELECT 1 FROM customer_industry_mapping cim WHERE cim.customer_id=customer_list.customer_id) OR EXISTS (SELECT 1 FROM customer_industry_mapping cim WHERE cim.customer_id=customer_list.customer_id AND cim.industry_id IN ($phs_i)))";
                foreach ($pos_finds_c as $i => $iv) { $params[":cfi$i"] = intval($iv); }
            }
            // 多選產業別小類
            $findsubs_c_raw = trim($_POST['filter_industry_subs_p'] ?? '');
            $findsubs_c = array_values(array_filter(array_map('intval', explode(',', $findsubs_c_raw)), function($v){ return $v > 0; }));
            if (!empty($findsubs_c)) {
                $phs_cs = implode(',', array_map(function($i){ return ":cfis$i"; }, range(0, count($findsubs_c)-1)));
                $where .= " AND EXISTS (SELECT 1 FROM customer_industry_sub_mapping csm_c WHERE csm_c.customer_id=customer_list.customer_id AND csm_c.sub_id IN ($phs_cs))";
                foreach ($findsubs_c as $i => $sv) { $params[":cfis$i"] = $sv; }
            }
            // 指定客戶篩選（pinned customer IDs）
            $fpinned_c_raw = trim($_POST['filter_pinned_cust_ids'] ?? '');
            $fpinned_c = $fpinned_c_raw !== '' ? array_values(array_filter(array_map('trim', explode(',', $fpinned_c_raw)))) : [];
            if (!empty($fpinned_c)) {
                $phs_pc = implode(',', array_map(function($i){ return ":fpc$i"; }, range(0, count($fpinned_c)-1)));
                $where .= " AND customer_list.customer_id IN ($phs_pc)";
                foreach ($fpinned_c as $i => $cid) { $params[":fpc$i"] = $cid; }
            }
            // 收款方式篩選
            $cf_pm = trim($_POST['filter_payment_method'] ?? '');
            if ($cf_pm !== '') { $where .= " AND payment_method = :cf_pm"; $params[':cf_pm'] = $cf_pm; }
            // 結帳模式篩選
            $cf_sm = trim($_POST['filter_settlement_mode'] ?? '');
            $cf_sd = intval($_POST['filter_settlement_day'] ?? 0);
            if ($cf_sm !== '') {
                if ($cf_sm === 'FIXED' && $cf_sd >= 1 && $cf_sd <= 31) {
                    if ($cf_sd === 31) {
                        $where .= " AND (settlement_mode = 'FIXED' AND settlement_day = 31 OR settlement_mode = 'EOM')";
                    } else {
                        $where .= " AND settlement_mode = 'FIXED' AND settlement_day = :cf_sd";
                        $params[':cf_sd'] = $cf_sd;
                    }
                } else {
                    $where .= " AND settlement_mode = :cf_sm"; $params[':cf_sm'] = $cf_sm;
                }
            }
            $cnt = $pdo->prepare("SELECT COUNT(*) FROM customer_list WHERE $where");
            $cnt->execute($params);
            $total = (int)$cnt->fetchColumn();
            $stmt = $pdo->prepare("SELECT * FROM customer_list WHERE $where ORDER BY CASE WHEN is_own_company=1 THEN 0 ELSE 1 END, CASE WHEN is_inactive=1 THEN 1 ELSE 0 END, customer_id ASC LIMIT $lmt OFFSET $off");
            $stmt->execute($params);
            $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            if (!empty($rows)) {
                $cids = array_column($rows, 'customer_id');
                $ph2 = implode(',', array_fill(0, count($cids), '?'));
                try {
                    $iq = $pdo->prepare("SELECT cim.customer_id, d.industry_id, d.industry_name, cim.note AS industry_note FROM customer_industry_mapping cim JOIN dict_industry_type d ON d.industry_id=cim.industry_id WHERE cim.customer_id IN ($ph2) AND d.is_active=1");
                    $iq->execute($cids);
                    $imap = [];
                    foreach ($iq->fetchAll(PDO::FETCH_ASSOC) as $ir) { $imap[$ir['customer_id']][] = ['industry_id'=>$ir['industry_id'],'industry_name'=>$ir['industry_name'], 'industry_note'=>$ir['industry_note']]; }
                    foreach ($rows as &$row) { $row['industries'] = $imap[$row['customer_id']] ?? []; }
                    unset($row);
                } catch(Exception $ex) {}
                // 業務資訊
                try {
                    $sq = $pdo->prepare("SELECT cs.customer_id, cs.role, u.user_cname AS user_name FROM customer_sales cs JOIN user u ON u.id=cs.user_id WHERE cs.customer_id IN ($ph2) AND cs.is_active=1");
                    $sq->execute($cids);
                    $smap = [];
                    foreach ($sq->fetchAll(PDO::FETCH_ASSOC) as $sr) { $smap[$sr['customer_id']][$sr['role']] = $sr['user_name']; }
                    foreach ($rows as &$row) { $row['sales_primary'] = $smap[$row['customer_id']]['primary'] ?? ''; $row['sales_deputy'] = $smap[$row['customer_id']]['deputy'] ?? ''; }
                    unset($row);
                } catch(Exception $ex) {}
                // 設計備註（有查看權限時補上）
                if ($can_see_design) {
                    try {
                        $dnq = $pdo->prepare("
                            SELECT dn.target_id, dn.note_id, dn.note_text,
                                   CASE WHEN EXISTS(SELECT 1 FROM note_images ni WHERE ni.note_id=dn.note_id AND ni.note_type='customer_design') THEN 1 ELSE 0 END AS has_img
                            FROM design_notes dn
                            WHERE dn.target_type='customer' AND dn.target_id IN ($ph2)
                            ORDER BY dn.created_at ASC");
                        $dnq->execute($cids);
                        $dnmap = [];
                        foreach ($dnq->fetchAll(PDO::FETCH_ASSOC) as $dn) {
                            $tid = $dn['target_id'];
                            if (!isset($dnmap[$tid])) { $dnmap[$tid] = ['first_text'=>$dn['note_text'],'count'=>0,'has_images'=>false]; }
                            $dnmap[$tid]['count']++;
                            if ($dn['has_img']) $dnmap[$tid]['has_images'] = true;
                        }
                        foreach ($rows as &$row) { $row['design_note'] = $dnmap[$row['customer_id']] ?? null; }
                        unset($row);
                    } catch(Exception $ex) {}
                }
            }
            echo json_encode(['success'=>true,'data'=>$rows,'total'=>$total,'pages'=>(int)ceil($total/$lmt),'page'=>$pg]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'get_customer') {
        try {
            $cid = trim($_POST['customer_id']);
            $stmt = $pdo->prepare("SELECT * FROM customer_list WHERE customer_id=?");
            $stmt->execute([$cid]);
            $row = $stmt->fetch(PDO::FETCH_ASSOC);
            if (!$row) throw new Exception('找不到客戶');
            // 聯絡人
            $sc = $pdo->prepare("SELECT * FROM customer_contacts WHERE customer_id=? ORDER BY sort_order, contact_id");
            $sc->execute([$cid]);
            $row['contacts'] = $sc->fetchAll(PDO::FETCH_ASSOC);
            // 業務對應（從 customer_sales 表）
            try {
                $ss = $pdo->prepare("SELECT cs.role, cs.user_id, u.realname AS user_name
                    FROM customer_sales cs LEFT JOIN user u ON u.id=cs.user_id
                    WHERE cs.customer_id=? AND cs.is_active=1");
                $ss->execute([$cid]);
                $row['sales'] = $ss->fetchAll(PDO::FETCH_ASSOC);
            } catch(Exception $ex) { $row['sales'] = []; }
            // 產業別
            $si = $pdo->prepare("SELECT m.industry_id, d.industry_name, m.note AS industry_note FROM customer_industry_mapping m JOIN dict_industry_type d ON d.industry_id=m.industry_id WHERE m.customer_id=?");
            $si->execute([$cid]);
            $row['industries'] = $si->fetchAll(PDO::FETCH_ASSOC);
            // Sub-type mapping
            try {
                $ss = $pdo->prepare("SELECT m.sub_id, m.note AS sub_note, s.sub_name, s.industry_id FROM customer_industry_sub_mapping m JOIN dict_industry_sub_type s ON s.sub_id=m.sub_id WHERE m.customer_id=?");
                $ss->execute([$cid]);
                $row['industry_subs'] = $ss->fetchAll(PDO::FETCH_ASSOC);
            } catch(Exception $ex) { $row['industry_subs'] = []; }
            // 結帳例外
            $se = $pdo->prepare("SELECT * FROM customer_settlement_exceptions WHERE customer_id=? ORDER BY target_year_month DESC LIMIT 12");
            $se->execute([$cid]);
            $row['settlement_exceptions'] = $se->fetchAll(PDO::FETCH_ASSOC);
            echo json_encode(['success'=>true,'data'=>$row]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'save_customer') {
        try {
            $customer_id     = strtoupper(trim($_POST['customer_id'] ?? ''));
            $is_new          = intval($_POST['is_new'] ?? 0);
            $customer        = trim($_POST['customer'] ?? '');
            $customer_full   = trim($_POST['customer_full'] ?? '');
            $customer_grade  = trim($_POST['customer_grade'] ?? '');
            $customer_tel    = trim($_POST['customer_tel'] ?? '');
            $customer_fax    = trim($_POST['customer_fax'] ?? '');
            $customer_address= trim($_POST['customer_address'] ?? '');
            $is_inactive     = intval($_POST['is_inactive'] ?? 0);
            $settlement_mode = trim($_POST['settlement_mode'] ?? 'FIXED');
            $settlement_day  = ($settlement_mode === 'FIXED') ? intval($_POST['settlement_day'] ?? 25) : null;
            $credit_limit    = trim($_POST['credit_limit'] ?? '') !== '' ? floatval($_POST['credit_limit']) : null;
            $payment_term    = trim($_POST['payment_term'] ?? '');
            $industries_raw  = json_decode($_POST['industries'] ?? '[]', true) ?: [];
            // 支援兩種格式：新格式 [{id,note}] 或舊格式 [id1,id2,...]
            $industries = [];
            foreach ($industries_raw as $i_raw) {
                if (is_array($i_raw)) {
                    $industries[] = ['id' => intval($i_raw['id'] ?? 0), 'note' => trim($i_raw['note'] ?? '')];
                } elseif (is_numeric($i_raw)) {
                    $industries[] = ['id' => intval($i_raw), 'note' => ''];
                }
            }
            // Extended fields
            $tax_id          = trim($_POST['tax_id'] ?? '');
            $quote_method    = trim($_POST['quote_method'] ?? 'FOB') ?: 'FOB';
            $payment_method  = trim($_POST['payment_method'] ?? '匯款');
            $net_days        = trim($_POST['net_days'] ?? '') !== '' ? intval($_POST['net_days']) : null;
            $allow_deduct    = intval($_POST['allow_deduct'] ?? 0);
            $bank_name       = trim($_POST['bank_name'] ?? '');
            $bank_branch     = trim($_POST['bank_branch'] ?? '');
            $bank_account    = trim($_POST['bank_account'] ?? '');
            $billing_contact = trim($_POST['billing_contact'] ?? '');
            $shipping_req    = trim($_POST['shipping_req'] ?? '');
            $invoice_email   = trim($_POST['invoice_email'] ?? '');
            $billing_note    = trim($_POST['billing_note'] ?? '');
            $general_note    = trim($_POST['general_note'] ?? '');
            $contacts        = json_decode($_POST['contacts'] ?? '[]', true) ?: [];
            $confirmed_settlement = intval($_POST['confirmed_settlement'] ?? 0);
            $confirmed_payment    = intval($_POST['confirmed_payment'] ?? 0);
            $is_own_company       = intval($_POST['is_own_company'] ?? 0);

            if (empty($customer_id)) throw new Exception('客戶代碼不可為空');
            if (empty($customer))    throw new Exception('客戶名稱不可為空');

            $customer_grade = in_array($customer_grade, ['S','A','B','C','D']) ? $customer_grade : null;

            // 取舊資料用於 audit diff
            $old_cust_row = [];
            $old_sales_p_uid=0; $old_sales_p_name=''; $old_sales_d_uid=0; $old_sales_d_name='';
            if (!$is_new) {
                $oq = $pdo->prepare("SELECT customer,customer_full,customer_tel,customer_fax,customer_address,is_inactive,customer_grade,settlement_mode,settlement_day,tax_id,quote_method,payment_method,net_days,allow_deduct,bank_name,bank_branch,bank_account,billing_contact,shipping_req,invoice_email,billing_note,general_note FROM customer_list WHERE customer_id=?");
                $oq->execute([$customer_id]);
                $old_cust_row = $oq->fetch(PDO::FETCH_ASSOC) ?: [];
                // 取舊業務
                $osr2=$pdo->prepare("SELECT cs.role,cs.user_id,u.user_cname FROM customer_sales cs LEFT JOIN user u ON u.id=cs.user_id WHERE cs.customer_id=? AND cs.is_active=1 AND cs.role IN ('primary','deputy')");
                $osr2->execute([$customer_id]);
                foreach($osr2->fetchAll(PDO::FETCH_ASSOC) as $or2){
                    if($or2['role']==='primary'){$old_sales_p_uid=intval($or2['user_id']);$old_sales_p_name=$or2['user_cname']??'';}
                    if($or2['role']==='deputy') {$old_sales_d_uid=intval($or2['user_id']);$old_sales_d_name=$or2['user_cname']??'';}
                }
            }

            $pdo->beginTransaction();
            // 若設為本公司，先將其他客戶的 is_own_company 清為 0（全系統唯一）
            if ($is_own_company) {
                $pdo->prepare("UPDATE customer_list SET is_own_company=0 WHERE customer_id != ?")->execute([$customer_id]);
            }
            if ($is_new) {
                if (!$can_create) throw new Exception('無新增權限');
                $ck = $pdo->prepare("SELECT customer_id FROM customer_list WHERE customer_id=?");
                $ck->execute([$customer_id]);
                if ($ck->fetch()) throw new Exception("客戶代碼「{$customer_id}」已存在");
                $pdo->prepare("INSERT INTO customer_list
                    (customer_id,customer,customer_full,customer_tel,customer_fax,customer_address,is_inactive,customer_grade,
                     settlement_mode,settlement_day,tax_id,quote_method,payment_method,net_days,allow_deduct,
                     bank_name,bank_branch,bank_account,billing_contact,shipping_req,invoice_email,billing_note,general_note,
                     confirmed_settlement,confirmed_payment,is_own_company,Created_By,Created_At)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())")
                    ->execute([$customer_id,$customer,$customer_full,$customer_tel,$customer_fax,$customer_address,$is_inactive,$customer_grade,
                               $settlement_mode,$settlement_day,$tax_id,$quote_method,$payment_method,$net_days,$allow_deduct,
                               $bank_name,$bank_branch,$bank_account,$billing_contact,$shipping_req,$invoice_email,$billing_note,$general_note,
                               $confirmed_settlement,$confirmed_payment,$is_own_company,$uid]);
            } else {
                if (!$can_update) throw new Exception('無修改權限');
                $pdo->prepare("UPDATE customer_list SET
                    customer=?,customer_full=?,customer_tel=?,customer_fax=?,customer_address=?,is_inactive=?,customer_grade=?,
                    settlement_mode=?,settlement_day=?,tax_id=?,quote_method=?,payment_method=?,net_days=?,allow_deduct=?,
                    bank_name=?,bank_branch=?,bank_account=?,billing_contact=?,shipping_req=?,invoice_email=?,billing_note=?,general_note=?,
                    confirmed_settlement=?,confirmed_payment=?,is_own_company=?,Modified_By=?,Modified_At=NOW() WHERE customer_id=?")
                    ->execute([$customer,$customer_full,$customer_tel,$customer_fax,$customer_address,$is_inactive,$customer_grade,
                               $settlement_mode,$settlement_day,$tax_id,$quote_method,$payment_method,$net_days,$allow_deduct,
                               $bank_name,$bank_branch,$bank_account,$billing_contact,$shipping_req,$invoice_email,$billing_note,$general_note,
                               $confirmed_settlement,$confirmed_payment,$is_own_company,$uid,$customer_id]);
            }
            // 產業別小類 Delete-then-Insert
            $industry_subs = json_decode($_POST['industry_subs'] ?? '[]', true) ?: [];
            try {
                $pdo->prepare("DELETE FROM customer_industry_sub_mapping WHERE customer_id=?")->execute([$customer_id]);
                if (!empty($industry_subs)) {
                    $ins_is = $pdo->prepare("INSERT INTO customer_industry_sub_mapping (customer_id,sub_id,note) VALUES (?,?,?)");
                    foreach ($industry_subs as $is) {
                        if (!empty($is['sub_id'])) $ins_is->execute([$customer_id, intval($is['sub_id']), trim($is['note']??'')]);
                    }
                }
            } catch(Exception $ex) {}  // table may not exist yet
            // 聯絡人 Delete-then-Insert
            $pdo->prepare("DELETE FROM customer_contacts WHERE customer_id=?")->execute([$customer_id]);
            if (!empty($contacts)) {
                $ins_c = $pdo->prepare("INSERT INTO customer_contacts (customer_id,name,department,title,phone_ext,mobile,email,note,is_primary,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)");
                foreach (array_values($contacts) as $k => $c) {
                    if (empty(trim($c['name']??''))) continue;
                    $ins_c->execute([$customer_id,trim($c['name']??''),trim($c['department']??''),trim($c['title']??''),trim($c['phone_ext']??''),trim($c['mobile']??''),trim($c['email']??''),trim($c['note']??''),intval($c['is_primary']??0),$k]);
                }
            }
            // 產業別 Delete-then-Insert
            $pdo->prepare("DELETE FROM customer_industry_mapping WHERE customer_id=?")->execute([$customer_id]);
            if (!empty($industries)) {
                $si = $pdo->prepare("INSERT IGNORE INTO customer_industry_mapping (customer_id,industry_id,note) VALUES (?,?,?)");
                foreach ($industries as $i_obj) { if (!empty($i_obj['id'])) $si->execute([$customer_id, intval($i_obj['id']), trim($i_obj['note']??'')]); }
            }
            // 業務設定（同 save_customer_sales）
            $primary_uid = intval($_POST['primary_user_id'] ?? 0);
            $deputy_uid  = intval($_POST['deputy_user_id'] ?? 0);
            if ($primary_uid > 0) {
                $pdo->prepare("INSERT INTO customer_sales (customer_id,user_id,role,is_active,Created_By,Created_At) VALUES (?,?,'primary',1,?,NOW()) ON DUPLICATE KEY UPDATE user_id=?,is_active=1")
                    ->execute([$customer_id,$primary_uid,$uid,$primary_uid]);
            } else {
                $pdo->prepare("UPDATE customer_sales SET is_active=0 WHERE customer_id=? AND role='primary'")->execute([$customer_id]);
            }
            if ($deputy_uid > 0) {
                $pdo->prepare("INSERT INTO customer_sales (customer_id,user_id,role,is_active,Created_By,Created_At) VALUES (?,?,'deputy',1,?,NOW()) ON DUPLICATE KEY UPDATE user_id=?,is_active=1")
                    ->execute([$customer_id,$deputy_uid,$uid,$deputy_uid]);
            } else {
                $pdo->prepare("UPDATE customer_sales SET is_active=0 WHERE customer_id=? AND role='deputy'")->execute([$customer_id]);
            }
            $pdo->commit();
            // ── audit log ──
            $op_name = _get_operator($pdo, $uid);
            if ($is_new) {
                _log_audit($pdo,'insert','customer',$customer_id,$customer,null,$uid,$op_name);
            } else {
                $new_cust_arr = ['customer'=>$customer,'customer_full'=>$customer_full,'customer_tel'=>$customer_tel,'customer_fax'=>$customer_fax,'customer_address'=>$customer_address,'is_inactive'=>$is_inactive,'customer_grade'=>$customer_grade,'settlement_mode'=>$settlement_mode,'settlement_day'=>$settlement_day,'tax_id'=>$tax_id,'quote_method'=>$quote_method,'payment_method'=>$payment_method,'net_days'=>$net_days,'allow_deduct'=>$allow_deduct,'bank_name'=>$bank_name,'bank_branch'=>$bank_branch,'bank_account'=>$bank_account,'billing_contact'=>$billing_contact,'shipping_req'=>$shipping_req,'invoice_email'=>$invoice_email,'billing_note'=>$billing_note,'general_note'=>$general_note];
                $ch = _diff_rows($old_cust_row, $new_cust_arr, array_keys($new_cust_arr));
                // 業務變動追蹤
                if ($old_sales_p_uid !== $primary_uid) {
                    $new_pn2='—'; if($primary_uid>0){$np2=$pdo->prepare("SELECT user_cname FROM user WHERE id=? LIMIT 1");$np2->execute([$primary_uid]);$new_pn2=$np2->fetchColumn()?:'uid:'.$primary_uid;}
                    $ch[] = ['field'=>'主要業務','old'=>$old_sales_p_name?:($old_sales_p_uid?'uid:'.$old_sales_p_uid:'—'),'new'=>$new_pn2];
                }
                if ($old_sales_d_uid !== $deputy_uid) {
                    $new_dn2='—'; if($deputy_uid>0){$nd2=$pdo->prepare("SELECT user_cname FROM user WHERE id=? LIMIT 1");$nd2->execute([$deputy_uid]);$new_dn2=$nd2->fetchColumn()?:'uid:'.$deputy_uid;}
                    $ch[] = ['field'=>'代理業務','old'=>$old_sales_d_name?:($old_sales_d_uid?'uid:'.$old_sales_d_uid:'—'),'new'=>$new_dn2];
                }
                if (!empty($ch)) _log_audit($pdo,'update','customer',$customer_id,$customer,$ch,$uid,$op_name);
            }
            echo json_encode(['success'=>true,'message'=>$is_new?'新增成功':'修改成功']);
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    if ($_POST['action'] === 'delete_customer') {
        try {
            if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
            $cid = trim($_POST['customer_id']);
            $blocks = [];
            $chk = $pdo->prepare("SELECT COUNT(*) FROM d_setting WHERE Customer_Id=?");
            $chk->execute([$cid]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "料號關聯 {$cnt} 筆（建議改為停用）";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM order_track WHERE Client_name_ID=?");
            $chk->execute([$cid]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "訂單 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM is_list WHERE Client_id=?");
            $chk->execute([$cid]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "出貨單 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM quotation_list WHERE client_id=?");
            $chk->execute([$cid]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "報價單 {$cnt} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM stock_items WHERE client_id=? AND is_active=1");
            $chk->execute([$cid]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "庫存紀錄 {$cnt} 筆";
            if (!empty($blocks)) throw new Exception('此客戶已有關聯資料，無法刪除：' . implode('、',$blocks));
            $del_cust_q = $pdo->prepare("SELECT customer FROM customer_list WHERE customer_id=?"); $del_cust_q->execute([$cid]); $del_cust_name = $del_cust_q->fetchColumn();
            $pdo->prepare("DELETE FROM customer_industry_mapping WHERE customer_id=?")->execute([$cid]);
            $pdo->prepare("DELETE FROM customer_list WHERE customer_id=?")->execute([$cid]);
            _log_audit($pdo,'delete','customer',$cid,$del_cust_name,null,$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true,'message'=>'已刪除']);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 結帳例外 儲存
    if ($_POST['action'] === 'save_settlement_exception') {
        try {
            if (!($can_create||$can_update)) throw new Exception('無權限');
            $cid  = trim($_POST['customer_id']);
            $ym   = trim($_POST['target_year_month']); // YYYY-MM
            $date = trim($_POST['adjusted_date']);
            $reason = trim($_POST['reason'] ?? '');
            if (!preg_match('/^\d{4}-\d{2}$/', $ym)) throw new Exception('年月格式錯誤');
            if (!$date) throw new Exception('調整日期不可為空');
            // upsert
            $chk = $pdo->prepare("SELECT exception_id FROM customer_settlement_exceptions WHERE customer_id=? AND target_year_month=?");
            $chk->execute([$cid, $ym]);
            if ($row = $chk->fetch()) {
                $pdo->prepare("UPDATE customer_settlement_exceptions SET adjusted_date=?,reason=? WHERE exception_id=?")
                    ->execute([$date,$reason,$row['exception_id']]);
            } else {
                $pdo->prepare("INSERT INTO customer_settlement_exceptions (customer_id,target_year_month,adjusted_date,reason) VALUES (?,?,?,?)")
                    ->execute([$cid,$ym,$date,$reason]);
            }
            echo json_encode(['success'=>true,'message'=>'已儲存結帳例外']);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 刪除結帳例外
    if ($_POST['action'] === 'delete_settlement_exception') {
        try {
            if (!$can_delete) throw new Exception('無刪除權限');
            $eid = intval($_POST['exception_id']);
            $pdo->prepare("DELETE FROM customer_settlement_exceptions WHERE exception_id=?")->execute([$eid]);
            echo json_encode(['success'=>true,'message'=>'已刪除']);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 產業別字典
    if ($_POST['action'] === 'get_industry_list') {
        try {
            $rows = $pdo->query("SELECT industry_id, industry_name, note FROM dict_industry_type WHERE is_active=1 ORDER BY sort_order, industry_id")->fetchAll(PDO::FETCH_ASSOC);
            $sq_il = $pdo->prepare("SELECT sub_id, sub_name FROM dict_industry_sub_type WHERE industry_id=? AND is_active=1 ORDER BY sort_order, sub_id");
            foreach ($rows as &$r_il) {
                $sq_il->execute([$r_il['industry_id']]);
                $r_il['sub_types'] = $sq_il->fetchAll(PDO::FETCH_ASSOC);
            }
            unset($r_il);
            echo json_encode(['success'=>true,'data'=>$rows]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 料號圖檔 ─────────────────────────────────────────────────────────────
    if ($_POST['action'] === 'get_part_files') {
        try {
            $pid = trim($_POST['product_id'] ?? '');
            if (!$pid) { echo json_encode(['success'=>true,'files'=>[]]); exit; }
            $stmt = $pdo->prepare("SELECT bom, sqty FROM bom WHERE d_id = ? ORDER BY Created_At DESC");
            $stmt->execute([$pid]);
            $bom_rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            $files = [];
            $scan_dir = 'Z:/BOM/';
            $url_dir  = '/nas/';
            if (is_dir($scan_dir)) {
                $allFiles = scandir($scan_dir);
                foreach ($bom_rows as $row) {
                    $bom = $row['bom'];
                    $qty = $row['sqty'];
                    foreach ($allFiles as $f) {
                        if ($f === '.' || $f === '..') continue;
                        if (strpos($f, $bom) === 0) {
                            $ext = strtolower(pathinfo($f, PATHINFO_EXTENSION));
                            if (in_array($ext, ['jpg','jpeg','png','pdf'])) {
                                $files[] = ['bom'=>$bom.($qty!==null?' (Qty:'.$qty.')':''), 'name'=>$f, 'path'=>$url_dir.$f, 'type'=>$ext, 'mtime'=>filemtime($scan_dir.$f)];
                            }
                        }
                    }
                }
            }
            usort($files, function($a,$b){ return $b['mtime']-$a['mtime']; });
            echo json_encode(['success'=>true,'files'=>$files]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 產業別小類（支援單筆或多筆大類 ID） ──────────────────────────────────
    if ($_POST['action'] === 'get_industry_subs') {
        try {
            $raw = trim($_POST['industry_ids'] ?? trim($_POST['industry_id'] ?? ''));
            $ids = array_values(array_filter(array_map('intval', explode(',', $raw)), function($v){ return $v > 0; }));
            if (empty($ids)) { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $phs = implode(',', array_fill(0, count($ids), '?'));
            $stmt = $pdo->prepare("SELECT sub_id, sub_name, industry_id FROM dict_industry_sub_type WHERE industry_id IN ($phs) AND is_active=1 ORDER BY sort_order, sub_id");
            $stmt->execute($ids);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 料號自動完成 ──────────────────────────────────────────────────────────
    if ($_POST['action'] === 'search_parts_ac') {
        try {
            $kw = trim($_POST['kw'] ?? '');
            if ($kw === '') { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $stmt = $pdo->prepare("SELECT D_Setting_Id AS part_id, Spec_No AS spec_no FROM d_setting WHERE (D_Setting_Id LIKE :kw OR Spec_No LIKE :kw OR Drawing_No LIKE :kw) ORDER BY D_Setting_Id LIMIT 15");
            $stmt->execute([':kw'=>"%$kw%"]);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 廠商自動完成 ──────────────────────────────────────────────────────────
    if ($_POST['action'] === 'search_makers_ac') {
        try {
            $kw = trim($_POST['kw'] ?? '');
            if ($kw === '') { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $stmt = $pdo->prepare("SELECT maker_id_no, COALESCE(maker_id,'') AS maker_short, COALESCE(maker_id_all,'') AS maker_full FROM maker_list WHERE (maker_id_no LIKE :kw OR maker_id LIKE :kw OR maker_id_all LIKE :kw) AND (status IS NULL OR status != 'X') ORDER BY maker_id_no LIMIT 15");
            $stmt->execute([':kw'=>"%$kw%"]);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 專用機台自動完成（料號表單用，來源 machine_list）──────────────────────
    if ($_POST['action'] === 'search_machines_ac') {
        try {
            $kw = trim($_POST['kw'] ?? '');
            if ($kw === '') { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $stmt = $pdo->prepare("SELECT ml.machine_id, COALESCE(ml.machine,'') AS machine_name, COALESCE(mt.machine_type,'') AS machine_type
                                   FROM machine_list ml
                                   LEFT JOIN machine_type mt ON mt.machine_type_id = ml.machine_type_id
                                   WHERE (ml.machine LIKE :kw OR CAST(ml.machine_id AS CHAR) LIKE :kw)
                                     AND (ml.state IS NULL OR ml.state != 1)
                                   ORDER BY ml.machine LIMIT 15");
            $stmt->execute([':kw'=>"%$kw%"]);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 專用料號自動完成（料號表單用，來源 d_setting，回傳 d_id 供對應表使用）──
    if ($_POST['action'] === 'search_dsetting_ac') {
        try {
            $kw = trim($_POST['kw'] ?? '');
            $exclude = intval($_POST['exclude_d_id'] ?? 0); // 排除自己，避免自我關聯
            if ($kw === '') { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $sql = "SELECT d_id, D_Setting_Id AS part_id, COALESCE(Spec_No,'') AS spec_no FROM d_setting WHERE (D_Setting_Id LIKE :kw OR Spec_No LIKE :kw OR Drawing_No LIKE :kw)";
            $params = [':kw'=>"%$kw%"];
            if ($exclude > 0) { $sql .= " AND d_id <> :exid"; $params[':exid'] = $exclude; }
            $sql .= " ORDER BY D_Setting_Id LIMIT 15";
            $stmt = $pdo->prepare($sql);
            $stmt->execute($params);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 客戶自動完成（料號篩選用）────────────────────────────────────────────
    if ($_POST['action'] === 'search_customers_ac') {
        try {
            $kw = trim($_POST['kw'] ?? '');
            if ($kw === '') { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $stmt = $pdo->prepare("SELECT customer_id, customer AS customer_name FROM customer_list WHERE (customer_id LIKE :kw OR customer LIKE :kw) AND (is_inactive IS NULL OR is_inactive != 1) ORDER BY customer LIMIT 20");
            $stmt->execute([':kw'=>"%$kw%"]);
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ─── 廠商 ─────────────────────────────────────────────────────────────
    if ($_POST['action'] === 'list_makers') {
        try {
            $fsub_cats_raw = trim($_POST['filter_sub_cats_p'] ?? trim($_POST['filter_sub_cat'] ?? ''));
            $fsub_cats = array_values(array_filter(array_map('intval', explode(',', $fsub_cats_raw)), function($v){ return $v > 0; }));
            $pg  = max(1, intval($_POST['page'] ?? 1));
            $lmt = ($lmt_req > 0 && $lmt_req <= 9999) ? $lmt_req : 10;
            $off = ($pg-1)*10;
            $where = '1=1'; $params = [];
            // 多選大類
            $fmains_raw = trim($_POST['filter_main_cats_p'] ?? trim($_POST['filter_main_cat'] ?? '0'));
            $fmains_all = array_filter(array_map('trim', explode(',', $fmains_raw)), function($v){ return $v !== '' && $v !== '0'; });
            $has_uncat_m = in_array('-1', $fmains_all);
            $pos_mains   = array_values(array_filter($fmains_all, function($v){ return intval($v) > 0; }));
            if ($has_uncat_m && empty($pos_mains)) {
                $where .= " AND (m.main_category_id IS NULL OR m.main_category_id = 0 OR m.main_category_id = '')
                            AND NOT EXISTS (SELECT 1 FROM maker_sub_category_mapping mmp WHERE mmp.maker_id_no = m.maker_id_no)";
            } elseif (!empty($pos_mains)) {
                $mOrs = [];
                foreach ($pos_mains as $mi => $mid) {
                    $mOrs[] = "(m.main_category_id = :fm{$mi} OR EXISTS (SELECT 1 FROM maker_sub_category_mapping mmp JOIN maker_category_hierarchy mch ON mch.sub_cat_id = mmp.sub_cat_id WHERE mmp.maker_id_no = m.maker_id_no AND mch.main_cat_id = :fm{$mi}b))";
                    $params[":fm{$mi}"]  = $mid;
                    $params[":fm{$mi}b"] = $mid;
                }
                if ($has_uncat_m) {
                    $mOrs[] = "((m.main_category_id IS NULL OR m.main_category_id = 0 OR m.main_category_id = '') AND NOT EXISTS (SELECT 1 FROM maker_sub_category_mapping mmp WHERE mmp.maker_id_no = m.maker_id_no))";
                }
                $where .= " AND (" . implode(" OR ", $mOrs) . ")";
            }
            if (!empty($fsub_cats)) {
                $phs_sc = implode(',', array_map(function($i){ return ":fsc$i"; }, range(0, count($fsub_cats)-1)));
                $where .= " AND EXISTS (SELECT 1 FROM maker_sub_category_mapping mmp2 WHERE mmp2.maker_id_no = m.maker_id_no AND mmp2.sub_cat_id IN ($phs_sc))";
                foreach ($fsub_cats as $i => $sv) { $params[":fsc$i"] = $sv; }
            }
            // 多關鍵字搜尋
            $mkws_p  = trim($_POST['keywords_p'] ?? '');
            $mkw_fb  = trim($_POST['keyword']    ?? '');
            $mkws    = $mkws_p !== '' ? array_values(array_filter(array_map('trim', explode('||', $mkws_p)))) : ($mkw_fb !== '' ? [$mkw_fb] : []);
            if (!empty($mkws)) {
                $mk_ors = [];
                foreach ($mkws as $mki => $mkw_i) {
                    $mk = ":mkw$mki";
                    $mk_ors[] = "(m.maker_id_no LIKE $mk OR m.maker_id LIKE $mk OR m.maker_id_all LIKE $mk OR m.m_category LIKE $mk OR m.m_process_items LIKE $mk
                                  OR EXISTS (SELECT 1 FROM dict_maker_main_category mc2 JOIN maker_category_hierarchy h2 ON h2.main_cat_id=mc2.main_cat_id JOIN maker_sub_category_mapping mp2 ON mp2.sub_cat_id=h2.sub_cat_id AND mp2.maker_id_no=m.maker_id_no WHERE mc2.main_cat_name LIKE $mk)
                                  OR EXISTS (SELECT 1 FROM dict_maker_sub_category ds2 JOIN maker_sub_category_mapping mp3 ON mp3.sub_cat_id=ds2.sub_cat_id AND mp3.maker_id_no=m.maker_id_no WHERE ds2.sub_cat_name LIKE $mk))";
                    $params[$mk] = "%$mkw_i%";
                }
                $where .= " AND (" . implode(" OR ", $mk_ors) . ")";
            }
            // 指定廠商篩選（pinned maker IDs）
            $fpinned_m_raw = trim($_POST['filter_pinned_maker_ids'] ?? '');
            $fpinned_m = $fpinned_m_raw !== '' ? array_values(array_filter(array_map('trim', explode(',', $fpinned_m_raw)))) : [];
            if (!empty($fpinned_m)) {
                $phs_pm = implode(',', array_map(function($i){ return ":fpm$i"; }, range(0, count($fpinned_m)-1)));
                $where .= " AND m.maker_id_no IN ($phs_pm)";
                foreach ($fpinned_m as $i => $mid) { $params[":fpm$i"] = $mid; }
            }
            // 付款方式篩選
            $fpm = trim($_POST['filter_payment_method'] ?? '');
            if ($fpm !== '') { $where .= " AND m.payment_method = :fpm"; $params[':fpm'] = $fpm; }
            // 結帳模式篩選
            $fsm = trim($_POST['filter_settlement_mode'] ?? '');
            $fsd = intval($_POST['filter_settlement_day'] ?? 0);
            if ($fsm !== '') {
                if ($fsm === 'FIXED' && $fsd >= 1 && $fsd <= 31) {
                    if ($fsd === 31) {
                        $where .= " AND (m.settlement_mode = 'FIXED' AND m.settlement_day = 31 OR m.settlement_mode = 'EOM')";
                    } else {
                        $where .= " AND m.settlement_mode = 'FIXED' AND m.settlement_day = :fsd";
                        $params[':fsd'] = $fsd;
                    }
                } else {
                    $where .= " AND m.settlement_mode = :fsm"; $params[':fsm'] = $fsm;
                }
            }
            // 廠商加工限制標籤篩選
            $fpl_raw = trim($_POST['filter_proc_labels'] ?? '');
            $fpl_arr = ($fpl_raw !== '' && $fpl_raw !== '[]') ? (json_decode($fpl_raw, true) ?: []) : [];
            foreach ($fpl_arr as $i => $fpl) {
                $pid   = intval($fpl['id'] ?? 0);
                $ftype = $fpl['filter_type'] ?? 'none';
                $fval  = $fpl['value'] ?? null;
                if (!$pid) continue;
                if ($ftype === 'MAX' && $fval !== null && $fval !== '') {
                    // 篩選條件：廠商設定的 MAX >= 輸入值（廠商能力上限 >= 需求值）
                    $where .= " AND EXISTS (SELECT 1 FROM maker_proc_label_map mpl WHERE mpl.maker_id_no=m.maker_id_no AND mpl.proc_label_id=:fpl_id{$i} AND mpl.value_max IS NOT NULL AND mpl.value_max >= :fpl_val{$i})";
                    $params[":fpl_id{$i}"] = $pid;
                    $params[":fpl_val{$i}"] = floatval($fval);
                } elseif ($ftype === 'MIN' && $fval !== null && $fval !== '') {
                    // 篩選條件：廠商設定的 MIN <= 輸入值（廠商能力下限 <= 需求值）
                    $where .= " AND EXISTS (SELECT 1 FROM maker_proc_label_map mpl WHERE mpl.maker_id_no=m.maker_id_no AND mpl.proc_label_id=:fpl_id{$i} AND mpl.value_min IS NOT NULL AND mpl.value_min <= :fpl_val{$i})";
                    $params[":fpl_id{$i}"] = $pid;
                    $params[":fpl_val{$i}"] = floatval($fval);
                } elseif ($ftype === 'range' && $fval !== null && $fval !== '') {
                    // 篩選條件：輸入值落在廠商範圍內（min <= 輸入值 <= max）
                    $where .= " AND EXISTS (SELECT 1 FROM maker_proc_label_map mpl WHERE mpl.maker_id_no=m.maker_id_no AND mpl.proc_label_id=:fpl_id{$i} AND mpl.value_min IS NOT NULL AND mpl.value_max IS NOT NULL AND mpl.value_min <= :fpl_val{$i} AND mpl.value_max >= :fpl_val2{$i})";
                    $params[":fpl_id{$i}"]   = $pid;
                    $params[":fpl_val{$i}"]  = floatval($fval);
                    $params[":fpl_val2{$i}"] = floatval($fval);
                } elseif ($ftype === 'text' && $fval !== null && $fval !== '') {
                    $where .= " AND EXISTS (SELECT 1 FROM maker_proc_label_map mpl WHERE mpl.maker_id_no=m.maker_id_no AND mpl.proc_label_id=:fpl_id{$i} AND mpl.text_value LIKE :fpl_val{$i})";
                    $params[":fpl_id{$i}"]  = $pid;
                    $params[":fpl_val{$i}"] = '%' . $fval . '%';
                } else {
                    $where .= " AND EXISTS (SELECT 1 FROM maker_proc_label_map mpl WHERE mpl.maker_id_no=m.maker_id_no AND mpl.proc_label_id=:fpl_id{$i})";
                    $params[":fpl_id{$i}"] = $pid;
                }
            }
            $cnt = $pdo->prepare("SELECT COUNT(DISTINCT m.maker_id_no) FROM maker_list m WHERE $where");
            $cnt->execute($params);
            $total = (int)$cnt->fetchColumn();

            // 基本資料
            $stmt = $pdo->prepare("SELECT m.* FROM maker_list m WHERE $where ORDER BY CASE WHEN m.status='X' THEN 1 ELSE 0 END, m.maker_id_no ASC LIMIT $lmt OFFSET $off");
            $stmt->execute($params);
            $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

            // 補上每筆廠商的小類標籤（含大類 palette 索引）
            if (!empty($rows)) {
                // 預先取得大類排序 index
                $mainCatIdx = [];
                $mcIdMap = [];
                $mcList = $pdo->query("SELECT main_cat_id, main_cat_name FROM dict_maker_main_category WHERE is_active=1 ORDER BY sort_order, main_cat_id")->fetchAll(PDO::FETCH_ASSOC);
                foreach ($mcList as $k => $mc) { 
                    $mainCatIdx[$mc['main_cat_id']] = $k; 
                    $mcIdMap[$mc['main_cat_id']] = $mc['main_cat_name'];
                }

                $maker_ids = array_column($rows, 'maker_id_no');
                $placeholders = implode(',', array_fill(0, count($maker_ids), '?'));

                // 小類 + 大類名稱聚合（每家廠商）
                $sqSub = $pdo->prepare("
                    SELECT mp.maker_id_no,
                           s.sub_cat_id, s.sub_cat_name, s.sub_cat_group,
                           h.main_cat_id, mc.main_cat_name
                    FROM maker_sub_category_mapping mp
                    JOIN dict_maker_sub_category s ON s.sub_cat_id=mp.sub_cat_id AND s.is_active=1
                    LEFT JOIN maker_category_hierarchy h ON h.sub_cat_id=s.sub_cat_id
                    LEFT JOIN dict_maker_main_category mc ON mc.main_cat_id=h.main_cat_id AND mc.is_active=1
                    WHERE mp.maker_id_no IN ($placeholders)
                    ORDER BY mp.maker_id_no, mc.main_cat_name, s.sub_cat_name");
                $sqSub->execute($maker_ids);
                $subByMaker = [];
                $mainByMaker = [];
                foreach ($sqSub->fetchAll(PDO::FETCH_ASSOC) as $sr) {
                    $mid = $sr['maker_id_no'];
                    if (!isset($subByMaker[$mid])) $subByMaker[$mid] = [];
                    $key = $sr['sub_cat_id'].'_'.($sr['main_cat_id']??'');
                    if (!isset($subByMaker[$mid][$key])) {
                        $subByMaker[$mid][$key] = [
                            'sub_cat_id'   => $sr['sub_cat_id'],
                            'sub_cat_name' => $sr['sub_cat_name'],
                            'sub_cat_group'=> $sr['sub_cat_group'],
                            'main_cat_id'  => $sr['main_cat_id'],
                            'main_cat_name'=> $sr['main_cat_name'],
                            'main_cat_idx' => isset($mainCatIdx[$sr['main_cat_id']]) ? $mainCatIdx[$sr['main_cat_id']] : 0,
                        ];
                    }
                    if ($sr['main_cat_id'] && !in_array($sr['main_cat_name'], $mainByMaker[$mid]??[])) {
                        $mainByMaker[$mid][] = $sr['main_cat_name'];
                    }
                }
                // 加工限制標籤
                $plByMaker = [];
                try {
                    $plStmt = $pdo->prepare("SELECT m.maker_id_no, m.map_id, m.proc_label_id, COALESCE(m.parent_map_id,0) AS parent_map_id, l.label_name, l.input_type, l.numeric_type, l.unit, COALESCE(l.parent_label_id,0) AS parent_label_id, COALESCE(l.is_repeatable,0) AS is_repeatable, m.value_min, m.value_max, m.text_value FROM maker_proc_label_map m JOIN dict_maker_proc_label l ON l.proc_label_id=m.proc_label_id AND l.is_active=1 WHERE m.maker_id_no IN ($placeholders) ORDER BY m.map_id");
                    $plStmt->execute($maker_ids);
                    foreach ($plStmt->fetchAll(PDO::FETCH_ASSOC) as $pr) { $plByMaker[$pr['maker_id_no']][] = $pr; }
                } catch (Exception $ex) {}

                // 檢查哪些廠商是其他廠商的舊編號
                $aliasOfMap = [];
                try {
                    $aqStmt = $pdo->prepare("SELECT a.old_id, a.new_id, m.maker_id AS new_name FROM maker_aliases a JOIN maker_list m ON m.maker_id_no=a.new_id WHERE a.old_id IN ($placeholders)");
                    $aqStmt->execute($maker_ids);
                    foreach ($aqStmt->fetchAll(PDO::FETCH_ASSOC) as $ar) {
                        $aliasOfMap[$ar['old_id']] = ['new_id'=>$ar['new_id'],'new_name'=>$ar['new_name']];
                    }
                } catch (Exception $ex) {}

                foreach ($rows as &$row) {
                    $mid = $row['maker_id_no'];
                    $row['sub_cat_tags']    = array_values($subByMaker[$mid] ?? []);
                    $row['main_cat_labels'] = $mainByMaker[$mid] ?? [];
                    $row['proc_labels']     = $plByMaker[$mid] ?? [];
                    $row['main_cat_name']   = isset($mcIdMap[$row['main_category_id']]) ? $mcIdMap[$row['main_category_id']] : ($mainByMaker[$mid][0] ?? null);
                    $row['is_old_alias']    = $aliasOfMap[$mid] ?? null; // null=非舊編號 / {new_id,new_name}=是
                }
                unset($row);
            }

            echo json_encode(['success'=>true,'data'=>$rows,'total'=>$total,'pages'=>(int)ceil($total/$lmt),'page'=>$pg]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 廠商歷史編號：新增連結 ───────────────────────────────────────────────
    if ($_POST['action'] === 'add_maker_alias') {
        try {
            if (!($can_update||$can_create)) throw new Exception('無權限');
            $new_id = trim($_POST['maker_id_no']);    // 目前廠商（新）
            $old_id = strtoupper(trim($_POST['old_id']));  // 舊廠商編號
            if (!$old_id || !$new_id) throw new Exception('廠商編號不可為空');
            if ($old_id === $new_id) throw new Exception('舊編號與目前編號相同');
            // 確認舊編號存在
            $ck = $pdo->prepare("SELECT maker_id FROM maker_list WHERE maker_id_no=?");
            $ck->execute([$old_id]); $oldRow = $ck->fetch(PDO::FETCH_ASSOC);
            if (!$oldRow) throw new Exception("廠商編號「{$old_id}」不存在，請確認後再連結");
            // 確認尚未連結
            $ck2 = $pdo->prepare("SELECT alias_id FROM maker_aliases WHERE old_id=? AND new_id=?");
            $ck2->execute([$old_id, $new_id]);
            if ($ck2->fetch()) throw new Exception("「{$old_id}」已連結至此廠商");
            $pdo->prepare("INSERT INTO maker_aliases (old_id,new_id,created_by) VALUES (?,?,?)")
                ->execute([$old_id, $new_id, $uid]);
            $aid = (int)$pdo->lastInsertId();
            echo json_encode(['success'=>true,'alias'=>['alias_id'=>$aid,'old_id'=>$old_id,'old_name'=>$oldRow['maker_id'],'created_at'=>date('Y-m-d')]]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 廠商歷史編號：移除連結 ───────────────────────────────────────────────
    if ($_POST['action'] === 'remove_maker_alias') {
        try {
            if (!($can_update||$can_create)) throw new Exception('無權限');
            $aid = intval($_POST['alias_id']);
            $pdo->prepare("DELETE FROM maker_aliases WHERE alias_id=?")->execute([$aid]);
            echo json_encode(['success'=>true]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'get_maker') {
        try {
            $mid = trim($_POST['maker_id_no']);
            $stmt = $pdo->prepare("SELECT * FROM maker_list WHERE maker_id_no=?");
            $stmt->execute([$mid]);
            $row = $stmt->fetch(PDO::FETCH_ASSOC);
            if (!$row) throw new Exception('找不到廠商');

            // 讀取已選小類（maker_sub_category_mapping 用 varchar maker_id_no）
            try {
                $sq = $pdo->prepare("
                    SELECT m.sub_cat_id, s.sub_cat_name, s.sub_cat_group
                    FROM maker_sub_category_mapping m
                    JOIN dict_maker_sub_category s ON s.sub_cat_id = m.sub_cat_id
                    WHERE m.maker_id_no = ? AND s.is_active = 1
                    ORDER BY m.sub_cat_id");
                $sq->execute([$mid]);
                $row['sub_cats'] = $sq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['sub_cats'] = []; }

            // 讀取此廠商的大類（透過小類反推，並加上 main_category_id 直接欄位）
            $mainIds = [];
            if ($row['main_category_id']) $mainIds[] = intval($row['main_category_id']);
            // 也從 maker_sub_category_mapping → maker_category_hierarchy 反查大類
            try {
                $mq = $pdo->prepare("
                    SELECT DISTINCT h.main_cat_id
                    FROM maker_sub_category_mapping m
                    JOIN maker_category_hierarchy h ON h.sub_cat_id = m.sub_cat_id
                    WHERE m.maker_id_no = ?");
                $mq->execute([$mid]);
                foreach ($mq->fetchAll(PDO::FETCH_COLUMN) as $id) {
                    if (!in_array((int)$id, $mainIds)) $mainIds[] = (int)$id;
                }
            } catch (Exception $ex) {}
            $row['selected_main_cat_ids'] = $mainIds;

            // 此廠商是否本身為某廠商的舊編號
            try {
                $raq = $pdo->prepare("SELECT a.new_id, ml.maker_id AS new_name FROM maker_aliases a JOIN maker_list ml ON ml.maker_id_no=a.new_id WHERE a.old_id=? LIMIT 1");
                $raq->execute([$mid]);
                $row['is_old_alias'] = $raq->fetch(PDO::FETCH_ASSOC) ?: null;
            } catch (Exception $ex) { $row['is_old_alias'] = null; }
            // 廠商歷史編號（alias）
            try {
                $aq = $pdo->prepare("SELECT a.alias_id, a.old_id, m.maker_id AS old_name, a.created_at FROM maker_aliases a LEFT JOIN maker_list m ON m.maker_id_no=a.old_id WHERE a.new_id=? ORDER BY a.created_at DESC");
                $aq->execute([$mid]);
                $row['aliases'] = $aq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['aliases'] = []; }
            // 廠商聯絡人
            try {
                $mcq = $pdo->prepare("SELECT * FROM maker_contacts WHERE maker_id_no=? ORDER BY sort_order, contact_id");
                $mcq->execute([$mid]);
                $row['contacts'] = $mcq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['contacts'] = []; }
            // 廠商加工限制標籤
            try {
                $plq = $pdo->prepare("SELECT m.map_id, m.proc_label_id, COALESCE(m.parent_map_id,0) AS parent_map_id, l.label_name, l.input_type, l.numeric_type, l.unit, COALESCE(l.parent_label_id,0) AS parent_label_id, COALESCE(l.is_repeatable,0) AS is_repeatable, m.value_min, m.value_max, m.text_value FROM maker_proc_label_map m JOIN dict_maker_proc_label l ON l.proc_label_id=m.proc_label_id AND l.is_active=1 WHERE m.maker_id_no=? ORDER BY m.map_id");
                $plq->execute([$mid]);
                $row['proc_labels'] = $plq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['proc_labels'] = []; }
            // 廠商大類製程標籤
            try {
                $ptq = $pdo->prepare("SELECT main_cat_id, ref_type, ref_id FROM maker_main_cat_process_tag WHERE maker_id_no=? ORDER BY main_cat_id, ref_type, ref_id");
                $ptq->execute([$mid]);
                $row['main_cat_process_tags'] = $ptq->fetchAll(PDO::FETCH_ASSOC);
            } catch (Exception $ex) { $row['main_cat_process_tags'] = []; }

            echo json_encode(['success'=>true,'data'=>$row]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'save_maker') {
        try {
            $mid             = strtoupper(trim($_POST['maker_id_no'] ?? ''));
            $is_new          = intval($_POST['is_new'] ?? 0);
            $maker_id        = trim($_POST['maker_id'] ?? '');
            $maker_all       = trim($_POST['maker_id_all'] ?? '');
            $m_tel           = trim($_POST['m_tel'] ?? '');
            $m_tel2          = trim($_POST['m_tel2'] ?? '');
            $m_fax           = trim($_POST['m_fax'] ?? '');
            $invoice_address = trim($_POST['invoice_address'] ?? '');
            $factory_address = trim($_POST['factory_address'] ?? '');
            $billing_address = trim($_POST['billing_address'] ?? '');
            $postal_code     = trim($_POST['postal_code'] ?? '');
            $tax_id          = trim($_POST['tax_id'] ?? '');
            $contact_person  = trim($_POST['contact_person'] ?? '');
            $contact_title   = trim($_POST['contact_title'] ?? '');
            $email           = trim($_POST['email'] ?? '');
            $m_category      = trim($_POST['m_category'] ?? '');
            $m_process_items = trim($_POST['m_process_items'] ?? '');
            $limit_dia       = trim($_POST['limit_dia'] ?? '');
            $limit_len       = trim($_POST['limit_len'] ?? '');
            $m_note          = trim($_POST['m_note'] ?? '');
            $status          = trim($_POST['status'] ?? '');
            $internal        = intval($_POST['internal'] ?? 0);
            $main_category_id= trim($_POST['main_category_id'] ?? '') !== '' ? intval($_POST['main_category_id']) : null;
            $quality_rating  = trim($_POST['quality_rating'] ?? '');
            $is_qualified    = intval($_POST['is_qualified'] ?? 0);

            if (empty($mid))      throw new Exception('廠商編號不可為空');
            if (empty($maker_id)) throw new Exception('廠商簡稱不可為空');

            $m_settlement_mode = trim($_POST['settlement_mode'] ?? 'FIXED');
            if (!in_array($m_settlement_mode, ['FIXED','EOM','VARIABLE'])) $m_settlement_mode = 'FIXED';
            $m_settlement_day  = ($m_settlement_mode === 'FIXED') ? intval($_POST['settlement_day'] ?? 0) ?: null : null;
            $m_payment_method  = trim($_POST['payment_method'] ?? '');
            $m_net_days        = trim($_POST['net_days'] ?? '') !== '' ? intval($_POST['net_days']) : null;
            $m_confirmed_settlement = intval($_POST['confirmed_settlement'] ?? 0);
            $m_confirmed_payment    = intval($_POST['confirmed_payment'] ?? 0);

            // 取舊資料用於 audit diff
            $old_maker_row = [];
            if (!$is_new) {
                $oqm = $pdo->prepare("SELECT maker_id,maker_id_all,m_tel,m_tel2,m_fax,m_category,status,invoice_address,factory_address,m_note,m_process_items,limit_dia,limit_len,internal,is_qualified,quality_rating,settlement_mode,settlement_day,payment_method,net_days FROM maker_list WHERE maker_id_no=?");
                $oqm->execute([$mid]);
                $old_maker_row = $oqm->fetch(PDO::FETCH_ASSOC) ?: [];
            }

            $limit_dia_min = trim($_POST['limit_dia_min'] ?? ''); $limit_dia_min = $limit_dia_min!=='' ? floatval($limit_dia_min) : null;
            $limit_dia_max = trim($_POST['limit_dia_max'] ?? ''); $limit_dia_max = $limit_dia_max!=='' ? floatval($limit_dia_max) : null;
            $limit_len_min = trim($_POST['limit_len_min'] ?? ''); $limit_len_min = $limit_len_min!=='' ? floatval($limit_len_min) : null;
            $limit_len_max = trim($_POST['limit_len_max'] ?? ''); $limit_len_max = $limit_len_max!=='' ? floatval($limit_len_max) : null;
            $fields = "maker_id,maker_id_all,m_tel,m_tel2,m_fax,invoice_address,factory_address,billing_address,postal_code,tax_id,contact_person,contact_title,email,m_category,m_process_items,limit_dia,limit_len,limit_dia_min,limit_dia_max,limit_len_min,limit_len_max,m_note,status,internal,main_category_id,settlement_mode,settlement_day,payment_method,net_days,confirmed_settlement,confirmed_payment,quality_rating,is_qualified";
            $vals   = [$maker_id,$maker_all,$m_tel,$m_tel2,$m_fax,$invoice_address,$factory_address,$billing_address,$postal_code,$tax_id,$contact_person,$contact_title,$email,$m_category,$m_process_items,$limit_dia,$limit_len,$limit_dia_min,$limit_dia_max,$limit_len_min,$limit_len_max,$m_note,$status,$internal,$main_category_id,$m_settlement_mode,$m_settlement_day,$m_payment_method,$m_net_days,$m_confirmed_settlement,$m_confirmed_payment,$quality_rating,$is_qualified];

            // 解析前端傳來的 sub_cats JSON（格式: [1,3,5] 整數陣列）
            $sub_cats_raw = trim($_POST['sub_cats'] ?? '[]');
            $sub_cat_ids  = array_values(array_filter(array_map('intval',
                json_decode($sub_cats_raw, true) ?: []
            )));

            $pdo->beginTransaction();

            if ($is_new) {
                if (!$can_create) throw new Exception('無新增權限');
                $ck = $pdo->prepare("SELECT maker_id_no FROM maker_list WHERE maker_id_no=?");
                $ck->execute([$mid]);
                if ($ck->fetch()) throw new Exception("廠商編號「{$mid}」已存在");
                $ph = implode(',', array_fill(0, count($vals)+2, '?'));
                $pdo->prepare("INSERT INTO maker_list (maker_id_no,{$fields},Created_By,Created_At) VALUES ({$ph},NOW())")
                    ->execute(array_merge([$mid],$vals,[$uid]));
            } else {
                if (!$can_update) throw new Exception('無修改權限');
                $sets = implode(',', array_map(function($f){ return "$f=?"; }, explode(',',$fields)));
                $pdo->prepare("UPDATE maker_list SET {$sets},Modified_By=?,Modified_At=NOW() WHERE maker_id_no=?")
                    ->execute(array_merge($vals,[$uid,$mid]));
            }

            // 同步小類映射：Delete-then-Insert（使用 varchar maker_id_no）
            $pdo->prepare("DELETE FROM maker_sub_category_mapping WHERE maker_id_no=?")->execute([$mid]);
            if (!empty($sub_cat_ids)) {
                $ins_sub = $pdo->prepare("INSERT IGNORE INTO maker_sub_category_mapping (maker_id_no, sub_cat_id) VALUES (?,?)");
                foreach ($sub_cat_ids as $sid) {
                    $ins_sub->execute([$mid, $sid]);
                }
            }

            // 同步廠商加工限制標籤
            $proc_labels_raw = trim($_POST['proc_labels'] ?? '[]');
            $proc_labels_arr = json_decode($proc_labels_raw, true) ?: [];
            $pdo->prepare("DELETE FROM maker_proc_label_map WHERE maker_id_no=?")->execute([$mid]);
            if (!empty($proc_labels_arr)) {
                $ins_pl = $pdo->prepare("INSERT INTO maker_proc_label_map (maker_id_no,proc_label_id,parent_map_id,value_min,value_max,text_value) VALUES (?,?,?,?,?,?)");
                $tmpIdMap = []; // tmp_id → inserted map_id
                // Pass 1: insert rows without parent (parent_tmp_id empty/null)
                foreach ($proc_labels_arr as $pl) {
                    $ptmpid = isset($pl['parent_tmp_id']) && $pl['parent_tmp_id'] !== '' && $pl['parent_tmp_id'] !== null ? $pl['parent_tmp_id'] : null;
                    if ($ptmpid !== null) continue;
                    $plid = intval($pl['proc_label_id'] ?? 0); if (!$plid) continue;
                    $pmin = isset($pl['value_min'])   && $pl['value_min']!==''   ? floatval($pl['value_min'])   : null;
                    $pmax = isset($pl['value_max'])   && $pl['value_max']!==''   ? floatval($pl['value_max'])   : null;
                    $ptxt = isset($pl['input_value']) && $pl['input_value']!=='' ? trim($pl['input_value'])    : null;
                    $ins_pl->execute([$mid, $plid, null, $pmin, $pmax, $ptxt]);
                    $newMapId = (int)$pdo->lastInsertId();
                    $tid = $pl['tmp_id'] ?? null; if ($tid) $tmpIdMap[$tid] = $newMapId;
                }
                // Pass 2: insert sub-label rows
                foreach ($proc_labels_arr as $pl) {
                    $ptmpid = isset($pl['parent_tmp_id']) && $pl['parent_tmp_id'] !== '' && $pl['parent_tmp_id'] !== null ? $pl['parent_tmp_id'] : null;
                    if ($ptmpid === null) continue;
                    $plid = intval($pl['proc_label_id'] ?? 0); if (!$plid) continue;
                    $parentMapId = isset($tmpIdMap[$ptmpid]) ? $tmpIdMap[$ptmpid] : null;
                    $pmin = isset($pl['value_min'])   && $pl['value_min']!==''   ? floatval($pl['value_min'])   : null;
                    $pmax = isset($pl['value_max'])   && $pl['value_max']!==''   ? floatval($pl['value_max'])   : null;
                    $ptxt = isset($pl['input_value']) && $pl['input_value']!=='' ? trim($pl['input_value'])    : null;
                    $ins_pl->execute([$mid, $plid, $parentMapId, $pmin, $pmax, $ptxt]);
                }
            }

            // 同步廠商大類製程標籤
            $mcat_tags_raw = trim($_POST['main_cat_process_tags'] ?? '[]');
            $mcat_tags_arr = json_decode($mcat_tags_raw, true) ?: [];
            $pdo->prepare("DELETE FROM maker_main_cat_process_tag WHERE maker_id_no=?")->execute([$mid]);
            if (!empty($mcat_tags_arr)) {
                $ins_mct = $pdo->prepare("INSERT IGNORE INTO maker_main_cat_process_tag (maker_id_no, main_cat_id, ref_type, ref_id) VALUES (?,?,?,?)");
                foreach ($mcat_tags_arr as $t) {
                    $mcid  = intval($t['main_cat_id'] ?? 0);
                    $rtype = in_array($t['ref_type']??'', ['type','no']) ? $t['ref_type'] : null;
                    $rid   = intval($t['ref_id'] ?? 0);
                    if (!$mcid || !$rtype || !$rid) continue;
                    $ins_mct->execute([$mid, $mcid, $rtype, $rid]);
                }
            }

            // 廠商聯絡人 Delete-then-Insert
            $maker_contacts_raw = trim($_POST['maker_contacts'] ?? '[]');
            $maker_contacts_arr = json_decode($maker_contacts_raw, true) ?: [];
            $pdo->prepare("DELETE FROM maker_contacts WHERE maker_id_no=?")->execute([$mid]);
            if (!empty($maker_contacts_arr)) {
                $ins_mc = $pdo->prepare("INSERT INTO maker_contacts (maker_id_no,name,department,title,phone_ext,mobile,email,note,is_primary,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)");
                foreach (array_values($maker_contacts_arr) as $k => $mc) {
                    if (empty(trim($mc['name']??''))) continue;
                    $ins_mc->execute([$mid,trim($mc['name']??''),trim($mc['department']??''),trim($mc['title']??''),trim($mc['phone_ext']??''),trim($mc['mobile']??''),trim($mc['email']??''),trim($mc['note']??''),intval($mc['is_primary']??0),$k]);
                }
                // 同步主要聯絡人到 maker_list 欄位（供其他頁面直接查詢）
                $primaryMc = null;
                foreach ($maker_contacts_arr as $mc) { if (intval($mc['is_primary']??0)) { $primaryMc = $mc; break; } }
                if (!$primaryMc) $primaryMc = $maker_contacts_arr[0] ?? null;
                if ($primaryMc) {
                    $pdo->prepare("UPDATE maker_list SET contact_person=?,contact_title=?,email=? WHERE maker_id_no=?")
                        ->execute([trim($primaryMc['name']??''),trim($primaryMc['title']??''),trim($primaryMc['email']??''),$mid]);
                }
            }

            $pdo->commit();
            // ── audit log ──
            $op_name = _get_operator($pdo, $uid);
            if ($is_new) {
                _log_audit($pdo,'insert','vendor',$mid,$maker_id,null,$uid,$op_name);
            } else {
                $new_maker_arr = ['maker_id'=>$maker_id,'maker_id_all'=>$maker_all,'m_tel'=>$m_tel,'m_tel2'=>$m_tel2,'m_fax'=>$m_fax,'m_category'=>$m_category,'status'=>$status,'invoice_address'=>$invoice_address,'factory_address'=>$factory_address,'m_note'=>$m_note,'m_process_items'=>$m_process_items,'limit_dia'=>$limit_dia,'limit_len'=>$limit_len,'internal'=>$internal,'is_qualified'=>$is_qualified,'settlement_mode'=>$m_settlement_mode,'settlement_day'=>(string)$m_settlement_day,'payment_method'=>$m_payment_method,'net_days'=>(string)$m_net_days];
                $ch = _diff_rows($old_maker_row, $new_maker_arr, array_keys($new_maker_arr));
                if (!empty($ch)) _log_audit($pdo,'update','vendor',$mid,$maker_id,$ch,$uid,$op_name);
            }
            echo json_encode(['success'=>true,'message'=>$is_new ? '新增成功' : '修改成功']);

        } catch (Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 料號刪除前阻擋預查 ──────────────────────────────────────────────────────
    if ($_POST['action'] === 'check_part_blocks') {
        try {
            $d_id = intval($_POST['d_id']);
            $prow = $pdo->prepare("SELECT d.d_id, d.D_Setting_Id, d.Customer_Id, COALESCE(c.customer,'') AS customer_name FROM d_setting d LEFT JOIN customer_list c ON c.customer_id=d.Customer_Id WHERE d.d_id=?");
            $prow->execute([$d_id]);
            $part = $prow->fetch(PDO::FETCH_ASSOC);
            if (!$part) throw new Exception('找不到料號');
            $blocks = []; $counts = [];
            $chk = $pdo->prepare("SELECT COUNT(*) FROM order_track WHERE d_id_ID=?"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="訂單 {$n} 筆";$counts['orders']=$n;}
            $chk = $pdo->prepare("SELECT COUNT(*) FROM bom WHERE d_setting_id=?"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="生產批次(BOM) {$n} 筆";$counts['bom']=$n;}
            $chk = $pdo->prepare("SELECT COUNT(*) FROM d_setting_bom WHERE parent_d_id=? OR child_d_id=?"); $chk->execute([$d_id,$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="BOM組合件關聯 {$n} 筆";$counts['bom_struct']=$n;}
            $chk = $pdo->prepare("SELECT COUNT(*) FROM is_list WHERE d_setting_id=?"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="出貨單 {$n} 筆";$counts['is_list']=$n;}
            $chk = $pdo->prepare("SELECT COUNT(*) FROM stock_items WHERE d_id=? AND is_active=1"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="庫存紀錄 {$n} 筆";$counts['stock']=$n;}
            $chk = $pdo->prepare("SELECT COUNT(*) FROM quotation_item WHERE d_setting_d_id=?"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="報價單 {$n} 筆";$counts['quotation']=$n;}
            $chk = $pdo->prepare("SELECT COUNT(*) FROM ir_track WHERE d_setting_id=?"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="退貨單 {$n} 筆";$counts['ir']=$n;}
            // 圖面變更紀錄（AS 2-PD-01-07）：見 delete_part 內同一段註解。表可能尚未建立，故包 try。
            try { $chk = $pdo->prepare("SELECT COUNT(*) FROM qc_drawing_change WHERE d_id=?"); $chk->execute([$d_id]); $n=(int)$chk->fetchColumn(); if($n){$blocks[]="圖面變更紀錄 {$n} 筆";$counts['dwg_change']=$n;} } catch (Exception $qe) {}
            echo json_encode(['success'=>true,'blocks'=>$blocks,'counts'=>$counts,'part'=>$part]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 客戶刪除前阻擋預查 ──────────────────────────────────────────────────────
    if ($_POST['action'] === 'check_customer_blocks') {
        try {
            $cid = trim($_POST['customer_id']);
            $crow = $pdo->prepare("SELECT customer_id, customer FROM customer_list WHERE customer_id=?");
            $crow->execute([$cid]);
            $cust = $crow->fetch(PDO::FETCH_ASSOC);
            if (!$cust) throw new Exception('找不到客戶');
            $blocks = [];
            $chk = $pdo->prepare("SELECT COUNT(*) FROM d_setting WHERE Customer_Id=?"); $chk->execute([$cid]); $n=(int)$chk->fetchColumn(); if($n) $blocks[]="料號關聯 {$n} 筆（建議改為停用）";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM order_track WHERE Client_name_ID=?"); $chk->execute([$cid]); $n=(int)$chk->fetchColumn(); if($n) $blocks[]="訂單 {$n} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM is_list WHERE Client_id=?"); $chk->execute([$cid]); $n=(int)$chk->fetchColumn(); if($n) $blocks[]="出貨單 {$n} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM quotation_list WHERE client_id=?"); $chk->execute([$cid]); $n=(int)$chk->fetchColumn(); if($n) $blocks[]="報價單 {$n} 筆";
            $chk = $pdo->prepare("SELECT COUNT(*) FROM stock_items WHERE client_id=? AND is_active=1"); $chk->execute([$cid]); $n=(int)$chk->fetchColumn(); if($n) $blocks[]="庫存紀錄 {$n} 筆";
            echo json_encode(['success'=>true,'blocks'=>$blocks,'customer'=>$cust]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 客戶移轉綁定：取得客戶詳細資訊＋各資料表綁定數量 ─────────────────────
    if ($_POST['action'] === 'get_customer_transfer_info') {
        try {
            $cid = trim($_POST['customer_id'] ?? '');
            $kw  = trim($_POST['kw'] ?? '');
            if ($cid !== '') {
                $stmt = $pdo->prepare("SELECT customer_id, customer, tax_id FROM customer_list WHERE customer_id=? LIMIT 1");
                $stmt->execute([$cid]); $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            } elseif ($kw !== '') {
                $stmt = $pdo->prepare("SELECT customer_id, customer, tax_id FROM customer_list WHERE (customer_id LIKE ? OR customer LIKE ?) AND is_inactive=0 ORDER BY customer_id LIMIT 10");
                $stmt->execute(["%$kw%","%$kw%"]); $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            } else { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            foreach ($rows as &$row) {
                $id=$row['customer_id']; $cs=[];
                $q=$pdo->prepare("SELECT COUNT(*) FROM d_setting WHERE Customer_Id=?"); $q->execute([$id]); $n=(int)$q->fetchColumn(); if($n) $cs[]="料號{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM order_track WHERE Client_name_ID=?"); $q->execute([$id]); $n=(int)$q->fetchColumn(); if($n) $cs[]="訂單{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM is_list WHERE Client_id=?"); $q->execute([$id]); $n=(int)$q->fetchColumn(); if($n) $cs[]="出貨{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM quotation_list WHERE client_id=?"); $q->execute([$id]); $n=(int)$q->fetchColumn(); if($n) $cs[]="報價{$n}筆";
                $row['bound_counts'] = implode('、', $cs) ?: '無綁定';
            }; unset($row);
            echo json_encode(['success'=>true,'data'=>$cid!==''?($rows[0]??null):$rows]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 客戶綁定移轉（不可逆，需 A 或 CDRU 權限）────────────────────────────
    if ($_POST['action'] === 'transfer_customer_binding') {
        try {
            if (!$can_delete_all) throw new Exception('無移轉綁定權限（需要 A 或 CDRU 權限）');
            $src_id = trim($_POST['src_customer_id']);
            $tgt_id = trim($_POST['tgt_customer_id']);
            if ($src_id==='' || $tgt_id==='') throw new Exception('客戶代碼不可為空');
            if ($src_id===$tgt_id) throw new Exception('來源與目標客戶不可相同');
            $src_q=$pdo->prepare("SELECT customer_id,customer FROM customer_list WHERE customer_id=?"); $src_q->execute([$src_id]); $src=$src_q->fetch(PDO::FETCH_ASSOC);
            $tgt_q=$pdo->prepare("SELECT customer_id,customer FROM customer_list WHERE customer_id=?"); $tgt_q->execute([$tgt_id]); $tgt=$tgt_q->fetch(PDO::FETCH_ASSOC);
            if (!$src) throw new Exception('找不到來源客戶');
            if (!$tgt) throw new Exception('找不到目標客戶');
            $pdo->beginTransaction();
            $pdo->prepare("UPDATE d_setting      SET Customer_Id=?    WHERE Customer_Id=?")->execute([$tgt_id,$src_id]);
            $pdo->prepare("UPDATE order_track    SET Client_name_ID=? WHERE Client_name_ID=?")->execute([$tgt_id,$src_id]);
            $pdo->prepare("UPDATE is_list        SET Client_id=?       WHERE Client_id=?")->execute([$tgt_id,$src_id]);
            $pdo->prepare("UPDATE quotation_list SET client_id=?       WHERE client_id=?")->execute([$tgt_id,$src_id]);
            // 記錄 alias，供歷史查詢追溯
            try { $pdo->prepare("INSERT INTO customer_aliases (old_id,new_id,created_by) VALUES (?,?,?)")->execute([$src_id,$tgt_id,$uid]); } catch(Exception $ae){}
            $pdo->commit();
            _log_audit($pdo,'update','customer',$src_id,$src['customer'],[['field'=>'綁定移轉','old'=>$src_id,'new'=>$tgt_id.'（所有關聯資料）']],$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true,'message'=>'移轉完成，所有關聯資料已改為指向「'.$tgt['customer'].'（'.$tgt_id.'）」']);
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 料號移轉綁定：取得料號詳細資訊＋各資料表綁定數量 ─────────────────────
    if ($_POST['action'] === 'get_part_transfer_info') {
        try {
            $d_id = intval($_POST['d_id'] ?? 0);
            $kw   = trim($_POST['kw'] ?? '');
            if ($d_id > 0) {
                $stmt = $pdo->prepare("SELECT d.d_id, d.D_Setting_Id, d.Customer_Id, COALESCE(c.customer,'') AS customer_name FROM d_setting d LEFT JOIN customer_list c ON c.customer_id=d.Customer_Id WHERE d.d_id=? LIMIT 1");
                $stmt->execute([$d_id]);
                $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            } elseif ($kw !== '') {
                $stmt = $pdo->prepare("SELECT d.d_id, d.D_Setting_Id, d.Customer_Id, COALESCE(c.customer,'') AS customer_name FROM d_setting d LEFT JOIN customer_list c ON c.customer_id=d.Customer_Id WHERE d.D_Setting_Id LIKE ? OR d.Spec_No LIKE ? OR d.Drawing_No LIKE ? ORDER BY d.D_Setting_Id LIMIT 10");
                $stmt->execute(["%$kw%","%$kw%","%$kw%"]);
                $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            } else { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            foreach ($rows as &$row) {
                $did = $row['d_id']; $cs = [];
                $q=$pdo->prepare("SELECT COUNT(*) FROM order_track WHERE d_id_ID=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $cs[]="訂單{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM bom WHERE d_setting_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $cs[]="生產{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM is_list WHERE d_setting_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $cs[]="出貨{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM quotation_item WHERE d_setting_d_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $cs[]="報價{$n}筆";
                $q=$pdo->prepare("SELECT COUNT(*) FROM ir_track WHERE d_setting_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $cs[]="退貨{$n}筆";
                try { $q=$pdo->prepare("SELECT COUNT(*) FROM qc_drawing_change WHERE d_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $cs[]="圖面變更{$n}筆"; } catch (Exception $qe) {}
                $row['bound_counts'] = implode('、', $cs) ?: '無綁定';
            }; unset($row);
            echo json_encode(['success'=>true,'data'=>$d_id>0?($rows[0]??null):$rows]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 料號綁定移轉（不可逆，需 A 或 CDRU 權限）────────────────────────────
    if ($_POST['action'] === 'transfer_part_binding') {
        try {
            if (!$can_delete_all) throw new Exception('無移轉綁定權限（需要 A 或 CDRU 權限）');
            $src_id = intval($_POST['src_d_id']);
            $tgt_id = intval($_POST['tgt_d_id']);
            if ($src_id <= 0 || $tgt_id <= 0) throw new Exception('料號 ID 不合法');
            if ($src_id === $tgt_id) throw new Exception('來源與目標料號不可相同');
            $src_q = $pdo->prepare("SELECT d_id, D_Setting_Id, Customer_Id FROM d_setting WHERE d_id=?"); $src_q->execute([$src_id]); $src = $src_q->fetch(PDO::FETCH_ASSOC);
            $tgt_q = $pdo->prepare("SELECT d_id, D_Setting_Id, Customer_Id FROM d_setting WHERE d_id=?"); $tgt_q->execute([$tgt_id]); $tgt = $tgt_q->fetch(PDO::FETCH_ASSOC);
            if (!$src) throw new Exception('找不到來源料號');
            if (!$tgt) throw new Exception('找不到目標料號');
            // 客戶隨料號（使用者政策 2026-07-15）：移轉料號時，一併把受影響單據（訂單/出貨/退貨/生產）的客戶欄
            // 改為目標料號所屬客戶；目標料號若未綁客戶(Customer_Id 空)則不動客戶欄。名稱用 COALESCE 保底，查不到名稱時保留原值。
            $tgt_cust_id = !empty($tgt['Customer_Id']) ? $tgt['Customer_Id'] : null;
            $tgt_cust_name = null;
            if ($tgt_cust_id !== null) {
                $cq = $pdo->prepare("SELECT customer FROM customer_list WHERE customer_id=? LIMIT 1");
                $cq->execute([$tgt_cust_id]);
                $tgt_cust_name = (($v = $cq->fetchColumn()) !== false && $v !== null) ? $v : null;
            }
            $sync_cust = ($tgt_cust_id !== null);
            $tds = $tgt['D_Setting_Id'];
            $pdo->beginTransaction();
            if ($sync_cust) {
                $pdo->prepare("UPDATE order_track SET d_id_ID=?, d_id=?, Client_name_ID=?, Client_name=COALESCE(?,Client_name) WHERE d_id_ID=?")->execute([$tgt_id,$tds,$tgt_cust_id,$tgt_cust_name,$src_id]);
                $pdo->prepare("UPDATE is_list     SET d_setting_id=?, Product_id=?, Client_id=?, Client_name=COALESCE(?,Client_name) WHERE d_setting_id=?")->execute([$tgt_id,$tds,$tgt_cust_id,$tgt_cust_name,$src_id]);
                $pdo->prepare("UPDATE ir_track     SET d_setting_id=?, d_id=?, Client_name=COALESCE(?,Client_name) WHERE d_setting_id=?")->execute([$tgt_id,$tds,$tgt_cust_name,$src_id]);
                $pdo->prepare("UPDATE bom          SET d_setting_id=?, d_id=?, Client_Name=COALESCE(?,Client_Name) WHERE d_setting_id=?")->execute([$tgt_id,$tds,$tgt_cust_name,$src_id]);
            } else {
                $pdo->prepare("UPDATE order_track SET d_id_ID=?, d_id=? WHERE d_id_ID=?")->execute([$tgt_id,$tds,$src_id]);
                $pdo->prepare("UPDATE is_list     SET d_setting_id=?, Product_id=? WHERE d_setting_id=?")->execute([$tgt_id,$tds,$src_id]);
                $pdo->prepare("UPDATE ir_track     SET d_setting_id=?, d_id=? WHERE d_setting_id=?")->execute([$tgt_id,$tds,$src_id]);
                $pdo->prepare("UPDATE bom          SET d_setting_id=?, d_id=? WHERE d_setting_id=?")->execute([$tgt_id,$tds,$src_id]);
            }
            $pdo->prepare("UPDATE d_setting_bom  SET parent_d_id=?            WHERE parent_d_id=?")->execute([$tgt_id,$src_id]);
            $pdo->prepare("UPDATE d_setting_bom  SET child_d_id=?             WHERE child_d_id=?")->execute([$tgt_id,$src_id]);
            $pdo->prepare("UPDATE stock_items    SET d_id=?                   WHERE d_id=?")->execute([$tgt_id,$src_id]);
            $pdo->prepare("UPDATE quotation_item SET d_setting_d_id=?, product_id=? WHERE d_setting_d_id=?")->execute([$tgt_id,$tds,$src_id]);
            // 圖面變更紀錄（AS 2-PD-01-07）改指向目標料號；表可能尚未建立，故包 try（缺表不影響其餘移轉）。
            // 註：qc_inspection_version（檢驗標準版本）刻意不自動搬——目標料號通常已有自己的生效版本，
            //     兩邊合併會出現兩個 is_active=1，屬品質決策，需人工到「檢驗標準管理」處理。
            try { $pdo->prepare("UPDATE qc_drawing_change SET d_id=? WHERE d_id=?")->execute([$tgt_id,$src_id]); } catch (Exception $qe) {}
            $pdo->commit();
            $op_name = _get_operator($pdo, $uid);
            $cust_note = $sync_cust ? ('，客戶一併改為「'.($tgt_cust_name ?: $tgt_cust_id).'」') : '';
            _log_audit($pdo,'update','part',$src['D_Setting_Id'],null,[['field'=>'綁定移轉','old'=>$src['D_Setting_Id'],'new'=>$tds.'（所有關聯資料'.$cust_note.'）']],$uid,$op_name);
            echo json_encode(['success'=>true,'message'=>'移轉完成，所有關聯資料已改為指向「'.$tds.'」'.$cust_note]);
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 廠商刪除前阻擋預查 ──────────────────────────────────────────────────────
    if ($_POST['action'] === 'check_maker_blocks') {
        try {
            $mid = trim($_POST['maker_id_no']);
            $mrow = $pdo->prepare("SELECT maker_id_no, maker_id FROM maker_list WHERE maker_id_no=?");
            $mrow->execute([$mid]); $maker = $mrow->fetch(PDO::FETCH_ASSOC);
            if (!$maker) throw new Exception('找不到廠商');
            $blocks = [];
            $q=$pdo->prepare("SELECT COUNT(*) FROM bom_ing WHERE maker_id_no=?"); $q->execute([$mid]); $n=(int)$q->fetchColumn(); if($n) $blocks[]="加工單 {$n} 筆";
            echo json_encode(['success'=>true,'blocks'=>$blocks,'maker'=>$maker]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 廠商移轉：取得廠商資訊＋綁定數量 ────────────────────────────────────
    if ($_POST['action'] === 'get_maker_transfer_info') {
        try {
            $mid = trim($_POST['maker_id_no'] ?? '');
            $kw  = trim($_POST['kw'] ?? '');
            if ($mid !== '') {
                $stmt = $pdo->prepare("SELECT maker_id_no, maker_id, maker_id_all FROM maker_list WHERE maker_id_no=? LIMIT 1");
                $stmt->execute([$mid]); $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            } elseif ($kw !== '') {
                $stmt = $pdo->prepare("SELECT maker_id_no, maker_id, maker_id_all FROM maker_list WHERE (maker_id_no LIKE ? OR maker_id LIKE ?) AND (status IS NULL OR status<>'X') ORDER BY maker_id_no LIMIT 10");
                $stmt->execute(["%$kw%","%$kw%"]); $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            } else { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            foreach ($rows as &$row) {
                $id=$row['maker_id_no']; $cs=[];
                $q=$pdo->prepare("SELECT COUNT(*) FROM bom_ing WHERE maker_id_no=?"); $q->execute([$id]); $n=(int)$q->fetchColumn(); if($n) $cs[]="加工單{$n}筆";
                $row['bound_counts'] = implode('、', $cs) ?: '無綁定';
            }; unset($row);
            echo json_encode(['success'=>true,'data'=>$mid!==''?($rows[0]??null):$rows]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 廠商綁定移轉（不可逆，需 A 或 CDRU 權限）────────────────────────────
    if ($_POST['action'] === 'transfer_maker_binding') {
        try {
            if (!$can_delete_all) throw new Exception('無移轉綁定權限（需要 A 或 CDRU 權限）');
            $src_id = trim($_POST['src_maker_id_no']);
            $tgt_id = trim($_POST['tgt_maker_id_no']);
            if ($src_id==='' || $tgt_id==='') throw new Exception('廠商編號不可為空');
            if ($src_id===$tgt_id) throw new Exception('來源與目標廠商不可相同');
            $src_q=$pdo->prepare("SELECT maker_id_no,maker_id FROM maker_list WHERE maker_id_no=?"); $src_q->execute([$src_id]); $src=$src_q->fetch(PDO::FETCH_ASSOC);
            $tgt_q=$pdo->prepare("SELECT maker_id_no,maker_id FROM maker_list WHERE maker_id_no=?"); $tgt_q->execute([$tgt_id]); $tgt=$tgt_q->fetch(PDO::FETCH_ASSOC);
            if (!$src) throw new Exception('找不到來源廠商');
            if (!$tgt) throw new Exception('找不到目標廠商');
            $pdo->beginTransaction();
            $pdo->prepare("UPDATE bom_ing SET maker_id_no=?, maker_id=? WHERE maker_id_no=?")->execute([$tgt_id,$tgt['maker_id'],$src_id]);
            // 記錄 alias，供歷史查詢追溯
            try { $pdo->prepare("INSERT INTO maker_aliases (old_id,new_id,created_by) VALUES (?,?,?)")->execute([$src_id,$tgt_id,$uid]); } catch(Exception $ae){}
            $pdo->commit();
            _log_audit($pdo,'update','vendor',$src_id,$src['maker_id'],[['field'=>'綁定移轉','old'=>$src_id,'new'=>$tgt_id.'（所有加工單）']],$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true,'message'=>'移轉完成，所有加工單已改為指向「'.$tgt['maker_id'].'（'.$tgt_id.'）」']);
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    if ($_POST['action'] === 'delete_maker') {
        try {
