            $mid = trim($_POST['maker_id_no']);
            $del_maker_q = $pdo->prepare("SELECT maker_id FROM maker_list WHERE maker_id_no=?"); $del_maker_q->execute([$mid]); $del_maker_name = $del_maker_q->fetchColumn();
            $blocks = [];
            $chk = $pdo->prepare("SELECT COUNT(*) FROM bom_ing WHERE maker_id_no=?");
            $chk->execute([$mid]); $cnt=(int)$chk->fetchColumn();
            if ($cnt>0) $blocks[] = "加工單(BOM製程) {$cnt} 筆";
            if (!empty($blocks)) throw new Exception('此廠商已有關聯資料，無法刪除（建議改為停用）：' . implode('、',$blocks));
            $pdo->prepare("DELETE FROM maker_list WHERE maker_id_no=?")->execute([$mid]);
            _log_audit($pdo,'delete','vendor',$mid,$del_maker_name,null,$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true,'message'=>'已刪除']);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
