            $sq = $pdo->prepare("SELECT is_inactive,customer FROM customer_list WHERE customer_id=?"); $sq->execute([$cid]); $sr = $sq->fetch(PDO::FETCH_ASSOC);
            $new_st = intval($sr['is_inactive']??0);
