            _log_audit($pdo,'delete','part',$ds_id??$d_setting_id,null,[['field'=>'齒型規格列','old'=>'gear_id='.$gear_id,'new'=>'']],$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
