                $chk->execute([$code]);
                $cnt = (int)$chk->fetchColumn();
                if ($cnt > 0) throw new Exception("此工件種類已有 {$cnt} 筆料號使用，無法刪除（請先修改那些料號的工件種類）");
                $del_wt = $pdo->prepare("SELECT type_name FROM dict_workpiece_type WHERE type_code=?"); $del_wt->execute([$code]); $del_wt_name = $del_wt->fetchColumn();
                $pdo->prepare("UPDATE dict_workpiece_type SET is_active=0 WHERE type_code=?")->execute([$code]);
                // 同時停用其小類
                $pdo->prepare("UPDATE dict_workpiece_sub_type SET is_active=0 WHERE type_code=?")->execute([$code]);
                _log_audit($pdo,'delete','dict','workpiece:'.$code,$del_wt_name?:$code,null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder') {
                if (!$can_dict_part) throw new Exception('無修改權限（需要 A、CDR 或 CDRU 權限）');
                $ids = array_filter(explode(',', $_POST['ids'] ?? ''));
                $upd = $pdo->prepare("UPDATE dict_workpiece_type SET sort_order=? WHERE type_code=?");
