                    $pdo->prepare("UPDATE dict_workpiece_sub_type SET sub_type_name=? WHERE sub_type_id=?")->execute([$name, $id]);
                    $ch=_diff_rows($old_wst_row??[],['sub_type_name'=>$name],['sub_type_name']); if(!empty($ch)) _log_audit($pdo,'update','dict','workpiece-sub:'.$id,$name,$ch,$uid,$op_name);
                } else {
