                    $max->execute([$type_code]);
                    $pdo->prepare("INSERT INTO dict_workpiece_sub_type (type_code, sub_type_name, sort_order) VALUES (?,?,?)")->execute([$type_code, $name, (int)$max->fetchColumn()]);
                    _log_audit($pdo,'insert','dict','workpiece-sub:new',$name,null,$uid,$op_name);
