                $del_wsn = $pdo->prepare("SELECT sub_type_name FROM dict_workpiece_sub_type WHERE sub_type_id=?"); $del_wsn->execute([$id]); $del_wsn = $del_wsn->fetchColumn();
                $pdo->prepare("UPDATE dict_workpiece_sub_type SET is_active=0 WHERE sub_type_id=?")->execute([$id]);
                _log_audit($pdo,'delete','dict','workpiece-sub:'.$id,$del_wsn?:('id:'.$id),null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder') {
