    if ($_POST['action'] === 'gear_spec_options') {
        $rows = $pdo->query(
            "SELECT DISTINCT module_display, Pressure_Angle FROM d_setting_gear
             WHERE module_display IS NOT NULL OR Pressure_Angle IS NOT NULL"
        )->fetchAll(PDO::FETCH_ASSOC);
        $modules   = array_values(array_unique(array_filter(array_column($rows, 'module_display'))));
        $pressures = array_values(array_unique(array_filter(array_column($rows, 'Pressure_Angle'))));
        usort($modules, function($a, $b) {
            $isMA = preg_match('/^M([\d.]+)$/i', $a, $mA);
            $isMB = preg_match('/^M([\d.]+)$/i', $b, $mB);
            if ($isMA && $isMB) return (float)$mA[1] <=> (float)$mB[1];
            if ($isMA) return -1;
            if ($isMB) return  1;
            return strcmp($a, $b);
        });
        sort($pressures);
