                if ($is_qty_dim_sv)     { $input_type = 'number'; $is_range_sv = 0; $has_tol_sv = 0; $has_draw_lathe = 0; $has_draw_lathe_depth_sv = 0; $is_dim_sv = 0; $is_imperial_dim_sv = 0; $is_countersink_sv = 0; $is_enum_sv = 0; $is_qty_triple_dim_sv = 0; }
                if ($is_qty_triple_dim_sv) { $input_type = 'number'; $is_range_sv = 0; $has_tol_sv = 0; $has_draw_lathe = 0; $has_draw_lathe_depth_sv = 0; $is_dim_sv = 0; $is_qty_dim_sv = 0; $is_imperial_dim_sv = 0; $is_countersink_sv = 0; $is_triple_dim_sv2 = 0; $is_enum_sv = 0; }
                if ($is_imperial_dim_sv){ $input_type = 'none';   $is_range_sv = 0; $has_tol_sv = 0; $has_draw_lathe = 0; $has_draw_lathe_depth_sv = 0; $is_dim_sv = 0; $is_qty_dim_sv = 0; $is_countersink_sv = 0; $is_enum_sv = 0; $is_qty_triple_dim_sv = 0; }
                if ($is_countersink_sv) { $input_type = 'none';   $is_range_sv = 0; $has_tol_sv = 0; $has_draw_lathe = 0; $has_draw_lathe_depth_sv = 0; $is_dim_sv = 0; $is_qty_dim_sv = 0; $is_imperial_dim_sv = 0; $is_enum_sv = 0; $is_qty_triple_dim_sv = 0; }
                if ($is_enum_sv)        { $input_type = 'none';   $is_range_sv = 0; $has_tol_sv = 0; $has_draw_lathe = 0; $has_draw_lathe_depth_sv = 0; $is_dim_sv = 0; $is_qty_dim_sv = 0; $is_imperial_dim_sv = 0; $is_countersink_sv = 0; $is_qty_triple_dim_sv = 0; }
                if (empty($sub_name))  throw new Exception('子標籤名稱不可為空');
                if (!$label_id)        throw new Exception('缺少父標籤ID');
                $uid = $_SESSION['user_id']??null; $op_name = _get_operator($pdo,$uid);
                if ($sub_id) {
                    $old_ls = $pdo->prepare("SELECT sub_name,input_type,is_repeatable,has_draw_lathe,is_range,has_tolerance,COALESCE(is_dimension,0) AS is_dimension,COALESCE(is_qty_dim,0) AS is_qty_dim,COALESCE(is_imperial_dim,0) AS is_imperial_dim,COALESCE(is_countersink,0) AS is_countersink,COALESCE(has_draw_lathe_depth,0) AS has_draw_lathe_depth,COALESCE(is_enum,0) AS is_enum,COALESCE(hide_name_in_display,0) AS hide_name_in_display,COALESCE(prefix_char,'') AS prefix_char,COALESCE(suffix_char,'') AS suffix_char FROM dict_label_sub WHERE sub_id=?"); $old_ls->execute([$sub_id]); $old_ls_row = $old_ls->fetch(PDO::FETCH_ASSOC);
                    $pdo->prepare("UPDATE dict_label_sub SET sub_name=?, input_type=?, is_repeatable=?, has_draw_lathe=?, is_range=?, has_tolerance=?, is_dimension=?, is_qty_dim=?, is_qty_triple_dim=?, is_imperial_dim=?, is_countersink=?, has_draw_lathe_depth=?, is_triple_dim=?, is_enum=?, hide_name_in_display=?, prefix_char=?, suffix_char=? WHERE sub_id=?")
                        ->execute([$sub_name, $input_type, $is_rep, $has_draw_lathe, $is_range_sv, $has_tol_sv, $is_dim_sv, $is_qty_dim_sv, $is_qty_triple_dim_sv, $is_imperial_dim_sv, $is_countersink_sv, $has_draw_lathe_depth_sv, $is_triple_dim_sv2, $is_enum_sv, $hide_name_sv, $prefix_char_sv ?: null, $suffix_char_sv ?: null, $sub_id]);
                    $ch=_diff_rows($old_ls_row??[],['sub_name'=>$sub_name,'input_type'=>$input_type,'is_repeatable'=>(string)$is_rep,'has_draw_lathe'=>(string)$has_draw_lathe,'is_range'=>(string)$is_range_sv,'has_tolerance'=>(string)$has_tol_sv,'is_dimension'=>(string)$is_dim_sv,'is_qty_dim'=>(string)$is_qty_dim_sv,'is_imperial_dim'=>(string)$is_imperial_dim_sv,'is_countersink'=>(string)$is_countersink_sv,'is_enum'=>(string)$is_enum_sv,'hide_name_in_display'=>(string)$hide_name_sv,'prefix_char'=>$prefix_char_sv,'suffix_char'=>$suffix_char_sv],array_keys($old_ls_row??[])); if(!empty($ch)) _log_audit($pdo,'update','dict','label-sub:'.$sub_id,$sub_name,$ch,$uid,$op_name);
                } else {
                    $max = $pdo->prepare("SELECT COALESCE(MAX(sort_order),0)+1 FROM dict_label_sub WHERE label_id=?");
                    $max->execute([$label_id]);
                    $pdo->prepare("INSERT INTO dict_label_sub (label_id, sub_name, input_type, is_repeatable, has_draw_lathe, is_range, has_tolerance, is_dimension, is_qty_dim, is_qty_triple_dim, is_imperial_dim, is_countersink, has_draw_lathe_depth, is_triple_dim, is_enum, hide_name_in_display, prefix_char, suffix_char, sort_order) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")
                        ->execute([$label_id, $sub_name, $input_type, $is_rep, $has_draw_lathe, $is_range_sv, $has_tol_sv, $is_dim_sv, $is_qty_dim_sv, $is_qty_triple_dim_sv, $is_imperial_dim_sv, $is_countersink_sv, $has_draw_lathe_depth_sv, $is_triple_dim_sv2, $is_enum_sv, $hide_name_sv, $prefix_char_sv ?: null, $suffix_char_sv ?: null, (int)$max->fetchColumn()]);
                    _log_audit($pdo,'insert','dict','label-sub:new',$sub_name,null,$uid,$op_name);
                }
                echo json_encode(['success'=>true]);
            } elseif ($op === 'delete_sub') {
                if (!$can_dict_part) throw new Exception('無刪除權限（需要 A、CDR 或 CDRU 權限）');
                $sub_id = intval($_POST['sub_id'] ?? 0);
                $chk = $pdo->prepare("SELECT COUNT(*) FROM item_sub_label_map WHERE sub_id=?");
                $chk->execute([$sub_id]);
                $cnt = (int)$chk->fetchColumn();
                if ($cnt > 0) throw new Exception("此子標籤已有 {$cnt} 筆料號使用，無法刪除");
                $del_ls = $pdo->prepare("SELECT sub_name FROM dict_label_sub WHERE sub_id=?"); $del_ls->execute([$sub_id]); $del_ls_name = $del_ls->fetchColumn();
                $pdo->prepare("UPDATE dict_label_sub SET is_active=0 WHERE sub_id=?")->execute([$sub_id]);
                _log_audit($pdo,'delete','dict','label-sub:'.$sub_id,$del_ls_name?:('id:'.$sub_id),null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder_subs') {
                if (!$can_dict_part) throw new Exception('無修改權限（需要 A、CDR 或 CDRU 權限）');
                $ids = array_filter(array_map('intval', explode(',', $_POST['ids']??'')));
                $upd = $pdo->prepare("UPDATE dict_label_sub SET sort_order=? WHERE sub_id=?");
                foreach (array_values($ids) as $k => $id) { $upd->execute([$k, $id]); }
                echo json_encode(['success'=>true]);
            }
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 3. 產業別
    if ($_POST['action'] === 'manage_industries') {
        try {
            $op = $_POST['op'];
            if ($op === 'list') {
                $rows = $pdo->query("SELECT industry_id, industry_name, note, is_active FROM dict_industry_type WHERE is_active=1 ORDER BY sort_order, industry_id")->fetchAll(PDO::FETCH_ASSOC);
                foreach ($rows as &$row) {
                    $sq = $pdo->prepare("SELECT sub_id, sub_name, sort_order FROM dict_industry_sub_type WHERE industry_id=? AND is_active=1 ORDER BY sort_order, sub_id");
                    $sq->execute([$row['industry_id']]);
                    $row['sub_types'] = $sq->fetchAll(PDO::FETCH_ASSOC);
                }
                unset($row);
                echo json_encode(['success'=>true, 'data'=>$rows]);
            } elseif ($op === 'save') {
                if (!$can_dict_edit) throw new Exception('無權限（需要 A 或 CRUD 權限）');
                $id   = intval($_POST['industry_id'] ?? 0);
                $name = trim($_POST['industry_name'] ?? '');
                $note = trim($_POST['industry_note'] ?? '');
                if (empty($name)) throw new Exception('產業別名稱不可為空');
                $uid = $_SESSION['user_id']??null; $op_name = _get_operator($pdo,$uid);
                if ($id) {
                    $old_ind = $pdo->prepare("SELECT industry_name,note FROM dict_industry_type WHERE industry_id=?"); $old_ind->execute([$id]); $old_ind_row = $old_ind->fetch(PDO::FETCH_ASSOC);
                    $pdo->prepare("UPDATE dict_industry_type SET industry_name=?,note=? WHERE industry_id=?")->execute([$name,$note,$id]);
                    $ch=_diff_rows($old_ind_row??[],['industry_name'=>$name,'note'=>$note],['industry_name','note']); if(!empty($ch)) _log_audit($pdo,'update','dict','industry:'.$id,$name,$ch,$uid,$op_name);
                } else {
                    $pdo->prepare("INSERT INTO dict_industry_type (industry_name,note) VALUES (?,?)")->execute([$name,$note]);
                    $id = (int)$pdo->lastInsertId();
                    _log_audit($pdo,'insert','dict','industry:'.$id,$name,null,$uid,$op_name);
                }
                echo json_encode(['success'=>true,'industry_id'=>$id]);
            } elseif ($op === 'check_delete') {
                $id = intval($_POST['id'] ?? 0);
                $chk = $pdo->prepare("SELECT COUNT(*) FROM customer_industry_mapping WHERE industry_id=?"); $chk->execute([$id]);
                $cnt = (int)$chk->fetchColumn();
                echo json_encode($cnt > 0 ? ['can_delete'=>false,'reason'=>'此產業別已有客戶使用，無法刪除'] : ['can_delete'=>true]);
            } elseif ($op === 'delete') {
                if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
                $id = intval($_POST['id'] ?? 0);
                $chk = $pdo->prepare("SELECT COUNT(*) FROM customer_industry_mapping WHERE industry_id=?");
                $chk->execute([$id]);
                if ($chk->fetchColumn() > 0) throw new Exception('此產業別已有客戶使用，無法刪除');
                $del_ind = $pdo->prepare("SELECT industry_name FROM dict_industry_type WHERE industry_id=?"); $del_ind->execute([$id]); $del_ind_name = $del_ind->fetchColumn();
                $pdo->prepare("UPDATE dict_industry_type SET is_active=0 WHERE industry_id=?")->execute([$id]);
                _log_audit($pdo,'delete','dict','industry:'.$id,$del_ind_name?:('id:'.$id),null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder') {
                if (!$can_update) throw new Exception('無修改權限');
                $ids = array_filter(array_map('intval', explode(',', $_POST['ids']??'')));
                $upd = $pdo->prepare("UPDATE dict_industry_type SET sort_order=? WHERE industry_id=?");
                foreach (array_values($ids) as $k => $id) { $upd->execute([$k, $id]); }
                echo json_encode(['success'=>true]);
            }
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 4. 廠商大類 (含小類綁定 + 排序)
    if ($_POST['action'] === 'manage_maker_main_cats') {
        try {
            $pdo->exec("SET SESSION lock_wait_timeout = 5");
            $op = $_POST['op'];
            if ($op === 'list') {
                // 每個大類同時帶出已綁定的小類清單
                $rows = $pdo->query("SELECT main_cat_id, main_cat_name, is_active, sort_order FROM dict_maker_main_category WHERE is_active=1 ORDER BY sort_order, main_cat_id")->fetchAll(PDO::FETCH_ASSOC);
                foreach ($rows as &$row) {
                    $sb = $pdo->prepare("SELECT s.sub_cat_id, s.sub_cat_name, s.sub_cat_group, h.sort_order AS bind_order
                        FROM maker_category_hierarchy h
                        JOIN dict_maker_sub_category s ON s.sub_cat_id=h.sub_cat_id
                        WHERE h.main_cat_id=? AND s.is_active=1
                        ORDER BY h.sort_order, s.sub_cat_id");
                    $sb->execute([$row['main_cat_id']]);
                    $row['sub_cats'] = $sb->fetchAll(PDO::FETCH_ASSOC);
                }
                unset($row);
                echo json_encode(['success'=>true, 'data'=>$rows]);
            } elseif ($op === 'save') {
                if (!$can_dict_edit) throw new Exception('無權限（需要 A 或 CRUD 權限）');
                $id = intval($_POST['main_cat_id'] ?? 0);
                $name = trim($_POST['main_cat_name'] ?? '');
                if (empty($name)) throw new Exception('大類名稱不可為空');
                $dup = $pdo->prepare("SELECT COUNT(*) FROM dict_maker_main_category WHERE LOWER(main_cat_name)=LOWER(?) AND is_active=1 AND main_cat_id<>?");
                $dup->execute([$name, $id]);
                if ((int)$dup->fetchColumn() > 0) throw new Exception("已存在相同名稱「{$name}」的廠商大類");
                $uid = $_SESSION['user_id']??null; $op_name = _get_operator($pdo,$uid);
                if ($id) {
                    $old_mc = $pdo->prepare("SELECT main_cat_name FROM dict_maker_main_category WHERE main_cat_id=?"); $old_mc->execute([$id]); $old_mc_row = $old_mc->fetch(PDO::FETCH_ASSOC);
                    $pdo->prepare("UPDATE dict_maker_main_category SET main_cat_name=? WHERE main_cat_id=?")->execute([$name, $id]);
                    $ch=_diff_rows($old_mc_row??[],['main_cat_name'=>$name],['main_cat_name']); if(!empty($ch)) _log_audit($pdo,'update','dict','maker-main:'.$id,$name,$ch,$uid,$op_name);
                } else {
                    $max = $pdo->query("SELECT COALESCE(MAX(sort_order),0)+1 FROM dict_maker_main_category")->fetchColumn();
                    $pdo->prepare("INSERT INTO dict_maker_main_category (main_cat_name, sort_order) VALUES (?,?)")->execute([$name, $max]);
                    $id = (int)$pdo->lastInsertId();
                    _log_audit($pdo,'insert','dict','maker-main:'.$id,$name,null,$uid,$op_name);
                }
                // 更新此大類的小類綁定
                $sub_ids_raw = trim($_POST['sub_cat_ids'] ?? '');
                $sub_ids = array_values(array_filter(array_map('intval', explode(',', $sub_ids_raw))));
                $pdo->prepare("DELETE FROM maker_category_hierarchy WHERE main_cat_id=?")->execute([$id]);
                if (!empty($sub_ids)) {
                    $ins = $pdo->prepare("INSERT IGNORE INTO maker_category_hierarchy (main_cat_id, sub_cat_id, sort_order) VALUES (?,?,?)");
                    foreach ($sub_ids as $k => $sid) { $ins->execute([$id, $sid, $k]); }
                }
                echo json_encode(['success'=>true, 'main_cat_id'=>$id]);
            } elseif ($op === 'check_delete') {
                echo json_encode(['can_delete'=>true]);
            } elseif ($op === 'delete') {
                if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
                $id = intval($_POST['id'] ?? 0);
                $del_mc = $pdo->prepare("SELECT main_cat_name FROM dict_maker_main_category WHERE main_cat_id=?"); $del_mc->execute([$id]); $del_mc_name = $del_mc->fetchColumn();
                $pdo->prepare("DELETE FROM maker_category_hierarchy WHERE main_cat_id=?")->execute([$id]);
                $pdo->prepare("UPDATE dict_maker_main_category SET is_active=0 WHERE main_cat_id=?")->execute([$id]);
                _log_audit($pdo,'delete','dict','maker-main:'.$id,$del_mc_name?:('id:'.$id),null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder') {
                // ids = comma-separated new order of main_cat_id
                if (!$can_update) throw new Exception('無修改權限');
                $ids = array_filter(array_map('intval', explode(',', $_POST['ids']??'')));
                $upd = $pdo->prepare("UPDATE dict_maker_main_category SET sort_order=? WHERE main_cat_id=?");
                foreach (array_values($ids) as $k => $mid) { $upd->execute([$k, $mid]); }
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder_sub') {
                // Reorder sub bindings within a main cat
                if (!$can_update) throw new Exception('無修改權限');
                $main_id = intval($_POST['main_cat_id']??0);
                $ids = array_filter(array_map('intval', explode(',', $_POST['ids']??'')));
                $upd = $pdo->prepare("UPDATE maker_category_hierarchy SET sort_order=? WHERE main_cat_id=? AND sub_cat_id=?");
                foreach (array_values($ids) as $k => $sid) { $upd->execute([$k, $main_id, $sid]); }
                echo json_encode(['success'=>true]);
            }
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 5. 廠商小類 (含 sub_cat_group, ref_process_type_id, reorder, 關鍵字搜尋)
    //    dict_maker_sub_category: 小類主檔
    //    maker_category_hierarchy: 大類←→小類關聯 (sort_order 支援拖曳排序)
    if ($_POST['action'] === 'manage_maker_sub_cats') {
        try {
            $pdo->exec("SET SESSION lock_wait_timeout = 5");
            $op = $_POST['op'];
            if ($op === 'list') {
                $kw = trim($_POST['keyword'] ?? '');
                $grp = trim($_POST['sub_cat_group'] ?? '');
                $where = 's.is_active=1';
                $params = [];
                if ($kw !== '') { $where .= ' AND s.sub_cat_name LIKE ?'; $params[] = "%$kw%"; }
                if ($grp !== '') { $where .= ' AND s.sub_cat_group=?'; $params[] = $grp; }
                $sql = "SELECT s.sub_cat_id, s.sub_cat_name, s.sub_cat_group, s.ref_process_type_id, s.sort_order, s.is_active,
                               GROUP_CONCAT(m.main_cat_name ORDER BY m.main_cat_name SEPARATOR ', ') AS main_cat_names,
                               GROUP_CONCAT(CAST(h.main_cat_id AS CHAR) ORDER BY m.main_cat_name) AS main_cat_ids
                        FROM dict_maker_sub_category s
                        LEFT JOIN maker_category_hierarchy h ON s.sub_cat_id = h.sub_cat_id
                        LEFT JOIN dict_maker_main_category m ON h.main_cat_id = m.main_cat_id AND m.is_active=1
                        WHERE $where
                        GROUP BY s.sub_cat_id, s.sub_cat_name, s.sub_cat_group, s.ref_process_type_id, s.sort_order, s.is_active
                        ORDER BY s.sort_order, s.sub_cat_id";
                $stmt = $pdo->prepare($sql);
                $stmt->execute($params);
                echo json_encode(['success'=>true, 'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
            } elseif ($op === 'save') {
                if (!$can_dict_edit) throw new Exception('無權限（需要 A 或 CRUD 權限）');
                $id       = intval($_POST['sub_cat_id'] ?? 0);
                $name     = trim($_POST['sub_cat_name'] ?? '');
                $group    = trim($_POST['sub_cat_group'] ?? 'PROCESS');
                $ref_pt   = trim($_POST['ref_process_type_id'] ?? '') !== '' ? intval($_POST['ref_process_type_id']) : null;
                // 同步自製程類別的項目（ref_process_type_id 有值）：禁止修改名稱與群組，僅允許更新綁定大類
                if ($id && $ref_pt !== null) {
                    $orig = $pdo->prepare("SELECT sub_cat_name, sub_cat_group, ref_process_type_id FROM dict_maker_sub_category WHERE sub_cat_id=?");
                    $orig->execute([$id]);
                    $origRow = $orig->fetch(PDO::FETCH_ASSOC);
                    if ($origRow && $origRow['ref_process_type_id']) {
                        $name  = $origRow['sub_cat_name'];   // 鎖定名稱
                        $group = $origRow['sub_cat_group'];  // 鎖定群組
                        $ref_pt = $origRow['ref_process_type_id'];
                    }
                }
                $main_ids_raw = trim($_POST['main_cat_ids'] ?? '');
                $main_ids = array_values(array_filter(array_map('intval', explode(',', $main_ids_raw))));
                if (empty($name)) throw new Exception('小類名稱不可為空');
                // Duplicate check (skip sync items with ref_process_type_id)
                if (!$ref_pt) {
                    $dup2 = $pdo->prepare("SELECT COUNT(*) FROM dict_maker_sub_category WHERE LOWER(sub_cat_name)=LOWER(?) AND is_active=1 AND sub_cat_id<>?");
                    $dup2->execute([$name, $id]);
                    if ((int)$dup2->fetchColumn() > 0) throw new Exception("已存在相同名稱「{$name}」的廠商小類");
                }
                $uid = $_SESSION['user_id']??null; $op_name = _get_operator($pdo,$uid);
                $pdo->beginTransaction();
                if ($id) {
                    $old_sc = $pdo->prepare("SELECT sub_cat_name,sub_cat_group FROM dict_maker_sub_category WHERE sub_cat_id=?"); $old_sc->execute([$id]); $old_sc_row = $old_sc->fetch(PDO::FETCH_ASSOC);
                    $pdo->prepare("UPDATE dict_maker_sub_category SET sub_cat_name=?,sub_cat_group=?,ref_process_type_id=? WHERE sub_cat_id=?")
                        ->execute([$name,$group,$ref_pt,$id]);
                    $ch=_diff_rows($old_sc_row??[],['sub_cat_name'=>$name,'sub_cat_group'=>$group],['sub_cat_name','sub_cat_group']); if(!empty($ch)) _log_audit($pdo,'update','dict','maker-sub:'.$id,$name,$ch,$uid,$op_name);
                } else {
                    $max = $pdo->query("SELECT COALESCE(MAX(sort_order),0)+1 FROM dict_maker_sub_category")->fetchColumn();
                    $pdo->prepare("INSERT INTO dict_maker_sub_category (sub_cat_name,sub_cat_group,ref_process_type_id,sort_order) VALUES (?,?,?,?)")
                        ->execute([$name,$group,$ref_pt,$max]);
                    $id = (int)$pdo->lastInsertId();
                    _log_audit($pdo,'insert','dict','maker-sub:'.$id,$name,null,$uid,$op_name);
                }
                $pdo->prepare("DELETE FROM maker_category_hierarchy WHERE sub_cat_id=?")->execute([$id]);
                if (!empty($main_ids)) {
                    $ins = $pdo->prepare("INSERT IGNORE INTO maker_category_hierarchy (main_cat_id, sub_cat_id, sort_order) VALUES (?,?,0)");
                    foreach ($main_ids as $mid) { $ins->execute([$mid, $id]); }
                }
                $pdo->commit();
                echo json_encode(['success'=>true]);
            } elseif ($op === 'check_delete') {
                echo json_encode(['can_delete'=>true]);
            } elseif ($op === 'delete') {
                if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
                $id = intval($_POST['id'] ?? 0);
                // 禁止實體刪除：改用 is_active=0 以維護 AI 數據完整性
                // 先檢查是否有廠商綁定
                try {
                    $chk = $pdo->prepare("SELECT COUNT(*) FROM maker_sub_category_mapping WHERE sub_cat_id=?");
                    $chk->execute([$id]);
                    $mapped = (int)$chk->fetchColumn();
                } catch (Exception $ex) { $mapped = 0; }

                $del_sc = $pdo->prepare("SELECT sub_cat_name FROM dict_maker_sub_category WHERE sub_cat_id=?"); $del_sc->execute([$id]); $del_sc_name = $del_sc->fetchColumn();
                $pdo->beginTransaction();
                $pdo->prepare("DELETE FROM maker_category_hierarchy WHERE sub_cat_id=?")->execute([$id]);
                $pdo->prepare("UPDATE dict_maker_sub_category SET is_active=0 WHERE sub_cat_id=?")->execute([$id]);
                $pdo->commit();
                _log_audit($pdo,'delete','dict','maker-sub:'.$id,$del_sc_name?:('id:'.$id),null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));

                $msg = $mapped > 0
                    ? "已停用（有 {$mapped} 家廠商綁定此標籤，資料保留以維護歷史紀錄）"
                    : '已停用';
                echo json_encode(['success'=>true,'message'=>$msg,'was_mapped'=>$mapped]);
            } elseif ($op === 'reorder') {
                if (!$can_update) throw new Exception('無修改權限');
                $ids = array_values(array_filter(array_map('intval', explode(',', $_POST['ids']??''))));
                $upd = $pdo->prepare("UPDATE dict_maker_sub_category SET sort_order=? WHERE sub_cat_id=?");
                foreach ($ids as $k => $sid) { $upd->execute([$k, $sid]); }
                echo json_encode(['success'=>true]);
            }
        } catch (Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 廠商加工限制標籤字典 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'manage_maker_proc_labels') {
        try {
            $pdo->exec("SET SESSION lock_wait_timeout = 5");
            $op2 = $_POST['op'];
            if ($op2 === 'list') {
                try {
                    $stmt = $pdo->prepare("SELECT d.proc_label_id, d.label_name, d.input_type, d.numeric_type, d.unit, d.sort_order, COALESCE(d.is_repeatable,0) AS is_repeatable, GROUP_CONCAT(pm.parent_label_id ORDER BY pm.parent_label_id SEPARATOR ',') AS parent_label_ids, GROUP_CONCAT(pl.label_name ORDER BY pm.parent_label_id SEPARATOR ',') AS parent_label_names FROM dict_maker_proc_label d LEFT JOIN dict_maker_proc_label_parent_map pm ON pm.sub_label_id=d.proc_label_id LEFT JOIN dict_maker_proc_label pl ON pl.proc_label_id=pm.parent_label_id AND pl.is_active=1 WHERE d.is_active=1 GROUP BY d.proc_label_id ORDER BY d.sort_order, d.proc_label_id");
                    $stmt->execute();
                    $data = $stmt->fetchAll(PDO::FETCH_ASSOC);
                } catch (Exception $e) {
                    $stmt = $pdo->prepare("SELECT proc_label_id, label_name, input_type, 'range' AS numeric_type, unit, sort_order, 0 AS is_repeatable, NULL AS parent_label_ids, NULL AS parent_label_names FROM dict_maker_proc_label WHERE is_active=1 ORDER BY sort_order, proc_label_id");
                    $stmt->execute();
                    $data = $stmt->fetchAll(PDO::FETCH_ASSOC);
                }
                echo json_encode(['success'=>true,'data'=>$data]);
            } elseif ($op2 === 'save') {
                if (!$can_update) throw new Exception('無修改權限（需 A/CDRU/CRU）');
                $id    = intval($_POST['proc_label_id'] ?? 0);
                $name  = trim($_POST['label_name'] ?? '');
                $itype = in_array($_POST['input_type']??'', ['none','numeric','text']) ? $_POST['input_type'] : 'none';
                $ntype = in_array($_POST['numeric_type']??'', ['range','MAX','MIN']) ? $_POST['numeric_type'] : 'range';
                $unit  = in_array($_POST['unit']??'', ['mm','kg']) ? $_POST['unit'] : 'mm';
                // Multi-parent support
                $pids_str = trim($_POST['parent_label_ids'] ?? '');
                $parent_ids = array_values(array_unique(array_filter(array_map('intval', explode(',', $pids_str)))));
                if ($id) $parent_ids = array_values(array_filter($parent_ids, function($p) use ($id){ return $p !== $id; }));
                $is_sub = !empty($parent_ids);
                $is_rep = $is_sub ? 0 : intval($_POST['is_repeatable'] ?? 0);
                $parent_id_bc = $is_sub ? $parent_ids[0] : null; // backward compat column
                if ($itype !== 'numeric') { $ntype = 'range'; $unit = 'mm'; }
                if (empty($name)) throw new Exception('標籤名稱不可為空');
                $dup = $pdo->prepare("SELECT COUNT(*) FROM dict_maker_proc_label WHERE LOWER(label_name)=LOWER(?) AND is_active=1 AND proc_label_id<>?");
                $dup->execute([$name,$id]);
                if ((int)$dup->fetchColumn() > 0) throw new Exception("已存在相同名稱「{$name}」");
                $uid2 = $_SESSION['user_id']??null; $op2n = _get_operator($pdo,$uid2);
                if ($id) {
                    $old = $pdo->prepare("SELECT label_name,input_type,numeric_type,unit,parent_label_id,is_repeatable FROM dict_maker_proc_label WHERE proc_label_id=?"); $old->execute([$id]); $oldRow = $old->fetch(PDO::FETCH_ASSOC);
                    $pdo->prepare("UPDATE dict_maker_proc_label SET label_name=?,input_type=?,numeric_type=?,unit=?,parent_label_id=?,is_repeatable=? WHERE proc_label_id=?")->execute([$name,$itype,$ntype,$unit,$parent_id_bc,$is_rep,$id]);
                    $newRow = ['label_name'=>$name,'input_type'=>$itype,'numeric_type'=>$ntype,'unit'=>$unit,'parent_label_id'=>$parent_id_bc,'is_repeatable'=>$is_rep];
                    $ch=_diff_rows($oldRow??[],$newRow,array_keys($newRow)); if(!empty($ch)) _log_audit($pdo,'update','dict','maker-proc-label:'.$id,$name,$ch,$uid2,$op2n);
                } else {
                    $max = $pdo->query("SELECT COALESCE(MAX(sort_order),0)+1 FROM dict_maker_proc_label")->fetchColumn();
                    $pdo->prepare("INSERT INTO dict_maker_proc_label (label_name,input_type,numeric_type,unit,sort_order,parent_label_id,is_repeatable) VALUES (?,?,?,?,?,?,?)")->execute([$name,$itype,$ntype,$unit,$max,$parent_id_bc,$is_rep]);
                    $id = (int)$pdo->lastInsertId();
                    _log_audit($pdo,'insert','dict','maker-proc-label:'.$id,$name,null,$uid2,$op2n);
                }
                // Sync multi-parent mapping table
                $pdo->prepare("DELETE FROM dict_maker_proc_label_parent_map WHERE sub_label_id=?")->execute([$id]);
                if (!empty($parent_ids)) {
                    $ins_pm = $pdo->prepare("INSERT IGNORE INTO dict_maker_proc_label_parent_map (sub_label_id, parent_label_id) VALUES (?,?)");
                    foreach ($parent_ids as $pid) $ins_pm->execute([$id, $pid]);
                }
                echo json_encode(['success'=>true,'proc_label_id'=>$id]);
            } elseif ($op2 === 'check_delete') {
                $id = intval($_POST['id'] ?? 0);
                $chk = $pdo->prepare("SELECT COUNT(*) FROM maker_proc_label_map WHERE proc_label_id=?"); $chk->execute([$id]); $mapped = (int)$chk->fetchColumn();
                if ($mapped > 0) {
                    $mk = $pdo->prepare("SELECT DISTINCT ml.maker_id_no, ml.maker_name FROM maker_proc_label_map m JOIN maker_list ml ON ml.maker_id_no=m.maker_id_no WHERE m.proc_label_id=? LIMIT 5"); $mk->execute([$id]);
                    $mkRows = $mk->fetchAll(PDO::FETCH_ASSOC);
                    $names = array_map(function($r){ return ($r['maker_name']?:$r['maker_id_no']); }, $mkRows);
                    $reason = "此標籤已有 {$mapped} 筆廠商資料使用，無法刪除。使用廠商：".implode('、',$names).($mapped>5?'…':'');
                    echo json_encode(['can_delete'=>false,'reason'=>$reason]);
                } else {
                    echo json_encode(['can_delete'=>true]);
                }
            } elseif ($op2 === 'delete') {
                if (!$can_delete_all) throw new Exception('無刪除權限（需 A 或 CDRU）');
                $id = intval($_POST['id'] ?? 0);
                $chk = $pdo->prepare("SELECT COUNT(*) FROM maker_proc_label_map WHERE proc_label_id=?"); $chk->execute([$id]); $mapped = (int)$chk->fetchColumn();
                if ($mapped > 0) throw new Exception("此標籤已有 {$mapped} 筆廠商資料使用，無法刪除");
                $nm = $pdo->prepare("SELECT label_name FROM dict_maker_proc_label WHERE proc_label_id=?"); $nm->execute([$id]); $nm_val = $nm->fetchColumn();
                $pdo->prepare("UPDATE dict_maker_proc_label SET is_active=0 WHERE proc_label_id=?")->execute([$id]);
                _log_audit($pdo,'delete','dict','maker-proc-label:'.$id,$nm_val?:('id:'.$id),null,$_SESSION['user_id']??null,_get_operator($pdo,$_SESSION['user_id']??null));
                echo json_encode(['success'=>true,'message'=>'已刪除']);
            } elseif ($op2 === 'reorder') {
                if (!$can_update) throw new Exception('無修改權限');
                $ids = array_values(array_filter(array_map('intval', explode(',', $_POST['ids']??''))));
                $upd = $pdo->prepare("UPDATE dict_maker_proc_label SET sort_order=? WHERE proc_label_id=?");
                foreach ($ids as $k => $sid) { $upd->execute([$k, $sid]); }
                echo json_encode(['success'=>true]);
            }
        } catch (Exception $e) {
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // 下拉選單資料
    if ($_POST['action'] === 'get_dict_options') {
        try {
            $res = [
                'workpiece_types' => $pdo->query("SELECT type_code as id, type_name as text FROM dict_workpiece_type WHERE is_active=1")->fetchAll(PDO::FETCH_ASSOC),
                'gear_types' => $pdo->query("SELECT gear_type_id as id, type_name as text, has_helix_angle FROM dict_gear_type WHERE is_active=1 ORDER BY sort_order, gear_type_id")->fetchAll(PDO::FETCH_ASSOC),
                'industries' => $pdo->query("SELECT industry_id as id, industry_name as text FROM dict_industry_type WHERE is_active=1")->fetchAll(PDO::FETCH_ASSOC),
                'maker_main_cats' => $pdo->query("SELECT main_cat_id as id, main_cat_name as text FROM dict_maker_main_category WHERE is_active=1")->fetchAll(PDO::FETCH_ASSOC)
            ];
            echo json_encode(['success'=>true, 'data'=>$res]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 廠商大類製程設定 ──────────────────────────────────────────────────────
    if ($_POST['action'] === 'manage_maker_main_cat_process') {
        try {
            $pdo->exec("SET SESSION lock_wait_timeout = 5");
            $op3 = $_POST['op'];
            if ($op3 === 'list_config') {
                // 回傳所有廠商大類 + 各大類的製程設定 + 所有製程大類/小類
                $main_cats = $pdo->query("SELECT main_cat_id, main_cat_name FROM dict_maker_main_category WHERE is_active=1 ORDER BY sort_order, main_cat_id")->fetchAll(PDO::FETCH_ASSOC);
                $configs = [];
                $crows = $pdo->query("SELECT main_cat_id, ref_type, ref_id FROM dict_maker_main_cat_process_config ORDER BY main_cat_id, ref_type, ref_id")->fetchAll(PDO::FETCH_ASSOC);
                foreach ($crows as $cr) { $configs[intval($cr['main_cat_id'])][] = ['ref_type'=>$cr['ref_type'],'ref_id'=>intval($cr['ref_id'])]; }
                foreach ($main_cats as &$mc) { $mc['process_config'] = $configs[intval($mc['main_cat_id'])] ?? []; }
                unset($mc);
                $all_ptypes = $pdo->query("SELECT process_type_id, process_type FROM process_type WHERE COALESCE(is_active,1)=1 ORDER BY COALESCE(sort_order,0), process_type_id")->fetchAll(PDO::FETCH_ASSOC);
                $all_pnos   = $pdo->query("SELECT pn.ProcessNo, pn.ProcessName, pn.process_type_id, GROUP_CONCAT(DISTINCT pm.process_type_id ORDER BY pm.process_type_id SEPARATOR ',') AS extra_type_ids FROM process_no pn LEFT JOIN process_type_process_map pm ON pm.process_no_id=pn.ProcessNo WHERE pn.ProcessName IS NOT NULL GROUP BY pn.ProcessNo ORDER BY pn.ProcessNo")->fetchAll(PDO::FETCH_ASSOC);
                echo json_encode(['success'=>true,'main_cats'=>$main_cats,'process_types'=>$all_ptypes,'process_nos'=>$all_pnos]);
            } elseif ($op3 === 'save_config') {
                if (!$can_update) throw new Exception('無修改權限');
                $main_cat_id = intval($_POST['main_cat_id'] ?? 0);
                $clear_all   = intval($_POST['clear_all'] ?? 0);
                $items = json_decode(trim($_POST['config_items'] ?? '[]'), true) ?: [];
                if ($clear_all) {
                    $pdo->exec("DELETE FROM dict_maker_main_cat_process_config");
                } elseif ($main_cat_id) {
                    $pdo->prepare("DELETE FROM dict_maker_main_cat_process_config WHERE main_cat_id=?")->execute([$main_cat_id]);
                }
                if ($main_cat_id && !empty($items)) {
                    $ins = $pdo->prepare("INSERT IGNORE INTO dict_maker_main_cat_process_config (main_cat_id, ref_type, ref_id) VALUES (?,?,?)");
                    foreach ($items as $item) {
                        $rtype = in_array($item['ref_type']??'', ['type','no']) ? $item['ref_type'] : null;
                        $rid   = intval($item['ref_id'] ?? 0);
                        if (!$rtype || !$rid) continue;
                        $ins->execute([$main_cat_id, $rtype, $rid]);
                    }
                }
                echo json_encode(['success'=>true]);
            } elseif ($op3 === 'get_vendor_tags') {
                $maker_id_no = trim($_POST['maker_id_no'] ?? '');
                $q = $pdo->prepare("SELECT main_cat_id, ref_type, ref_id FROM maker_main_cat_process_tag WHERE maker_id_no=? ORDER BY main_cat_id, ref_type, ref_id");
                $q->execute([$maker_id_no]);
                echo json_encode(['success'=>true,'data'=>$q->fetchAll(PDO::FETCH_ASSOC)]);
            }
        } catch (Exception $e) {
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── KPI 評級（即時計算，近12個月）──────────────────────────────────────
    if ($_POST['action'] === 'get_kpi_grades') {
        try {
            $maker_ids = json_decode($_POST['maker_ids'] ?? '[]', true) ?: [];
            if (empty($maker_ids)) { echo json_encode(['success'=>true,'data'=>[]]); exit; }
            $pdo->exec("SET SESSION lock_wait_timeout=5");

            $cfg = $pdo->query("SELECT setting_key,setting_value FROM kpi_vendor_setting")->fetchAll(PDO::FETCH_KEY_PAIR);
            $tol     = intval($cfg['ontime_tolerance_days'] ?? 3);
            $minTxn  = intval($cfg['min_txn_count'] ?? 5);
            $grules  = $pdo->query("SELECT grade,ontime_gte,ng_lte,color FROM kpi_grade_rule ORDER BY sort_order,rule_id")->fetchAll(PDO::FETCH_ASSOC);

            $ds = date('Y-m-d', strtotime('-12 months'));
            $de = date('Y-m-d');

            $ph  = implode(',', array_fill(0, count($maker_ids), '?'));
            $sql = "SELECT bi.maker_id,
                           ml.maker_id_no,
                           COUNT(*) AS total,
                           SUM(CASE WHEN bi.return_date IS NOT NULL AND DATEDIFF(bi.return_date, bi.expect_date) <= ? THEN 1 ELSE 0 END) AS ontime,
                           SUM(CASE WHEN bi.quality_ng IS NOT NULL AND bi.quality_ng > 0 THEN 1 ELSE 0 END) AS ng_count
                    FROM bom_ing bi
                    LEFT JOIN maker_list ml ON ml.maker_id = bi.maker_id
                    WHERE DATE(bi.outsource_date) BETWEEN ? AND ?
                      AND bi.maker_id IS NOT NULL AND bi.maker_id <> ''
                      AND ml.maker_id_no IN ($ph)
                    GROUP BY bi.maker_id, ml.maker_id_no";

            $params = array_merge([$tol, $ds, $de], $maker_ids);
            $stmt = $pdo->prepare($sql);
            $stmt->execute($params);
            $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

            $grades = [];
            foreach ($rows as $r) {
                $key  = $r['maker_id_no'];
                $valid = (int)$r['total'];
                $ontime_pct = $valid >= $minTxn ? round((int)$r['ontime'] / $valid * 100, 1) : null;
                $ng_pct     = $valid > 0 ? round((int)$r['ng_count'] / $valid * 100, 1) : 0;
                $grade = '—'; $color = 'gray';
                if ($ontime_pct !== null) {
                    foreach ($grules as $rule) {
                        if ($ontime_pct >= ($rule['ontime_gte'] ?? 0) && $ng_pct <= ($rule['ng_lte'] ?? 999)) {
                            $grade = $rule['grade']; $color = $rule['color']; break;
                        }
                    }
                }
                $grades[$key] = [
                    'grade'       => $grade,
                    'grade_color' => $color,
                    'ontime_pct'  => $ontime_pct,
                    'ng_pct'      => $ng_pct,
                    'total'       => $valid,
                    'enough'      => $valid >= $minTxn,
                ];
            }
            echo json_encode(['success'=>true,'data'=>$grades]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'data'=>[],'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 重複/相似 檢測 ────────────────────────────────────────────────────────
    if ($_POST['action'] === 'check_duplicates') {
        try {
            $type = trim($_POST['type'] ?? '');

            if ($type === 'parts') {
                // 料號完全重複（D_Setting_Id 相同）
                $dup = $pdo->query("
                    SELECT D_Setting_Id, COUNT(*) AS cnt
                    FROM d_setting
                    GROUP BY D_Setting_Id HAVING cnt > 1
                    ORDER BY D_Setting_Id")->fetchAll(PDO::FETCH_ASSOC);

                $result = [];
                foreach ($dup as $d) {
                    $rows = $pdo->prepare("
                        SELECT s.d_id, s.D_Setting_Id, s.Spec_No, s.Revision, s.Issue_Date,
                               s.Type, s.Remark, c.customer AS client_name
                        FROM d_setting s
                        LEFT JOIN customer_list c ON c.customer_id=s.Customer_Id
                        WHERE s.D_Setting_Id=?
                        ORDER BY s.Issue_Date DESC, s.d_id ASC");
                    $rows->execute([$d['D_Setting_Id']]);
                    $partRows = $rows->fetchAll(PDO::FETCH_ASSOC);
                    foreach ($partRows as &$pr) {
                        $did = $pr['d_id']; $rel = [];
                        $q=$pdo->prepare("SELECT COUNT(*) FROM order_track WHERE d_id_ID=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $rel[]="訂單{$n}筆";
                        $q=$pdo->prepare("SELECT COUNT(*) FROM bom WHERE d_setting_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $rel[]="生產{$n}筆";
                        $q=$pdo->prepare("SELECT COUNT(*) FROM is_list WHERE d_setting_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $rel[]="出貨{$n}筆";
                        $q=$pdo->prepare("SELECT COUNT(*) FROM quotation_item WHERE d_setting_d_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $rel[]="報價{$n}筆";
                        $q=$pdo->prepare("SELECT COUNT(*) FROM ir_track WHERE d_setting_id=?"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $rel[]="退貨{$n}筆";
                        $q=$pdo->prepare("SELECT COUNT(*) FROM stock_items WHERE d_id=? AND is_active=1"); $q->execute([$did]); $n=(int)$q->fetchColumn(); if($n) $rel[]="庫存{$n}筆";
                        $pr['relations'] = $rel;
                    }; unset($pr);
                    $result[] = [
                        'key'   => $d['D_Setting_Id'],
                        'count' => (int)$d['cnt'],
                        'rows'  => $partRows,
                    ];
                }
                echo json_encode(['success'=>true,'data'=>$result,'type'=>'parts']);

            } elseif ($type === 'customers') {
                // 內部函式：取單一客戶詳細 + 關聯筆數
                $getCustomerDetail = function($cid) use ($pdo) {
                    $row = $pdo->prepare("SELECT * FROM customer_list WHERE customer_id=?");
                    $row->execute([$cid]);
                    $d = $row->fetch(PDO::FETCH_ASSOC);
                    if (!$d) return null;
                    // 關聯
                    $rel = [];
                    $n = $pdo->prepare("SELECT COUNT(*) FROM d_setting WHERE Customer_Id=?"); $n->execute([$cid]);
                    $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "料號 {$cnt} 筆";
                    $n = $pdo->prepare("SELECT COUNT(*) FROM order_track WHERE Client_name_ID=?"); $n->execute([$cid]);
                    $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "訂單 {$cnt} 筆";
                    $n = $pdo->prepare("SELECT COUNT(*) FROM is_list WHERE Client_id=?"); $n->execute([$cid]);
                    $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "出貨單 {$cnt} 筆";
                    $n = $pdo->prepare("SELECT COUNT(*) FROM quotation_list WHERE client_id=?"); $n->execute([$cid]);
                    $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "報價單 {$cnt} 筆";
                    $n = $pdo->prepare("SELECT COUNT(*) FROM stock_items WHERE client_id=? AND is_active=1"); $n->execute([$cid]);
                    $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "庫存 {$cnt} 筆";
                    $d['relations'] = $rel;
                    return $d;
                };

                // 完全相同名稱
                $exactRaw = $pdo->query("
                    SELECT customer, GROUP_CONCAT(customer_id ORDER BY customer_id SEPARATOR ',') AS ids, COUNT(*) AS cnt
                    FROM customer_list WHERE (is_inactive IS NULL OR is_inactive=0)
                    GROUP BY customer HAVING cnt>1 ORDER BY customer")->fetchAll(PDO::FETCH_ASSOC);
                $exact = [];
                foreach ($exactRaw as $g) {
                    $ids = explode(',', $g['ids']);
                    $rows = [];
                    foreach ($ids as $cid) { $detail = $getCustomerDetail(trim($cid)); if ($detail) $rows[] = $detail; }
                    $exact[] = ['key'=>$g['customer'],'count'=>(int)$g['cnt'],'rows'=>$rows];
                }

                // 疑似相似（只取代碼對）
                $similarRaw = $pdo->query("
                    SELECT a.customer_id AS id_a, a.customer AS name_a,
                           b.customer_id AS id_b, b.customer AS name_b
                    FROM customer_list a JOIN customer_list b
                      ON a.customer_id < b.customer_id
                         AND a.customer <> b.customer
                         AND (a.is_inactive IS NULL OR a.is_inactive=0)
                         AND (b.is_inactive IS NULL OR b.is_inactive=0)
                         AND (LEFT(a.customer,4) = LEFT(b.customer,4)
                              OR a.customer LIKE CONCAT('%',LEFT(b.customer,3),'%'))
                    ORDER BY a.customer LIMIT 80")->fetchAll(PDO::FETCH_ASSOC);
                $similar = [];
                foreach ($similarRaw as $s) {
                    $da = $getCustomerDetail($s['id_a']);
                    $db = $getCustomerDetail($s['id_b']);
                    if ($da && $db) $similar[] = ['a'=>$da,'b'=>$db];
                }
                echo json_encode(['success'=>true,'exact'=>$exact,'similar'=>$similar,'type'=>'customers']);

            } elseif ($type === 'makers') {
                // 內部函式：取單一廠商詳細 + 關聯筆數
                $getMakerDetail = function($mid) use ($pdo) {
                    $row = $pdo->prepare("SELECT * FROM maker_list WHERE maker_id_no=?");
                    $row->execute([$mid]);
                    $d = $row->fetch(PDO::FETCH_ASSOC);
                    if (!$d) return null;
                    $rel = [];
                    $n = $pdo->prepare("SELECT COUNT(*) FROM bom_ing WHERE maker_id_no=?"); $n->execute([$mid]);
                    $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "加工單 {$cnt} 筆";
                    try {
                        $n = $pdo->prepare("SELECT COUNT(*) FROM maker_sub_category_mapping WHERE maker_id_no=?"); $n->execute([$mid]);
                        $cnt = (int)$n->fetchColumn(); if ($cnt) $rel[] = "加工標籤 {$cnt} 項";
                    } catch(Exception $ex){}
                    $d['relations'] = $rel;
                    return $d;
                };

                // 完全相同簡稱
                $exactNRaw = $pdo->query("
                    SELECT maker_id, GROUP_CONCAT(maker_id_no ORDER BY maker_id_no SEPARATOR ',') AS ids, COUNT(*) AS cnt
                    FROM maker_list WHERE (status IS NULL OR status<>'X')
                    GROUP BY maker_id HAVING cnt>1 ORDER BY maker_id")->fetchAll(PDO::FETCH_ASSOC);
                $exactFRaw = $pdo->query("
                    SELECT maker_id_all, GROUP_CONCAT(maker_id_no ORDER BY maker_id_no SEPARATOR ',') AS ids, COUNT(*) AS cnt
                    FROM maker_list WHERE maker_id_all IS NOT NULL AND maker_id_all<>'' AND (status IS NULL OR status<>'X')
                    GROUP BY maker_id_all HAVING cnt>1 ORDER BY maker_id_all")->fetchAll(PDO::FETCH_ASSOC);
                $exact_name = []; $exact_full = [];
                foreach ($exactNRaw as $g) {
                    $ids = explode(',', $g['ids']); $rows = [];
                    foreach ($ids as $mid) { $d = $getMakerDetail(trim($mid)); if ($d) $rows[] = $d; }
                    $exact_name[] = ['key'=>$g['maker_id'],'count'=>(int)$g['cnt'],'rows'=>$rows];
                }
                foreach ($exactFRaw as $g) {
                    $ids = explode(',', $g['ids']); $rows = [];
                    foreach ($ids as $mid) { $d = $getMakerDetail(trim($mid)); if ($d) $rows[] = $d; }
                    $exact_full[] = ['key'=>$g['maker_id_all'],'count'=>(int)$g['cnt'],'rows'=>$rows];
                }
                // 疑似相似
                $similarRaw = $pdo->query("
                    SELECT a.maker_id_no AS id_a, b.maker_id_no AS id_b
                    FROM maker_list a JOIN maker_list b
                      ON a.maker_id_no < b.maker_id_no
                         AND a.maker_id <> b.maker_id
                         AND (a.status IS NULL OR a.status<>'X')
                         AND (b.status IS NULL OR b.status<>'X')
                         AND LEFT(a.maker_id,3) = LEFT(b.maker_id,3)
                    ORDER BY a.maker_id LIMIT 80")->fetchAll(PDO::FETCH_ASSOC);
                $similar = [];
                foreach ($similarRaw as $s) {
                    $da = $getMakerDetail($s['id_a']);
                    $db = $getMakerDetail($s['id_b']);
                    if ($da && $db) $similar[] = ['a'=>$da,'b'=>$db];
                }
                echo json_encode(['success'=>true,'exact_name'=>$exact_name,'exact_full'=>$exact_full,'similar'=>$similar,'type'=>'makers']);
            } else {
                throw new Exception('未知類型');
            }
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 除錯：停用/刪除客戶 ────────────────────────────────────────────────
    if ($_POST['action'] === 'dup_deactivate_customer') {
        try {
            if (!$can_set_status) throw new Exception('無狀態切換權限（需要 A 或 CDRU 權限）');
            $cid = trim($_POST['customer_id']);
            $pdo->prepare("UPDATE customer_list SET is_inactive=1, Modified_By=?, Modified_At=NOW() WHERE customer_id=?")
                ->execute([$uid, $cid]);
            echo json_encode(['success'=>true,'message'=>"客戶 {$cid} 已設為停用"]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'dup_delete_customer') {
        try {
            if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
            $cid = trim($_POST['customer_id']);
            // Check relations
            $n1 = $pdo->prepare("SELECT COUNT(*) FROM d_setting WHERE Customer_Id=?"); $n1->execute([$cid]); $c1=(int)$n1->fetchColumn();
            $n2 = $pdo->prepare("SELECT COUNT(*) FROM order_track WHERE Client_name_ID=?"); $n2->execute([$cid]); $c2=(int)$n2->fetchColumn();
            if ($c1+$c2 > 0) throw new Exception("此客戶有關聯資料（料號{$c1}筆、訂單{$c2}筆），請先改為停用狀態");
            $pdo->prepare("DELETE FROM customer_industry_mapping WHERE customer_id=?")->execute([$cid]);
            $pdo->prepare("DELETE FROM customer_list WHERE customer_id=?")->execute([$cid]);
            echo json_encode(['success'=>true,'message'=>"客戶 {$cid} 已刪除"]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 除錯：停用/刪除廠商 ────────────────────────────────────────────────
    if ($_POST['action'] === 'dup_deactivate_maker') {
        try {
            if (!$can_set_status) throw new Exception('無狀態切換權限（需要 A 或 CDRU 權限）');
            $mid = trim($_POST['maker_id_no']);
            $pdo->prepare("UPDATE maker_list SET status='X', Modified_By=?, Modified_At=NOW() WHERE maker_id_no=?")
                ->execute([$uid, $mid]);
            echo json_encode(['success'=>true,'message'=>"廠商 {$mid} 已設為停用"]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'dup_delete_maker') {
        try {
            if (!$can_delete_all) throw new Exception('無刪除權限（需要 A 或 CRUD 權限）');
            $mid = trim($_POST['maker_id_no']);
            $n1 = $pdo->prepare("SELECT COUNT(*) FROM bom_ing WHERE maker_id_no=?"); $n1->execute([$mid]); $c1=(int)$n1->fetchColumn();
            if ($c1 > 0) throw new Exception("此廠商有加工單 {$c1} 筆關聯，不可刪除（請改為停用）");
            try {
                $pdo->prepare("DELETE FROM maker_sub_category_mapping WHERE maker_id_no=?")->execute([$mid]);
            } catch(Exception $ex){}
            $pdo->prepare("DELETE FROM maker_list WHERE maker_id_no=?")->execute([$mid]);
            echo json_encode(['success'=>true,'message'=>"廠商 {$mid} 已刪除"]);
        } catch (Exception $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
