    // ── 取得可設定業務的人員清單 ───────────────────────────────────────────
    if ($_POST['action'] === 'get_sales_users') {
        try {
            // 取業務單位設定（system_parameters.param_group=SALES_SETTING, param_key=sales_unit_id）
            $salesUnitId = null;
            try {
                $sp = $pdo->query("SELECT param_value FROM system_parameters WHERE param_group='SALES_SETTING' AND param_key='sales_unit_id' LIMIT 1");
                $spRow = $sp->fetch(PDO::FETCH_COLUMN);
                if ($spRow) {
                    $decoded = json_decode($spRow, true);
                    $salesUnitId = isset($decoded['id']) ? intval($decoded['id']) : intval($spRow);
                }
            } catch(Exception $ex) {}

            if ($salesUnitId) {
                // 取本部門及所有子部門的 id
                $deptIds = [$salesUnitId];
                $queue   = [$salesUnitId];
                while (!empty($queue)) {
                    $ph = implode(',', array_fill(0, count($queue), '?'));
                    $sub = $pdo->prepare("SELECT id FROM department WHERE parent_id IN ($ph)");
                    $sub->execute($queue);
                    $queue = [];
                    foreach ($sub->fetchAll(PDO::FETCH_COLUMN) as $cid) {
                        $deptIds[] = intval($cid);
                        $queue[]   = intval($cid);
                    }
                }
                $ph = implode(',', array_fill(0, count($deptIds), '?'));
                // Try with position table, fallback without it
                try {
                    $stmt = $pdo->prepare("SELECT u.id, u.user_cname AS name,
                            COALESCE(dp.name,'') AS dept_name,
                            COALESCE(p.name,'') AS position_name
                        FROM user u
                        LEFT JOIN user_department_position_map m ON m.user_id = u.id
                        LEFT JOIN department dp ON dp.id = m.department_id
                        LEFT JOIN position p ON p.id = m.position_id
                        WHERE u.state = 1 AND m.department_id IN ($ph)
                        GROUP BY u.id
                        ORDER BY dp.sort_order, dp.name, u.user_cname");
                    $stmt->execute($deptIds);
                    $allRows = $stmt->fetchAll(PDO::FETCH_ASSOC);
                    echo json_encode(['success'=>true,'data'=>$allRows]);
                    exit;
                } catch(Exception $joinEx) {
                    // Simpler fallback
                    $stmt = $pdo->prepare("SELECT u.id, u.user_cname AS name,
                            COALESCE(dp.name,'') AS dept_name, '' AS position_name
                        FROM user u
                        LEFT JOIN user_department_position_map m ON m.user_id = u.id
                        LEFT JOIN department dp ON dp.id = m.department_id
                        WHERE u.state = 1 AND m.department_id IN ($ph)
                        GROUP BY u.id
                        ORDER BY dp.name, u.user_cname");
                    $stmt->execute($deptIds);
                }
            } else {
                // 無設定時，回傳所有在職人員
                $stmt = $pdo->query("SELECT u.id, u.user_cname AS name,
                        COALESCE(dp.name,'') AS dept_name,
                        COALESCE(p.name,'') AS position_name
                    FROM user u
                    LEFT JOIN user_department_position_map m ON m.user_id=u.id
                    LEFT JOIN department dp ON dp.id=m.department_id
                    LEFT JOIN position p ON p.id=m.position_id
                    WHERE u.state=1
                    GROUP BY u.id
                    ORDER BY dp.sort_order, dp.name, u.user_cname");
            }
            echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'data'=>[],'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 儲存客戶業務設定 ─────────────────────────────────────────────────
    if ($_POST['action'] === 'save_customer_sales') {
        try {
            if (!$can_update) throw new Exception('無修改權限');
            $cid          = trim($_POST['customer_id']);
            $primary_uid  = intval($_POST['primary_user_id'] ?? 0);
            $deputy_uid   = intval($_POST['deputy_user_id'] ?? 0);
            if ($primary_uid && $primary_uid === $deputy_uid) throw new Exception('主要業務與代理業務不可為同一人');
            // 取舊業務資料供 audit diff
            $old_p_uid=0; $old_p_name=''; $old_d_uid=0; $old_d_name='';
            $osr=$pdo->prepare("SELECT cs.role,cs.user_id,u.user_cname FROM customer_sales cs LEFT JOIN user u ON u.id=cs.user_id WHERE cs.customer_id=? AND cs.is_active=1 AND cs.role IN ('primary','deputy')");
            $osr->execute([$cid]);
            foreach($osr->fetchAll(PDO::FETCH_ASSOC) as $orow){
                if($orow['role']==='primary'){$old_p_uid=intval($orow['user_id']);$old_p_name=$orow['user_cname']??'';}
                if($orow['role']==='deputy') {$old_d_uid=intval($orow['user_id']);$old_d_name=$orow['user_cname']??'';}
            }
            $pdo->beginTransaction();
            // UPSERT primary
            if ($primary_uid > 0) {
                $pdo->prepare("INSERT INTO customer_sales (customer_id,user_id,role,is_active,Created_By,Created_At)
                    VALUES (?,?,'primary',1,?,NOW())
                    ON DUPLICATE KEY UPDATE user_id=?,is_active=1")
                    ->execute([$cid,$primary_uid,$uid,$primary_uid]);
            } else {
                $pdo->prepare("UPDATE customer_sales SET is_active=0 WHERE customer_id=? AND role='primary'")->execute([$cid]);
            }
            // UPSERT deputy
            if ($deputy_uid > 0) {
                $pdo->prepare("INSERT INTO customer_sales (customer_id,user_id,role,is_active,Created_By,Created_At)
                    VALUES (?,?,'deputy',1,?,NOW())
                    ON DUPLICATE KEY UPDATE user_id=?,is_active=1")
                    ->execute([$cid,$deputy_uid,$uid,$deputy_uid]);
            } else {
                $pdo->prepare("UPDATE customer_sales SET is_active=0 WHERE customer_id=? AND role='deputy'")->execute([$cid]);
            }
            $pdo->commit();
            // audit log
            $op_cs = _get_operator($pdo, $uid);
            $cn_q  = $pdo->prepare("SELECT customer FROM customer_list WHERE customer_id=? LIMIT 1");
            $cn_q->execute([$cid]); $cust_nm = $cn_q->fetchColumn()?:$cid;
            $sales_ch = [];
            if ($old_p_uid !== $primary_uid) {
                $new_pn='—'; if($primary_uid>0){$npq=$pdo->prepare("SELECT user_cname FROM user WHERE id=? LIMIT 1");$npq->execute([$primary_uid]);$new_pn=$npq->fetchColumn()?:'uid:'.$primary_uid;}
                $sales_ch[] = ['field'=>'主要業務','old'=>$old_p_name?:($old_p_uid?'uid:'.$old_p_uid:'—'),'new'=>$new_pn];
            }
            if ($old_d_uid !== $deputy_uid) {
                $new_dn='—'; if($deputy_uid>0){$ndq=$pdo->prepare("SELECT user_cname FROM user WHERE id=? LIMIT 1");$ndq->execute([$deputy_uid]);$new_dn=$ndq->fetchColumn()?:'uid:'.$deputy_uid;}
                $sales_ch[] = ['field'=>'代理業務','old'=>$old_d_name?:($old_d_uid?'uid:'.$old_d_uid:'—'),'new'=>$new_dn];
            }
            if (!empty($sales_ch)) _log_audit($pdo,'update','customer',$cid,$cust_nm,$sales_ch,$uid,$op_cs);
            echo json_encode(['success'=>true,'message'=>'業務設定已儲存']);
        } catch(Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 產業別小類 CRUD ────────────────────────────────────────────────────
    if ($_POST['action'] === 'manage_industry_sub_types') {
        try {
            $op = $_POST['op'];
            if ($op === 'list') {
                $ind_id = intval($_POST['industry_id']);
                $stmt = $pdo->prepare("SELECT sub_id, sub_name, sort_order FROM dict_industry_sub_type WHERE industry_id=? AND is_active=1 ORDER BY sort_order, sub_id");
                $stmt->execute([$ind_id]);
                echo json_encode(['success'=>true,'data'=>$stmt->fetchAll(PDO::FETCH_ASSOC)]);
            } elseif ($op === 'save') {
                $id  = intval($_POST['sub_id'] ?? 0);
                $iid = intval($_POST['industry_id']);
                $nm  = trim($_POST['sub_name'] ?? '');
                if (!$nm) throw new Exception('小類名稱不可為空');
                if ($id) {
                    $pdo->prepare("UPDATE dict_industry_sub_type SET sub_name=? WHERE sub_id=?")->execute([$nm,$id]);
                } else {
                    $pdo->prepare("INSERT INTO dict_industry_sub_type (industry_id,sub_name) VALUES (?,?)")->execute([$iid,$nm]);
                }
                echo json_encode(['success'=>true]);
            } elseif ($op === 'delete') {
                $id = intval($_POST['id']);
                $pdo->prepare("UPDATE dict_industry_sub_type SET is_active=0 WHERE sub_id=?")->execute([$id]);
                echo json_encode(['success'=>true]);
            }
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 取客戶產業別（含小類）
    if ($_POST['action'] === 'get_customer_industries') {
        try {
            $cid = trim($_POST['customer_id']);
            // 已選大類
            $big = $pdo->prepare("SELECT cim.industry_id, d.industry_name, d.note FROM customer_industry_mapping cim JOIN dict_industry_type d ON d.industry_id=cim.industry_id WHERE cim.customer_id=? AND d.is_active=1");
            $big->execute([$cid]);
            $bigList = $big->fetchAll(PDO::FETCH_ASSOC);
            // 已選小類（含備註）
            $sub = $pdo->prepare("SELECT m.sub_id, m.note AS sub_note, s.sub_name, s.industry_id FROM customer_industry_sub_mapping m JOIN dict_industry_sub_type s ON s.sub_id=m.sub_id WHERE m.customer_id=?");
            $sub->execute([$cid]);
            $subList = $sub->fetchAll(PDO::FETCH_ASSOC);
            echo json_encode(['success'=>true,'industries'=>$bigList,'sub_types'=>$subList]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // 儲存客戶產業別小類
    if ($_POST['action'] === 'save_customer_industry_subs') {
        try {
            if (!$can_update) throw new Exception('無修改權限');
