            $pdo->beginTransaction();
            $pdo->prepare("DELETE FROM customer_industry_sub_mapping WHERE customer_id=?")->execute([$cid]);
            $ins = $pdo->prepare("INSERT INTO customer_industry_sub_mapping (customer_id,sub_id,note) VALUES (?,?,?)");
            foreach ($subs as $s) {
                if (!empty($s['sub_id'])) $ins->execute([$cid, intval($s['sub_id']), trim($s['note']??'')]);
            }
            $pdo->commit();
            echo json_encode(['success'=>true,'message'=>'產業別小類已儲存']);
        } catch(Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
