        }
        exit;
    }

    // ── 批次設定客戶等級 / 產業別 / 結帳日 ────────────────────────────────
    if ($_POST['action'] === 'batch_update_customers') {
        try {
            if (!$can_update) throw new Exception('無修改權限');
            $ids    = json_decode($_POST['customer_ids'] ?? '[]', true) ?: [];
            $field  = trim($_POST['field'] ?? '');
            $value  = trim($_POST['value'] ?? '');
            if (empty($ids)) throw new Exception('未選擇客戶');
            $ph = implode(',', array_fill(0, count($ids), '?'));
            if ($field === 'customer_grade') {
                if (!in_array($value, ['S','A','B','C','D',''])) throw new Exception('無效等級');
                $pdo->prepare("UPDATE customer_list SET customer_grade=? WHERE customer_id IN ($ph)")
                    ->execute(array_merge([$value ?: null], $ids));
            } elseif ($field === 'settlement_day') {
                $day = intval($value);
                if ($day < 1 || $day > 31) throw new Exception('結帳日須為 1~31');
                $pdo->prepare("UPDATE customer_list SET settlement_day=?,settlement_mode='FIXED' WHERE customer_id IN ($ph)")
                    ->execute(array_merge([$day], $ids));
            } elseif ($field === 'add_industry') {
                $ind_id = intval($value);
                if (!$ind_id) throw new Exception('請選擇產業別');
                $ins = $pdo->prepare("INSERT IGNORE INTO customer_industry_mapping (customer_id,industry_id) VALUES (?,?)");
                foreach ($ids as $cid) { $ins->execute([$cid, $ind_id]); }
            } elseif ($field === 'remove_industry') {
                $ind_id = intval($value);
                $pdo->prepare("DELETE FROM customer_industry_mapping WHERE customer_id IN ($ph) AND industry_id=?")
                    ->execute(array_merge($ids, [$ind_id]));
            } else {
                throw new Exception('未知操作欄位');
            }
            echo json_encode(['success'=>true,'message'=>'已更新 '.count($ids).' 筆客戶']);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 批次設定料號工件種類 / 小類 ────────────────────────────────────
    if ($_POST['action'] === 'batch_update_parts') {
        try {
            if (!$can_update) throw new Exception('無修改權限');
            $ids   = json_decode($_POST['d_ids'] ?? '[]', true) ?: [];
            $field = trim($_POST['field'] ?? '');
            $value = trim($_POST['value'] ?? '');
            if (empty($ids)) throw new Exception('未選擇料號');
            $ph = implode(',', array_fill(0, count($ids), '?'));
            if ($field === 'Type') {
                if ($value === 'G') throw new Exception('批次設定不提供設定為G（齒輪）');
                $pdo->prepare("UPDATE d_setting SET Type=? WHERE d_id IN ($ph)")
                    ->execute(array_merge([$value], array_map('intval', $ids)));
            } elseif ($field === 'workpiece_sub_type_id') {
                $sid = intval($value) ?: null;
                $pdo->prepare("UPDATE d_setting SET workpiece_sub_type_id=? WHERE d_id IN ($ph)")
                    ->execute(array_merge([$sid], array_map('intval', $ids)));
            } else {
                throw new Exception('未知操作欄位');
            }
            echo json_encode(['success'=>true,'message'=>'已更新 '.count($ids).' 筆料號']);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 取得操作歷史紀錄 ─────────────────────────────────────────────────────
    if ($_POST['action'] === 'get_audit_log') {
        try {
            $pg   = max(1, intval($_POST['page'] ?? 1));
            $lmt  = 20; $off = ($pg-1)*$lmt;
            $where = '1=1'; $params = [];
            $df = trim($_POST['date_from'] ?? ''); $dt = trim($_POST['date_to'] ?? '');
            $tt = trim($_POST['target_type'] ?? ''); $kw = trim($_POST['keyword'] ?? '');
            if ($df) { $where .= ' AND created_at >= ?'; $params[] = $df.' 00:00:00'; }
            if ($dt) { $where .= ' AND created_at <= ?'; $params[] = $dt.' 23:59:59'; }
            if ($tt) { $where .= ' AND target_type=?';   $params[] = $tt; }
            if ($kw) { $where .= ' AND (target_id LIKE ? OR target_name LIKE ? OR operator LIKE ?)'; $params=array_merge($params,["%$kw%","%$kw%","%$kw%"]); }
            $tc=$pdo->prepare("SELECT COUNT(*) FROM audit_log WHERE $where"); $tc->execute($params); $total=(int)$tc->fetchColumn();
            $st=$pdo->prepare("SELECT * FROM audit_log WHERE $where ORDER BY created_at DESC LIMIT $lmt OFFSET $off"); $st->execute($params);
            echo json_encode(['success'=>true,'data'=>$st->fetchAll(PDO::FETCH_ASSOC),'total'=>$total,'pages'=>max(1,(int)ceil($total/$lmt)),'page'=>$pg]);
        } catch(Throwable $e){ echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 製程大類列表（for filter buttons in process tab）────────────────
    if ($_POST['action'] === 'get_process_types') {
        try {
            $q = $pdo->query("SELECT process_type_id, process_type, COALESCE(sort_order,0) AS sort_order FROM process_type WHERE COALESCE(is_active,1)=1 ORDER BY COALESCE(sort_order,0), process_type_id");
            echo json_encode(['success'=>true,'data'=>$q->fetchAll(PDO::FETCH_ASSOC)]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 製程列表（process_no，附大類標籤 + 備註筆數）─────────────────────
    if ($_POST['action'] === 'list_process') {
        try {
            $design_col = $can_see_design
                ? "GROUP_CONCAT(DISTINCT CASE WHEN notes.note_type='design' THEN notes.note_text END ORDER BY notes.note_id SEPARATOR ' ')"
                : "NULL";
            $sql = "SELECT pn.ProcessNo, pn.ProcessName, COALESCE(pn.is_exclude_qc,0) AS is_exclude_qc,
                        GROUP_CONCAT(DISTINCT pt.process_type_id ORDER BY pt.process_type_id SEPARATOR ',') AS type_ids,
                        GROUP_CONCAT(DISTINCT pt.process_type   ORDER BY pt.process_type_id SEPARATOR ',') AS type_names,
                        COUNT(DISTINCT CASE WHEN notes.note_type='oper'   THEN notes.note_id END) AS oper_count,
                        COUNT(DISTINCT CASE WHEN notes.note_type='design' THEN notes.note_id END) AS design_count,
                        GROUP_CONCAT(DISTINCT CASE WHEN notes.note_type='oper' THEN notes.note_text END ORDER BY notes.note_id SEPARATOR ' ') AS oper_text,
                        {$design_col} AS design_text
                    FROM process_no pn
                    LEFT JOIN (
                        SELECT process_no_id AS pno_id, process_type_id AS pt_id FROM process_type_process_map
                        UNION
                        SELECT ProcessNo, process_type_id FROM process_no WHERE process_type_id IS NOT NULL
                    ) combined ON combined.pno_id = pn.ProcessNo
                    LEFT JOIN process_type pt ON pt.process_type_id = combined.pt_id
                    LEFT JOIN process_notes notes ON notes.process_no_id = pn.ProcessNo
                    GROUP BY pn.ProcessNo, pn.ProcessName
                    ORDER BY pn.ProcessNo";
            $rows = $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);

            // Load note links
            $linkMap = [];
            try {
                foreach ($pdo->query("SELECT src_pno, dst_pno, link_type FROM process_note_links")->fetchAll(PDO::FETCH_ASSOC) as $lr) {
                    $linkMap[(int)$lr['dst_pno']][$lr['link_type']] = (int)$lr['src_pno'];
                }
            } catch(Exception $e){}

            // Load notes+images and merge into rows
            $noteTypes = $can_see_design ? "('oper','design')" : "('oper')";
            $nSql = "SELECT n.process_no_id AS pno, n.note_id, n.note_type, n.note_text, n.created_by, n.created_at,
                        GROUP_CONCAT(ni.file_name ORDER BY ni.img_id SEPARATOR '\t') AS img_files,
                        GROUP_CONCAT(ni.img_id    ORDER BY ni.img_id SEPARATOR '\t') AS img_ids
                     FROM process_notes n
                     LEFT JOIN note_images ni ON ni.note_id=n.note_id AND ni.note_type IN ('process_oper','process_design')
                     WHERE n.note_type IN {$noteTypes}
                     GROUP BY n.note_id ORDER BY n.process_no_id, n.note_type, n.note_id";
            $nRows = $pdo->query($nSql)->fetchAll(PDO::FETCH_ASSOC);
            $nMap = [];
            foreach ($nRows as $nr) {
                $p = (int)$nr['pno'];
                $nt = $nr['note_type'];
                if (!isset($nMap[$p])) $nMap[$p] = ['oper'=>[],'design'=>[]];
                $imgs = [];
                if ($nr['img_files']) {
                    $fArr = explode("\t", $nr['img_files']);
                    $iArr = explode("\t", $nr['img_ids']);
                    foreach ($fArr as $fi => $fn) $imgs[] = ['f'=>$fn,'i'=>(int)($iArr[$fi]??0)];
                }
                $nMap[$p][$nt][] = ['id'=>(int)$nr['note_id'],'text'=>$nr['note_text'],'by'=>$nr['created_by'],'at'=>$nr['created_at'],'imgs'=>$imgs];
            }
            foreach ($rows as &$row) {
                $p = (int)$row['ProcessNo'];
                $operSrc   = $linkMap[$p]['oper']   ?? $p;
                $designSrc = $linkMap[$p]['design']  ?? $p;
                $row['oper_notes']      = $nMap[$operSrc]['oper']    ?? [];
                $row['design_notes']    = $can_see_design ? ($nMap[$designSrc]['design'] ?? []) : [];
                $row['oper_link_src']   = isset($linkMap[$p]['oper'])   ? $linkMap[$p]['oper']   : null;
                $row['design_link_src'] = $can_see_design && isset($linkMap[$p]['design']) ? $linkMap[$p]['design'] : null;
            }
            unset($row);
            echo json_encode(['success'=>true,'data'=>$rows]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 取得製程備註 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'get_process_notes') {
        try {
            $pno      = intval($_POST['process_no']);
            $nt_filter = trim($_POST['note_type'] ?? '');

            // Links where this process is the subordinate (dst)
            $dstQ = $pdo->prepare("SELECT l.link_id, l.src_pno, l.link_type, p.ProcessName AS src_name FROM process_note_links l LEFT JOIN process_no p ON p.ProcessNo=l.src_pno WHERE l.dst_pno=?");
            $dstQ->execute([$pno]);
            $dstLinkRows = $dstQ->fetchAll(PDO::FETCH_ASSOC);
            $linkedTypes = [];
            foreach ($dstLinkRows as $dl) { $linkedTypes[$dl['link_type']] = $dl; }

            // Links where this process is the source (src)
            $srcQ = $pdo->prepare("SELECT l.link_id, l.dst_pno, l.link_type, p.ProcessName AS dst_name FROM process_note_links l LEFT JOIN process_no p ON p.ProcessNo=l.dst_pno WHERE l.src_pno=?");
            $srcQ->execute([$pno]);
            $srcLinkRows = $srcQ->fetchAll(PDO::FETCH_ASSOC);

            $note_types = ['oper'];
            if ($can_see_design) $note_types[] = 'design';
            if ($nt_filter && in_array($nt_filter, ['oper','design'])) $note_types = [$nt_filter];

            $rows = [];
            $imgStmt = $pdo->prepare("SELECT img_id, file_name, original_name FROM note_images WHERE note_id=? AND note_type=? ORDER BY sort_order,img_id");
            foreach ($note_types as $nt) {
                $fetch_pno = isset($linkedTypes[$nt]) ? (int)$linkedTypes[$nt]['src_pno'] : $pno;
                $stmt = $pdo->prepare("SELECT pn.note_id, pn.note_type, pn.note_text, pn.created_by, pn.created_by_id, pn.created_at, pn.updated_at, pn.updated_by, pn.updated_by_id FROM process_notes pn WHERE pn.process_no_id=? AND pn.note_type=? ORDER BY pn.created_at ASC");
                $stmt->execute([$fetch_pno, $nt]);
                $typeRows = $stmt->fetchAll(PDO::FETCH_ASSOC);
                foreach ($typeRows as &$r) {
                    $imgStmt->execute([$r['note_id'], 'process_'.$r['note_type']]);
                    $r['images'] = $imgStmt->fetchAll(PDO::FETCH_ASSOC);
                    if (isset($linkedTypes[$nt])) {
                        $r['linked_from_pno']  = (int)$linkedTypes[$nt]['src_pno'];
                        $r['linked_from_name'] = $linkedTypes[$nt]['src_name'];
                        $r['link_id']          = (int)$linkedTypes[$nt]['link_id'];
                    }
                }
                unset($r);
                $rows = array_merge($rows, $typeRows);
            }
            echo json_encode(['success'=>true,'data'=>$rows,'links_as_dst'=>$dstLinkRows,'links_as_src'=>$srcLinkRows]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 儲存製程備註 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'save_process_note') {
        try {
            if (!$can_proc_edit) throw new Exception('無備註編輯權限（需 A 或含D權限）');
            $note_id = intval($_POST['note_id'] ?? 0);
            $pno     = intval($_POST['process_no']);
            $nt      = in_array($_POST['note_type']??'', ['oper','design']) ? $_POST['note_type'] : 'oper';
            $text    = trim($_POST['note_text'] ?? '');
            if (!$pno) throw new Exception('製程不可為空');
            $op      = _get_operator($pdo, $uid);
            $ntLabel = ($nt === 'design') ? '技術備註' : '作業備註';
            $pn_tname = _target_display_name($pdo, 'process', (string)$pno);
            if ($note_id) {
                $ownQ2 = $pdo->prepare("SELECT created_by_id, note_text FROM process_notes WHERE note_id=?");
                $ownQ2->execute([$note_id]);
                $ownRow2 = $ownQ2->fetch(PDO::FETCH_ASSOC);
                if ($ownRow2 === false) throw new Exception('找不到此備註');
                $ownerId2 = intval($ownRow2['created_by_id']);
                $old_pn_text = $ownRow2['note_text'] ?? '';
                $pdo->prepare("UPDATE process_notes SET note_text=?, updated_at=NOW(), updated_by_id=?, updated_by=? WHERE note_id=?")->execute([$text,$uid,$op,$note_id]);
                if ($old_pn_text !== $text) {
                    _log_audit($pdo,'update','process','note:pno:'.$pno,$pn_tname,[['field'=>$ntLabel,'old'=>mb_strimwidth($old_pn_text,0,120,'…'),'new'=>mb_strimwidth($text,0,120,'…')]],$uid,$op);
                }
            } else {
                $pdo->prepare("INSERT INTO process_notes (process_no_id,note_type,note_text,created_by_id,created_by) VALUES (?,?,?,?,?)")->execute([$pno,$nt,$text,$uid,$op]);
                $note_id = intval($pdo->lastInsertId());
                _log_audit($pdo,'insert','process','note:pno:'.$pno,$pn_tname,[['field'=>$ntLabel,'old'=>'','new'=>mb_strimwidth($text,0,120,'…')]],$uid,$op);
            }
            echo json_encode(['success'=>true,'note_id'=>$note_id]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 刪除製程備註 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'delete_process_note') {
        try {
            if (!$can_proc_edit) throw new Exception('無刪除備註權限');
            $note_id = intval($_POST['note_id']);
            // 只有建立者或A權限可刪除；同時取得 pno/type 供審計紀錄使用
            $ownQ3 = $pdo->prepare("SELECT created_by_id, process_no_id, note_type FROM process_notes WHERE note_id=?");
            $ownQ3->execute([$note_id]);
            $ownRow3 = $ownQ3->fetch(PDO::FETCH_ASSOC);
            if ($ownRow3 === false) throw new Exception('找不到此備註');
            $ownerId3 = intval($ownRow3['created_by_id']);
            $del_pno3   = intval($ownRow3['process_no_id']);
            $del_ntype3 = $ownRow3['note_type'] === 'design' ? '技術備註' : '作業備註';
            $imgs = $pdo->prepare("SELECT file_name FROM note_images WHERE note_id=? AND note_type IN ('process_oper','process_design')");
            $imgs->execute([$note_id]);
            foreach ($imgs->fetchAll(PDO::FETCH_COLUMN) as $fn) {
                $fp = $_nas_dir . $fn;
                if (file_exists($fp)) @unlink($fp);
            }
            $pdo->prepare("DELETE FROM note_images WHERE note_id=? AND note_type IN ('process_oper','process_design')")->execute([$note_id]);
            $pdo->prepare("DELETE FROM process_notes WHERE note_id=?")->execute([$note_id]);
            $del_pn3_tname = _target_display_name($pdo, 'process', (string)$del_pno3);
            _log_audit($pdo,'delete','process','note:pno:'.$del_pno3,$del_pn3_tname,null,$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 複製製程備註 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'copy_process_notes') {
        try {
            if (!$can_proc_edit) throw new Exception('無備註操作權限');
            $src_pno   = intval($_POST['src_pno']);
            $dst_pno   = intval($_POST['dst_pno']);
            $types_raw = trim($_POST['copy_types'] ?? '');
            $mode      = trim($_POST['copy_mode']  ?? '');
            if (!$src_pno || !$dst_pno) throw new Exception('來源/目標製程不可為空');
            if ($src_pno === $dst_pno) throw new Exception('來源與目標製程不可相同');
            if (!in_array($types_raw, ['oper','design','both'])) throw new Exception('備註類型參數錯誤');
            if (!in_array($mode, ['append','replace'])) throw new Exception('複製模式參數錯誤');
            $copy_types = ($types_raw === 'both') ? ['oper','design'] : [$types_raw];
            $op = _get_operator($pdo, $uid);
            $nas_dir = $_nas_dir;
            // 非A權限：若目標製程有非自己建立的備註，禁止使用取代模式
            if ($mode === 'replace' && $permission_code !== 'A') {
                foreach ($copy_types as $nt) {
                    $chkOwn = $pdo->prepare("SELECT COUNT(*) FROM process_notes WHERE process_no_id=? AND note_type=? AND (created_by_id IS NULL OR created_by_id != ?)");
                    $chkOwn->execute([$dst_pno, $nt, $uid]);
                    if ((int)$chkOwn->fetchColumn() > 0) {
                        throw new Exception('目標製程含有非本人建立的備註，只能使用「僅複製（附加）」模式');
                    }
                }
            }
            $pdo->beginTransaction();
            $copied = 0;
            foreach ($copy_types as $nt) {
                if ($mode === 'replace') {
                    $nids = $pdo->prepare("SELECT note_id FROM process_notes WHERE process_no_id=? AND note_type=?");
                    $nids->execute([$dst_pno, $nt]);
                    $imgDel = $pdo->prepare("SELECT file_name FROM note_images WHERE note_id=? AND note_type=?");
                    foreach ($nids->fetchAll(PDO::FETCH_COLUMN) as $nid) {
                        $imgDel->execute([$nid, 'process_'.$nt]);
                        foreach ($imgDel->fetchAll(PDO::FETCH_COLUMN) as $fn) {
                            $fp = $nas_dir.$fn; if (file_exists($fp)) @unlink($fp);
                        }
                        $pdo->prepare("DELETE FROM note_images WHERE note_id=? AND note_type=?")->execute([$nid,'process_'.$nt]);
                    }
                    $pdo->prepare("DELETE FROM process_notes WHERE process_no_id=? AND note_type=?")->execute([$dst_pno, $nt]);
                }
                $srcNotes = $pdo->prepare("SELECT note_id, note_text FROM process_notes WHERE process_no_id=? AND note_type=? ORDER BY created_at ASC");
                $srcNotes->execute([$src_pno, $nt]);
                $imgSrc = $pdo->prepare("SELECT file_name, original_name FROM note_images WHERE note_id=? AND note_type=? ORDER BY sort_order,img_id");
                $imgIns = $pdo->prepare("INSERT INTO note_images (note_type,note_id,file_name,original_name,file_size,created_by_id) VALUES (?,?,?,?,?,?)");
                foreach ($srcNotes->fetchAll(PDO::FETCH_ASSOC) as $sn) {
                    $pdo->prepare("INSERT INTO process_notes (process_no_id,note_type,note_text,created_by_id,created_by) VALUES (?,?,?,?,?)")
                        ->execute([$dst_pno, $nt, $sn['note_text'], $uid, $op]);
                    $new_nid = intval($pdo->lastInsertId());
                    $imgSrc->execute([$sn['note_id'], 'process_'.$nt]);
                    foreach ($imgSrc->fetchAll(PDO::FETCH_ASSOC) as $img) {
                        $src_fp = $nas_dir.$img['file_name'];
                        if (!file_exists($src_fp)) continue;
                        $ext    = strtolower(pathinfo($img['file_name'], PATHINFO_EXTENSION));
                        $new_fn = date('Ymd_His_').bin2hex(random_bytes(4)).'.'.$ext;
                        if (@copy($src_fp, $nas_dir.$new_fn)) {
                            $imgIns->execute(['process_'.$nt, $new_nid, $new_fn, $img['original_name'], filesize($nas_dir.$new_fn)?:0, $uid]);
                        }
                    }
                    $copied++;
                }
            }
            $pdo->commit();
            _log_audit($pdo,'copy','process_notes',"src:{$src_pno}→dst:{$dst_pno}","{$types_raw}({$mode})",null,$uid,$op);
            echo json_encode(['success'=>true,'copied'=>$copied]);
        } catch(Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 製程備註連動 ─────────────────────────────────────────────────────
    if ($_POST['action'] === 'manage_process_links') {
        try {
            $op_code = trim($_POST['op'] ?? '');
            if ($op_code === 'get') {
                $pno = intval($_POST['process_no']);
                $dQ = $pdo->prepare("SELECT l.link_id, l.src_pno, l.link_type, p.ProcessName AS src_name FROM process_note_links l LEFT JOIN process_no p ON p.ProcessNo=l.src_pno WHERE l.dst_pno=?");
                $dQ->execute([$pno]);
                $sQ = $pdo->prepare("SELECT l.link_id, l.dst_pno, l.link_type, p.ProcessName AS dst_name FROM process_note_links l LEFT JOIN process_no p ON p.ProcessNo=l.dst_pno WHERE l.src_pno=?");
                $sQ->execute([$pno]);
                echo json_encode(['success'=>true,'as_dst'=>$dQ->fetchAll(PDO::FETCH_ASSOC),'as_src'=>$sQ->fetchAll(PDO::FETCH_ASSOC)]);
            } elseif ($op_code === 'set') {
                if (!$can_proc_edit) throw new Exception('無連動設定權限');
                $src_pno   = intval($_POST['src_pno']);
                $dst_pno   = intval($_POST['dst_pno']);
                $types_raw = trim($_POST['link_types'] ?? '');
                if (!$src_pno || !$dst_pno) throw new Exception('來源/目標製程不可為空');
                if ($src_pno === $dst_pno) throw new Exception('來源與目標製程不可相同');
                // Prevent circular links: src must not itself be a dst
                $chk = $pdo->prepare("SELECT COUNT(*) FROM process_note_links WHERE dst_pno=?");
                $chk->execute([$src_pno]);
                if ((int)$chk->fetchColumn() > 0) throw new Exception('來源製程本身已連動自其他製程，不可再設為來源（避免循環連動）');
                $link_types = ($types_raw === 'both') ? ['oper','design'] : [in_array($types_raw,['oper','design'])?$types_raw:'oper'];
                $op = _get_operator($pdo, $uid);
                $ins = $pdo->prepare("INSERT INTO process_note_links (src_pno,dst_pno,link_type,created_by_id,created_by) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE src_pno=VALUES(src_pno),created_by_id=VALUES(created_by_id),created_by=VALUES(created_by),created_at=NOW()");
                foreach ($link_types as $lt) { $ins->execute([$src_pno, $dst_pno, $lt, $uid, $op]); }
                _log_audit($pdo,'insert','process_notes',"link:src{$src_pno}→dst{$dst_pno}","{$types_raw}",null,$uid,$op);
                echo json_encode(['success'=>true]);
            } elseif ($op_code === 'unlink') {
                if (!$can_proc_edit) throw new Exception('無連動設定權限');
                $link_id = intval($_POST['link_id']);
                $dst_pno = intval($_POST['dst_pno']);
                $lnk = $pdo->prepare("SELECT src_pno, link_type FROM process_note_links WHERE link_id=? AND dst_pno=?");
                $lnk->execute([$link_id, $dst_pno]);
                $lnkRow = $lnk->fetch(PDO::FETCH_ASSOC);
                if (!$lnkRow) throw new Exception('連動記錄不存在');
                $src_pno = (int)$lnkRow['src_pno'];
                $nt      = $lnkRow['link_type'];
                $op      = _get_operator($pdo, $uid);
                $nas_dir = $_nas_dir;
                $pdo->beginTransaction();
                // Copy notes from src to dst
                $srcNotes = $pdo->prepare("SELECT note_id, note_text FROM process_notes WHERE process_no_id=? AND note_type=? ORDER BY created_at ASC");
                $srcNotes->execute([$src_pno, $nt]);
                $imgSrc = $pdo->prepare("SELECT file_name, original_name FROM note_images WHERE note_id=? AND note_type=? ORDER BY sort_order,img_id");
                $imgIns = $pdo->prepare("INSERT INTO note_images (note_type,note_id,file_name,original_name,file_size,created_by_id) VALUES (?,?,?,?,?,?)");
                foreach ($srcNotes->fetchAll(PDO::FETCH_ASSOC) as $sn) {
                    $pdo->prepare("INSERT INTO process_notes (process_no_id,note_type,note_text,created_by_id,created_by) VALUES (?,?,?,?,?)")
                        ->execute([$dst_pno, $nt, $sn['note_text'], $uid, $op]);
                    $new_nid = intval($pdo->lastInsertId());
                    $imgSrc->execute([$sn['note_id'], 'process_'.$nt]);
                    foreach ($imgSrc->fetchAll(PDO::FETCH_ASSOC) as $img) {
                        $src_fp = $nas_dir.$img['file_name'];
                        if (!file_exists($src_fp)) continue;
                        $ext    = strtolower(pathinfo($img['file_name'], PATHINFO_EXTENSION));
                        $new_fn = date('Ymd_His_').bin2hex(random_bytes(4)).'.'.$ext;
                        if (@copy($src_fp, $nas_dir.$new_fn)) {
                            $imgIns->execute(['process_'.$nt, $new_nid, $new_fn, $img['original_name'], filesize($nas_dir.$new_fn)?:0, $uid]);
                        }
                    }
                }
                $pdo->prepare("DELETE FROM process_note_links WHERE link_id=?")->execute([$link_id]);
                $pdo->commit();
                _log_audit($pdo,'delete','process_notes',"link_id:{$link_id}","unlink src:{$src_pno}→dst:{$dst_pno}({$nt})",null,$uid,$op);
                echo json_encode(['success'=>true]);
            } else {
                throw new Exception('未知操作');
            }
        } catch(Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 儲存製程（新增/編輯 process_no）─────────────────────────────────
    if ($_POST['action'] === 'save_process') {
        try {
            if (!$can_proc_edit) throw new Exception('無新增/修改製程權限（需 A 或含D權限）');
            $is_new       = intval($_POST['is_new'] ?? 0);
            $pno          = intval($_POST['process_no']);
            $pname        = trim($_POST['process_name'] ?? '');
            $tid_raw      = trim($_POST['type_ids'] ?? '[]');
            $is_excl_qc   = intval($_POST['is_exclude_qc'] ?? 0) ? 1 : 0;
            $type_ids = array_values(array_filter(array_map('intval', json_decode($tid_raw, true) ?: [])));
            if (!$pno) throw new Exception('製程ID不可為空');
            if (!$pname) throw new Exception('製程名稱不可為空');
            $op = _get_operator($pdo, $uid);
            $primary_tid = !empty($type_ids) ? $type_ids[0] : null;
            $pdo->beginTransaction();
            if ($is_new) {
                $chk = $pdo->prepare("SELECT COUNT(*) FROM process_no WHERE ProcessNo=?");
                $chk->execute([$pno]);
                if ((int)$chk->fetchColumn() > 0) throw new Exception("製程ID「{$pno}」已存在");
                $pdo->prepare("INSERT INTO process_no (ProcessNo, ProcessName, process_type_id, is_exclude_qc) VALUES (?,?,?,?)")->execute([$pno, $pname, $primary_tid, $is_excl_qc]);
                _log_audit($pdo,'insert','process','process:'.$pno,$pname,null,$uid,$op);
            } else {
                $old = $pdo->prepare("SELECT ProcessName, COALESCE(is_exclude_qc,0) AS is_exclude_qc FROM process_no WHERE ProcessNo=?"); $old->execute([$pno]);
                $oldRow = $old->fetch(PDO::FETCH_ASSOC) ?: [];
                $pdo->prepare("UPDATE process_no SET ProcessName=?, process_type_id=?, is_exclude_qc=? WHERE ProcessNo=?")->execute([$pname, $primary_tid, $is_excl_qc, $pno]);
                $ch = _diff_rows($oldRow, ['ProcessName'=>$pname,'is_exclude_qc'=>(string)$is_excl_qc], ['ProcessName','is_exclude_qc']);
                if (!empty($ch)) _log_audit($pdo,'update','process','process:'.$pno,$pname,$ch,$uid,$op);
            }
            $pdo->prepare("DELETE FROM process_type_process_map WHERE process_no_id=?")->execute([$pno]);
            if (!empty($type_ids)) {
                $ins = $pdo->prepare("INSERT IGNORE INTO process_type_process_map (process_type_id,process_no_id) VALUES (?,?)");
                foreach ($type_ids as $tid) { $ins->execute([$tid, $pno]); }
            }
            $pdo->commit();
            echo json_encode(['success'=>true]);
        } catch(Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 刪除製程（檢查使用情況）──────────────────────────────────────────
    if ($_POST['action'] === 'delete_process') {
        try {
            if (!$can_proc_edit) throw new Exception('無刪除製程權限（需 A 或含D權限）');
            $pno = intval($_POST['process_no']);
            $blocks = [];
            $chks = [
                ['bom_ing',         'process_no', '加工單(bom_ing)'],
                ['qa_abnormal_base','process_no', '品質異常單'],
            ];
            foreach ($chks as $ck) {
                try {
                    $s = $pdo->prepare("SELECT COUNT(*) FROM `{$ck[0]}` WHERE `{$ck[1]}`=?");
                    $s->execute([$pno]);
                    if ($s->fetchColumn() > 0) $blocks[] = $ck[2];
                } catch(Exception $ex){}
            }
            if (!empty($blocks)) throw new Exception("此製程已被以下地方使用，無法刪除：" . implode('、', $blocks));
            $pdo->beginTransaction();
            $pdo->prepare("DELETE FROM process_type_process_map WHERE process_no_id=?")->execute([$pno]);
            // delete notes + images
            $nids = $pdo->prepare("SELECT note_id FROM process_notes WHERE process_no_id=?"); $nids->execute([$pno]);
            $imgDel = $pdo->prepare("SELECT file_name FROM note_images WHERE note_id=? AND note_type IN ('process_oper','process_design')");
            foreach ($nids->fetchAll(PDO::FETCH_COLUMN) as $nid) {
                $imgDel->execute([$nid]);
                foreach ($imgDel->fetchAll(PDO::FETCH_COLUMN) as $fn) {
                    $fp = $_nas_dir . $fn; if (file_exists($fp)) @unlink($fp);
                }
                $pdo->prepare("DELETE FROM note_images WHERE note_id=? AND note_type IN ('process_oper','process_design')")->execute([$nid]);
            }
            $pdo->prepare("DELETE FROM process_notes WHERE process_no_id=?")->execute([$pno]);
            $pdo->prepare("DELETE FROM process_no WHERE ProcessNo=?")->execute([$pno]);
            $pdo->commit();
            _log_audit($pdo,'delete','process','process:'.$pno,''.$pno,null,$uid,_get_operator($pdo,$uid));
            echo json_encode(['success'=>true]);
        } catch(Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 管理製程大類（dict settings）──────────────────────────────────────
    if ($_POST['action'] === 'manage_process_types') {
        try {
            $op = trim($_POST['op'] ?? '');
            if ($op === 'list') {
                $q = $pdo->query("SELECT pt.process_type_id, pt.process_type, COALESCE(pt.sort_order,0) AS sort_order, COALESCE(pt.is_active,1) AS is_active, COUNT(DISTINCT ppm.process_no_id) AS process_count FROM process_type pt LEFT JOIN process_type_process_map ppm ON ppm.process_type_id=pt.process_type_id GROUP BY pt.process_type_id ORDER BY COALESCE(pt.sort_order,0), pt.process_type_id");
                echo json_encode(['success'=>true,'data'=>$q->fetchAll(PDO::FETCH_ASSOC)]);
            } elseif ($op === 'save') {
                if (!$can_dict_part) throw new Exception('無字典編輯權限（需要 A、CDR 或 CDRU 權限）');
                $id   = intval($_POST['id'] ?? 0);
                $name = trim($_POST['name'] ?? '');
                if (!$name) throw new Exception('名稱不可為空');
                $op_name = _get_operator($pdo, $uid);
                if ($id) {
                    $dup = $pdo->prepare("SELECT COUNT(*) FROM process_type WHERE LOWER(process_type)=LOWER(?) AND process_type_id<>?");
                    $dup->execute([$name, $id]);
                    if ((int)$dup->fetchColumn() > 0) throw new Exception("已存在相同名稱「{$name}」的製程大類");
                    $old_pt = $pdo->prepare("SELECT process_type FROM process_type WHERE process_type_id=?"); $old_pt->execute([$id]); $old_pt_row = $old_pt->fetch(PDO::FETCH_ASSOC) ?: [];
                    $pdo->prepare("UPDATE process_type SET process_type=?, modified_by=?, modified_at=NOW() WHERE process_type_id=?")->execute([$name, $uid, $id]);
                    $ch_pt = _diff_rows($old_pt_row, ['process_type'=>$name], ['process_type']);
                    if (!empty($ch_pt)) _log_audit($pdo,'update','process','process-type:'.$id,$name,$ch_pt,$uid,$op_name);
                } else {
                    $dup = $pdo->prepare("SELECT COUNT(*) FROM process_type WHERE LOWER(process_type)=LOWER(?)");
                    $dup->execute([$name]);
                    if ((int)$dup->fetchColumn() > 0) throw new Exception("已存在相同名稱「{$name}」的製程大類");
                    $max = $pdo->query("SELECT COALESCE(MAX(sort_order),0)+1 FROM process_type")->fetchColumn();
                    $new_id_raw = intval($_POST['new_id'] ?? 0);
                    if ($new_id_raw > 0) {
                        $chk_id = $pdo->prepare("SELECT COUNT(*) FROM process_type WHERE process_type_id=?");
                        $chk_id->execute([$new_id_raw]);
                        if ((int)$chk_id->fetchColumn() > 0) throw new Exception("製程大類ID「{$new_id_raw}」已存在");
                        $pdo->prepare("INSERT INTO process_type (process_type_id, process_type, sort_order, is_active, modified_by) VALUES (?,?,?,1,?)")->execute([$new_id_raw, $name, $max, $uid]);
                        $id = $new_id_raw;
                    } else {
                        $pdo->prepare("INSERT INTO process_type (process_type, sort_order, is_active, modified_by) VALUES (?,?,1,?)")->execute([$name, $max, $uid]);
                        $id = intval($pdo->lastInsertId());
                    }
                    _log_audit($pdo,'insert','process','process-type:'.$id,$name,null,$uid,$op_name);
                }
                echo json_encode(['success'=>true,'id'=>$id]);
            } elseif ($op === 'check_delete') {
                $id = intval($_POST['id']);
                $c1 = $pdo->prepare("SELECT COUNT(*) FROM process_type_process_map WHERE process_type_id=?"); $c1->execute([$id]);
                if ((int)$c1->fetchColumn() > 0) { echo json_encode(['can_delete'=>false,'reason'=>'此製程大類已有製程綁定，無法刪除']); exit; }
                $c2 = $pdo->prepare("SELECT COUNT(*) FROM process_no WHERE process_type_id=?"); $c2->execute([$id]);
                echo json_encode((int)$c2->fetchColumn() > 0 ? ['can_delete'=>false,'reason'=>'此製程大類被製程的主類型使用，無法刪除'] : ['can_delete'=>true]);
            } elseif ($op === 'delete') {
                if (!$can_dict_part) throw new Exception('無字典編輯權限（需要 A、CDR 或 CDRU 權限）');
                $id = intval($_POST['id']);
                $c1 = $pdo->prepare("SELECT COUNT(*) FROM process_type_process_map WHERE process_type_id=?"); $c1->execute([$id]);
                if ((int)$c1->fetchColumn() > 0) throw new Exception("此製程大類已有製程綁定，無法刪除");
                $c2 = $pdo->prepare("SELECT COUNT(*) FROM process_no WHERE process_type_id=?"); $c2->execute([$id]);
                if ((int)$c2->fetchColumn() > 0) throw new Exception("此製程大類被製程的主類型使用，無法刪除");
                $del_pt_name = $pdo->prepare("SELECT process_type FROM process_type WHERE process_type_id=?"); $del_pt_name->execute([$id]); $del_pt_name = $del_pt_name->fetchColumn();
                $pdo->prepare("DELETE FROM process_type WHERE process_type_id=?")->execute([$id]);
                _log_audit($pdo,'delete','process','process-type:'.$id,$del_pt_name?:('id:'.$id),null,$uid,_get_operator($pdo,$uid));
                echo json_encode(['success'=>true]);
            } elseif ($op === 'reorder') {
                if (!$can_dict_part) throw new Exception('無字典編輯權限（需要 A、CDR 或 CDRU 權限）');
                $ids = array_values(array_filter(explode(',', $_POST['ids'] ?? '')));
                $upd = $pdo->prepare("UPDATE process_type SET sort_order=? WHERE process_type_id=?");
                foreach ($ids as $i => $tid) { $upd->execute([$i, intval($tid)]); }
                echo json_encode(['success'=>true]);
            } else {
                throw new Exception('未知操作');
            }
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 取得製程大類列表（for process modal type picker）────────────────
    if ($_POST['action'] === 'get_all_process_types') {
        try {
            $q = $pdo->query("SELECT process_type_id, process_type FROM process_type WHERE COALESCE(is_active,1)=1 ORDER BY COALESCE(sort_order,0), process_type_id");
            echo json_encode(['success'=>true,'data'=>$q->fetchAll(PDO::FETCH_ASSOC)]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 取得單一製程詳情（for edit modal）──────────────────────────────
    if ($_POST['action'] === 'get_process_detail') {
        try {
            $pno = intval($_POST['process_no']);
            $row = $pdo->prepare("SELECT ProcessNo, ProcessName, process_type_id, COALESCE(is_exclude_qc,0) AS is_exclude_qc FROM process_no WHERE ProcessNo=?");
            $row->execute([$pno]);
            $data = $row->fetch(PDO::FETCH_ASSOC);
            if (!$data) throw new Exception('找不到製程');
            // Union map table + legacy process_no.process_type_id
            $types = $pdo->prepare(
                "SELECT DISTINCT t.process_type_id FROM process_type t WHERE t.process_type_id IN (
                    SELECT process_type_id FROM process_type_process_map WHERE process_no_id=?
                    UNION
                    SELECT process_type_id FROM process_no WHERE ProcessNo=? AND process_type_id IS NOT NULL
                )"
            );
            $types->execute([$pno, $pno]);
            $data['type_ids'] = array_column($types->fetchAll(PDO::FETCH_ASSOC), 'process_type_id');
            echo json_encode(['success'=>true,'data'=>$data]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 批次修改製程大類 ──────────────────────────────────────────────────
    if ($_POST['action'] === 'batch_process_type') {
        try {
            if (!$can_proc_edit) throw new Exception('無批次修改製程大類權限（需 A 或含D權限）');
            $pnos    = array_values(array_filter(array_map('intval', json_decode($_POST['process_nos']??'[]', true) ?: [])));
            $add_tid = intval($_POST['add_type_id'] ?? 0);
            $rm_tid  = intval($_POST['rm_type_id']  ?? 0);
            if (empty($pnos)) throw new Exception('未選擇製程');
            if (!$add_tid && !$rm_tid) throw new Exception('未指定大類操作');
            $pdo->beginTransaction();
            foreach ($pnos as $pno) {
                if ($rm_tid) {
                    $pdo->prepare("DELETE FROM process_type_process_map WHERE process_no_id=? AND process_type_id=?")->execute([$pno, $rm_tid]);
                }
                if ($add_tid) {
                    $pdo->prepare("INSERT IGNORE INTO process_type_process_map (process_type_id, process_no_id) VALUES (?,?)")->execute([$add_tid, $pno]);
                }
            }
            $pdo->commit();
            echo json_encode(['success'=>true]);
        } catch(Exception $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['success'=>false,'message'=>$e->getMessage()]);
        }
        exit;
    }

    // ── 上傳備註圖片（備註需先儲存取得 note_id）──────────────────────────
    if ($_POST['action'] === 'upload_note_image') {
        try {
            if (!$can_edit_design) throw new Exception('無上傳圖片權限');
            $allowed_types = ['process_oper','process_design','part_design','customer_design'];
            $nt      = trim($_POST['note_type'] ?? '');
            $note_id = intval($_POST['note_id'] ?? 0);
            if (!in_array($nt, $allowed_types) || !$note_id) throw new Exception('參數不完整');
            if (!isset($_FILES['image']) || $_FILES['image']['error'] !== UPLOAD_ERR_OK) throw new Exception('上傳失敗（檔案錯誤）');
            $blocked_ext = ['php','php3','php4','php5','phtml','phar','exe','bat','sh','cmd','com','msi','vbs','vbe','js','jse','wsf','wsh','asp','aspx','jsp','py','rb','pl','cgi','htaccess','htpasswd'];
            $orig = basename($_FILES['image']['name']);
            $ext  = strtolower(pathinfo($orig, PATHINFO_EXTENSION));
            if (in_array($ext, $blocked_ext) || $ext === '') throw new Exception('不允許上傳此類型檔案');
            $nas_dir = $_nas_dir;
            if (!is_dir($nas_dir)) {
                if (!mkdir($nas_dir, 0777, true)) throw new Exception('無法建立 NAS 目錄');
            }
            $fname = date('Ymd_His_') . bin2hex(random_bytes(4)) . '.' . $ext;
            if (!move_uploaded_file($_FILES['image']['tmp_name'], $nas_dir . $fname)) throw new Exception('檔案移動失敗');
            $pdo->prepare("INSERT INTO note_images (note_type,note_id,file_name,original_name,file_size,created_by_id) VALUES (?,?,?,?,?,?)")
                ->execute([$nt, $note_id, $fname, $orig, intval($_FILES['image']['size']), $uid]);
            $img_id = intval($pdo->lastInsertId());
            echo json_encode(['success'=>true,'img_id'=>$img_id,'file_name'=>$fname,'original_name'=>$orig]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 刪除備註圖片 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'delete_note_image') {
        try {
            if (!$can_edit_design) throw new Exception('無刪除圖片權限');
            $img_id = intval($_POST['img_id']);
            $row = $pdo->prepare("SELECT file_name FROM note_images WHERE img_id=?");
            $row->execute([$img_id]);
            $fn = $row->fetchColumn();
            if ($fn) { $fp = $_nas_dir . $fn; if (file_exists($fp)) @unlink($fp); }
            $pdo->prepare("DELETE FROM note_images WHERE img_id=?")->execute([$img_id]);
            echo json_encode(['success'=>true]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 設計備註（料號/客戶）──────────────────────────────────────────
    if ($_POST['action'] === 'get_design_notes') {
        try {
            if (!$can_see_design) throw new Exception('無查看設計備註權限');
            $ttype = in_array($_POST['target_type']??'', ['part','customer']) ? $_POST['target_type'] : null;
            $tid   = trim($_POST['target_id'] ?? '');
            if (!$ttype || !$tid) throw new Exception('參數不完整');
            $stmt = $pdo->prepare("SELECT note_id, note_text, created_by, created_by_id, created_at, updated_at, updated_by, updated_by_id FROM design_notes WHERE target_type=? AND target_id=? ORDER BY created_at ASC");
            $stmt->execute([$ttype, $tid]);
            $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
            $img_nt = ($ttype === 'part') ? 'part_design' : 'customer_design';
            $imgStmt = $pdo->prepare("SELECT img_id, file_name, original_name FROM note_images WHERE note_id=? AND note_type=? ORDER BY sort_order,img_id");
            foreach ($rows as &$r) {
                $imgStmt->execute([$r['note_id'], $img_nt]);
                $r['images'] = $imgStmt->fetchAll(PDO::FETCH_ASSOC);
            }
            echo json_encode(['success'=>true,'data'=>$rows]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'save_design_note') {
        try {
            if (!$can_edit_design) throw new Exception('無設計備註編輯權限');
            $note_id = intval($_POST['note_id'] ?? 0);
            $ttype   = in_array($_POST['target_type']??'', ['part','customer']) ? $_POST['target_type'] : null;
            $tid     = trim($_POST['target_id'] ?? '');
            $text    = trim($_POST['note_text'] ?? '');
            if (!$ttype || !$tid) throw new Exception('參數不完整');
            $op = _get_operator($pdo, $uid);
            $dn_tname = _target_display_name($pdo, $ttype, $tid);
            if ($note_id) {
                $ownQ = $pdo->prepare("SELECT created_by_id, updated_by_id, note_text FROM design_notes WHERE note_id=?");
                $ownQ->execute([$note_id]);
                $ownRow = $ownQ->fetch(PDO::FETCH_ASSOC);
                if ($ownRow === false) throw new Exception('找不到此備註');
                // 通知對象：有修改紀錄則通知最後修改者，否則通知建立者
                $ownerId = intval($ownRow['updated_by_id'] ?: $ownRow['created_by_id']);
                $old_dn_text = $ownRow['note_text'] ?? '';
                $pdo->prepare("UPDATE design_notes SET note_text=?, updated_at=NOW(), updated_by_id=?, updated_by=? WHERE note_id=?")->execute([$text,$uid,$op,$note_id]);
                if ($old_dn_text !== $text) {
                    _log_audit($pdo,'update',$ttype,$tid,$dn_tname,[['field'=>'設計備註','old'=>mb_strimwidth($old_dn_text,0,120,'…'),'new'=>mb_strimwidth($text,0,120,'…')]],$uid,$op);
                    // 若操作者不是應通知對象，發送通知給最後修改者（無修改紀錄則為建立者）
                    if ($ownerId > 0 && $ownerId !== intval($uid)) {
                        _notify_design_note($pdo, $ownerId, $note_id, $ttype, $tid, 'modified', $uid, $op, $old_dn_text, $text);
                    }
                }
            } else {
                $pdo->prepare("INSERT INTO design_notes (target_type,target_id,note_text,created_by_id,created_by) VALUES (?,?,?,?,?)")->execute([$ttype,$tid,$text,$uid,$op]);
                $note_id = intval($pdo->lastInsertId());
                _log_audit($pdo,'insert',$ttype,$tid,$dn_tname,[['field'=>'設計備註','old'=>'','new'=>mb_strimwidth($text,0,120,'…')]],$uid,$op);
            }
            echo json_encode(['success'=>true,'note_id'=>$note_id]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    if ($_POST['action'] === 'delete_design_note') {
        try {
            if (!$can_edit_design) throw new Exception('無刪除設計備註權限');
            $note_id = intval($_POST['note_id']);
            // 取得備註資料（含建立者與文字供通知用）
            $ownQ = $pdo->prepare("SELECT created_by_id, updated_by_id, target_id, target_type AS db_ttype, note_text FROM design_notes WHERE note_id=?");
            $ownQ->execute([$note_id]);
            $ownRow = $ownQ->fetch(PDO::FETCH_ASSOC);
            if ($ownRow === false) throw new Exception('找不到此備註');
            // 通知對象：有修改紀錄則通知最後修改者，否則通知建立者
            $ownerId    = intval($ownRow['updated_by_id'] ?: $ownRow['created_by_id']);
            $del_dn_old = $ownRow['note_text'] ?? '';
            $ttype      = in_array($_POST['target_type']??'', ['part','customer']) ? $_POST['target_type'] : ($ownRow['db_ttype'] ?? 'part');
            $del_dn_tid = $ownRow['target_id'] ?? '';
            $img_nt     = ($ttype === 'part') ? 'part_design' : 'customer_design';
            $imgs = $pdo->prepare("SELECT file_name FROM note_images WHERE note_id=? AND note_type=?");
            $imgs->execute([$note_id, $img_nt]);
            foreach ($imgs->fetchAll(PDO::FETCH_COLUMN) as $fn) {
                $fp = $_nas_dir . $fn;
                if (file_exists($fp)) @unlink($fp);
            }
            $pdo->prepare("DELETE FROM note_images WHERE note_id=? AND note_type=?")->execute([$note_id, $img_nt]);
            $pdo->prepare("DELETE FROM design_notes WHERE note_id=?")->execute([$note_id]);
            $del_op       = _get_operator($pdo, $uid);
            $del_dn_tname = _target_display_name($pdo, $ttype, $del_dn_tid);
            _log_audit($pdo,'delete',$ttype,$del_dn_tid,$del_dn_tname,null,$uid,$del_op);
            // 若刪除者不是建立者，發送通知給建立者
            if ($ownerId > 0 && $ownerId !== intval($uid)) {
                _notify_design_note($pdo, $ownerId, 0, $ttype, $del_dn_tid, 'deleted', $uid, $del_op, $del_dn_old, null);
            }
            echo json_encode(['success'=>true]);
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 附件類別標籤管理（共用 quotation_file_categories）──────────────────
    if ($_POST['action'] === 'manage_attach_categories') {
        try {
            $op_code = trim($_POST['op'] ?? '');
            if ($op_code === 'list') {
                // is_own_drawing＝「自家出的圖」：上傳時要填發行章日期並參與圖面變更判定
                // （見 ai-rules/15-圖面變更判定依據.md）。欄位由 dwg_change_lib 建立，舊環境可能還沒有。
                require_once __DIR__ . '/../../src/common/dwg_change_lib.php';
                dwg_ensure_schema($pdo);
                // 外來文件欄位（AS9100，與報價頁附件類別設定連動；舊環境自動補欄位）
                try { $pdo->exec("ALTER TABLE quotation_file_categories ADD COLUMN is_external_doc TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否列入外來文件清單'"); } catch(PDOException $e){}
                try { $pdo->exec("ALTER TABLE quotation_file_categories ADD COLUMN external_doc_name VARCHAR(100) NULL COMMENT '外來文件類別名稱(空=用標籤名)'"); } catch(PDOException $e){}
                $rows = $pdo->query("SELECT id, category_name, sort_order, is_active, COALESCE(show_in_list,0) AS show_in_list, COALESCE(tag_variables,'') AS tag_variables, COALESCE(is_own_drawing,0) AS is_own_drawing, COALESCE(is_external_doc,0) AS is_external_doc, COALESCE(external_doc_name,'') AS external_doc_name FROM quotation_file_categories ORDER BY sort_order, id")->fetchAll(PDO::FETCH_ASSOC);
                echo json_encode(['success'=>true,'data'=>$rows]);
            } elseif ($op_code === 'save') {
                if (!$can_attach_cat_edit) throw new Exception('無編輯附件類別標籤權限（需 A/CDR/CDRU）');
                $cat_id       = intval($_POST['cat_id'] ?? 0);
                $name         = trim($_POST['category_name'] ?? '');
                $order        = intval($_POST['sort_order'] ?? 0);
                $show_in_list = intval($_POST['show_in_list'] ?? 0) ? 1 : 0;
                $own_drawing  = intval($_POST['is_own_drawing'] ?? 0) ? 1 : 0;
                $is_ext_doc   = intval($_POST['is_external_doc'] ?? 0) ? 1 : 0;
                $ext_doc_name = trim($_POST['external_doc_name'] ?? '') ?: null;
                $tag_vars     = trim($_POST['tag_variables'] ?? '') ?: null;
                $reactivate   = intval($_POST['reactivate'] ?? 0);
                $op_name      = _get_operator($pdo, $uid);
                if ($cat_id && $reactivate) {
                    $pdo->prepare("UPDATE quotation_file_categories SET is_active=1 WHERE id=?")->execute([$cat_id]);
                    echo json_encode(['success'=>true,'message'=>'已重新啟用','cat_id'=>$cat_id]);
                } elseif ($cat_id) {
                    if (!$name) throw new Exception('類別名稱不可為空');
                    $pdo->prepare("UPDATE quotation_file_categories SET category_name=?,sort_order=?,show_in_list=?,tag_variables=?,is_own_drawing=?,is_external_doc=?,external_doc_name=? WHERE id=?")
                        ->execute([$name, $order, $show_in_list, $tag_vars, $own_drawing, $is_ext_doc, $ext_doc_name, $cat_id]);
                    _log_audit($pdo,'update','dict','attach-cat:'.$cat_id,$name,null,$uid,$op_name);
                    echo json_encode(['success'=>true,'message'=>'已更新','cat_id'=>$cat_id]);
                } else {
                    if (!$name) throw new Exception('類別名稱不可為空');
                    $pdo->prepare("INSERT INTO quotation_file_categories (category_name,sort_order,show_in_list,tag_variables,is_own_drawing,is_external_doc,external_doc_name) VALUES (?,?,?,?,?,?,?)")
                        ->execute([$name, $order, $show_in_list, $tag_vars, $own_drawing, $is_ext_doc, $ext_doc_name]);
                    $new_id = (int)$pdo->lastInsertId();
                    _log_audit($pdo,'insert','dict','attach-cat:'.$new_id,$name,null,$uid,$op_name);
                    echo json_encode(['success'=>true,'message'=>'已新增','cat_id'=>$new_id]);
                }
            } elseif ($op_code === 'deactivate') {
                if (!$can_attach_cat_edit) throw new Exception('無停用權限');
                $cat_id = intval($_POST['cat_id'] ?? 0);
                $pdo->prepare("UPDATE quotation_file_categories SET is_active=0 WHERE id=?")->execute([$cat_id]);
                _log_audit($pdo,'delete','dict','attach-cat:'.$cat_id,'停用',null,$uid,_get_operator($pdo,$uid));
                echo json_encode(['success'=>true,'message'=>'已停用']);
            } elseif ($op_code === 'reorder') {
                if (!$can_attach_cat_edit) throw new Exception('無排序權限');
                $ids = json_decode($_POST['ids'] ?? '[]', true);
                if (is_array($ids)) {
                    $stmt = $pdo->prepare("UPDATE quotation_file_categories SET sort_order=? WHERE id=?");
                    foreach ($ids as $i => $id) $stmt->execute([$i, intval($id)]);
                }
                echo json_encode(['success'=>true]);
            } elseif ($op_code === 'save_path') {
                if ($permission_code !== 'A') throw new Exception('僅限 A 等級修改儲存路徑');
                $nas = trim($_POST['nas_dir'] ?? '');
                $url = trim($_POST['url_dir'] ?? '');
                if (!$nas || !$url) throw new Exception('路徑不可為空');
                $op_name = _get_operator($pdo,$uid);
                $ups = $pdo->prepare("INSERT INTO system_settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");
                $ups->execute(['part_attach_nas_dir', $nas]);
                $ups->execute(['part_attach_url_dir', $url]);
                _log_audit($pdo,'update','settings','part_attach_path','料號附件儲存路徑',null,$uid,$op_name);
                echo json_encode(['success'=>true]);
            } elseif ($op_code === 'get_path') {
                $nas = _get_setting($pdo,'part_attach_nas_dir','');
                $url = _get_setting($pdo,'part_attach_url_dir','');
                echo json_encode(['success'=>true,'nas_dir'=>$nas,'url_dir'=>$url]);
            } else { throw new Exception('未知操作'); }
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 齒輪等級對照表 ────────────────────────────────────────────────────
    if ($_POST['action'] === 'manage_gear_quality') {
        try {
            $op_code = trim($_POST['op'] ?? '');
            if ($op_code === 'get_ref') {
                $rows = $pdo->query("SELECT * FROM dict_gear_quality_ref ORDER BY sort_order, quality_ref_id")->fetchAll(PDO::FETCH_ASSOC);
                echo json_encode(['success'=>true,'data'=>$rows]);
            } elseif ($op_code === 'save_ref_row') {
                if (!$can_dict_edit) throw new Exception('無修改權限（需 A 或 CDRU）');
                $rid  = intval($_POST['quality_ref_id'] ?? 0);
                $to_int_or_null = function($k) { $v = trim($_POST[$k] ?? ''); return ($v !== '' && is_numeric($v)) ? intval($v) : null; };
                $iso  = $to_int_or_null('iso_grade');
                $din  = $to_int_or_null('din_grade');
                $jis  = $to_int_or_null('jis_grade');
                $agma = $to_int_or_null('agma_grade');
                $so   = intval($_POST['sort_order'] ?? 0);
                $op_name = _get_operator($pdo, $uid);
                if ($rid) {
                    $pdo->prepare("UPDATE dict_gear_quality_ref SET iso_grade=?,din_grade=?,jis_grade=?,agma_grade=?,sort_order=? WHERE quality_ref_id=?")->execute([$iso,$din,$jis,$agma,$so,$rid]);
                } else {
                    $pdo->prepare("INSERT INTO dict_gear_quality_ref (iso_grade,din_grade,jis_grade,agma_grade,sort_order) VALUES (?,?,?,?,?)")->execute([$iso,$din,$jis,$agma,$so]);
                    $rid = (int)$pdo->lastInsertId();
                }
                _log_audit($pdo,'save','dict','gear-quality-ref:'.$rid,'齒輪等級對照',null,$uid,$op_name);
                echo json_encode(['success'=>true,'quality_ref_id'=>$rid]);
            } elseif ($op_code === 'delete_ref_row') {
                if (!$can_dict_edit) throw new Exception('無刪除權限（需 A 或 CDRU）');
                $rid = intval($_POST['quality_ref_id'] ?? 0);
                if ($rid) $pdo->prepare("DELETE FROM dict_gear_quality_ref WHERE quality_ref_id=?")->execute([$rid]);
                _log_audit($pdo,'delete','dict','gear-quality-ref:'.$rid,'齒輪等級對照',null,$uid,_get_operator($pdo,$uid));
                echo json_encode(['success'=>true]);
            } elseif ($op_code === 'get_default') {
                echo json_encode(['success'=>true,'data'=>[
                    'std'   => _get_setting($pdo,'gear_quality_default_std',''),
                    'grade' => _get_setting($pdo,'gear_quality_default_grade','')
                ]]);
            } elseif ($op_code === 'save_default') {
                if (!$can_dict_edit) throw new Exception('無修改權限（需 A 或 CDRU）');
                $std   = trim($_POST['std'] ?? '');
                $grade = trim($_POST['grade'] ?? '');
                if ($std !== '' && !in_array($std, ['JIS','ISO','DIN','AGMA'])) throw new Exception('無效的等級標準');
                $op_name = _get_operator($pdo,$uid);
                _save_setting($pdo,'gear_quality_default_std',$std,$uid,$op_name);
                _save_setting($pdo,'gear_quality_default_grade',$grade,$uid,$op_name);
                _log_audit($pdo,'update','settings','gear_quality_default','齒輪預設等級',[['field'=>'std','old'=>null,'new'=>$std],['field'=>'grade','old'=>null,'new'=>$grade]],$uid,$op_name);
                echo json_encode(['success'=>true]);
            } else { throw new Exception('未知操作'); }
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 系統設定 ────────────────────────────────────────────────────────
    if ($_POST['action'] === 'manage_system_settings') {
        try {
            $op_code = trim($_POST['op'] ?? '');
            if ($op_code === 'get') {
                $keys = ['notes_nas_dir','notes_url_dir','default_settlement_mode','default_settlement_day','default_payment_method','default_net_days','vendor_default_settlement_mode','vendor_default_settlement_day','vendor_default_payment_method','vendor_default_net_days','cust_default_settlement_mode','cust_default_settlement_day','cust_default_payment_method','cust_default_net_days'];
                $result = [];
                foreach ($keys as $k) { $result[$k] = _get_setting($pdo, $k); }
                echo json_encode(['success'=>true,'data'=>$result]);
            } elseif ($op_code === 'save') {
                if (!$can_dict_edit) throw new Exception('無系統設定修改權限（需 A 或 CDRU）');
                $op = _get_operator($pdo, $uid);
                $allowed_keys = ['notes_nas_dir','notes_url_dir','default_settlement_mode','default_settlement_day','default_payment_method','default_net_days','vendor_default_settlement_mode','vendor_default_settlement_day','vendor_default_payment_method','vendor_default_net_days','cust_default_settlement_mode','cust_default_settlement_day','cust_default_payment_method','cust_default_net_days'];
                $label_map = ['notes_nas_dir'=>'NAS路徑','notes_url_dir'=>'URL路徑','default_settlement_mode'=>'預設結帳模式','default_settlement_day'=>'預設結帳日','default_payment_method'=>'預設付款方式','default_net_days'=>'預設月結天數','vendor_default_settlement_mode'=>'廠商預設結帳模式','vendor_default_settlement_day'=>'廠商預設結帳日','vendor_default_payment_method'=>'廠商預設付款方式','vendor_default_net_days'=>'廠商預設月結天數','cust_default_settlement_mode'=>'客戶預設結帳模式','cust_default_settlement_day'=>'客戶預設結帳日','cust_default_payment_method'=>'客戶預設付款方式','cust_default_net_days'=>'客戶預設月結天數'];
                foreach ($allowed_keys as $k) {
                    if (isset($_POST[$k])) {
                        $val = trim($_POST[$k]);
                        if ($val !== '') {
                            $old_val = _get_setting($pdo, $k);
                            _save_setting($pdo, $k, $val, $uid, $op);
                            if ($old_val !== $val) {
                                _log_audit($pdo,'update','settings',$k,($label_map[$k]??$k),[['field'=>($label_map[$k]??$k),'old'=>$old_val,'new'=>$val]],$uid,$op);
                            }
                        }
                    }
                }
                echo json_encode(['success'=>true]);
            } else { throw new Exception('未知操作'); }
        } catch(Throwable $e) { echo json_encode(['success'=>false,'message'=>$e->getMessage()]); }
        exit;
    }

    // ── 設計備註通知：取得未讀 ──
    if ($_POST['action'] === 'get_unread_dn_notifications') {
        try {
            $st = $pdo->prepare("SELECT * FROM design_note_notifications WHERE user_id=? AND is_read=0 ORDER BY created_at DESC LIMIT 30");
            $st->execute([$uid]);
            echo json_encode(['success'=>true,'notifications'=>$st->fetchAll(PDO::FETCH_ASSOC)]);
        } catch(Throwable $e) { echo json_encode(['success'=>true,'notifications'=>[]]); }
        exit;
    }

    // ── 設計備註通知：標記已讀 ──
    if ($_POST['action'] === 'mark_dn_notif_read') {
        try {
            $nid = intval($_POST['notif_id'] ?? 0);
            if ($nid) $pdo->prepare("UPDATE design_note_notifications SET is_read=1 WHERE notif_id=? AND user_id=?")->execute([$nid, $uid]);
            else      $pdo->prepare("UPDATE design_note_notifications SET is_read=1 WHERE user_id=?")->execute([$uid]);
            echo json_encode(['success'=>true]);
        } catch(Throwable $e) { echo json_encode(['success'=>false]); }
        exit;
    }

    echo json_encode(['success'=>false,'message'=>'未知 action']);
    exit;
}
?>
<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>主檔管理 — 料號 / 客戶 / 廠商</title>
<link href="../../resource/css/bootstrap.css" rel="stylesheet">
<link href="../../resource/css/font-awesome.css" rel="stylesheet">
<link href="../../resource/css/custom.css" rel="stylesheet">
<script src="../../resource/js/Sortable.min.js"></script>

<style>
/* ── CSS Variables (matching NewOrder color scheme) ── */
:root {
    --primary:   #2A3F54;
    --accent:    #1ABB9C;
    --accent2:   #26B99A;
    --bg:        #F4F7FC;
    --card:      #FFFFFF;
    --text:      #495057;
    --border:    #E6E9ED;
    --danger:    #e74c3c;
    --warning:   #f39c12;
    --info:      #3498db;
}

body { background: var(--bg); font-family: "Segoe UI","Roboto","Helvetica Neue",Arial,sans-serif; color: var(--text); }
.right_col { background: var(--bg) !important; padding: 20px 20px 40px; }

/* ── Tab Switcher ── */
.master-tabs { display:flex; gap:0; margin-bottom:20px; background:var(--card); border-radius:10px; box-shadow:0 2px 8px rgba(0,0,0,.06); overflow:hidden; }
.master-tab-btn {
    flex:1; padding:14px 10px; border:none; background:transparent; font-weight:600; font-size:14px;
    color:#888; cursor:pointer; transition:all .2s; position:relative;
    border-bottom:3px solid transparent;
}
.master-tab-btn:hover { color:var(--primary); background:#f8f9fa; }
.master-tab-btn.active { color:var(--primary); border-bottom-color:var(--accent); background:#f0faf8; }
.master-tab-btn .tab-icon { font-size:20px; display:block; margin-bottom:4px; }
.master-tab-btn .tab-badge { display:inline-block; background:var(--accent); color:#fff; border-radius:10px; font-size:10px; padding:1px 7px; margin-left:5px; vertical-align:middle; }

/* ── Search & Action Bar ── */
/* Customer modal tabs */
#customerModal .tab-pane { display:none !important; }
#customerModal .tab-pane.active { display:block !important; }
#custModalTabs > li > a { cursor:pointer; }

/* ══ Quick-filter chip bar ══════════════════════════════════ */
.filter-bar {
    display:flex; align-items:flex-start; gap:6px 8px; flex-wrap:wrap;
    padding:0 0 8px; margin-bottom:4px;
}
.filter-group { display:flex; align-items:center; gap:5px; flex-wrap:wrap; }
.filter-group-label {
    font-size:10px; font-weight:700; color:#bbb; text-transform:uppercase;
    letter-spacing:.6px; white-space:nowrap; padding:4px 2px 0; flex-shrink:0;
}
.fc {  /* filter chip */
    display:inline-flex; align-items:center; gap:3px;
    padding:3px 10px; border-radius:13px; font-size:12px; font-weight:600;
    cursor:pointer; user-select:none; transition:all .15s;
    background:#f0f2f5; color:#666; border:1.5px solid transparent;
    white-space:nowrap;
}
.fc:hover { background:#e4e7ec; color:#333; }
.fc.active { color:#fff; border-color:transparent; box-shadow:0 2px 6px rgba(0,0,0,.15); }
/* 製程大類篩選按鈕 — 更高對比度 */
#proc-type-filter-group .fc { background:#dce8f5; color:#1a3a5c; border:1.5px solid #b0cce4; }
#proc-type-filter-group .fc:hover { background:#c2d8ee; color:#0d2a45; }
/* 廠商付款/結帳篩選列 */
#maker-pay-settle-filter .fc { background:#e8edf3; color:#2A3F54; border:1.5px solid #aabbcc; }
#maker-pay-settle-filter .fc:hover { background:#d4dce6; }
#maker-pay-settle-filter .fc.active { background:#2A3F54; color:#fff; border-color:#2A3F54; }
/* 客戶收款/結帳篩選列 */
#cust-pay-settle-filter .fc { background:#e8f5f2; color:#1a6050; border:1.5px solid #a0d0c8; }
#cust-pay-settle-filter .fc:hover { background:#d0ece8; }
#cust-pay-settle-filter .fc.active { background:#1ABB9C; color:#fff; border-color:#1ABB9C; }
/* 加工限制標籤篩選列 */
#makers-proc-label-filter .fc { background:#e8f0ff; color:#2c5aa0; border:1.5px solid #a0bce0; }
#makers-proc-label-filter .fc:hover { background:#d0e2f8; }
#makers-proc-label-filter .fc.active { background:#2A3F54; color:#fff; border-color:#2A3F54; }
/* 結帳日輸入框無 spinner */
.settle-day-input::-webkit-inner-spin-button,.settle-day-input::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
.settle-day-input { -moz-appearance:textfield; }
.no-spin-input::-webkit-inner-spin-button,.no-spin-input::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
.no-spin-input { -moz-appearance:textfield; }
/* 料號表單 廠商/專用料號/專用機台 自動完成下拉 */
.pf-ac-dropdown { position:absolute; z-index:1060; left:0; right:0; background:#fff; border:1px solid #ddd; border-top:none; max-height:200px; overflow-y:auto; border-radius:0 0 6px 6px; box-shadow:0 4px 12px rgba(0,0,0,.12); }
.pf-ac-dropdown .pf-ac-opt:hover { background:#f0f4ff; }
.pf-ac-list:empty { display:none; }
#proc-type-filter-group .fc.active { background:var(--accent); color:#fff; border-color:var(--accent); }
.fc .fc-n { font-size:10px; opacity:.7; background:rgba(255,255,255,.2); border-radius:8px; padding:0 4px; margin-left:2px; }
.filter-sub-row {
    display:none; flex-wrap:wrap; gap:4px; align-items:center;
    padding:4px 0 2px 0; width:100%;
}
.filter-sub-row.visible { display:flex; }
.fc-sub { font-size:11px; padding:2px 8px; border-radius:10px; }
/* PAV 附件彈窗可拖移 */
#partAttachViewModal .modal-header { cursor:move; user-select:none; }
#partAttachViewModal .modal-header button,
#partAttachViewModal .modal-header a { cursor:pointer; }
#partAttachViewModal.pav-dragging .modal-dialog { transition:none !important; }

.action-bar {
    background:var(--card); border-radius:8px; padding:12px 16px;
    box-shadow:0 2px 6px rgba(0,0,0,.05); margin-bottom:14px;
    display:flex; gap:10px; align-items:center; flex-wrap:wrap;
}
.action-bar .search-wrap { flex:1; min-width:200px; position:relative; }
.action-bar .search-wrap input { padding-left:36px; border-radius:20px; border:1px solid var(--border); }
.action-bar .search-wrap .fa { position:absolute; left:12px; top:50%; transform:translateY(-50%); color:#aaa; }
.btn-add { background:var(--accent2); color:#fff; border:none; padding:7px 18px; border-radius:20px; font-weight:600; font-size:13px; transition:all .2s; }
.btn-add:hover { background:var(--primary); color:#fff; transform:translateY(-1px); box-shadow:0 4px 12px rgba(0,0,0,.15); }
.btn-add .fa { margin-right:5px; }

/* ── Data Table Card ── */
.data-card { background:var(--card); border-radius:10px; box-shadow:0 2px 8px rgba(0,0,0,.06); overflow:hidden; }
.data-card table { margin:0; border-collapse:collapse; width:100%; }
.data-card thead th {
    background:#f5f7fa; color:#555; font-weight:700; font-size:12px;
    padding:11px 10px; border-bottom:2px solid var(--border);
    text-transform:uppercase; letter-spacing:.5px; white-space:nowrap;
}
.data-card tbody td { padding:9px 10px; border-bottom:1px solid #f1f3f5; font-size:13px; vertical-align:middle; }
.data-card tbody tr:hover { background:#fafbfe; }
.data-card tbody tr:last-child td { border-bottom:none; }

    /* 廠商列表欄位距離修正 */
    #makers-table-wrap table { table-layout: fixed; width:100%; }
    #makers-table-wrap th, #makers-table-wrap td { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    #makers-table-wrap td:nth-child(2) { white-space: normal; word-break: break-all; }

/* ── Badges & Tags ── */
.badge-type { display:inline-block; border-radius:4px; padding:2px 7px; font-size:11px; font-weight:700; }
.badge-G { background:#fff3cd; color:#856404; }
.badge-H { background:#d1ecf1; color:#0c5460; }
.badge-N { background:#e2e8f0; color:#4a5568; }
.badge-active   { background:#d4edda; color:#155724; }
.badge-inactive { background:#f8d7da; color:#721c24; }
.badge-internal { background:#cce5ff; color:#004085; }

/* ── Pagination ── */
.pagination-row {
    display:flex; align-items:center; justify-content:space-between;
    padding:5px 4px 8px; margin-bottom:2px; border-bottom:1px solid #f0f2f4;
}
.pagination-info { font-size:12px; color:#888; }
.pg-btns { display:flex; gap:4px; }
.pg-btns button { background:#fff; border:1px solid var(--border); border-radius:4px; padding:3px 10px; font-size:12px; cursor:pointer; transition:all .15s; }
.pg-btns button:hover:not(:disabled) { background:var(--primary); color:#fff; border-color:var(--primary); }
.pg-btns button.active { background:var(--primary); color:#fff; border-color:var(--primary); }
.pg-btns button:disabled { opacity:.4; cursor:not-allowed; }

/* ── Row Actions ── */
.row-actions { display:flex; gap:4px; justify-content:center; }
.btn-row { border:none; border-radius:5px; padding:4px 9px; font-size:12px; cursor:pointer; transition:all .15s; }
.btn-row:hover { filter:brightness(1.1); transform:translateY(-1px); }
.btn-edit   { background:#e8f4ff; color:#1d6fa4; }
.btn-delete { background:#fde8e8; color:#c0392b; }
.btn-view   { background:#e8f8f5; color:#1a7a6e; }

/* ── Modal Overrides ── */
.modal-header { background:var(--primary); color:#fff; border-radius:8px 8px 0 0; }
.modal-header .modal-title { font-weight:700; }
.modal-header .close { color:#fff; opacity:.8; font-size:22px; }
.modal-header .close:hover { opacity:1; }
.modal-content { border:none; border-radius:8px; box-shadow:0 8px 32px rgba(0,0,0,.18); }
.modal-footer { border-top:1px solid var(--border); }
.form-section-title { font-size:12px; font-weight:700; text-transform:uppercase; color:var(--accent); letter-spacing:.8px; margin:16px 0 8px; padding-bottom:4px; border-bottom:1px dashed var(--border); }
.required-star { color:var(--danger); margin-left:2px; }
/* 料號／圖面代號 重複即時提示 */
.code-conflict-msg { display:none; margin-top:4px; font-size:12px; line-height:1.4; color:#DD5138; }
.code-conflict-msg.show { display:block; }
input.code-conflict { border-color:#DD5138 !important; background:#FDF1ED; }

/* ── Empty State ── */
.empty-state { text-align:center; padding:60px 20px; color:#aaa; }
.empty-state .fa { font-size:48px; margin-bottom:12px; display:block; }

/* ── Loading Overlay ── */
.table-loading { display:flex; align-items:center; justify-content:center; padding:40px; color:#aaa; gap:10px; }
.spinner { width:20px; height:20px; border:2px solid #ddd; border-top-color:var(--accent); border-radius:50%; animation:spin .7s linear infinite; }
@keyframes spin { to { transform:rotate(360deg); } }

/* ── Toast ── */
#toast-container { position:fixed; bottom:24px; right:24px; z-index:9999; display:flex; flex-direction:column; gap:8px; }
.toast-msg {
    background:var(--primary); color:#fff; padding:11px 18px; border-radius:8px;
    font-size:13px; box-shadow:0 4px 16px rgba(0,0,0,.2); opacity:0;
    animation:toastIn .3s forwards, toastOut .3s forwards 2.5s;
    display:flex; align-items:center; gap:8px; min-width:220px;
}
.toast-msg.success { background:var(--accent2); }
.toast-msg.error   { background:var(--danger); }
@keyframes toastIn  { to { opacity:1; transform:translateY(0); } from { opacity:0; transform:translateY(12px); } }
@keyframes toastOut { to { opacity:0; transform:translateY(12px); } from { opacity:1; transform:translateY(0); } }

/* ── Customer ID input hint ── */
.id-hint { font-size:11px; color:#888; margin-top:3px; }

/* ── Tag chips (process items) ── */
.process-chip { display:inline-block; background:#e2e8f0; border-radius:4px; padding:2px 6px; font-size:11px; margin:1px; }
/* ── Part label chips (in table + modal) ── */
.part-label-chip { display:inline-block; background:#e8f5f2; color:#1ABB9C; border:1px solid #a8dfd4; border-radius:10px; padding:1px 8px; font-size:11px; font-weight:600; margin:1px 2px 1px 0; cursor:default; }
#parts-table-wrap .part-label-chip { padding:0 6px; font-size:10.5px; }
/* 料號圖面連結 */
.part-drawing-link { cursor:pointer; color:var(--primary); border-bottom:1px dashed var(--primary); font-family:Consolas,monospace; transition:color .15s; }
.part-drawing-link:hover { color:#1ABB9C; border-bottom-color:#1ABB9C; }
/* 圖面 modal 檔案列表 */
.drawing-file-item { padding:9px 14px; border-bottom:1px solid #e9ecef; cursor:pointer; transition:background .15s; }
.drawing-file-item:hover { background:#e2e6ea; }
.drawing-file-item.active { background:#fff; border-left:4px solid var(--accent); box-shadow:0 1px 4px rgba(0,0,0,.08); }
.drawing-file-item h5 { margin:0 0 2px; font-size:13px; font-weight:600; color:#333; }
.drawing-file-item p { margin:0; font-size:11px; color:#888; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
/* 客戶自動完成 */
.parts-cust-dropdown { position:absolute; top:100%; left:0; z-index:9999; width:220px; max-height:200px; overflow-y:auto; background:#fff; border:1px solid #ddd; border-radius:6px; box-shadow:0 4px 12px rgba(0,0,0,.12); display:none; }
.parts-cust-dropdown .pac-item { padding:5px 12px; font-size:12px; cursor:pointer; }
.parts-cust-dropdown .pac-item:hover { background:#f0f4f8; }
.part-cust-chip { display:inline-flex; align-items:center; gap:5px; background:#e3f2fd; color:#1565c0; border:1px solid #1565c0aa; border-radius:13px; padding:2px 10px; font-size:12px; font-weight:600; }
.part-cust-chip .rm { cursor:pointer; color:#aaa; font-size:11px; margin-left:2px; }
.part-cust-chip .rm:hover { color:#e74c3c; }
.lbl-filter-val[type=number]::-webkit-inner-spin-button,.lbl-filter-val[type=number]::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
.lbl-filter-val[type=number] { -moz-appearance:textfield; }
.mf-filter-val[type=number]::-webkit-inner-spin-button,.mf-filter-val[type=number]::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
.mf-filter-val[type=number] { -moz-appearance:textfield; }
.mf-proc-min-val::-webkit-inner-spin-button,.mf-proc-min-val::-webkit-outer-spin-button,
.mf-proc-max-val::-webkit-inner-spin-button,.mf-proc-max-val::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
.mf-proc-min-val,.mf-proc-max-val { -moz-appearance:textfield; }
#helix-d-0::-webkit-inner-spin-button,#helix-d-0::-webkit-outer-spin-button,
#helix-m-0::-webkit-inner-spin-button,#helix-m-0::-webkit-outer-spin-button,
#helix-s-0::-webkit-inner-spin-button,#helix-s-0::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
[id^="helix-d-"]::-webkit-inner-spin-button,[id^="helix-d-"]::-webkit-outer-spin-button,
[id^="helix-m-"]::-webkit-inner-spin-button,[id^="helix-m-"]::-webkit-outer-spin-button,
[id^="helix-s-"]::-webkit-inner-spin-button,[id^="helix-s-"]::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
[id^="helix-d-"],[id^="helix-m-"],[id^="helix-s-"] { -moz-appearance:textfield; }
.multi-kw-wrap { display:flex; align-items:center; flex-wrap:wrap; gap:4px; background:var(--card); border:1px solid var(--border); border-radius:20px; padding:3px 12px; min-height:34px; flex:1; min-width:180px; }
.multi-kw-input { border:none; outline:none; background:transparent; padding:2px 4px; font-size:13px; min-width:100px; flex:1; }
.search-kw-chip { display:inline-flex; align-items:center; gap:3px; background:#e3f2fd; color:#1565c0; border:1px solid #1565c0aa; border-radius:10px; padding:1px 8px; font-size:12px; white-space:nowrap; }
.search-kw-chip .rm { cursor:pointer; color:#aaa; font-size:11px; }
.search-kw-chip .rm:hover { color:#e74c3c; }
.clear-filter-btn { background:#fff5f5; color:#e74c3c; border:1px solid #e74c3c88; border-radius:16px; padding:5px 14px; font-size:12px; cursor:pointer; white-space:nowrap; }
.clear-filter-btn:hover { background:#e74c3c; color:#fff; }
.part-label-chip.selected { background:#1ABB9C; color:#fff; border-color:#1ABB9C; }
.part-label-chip.no-input { cursor:pointer; }
.part-label-chip.no-input:hover { background:#c8ece6; }

/* ── Gear / BOM rows ── */
.gear-row { background:#fffbf0; border:1px solid #fde8c0; border-radius:6px; padding:10px 12px 6px; margin-bottom:10px; position:relative; overflow:hidden; }
.gear-row .row { margin-left:-5px; margin-right:-5px; }
.gear-row .row > [class*="col-"] { padding-left:5px; padding-right:5px; }
.gear-row .form-group { margin-bottom:5px; }
.gear-row-title { font-size:11px; font-weight:700; color:#e67e22; margin-bottom:8px; text-transform:uppercase; letter-spacing:.5px; }
.btn-remove-row { position:absolute; top:8px; right:8px; background:none; border:none; color:#c0392b; font-size:16px; cursor:pointer; padding:0 4px; line-height:1; }
.btn-remove-row:hover { color:#e74c3c; }
.bom-child-item { padding:8px 12px; cursor:pointer; border-bottom:1px solid #f5f5f5; }
.bom-child-item:hover { background:#f0ebff; }
.bom-child-item strong { color:#8e44ad; font-family:Consolas,monospace; }
.bom-row-part { font-family:Consolas,monospace; font-weight:700; color:#8e44ad; }

/* ── Industry / sub-cat tags ── */
.industry-tag, .sub-cat-tag { user-select:none; }
.industry-tag:hover { opacity:.85; }

/* ── Sub pool / selected chips ── */
.sub-pool-chip, .sub-sel-chip {
    display:inline-block; cursor:pointer; user-select:none;
    padding:3px 9px; border-radius:12px; font-size:11px; font-weight:600;
    border:1.5px solid transparent; transition:all .15s;
}
.sub-pool-chip { background:#f0f0f0; color:#555; border-color:#ddd; }
.sub-pool-chip:hover { background:#e0e0e0; }
.sub-sel-chip  { background:#5856d6; color:#fff; border-color:#5856d6; }
.sub-sel-chip:hover  { background:#4040b8; }
/* Group colours for pool chips */
.sub-pool-chip.sub-group-PROCESS    { background:#e8f8f5; color:#1ABB9C; border-color:#1ABB9C44; }
.sub-pool-chip.sub-group-CONSUMABLE { background:#fef3e7; color:#e67e22; border-color:#e67e2244; }
.sub-pool-chip.sub-group-TOOL       { background:#eaf4fd; color:#3498db; border-color:#3498db44; }
.sub-pool-chip.sub-group-OTHER      { background:#f5f5f5; color:#888;    border-color:#ddd; }
/* Group colours for selected chips */
.sub-sel-chip.sub-group-PROCESS    { background:#1ABB9C; border-color:#1ABB9C; }
.sub-sel-chip.sub-group-CONSUMABLE { background:#e67e22; border-color:#e67e22; }
.sub-sel-chip.sub-group-TOOL       { background:#3498db; border-color:#3498db; }
.sub-sel-chip.sub-group-OTHER      { background:#888;    border-color:#888; }
/* Table row chips */
.sub-tag-chip { display:inline-block; padding:1px 7px; border-radius:10px; font-size:10px; font-weight:600; margin:1px; }
.sub-tag-chip.sub-group-PROCESS    { background:#e8f8f5; color:#1ABB9C; }
.sub-tag-chip.sub-group-CONSUMABLE { background:#fef3e7; color:#e67e22; }
.sub-tag-chip.sub-group-TOOL       { background:#eaf4fd; color:#3498db; }
.sub-tag-chip.sub-group-OTHER      { background:#f5f5f5; color:#888; }
/* Sortable ghost */
.sortable-ghost { opacity:.35; background:#fff9c4 !important; }
/* Sub group filter buttons */
.sub-grp-btn { border-radius:10px !important; padding:2px 8px !important; font-size:10px !important; background:#f0f0f0; border:1px solid #ddd; color:#666; transition:all .15s; }
.sub-grp-btn.active { background:#5856d6; color:#fff; border-color:#5856d6; }
.sub-grp-btn:hover:not(.active) { background:#e0e0e0; }

/* ── Dict Modal Nav ── */
.dict-nav-btn {
    display:block; width:100%; text-align:left; padding:9px 14px; border:none;
    background:transparent; font-size:13px; color:#555; cursor:pointer;
