.dict-nav-btn.active { background:#e8f5f2; color:#1ABB9C; border-left-color:#1ABB9C; font-weight:700; }
.dict-nav-btn .fa    { width:16px; margin-right:7px; opacity:.6; }
.dict-nav-btn.active .fa { opacity:1; }

/* ── 附件畫布標記 ── */
#mdm-canvas-container {
    overflow: auto; background: #888; display: flex;
