#dict-table tbody tr:last-child td { border-bottom:none; }
.dict-tag-badge { display:inline-block; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:600; background:#e8f5f2; color:#1ABB9C; }
.dict-code-badge { display:inline-block; padding:1px 7px; border-radius:4px; font-size:11px; font-weight:700; background:#f0f4ff; color:#5856d6; font-family:Consolas,monospace; margin-right:6px; }
.dict-helix-badge { display:inline-block; padding:1px 6px; border-radius:10px; font-size:10px; background:#fff3cd; color:#856404; margin-left:4px; }

/* ── Dup check ── */
