.dup-row { display:flex; align-items:center; gap:8px; padding:8px 14px; border-bottom:1px solid #f5f6f7; font-size:12px; }
.dup-row:last-child { border-bottom:none; }
.dup-row:hover { background:#fffdf5; }
.dup-field { display:inline-block; background:#f0f0f0; border-radius:4px; padding:1px 6px; font-size:11px; color:#555; margin:1px; }
.dup-field.empty { color:#ccc; font-style:italic; }
.dup-del-btn { margin-left:auto; flex-shrink:0; }
.sim-badge { display:inline-block; background:#fff3e0; color:#e65100; border-radius:10px; padding:1px 8px; font-size:10px; font-weight:700; margin-left:6px; }

/* ── Settlement badge ── */
.settle-badge { display:inline-block; background:#e8f5e9; color:#2e7d32; border-radius:4px; padding:2px 8px; font-size:11px; font-weight:600; }

