// ─── Debounce ──────────────────────────────────────
function debounce(fn, ms) {
    var t;
    return function() { var a=arguments,th=this; clearTimeout(t); t=setTimeout(function(){fn.apply(th,a);},ms); };
}

// ─── Toast ─────────────────────────────────────────
function showToast(msg, type) {
    type = type || 'success';
    var c = document.getElementById('toast-container');
    var d = document.createElement('div');
    var icon = (type==='success') ? 'check-circle' : 'exclamation-circle';
    d.className = 'toast-msg ' + type;
    d.innerHTML = '<i class="fa fa-' + icon + '"></i> ' + msg;
    c.appendChild(d);
    setTimeout(function(){ d.remove(); }, 2900);
}

// ─────────────────────────────────────────────────────
//  設計備註異動通知
// ─────────────────────────────────────────────────────
var _dnNotifShown    = {};   // notif_id → true（防重複顯示）
var _dnNotifInterval = null;
var _origDocTitle    = document.title;

function startDnNotifPolling() {
    if (_dnNotifInterval) return;
    _pollDnNotifs();
    _dnNotifInterval = setInterval(_pollDnNotifs, 3000);
}
function _pollDnNotifs() {
    $.post(SELF_URL, {action:'get_unread_dn_notifications'}, function(r) {
        if (!r || !r.success || !r.notifications || !r.notifications.length) return;
        r.notifications.forEach(function(n) { _showDnNotif(n); });
    }, 'json');
}
function _showDnNotif(n) {
    var nid = n.notif_id;
    if (_dnNotifShown[nid]) return;
    _dnNotifShown[nid] = true;

    var isDeleted = (n.type === 'deleted');
    var color  = isDeleted ? '#e74c3c' : '#f39c12';
    var icon   = isDeleted ? 'fa-trash' : 'fa-pencil';
    var typeZh = isDeleted ? '刪除' : '修改';
    var tLabel = n.target_type === 'part' ? '料號' : '客戶';
    var tName  = escHtml(n.target_name || n.target_id || '');
    var opName = escHtml(n.operator || '');
    var timeStr= escHtml((n.created_at||'').substr(0,16));

    // 變動摘要（最多60字）
    var oldSnip = n.old_text ? escHtml(n.old_text.substr(0,60) + (n.old_text.length>60?'…':'')) : '（無）';
    var newSnip = n.new_text ? escHtml(n.new_text.substr(0,60) + (n.new_text.length>60?'…':'')) : '';

    var detailHtml = '<div style="font-size:11px;color:#666;margin-top:6px;border-top:1px dashed #eee;padding-top:6px;">';
    detailHtml += '<div style="margin-bottom:3px;"><span style="color:#999;">變動前：</span>' + oldSnip + '</div>';
    if (!isDeleted) {
        detailHtml += '<div><span style="color:#999;">變動後：</span>' + newSnip + '</div>';
    }
    detailHtml += '</div>';

    var card = $('<div id="dn-notif-'+nid+'" style="pointer-events:auto;background:#fff;border:1px solid #ddd;border-left:4px solid '+color+';border-radius:6px;padding:10px 14px;box-shadow:0 3px 12px rgba(0,0,0,.15);cursor:pointer;max-width:340px;font-size:13px;position:relative;word-break:break-word;">'
        +'<div style="font-weight:700;color:'+color+';margin-bottom:4px;"><i class="fa '+icon+'"></i> 設計備註已被'+typeZh+'</div>'
        +'<div style="color:#333;margin-bottom:2px;"><b>'+tLabel+'：</b>'+tName+'</div>'
        +'<div style="color:#555;font-size:12px;"><b>操作者：</b>'+opName+'&emsp;<span style="color:#aaa;">'+timeStr+'</span></div>'
        + detailHtml
        +'<button onclick="_dismissDnNotif('+nid+',event)" style="position:absolute;top:6px;right:8px;background:none;border:none;color:#aaa;font-size:16px;cursor:pointer;line-height:1;" title="關閉">&times;</button>'
        +'</div>');

    card.on('click', function(e) {
        if ($(e.target).is('button')) return;
        _dismissDnNotif(nid, e);
        _openDnNotifTarget(n);
    });

    $('#dn-notif-panel').append(card);
    // 5分鐘後自動消失
    setTimeout(function() { card.fadeOut(400, function(){ card.remove(); }); }, 300000);
}

function _dismissDnNotif(nid, e) {
    if (e) e.stopPropagation();
    $('#dn-notif-' + nid).fadeOut(200, function(){ $(this).remove(); });
    $.post(SELF_URL, {action:'mark_dn_notif_read', notif_id:nid}, function(){}, 'json');
}

function _openDnNotifTarget(n) {
    var tabName = n.target_type === 'part' ? 'parts' : 'customers';
    var tabBtn  = document.querySelector('.master-tab-btn[onclick*="\''+tabName+'\'"]');
    switchTab(tabName, tabBtn);
    setTimeout(function() {
        if (n.target_type === 'part' && n.target_pk) {
            openPartDesignModal(parseInt(n.target_pk), n.target_id || '');
        } else if (n.target_type === 'customer') {
            // 取得客戶名稱再開窗
            var custName = n.target_name ? n.target_name.replace(/\(.*\)$/, '').trim() : (n.target_id||'');
            openCustDesignModal(n.target_id, custName);
        }
    }, 400);
}

// ─── AJAX helper ───────────────────────────────────
var _pendingSaves = {};
function api(data) {
    return $.ajax({ url: SELF_URL, method:'POST', data: data, dataType:'json' });
}
// Debounced submit: prevents double-click sending multiple requests
function apiOnce(key, data, onDone, onFail) {
    if (_pendingSaves[key]) return;
    _pendingSaves[key] = true;
    $.ajax({ url: SELF_URL, method:'POST', data: data, dataType:'json' }).done(function(r){ _pendingSaves[key]=false; if(onDone) onDone(r); }).fail(function(){ _pendingSaves[key]=false; if(onFail) onFail(); });
}

// ─── Escape helpers ────────────────────────────────
function escHtml(s) {
    return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
// Strip [...] hint text from label/sub-label names for frontend display
function _stripLabelHint(name) {
    return String(name||'').replace(/\s*\[.*?\]\s*/g, ' ').trim();
}
function escAttr(s) {
    return String(s||'').replace(/'/g,"\\'").replace(/"/g,'&quot;');
}
function fmtNum(v) {
    if (v === null || v === undefined || v === '') return '';
    var n = parseFloat(v);
    return isNaN(n) ? String(v) : String(n);
}

// ─── Pagination helper ─────────────────────────────
function paginationHTML(total, pg, pages, fnName) {
    if (!total) return '';
    var from = (pg-1)*10+1, to = Math.min(pg*10, total);
    var btns = '';
    var start = Math.max(1, pg-3), end = Math.min(pages, pg+3);
    if (end-start < 6) start = Math.max(1, end-6);
    if (start > 1) btns += '<button onclick="'+fnName+'(1)">1</button>'+(start>2?'<button disabled>…</button>':'');
    for (var i=start; i<=end; i++) btns += '<button class="'+(i===pg?'active':'')+'" onclick="'+fnName+'('+i+')">'+i+'</button>';
    if (end < pages) btns += (end<pages-1?'<button disabled>…</button>':'')+'<button onclick="'+fnName+'('+pages+')">'+pages+'</button>';
    return '<div class="pagination-row">'
        + '<span class="pagination-info">共 <strong>'+total+'</strong> 筆，顯示 '+from+'–'+to+'</span>'
        + '<div class="pg-btns">'
        + '<button '+(pg<=1?'disabled':'')+' onclick="'+fnName+'('+(pg-1)+')"><i class="fa fa-chevron-left"></i></button>'
        + btns
        + '<button '+(pg>=pages?'disabled':'')+' onclick="'+fnName+'('+(pg+1)+')"><i class="fa fa-chevron-right"></i></button>'
        + '</div></div>';
}

// ─── Tab Switcher ───────────────────────────────────
var activeTab = 'parts';
function switchTab(tab, btn) {
    ['parts','customers','makers','process','history'].forEach(function(t) {
        document.getElementById('tab-' + t).style.display = (t===tab) ? '' : 'none';
    });
    document.querySelectorAll('.master-tab-btn').forEach(function(b){ b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    activeTab = tab;
    // 每次切換分頁都重新載入，確保資料最新
    if (tab==='parts')     loadParts(1);
    if (tab==='customers') loadCustomers(1);
    if (tab==='makers')    loadMakers(1);
    if (tab==='process')   loadProcessList();
    if (tab==='history')  { histSetToday(); loadHistory(1); }
}
function switchToHistory() {
    var btn = document.getElementById('tab-btn-history');
    switchTab('history', btn);
}

