function showPermHelp() { $('#permHelpModal').modal('show'); }

// ─── 刪除確認（需輸入大寫 Y）────────────────────────
function confirmDeleteY(msg) {
    var v = prompt(msg + '\n\n請輸入大寫 Y 確認刪除：', '');
    return v === 'Y';
}

// ─── 歷史紀錄 ────────────────────────────────────────
var historyFilter = { dateFrom:'', dateTo:'', targetType:'', keyword:'' };
var historyCurrent = 1;
function _histFmtDate(dt) {
    return dt.getFullYear() + '-' + String(dt.getMonth()+1).padStart(2,'0') + '-' + String(dt.getDate()).padStart(2,'0');
}
function _histSetDates(ds, de) {
    document.getElementById('hist-date-from').value = ds;
    document.getElementById('hist-date-to').value   = de;
    historyFilter.dateFrom = ds; historyFilter.dateTo = de;
}
function histSetToday() {
    var ds = _histFmtDate(new Date());
    _histSetDates(ds, ds);
    loadHistory(1);
}
function histSetWeek() {
    var t = new Date(); var d1 = new Date(t); d1.setDate(t.getDate() - t.getDay());
    _histSetDates(_histFmtDate(d1), _histFmtDate(t));
    loadHistory(1);
}
function histSetMonth() {
    var t = new Date();
    var ds = t.getFullYear() + '-' + String(t.getMonth()+1).padStart(2,'0') + '-01';
    _histSetDates(ds, _histFmtDate(t));
    loadHistory(1);
}
var _histTypeColors = { '':'#6c757d', 'part':'#3498db', 'customer':'#1ABB9C', 'vendor':'#e67e22', 'dict':'#9b59b6', 'process':'#2980b9', 'settings':'#c0392b' };
function histSetType(val, el) {
    historyFilter.targetType = val;
    document.querySelectorAll('.hist-type-btn').forEach(function(b) {
        var bVal = b.dataset.val;
        var c = _histTypeColors[bVal] || '#6c757d';
        if (bVal === val) {
            b.style.background = c; b.style.color = '#fff'; b.style.borderColor = c;
            b.classList.add('active');
        } else {
            b.style.background = '#fff'; b.style.color = c; b.style.borderColor = c;
            b.classList.remove('active');
        }
    });
    loadHistory(1);
}
function histShiftDay(delta) {
    var fEl = document.getElementById('hist-date-from');
    var tEl = document.getElementById('hist-date-to');
    if (!fEl.value || !tEl.value) return;
    var parseLocal = function(val) {
        var p = val.split('-');
        return new Date(parseInt(p[0]), parseInt(p[1])-1, parseInt(p[2]));
    };
    var fd = parseLocal(fEl.value); fd.setDate(fd.getDate() + delta);
    var td = parseLocal(tEl.value); td.setDate(td.getDate() + delta);
    _histSetDates(_histFmtDate(fd), _histFmtDate(td));
    loadHistory(1);
}
function loadHistory(pg) {
    historyCurrent = pg || 1;
    var wrap = document.getElementById('history-table-wrap');
    wrap.innerHTML = '<div class="table-loading"><div class="spinner"></div> 載入中…</div>';
    var kw = (document.getElementById('hist-keyword')||{}).value||'';
    historyFilter.keyword = kw;
    api({ action:'get_audit_log', page:historyCurrent,
          date_from:historyFilter.dateFrom, date_to:historyFilter.dateTo,
          target_type:historyFilter.targetType, keyword:historyFilter.keyword
    }).done(function(r) {
        if (!r.success) { wrap.innerHTML = '<div style="color:#e74c3c;padding:20px;">載入失敗：'+escHtml(r.message||'')+'</div>'; return; }
        renderHistoryTable(r.data||[], r.total||0, r.page||1, r.pages||1);
    }).fail(function(){ wrap.innerHTML = '<div style="color:#e74c3c;padding:20px;">網路錯誤</div>'; });
}
function renderHistoryTable(rows, total, pg, pages) {
    var wrap = document.getElementById('history-table-wrap');
    var typeMap  = {part:'料號',customer:'客戶',vendor:'廠商',dict:'字典',process:'製程/大類',settings:'系統設定'};
    var actMap   = {insert:'新增',update:'修改',delete:'刪除'};
    var actColor = {insert:'#1ABB9C',update:'#3498db',delete:'#e74c3c'};
    var html = '<div style="overflow-x:auto;"><table class="table table-condensed table-bordered" style="font-size:12px;">';
    html += '<thead><tr style="background:#f7f9fb;"><th style="width:130px;">時間 / 操作人</th><th style="width:50px;">操作</th><th style="width:50px;">類型</th><th style="width:160px;white-space:nowrap;">名稱</th><th>變更內容</th></tr></thead><tbody>';
    if (!rows.length) {
        html += '<tr><td colspan="5" style="text-align:center;color:#aaa;padding:24px;"><i class="fa fa-inbox"></i> 無紀錄</td></tr>';
    } else {
        rows.forEach(function(r) {
            var changes = '—';
            if (r.changes) {
                try {
                    var ch = JSON.parse(r.changes);
                    if (Array.isArray(ch) && ch.length) {
                        changes = ch.map(function(c){ return '<span style="color:#888;">'+escHtml(c.field||'')+'</span> <span style="color:#e74c3c;text-decoration:line-through;">'+escHtml(String(c.old||''))+'</span> → <span style="color:#1ABB9C;">'+escHtml(String(c.new||''))+'</span>'; }).join('<br>');
                    }
                } catch(e) { changes = escHtml(r.changes); }
            }
            html += '<tr>';
            html += '<td style="white-space:nowrap;"><div style="color:#888;font-size:11px;">'+escHtml(r.created_at||'')+'</div><div style="color:#aaa;font-size:10px;text-align:right;">'+escHtml(r.operator||'')+'</div></td>';
            html += '<td><span style="color:'+(actColor[r.action_type]||'#555')+';font-weight:700;font-size:11px;">'+escHtml(actMap[r.action_type]||r.action_type)+'</span></td>';
            html += '<td><span style="color:'+(_histTypeColors[r.target_type]||'#555')+';font-size:11px;font-weight:600;">'+escHtml(typeMap[r.target_type]||r.target_type)+'</span></td>';
            html += '<td style="color:#555;font-size:11px;white-space:nowrap;max-width:160px;overflow:hidden;text-overflow:ellipsis;" title="'+escHtml(r.target_name||'')+'">'+escHtml(r.target_name||'')+'</td>';
            html += '<td style="font-size:11px;color:#555;line-height:1.7;">'+(changes)+'</td>';
            html += '</tr>';
        });
    }
    html += '</tbody></table></div>';
    wrap.innerHTML = paginationHTML(total, pg, pages, 'loadHistory') + html;
}

// ─── 切換客戶狀態 ─────────────────────────────────────
function toggleCustomerStatus(customerId, currentStatus) {
    var action = currentStatus ? '啟用' : '停用';
    if (!confirm('確定要'+action+'客戶「'+customerId+'」？')) return;
    api({ action:'toggle_customer_status', customer_id:customerId }).done(function(r) {
        if (r.success) { showToast(action+'成功','success'); loadCustomers(customersCurrent||1); }
        else showToast(r.message||'操作失敗','error');
    });
}

// ─── 切換廠商狀態 ─────────────────────────────────────
function toggleMakerStatus(makerIdNo, currentStatus) {
    var action = (currentStatus==='停用') ? '啟用(正常)' : '停用';
    if (!confirm('確定要'+action+'廠商「'+makerIdNo+'」？')) return;
    api({ action:'toggle_maker_status', maker_id_no:makerIdNo }).done(function(r) {
        if (r.success) { showToast(action+'成功','success'); loadMakers(makersCurrent||1); }
        else showToast(r.message||'操作失敗','error');
    });
}

// ─── 刪除齒輪規格列（立即生效） ────────────────────────
function deleteGearRow(gearId, dSettingDbId) {
    if (!confirmDeleteY('確定立即刪除此齒型規格列？此操作無法復原。')) return;
    api({ action:'delete_gear_row', gear_id:gearId, d_setting_id:dSettingDbId }).done(function(r) {
        if (r.success) {
            showToast('已刪除齒型規格列','success');
            api({ action:'get_part', d_id:dSettingDbId }).done(function(r2) {
                if (r2.success && r2.data) {
                    gearRows = [];
                    (r2.data.gears||[]).forEach(function(g){ addGearRow(g); });
                }
            });
        } else showToast(r.message||'刪除失敗','error');
    });
}

// ═══════════════════════════════════════════════════
// ──────────── 料號 ─────────────────────────────────
// ═══════════════════════════════════════════════════
// ── Filter state ──────────────────────────────────────────
var _partsFilter  = { types:[], gear:0, sub:0, labels:[], customerIds:[], grades:[], industries:[], industrySubs:[], keywords:[], pinnedPartIds:[], quickKws:[], gearDaMin:null, gearDaMax:null, shipSort:'', attachTags:[], gearModules:[], gearHelixDir:'', gearPressureAngles:[], gearTeethMin:null, gearTeethMax:null, gearFwMin:null, gearFwMax:null, gearHaMin:null, gearHaMax:null };
var _custFilter   = { grades:[], industries:[], industrySubs:[], keywords:[], pinnedCustIds:[], quickKws:[], payment_method:'', settlement_mode:'', settlement_day: null };
var _makersFilter = { main_cats:[], sub_cats:[], keywords:[], pinnedMakerIds:[], quickKws:[], payment_method:'', settlement_mode:'', settlement_day: null, proc_labels:[] };

// Palette for workpiece type chips (same logic as maker cat palette, no red)
var _wpPalette = [
    {bg:'#eef2ff',fg:'#5856d6',sel:'#5856d6'},
    {bg:'#e8f8f5',fg:'#1ABB9C',sel:'#1ABB9C'},
    {bg:'#fff3e0',fg:'#e65100',sel:'#e65100'},
    {bg:'#e0f7fa',fg:'#00695c',sel:'#00695c'},
    {bg:'#f3e5f5',fg:'#7b1fa2',sel:'#7b1fa2'},
    {bg:'#fce4ec',fg:'#880e4f',sel:'#880e4f'},
    {bg:'#f9fbe7',fg:'#558b2f',sel:'#558b2f'},
    {bg:'#e3f2fd',fg:'#1565c0',sel:'#1565c0'},
];

// ── 附件標籤篩選 ──────────────────────────────────────────────────────────
var _attachFilterSelected = [];  // [{cat_id, var_key, var_val}] — cat_id=id, var_key='' means "has this tag", var_key!='' means variable match

function initAttachFilterBar() {
    loadActiveCatsForUpload(function(cats) {
        if (!cats || !cats.length) return;
        var row  = document.getElementById('parts-attach-filter');
        var wrap = document.getElementById('parts-attach-filter-chips');
        if (!row || !wrap) return;
        row.style.display = '';
        wrap.innerHTML = '';
        cats.forEach(function(c) {
            var vars = [];
            try { vars = JSON.parse(c.tag_variables||'[]'); } catch(e) { vars = []; }
            // Main chip
            var chip = document.createElement('span');
            chip.className = 'fc fc-sub';
            chip.dataset.catId  = c.id;
            chip.dataset.active = '0';
            chip.textContent    = c.category_name;
            chip.style.cssText  = 'background:#f0f8ff;color:#1a5276;border:1.5px solid #aed6f1;cursor:pointer;';
            chip.onclick = function() {
                var isA = chip.dataset.active === '1';
                chip.dataset.active = isA ? '0' : '1';
                chip.style.background = isA ? '#f0f8ff' : '#2980b9';
                chip.style.color      = isA ? '#1a5276' : '#fff';
                var varWrap = document.getElementById('afc-vars-'+c.id);
                if (varWrap) varWrap.style.display = isA ? 'none' : 'inline-flex';
                syncAttachFilter();
            };
            wrap.appendChild(chip);
            // Variable inputs (hidden until chip active)
            if (vars.length) {
                var vw = document.createElement('span');
                vw.id = 'afc-vars-'+c.id;
                vw.style.cssText = 'display:none;align-items:center;gap:3px;';
                vars.forEach(function(v) {
                    var label = document.createElement('span');
                    label.style.cssText = 'font-size:10px;color:#888;';
                    label.textContent   = v.key + ':';
                    var inp = document.createElement('input');
                    inp.type         = 'text';
                    inp.className    = 'form-control input-sm afc-var-input';
                    inp.placeholder  = v.hint||v.key;
                    inp.dataset.catId = c.id;
                    inp.dataset.key   = v.key;
                    inp.style.cssText = 'width:80px;font-size:11px;';
                    inp.oninput       = function() { syncAttachFilter(); };
                    vw.appendChild(label);
                    vw.appendChild(inp);
                });
                wrap.appendChild(vw);
            }
        });
    });
}

function syncAttachFilter() {
    _attachFilterSelected = [];
    document.querySelectorAll('#parts-attach-filter-chips .fc[data-cat-id]').forEach(function(chip) {
        if (chip.dataset.active !== '1') return;
        var cid = chip.dataset.catId;
        var varWrap = document.getElementById('afc-vars-'+cid);
        var hasVarFilter = false;
        if (varWrap) {
            varWrap.querySelectorAll('.afc-var-input').forEach(function(inp) {
                var val = inp.value.trim();
                if (val) { _attachFilterSelected.push({ cat_id:cid, var_key:inp.dataset.key, var_val:val }); hasVarFilter=true; }
            });
        }
        if (!hasVarFilter) _attachFilterSelected.push({ cat_id:cid, var_key:'', var_val:'' });
    });
    var clearBtn = document.getElementById('parts-attach-filter-clear');
    if (clearBtn) clearBtn.style.display = _attachFilterSelected.length ? '' : 'none';
    _partsFilter.attachTags = _attachFilterSelected;
    loadParts(1);
}

function clearAttachFilter() {
    document.querySelectorAll('#parts-attach-filter-chips .fc[data-cat-id]').forEach(function(chip) {
        chip.dataset.active = '0';
        chip.style.background = '#f0f8ff'; chip.style.color = '#1a5276';
        var vw = document.getElementById('afc-vars-'+chip.dataset.catId);
        if (vw) { vw.style.display='none'; vw.querySelectorAll('.afc-var-input').forEach(function(i){ i.value=''; }); }
    });
    _attachFilterSelected = [];
    _partsFilter.attachTags = [];
    var clearBtn = document.getElementById('parts-attach-filter-clear');
    if (clearBtn) clearBtn.style.display = 'none';
    loadParts(1);
}

// ── 料號篩選初始化 ─────────────────────────────────────────
function initPartsFilterBar() {
    var bar = document.getElementById('parts-type-group');
    if (!bar) return;
    // Remove previously injected chips (keep pac-wrap + chips-span + label + 全部 = 4 children)
    while (bar.children.length > 4) bar.removeChild(bar.lastChild);
    api({ action:'manage_workpiece_types', op:'list' }).done(function(r) {
        if (!r.success) return;
        while (bar.children.length > 4) bar.removeChild(bar.lastChild);
        r.data.forEach(function(t, idx) {
            var pal = _wpPalette[idx % _wpPalette.length];
            var chip = document.createElement('span');
            chip.className = 'fc';
            chip.dataset.type = t.type_code;
            chip.dataset.typePal = JSON.stringify(pal);
            chip.dataset.subTypes = JSON.stringify(t.sub_types||[]);
            chip.dataset.isGear   = (t.type_code === 'G') ? '1' : '0';
            chip.style.background = pal.bg;
            chip.style.color      = pal.fg;
            chip.innerHTML = escHtml(t.type_code + ' — ' + t.type_name);
            chip.onclick = function(){ setPartFilter('type', t.type_code, this); };
            bar.appendChild(chip);
        });
        // Gear types row
        api({ action:'manage_gear_types', op:'list' }).done(function(gr) {
            if (!gr.success) return;
            var gRow = document.getElementById('parts-gear-filter');
            // 清除舊 chips（保留 label + 全部 = 前2個子元素）
            while (gRow.children.length > 2) gRow.removeChild(gRow.lastChild);
            gr.data.forEach(function(g) {
                var chip = document.createElement('span');
                chip.className = 'fc fc-sub';
                chip.dataset.gear = g.gear_type_id;
                chip.innerHTML = escHtml(g.type_name);
                chip.onclick = function(){ setPartFilter('gear', g.gear_type_id, this); };
                gRow.appendChild(chip);
            });
        });
        // 頁面初次載入：顯示所有標籤（不限種類）
        buildLabelFilterRow('');
    });
}

function setPartFilter(dim, val, el) {
    if (dim === 'type') {
        if (val === '') {
            _partsFilter.types = [];
        } else {
            var idx = _partsFilter.types.indexOf(val);
            if (idx >= 0) _partsFilter.types.splice(idx, 1);
            else _partsFilter.types.push(val);
        }
        // Update all type chip active states
        document.querySelectorAll('#parts-type-group .fc[data-type]').forEach(function(c) {
            var ct = c.dataset.type;
            var isActive = (ct === '' || ct === undefined) ? _partsFilter.types.length === 0 : _partsFilter.types.indexOf(ct) >= 0;
            c.classList.toggle('active', isActive);
            if (c.dataset.typePal) {
                var p = JSON.parse(c.dataset.typePal);
                if (isActive) { c.style.background = p.sel; c.style.color = '#fff'; }
                else { c.style.background = p.bg; c.style.color = p.fg; }
            } else {
                if (isActive) { c.style.background = '#2A3F54'; c.style.color = '#fff'; }
                else { c.style.background = ''; c.style.color = ''; }
            }
        });

        _partsFilter.gear = 0; _partsFilter.sub = 0; _partsFilter.labels = [];

        var gRow = document.getElementById('parts-gear-filter');
        var sRow = document.getElementById('parts-sub-filter');
        // Gear row only when exactly 1 type selected and it's G
        var showGear = _partsFilter.types.length === 1 && _partsFilter.types[0] === 'G';
        gRow.classList.toggle('visible', showGear);
        var specRow  = document.getElementById('parts-gear-spec-filter');
        var rangeRow = document.getElementById('parts-gear-range-filter');
        if (specRow)  specRow.classList.toggle('visible', showGear);
        if (rangeRow) rangeRow.classList.toggle('visible', showGear);
        if (showGear) {
            document.querySelectorAll('#parts-gear-filter .fc').forEach(function(c){
                c.classList.remove('active'); c.style.background=''; c.style.color=''; c.style.borderColor='';
            });
            var allGear = document.querySelector('#parts-gear-filter .fc');
            if (allGear) { allGear.classList.add('active'); allGear.style.background='#fff3cd'; allGear.style.color='#030303'; allGear.style.borderColor='#ffeeba'; }
            loadGearSpecOptions();
        } else {
            _partsFilter.gearModules = []; _partsFilter.gearHelixDir = '';
            _partsFilter.gearPressureAngles = []; _partsFilter.gearTeethMin = null;
            _partsFilter.gearTeethMax = null; _partsFilter.gearFwMin = null; _partsFilter.gearFwMax = null;
            ['fg-teeth-min','fg-teeth-max','fg-fw-min','fg-fw-max','fg-ha-min','fg-ha-max'].forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; });
        }

        var selEl = _partsFilter.types.length === 1
            ? document.querySelector('#parts-type-group .fc[data-type="'+_partsFilter.types[0]+'"]')
            : null;
        var subs = selEl && selEl.dataset.subTypes ? JSON.parse(selEl.dataset.subTypes) : [];
        sRow.classList.toggle('visible', _partsFilter.types.length === 1 && subs.length > 0);
        if (subs.length > 0 && _partsFilter.types.length === 1) {
            var pal = selEl.dataset.typePal ? JSON.parse(selEl.dataset.typePal) : _wpPalette[0];
            sRow.innerHTML = '<span class="filter-group-label">小類</span>'
                + '<span class="fc fc-sub active" data-sub="0" style="background:'+pal.sel+';color:#fff;" onclick="setPartFilter(\'sub\',0,this)">全部</span>';
            subs.forEach(function(s) {
                var c = document.createElement('span');
                c.className = 'fc fc-sub';
                c.dataset.sub = s.sub_type_id;
                c.style.cssText = 'background:'+pal.bg+';color:'+pal.fg+';';
                c.textContent = s.sub_type_name;
                c.onclick = function(){ setPartFilter('sub', s.sub_type_id, this); };
                sRow.appendChild(c);
            });
        }

        buildLabelFilterRow(_partsFilter.types.length === 1 ? _partsFilter.types[0] : '');
        updatePartsClearBtn();
        loadParts(1);
        return;
    }

    // gear and sub remain single-select
    _partsFilter[dim] = val;

    var contextPal = null;
    if (_partsFilter.types.length === 1) {
        var atc = document.querySelector('#parts-type-group .fc[data-type="'+_partsFilter.types[0]+'"]');
        if (atc && atc.dataset.typePal) contextPal = JSON.parse(atc.dataset.typePal);
    }

    var groupSel = dim==='gear' ? '#parts-gear-filter .fc' : '#parts-sub-filter .fc';
    document.querySelectorAll(groupSel).forEach(function(c) {
        c.classList.remove('active');
        if (dim === 'sub' && contextPal) { c.style.background = contextPal.bg; c.style.color = contextPal.fg; }
        else { c.style.background = ''; c.style.color = ''; c.style.borderColor = ''; }
    });

    if (el) {
        el.classList.add('active');
        if (dim === 'sub' && contextPal) { el.style.background = contextPal.sel; el.style.color = '#fff'; }
        else if (dim === 'gear') { el.style.background = '#fff3cd'; el.style.color = '#090909'; el.style.borderColor = '#ffeeba'; }
    }

    updatePartsClearBtn();
    loadParts(1);
}

// ── 齒輪規格篩選 ──────────────────────────────────────────────
function loadGearSpecOptions() {
    api({ action:'gear_spec_options' }).done(function(r) {
        if (!r.success) return;
        var modC = document.getElementById('fg-module-chips');
        var paC  = document.getElementById('fg-pa-chips');
        if (!modC || !paC) return;
        modC.innerHTML = '';
        r.modules.forEach(function(m) {
            var c = document.createElement('span');
            c.className = 'fc fc-sub'; c.dataset.gmod = m; c.textContent = m;
            c.onclick = function(){ setGearSpecFilter('module', m, this); };
            modC.appendChild(c);
        });
        paC.innerHTML = '';
        r.pressures.forEach(function(p) {
            var c = document.createElement('span');
            c.className = 'fc fc-sub'; c.dataset.gpa = p; c.textContent = p;
            c.onclick = function(){ setGearSpecFilter('pressureAngle', p, this); };
            paC.appendChild(c);
        });
    });
}

function setGearSpecFilter(dim, val, el) {
    if (dim === 'module') {
        if (val === '') { _partsFilter.gearModules = []; }
        else { var idx=_partsFilter.gearModules.indexOf(val); if(idx>=0) _partsFilter.gearModules.splice(idx,1); else _partsFilter.gearModules.push(val); }
        document.querySelectorAll('#parts-gear-spec-filter .fc[data-gmod]').forEach(function(c){
            c.classList.toggle('active', c.dataset.gmod==='' ? _partsFilter.gearModules.length===0 : _partsFilter.gearModules.indexOf(c.dataset.gmod)>=0);
        });
    } else if (dim === 'helixDir') {
        _partsFilter.gearHelixDir = (_partsFilter.gearHelixDir === val && val !== '') ? '' : val;
        document.querySelectorAll('#parts-gear-spec-filter .fc[data-ghd]').forEach(function(c){
            c.classList.toggle('active', c.dataset.ghd === _partsFilter.gearHelixDir);
        });
    } else if (dim === 'pressureAngle') {
        if (val === '') { _partsFilter.gearPressureAngles = []; }
        else { var idx=_partsFilter.gearPressureAngles.indexOf(val); if(idx>=0) _partsFilter.gearPressureAngles.splice(idx,1); else _partsFilter.gearPressureAngles.push(val); }
        document.querySelectorAll('#parts-gear-spec-filter .fc[data-gpa]').forEach(function(c){
            c.classList.toggle('active', c.dataset.gpa==='' ? _partsFilter.gearPressureAngles.length===0 : _partsFilter.gearPressureAngles.indexOf(c.dataset.gpa)>=0);
        });
    }
    updatePartsClearBtn();
    loadParts(1);
}

var _gearRangeTimer = null;
function onGearRangeInput() {
    clearTimeout(_gearRangeTimer);
    _gearRangeTimer = setTimeout(function() {
        var tMin=document.getElementById('fg-teeth-min'), tMax=document.getElementById('fg-teeth-max');
        var fMin=document.getElementById('fg-fw-min'),   fMax=document.getElementById('fg-fw-max');
        var hMin=document.getElementById('fg-ha-min'),   hMax=document.getElementById('fg-ha-max');
        _partsFilter.gearTeethMin = (tMin&&tMin.value!=='') ? parseFloat(tMin.value) : null;
        _partsFilter.gearTeethMax = (tMax&&tMax.value!=='') ? parseFloat(tMax.value) : null;
        _partsFilter.gearFwMin    = (fMin&&fMin.value!=='') ? parseFloat(fMin.value) : null;
        _partsFilter.gearFwMax    = (fMax&&fMax.value!=='') ? parseFloat(fMax.value) : null;
        _partsFilter.gearHaMin    = (hMin&&hMin.value!=='') ? parseFloat(hMin.value) : null;
        _partsFilter.gearHaMax    = (hMax&&hMax.value!=='') ? parseFloat(hMax.value) : null;
        updatePartsClearBtn();
        loadParts(1);
    }, 350);
}

// ── 料號客戶/產業/等級篩選 ──────────────────────────────────
function initPartsCustomerFilters() {
    // 產業別大類 chips
    var indBar = document.getElementById('parts-industry-filter');
    if (!indBar) return;
    while (indBar.children.length > 2) indBar.removeChild(indBar.lastChild); // keep label + 全部
    api({ action:'get_industry_list' }).done(function(r) {
        if (!r.success) return;
        while (indBar.children.length > 2) indBar.removeChild(indBar.lastChild);
        r.data.forEach(function(ind) {
            var c = document.createElement('span');
            c.className = 'fc fc-sub';
            c.dataset.pind = ind.industry_id;
            c.style.cssText = 'background:#e8f5f2;color:var(--accent);border-color:var(--accent)44;';
            c.textContent = ind.industry_name;
            if (ind.note) c.title = ind.note;
            c.onclick = function(){ setPartIndustryFilter(ind.industry_id, this); };
            indBar.appendChild(c);
        });
    });
}

function setPartGradeFilter(val, el) {
    if (val === '') {
        _partsFilter.grades = [];
    } else {
        var idx = _partsFilter.grades.indexOf(val);
        if (idx >= 0) _partsFilter.grades.splice(idx, 1);
        else _partsFilter.grades.push(val);
    }
    document.querySelectorAll('#parts-grade-filter [data-pgrade]').forEach(function(c) {
        var g = c.dataset.pgrade;
        var isActive = (g === '' || g === undefined) ? _partsFilter.grades.length === 0 : _partsFilter.grades.indexOf(g) >= 0;
        c.classList.toggle('active', isActive);
        if (!g) {
            if (isActive) { c.style.background='#2A3F54'; c.style.color='#fff'; c.style.borderColor='#2A3F54'; }
            else { c.style.background='#f0f2f5'; c.style.color='#555'; c.style.borderColor='transparent'; }
        } else {
            if (isActive) { c.style.background=_gradeColors[g]||'#aaa'; c.style.color='#fff'; c.style.borderColor=_gradeColors[g]||'#aaa'; }
            else { c.style.background=_gradeBg[g]||'#f5f5f5'; c.style.color=_gradeColors[g]||'#aaa'; c.style.borderColor=(_gradeColors[g]||'#aaa')+'aa'; }
        }
    });
    updatePartsClearBtn();
    loadParts(1);
}

function setPartShipSort(val, el) {
    _partsFilter.shipSort = val;
    document.querySelectorAll('#parts-ship-sort-row [data-shipsort]').forEach(function(c) {
        var isActive = c.dataset.shipsort === val;
        c.classList.toggle('active', isActive);
        if (isActive) { c.style.background='#2A3F54'; c.style.color='#fff'; c.style.borderColor='#2A3F54'; }
        else { c.style.background='#f0f2f5'; c.style.color='#555'; c.style.borderColor='transparent'; }
    });
    updatePartsClearBtn();
    loadParts(1);
}

function setPartIndustryFilter(val, el) {
    if (val === 0) {
        _partsFilter.industries = [];
        _partsFilter.industrySubs = [];
    } else {
        var idx = _partsFilter.industries.indexOf(val);
        if (idx >= 0) _partsFilter.industries.splice(idx, 1);
        else _partsFilter.industries.push(val);
    }
    document.querySelectorAll('#parts-industry-filter .fc').forEach(function(c) {
        var cval = parseInt(c.dataset.pind, 10);
        var isActive = isNaN(cval) ? false : (cval === 0 ? _partsFilter.industries.length === 0 : _partsFilter.industries.indexOf(cval) >= 0);
        c.classList.toggle('active', isActive);
        if (isActive) { c.style.background='var(--accent)'; c.style.color='#fff'; c.style.borderColor='var(--accent)'; }
        else { c.style.background='#e8f5f2'; c.style.color='var(--accent)'; c.style.borderColor='var(--accent)44'; }
    });
    var subRow = document.getElementById('parts-industry-sub-filter');
    if (!subRow) { updatePartsClearBtn(); loadParts(1); return; }
    if (_partsFilter.industries.length === 0) {
        subRow.classList.remove('visible');
        _partsFilter.industrySubs = [];
        updatePartsClearBtn(); loadParts(1); return;
    }
    api({ action:'get_industry_subs', industry_ids: _partsFilter.industries.join(',') }).done(function(r) {
        if (!r.success || !r.data || !r.data.length) {
            subRow.classList.remove('visible');
            _partsFilter.industrySubs = [];
        } else {
            subRow.classList.add('visible');
            while (subRow.children.length > 2) subRow.removeChild(subRow.lastChild);
            var availIds = r.data.map(function(s){ return s.sub_id; });
            _partsFilter.industrySubs = _partsFilter.industrySubs.filter(function(s){ return availIds.indexOf(s) >= 0; });
            var allChip = subRow.querySelector('[data-pindsub="0"]');
            if (allChip) {
                if (_partsFilter.industrySubs.length === 0) { allChip.classList.add('active'); allChip.style.background='#2A3F54'; allChip.style.color='#fff'; }
                else { allChip.classList.remove('active'); allChip.style.background='#e8f5f2'; allChip.style.color='var(--accent)'; }
            }
            r.data.forEach(function(s) {
                var active = _partsFilter.industrySubs.indexOf(s.sub_id) >= 0;
                var c = document.createElement('span');
                c.className = 'fc fc-sub' + (active ? ' active' : '');
                c.dataset.pindsub = s.sub_id;
                if (active) c.style.cssText='background:var(--accent);color:#fff;border-color:var(--accent);';
                else c.style.cssText='background:#e8f5f2;color:var(--accent);border-color:var(--accent)44;';
                c.textContent = s.sub_name;
                c.onclick = function(){ setPartIndustrySub(s.sub_id, this); };
                subRow.appendChild(c);
            });
        }
        updatePartsClearBtn(); loadParts(1);
    }).fail(function(){ updatePartsClearBtn(); loadParts(1); });
}

function setPartIndustrySub(val, el) {
    if (val === 0) { _partsFilter.industrySubs = []; }
    else { var idx=_partsFilter.industrySubs.indexOf(val); if(idx>=0) _partsFilter.industrySubs.splice(idx,1); else _partsFilter.industrySubs.push(val); }
    var subRow = document.getElementById('parts-industry-sub-filter');
    if (subRow) {
        subRow.querySelectorAll('.fc').forEach(function(c) {
            var cv = parseInt(c.dataset.pindsub, 10);
            var active = cv === 0 ? _partsFilter.industrySubs.length === 0 : _partsFilter.industrySubs.indexOf(cv) >= 0;
            c.classList.toggle('active', active);
            if (cv === 0) { if(active){c.style.background='#2A3F54';c.style.color='#fff';c.style.borderColor='#2A3F54';}else{c.style.background='#e8f5f2';c.style.color='var(--accent)';c.style.borderColor='var(--accent)44';} }
            else { if(active){c.style.background='var(--accent)';c.style.color='#fff';c.style.borderColor='var(--accent)';}else{c.style.background='#e8f5f2';c.style.color='var(--accent)';c.style.borderColor='var(--accent)44';} }
        });
    }
    updatePartsClearBtn(); loadParts(1);
}

// 客戶自動完成
var _custAcTimer = null;
function onPartsCustInput(kw) {
    clearTimeout(_custAcTimer);
    var dd = document.getElementById('parts-cust-dropdown');
    if (!kw) { if(dd) dd.style.display='none'; return; }
    _custAcTimer = setTimeout(function() {
        api({ action:'search_customers_ac', kw: kw }).done(function(r) {
            if (!r.success || !r.data.length) { dd.style.display='none'; return; }
            dd.innerHTML = r.data.map(function(c) {
                return '<div class="pac-item" data-id="'+escHtml(c.customer_id)+'" data-name="'+escHtml(c.customer_name)+'">'
                    + escHtml(c.customer_id) + ' — ' + escHtml(c.customer_name) + '</div>';
            }).join('');
            dd.style.display='block';
            dd.querySelectorAll('.pac-item').forEach(function(item) {
                item.onclick = function() {
                    selectPartsCust(this.dataset.id, this.dataset.name);
                };
            });
        });
    }, 250);
}
function selectPartsCust(cid, cname) {
    if (_partsFilter.customerIds.indexOf(cid) >= 0) {
        var dd2 = document.getElementById('parts-cust-dropdown');
        if (dd2) dd2.style.display = 'none';
        var inp2 = document.getElementById('parts-cust-input');
        if (inp2) inp2.value = '';
        return;
    }
    _partsFilter.customerIds.push(cid);
    var inp = document.getElementById('parts-cust-input');
    var dd  = document.getElementById('parts-cust-dropdown');
    if (inp) inp.value = '';
    if (dd)  dd.style.display = 'none';
    var chips = document.getElementById('parts-cust-chips');
    if (chips) {
        var chip = document.createElement('span');
        chip.className = 'part-cust-chip';
        chip.dataset.cid = cid;
        chip.innerHTML = escHtml(cid) + ' ' + escHtml(cname)
            + ' <span class="rm" onclick="removePartsCust(\''+escHtml(cid)+'\',this)">×</span>';
        chips.appendChild(chip);
    }
    updatePartsClearBtn();
    loadParts(1);
}
function removePartsCust(cid, rmEl) {
    var idx = _partsFilter.customerIds.indexOf(cid);
    if (idx >= 0) _partsFilter.customerIds.splice(idx, 1);
    if (rmEl && rmEl.parentElement) rmEl.parentElement.remove();
    updatePartsClearBtn();
    loadParts(1);
}
function clearPartsCust() {
    _partsFilter.customerIds = [];
    var inp = document.getElementById('parts-cust-input');
    if (inp) inp.value = '';
    var chips = document.getElementById('parts-cust-chips');
    if (chips) chips.innerHTML = '';
    updatePartsClearBtn();
    loadParts(1);
}

// 取消篩選按鈕顯示邏輯
function updatePartsClearBtn() {
    var hasFilter = _partsFilter.types.length || _partsFilter.gear || _partsFilter.sub
        || (_partsFilter.labels && _partsFilter.labels.length)
        || _partsFilter.customerIds.length || _partsFilter.grades.length
        || _partsFilter.industries.length || _partsFilter.industrySubs.length
        || _partsFilter.keywords.length || _partsFilter.pinnedPartIds.length
        || (_partsFilter.quickKws && _partsFilter.quickKws.length)
        || _partsFilter.gearDaMin !== null || _partsFilter.gearDaMax !== null
        || _partsFilter.gearModules.length || _partsFilter.gearHelixDir !== ''
        || _partsFilter.gearPressureAngles.length
        || _partsFilter.gearTeethMin !== null || _partsFilter.gearTeethMax !== null
        || _partsFilter.gearFwMin !== null || _partsFilter.gearFwMax !== null
        || _partsFilter.gearHaMin !== null || _partsFilter.gearHaMax !== null
        || _partsFilter.shipSort;
    var btn = document.getElementById('parts-clear-filter-btn');
    if (btn) btn.style.display = hasFilter ? '' : 'none';
}

function clearPartsFilter() {
    _partsFilter = { types:[], gear:0, sub:0, labels:[], customerIds:[], grades:[], industries:[], industrySubs:[], keywords:[], pinnedPartIds:[], quickKws:[], gearDaMin:null, gearDaMax:null, shipSort:'', attachTags:[], gearModules:[], gearHelixDir:'', gearPressureAngles:[], gearTeethMin:null, gearTeethMax:null, gearFwMin:null, gearFwMax:null, gearHaMin:null, gearHaMax:null };
    ['fg-teeth-min','fg-teeth-max','fg-fw-min','fg-fw-max','fg-ha-min','fg-ha-max'].forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; });
    document.querySelectorAll('#parts-ship-sort-row [data-shipsort]').forEach(function(c) {
        var isDefault = c.dataset.shipsort === '';
        c.classList.toggle('active', isDefault);
        if (isDefault) { c.style.background='#2A3F54'; c.style.color='#fff'; c.style.borderColor='#2A3F54'; }
        else { c.style.background='#f0f2f5'; c.style.color='#555'; c.style.borderColor='transparent'; }
    });
    var ptc=document.getElementById('parts-type-chips'); if(ptc) ptc.innerHTML='';
    // Clear keyword chips
    var skc = document.getElementById('parts-search-chips'); if (skc) skc.innerHTML = '';
    var ski = document.getElementById('parts-search'); if (ski) ski.value = '';
    // Clear industry sub-row
    var subRow = document.getElementById('parts-industry-sub-filter');
    if (subRow) { subRow.classList.remove('visible'); while(subRow.children.length>2) subRow.removeChild(subRow.lastChild); var ac=subRow.querySelector('[data-pindsub="0"]'); if(ac){ac.classList.add('active');ac.style.background='#2A3F54';ac.style.color='#fff';} }
    // Reset type chips
    document.querySelectorAll('#parts-type-group .fc[data-type]').forEach(function(c) {
        c.classList.remove('active');
        if (c.dataset.typePal) { var p=JSON.parse(c.dataset.typePal); c.style.background=p.bg; c.style.color=p.fg; }
        else { c.style.background=''; c.style.color=''; }
    });
    var allType = document.querySelector('#parts-type-group .fc[data-type=""]');
    if (allType) { allType.classList.add('active'); allType.style.background='#2A3F54'; allType.style.color='#fff'; }
    // Hide collapsible sub-rows (not grade/industry — those are always visible)
    ['parts-gear-filter','parts-gear-spec-filter','parts-gear-range-filter','parts-sub-filter','parts-label-filter','parts-industry-sub-filter'].forEach(function(id) {
        var el = document.getElementById(id); if (el) el.classList.remove('visible');
    });
    // Reset grade chips
    document.querySelectorAll('#parts-grade-filter [data-pgrade]').forEach(function(c) {
        c.classList.remove('active');
        var g = c.dataset.pgrade;
        if (!g) { c.classList.add('active'); c.style.background='#2A3F54'; c.style.color='#fff'; c.style.borderColor='#2A3F54'; }
        else { c.style.background=_gradeBg[g]||'#f5f5f5'; c.style.color=_gradeColors[g]||'#aaa'; c.style.borderColor=(_gradeColors[g]||'#aaa')+'aa'; }
    });
    // Reset industry chips
    document.querySelectorAll('#parts-industry-filter .fc').forEach(function(c) {
        c.classList.remove('active');
        c.style.background='#e8f5f2'; c.style.color='var(--accent)'; c.style.borderColor='var(--accent)44';
    });
    var allInd = document.querySelector('#parts-industry-filter [data-pind="0"]');
    if (allInd) { allInd.classList.add('active'); allInd.style.background='#2A3F54'; allInd.style.color='#fff'; allInd.style.borderColor='#2A3F54'; }
    // Reset customer chips
    var inp = document.getElementById('parts-cust-input');
    if (inp) inp.value = '';
    var chips = document.getElementById('parts-cust-chips');
    if (chips) chips.innerHTML = '';
    updatePartsClearBtn();
    loadParts(1);
}

// ── 多關鍵字搜尋 ──────────────────────────────────────────────
// prefix: 'parts' | 'cust' | 'makers'
function onKwKeydown(event, prefix) {
    if (event.key !== 'Enter') return;
    var inputId = prefix === 'parts' ? 'parts-search' : prefix === 'cust' ? 'customers-search' : 'makers-search';
    var inp = document.getElementById(inputId);
    if (!inp) return;
    var val = inp.value.trim();
    if (!val) return;
    event.preventDefault();
    var ddId = prefix==='parts' ? 'parts-search-dd' : prefix==='cust' ? 'cust-search-dd' : 'makers-search-dd';
    var dd = document.getElementById(ddId); if (dd) dd.style.display='none';
    addKwChip(prefix, val);
}

function removeKwChip(rmEl, prefix) {
    var chip = rmEl.parentElement;
    var val = chip ? chip.dataset.kw : '';
    if (val) {
        if (prefix === 'parts') { var i=_partsFilter.keywords.indexOf(val); if(i>=0) _partsFilter.keywords.splice(i,1); }
        else if (prefix === 'cust') { var i=_custFilter.keywords.indexOf(val); if(i>=0) _custFilter.keywords.splice(i,1); }
        else { var i=_makersFilter.keywords.indexOf(val); if(i>=0) _makersFilter.keywords.splice(i,1); }
    }
    if (chip) chip.remove();
    if (prefix === 'parts') { updatePartsClearBtn(); loadParts(1); }
    else if (prefix === 'cust') { updateCustClearBtn(); loadCustomers(1); }
    else { updateMakersClearBtn(); loadMakers(1); }
}

// 搜尋框外點擊關閉下拉
document.addEventListener('click', function(e) {
    var wrap = document.querySelector('.parts-cust-wrap');
    if (wrap && !wrap.contains(e.target)) {
        var dd = document.getElementById('parts-cust-dropdown');
        if (dd) dd.style.display='none';
    }
    // 關閉搜尋欄建議下拉
    ['parts-search-dd','cust-search-dd','makers-search-dd'].forEach(function(id) {
        var ddEl = document.getElementById(id);
        if (ddEl && ddEl.style.display!=='none') {
            var wrap2 = ddEl.parentElement;
            if (!wrap2 || !wrap2.contains(e.target)) ddEl.style.display='none';
        }
    });
});

// ── addKwChip 通用輔助 ─────────────────────────────────────────────────────
function addKwChip(prefix, val) {
    val = (val||'').trim();
    if (!val) return;
    var stateArr = prefix==='parts' ? _partsFilter.keywords : prefix==='cust' ? _custFilter.keywords : _makersFilter.keywords;
    if (stateArr.indexOf(val) >= 0) return;
    stateArr.push(val);
    var chipsId = prefix==='parts' ? 'parts-search-chips' : prefix==='cust' ? 'cust-search-chips' : 'makers-search-chips';
    var inputId = prefix==='parts' ? 'parts-search' : prefix==='cust' ? 'customers-search' : 'makers-search';
    var container = document.getElementById(chipsId);
    if (container) {
        var chip = document.createElement('span');
        chip.className = 'search-kw-chip';
        chip.dataset.kw = val;
        chip.innerHTML = escHtml(val) + ' <span class="rm" onclick="removeKwChip(this,\''+prefix+'\')">×</span>';
        container.appendChild(chip);
    }
    var inp = document.getElementById(inputId); if (inp) inp.value='';
    if (prefix==='parts') { updatePartsClearBtn(); loadParts(1); }
    else if (prefix==='cust') { updateCustClearBtn(); loadCustomers(1); }
    else { updateMakersClearBtn(); loadMakers(1); }
}

