        api({ action:'search_parts_ac', kw: kw }).done(function(r) {
            if (!r.success || !r.data || !r.data.length) { dd.style.display='none'; return; }
            dd.innerHTML = r.data.map(function(p) {
                var pinned = _partsFilter.pinnedPartIds.indexOf(p.part_id) >= 0;
                return '<div class="pac-item" data-id="'+escHtml(p.part_id)+'" data-spec="'+escHtml(p.spec_no||'')+'" style="'+(pinned?'font-weight:600;':'')+'">'+escHtml(p.part_id)+(p.spec_no?' — '+escHtml(p.spec_no):'')+(pinned?' ✓':'')+'</div>';
            }).join('');
            dd.style.display='block';
            dd.querySelectorAll('.pac-item').forEach(function(item) {
                item.addEventListener('mousedown', function(e) {
                    e.preventDefault();
                    selectPinnedPart(this.dataset.id, this.dataset.spec);
                    var inp=document.getElementById('parts-type-input'); if(inp) inp.value='';
                    dd.style.display='none';
                });
