        chip.className = 'part-cust-chip';
        chip.dataset.mid = makerId;
        chip.innerHTML = escHtml(makerId)+(makerLabel&&makerLabel!==makerId?' '+escHtml(makerLabel):'')+' <span class="rm" onclick="removePinnedMaker(\''+escHtml(makerId)+'\',this)">×</span>';
        chips.appendChild(chip);
    }
    updateMakersClearBtn(); loadMakers(1);
}
function removePinnedMaker(makerId, rmEl) {
    var idx = _makersFilter.pinnedMakerIds.indexOf(makerId);
    if (idx >= 0) _makersFilter.pinnedMakerIds.splice(idx, 1);
    if (rmEl && rmEl.parentElement) rmEl.parentElement.remove();
    updateMakersClearBtn(); loadMakers(1);
}

// ── 快搜 ENTER → 關鍵字 chip ──────────────────────────────────────────────
var _kwChipStyle = 'background:#fff3cd;color:#856404;border:1px solid #f6c23e;border-radius:12px;display:inline-flex;align-items:center;gap:4px;padding:2px 9px;font-size:11px;font-weight:600;cursor:default;margin:1px;';
function _addQuickKwChip(chipsId, kw, filterKws, onDone) {
    if (!kw || filterKws.indexOf(kw) >= 0) return;
    filterKws.push(kw);
    var chips = document.getElementById(chipsId);
    if (chips) {
        var chip = document.createElement('span');
        chip.className = 'part-cust-chip quick-kw-chip';
        chip.dataset.kw = kw;
        chip.style.cssText = _kwChipStyle;
        chip.innerHTML = '<i class="fa fa-search" style="font-size:9px;opacity:.7;"></i> '+escHtml(kw)
            +' <span style="cursor:pointer;margin-left:2px;opacity:.7;" onclick="('+onDone.toString()+')(\''+escHtml(kw).replace(/'/g,"\\'")+"',this)\">×</span>";
        chips.appendChild(chip);
    }
}
function onPartsTypeKeydown(e) {
    if (e.key !== 'Enter' && e.keyCode !== 13) return;
    var inp = document.getElementById('parts-type-input');
    var kw = inp ? inp.value.trim() : '';
    if (!kw) return;
    e.preventDefault();
    _addQuickKwChip('parts-type-chips', kw, _partsFilter.quickKws, removePartsQuickKw);
    if (inp) inp.value = '';
    var dd = document.getElementById('parts-type-dd'); if (dd) dd.style.display = 'none';
    updatePartsClearBtn(); loadParts(1);
}
function removePartsQuickKw(kw, rmEl) {
    var idx = _partsFilter.quickKws.indexOf(kw);
    if (idx >= 0) _partsFilter.quickKws.splice(idx, 1);
    if (rmEl && rmEl.parentElement) rmEl.parentElement.remove();
    updatePartsClearBtn(); loadParts(1);
}
function onCustGradeKeydown(e) {
    if (e.key !== 'Enter' && e.keyCode !== 13) return;
    var inp = document.getElementById('cust-grade-input');
    var kw = inp ? inp.value.trim() : '';
    if (!kw) return;
    e.preventDefault();
    _addQuickKwChip('cust-grade-chips', kw, _custFilter.quickKws, removeCustQuickKw);
    if (inp) inp.value = '';
    var dd = document.getElementById('cust-grade-dd'); if (dd) dd.style.display = 'none';
    updateCustClearBtn(); loadCustomers(1);
}
function removeCustQuickKw(kw, rmEl) {
    var idx = _custFilter.quickKws.indexOf(kw);
    if (idx >= 0) _custFilter.quickKws.splice(idx, 1);
    if (rmEl && rmEl.parentElement) rmEl.parentElement.remove();
    updateCustClearBtn(); loadCustomers(1);
}
function onMakersMainKeydown(e) {
    if (e.key !== 'Enter' && e.keyCode !== 13) return;
