    var kw = inp ? inp.value.trim() : '';
    if (!kw) return;
    e.preventDefault();
    _addQuickKwChip('makers-main-chips', kw, _makersFilter.quickKws, removeMakersQuickKw);
    if (inp) inp.value = '';
    var dd = document.getElementById('makers-main-dd'); if (dd) dd.style.display = 'none';
    updateMakersClearBtn(); loadMakers(1);
}
function removeMakersQuickKw(kw, rmEl) {
    var idx = _makersFilter.quickKws.indexOf(kw);
    if (idx >= 0) _makersFilter.quickKws.splice(idx, 1);
    if (rmEl && rmEl.parentElement) rmEl.parentElement.remove();
    updateMakersClearBtn(); loadMakers(1);
}

// ── 客戶產業別小類篩選 ──────────────────────────────────────────────────────
function updateCustIndustrySub() {
    var subRow = document.getElementById('cust-industry-sub-filter');
    if (!subRow) return;
    var posInds = _custFilter.industries.filter(function(v){ return v > 0; });
    if (!posInds.length) {
        subRow.classList.remove('visible');
        _custFilter.industrySubs = [];
        return;
    }
    api({ action:'get_industry_subs', industry_ids: posInds.join(',') }).done(function(r) {
        if (!r.success||!r.data||!r.data.length) {
            subRow.classList.remove('visible'); _custFilter.industrySubs = [];
        } else {
            subRow.classList.add('visible');
            while (subRow.children.length > 2) subRow.removeChild(subRow.lastChild);
            var availIds = r.data.map(function(s){ return s.sub_id; });
            _custFilter.industrySubs = _custFilter.industrySubs.filter(function(s){ return availIds.indexOf(s)>=0; });
            var allChip3 = subRow.querySelector('[data-cindsub="0"]');
            if (allChip3) {
                if (_custFilter.industrySubs.length===0) { allChip3.classList.add('active'); allChip3.style.background='var(--accent)'; allChip3.style.color='#fff'; }
                else { allChip3.classList.remove('active'); allChip3.style.background='#e8f5f2'; allChip3.style.color='var(--accent)'; }
            }
            r.data.forEach(function(s) {
                var active3 = _custFilter.industrySubs.indexOf(s.sub_id)>=0;
                var c3=document.createElement('span'); c3.className='fc fc-sub'+(active3?' active':'');
                c3.dataset.cindsub=s.sub_id;
                if(active3){c3.style.cssText='background:var(--accent);color:#fff;border-color:var(--accent);';}
                else{c3.style.cssText='background:#e8f5f2;color:var(--accent);border-color:var(--accent)44;';}
                c3.textContent=s.sub_name; c3.onclick=function(){ setCustIndustrySub(s.sub_id,this); }; subRow.appendChild(c3);
            });
            updateCustClearBtn();
        }
    });
}

function setCustIndustrySub(val, el) {
    if (val===0) { _custFilter.industrySubs=[]; }
    else { var idx=_custFilter.industrySubs.indexOf(val); if(idx>=0) _custFilter.industrySubs.splice(idx,1); else _custFilter.industrySubs.push(val); }
    var subRow=document.getElementById('cust-industry-sub-filter');
    if (subRow) {
        subRow.querySelectorAll('.fc').forEach(function(c) {
            var cv=parseInt(c.dataset.cindsub,10);
            var active=cv===0?_custFilter.industrySubs.length===0:_custFilter.industrySubs.indexOf(cv)>=0;
            c.classList.toggle('active',active);
            if(active){c.style.background=cv===0?'#2A3F54':'var(--accent)';c.style.color='#fff';c.style.borderColor=cv===0?'#2A3F54':'var(--accent)';}
            else{c.style.background='#e8f5f2';c.style.color='var(--accent)';c.style.borderColor='var(--accent)44';}
        });
    }
    updateCustClearBtn(); loadCustomers(1);
}

// ── 標籤篩選行建構 ────────────────────────────────────────
function _makeLblValWrap(key, it, hasDl, isRng, small, isDim) {
    var w = parseInt(small ? 54 : 66);
    if (it === 'none' && !isRng && !hasDl && !isDim) return null;
    var vw = document.createElement('span');
    vw.style.cssText = 'display:none;align-items:center;gap:2px;';
    if (hasDl) {
        vw.innerHTML = '<input type="number" placeholder="圖面min" style="width:'+w+'px;" class="form-control input-sm lbl-filter-val" data-role="dl-min" data-lid="'+key+'" oninput="syncLabelFilter()">'
            + '<span style="font-size:10px;color:#aaa;">~</span>'
            + '<input type="number" placeholder="圖面max" style="width:'+w+'px;" class="form-control input-sm lbl-filter-val" data-role="dl-max" data-lid="'+key+'" oninput="syncLabelFilter()">';
    } else if (isDim) {
        vw.innerHTML = '<input type="number" placeholder="第一數字" style="width:'+(small?60:70)+'px;" class="form-control input-sm lbl-filter-val" data-role="dim-main" data-lid="'+key+'" oninput="syncLabelFilter()">';
    } else if (it === 'number' || isRng) {
        vw.innerHTML = '<input type="number" placeholder="min" style="width:'+w+'px;" class="form-control input-sm lbl-filter-val" data-role="min" data-lid="'+key+'" oninput="syncLabelFilter()">'
            + '<span style="font-size:10px;color:#aaa;">~</span>'
            + '<input type="number" placeholder="max" style="width:'+w+'px;" class="form-control input-sm lbl-filter-val" data-role="max" data-lid="'+key+'" oninput="syncLabelFilter()">';
    } else {
        vw.innerHTML = '<input type="text" placeholder="模糊搜尋…" style="width:'+(small?80:100)+'px;" class="form-control input-sm lbl-filter-val" data-role="like" data-lid="'+key+'" oninput="syncLabelFilter()">';
    }
    return vw;
}

function syncGearDaFilter() {
    var lRow = document.getElementById('parts-label-filter');
    if (!lRow) return;
    var mnEl = lRow.querySelector('.lbl-filter-val[data-role="gda-min"]');
    var mxEl = lRow.querySelector('.lbl-filter-val[data-role="gda-max"]');
    _partsFilter.gearDaMin = (mnEl && mnEl.value.trim() !== '') ? parseFloat(mnEl.value) : null;
    _partsFilter.gearDaMax = (mxEl && mxEl.value.trim() !== '') ? parseFloat(mxEl.value) : null;
    updatePartsClearBtn();
    loadParts(1);
}

function buildLabelFilterRow(typeCode) {
    var lRow = document.getElementById('parts-label-filter');
    if (!lRow) return;
    lRow.classList.remove('visible');
    lRow.innerHTML = '<span class="filter-group-label" style="margin-top:4px;">標籤篩選</span>';
    _partsFilter.gearDaMin = null; _partsFilter.gearDaMax = null;
    // typeCode='' → 不限種類，API 會回傳所有標籤，不再提前 return

    // 齒部外徑 range filter（齒輪型 G 才顯示，作為第一個）
    if (typeCode === 'G') {
        lRow.classList.add('visible');
        var daWrap = document.createElement('div');
        daWrap.className = 'lbl-filter-group';
        daWrap.style.cssText = 'display:inline-flex;align-items:center;flex-wrap:wrap;gap:3px;margin:1px 4px 1px 0;vertical-align:middle;';

        var daChip = document.createElement('span');
        daChip.className = 'fc fc-sub';
        daChip.dataset.active = '0';
        daChip.textContent = '齒部外徑';
        daChip.style.cssText = 'background:#fff3e0;color:#e65100;border:1.5px solid #ffcc80;cursor:pointer;';

        var daValWrap = document.createElement('span');
        daValWrap.style.cssText = 'display:none;align-items:center;gap:3px;';

        var daMin = document.createElement('input');
        daMin.type = 'number'; daMin.placeholder = 'min'; daMin.style.width = '60px';
        daMin.className = 'form-control input-sm lbl-filter-val'; daMin.dataset.role = 'gda-min';
        daMin.oninput = function(){ syncGearDaFilter(); };

        var daSep = document.createTextNode(' ~ ');

        var daMax = document.createElement('input');
        daMax.type = 'number'; daMax.placeholder = 'max'; daMax.style.width = '60px';
        daMax.className = 'form-control input-sm lbl-filter-val'; daMax.dataset.role = 'gda-max';
        daMax.oninput = function(){ syncGearDaFilter(); };

        daValWrap.appendChild(daMin);
        daValWrap.appendChild(daSep);
        daValWrap.appendChild(daMax);

        daChip.onclick = (function(c, vw) {
            return function() {
                var isA = c.dataset.active === '1';
                c.dataset.active = isA ? '0' : '1';
                c.style.background = isA ? '#fff3e0' : '#e65100';
                c.style.color      = isA ? '#e65100' : '#fff';
                vw.style.display   = isA ? 'none' : 'inline-flex';
                if (isA) { vw.querySelector('[data-role="gda-min"]').value = ''; vw.querySelector('[data-role="gda-max"]').value = ''; syncGearDaFilter(); }
            };
        })(daChip, daValWrap);

        daWrap.appendChild(daChip);
        daWrap.appendChild(daValWrap);
        lRow.appendChild(daWrap);
    }

    api({ action:'manage_labels', op:'list', type_code:typeCode }).done(function(r) {
        if (!r.success || !r.data || !r.data.length) return;
        lRow.classList.add('visible');
        r.data.forEach(function(ldef) {
            var lid   = String(ldef.label_id);
            var it    = ldef.input_type || 'none';
            var hasDl = (ldef.has_draw_lathe=='1'||ldef.has_draw_lathe===1);
            var hasDlDepth = (ldef.has_draw_lathe_depth=='1'||ldef.has_draw_lathe_depth===1);
            var isRng = (ldef.is_range=='1'||ldef.is_range===1);
            var isDim = (ldef.is_dimension=='1'||ldef.is_dimension===1);
            var needsInput = hasDl || hasDlDepth || it !== 'none' || isRng || isDim;

            var wrap = document.createElement('div');
            wrap.className = 'lbl-filter-group';
            wrap.style.cssText = 'display:inline-flex;align-items:center;flex-wrap:wrap;gap:3px;margin:1px 4px 1px 0;vertical-align:middle;';

            var chip = document.createElement('span');
            chip.className = 'fc fc-sub lbl-main-chip';
            chip.dataset.labelId      = lid;
            chip.dataset.inputType    = it;
            chip.dataset.hasDrawLathe = hasDl ? '1' : '0';
            chip.dataset.hasDlDepth   = hasDlDepth ? '1' : '0';
            chip.dataset.isRange      = isRng ? '1' : '0';
            chip.dataset.isDimension  = isDim ? '1' : '0';
            chip.dataset.active       = '0';
            chip.textContent         = _stripLabelHint(ldef.label_name||'');
            chip.style.cssText = 'background:#f0faf8;color:#1ABB9C;border:1.5px solid #a8dfd4;cursor:pointer;';
            wrap.appendChild(chip);

            var valWrap = _makeLblValWrap(lid, it, hasDl, isRng, false, isDim);
            if (valWrap) wrap.appendChild(valWrap);

            // Sub-labels container (shown when parent active)
            var subSec = document.createElement('span');
            subSec.className = 'lbl-sub-section';
            subSec.style.cssText = 'display:none;align-items:center;flex-wrap:wrap;gap:3px;padding-left:5px;border-left:2px solid #c8e8e0;margin-left:2px;';
            wrap.appendChild(subSec);

            chip.onclick = (function(c, vw, ss, nI) {
                return function() {
                    var isA = c.dataset.active === '1';
                    c.dataset.active = isA ? '0' : '1';
                    c.style.background = isA ? '#f0faf8' : '#1ABB9C';
                    c.style.color      = isA ? '#1ABB9C' : '#fff';
                    if (vw) vw.style.display = (!isA && nI) ? 'inline-flex' : 'none';
                    ss.style.display = !isA ? 'inline-flex' : 'none';
                    syncLabelFilter();
                };
            })(chip, valWrap, subSec, needsInput);

            lRow.appendChild(wrap);

            // Load sub-labels async
            _ensureSubLabelCache(lid, function(subs) {
                if (!subs || !subs.length) return;
                subs.forEach(function(sdef) {
                    var sid    = String(sdef.sub_id);
                    var sit    = sdef.input_type || 'none';
                    var sHasDl = (sdef.has_draw_lathe=='1'||sdef.has_draw_lathe===1);
                    var sHasDlDepth = (sdef.has_draw_lathe_depth=='1'||sdef.has_draw_lathe_depth===1);
                    var sIsRng = (sdef.is_range=='1'||sdef.is_range===1);
                    var sIsEnumF = (sdef.is_enum=='1'||sdef.is_enum===1);
                    var sEnumOptsF = sdef.options || [];
                    var sNeedsInput = sHasDl || sHasDlDepth || sit !== 'none' || sIsRng || (sIsEnumF && sEnumOptsF.length);
                    var sKey   = lid + '_s_' + sid;

                    var sWrap = document.createElement('span');
                    sWrap.style.cssText = 'display:inline-flex;align-items:center;flex-wrap:wrap;gap:2px;';

                    var sChip = document.createElement('span');
                    sChip.className = 'fc fc-sub lbl-sub-chip';
                    sChip.dataset.labelId     = lid;
                    sChip.dataset.subId       = sid;
                    sChip.dataset.inputType   = sit;
                    sChip.dataset.hasDrawLathe = sHasDl ? '1' : '0';
                    sChip.dataset.hasDlDepth   = sHasDlDepth ? '1' : '0';
                    sChip.dataset.isRange     = sIsRng ? '1' : '0';
                    sChip.dataset.isEnum      = sIsEnumF ? '1' : '0';
                    sChip.dataset.active      = '0';
                    sChip.textContent         = sdef.sub_name;
                    sChip.style.cssText = 'background:#e8f8f5;color:#1c7068;border:1px solid #85cec4;font-size:10px;cursor:pointer;padding:1px 7px;';
                    sWrap.appendChild(sChip);

                    var sValWrap;
                    if (sIsEnumF && sEnumOptsF.length) {
                        sValWrap = document.createElement('span');
                        sValWrap.className = 'sub-enum-filter-opts';
                        sValWrap.style.cssText = 'display:none;flex-wrap:wrap;gap:2px;margin-left:3px;';
                        sEnumOptsF.forEach(function(opt) {
                            var oChip = document.createElement('span');
                            oChip.className = 'fc fc-sub sub-enum-filter-opt-chip';
                            oChip.dataset.optVal  = opt.option_value;
                            oChip.dataset.labelId = lid;
                            oChip.dataset.subId   = sid;
                            oChip.dataset.active  = '0';
                            oChip.textContent = opt.option_value;
                            oChip.style.cssText = 'background:#f0f9f7;color:#2e7d6e;border:1px solid #b2dfdb;font-size:9px;cursor:pointer;padding:1px 5px;';
                            oChip.onclick = (function(oc) {
                                return function() {
                                    var isA = oc.dataset.active === '1';
                                    oc.dataset.active = isA ? '0' : '1';
                                    oc.style.background = isA ? '#f0f9f7' : '#2e7d6e';
                                    oc.style.color = isA ? '#2e7d6e' : '#fff';
                                    syncLabelFilter();
                                };
                            })(oChip);
                            sValWrap.appendChild(oChip);
                        });
                    } else {
                        sValWrap = _makeLblValWrap(sKey, sit, sHasDl, sIsRng, true);
                    }
                    if (sValWrap) sWrap.appendChild(sValWrap);

                    sChip.onclick = (function(sc, svw, snI) {
                        return function() {
                            var isA = sc.dataset.active === '1';
                            sc.dataset.active = isA ? '0' : '1';
                            sc.style.background = isA ? '#e8f8f5' : '#1c7068';
                            sc.style.color      = isA ? '#1c7068' : '#fff';
                            if (svw) svw.style.display = (!isA && snI) ? 'inline-flex' : 'none';
                            if (isA && svw) { svw.querySelectorAll('.sub-enum-filter-opt-chip').forEach(function(oc){ oc.dataset.active='0'; oc.style.background='#f0f9f7'; oc.style.color='#2e7d6e'; }); }
                            syncLabelFilter();
                        };
                    })(sChip, sValWrap, sNeedsInput);

                    subSec.appendChild(sWrap);
                });
            });
        });
    });
}

function _readLblVals(container, key, it, hasDl, isRng, isDim) {
    var item = { value_op:'any', vmin:null, vmax:null, value:'' };
    if (hasDl) {
        var mn = container.querySelector('.lbl-filter-val[data-role="dl-min"][data-lid="'+key+'"]');
        var mx = container.querySelector('.lbl-filter-val[data-role="dl-max"][data-lid="'+key+'"]');
        var v1 = mn && mn.value.trim() !== '' ? parseFloat(mn.value) : null;
        var v2 = mx && mx.value.trim() !== '' ? parseFloat(mx.value) : null;
        if (v1 !== null || v2 !== null) { item.value_op='range'; item.vmin=v1; item.vmax=v2; }
    } else if (isDim) {
        var dm = container.querySelector('.lbl-filter-val[data-role="dim-main"][data-lid="'+key+'"]');
        var dv = dm && dm.value.trim() !== '' ? parseFloat(dm.value) : null;
        if (dv !== null && !isNaN(dv)) { item.value_op='dim_eq'; item.value=String(dv); }
    } else if (it === 'number' || isRng) {
        var mn2 = container.querySelector('.lbl-filter-val[data-role="min"][data-lid="'+key+'"]');
        var mx2 = container.querySelector('.lbl-filter-val[data-role="max"][data-lid="'+key+'"]');
        var v3 = mn2 && mn2.value.trim() !== '' ? parseFloat(mn2.value) : null;
        var v4 = mx2 && mx2.value.trim() !== '' ? parseFloat(mx2.value) : null;
        if (v3 !== null || v4 !== null) { item.value_op='range'; item.vmin=v3; item.vmax=v4; }
    } else if (it === 'text') {
        var lk = container.querySelector('.lbl-filter-val[data-role="like"][data-lid="'+key+'"]');
        var lv = lk ? lk.value.trim() : '';
        if (lv) { item.value_op='like'; item.value=lv; }
    }
    return item;
}

function syncLabelFilter() {
    var lRow = document.getElementById('parts-label-filter');
    if (!lRow) return;
    var labels = [];
    lRow.querySelectorAll('.lbl-main-chip').forEach(function(chip) {
        if (chip.dataset.active !== '1') return;
        var lid   = chip.dataset.labelId;
        var it    = chip.dataset.inputType || 'none';
        var hasDl = chip.dataset.hasDrawLathe === '1';
        var hasDlDepth = chip.dataset.hasDlDepth === '1';
        var isRng = chip.dataset.isRange === '1';
        var isDim = chip.dataset.isDimension === '1';
        var vals  = _readLblVals(lRow, lid, it, hasDl, isRng, isDim);
        labels.push({ label_id:lid, value_op:vals.value_op, value:vals.value, vmin:vals.vmin, vmax:vals.vmax, has_draw_lathe:hasDl?1:0, has_draw_lathe_depth:hasDlDepth?1:0, is_range:isRng?1:0, is_dimension:isDim?1:0 });

        // Sub-label filters
        var subSec = chip.parentElement ? chip.parentElement.querySelector('.lbl-sub-section') : null;
        if (subSec) {
            subSec.querySelectorAll('.lbl-sub-chip').forEach(function(sc) {
                if (sc.dataset.active !== '1') return;
                var sid    = sc.dataset.subId;
                var sit    = sc.dataset.inputType || 'none';
                var sHasDl = sc.dataset.hasDrawLathe === '1';
                var sHasDlDepth = sc.dataset.hasDlDepth === '1';
                var sIsRng = sc.dataset.isRange === '1';
                var sIsEnumF = sc.dataset.isEnum === '1';
                // Enum: check for specific option selections
                if (sIsEnumF) {
                    var activeOpts = Array.from(sc.parentElement ? sc.parentElement.querySelectorAll('.sub-enum-filter-opt-chip[data-active="1"]') : []);
                    if (activeOpts.length > 0) {
                        activeOpts.forEach(function(oc) {
                            labels.push({ label_id:lid, sub_id:sid, value_op:'eq', value:oc.dataset.optVal });
                        });
                    } else {
                        labels.push({ label_id:lid, sub_id:sid, value_op:'any', value:'', vmin:null, vmax:null, has_draw_lathe:0, is_range:0 });
                    }
                    return;
                }
                var sKey   = lid + '_s_' + sid;
                var sVals  = _readLblVals(lRow, sKey, sit, sHasDl, sIsRng);
                labels.push({ label_id:lid, sub_id:sid, value_op:sVals.value_op, value:sVals.value, vmin:sVals.vmin, vmax:sVals.vmax, has_draw_lathe:sHasDl?1:0, has_draw_lathe_depth:sHasDlDepth?1:0, is_range:sIsRng?1:0 });
            });
        }
    });
    _partsFilter.labels = labels;
    loadParts(1);
}

// ── 客戶產業別篩選初始化 ──────────────────────────────────
function initCustFilterBar() {
    var bar = document.getElementById('cust-industry-group');
    if (!bar) return;
    while (bar.children.length > 3) bar.removeChild(bar.lastChild);
    api({ action:'get_industry_list' }).done(function(r) {
        if (!r.success) return;
        while (bar.children.length > 3) bar.removeChild(bar.lastChild);
        r.data.forEach(function(ind) {
            var chip = document.createElement('span');
            chip.className = 'fc';
            chip.dataset.ind = ind.industry_id;
            chip.style.cssText = 'background:#e8f5f2;color:var(--accent);border-color:var(--accent)44;';
            chip.textContent = ind.industry_name;
            if (ind.note) chip.title = ind.note;
            chip.onclick = function(){ setCustFilter(ind.industry_id, this); };
            bar.appendChild(chip);
        });
    });
}

// Grade colours for active state
var _gradeColors = {S:'#7b1fa2',A:'#1565c0',B:'#1ABB9C',C:'#f39c12',D:'#aaa'};
var _gradeBg     = {S:'#f3e5f5',A:'#e3f2fd',B:'#e8f5e9',C:'#fff3e0',D:'#f5f5f5'};

function setCustGradeFilter(val, el) {
    if (val === '') { _custFilter.grades = []; }
    else { var idx=_custFilter.grades.indexOf(val); if(idx>=0) _custFilter.grades.splice(idx,1); else _custFilter.grades.push(val); }
    document.querySelectorAll('#cust-grade-group [data-grade]').forEach(function(c){
        var g = c.dataset.grade;
        var active = (g===''||g===undefined) ? _custFilter.grades.length===0 : _custFilter.grades.indexOf(g)>=0;
        c.classList.toggle('active', active);
        if (!g) {
            if (active) { c.style.background='#2A3F54'; c.style.color='#fff'; c.style.borderColor='#2A3F54'; }
            else { c.style.background='#f0f2f5'; c.style.color='#555'; c.style.borderColor='transparent'; }
        } else {
            if (active) { c.style.background=_gradeColors[g]||'#aaa'; c.style.color='#fff'; c.style.borderColor=_gradeColors[g]||'#aaa'; }
            else { c.style.background=_gradeBg[g]||'#f5f5f5'; c.style.color=_gradeColors[g]||'#aaa'; c.style.borderColor=(_gradeColors[g]||'#aaa')+'aa'; }
        }
    });
    updateCustClearBtn(); loadCustomers(1);
}

function setCustFilter(val, el) {
    if (val === 0) { _custFilter.industries = []; _custFilter.industrySubs = []; }
    else { var idx=_custFilter.industries.indexOf(val); if(idx>=0) _custFilter.industries.splice(idx,1); else _custFilter.industries.push(val); }
    document.querySelectorAll('#cust-industry-group [data-ind]').forEach(function(c){
        var cval=parseInt(c.dataset.ind,10);
        var active = isNaN(cval) ? false : (cval===0 ? _custFilter.industries.length===0 : _custFilter.industries.indexOf(cval)>=0);
        c.classList.toggle('active', active);
        if (cval===-1) {
            if (active) { c.style.background='#555'; c.style.color='#fff'; c.style.borderColor='#555'; }
            else { c.style.background='#f5f5f5'; c.style.color='#888'; c.style.borderColor='#ddd'; }
        } else {
            if (active) { c.style.background='var(--accent)'; c.style.color='#fff'; c.style.borderColor='var(--accent)'; }
            else { c.style.background='#e8f5f2'; c.style.color='var(--accent)'; c.style.borderColor='var(--accent)44'; }
        }
    });
    updateCustIndustrySub();
    updateCustClearBtn(); loadCustomers(1);
}

function updateCustClearBtn() {
