function initMakersFilterBar() {
    var bar = document.getElementById('makers-main-group');
    if (!bar) return;
    // Keep: pac-wrap(0) + chips-span(1) + label(2) + 全部(3) + 未分類(4) = 5 children
    while (bar.children.length > 5) bar.removeChild(bar.lastChild);
    api({ action:'manage_maker_main_cats', op:'list' }).done(function(r) {
        if (!r.success) return;
        while (bar.children.length > 5) bar.removeChild(bar.lastChild);
        // Also update _mainCatIdxMap for colour consistency
        _mainCatIdxMap = {};
        r.data.forEach(function(cat, idx) {
            _mainCatIdxMap[String(cat.main_cat_id)] = idx;
            var pal = _mainCatPalette[idx % _mainCatPalette.length];
            var chip = document.createElement('span');
            chip.className = 'fc';
            chip.dataset.main    = cat.main_cat_id;
            chip.dataset.subCats = JSON.stringify(cat.sub_cats || []);  // store sub_cats
            chip.style.cssText   = 'background:'+pal.bg+';color:'+pal.fg+';border-color:'+pal.fg+'44;';
            chip.textContent     = cat.main_cat_name;
            chip.onclick = function(){ setMakerFilter(cat.main_cat_id, this); };
            bar.appendChild(chip);
        });
    });
}

function setMakerFilter(val, el) {
    if (val === 0) { _makersFilter.main_cats = []; _makersFilter.sub_cats = []; }
    else { var idx=_makersFilter.main_cats.indexOf(val); if(idx>=0) _makersFilter.main_cats.splice(idx,1); else _makersFilter.main_cats.push(val); }

    document.querySelectorAll('#makers-filter-bar .filter-group .fc').forEach(function(c){
        var mid = parseInt(c.dataset.main||'0');
        var active = mid===0 ? _makersFilter.main_cats.length===0 : _makersFilter.main_cats.indexOf(mid)>=0;
        c.classList.toggle('active', active);
        if (mid===0) {
            if (active) { c.style.background='#2A3F54'; c.style.color='#fff'; c.style.borderColor='#2A3F54'; }
            else { c.style.background='#f0f2f5'; c.style.color='#666'; c.style.borderColor='transparent'; }
        } else if (mid===-1) {
            if (active) { c.style.background='#555'; c.style.color='#fff'; c.style.borderColor='#555'; }
            else { c.style.background='#f5f5f5'; c.style.color='#888'; c.style.borderColor='#ddd'; }
        } else {
            var pal = _mainCatIdxMap&&_mainCatIdxMap[String(c.dataset.main)]!==undefined ? _mainCatPalette[_mainCatIdxMap[String(c.dataset.main)]%_mainCatPalette.length] : _mainCatPalette[0];
            if (active) { c.style.background=pal.sel; c.style.color='#fff'; c.style.borderColor=pal.sel; }
            else { c.style.background=pal.bg; c.style.color=pal.fg; c.style.borderColor=pal.fg+'44'; }
        }
    });

    // Sub-cat row: show when any main_cat selected; collect subs from all selected cats
    var subRow = document.getElementById('makers-sub-filter');
    if (subRow) {
        if (_makersFilter.main_cats.length === 0) {
            subRow.classList.remove('visible');
            _makersFilter.sub_cats = [];
            subRow.innerHTML = '<span class="filter-group-label">小類</span><span class="fc fc-sub active" data-subcat="0" onclick="setMakerSubFilter(0,this)">全部</span>';
        } else {
            var allSubs = [];
            _makersFilter.main_cats.forEach(function(mid2) {
                var selEl = document.querySelector('#makers-filter-bar .filter-group .fc[data-main="'+mid2+'"]');
                var subs = selEl&&selEl.dataset.subCats ? JSON.parse(selEl.dataset.subCats) : [];
                subs.forEach(function(s) {
                    if (!allSubs.find(function(x){ return x.sub_cat_id===s.sub_cat_id; })) allSubs.push({sub_cat_id:s.sub_cat_id, sub_cat_name:s.sub_cat_name, main_cat_id:mid2});
                });
            });
            if (!allSubs.length) {
                subRow.classList.remove('visible');
                _makersFilter.sub_cats = [];
                subRow.innerHTML = '<span class="filter-group-label">小類</span><span class="fc fc-sub active" data-subcat="0" onclick="setMakerSubFilter(0,this)">全部</span>';
            } else {
                subRow.classList.add('visible');
                var availSubIds = allSubs.map(function(s){ return s.sub_cat_id; });
                _makersFilter.sub_cats = _makersFilter.sub_cats.filter(function(s){ return availSubIds.indexOf(s)>=0; });
                var allNone = _makersFilter.sub_cats.length===0;
                subRow.innerHTML = '<span class="filter-group-label">小類</span>';
                var allChip = document.createElement('span'); allChip.className='fc fc-sub'+(allNone?' active':'');
                allChip.dataset.subcat='0';
                allChip.style.cssText=allNone?'background:#2A3F54;color:#fff;border-color:#2A3F54;':'background:#f0f2f5;color:#666;border-color:transparent;';
                allChip.textContent='全部'; allChip.onclick=function(){ setMakerSubFilter(0,this); }; subRow.appendChild(allChip);
                allSubs.forEach(function(s) {
                    var pal2 = _mainCatIdxMap&&_mainCatIdxMap[String(s.main_cat_id)]!==undefined ? _mainCatPalette[_mainCatIdxMap[String(s.main_cat_id)]%_mainCatPalette.length] : _mainCatPalette[0];
                    var active2 = _makersFilter.sub_cats.indexOf(s.sub_cat_id)>=0;
                    var c2=document.createElement('span'); c2.className='fc fc-sub'+(active2?' active':'');
                    c2.dataset.subcat=s.sub_cat_id; c2.dataset.maincat=s.main_cat_id;
                    c2.style.cssText=active2?'background:'+pal2.sel+';color:#fff;border-color:'+pal2.sel+';':'background:'+pal2.bg+';color:'+pal2.fg+';border-color:'+pal2.fg+'44;';
                    c2.textContent=s.sub_cat_name; c2.onclick=function(){ setMakerSubFilter(s.sub_cat_id,this); }; subRow.appendChild(c2);
                });
            }
        }
    }
    updateMakersClearBtn(); loadMakers(1);
}

