function _procLabelEffectiveType(itype, ntype) {
    if (itype === 'text')    return 'text';
    if (itype === 'numeric') return ntype || 'range';
    return 'none';
}
function setMakerProcLabelFilter(id, itype, ntype) {
    id = parseInt(id, 10);
    var ftype = _procLabelEffectiveType(itype, ntype);
    var chip  = document.querySelector('#makers-proc-label-filter .fc[data-plid="'+id+'"]');
    var valArea = document.querySelector('#makers-proc-label-filter .mf-filter-val-area[data-plid="'+id+'"]');
    var hasInput = (ftype !== 'none');
    if (hasInput) {
        var isVisible = valArea && valArea.style.display !== 'none';
        if (isVisible) {
            if (valArea) { valArea.style.display = 'none'; var vi = valArea.querySelector('.mf-filter-val'); if(vi) vi.value = ''; }
            var idx = _makersFilter.proc_labels.findIndex(function(e){ return e.id === id; });
            if (idx >= 0) _makersFilter.proc_labels.splice(idx, 1);
            if (chip) chip.classList.remove('active');
            updateMakersClearBtn(); loadMakers(1);
        } else {
            if (valArea) {
                valArea.style.display = 'inline-flex';
                var fi = valArea.querySelector('.mf-filter-val');
                if (fi) setTimeout(function(){ fi.focus(); fi.select && fi.select(); }, 50);
            }
            if (chip) chip.classList.add('active');
        }
    } else {
        var idx = _makersFilter.proc_labels.findIndex(function(e){ return e.id === id; });
        if (idx >= 0) {
            _makersFilter.proc_labels.splice(idx, 1);
            if (chip) chip.classList.remove('active');
        } else {
            _makersFilter.proc_labels.push({ id: id, filter_type: 'none', value: null });
            if (chip) chip.classList.add('active');
        }
        updateMakersClearBtn(); loadMakers(1);
    }
}
function applyMakerProcLabelFilter(id, ftype) {
    id = parseInt(id, 10);
    var valArea = document.querySelector('#makers-proc-label-filter .mf-filter-val-area[data-plid="'+id+'"]');
    if (!valArea) return;
    var vi   = valArea.querySelector('.mf-filter-val');
    var fval = vi ? vi.value.trim() : '';
    var idx  = _makersFilter.proc_labels.findIndex(function(e){ return e.id === id; });
    if (fval !== '') {
        var entry = { id: id, filter_type: ftype, value: ftype === 'text' ? fval : parseFloat(fval) };
        if (idx >= 0) _makersFilter.proc_labels[idx] = entry;
        else _makersFilter.proc_labels.push(entry);
    } else {
        if (idx >= 0) _makersFilter.proc_labels.splice(idx, 1);
    }
    updateMakersClearBtn(); loadMakers(1);
}
function initMakerProcLabelFilter(forceApi) {
    function buildUI(r) {
        var row = document.getElementById('makers-proc-label-filter');
        if (!row) return;
        if (!r.success || !r.data || !r.data.length) { row.style.display = 'none'; return; }
        while (row.children.length > 1) row.removeChild(row.lastChild);
        r.data.forEach(function(lbl) {
            var itype  = lbl.input_type  || 'none';
            var ntype  = lbl.numeric_type || 'range';
            var ftype  = _procLabelEffectiveType(itype, ntype);
            var chip = document.createElement('span');
            chip.className = 'fc';
            chip.dataset.plid  = lbl.proc_label_id;
            chip.dataset.itype = itype;
            chip.dataset.ntype = ntype;
            chip.textContent   = lbl.label_name;
            chip.onclick = (function(lid, it, nt){ return function(){ setMakerProcLabelFilter(lid, it, nt); }; })(lbl.proc_label_id, itype, ntype);
            row.appendChild(chip);
            if (ftype !== 'none') {
                var unit     = lbl.unit || 'mm';
                var valArea  = document.createElement('span');
                valArea.className      = 'mf-filter-val-area';
                valArea.dataset.plid   = lbl.proc_label_id;
                valArea.style.cssText  = 'display:none;align-items:center;gap:4px;';
                var unitHtml   = (unit && unit !== 'mm') ? '<span style="font-size:11px;color:#888;">'+escHtml(unit)+'</span>' : '';
                var inputType  = ftype === 'text' ? 'text' : 'number';
                valArea.innerHTML =
                    '<input type="'+inputType+'" class="form-control input-sm mf-filter-val" data-plid="'+lbl.proc_label_id+'" step="0.001" style="width:'+(ftype==='text'?'110':'70')+'px;" placeholder="輸入數值">'
                    + unitHtml;
                (function(lid, ft){
                    var vi = valArea.querySelector('.mf-filter-val');
                    if (vi) vi.addEventListener('input', debounce(function(){ applyMakerProcLabelFilter(lid, ft); }, 400));
                })(lbl.proc_label_id, ftype);
                row.appendChild(valArea);
            }
        });
        row.style.display = 'flex';
    }
    var labels = (typeof MAKER_PROC_LABELS !== 'undefined') ? MAKER_PROC_LABELS : [];
    if (forceApi || labels.length === 0) {
        api({ action:'manage_maker_proc_labels', op:'list' }).done(function(r) { buildUI(r); });
    } else {
        buildUI({success:true, data:labels});
    }
}

var partsLoaded=false, partsCurrent=1, partsTotal=1;

function loadParts(pg) {
    pg = pg || 1;
    partsCurrent = pg;
    var liveKw = (document.getElementById('parts-search')||{}).value || '';
    var allKws = _partsFilter.keywords.slice().concat(_partsFilter.quickKws||[]); if (liveKw.trim()) allKws.push(liveKw.trim());
    document.getElementById('parts-table-wrap').innerHTML = '<div class="table-loading"><div class="spinner"></div> 載入中…</div>';
    api({ action:'list_parts', keywords_p:allKws.join('||'), page:pg,
          filter_type:             _partsFilter.types.join(','),
          filter_gear:             _partsFilter.gear,
          filter_sub:              _partsFilter.sub,
          filter_labels:           JSON.stringify(_partsFilter.labels||[]),
          filter_gear_da_min:      _partsFilter.gearDaMin !== null ? _partsFilter.gearDaMin : '',
          filter_gear_da_max:      _partsFilter.gearDaMax !== null ? _partsFilter.gearDaMax : '',
          filter_gear_modules:     JSON.stringify(_partsFilter.gearModules||[]),
          filter_gear_helix_dir:   _partsFilter.gearHelixDir||'',
          filter_gear_pressures:   JSON.stringify(_partsFilter.gearPressureAngles||[]),
          filter_gear_teeth_min:   _partsFilter.gearTeethMin !== null ? _partsFilter.gearTeethMin : '',
          filter_gear_teeth_max:   _partsFilter.gearTeethMax !== null ? _partsFilter.gearTeethMax : '',
          filter_gear_fw_min:      _partsFilter.gearFwMin !== null ? _partsFilter.gearFwMin : '',
          filter_gear_fw_max:      _partsFilter.gearFwMax !== null ? _partsFilter.gearFwMax : '',
          filter_gear_ha_min:      _partsFilter.gearHaMin !== null ? _partsFilter.gearHaMin : '',
          filter_gear_ha_max:      _partsFilter.gearHaMax !== null ? _partsFilter.gearHaMax : '',
          filter_pinned_part_ids:  _partsFilter.pinnedPartIds.join(','),
          filter_customer_ids:     _partsFilter.customerIds.join(','),
          filter_grades_p:         _partsFilter.grades.join(','),
          filter_industries_p:     _partsFilter.industries.join(','),
          filter_industry_subs_p:  _partsFilter.industrySubs.join(','),
          sort_by:                 _partsFilter.shipSort,
          filter_attach_tags:      JSON.stringify(_partsFilter.attachTags||[])
    }).done(function(r) {
        if (!r.success) { showToast(r.message,'error'); return; }
        partsLoaded = true;
        partsTotal  = r.pages;
        ensureTypeLabel(function(){
            renderPartsTable(r.data, r.total, pg, r.pages);
        });
    }).fail(function(){ showToast('網路錯誤','error'); });
}

var typeLabel = {G:'齒輪', H:'滾刀', N:'一般'};  // will be extended from DB
var _typeLabelLoaded = false;
// 各工件種類的料號表單欄位顯示設定（由 manage_workpiece_types 帶出 show_vendor/show_part_no/show_machine/show_price）
var partTypeMeta = {};

function ensureTypeLabel(callback) {
    if (_typeLabelLoaded) { callback(); return; }
    api({ action:'manage_workpiece_types', op:'list' }).done(function(r) {
        if (r.success && r.data) {
            r.data.forEach(function(t){ typeLabel[t.type_code] = t.type_name; });
        }
        _typeLabelLoaded = true;
        callback();
    }).fail(function(){ callback(); });
}

// ── 圖面開啟（獨立跳窗，使用 bom_viewer.php d_id 模式：BOM圖＋料號附件＋自動標籤）
function openPartDrawing(pid) {
    if (!pid) return;
    var w = screen.availWidth, h = screen.availHeight;
    var pw = Math.min(1400, Math.round(w * 0.85));
    var ph = Math.min(900,  Math.round(h * 0.88));
    var pl = Math.round((w - pw) / 2);
    var pt = Math.round((h - ph) / 2);
    window.open(
        '../pm/bom_viewer.php?d_id=' + encodeURIComponent(pid),
        'bom_dv_' + pid,
        'width=' + pw + ',height=' + ph + ',left=' + pl + ',top=' + pt
            + ',resizable=yes,scrollbars=yes,menubar=no,toolbar=no,location=no,status=no'
    );
}

function renderPartsTable(rows, total, pg, pages) {
    var colCount = 10 + (CAN_UPDATE||CAN_DELETE_ALL ? 1 : 0) + (CAN_SEE_DESIGN ? 1 : 0);
    var html = '<div style="overflow-x:auto;"><table class="table"><thead><tr>';
    html += '<th style="width:36px;">#</th>';
    html += '<th style="max-width:130px;">料號</th><th>規格</th><th style="white-space:nowrap;">版次 / 發行日</th><th>種類</th><th>客戶</th><th>備註</th><th style="white-space:nowrap;">重量</th>';
    html += '<th style="white-space:nowrap;min-width:90px;">出貨筆數/件數</th>';
    html += '<th style="min-width:80px;white-space:nowrap;"><i class="fa fa-paperclip"></i> 附件</th>';
    if (CAN_SEE_DESIGN) html += '<th style="min-width:120px;">設計備註</th>';
    if (CAN_UPDATE||CAN_DELETE_ALL) html += '<th style="text-align:center;width:80px;">操作</th>';
    html += '</tr></thead><tbody>';

    if (!rows.length) {
        html += '<tr><td colspan="'+colCount+'"><div class="empty-state"><i class="fa fa-search"></i>查無資料</div></td></tr>';
    } else {
        rows.forEach(function(r, i) {
            var t = r.Type||'N';
            var typeBadge = '<span class="badge-type badge-'+t+'">'+t+' — '+(typeLabel[t]||'')+'</span>';
            var asmBadge = (r.Is_Assembly=='1') ? '<span class="badge-type badge-G" style="margin-left:3px;">組合件</span>' : '';
            // 子件標籤＋所屬組合件料號（一個料號可能屬於多個組合件；超過 2 個以 +N 收合，tooltip 列全部）
            var subBadge = '', subParentsHtml = '';
            if (r.parent_assemblies) {
                var _pas = r.parent_assemblies.split(',');
                subBadge = '<span class="badge-type" style="margin-left:3px;background:#e0f2f1;color:#00695c;border:1px solid #4db6ac;">子件</span>';
                var _pasShow = _pas.slice(0,2).map(escHtml).join('、') + (_pas.length > 2 ? ' +'+(_pas.length-2) : '');
                subParentsHtml = '<div style="font-size:10px;color:#888;margin-top:2px;line-height:1.2;" title="所屬組合件：'+escHtml(_pas.join('、'))+'">組合件名稱：'+_pasShow+'</div>';
            }
            // 關鍵字搜尋時，料號本身未命中、因所屬組合件命中而帶出的列 → 標示來源
            var pulledHtml = '';
            if (r.kw_direct == 0 && r.kw_parent_srcs) {
                var _pss = r.kw_parent_srcs.split(',');
                var _pssShow = _pss.slice(0,2).map(escHtml).join('、') + (_pss.length > 2 ? ' +'+(_pss.length-2) : '');
                pulledHtml = '<div style="font-size:10px;color:#e67e22;margin-top:2px;line-height:1.2;" title="此料號本身未含關鍵字，因其組合件命中而列出：'+escHtml(_pss.join('、'))+'">↳ 由組合件 '+_pssShow+' 帶出</div>';
            }
            html += '<tr>';
            html += '<td style="color:#aaa;font-size:11px;">'+(((pg-1)*10)+i+1)+'</td>';
            // 齒輪規格小字（僅 G 種類）
            var gearSpec = (r.Type==='G' && r.gear_spec_str)
                ? '<span style="font-size:10px;color:#888;font-family:Consolas,monospace;letter-spacing:.3px;display:block;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:1.2;margin-top:1px;" title="'+escHtml(r.gear_spec_str)+'">'+escHtml(r.gear_spec_str)+'</span>' : '';
            var dIdBadge = '<span style="font-size:10px;color:#bbb;font-family:Consolas,monospace;letter-spacing:.3px;display:block;line-height:1.2;margin-top:1px;">id:'+r.d_id+'</span>';
            var drawingBadge = (r.Drawing_No && r.Drawing_No !== r.D_Setting_Id)
                ? '<span style="font-size:10px;color:#1a7abf;display:block;line-height:1.2;margin-top:1px;" title="圖面代號">代：'+escHtml(r.Drawing_No)+'</span>' : '';
            if (r.has_drawing || (MD_CAN_OTHER && r.has_attach) || (MD_CAN_QUOTE && r.has_quote)) {
                html += '<td style="max-width:160px;line-height:1.3;"><strong class="part-drawing-link" onclick="openPartDrawing(\''+escHtml(r.D_Setting_Id)+'\')" title="點擊開啟圖面 / 附件">'+escHtml(r.D_Setting_Id)+'</strong>'+dIdBadge+drawingBadge+gearSpec+'</td>';
            } else {
                html += '<td style="max-width:160px;line-height:1.3;"><strong style="font-family:Consolas,monospace;">'+escHtml(r.D_Setting_Id)+'</strong>'+dIdBadge+drawingBadge+gearSpec+'</td>';
            }
            // 規格 + 標籤
            var labelsHtml = '';
            // 齒部外徑 chip（僅 G 種類有計算值）
            if (r.Type === 'G' && r.gear_da_str) {
                r.gear_da_str.split('/').forEach(function(daStr) {
                    var daNum = parseFloat(daStr);
                    if (!isNaN(daNum)) {
                        labelsHtml += '<span class="part-label-chip" style="background:#fff3e0;color:#e65100;border-color:#ffcc80;">齒部外徑<em style="font-style:normal;font-weight:normal;opacity:.9;"> ' + escHtml(trimFloat(daNum)) + '</em></span>';
                    }
                });
            }
            if (r.labels_str) {
                var _lsegs = r.labels_str.split('\n');
                var _calcBaseSubIds = {};
                // First pass: collect base/sub label IDs used by calc_diff labels
                _lsegs.forEach(function(seg) {
                    var p = seg.split('|');
                    if (p.length < 17) return;
                    if (p[14]==='1') { if(p[15]) _calcBaseSubIds[p[15]]=1; if(p[16]) _calcBaseSubIds[p[16]]=1; }
                });
                var _tf2 = function(v){ var n=parseFloat(v); return (!isNaN(n)&&v!=='')?String(trimFloat(n)):String(v); };
                // Second pass: render chips
                _lsegs.forEach(function(seg) {
                    var parts    = seg.split('|'); // [0]label_id [1]label_name [2]input_type [3]input_value [4]has_draw_lathe [5]draw_dim [6]lathe_dim [7]sub_names [8]is_range [9]value_min [10]value_max [11]has_tolerance [12]tol_upper [13]tol_lower [14]is_calc_diff [15]calc_base_name [16]calc_sub_name [17]calc_value [18]calc_value_min [19]calc_value_max [20]is_dimension [21]is_qty_dim [22]prefix_char [23]suffix_char [24]is_hidden_frontend [25]qty [26]lathe_optional [27]has_draw_lathe_depth [28]is_triple_dim
                    if (parts.length < 5) return;
                    var lid      = parts[0]||'';
                    if (_calcBaseSubIds[lid]) return; // hide base/sub of calc_diff
                    var lname    = parts[1]||'';
                    var hasDl    = (parts[4]==='1');
                    var lval     = parts[3]||'';
                    var drawD    = parts[5]||'';
                    var lathD    = parts[6]||'';
                    var subNames = parts[7]||'';
                    var isRng    = (parts[8]==='1');
                    var vmin     = parts[9]||'';
                    var vmax     = parts[10]||'';
                    var hasTolF  = (parts[11]==='1');
                    var tolU     = parts[12]||'';
                    var tolL     = parts[13]||'';
                    var isCalcF  = (parts[14]==='1');
                    var calcVal  = parts[17]||'';
                    var calcVMin = parts[18]||'';
                    var calcVMax = parts[19]||'';
                    var isDimF      = (parts[20]==='1');
                    var isQtyDimF   = (parts[21]==='1');
                    var pfxF        = parts[22]||'';
                    var sfxF        = parts[23]||'';
                    var isHiddenF   = (parts[24]==='1');
                    var qtyF        = parts[25]||'';
                    var latheOptF     = (parts[26]==='1');
                    var hasDlDepthF   = (parts[27]==='1');
                    var isTripleDimF  = (parts[28]==='1');
                    // Skip hidden labels unless this label is actively being filtered on
                    if (isHiddenF) {
                        var isFilteredByLabel = _partsFilter.labels && _partsFilter.labels.some(function(lf) {
                            return String(lf.label_id) === lid;
                        });
                        if (!isFilteredByLabel) return;
                    }
                    var chip = escHtml(_stripLabelHint(lname));
                    var chipStyle = '';
                    if (isCalcF) {
                        chipStyle = 'background:#f3e5f5;border-color:#ce93d8;color:#6a1b9a;';
                        if (calcVMin !== '' && calcVMax !== '') {
                            chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(_tf2(calcVMin))+'~'+escHtml(_tf2(calcVMax))+'</em>';
                        } else if (calcVal !== '') {
                            chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(_tf2(calcVal))+'</em>';
                        } else {
                            chip += '<em style="font-style:normal;opacity:.6;"> 待計算</em>';
                        }
                    } else if (isTripleDimF && (vmin||vmax)) {
                        var sm3 = vmin ? _tf2(vmin) : '';
                        var lg3 = vmax ? _tf2(vmax) : '';
                        var dp3 = drawD ? _tf2(drawD) : '';
                        chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(sm3?pfxF+sm3:'')+(lg3?'x'+pfxF+lg3:'')+(dp3?'x'+dp3+sfxF:'')+'</em>';
                    } else if (hasDlDepthF && (drawD||lathD)) {
                        var dd2 = drawD ? _tf2(drawD) : '';
                        var ld2 = lathD ? _tf2(lathD) : '';
                        var dep2= vmin  ? _tf2(vmin)  : '';
                        chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(dd2?'圖'+dd2:'')+(ld2?' 車'+ld2+(dep2?'x'+dep2+sfxF:''):'')+'</em>';
                    } else if (hasDl) {
                        var dd = drawD !== '' ? parseFloat(drawD)||drawD : '';
                        var ld = lathD !== '' ? parseFloat(lathD)||lathD : '';
                        if (dd !== '') chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+dd+(ld!==''?' 車'+ld:'')+'</em>';
                    } else if (isQtyDimF && (vmin||vmax)) {
                        var qtyNumF = (qtyF && parseFloat(qtyF) > 1) ? escHtml(_tf2(qtyF))+'-' : '';
                        chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+qtyNumF+escHtml(pfxF)+escHtml(_tf2(vmin))+'×'+escHtml(_tf2(vmax))+escHtml(sfxF)+'</em>';
                    } else if (isDimF && (vmin||vmax)) {
                        chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(pfxF)+escHtml(_tf2(vmin))+'×'+escHtml(_tf2(vmax))+escHtml(sfxF)+'</em>';
                    } else if (isRng && (vmin||vmax)) {
                        chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(_tf2(vmin))+'~'+escHtml(_tf2(vmax))+'</em>';
                    } else if (hasTolF) {
                        if (lval !== '') {
                            var tolStr = '';
                            if (tolU !== '') tolStr += (parseFloat(tolU) >= 0 ? '+' : '') + escHtml(_tf2(tolU));
                            if (tolL !== '') tolStr += (parseFloat(tolL) >= 0 ? '+' : '') + escHtml(_tf2(tolL));
                            chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(_tf2(lval))+tolStr+'</em>';
                        }
                    } else if (lval) {
                        chip += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(lval)+'</em>';
                    }
                    if (!isCalcF && subNames) {
                        subNames.split('~').forEach(function(subSeg) {
                            var sp = subSeg.split('§'); // [0]sub_name [1]ival [2]vmin [3]vmax [4]is_range [5]has_tolerance [6]tol_upper [7]tol_lower [8]is_dimension [9]is_qty_dim [10]prefix_char [11]suffix_char [12]qty [13]is_imperial_dim [14]is_enum [15]hide_name [16]is_countersink [17]has_draw_lathe_depth [18]draw_dim [19]lathe_dim [20]is_triple_dim [21]is_qty_triple_dim
                            var snameRaw = _stripLabelHint(sp[0]||'');
                            var sIsEnumSp        = (sp[14]==='1');
                            var sHideNameSp      = (sp[15]==='1');
                            var sIsCountersinkSp = (sp[16]==='1');
                            var sHasDlDepthSp    = (sp[17]==='1');
                            var sDrawDimSp       = sp[18]||'';
                            var sLatheDimSp      = sp[19]||'';
                            var sIsTripleDimSp   = (sp[20]==='1');
                            var sIsQtyTripleDimSp = (sp[21]==='1');
                            if (!snameRaw && !sIsEnumSp) return;
                            var sname = sHideNameSp ? '' : snameRaw;
                            var sIsRng         = (sp[4]==='1');
                            var sHasTol        = (sp[5]==='1');
                            var sIsDimSp       = (sp[8]==='1');
                            var sIsQtyDimSp    = (sp[9]==='1');
                            var sPfxSp         = sp[10]||'';
                            var sSfxSp         = sp[11]||'';
                            var sQtySp         = sp[12]||'';
                            var sIsImperialDimSp = (sp[13]==='1');
                            var siv = sp[1]||'', svn = sp[2]||'', svx = sp[3]||'';
                            var sivRaw = siv;
                            var stU = sp[6]||'', stL = sp[7]||'';
                            siv = _tf2(siv); svn = _tf2(svn); svx = _tf2(svx);
                            var sDisp;
                            if (sIsTripleDimSp && (svn||svx)) {
                                var ssm = svn ? _tf2(svn) : '';
                                var slg = svx ? _tf2(svx) : '';
                                var sdp3 = sDrawDimSp ? _tf2(sDrawDimSp) : '';
                                sDisp = (ssm?sPfxSp+ssm:'')+(slg?'x'+sPfxSp+slg:'')+(sdp3?'x'+sdp3+sSfxSp:'');
                            } else if (sIsQtyTripleDimSp && (svn||svx||sDrawDimSp)) {
                                var q3a = svn ? _tf2(svn) : '';
                                var q3b = svx ? _tf2(svx) : '';
                                var q3c = sDrawDimSp ? _tf2(sDrawDimSp) : '';
                                var q3n = (sQtySp && parseFloat(sQtySp) > 1) ? _tf2(sQtySp)+'-' : '';
                                sDisp = q3n+(q3a?sPfxSp+q3a:'')+(q3b?'×'+sPfxSp+q3b:'')+(q3c?'×'+q3c+sSfxSp:'');
                            } else if (sHasDlDepthSp && (sDrawDimSp||sLatheDimSp)) {
                                var sdd2 = sDrawDimSp ? _tf2(sDrawDimSp) : '';
                                var sld2 = sLatheDimSp ? _tf2(sLatheDimSp) : '';
                                var sdep2 = svn; // value_min = 深度
                                sDisp = (sdd2?'圖'+sdd2:'')+(sld2?' 車'+sld2+(sdep2?'x'+sdep2+sSfxSp:''):'');
                            } else if (sIsCountersinkSp) {
                                var csPart1sp = (svn||svx) ? (sPfxSp+svn+(svx?'x'+svx+sSfxSp:'')) : '';
                                var csPart2sp = (stU||stL) ? (stU+(stL?'x'+_tf2(stL)+sSfxSp:'')) : '';
                                var csDispSp  = csPart1sp + (csPart2sp ? '+'+csPart2sp : '');
                                if (sQtySp && parseFloat(sQtySp) > 1) csDispSp = _tf2(sQtySp)+'-'+csDispSp;
                                sDisp = csDispSp;
                            } else if (sIsEnumSp) {
                                sDisp = sivRaw;
                            } else if (sIsImperialDimSp && sivRaw) {
                                var siQtyNumSp = (sQtySp && parseFloat(sQtySp) > 1) ? _tf2(sQtySp)+'-' : '';
                                var siUncSp    = stU ? _tf2(stU) : '';
                                var siDepthSp  = svx ? svx : '';
                                var siSpecSp   = sivRaw + (siUncSp ? '-'+siUncSp+'UNC' : '');
                                sDisp = siQtyNumSp + siSpecSp + (siDepthSp ? ' x'+siDepthSp+sSfxSp : '');
                            } else if (sIsQtyDimSp && (svn||svx)) {
                                var sQtyNumSp = (sQtySp && parseFloat(sQtySp) > 1) ? _tf2(sQtySp)+'-' : '';
                                sDisp = sQtyNumSp + sPfxSp + svn + '×' + svx + sSfxSp;
                            } else if (sIsDimSp && (svn||svx)) {
                                sDisp = sPfxSp + svn + '×' + svx + sSfxSp;
                            } else if (sIsRng) {
                                sDisp = (!svn && !svx) ? '' : (svn||'')+'~'+(svx||'');
                            } else if (sHasTol && siv !== '') {
                                var sTolStr = '';
                                if (stU !== '') sTolStr += (parseFloat(stU) >= 0 ? '+' : '') + _tf2(stU);
                                if (stL !== '') sTolStr += (parseFloat(stL) >= 0 ? '+' : '') + _tf2(stL);
                                sDisp = siv + sTolStr;
                            } else {
                                sDisp = sivRaw;
                            }
                            var _dispCombined = sname ? (escHtml(sname)+(sDisp?' '+escHtml(sDisp):'')) : escHtml(sDisp||'');
                            if (!_dispCombined) return;
                            chip += '<em style="font-style:normal;opacity:.8;font-size:10px;"> | '+_dispCombined+'</em>';
                        });
                    }
                    labelsHtml += '<span class="part-label-chip"'+(chipStyle?' style="'+chipStyle+'"':'')+'>'+chip+'</span>';
                });
            }
            html += '<td style="font-size:12px;">'+escHtml(r.Spec_No||'—')+(labelsHtml?'<div style="margin-top:3px;">'+labelsHtml+'</div>':'')+'</td>';
            html += '<td style="white-space:nowrap;">';
            if (r.Revision) html += '<code style="background:#f0f4f8;border-radius:3px;padding:1px 5px;">Rev.'+escHtml(r.Revision)+'</code>';
            else html += '<span style="color:#ccc;">—</span>';
            html += '<br><span style="font-size:11px;color:#aaa;">'+(r.Issue_Date||'—')+'</span>';
            html += '</td>';
            html += '<td style="white-space:nowrap;">'+typeBadge+asmBadge+subBadge+subParentsHtml+pulledHtml+'</td>';
            if (r.client_name) {
                html += '<td style="white-space:nowrap;"><span style="color:var(--info);font-weight:600;">'+escHtml(r.client_name)+'</span><br><small style="color:#aaa;font-size:10px;">'+escHtml(r.Customer_Id||'')+'</small></td>';
            } else {
                html += '<td><span style="color:#ddd;">—</span></td>';
            }
            html += '<td style="font-size:12px;color:#888;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+escHtml(r.Remark)+'">'+(escHtml(r.Remark)||'—')+'</td>';
            if (r.Weight_Kg != null && r.Weight_Kg !== '') {
                var wkg = parseFloat(r.Weight_Kg);
                var wCell;
                if (!isNaN(wkg)) {
                    if (wkg > 0 && wkg < 1) { wCell = String(trimFloat(wkg * 1000))+' <span style="color:#aaa;font-size:10px;">g</span>'; }
                    else { wCell = String(trimFloat(wkg))+' <span style="color:#aaa;font-size:10px;">kg</span>'; }
                } else { wCell = escHtml(String(r.Weight_Kg)); }
                html += '<td style="white-space:nowrap;font-size:12px;">'+wCell+'</td>';
            } else {
                html += '<td style="color:#ddd;">—</td>';
            }
            (function() {
                var cyCount = parseInt(r.ship_cy_count) || 0;
                var cyQty   = parseInt(r.ship_cy_qty)   || 0;
                var pyCount = parseInt(r.ship_py_count) || 0;
                var pyQty   = parseInt(r.ship_py_qty)   || 0;
                var cy = new Date().getFullYear();
                var py = cy - 1;
                if (cyCount === 0 && pyCount === 0) {
                    html += '<td style="color:#ddd;font-size:12px;">—</td>';
                } else {
                    var lines = '';
                    if (cyCount > 0) lines += '<span style="color:#1ABB9C;font-size:10px;font-weight:600;">'+cy+'</span> <span style="font-size:12px;">'+cyCount+'筆</span> <span style="color:#888;font-size:11px;">'+cyQty+'件</span>';
                    if (cyCount > 0 && pyCount > 0) lines += '<br>';
                    if (pyCount > 0) lines += '<span style="color:#aaa;font-size:10px;">'+py+'</span> <span style="font-size:11px;color:#888;">'+pyCount+'筆</span> <span style="color:#bbb;font-size:11px;">'+pyQty+'件</span>';
                    html += '<td style="white-space:nowrap;">'+lines+'</td>';
                }
            })();
            // 附件欄（先佔位，批次非同步填入）
            html += '<td class="part-attach-cell" data-did="'+r.d_id+'" data-part-no="'+escHtml(r.D_Setting_Id)+'" style="min-width:80px;padding:4px 6px;vertical-align:middle;">'
                  + '<i class="fa fa-spinner fa-spin" style="color:#ddd;font-size:10px;"></i>'
                  + '</td>';
            if (CAN_SEE_DESIGN) {
                var pdn = r.design_note;
                if (pdn && pdn.first_text) {
                    var pdnHasMore = pdn.first_text.length > 80 || pdn.count > 1 || pdn.has_images;
                    var pdnExtra = '';
                    if (pdn.has_images) pdnExtra += '<i class="fa fa-picture-o" style="color:#3498db;margin-right:3px;" title="含圖片"></i>';
                    if (pdn.count > 1)  pdnExtra += '<span style="font-size:10px;color:#aaa;">共'+pdn.count+'則</span>';
                    html += '<td style="font-size:11px;color:#555;max-width:160px;cursor:pointer;" onclick="openPartDesignModal('+r.d_id+',\''+escAttr(r.D_Setting_Id)+'\')">';
                    html += '<div style="display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;white-space:pre-wrap;word-break:break-word;">'+escHtml(pdn.first_text)+'</div>';
                    html += '<div style="display:flex;align-items:center;gap:4px;margin-top:2px;">'+pdnExtra+(pdnHasMore?'<span style="color:#3498db;font-size:10px;font-weight:700;">＋</span>':'')+'</div>';
                    html += '</td>';
                } else {
                    html += '<td style="color:#bbb;font-size:11px;">無備註</td>';
                }
            }
            if (CAN_UPDATE||CAN_CREATE||CAN_DELETE_ALL||CAN_DELETE_GEAR||CAN_SEE_DESIGN) {
                html += '<td><div class="row-actions">';
                if (CAN_UPDATE||CAN_DELETE_GEAR) html += '<button class="btn-row btn-edit" onclick="openPartModal('+r.d_id+')" title="'+(CAN_UPDATE?'編輯':'查看/管理齒輪規格')+'"><i class="fa fa-'+(CAN_UPDATE?'pencil':'gear')+'"></i></button>';
                if (CAN_CREATE||CAN_UPDATE) html += '<button class="btn-row" onclick="copyPartModal('+r.d_id+')" title="複製料號" style="color:#27ae60;"><i class="fa fa-copy"></i></button>';
                if (CAN_SEE_DESIGN) html += '<button class="btn-row" onclick="openPartDesignModal('+r.d_id+',\''+escAttr(r.D_Setting_Id)+'\')" title="設計備註" style="color:#c0392b;font-size:11px;font-weight:600;padding:1px 5px;"><i class="fa fa-file-text-o"></i> 設計</button>';
                if (CAN_DELETE_ALL) html += '<button class="btn-row btn-delete" onclick="deletePart('+r.d_id+',\''+escAttr(r.D_Setting_Id)+'\')" title="刪除"><i class="fa fa-trash"></i></button>';
                html += '</div></td>';
            }
            html += '</tr>';
        });
    }
    var pgHtml = paginationHTML(total, pg, pages, 'loadParts');
    document.getElementById('parts-table-wrap').innerHTML = pgHtml + html + '</tbody></table></div>';
    // 批次載入附件資料
    var dIds = rows.map(function(r){ return r.d_id; });
    if (dIds.length) loadPartAttachDataForRows(dIds);
}

// ── Part Labels ───────────────────────────────────────
var _partLabelData  = [];
var _labelDefs      = [];
var _subLabelCache  = {};  // label_id → [{sub_id, sub_name, input_type, is_repeatable, has_draw_lathe}]

function loadPartLabels(typeCode, existingLabels) {
    var sec  = document.getElementById('pf-label-section');
    var wrap = document.getElementById('pf-label-chips');
    if (!sec || !wrap) return;
    _partLabelData = existingLabels || [];
    if (!typeCode) { sec.style.display='none'; return; }
    api({ action:'manage_labels', op:'list', type_code:typeCode }).done(function(r) {
        if (!r.success || !r.data || !r.data.length) { sec.style.display='none'; return; }
        _labelDefs = r.data;
        sec.style.display = '';
        renderPartLabelChips(r.data, _partLabelData);
    }).fail(function(){ sec.style.display='none'; });
}

function renderPartLabelChips(labelDefs, existing) {
    var wrap = document.getElementById('pf-label-chips');
    if (!wrap) return;
    wrap.innerHTML = '';
    var canAdd    = CAN_EDIT_GEAR;      // 業務(CRU)、設計(CRD)、A 可新增標籤
    var canRemove = CAN_REMOVE_LABELS;  // 設計(CRD)、A 可移除標籤

    // Build existing map: label_id → [{map_id, input_value, draw_dim, lathe_dim, value_min, value_max, tol_upper, tol_lower, calc_value, calc_value_min, calc_value_max, sub_labels}]
    var exMap = {};
    (existing||[]).forEach(function(e) {
        var lid = String(e.label_id);
        if (!exMap[lid]) exMap[lid] = [];
        exMap[lid].push({
            map_id:        e.map_id||0,
            input_value:   e.input_value||'',
            draw_dim:      e.draw_dim      != null ? e.draw_dim      : '',
            lathe_dim:     e.lathe_dim     != null ? e.lathe_dim     : '',
            value_min:     e.value_min     != null ? e.value_min     : '',
            value_max:     e.value_max     != null ? e.value_max     : '',
            tol_upper:     e.tol_upper     != null ? e.tol_upper     : '',
            tol_lower:     e.tol_lower     != null ? e.tol_lower     : '',
            calc_value:    e.calc_value    != null ? e.calc_value    : '',
            calc_value_min:e.calc_value_min!= null ? e.calc_value_min: '',
            calc_value_max:e.calc_value_max!= null ? e.calc_value_max: '',
            qty:           e.qty          != null ? e.qty           : '',
            sub_labels:    e.sub_labels || []
        });
    });

    // Auto-apply calc_diff labels: if base + sub are both applied, auto-add the calc_diff chip
    labelDefs.forEach(function(ldef) {
        var isCalc2 = (ldef.is_calc_diff=='1'||ldef.is_calc_diff===1);
        if (!isCalc2) return;
        var lid2    = String(ldef.label_id);
        if (exMap[lid2] && exMap[lid2].length) return; // already applied
        var baseId  = String(ldef.calc_base_label_id||'');
        var subId   = String(ldef.calc_sub_label_id||'');
        if (!baseId || !subId) return;
        if (exMap[baseId] && exMap[baseId].length && exMap[subId] && exMap[subId].length) {
            if (!exMap[lid2]) exMap[lid2] = [];
            exMap[lid2].push({ map_id:0, input_value:'', draw_dim:'', lathe_dim:'', value_min:'', value_max:'', tol_upper:'', tol_lower:'', calc_value:'', calc_value_min:'', calc_value_max:'', qty:'', sub_labels:[] });
        }
    });

    // Helper to render one labelDef into a target container
    var _renderOneLabelChip = function(ldef, targetWrap) {
        var lid      = String(ldef.label_id);
        var exItems  = exMap[lid] || [];
        var isRep    = (ldef.is_repeatable=='1'||ldef.is_repeatable===1);
        var inpType  = ldef.input_type||'none';
        var hasDl    = (ldef.has_draw_lathe=='1'||ldef.has_draw_lathe===1);
        var latheOpt = (ldef.lathe_optional=='1'||ldef.lathe_optional===1);
        var hasTol   = (ldef.has_tolerance=='1'||ldef.has_tolerance===1);
        var isCalc   = (ldef.is_calc_diff=='1'||ldef.is_calc_diff===1);

        exItems.forEach(function(ei) {
            var grp = _makeLabelGrp(ldef, ei, canRemove, function() { syncPartLabelsJson(); });
            targetWrap.appendChild(grp);
        });

        if (canAdd) {
            var addChip = document.createElement('span');
            addChip.className = 'part-label-chip no-input';
            addChip.style.cssText = 'background:#f0faf8;color:#aaa;border-color:#c8e8e0;cursor:pointer;';
            addChip.dataset.labelId  = lid;
            addChip.dataset.applied  = '0';
            if (!isRep && exItems.length) addChip.style.display = 'none';

            var hasDlDepth   = (ldef.has_draw_lathe_depth=='1'||ldef.has_draw_lathe_depth===1);
            var isTripleDimL = (ldef.is_triple_dim=='1'||ldef.is_triple_dim===1);
            var calcBaseName = ldef.calc_base_name||'';
            var calcSubName  = ldef.calc_sub_name||'';
            var isRng    = (ldef.is_range == '1' || ldef.is_range === 1);
            var isDim    = (ldef.is_dimension == '1' || ldef.is_dimension === 1);
            var isQtyDim = (ldef.is_qty_dim == '1' || ldef.is_qty_dim === 1);
            var chipLabel;
            var _dispName = escHtml(ldef.label_name||'');
            if (isCalc || hasDl || hasDlDepth || isTripleDimL || inpType !== 'none' || isRng || hasTol || isDim || isQtyDim) {
                chipLabel = '<i class="fa fa-plus" style="font-size:9px;"></i> '+_dispName;
            } else {
                chipLabel = _dispName;
            }
            addChip.innerHTML = chipLabel;

            addChip.onclick = (function(ldefC, hasDlC, hasDlDepthC, isTripleDimLC, calcBaseNameC, calcSubNameC, inpTypeC, isRepC, isRngC, hasTolC, isCalcC, isDimC, isQtyDimC, latheOptC, lidC, addChipC, canRemoveC, targetWrapC) {
                return function() {
                    var ei = { map_id:0, input_value:'', draw_dim:'', lathe_dim:'', value_min:'', value_max:'', tol_upper:'', tol_lower:'', calc_value:'', calc_value_min:'', calc_value_max:'', qty:'', sub_labels:[] };
                    if (isCalcC) {
                        var baseN = calcBaseNameC || '基準項';
                        var subN  = calcSubNameC  || '減項';
                        var bv = prompt('請輸入「'+ldefC.label_name+'」'+baseN+'（數字）', '');
                        if (bv === null) return; bv = bv.trim();
                        if (!bv || isNaN(parseFloat(bv))) { showToast('請輸入有效數字','error'); return; }
                        var sv = prompt('請輸入「'+ldefC.label_name+'」'+subN+'（數字）', '');
                        if (sv === null) return; sv = sv.trim();
                        if (!sv || isNaN(parseFloat(sv))) { showToast('請輸入有效數字','error'); return; }
                        var tu = prompt('請輸入減項上公差（數字，可省略）', '');
                        if (tu === null) return; tu = tu.trim();
                        if (tu && isNaN(parseFloat(tu))) { showToast('請輸入有效數字','error'); return; }
                        ei.draw_dim = bv; ei.lathe_dim = sv; ei.tol_upper = tu;
                        var _stdUp = (ldefC.tolerance_std_upper !== null && ldefC.tolerance_std_upper !== '' && ldefC.tolerance_std_upper !== undefined) ? parseFloat(ldefC.tolerance_std_upper) : null;
                        var _tuNum = (tu !== '') ? parseFloat(tu) : null;
                        var _subC  = parseFloat(sv);
                        if (_tuNum !== null && _stdUp !== null) { _subC = _subC + (_tuNum - _stdUp); }
                        ei.calc_value = String(trimFloat(parseFloat(bv) - _subC));
                    } else if (isTripleDimLC) {
                        var sm = prompt('請輸入「'+ldefC.label_name+'」小圓直徑（數字）', '');
                        if (sm === null) return; sm = sm.trim();
                        if (!sm || isNaN(parseFloat(sm))) { showToast('請輸入有效數字','error'); return; }
                        var lg = prompt('請輸入「'+ldefC.label_name+'」大圓直徑（數字）', '');
                        if (lg === null) return; lg = lg.trim();
                        if (!lg || isNaN(parseFloat(lg))) { showToast('請輸入有效數字','error'); return; }
                        var dep3 = prompt('請輸入「'+ldefC.label_name+'」深度（數字）', '');
                        if (dep3 === null) return; dep3 = dep3.trim();
                        if (!dep3 || isNaN(parseFloat(dep3))) { showToast('請輸入有效數字','error'); return; }
                        ei.value_min = sm; ei.value_max = lg; ei.draw_dim = dep3;
                    } else if (hasDlDepthC) {
                        var ddd = prompt('請輸入「'+ldefC.label_name+'」圖面尺寸（數字）', '');
                        if (ddd === null) return; ddd = ddd.trim();
                        if (!ddd || isNaN(parseFloat(ddd))) { showToast('請輸入有效數字','error'); return; }
                        var ldd = prompt('請輸入「'+ldefC.label_name+'」車床尺寸（數字）', '');
                        if (ldd === null) return; ldd = ldd.trim();
                        if (!ldd || isNaN(parseFloat(ldd))) { showToast('請輸入有效數字','error'); return; }
                        var depp = prompt('請輸入「'+ldefC.label_name+'」深度（數字，可省略）', '');
                        if (depp === null) return; depp = depp.trim();
                        if (depp && isNaN(parseFloat(depp))) { showToast('請輸入有效數字','error'); return; }
                        ei.draw_dim = ddd; ei.lathe_dim = ldd; ei.value_min = depp;
                    } else if (hasDlC) {
                        var dd = prompt('請輸入「'+ldefC.label_name+'」圖面尺寸（數字）', '');
                        if (dd === null) return;
                        dd = dd.trim();
                        if (!dd || isNaN(parseFloat(dd))) { showToast('請輸入有效數字','error'); return; }
                        var ldHint = latheOptC ? '車床尺寸（數字，可留空）' : '車床尺寸（數字）';
                        var ld = prompt('請輸入「'+ldefC.label_name+'」'+ldHint, '');
                        if (ld === null) return;
                        ld = ld.trim();
                        if (!latheOptC && (!ld || isNaN(parseFloat(ld)))) { showToast('請輸入有效數字','error'); return; }
                        if (latheOptC && ld && isNaN(parseFloat(ld))) { showToast('請輸入有效數字','error'); return; }
                        ei.draw_dim = dd; ei.lathe_dim = ld;
                    } else if (isQtyDimC) {
                        var pq = prompt('請輸入「'+ldefC.label_name+'」數量（可省略，省略=1）', '');
                        if (pq === null) return;
                        pq = pq.trim();
                        if (pq && isNaN(parseFloat(pq))) { showToast('請輸入有效數字','error'); return; }
                        var pqA = prompt('請輸入「'+ldefC.label_name+'」A數值（長/圓）', '');
                        if (pqA === null) return;
                        pqA = pqA.trim();
                        if (!pqA || isNaN(parseFloat(pqA))) { showToast('請輸入有效數字','error'); return; }
                        var pqB = prompt('請輸入「'+ldefC.label_name+'」B數值（寬/深）', '');
                        if (pqB === null) return;
                        pqB = pqB.trim();
                        if (!pqB || isNaN(parseFloat(pqB))) { showToast('請輸入有效數字','error'); return; }
                        ei.qty = pq; ei.value_min = pqA; ei.value_max = pqB;
                    } else if (isDimC) {
                        var va = prompt('請輸入「'+ldefC.label_name+'」A數值（長/圓）', '');
                        if (va === null) return;
                        va = va.trim();
                        if (!va || isNaN(parseFloat(va))) { showToast('請輸入有效數字','error'); return; }
                        var vb = prompt('請輸入「'+ldefC.label_name+'」B數值（寬/深）', '');
                        if (vb === null) return;
                        vb = vb.trim();
                        if (!vb || isNaN(parseFloat(vb))) { showToast('請輸入有效數字','error'); return; }
                        ei.value_min = va; ei.value_max = vb;
                    } else if (isRngC) {
                        var vmin = prompt('請輸入「'+ldefC.label_name+'」最小值（數字）', '');
                        if (vmin === null) return;
                        vmin = vmin.trim();
                        if (vmin && isNaN(parseFloat(vmin))) { showToast('請輸入有效數字','error'); return; }
                        var vmax = prompt('請輸入「'+ldefC.label_name+'」最大值（數字）', '');
                        if (vmax === null) return;
                        vmax = vmax.trim();
                        if (vmax && isNaN(parseFloat(vmax))) { showToast('請輸入有效數字','error'); return; }
                        ei.value_min = vmin; ei.value_max = vmax;
                    } else if (hasTolC) {
                        var v = prompt('請輸入「'+ldefC.label_name+'」數值（數字）', '');
                        if (v === null) return;
                        v = v.trim();
                        if (v && isNaN(parseFloat(v))) { showToast('請輸入數字','error'); return; }
                        var tu = prompt('請輸入「'+ldefC.label_name+'」上公差（數字，可為負數，例：+0.05）', '');
                        if (tu === null) return;
                        tu = tu.trim();
                        if (tu && isNaN(parseFloat(tu))) { showToast('請輸入有效數字','error'); return; }
                        var tl = prompt('請輸入「'+ldefC.label_name+'」下公差（數字，可為負數，例：-0.02）', '');
                        if (tl === null) return;
                        tl = tl.trim();
                        if (tl && isNaN(parseFloat(tl))) { showToast('請輸入有效數字','error'); return; }
                        ei.input_value = v; ei.tol_upper = tu; ei.tol_lower = tl;
                    } else if (inpTypeC !== 'none') {
                        var v2 = prompt('請輸入「'+ldefC.label_name+'」的值'+(inpTypeC==='number'?'（數字）':'（文字）'),'');
                        if (v2 === null) return;
                        v2 = v2.trim();
                        if (inpTypeC==='number' && v2 && isNaN(parseFloat(v2))) { showToast('請輸入數字','error'); return; }
                        ei.input_value = v2;
                    }
                    var grp = _makeLabelGrp(ldefC, ei, canRemoveC, function(){ syncPartLabelsJson(); });
                    targetWrapC.insertBefore(grp, addChipC);
                    if (!isRepC) addChipC.style.display='none';
                    // Load sub-labels if needed
                    _ensureSubLabelCache(lidC, function(subs) {
                        if (subs && subs.length) _renderSubLabelSection(grp, ldefC, [], subs, true, canRemoveC, function(){ syncPartLabelsJson(); });
                    });
                    syncPartLabelsJson();
                };
            })(ldef, hasDl, hasDlDepth, isTripleDimL, calcBaseName, calcSubName, inpType, isRep, isRng, hasTol, isCalc, isDim, isQtyDim, latheOpt, lid, addChip, canRemove, targetWrap);

            targetWrap.appendChild(addChip);

            // If existing items already apply but sub-labels haven't been rendered: load subs
            if (exItems.length) {
                (function(lidC, exItemsC, ldefC, canRemoveC, targetWrapC) {
                    _ensureSubLabelCache(lidC, function(subs) {
                        if (!subs || !subs.length) return;
                        var grpEls = targetWrapC.querySelectorAll('.label-inst-grp[data-label-id="'+lidC+'"]');
                        exItemsC.forEach(function(ei, idx) {
                            if (grpEls[idx]) _renderSubLabelSection(grpEls[idx], ldefC, ei.sub_labels||[], subs, canRemoveC, canRemoveC, function(){ syncPartLabelsJson(); });
                        });
                    });
                })(lid, exItems, ldef, canRemove, targetWrap);
            }
        }
    };

    // Render normal (non-hidden) labels first, then hidden labels below a separator
    var normalDefs = labelDefs.filter(function(ldef) {
        return !(ldef.is_hidden_frontend=='1'||ldef.is_hidden_frontend===1);
    });
    var hiddenDefs = labelDefs.filter(function(ldef) {
        return (ldef.is_hidden_frontend=='1'||ldef.is_hidden_frontend===1);
    });

    normalDefs.forEach(function(ldef) { _renderOneLabelChip(ldef, wrap); });

    if (hiddenDefs.length) {
        var hidSep = document.createElement('div');
        hidSep.style.cssText = 'width:100%;display:flex;align-items:center;gap:6px;margin:6px 0 4px;';
        hidSep.innerHTML = '<hr style="flex:1;margin:0;border:none;border-top:1px dashed #ccc;"><span style="font-size:11px;color:#999;white-space:nowrap;">不顯示於前端</span><hr style="flex:1;margin:0;border:none;border-top:1px dashed #ccc;">';
        wrap.appendChild(hidSep);
        hiddenDefs.forEach(function(ldef) { _renderOneLabelChip(ldef, wrap); });
    }

    syncPartLabelsJson();
}

function _makeLabelGrp(ldef, ei, canEdit, onChange) {
    var hasDl        = (ldef.has_draw_lathe=='1'||ldef.has_draw_lathe===1);
    var hasDlDepth   = (ldef.has_draw_lathe_depth=='1'||ldef.has_draw_lathe_depth===1);
    var isTripleDimM = (ldef.is_triple_dim=='1'||ldef.is_triple_dim===1);
    var isRng    = (ldef.is_range=='1'||ldef.is_range===1);
    var hasTol   = (ldef.has_tolerance=='1'||ldef.has_tolerance===1);
    var isCalc   = (ldef.is_calc_diff=='1'||ldef.is_calc_diff===1);
    var isDim    = (ldef.is_dimension=='1'||ldef.is_dimension===1);
    var isQtyDim = (ldef.is_qty_dim=='1'||ldef.is_qty_dim===1);
    var pfxChar  = ldef.prefix_char || '';
    var sfxChar  = ldef.suffix_char || '';
    var grp = document.createElement('div');
    grp.className = 'label-inst-grp';
    grp.dataset.labelId  = String(ldef.label_id);
    grp.dataset.applied  = '1';
    grp.style.cssText    = 'display:inline-block;vertical-align:top;margin:1px 4px 1px 0;';

    // Build chip label
    var _tf2 = function(v){ if(v===''||v==null) return ''; var n=parseFloat(v); return !isNaN(n)?String(trimFloat(n)):String(v); };
    var labelText = escHtml(ldef.label_name||'');
    if (isCalc) {
        var cv = (ei.calc_value != null && ei.calc_value !== '') ? _tf2(ei.calc_value) : '';
        var cvmin = (ei.calc_value_min != null && ei.calc_value_min !== '') ? _tf2(ei.calc_value_min) : '';
        var cvmax = (ei.calc_value_max != null && ei.calc_value_max !== '') ? _tf2(ei.calc_value_max) : '';
        if (cvmin !== '' && cvmax !== '') {
            labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(cvmin)+'~'+escHtml(cvmax)+'</em>';
        } else if (cv !== '') {
            labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(cv)+'</em>';
        } else {
            labelText += '<em style="font-style:normal;opacity:.6;"> 待計算</em>';
        }
    } else if (isTripleDimM) {
        var sm = _tf2(ei.value_min);
        var lg = _tf2(ei.value_max);
        var dp = _tf2(ei.draw_dim);
        if (sm !== '' || lg !== '') labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(sm?escHtml(pfxChar)+escHtml(sm):'')+(lg?'x'+escHtml(pfxChar)+escHtml(lg):'')+(dp?'x'+escHtml(dp)+escHtml(sfxChar):'')+'</em>';
    } else if (hasDlDepth) {
        var dd = _tf2(ei.draw_dim);
        var ld = _tf2(ei.lathe_dim);
        var dep = _tf2(ei.value_min);
        if (dd !== '' || ld !== '') labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(dd?'圖'+escHtml(dd):'')+(ld?' 車'+escHtml(ld)+(dep?'x'+escHtml(dep)+escHtml(sfxChar):''):'')+'</em>';
    } else if (hasDl) {
        var dd = _tf2(ei.draw_dim);
        var ld = _tf2(ei.lathe_dim);
        if (dd !== '') labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+dd+(ld!==''?' 車'+ld:'')+'</em>';
    } else if (isQtyDim) {
        var qQty = (ei.qty != null && ei.qty !== '') ? _tf2(ei.qty) : '';
        var qA   = _tf2(ei.value_min);
        var qB   = _tf2(ei.value_max);
        if (qA !== '' || qB !== '') {
            var qAB = escHtml(pfxChar)+escHtml(qA)+'×'+escHtml(qB)+escHtml(sfxChar);
            var qNum = (qQty !== '' && parseFloat(qQty) > 1) ? escHtml(qQty)+'-' : '';
            labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+qNum+qAB+'</em>';
        }
    } else if (isDim) {
        var va = _tf2(ei.value_min);
        var vb = _tf2(ei.value_max);
        if (va !== '' || vb !== '') labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(pfxChar)+escHtml(va)+'×'+escHtml(vb)+escHtml(sfxChar)+'</em>';
    } else if (isRng) {
        var vmin = _tf2(ei.value_min);
        var vmax = _tf2(ei.value_max);
        if (vmin !== '' || vmax !== '') labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(vmin)+'~'+escHtml(vmax)+'</em>';
    } else if (hasTol) {
        var tv = _tf2(ei.input_value);
        if (tv !== '') {
            var tu = (ei.tol_upper != null && ei.tol_upper !== '') ? _tf2(ei.tol_upper) : '';
            var tl = (ei.tol_lower != null && ei.tol_lower !== '') ? _tf2(ei.tol_lower) : '';
            var tolStr = '';
            if (tu !== '') tolStr += (parseFloat(tu) >= 0 ? '+' : '') + escHtml(tu);
            if (tl !== '') tolStr += (parseFloat(tl) >= 0 ? '+' : '') + escHtml(tl);
            labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(tv)+tolStr+'</em>';
        }
    } else if (ei.input_value) {
        labelText += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(_tf2(ei.input_value))+'</em>';
    }

    var chip = document.createElement('span');
    chip.className = 'part-label-chip selected';
    if (isCalc) chip.style.cssText = 'background:#f3e5f5;border-color:#ce93d8;color:#6a1b9a;';
    chip.dataset.labelId    = String(ldef.label_id);
    chip.dataset.inputValue = ei.input_value||'';
    chip.dataset.drawDim    = (ei.draw_dim != null ? String(ei.draw_dim) : '');
    chip.dataset.latheDim   = (ei.lathe_dim != null ? String(ei.lathe_dim) : '');
    chip.dataset.valueMin   = (ei.value_min != null ? String(ei.value_min) : '');
    chip.dataset.valueMax   = (ei.value_max != null ? String(ei.value_max) : '');
    chip.dataset.tolUpper   = (ei.tol_upper != null ? String(ei.tol_upper) : '');
    chip.dataset.tolLower   = (ei.tol_lower != null ? String(ei.tol_lower) : '');
    chip.dataset.qty        = (ei.qty != null ? String(ei.qty) : '');
    chip.innerHTML = labelText;

    if (canEdit) {
        var rm = document.createElement('span');
        rm.style.cssText = 'margin-left:4px;cursor:pointer;color:#ccc;font-size:11px;';
        rm.textContent = '×';
        rm.onclick = function(e) {
            e.stopPropagation();
            var lid2 = String(ldef.label_id);
            grp.remove();
            // Re-show the add-button for this label so user can re-add it
            var wrap2 = document.getElementById('pf-label-chips');
            if (wrap2) {
                var addBtn = wrap2.querySelector('.part-label-chip[data-label-id="'+lid2+'"][data-applied="0"]');
                if (addBtn) addBtn.style.display = '';
            }
            if (onChange) onChange();
        };
        chip.appendChild(rm);
    }
    grp.appendChild(chip);
    return grp;
}

function _ensureSubLabelCache(labelId, callback) {
    var lid = String(labelId);
    if (_subLabelCache[lid] !== undefined) { callback(_subLabelCache[lid]); return; }
    api({ action:'manage_labels', op:'list_subs', label_id:lid }).done(function(r) {
        _subLabelCache[lid] = (r.success && r.data) ? r.data : [];
        callback(_subLabelCache[lid]);
    }).fail(function(){ _subLabelCache[lid]=[]; callback([]); });
}

function _renderSubLabelSection(grpEl, parentLdef, existingSubs, subDefs, canAdd, canRemove, onChange) {
    var canEdit = canAdd; // legacy alias for add-button checks below
    var existing = grpEl.querySelector('.sub-label-row');
    if (existing) existing.remove();
    if (!subDefs || !subDefs.length) return;

    var row = document.createElement('div');
    row.className = 'sub-label-row';
    row.style.cssText = 'display:block;margin-top:3px;padding:4px 6px;background:#f5fffe;border:1px solid #d0ede8;border-radius:6px;font-size:11px;';

    var exSubMap = {};
    (existingSubs||[]).forEach(function(s) {
        var sid = String(s.sub_id);
        if (!exSubMap[sid]) exSubMap[sid] = [];
        exSubMap[sid].push({
            input_value: s.input_value||'',
            draw_dim:    s.draw_dim   != null ? s.draw_dim   : '',
            lathe_dim:   s.lathe_dim  != null ? s.lathe_dim  : '',
            value_min:   s.value_min  != null ? s.value_min  : '',
            value_max:   s.value_max  != null ? s.value_max  : '',
            tol_upper:   s.tol_upper  != null ? s.tol_upper  : '',
            tol_lower:   s.tol_lower  != null ? s.tol_lower  : '',
            qty:         s.qty        != null ? s.qty        : ''
        });
    });

    var _subPromptInputs = function(sdefC, sHasDlC, inpTypeC, sIsRngC, sHasTolC, sIsDimC, sIsQtyDimC, sIsImperialDimC, sIsCountersinkC, sHasDlDepthC, sIsTripleDimC, parentLdefC) {
        var es = { input_value:'', draw_dim:'', lathe_dim:'', value_min:'', value_max:'', tol_upper:'', tol_lower:'', qty:'' };
        var sIsQtyTripleDimC = (sdefC.is_qty_triple_dim=='1'||sdefC.is_qty_triple_dim===1);
        if (sIsQtyTripleDimC) {
            var qtq = prompt('請輸入「'+sdefC.sub_name+'」數量（可省略，省略=1）','');
            if (qtq===null) return null; qtq=qtq.trim();
            if (qtq && isNaN(parseFloat(qtq))){ showToast('請輸入有效數字','error'); return null; }
            var qtA = prompt('請輸入「'+sdefC.sub_name+'」第1維 圓直徑/長（數字）','');
            if (qtA===null) return null; qtA=qtA.trim();
            if (!qtA||isNaN(parseFloat(qtA))){ showToast('請輸入有效數字','error'); return null; }
            var qtB = prompt('請輸入「'+sdefC.sub_name+'」第2維 鍵長/寬（數字）','');
            if (qtB===null) return null; qtB=qtB.trim();
            if (!qtB||isNaN(parseFloat(qtB))){ showToast('請輸入有效數字','error'); return null; }
            var qtC = prompt('請輸入「'+sdefC.sub_name+'」第3維 鍵高/高（數字）','');
            if (qtC===null) return null; qtC=qtC.trim();
            if (!qtC||isNaN(parseFloat(qtC))){ showToast('請輸入有效數字','error'); return null; }
            es.qty=qtq; es.value_min=qtA; es.value_max=qtB; es.draw_dim=qtC;
        } else if (sHasDlDepthC) {
            var ddd = prompt('請輸入「'+sdefC.sub_name+'」圖面尺寸（數字）','');
            if (ddd===null) return null; ddd=ddd.trim();
            if (!ddd||isNaN(parseFloat(ddd))){ showToast('請輸入有效數字','error'); return null; }
            var ldd = prompt('請輸入「'+sdefC.sub_name+'」車床尺寸（數字）','');
            if (ldd===null) return null; ldd=ldd.trim();
            if (!ldd||isNaN(parseFloat(ldd))){ showToast('請輸入有效數字','error'); return null; }
            var depp = prompt('請輸入「'+sdefC.sub_name+'」深度（數字，可省略）','');
            if (depp===null) return null; depp=depp.trim();
            if (depp && isNaN(parseFloat(depp))){ showToast('請輸入有效數字','error'); return null; }
            es.draw_dim=ddd; es.lathe_dim=ldd; es.value_min=depp;
        } else if (sIsTripleDimC) {
            var pssm = prompt('請輸入「'+sdefC.sub_name+'」小圓直徑（數字）','');
            if (pssm===null) return null; pssm=pssm.trim();
            if (!pssm||isNaN(parseFloat(pssm))){ showToast('請輸入有效數字','error'); return null; }
            var pslg = prompt('請輸入「'+sdefC.sub_name+'」大圓直徑（數字）','');
            if (pslg===null) return null; pslg=pslg.trim();
            if (!pslg||isNaN(parseFloat(pslg))){ showToast('請輸入有效數字','error'); return null; }
            var psdp = prompt('請輸入「'+sdefC.sub_name+'」深度（數字）','');
            if (psdp===null) return null; psdp=psdp.trim();
            if (!psdp||isNaN(parseFloat(psdp))){ showToast('請輸入有效數字','error'); return null; }
            es.value_min=pssm; es.value_max=pslg; es.draw_dim=psdp;
        } else if (sHasDlC) {
            var dd = prompt('請輸入「'+parentLdefC.label_name+' > '+sdefC.sub_name+'」圖面尺寸（數字）','');
            if (dd===null) return null; dd=dd.trim();
            if (!dd||isNaN(parseFloat(dd))){ showToast('請輸入有效數字','error'); return null; }
            var ld = prompt('請輸入「'+parentLdefC.label_name+' > '+sdefC.sub_name+'」車床尺寸（數字）','');
            if (ld===null) return null; ld=ld.trim();
            if (!ld||isNaN(parseFloat(ld))){ showToast('請輸入有效數字','error'); return null; }
            es.draw_dim=dd; es.lathe_dim=ld;
        } else if (sIsRngC) {
            var vmin = prompt('請輸入「'+sdefC.sub_name+'」最小值（數字）','');
            if (vmin===null) return null; vmin=vmin.trim();
            if (vmin&&isNaN(parseFloat(vmin))){ showToast('請輸入有效數字','error'); return null; }
            var vmax = prompt('請輸入「'+sdefC.sub_name+'」最大值（數字）','');
            if (vmax===null) return null; vmax=vmax.trim();
            if (vmax&&isNaN(parseFloat(vmax))){ showToast('請輸入有效數字','error'); return null; }
            es.value_min=vmin; es.value_max=vmax;
        } else if (sHasTolC) {
            var sv = prompt('請輸入「'+sdefC.sub_name+'」數值（數字）','');
            if (sv===null) return null; sv=sv.trim();
            if (sv&&isNaN(parseFloat(sv))){ showToast('請輸入數字','error'); return null; }
            var stu = prompt('請輸入「'+sdefC.sub_name+'」上公差（例：+0.05）','');
            if (stu===null) return null; stu=stu.trim();
            if (stu&&isNaN(parseFloat(stu))){ showToast('請輸入有效數字','error'); return null; }
            var stl = prompt('請輸入「'+sdefC.sub_name+'」下公差（例：-0.02）','');
            if (stl===null) return null; stl=stl.trim();
            if (stl&&isNaN(parseFloat(stl))){ showToast('請輸入有效數字','error'); return null; }
            es.input_value=sv; es.tol_upper=stu; es.tol_lower=stl;
        } else if (sIsQtyDimC) {
            var sqty = prompt('請輸入「'+sdefC.sub_name+'」數量（可省略，省略=1）','');
            if (sqty===null) return null; sqty=sqty.trim();
            if (sqty && isNaN(parseFloat(sqty))){ showToast('請輸入有效數字','error'); return null; }
            var sqA = prompt('請輸入「'+sdefC.sub_name+'」A數值（長/圓）','');
            if (sqA===null) return null; sqA=sqA.trim();
            if (!sqA||isNaN(parseFloat(sqA))){ showToast('請輸入有效數字','error'); return null; }
            var sqB = prompt('請輸入「'+sdefC.sub_name+'」B數值（寬/深）','');
            if (sqB===null) return null; sqB=sqB.trim();
            if (!sqB||isNaN(parseFloat(sqB))){ showToast('請輸入有效數字','error'); return null; }
            es.qty=sqty; es.value_min=sqA; es.value_max=sqB;
        } else if (sIsImperialDimC) {
            var siqty = prompt('請輸入「'+sdefC.sub_name+'」數量（可省略，省略=1）','');
            if (siqty===null) return null; siqty=siqty.trim();
            if (siqty && isNaN(parseFloat(siqty))){ showToast('請輸入有效數字','error'); return null; }
            var siFrac = prompt('請輸入「'+sdefC.sub_name+'」英制圓（例：3/8）','');
            if (siFrac===null) return null; siFrac=siFrac.trim();
            if (!siFrac){ showToast('請輸入英制圓規格','error'); return null; }
            var siFracMatch = siFrac.match(/^(\d+)\/(\d+)$/);
            if (!siFracMatch){ showToast('請輸入分數格式（例：3/8）','error'); return null; }
            var siFracDec = parseFloat(siFracMatch[1]) / parseFloat(siFracMatch[2]);
            var siUnc = prompt('請輸入「'+sdefC.sub_name+'」UNC牙數（可省略）','');
            if (siUnc===null) return null; siUnc=siUnc.trim();
            if (siUnc && isNaN(parseFloat(siUnc))){ showToast('請輸入有效數字','error'); return null; }
            var siDepth = prompt('請輸入「'+sdefC.sub_name+'」深度（數字）','');
            if (siDepth===null) return null; siDepth=siDepth.trim();
            if (!siDepth||isNaN(parseFloat(siDepth))){ showToast('請輸入有效數字','error'); return null; }
            es.qty=siqty; es.input_value=siFrac; es.tol_upper=siUnc; es.value_min=String(siFracDec); es.value_max=siDepth;
        } else if (sIsCountersinkC) {
            var csqty = prompt('請輸入「'+sdefC.sub_name+'」數量（可省略）','');
            if (csqty===null) return null; csqty=csqty.trim();
            if (csqty && isNaN(parseFloat(csqty))){ showToast('請輸入有效數字','error'); return null; }
            var csHead = prompt('請輸入沉頭孔徑（數字，可省略）','');
            if (csHead===null) return null; csHead=csHead.trim();
            if (csHead && isNaN(parseFloat(csHead))){ showToast('請輸入有效數字','error'); return null; }
            var csHd = prompt('請輸入沉頭深度（數字，可省略）','');
            if (csHd===null) return null; csHd=csHd.trim();
            if (csHd && isNaN(parseFloat(csHd))){ showToast('請輸入有效數字','error'); return null; }
            var csSmall = prompt('請輸入小孔孔徑（數字，可省略）','');
            if (csSmall===null) return null; csSmall=csSmall.trim();
            if (csSmall && isNaN(parseFloat(csSmall))){ showToast('請輸入有效數字','error'); return null; }
            var csSd = prompt('請輸入小孔深度（數字，可省略）','');
            if (csSd===null) return null; csSd=csSd.trim();
            if (csSd && isNaN(parseFloat(csSd))){ showToast('請輸入有效數字','error'); return null; }
            es.qty=csqty; es.value_min=csHead; es.value_max=csHd; es.tol_upper=csSmall; es.tol_lower=csSd;
        } else if (sIsDimC) {
            var sdA = prompt('請輸入「'+sdefC.sub_name+'」A數值（長/圓）','');
            if (sdA===null) return null; sdA=sdA.trim();
            if (!sdA||isNaN(parseFloat(sdA))){ showToast('請輸入有效數字','error'); return null; }
            var sdB = prompt('請輸入「'+sdefC.sub_name+'」B數值（寬/深）','');
            if (sdB===null) return null; sdB=sdB.trim();
            if (!sdB||isNaN(parseFloat(sdB))){ showToast('請輸入有效數字','error'); return null; }
            es.value_min=sdA; es.value_max=sdB;
        } else if (inpTypeC!=='none') {
            var v = prompt('請輸入「'+sdefC.sub_name+'」的值'+(inpTypeC==='number'?'（數字）':'（文字）'),'');
            if (v===null) return null; v=v.trim();
            if (inpTypeC==='number'&&v&&isNaN(parseFloat(v))){ showToast('請輸入數字','error'); return null; }
            es.input_value=v;
        }
        return es;
    };

    subDefs.forEach(function(sdef) {
        var sid       = String(sdef.sub_id);
        var isRep     = (sdef.is_repeatable=='1'||sdef.is_repeatable===1);
        var inpType   = sdef.input_type||'none';
        var sHasDl          = (sdef.has_draw_lathe=='1'||sdef.has_draw_lathe===1);
        var sHasTol         = (sdef.has_tolerance=='1'||sdef.has_tolerance===1);
        var sIsDim          = (sdef.is_dimension=='1'||sdef.is_dimension===1);
        var sIsQtyDim       = (sdef.is_qty_dim=='1'||sdef.is_qty_dim===1);
        var sIsImperialDim  = (sdef.is_imperial_dim=='1'||sdef.is_imperial_dim===1);
        var sIsCountersink  = (sdef.is_countersink=='1'||sdef.is_countersink===1);
        var sHasDlDepthSub  = (sdef.has_draw_lathe_depth=='1'||sdef.has_draw_lathe_depth===1);
        var sIsTripleDimSub = (sdef.is_triple_dim=='1'||sdef.is_triple_dim===1);
        var sIsEnum         = (sdef.is_enum=='1'||sdef.is_enum===1);
        var sEnumOpts       = sdef.options || [];
        var exSubs    = exSubMap[sid] || [];
        var sIsRng = (sdef.is_range=='1'||sdef.is_range===1);

        if (sIsEnum) {
            // Enum sub-label: own row — [category label] [selected chips] [option chips]
            var enumRow = document.createElement('div');
            enumRow.className = 'sub-enum-category-row';
            enumRow.style.cssText = 'display:flex;flex-wrap:wrap;align-items:center;gap:3px;margin-top:3px;';
            var catLabel = document.createElement('span');
            catLabel.style.cssText = 'font-size:10px;color:#555;font-weight:600;white-space:nowrap;padding:1px 5px;background:#e8f4e8;border:1px solid #c3dfc3;border-radius:3px;';
            catLabel.textContent = (sdef.sub_name||'').replace(/\[.*?\]/g,'').trim();
            enumRow.appendChild(catLabel);
            exSubs.forEach(function(es) {
                var chip = _makeSubChip(sdef, es, canRemove, function() { if(onChange)onChange(); });
                enumRow.appendChild(chip);
            });
            if (sEnumOpts.length && canEdit) {
                var selVals = exSubs.map(function(e){ return e.input_value; });
                var optWrap = document.createElement('span');
                optWrap.className = 'sub-enum-opts';
                optWrap.style.cssText = 'display:inline-flex;flex-wrap:wrap;gap:3px;vertical-align:middle;';
                sEnumOpts.forEach(function(opt) {
                    var alreadySel = !isRep && selVals.indexOf(opt.option_value) >= 0;
                    var optChip = document.createElement('span');
                    optChip.className = 'part-label-chip no-input sub-enum-opt-chip';
                    optChip.dataset.optVal = opt.option_value;
                    optChip.dataset.subId  = sid;
                    optChip.style.cssText = 'background:#f0f2f5;color:#555;border-color:#ddd;cursor:pointer;font-size:10px;' + (alreadySel?'display:none;':'');
                    optChip.textContent = opt.option_value;
                    optChip.onclick = (function(sdefC, optChipC, optWrapC, enumRowC, isRepC, canRemoveC) {
                        return function() {
                            if (!isRepC) {
                                enumRowC.querySelectorAll('.part-label-chip.selected[data-sub-id="'+sdefC.sub_id+'"]').forEach(function(c){ c.remove(); });
                                optWrapC.querySelectorAll('.sub-enum-opt-chip').forEach(function(c){ c.style.display=''; });
                            }
                            var es2 = { input_value:optChipC.dataset.optVal, draw_dim:'', lathe_dim:'', value_min:'', value_max:'', tol_upper:'', tol_lower:'', qty:'' };
                            var chip2 = _makeSubChip(sdefC, es2, canRemoveC, function(){ if(onChange)onChange(); });
                            enumRowC.insertBefore(chip2, optWrapC);
                            optChipC.style.display = 'none';
                            if (onChange) onChange();
                        };
                    })(sdef, optChip, optWrap, enumRow, isRep, canRemove);
                    optWrap.appendChild(optChip);
                });
                enumRow.appendChild(optWrap);
            } else if (canEdit) {
                var noOptSpan = document.createElement('span');
                noOptSpan.style.cssText = 'font-size:10px;color:#aaa;';
                noOptSpan.textContent = '（尚無選項）';
                enumRow.appendChild(noOptSpan);
            }
            row.appendChild(enumRow);
        } else {
            // Non-enum: existing flat behavior
            exSubs.forEach(function(es) {
                var chip = _makeSubChip(sdef, es, canRemove, function() { if(onChange)onChange(); });
                row.appendChild(chip);
            });
            if (canEdit && (isRep || !exSubs.length)) {
                var addBtn = document.createElement('span');
                addBtn.className = 'part-label-chip no-input';
                addBtn.dataset.subId = sid;   // 標記所屬小類，刪除已設定小類時才能精準找回「此」小類的＋按鈕（修正會抓到前一個小類的 bug）
                addBtn.style.cssText = 'background:#e8f8f5;color:#aaa;border-color:#b2e0d8;cursor:pointer;font-size:10px;';
                if (!isRep && exSubs.length) addBtn.style.display = 'none';
                var _sDispName = escHtml(sdef.sub_name||'');
                addBtn.innerHTML = (sHasDl || sIsCountersink || sIsImperialDim || sHasDlDepthSub || sIsTripleDimSub || inpType!=='none' || sIsRng || sHasTol || sIsDim || sIsQtyDim) ? '<i class="fa fa-plus" style="font-size:8px;"></i> '+_sDispName : _sDispName;
                addBtn.onclick = (function(sdefC, sHasDlC, inpTypeC, isRepC, sIsRngC, sHasTolC, sIsDimC, sIsQtyDimC, sIsImperialDimC, sIsCountersinkC, sHasDlDepthCC, sIsTripleDimCC, addBtnC, canRemoveC) {
                    return function() {
                        var es = _subPromptInputs(sdefC, sHasDlC, inpTypeC, sIsRngC, sHasTolC, sIsDimC, sIsQtyDimC, sIsImperialDimC, sIsCountersinkC, sHasDlDepthCC, sIsTripleDimCC, parentLdef);
                        if (es === null) return;
                        var chip2 = _makeSubChip(sdefC, es, canRemoveC, function(){ if(onChange)onChange(); });
                        addBtnC.parentNode.insertBefore(chip2, addBtnC);
                        if (!isRepC) addBtnC.style.display='none';
                        if (onChange) onChange();
                    };
                })(sdef, sHasDl, inpType, isRep, sIsRng, sHasTol, sIsDim, sIsQtyDim, sIsImperialDim, sIsCountersink, sHasDlDepthSub, sIsTripleDimSub, addBtn, canRemove);
                row.appendChild(addBtn);
            } else if (canEdit) {
                // Non-repeatable with existing: hidden add-button for re-add after delete
                var addBtnH = document.createElement('span');
                addBtnH.className = 'part-label-chip no-input';
                addBtnH.dataset.subId = sid;   // 同上：標記所屬小類，確保刪除後找回正確的＋按鈕
                addBtnH.style.cssText = 'background:#e8f8f5;color:#aaa;border-color:#b2e0d8;cursor:pointer;font-size:10px;display:none;';
                addBtnH.innerHTML = (sHasDl || sIsCountersink || sIsImperialDim || sHasDlDepthSub || inpType!=='none' || sIsRng || sHasTol || sIsDim || sIsQtyDim) ? '<i class="fa fa-plus" style="font-size:8px;"></i> '+escHtml(sdef.sub_name||'') : escHtml(sdef.sub_name||'');
                addBtnH.onclick = (function(sdefC, sHasDlC, inpTypeC, sIsRngC, sHasTolC, sIsDimC, sIsQtyDimC, sIsImperialDimC, sIsCountersinkC, sHasDlDepthCC, sIsTripleDimCC, addBtnHC, canRemoveC) {
                    return function() {
                        var es = _subPromptInputs(sdefC, sHasDlC, inpTypeC, sIsRngC, sHasTolC, sIsDimC, sIsQtyDimC, sIsImperialDimC, sIsCountersinkC, sHasDlDepthCC, sIsTripleDimCC, parentLdef);
                        if (es === null) return;
                        var chip3 = _makeSubChip(sdefC, es, canRemoveC, function(){ if(onChange)onChange(); });
                        addBtnHC.parentNode.insertBefore(chip3, addBtnHC);
                        addBtnHC.style.display='none';
                        if (onChange) onChange();
                    };
                })(sdef, sHasDl, inpType, sIsRng, sHasTol, sIsDim, sIsQtyDim, sIsImperialDim, sIsCountersink, sHasDlDepthSub, sIsTripleDimSub, addBtnH, canRemove);
                row.appendChild(addBtnH);
            }
        }
    });
    grpEl.appendChild(row);
}

function _makeSubChip(sdef, es, canEdit, onChange) {
    var sHasDl      = (sdef.has_draw_lathe=='1'||sdef.has_draw_lathe===1);
    var sIsRng      = (sdef.is_range=='1'||sdef.is_range===1);
    var sHasTol     = (sdef.has_tolerance=='1'||sdef.has_tolerance===1);
    var sIsDim      = (sdef.is_dimension=='1'||sdef.is_dimension===1);
    var sIsQtyDim   = (sdef.is_qty_dim=='1'||sdef.is_qty_dim===1);
    var sIsImperialDim   = (sdef.is_imperial_dim=='1'||sdef.is_imperial_dim===1);
    var sIsCountersink   = (sdef.is_countersink=='1'||sdef.is_countersink===1);
    var sHasDlDepthSub   = (sdef.has_draw_lathe_depth=='1'||sdef.has_draw_lathe_depth===1);
    var sIsTripleDimSub  = (sdef.is_triple_dim=='1'||sdef.is_triple_dim===1);
    var sIsQtyTripleDimSub = (sdef.is_qty_triple_dim=='1'||sdef.is_qty_triple_dim===1);
    var sIsEnum          = (sdef.is_enum=='1'||sdef.is_enum===1);
    var sPfx     = sdef.prefix_char || '';
    var sSfx     = sdef.suffix_char || '';
    var chip = document.createElement('span');
    chip.className = 'part-label-chip selected';
    chip.dataset.subId      = String(sdef.sub_id);
    chip.dataset.inputValue = es.input_value||'';
    chip.dataset.drawDim    = es.draw_dim   != null ? String(es.draw_dim)   : '';
    chip.dataset.latheDim   = es.lathe_dim  != null ? String(es.lathe_dim)  : '';
    chip.dataset.valueMin   = es.value_min  != null ? String(es.value_min)  : '';
    chip.dataset.valueMax   = es.value_max  != null ? String(es.value_max)  : '';
    chip.dataset.tolUpper   = es.tol_upper  != null ? String(es.tol_upper)  : '';
    chip.dataset.tolLower   = es.tol_lower  != null ? String(es.tol_lower)  : '';
    chip.dataset.qty        = es.qty        != null ? String(es.qty)        : '';
    chip.style.cssText      += 'font-size:10px;background:#b2e0d8;border-color:#85cec4;color:#1c7068;';
    var _tf3 = function(v){ if(v===''||v==null) return ''; var n=parseFloat(v); return !isNaN(n)?String(trimFloat(n)):String(v); };
    var txt = escHtml(sdef.sub_name||'');
    if (sIsTripleDimSub && (es.value_min||es.value_max)) {
        var ssm = (es.value_min != null && es.value_min !== '') ? _tf3(es.value_min) : '';
        var slg = (es.value_max != null && es.value_max !== '') ? _tf3(es.value_max) : '';
        var sdp = (es.draw_dim  != null && es.draw_dim  !== '') ? _tf3(es.draw_dim)  : '';
        txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(ssm?escHtml(sPfx)+escHtml(ssm):'')+(slg?'x'+escHtml(sPfx)+escHtml(slg):'')+(sdp?'x'+escHtml(sdp)+escHtml(sSfx):'')+'</em>';
    } else if (sHasDlDepthSub && (es.draw_dim||es.lathe_dim)) {
        var sdd = _tf3(es.draw_dim);
        var sld = _tf3(es.lathe_dim);
        var sdp = (es.value_min != null && es.value_min !== '') ? _tf3(es.value_min) : '';
        txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(sdd?'圖'+escHtml(sdd):'')+(sld?' 車'+escHtml(sld)+(sdp?'x'+escHtml(sdp)+escHtml(sSfx):''):'')+'</em>';
    } else if (sHasDl && (es.draw_dim||es.lathe_dim)) {
        var dd = _tf3(es.draw_dim);
        var ld = _tf3(es.lathe_dim);
        txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+(dd!==''?dd:'')+(ld!==''?' 車'+ld:'')+'</em>';
    } else if (sIsCountersink) {
        var csQtyV  = (es.qty != null && es.qty !== '') ? _tf3(es.qty) : '';
        var csHeadV = (es.value_min != null && es.value_min !== '') ? _tf3(es.value_min) : '';
        var csHdV   = (es.value_max != null && es.value_max !== '') ? _tf3(es.value_max) : '';
        var csSV    = (es.tol_upper != null && es.tol_upper !== '') ? _tf3(es.tol_upper) : '';
        var csSdV   = (es.tol_lower != null && es.tol_lower !== '') ? _tf3(es.tol_lower) : '';
        var csPart1 = (csHeadV || csHdV) ? (escHtml(sPfx)+escHtml(csHeadV)+(csHdV?'x'+escHtml(csHdV)+escHtml(sSfx):'')) : '';
        var csPart2 = (csSV || csSdV) ? (escHtml(csSV)+(csSdV?'x'+escHtml(csSdV)+escHtml(sSfx):'')) : '';
        var csDisp  = csPart1 + (csPart2 ? '+'+csPart2 : '');
        if (csQtyV && parseFloat(csQtyV) > 1) csDisp = escHtml(csQtyV)+'-'+csDisp;
        if (csDisp) txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+csDisp+'</em>';
    } else if (sIsEnum) {
        if (es.input_value) {
            txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(es.input_value)+'</em>';
        }
    } else if (sIsImperialDim) {
        var siQtyV  = (es.qty != null && es.qty !== '') ? _tf3(es.qty) : '';
        var siFracV = es.input_value || '';
        var siUncV  = (es.tol_upper != null && es.tol_upper !== '') ? _tf3(es.tol_upper) : '';
        var siDepthV= (es.value_max != null && es.value_max !== '') ? _tf3(es.value_max) : '';
        if (siFracV) {
            var siQtyNum = (siQtyV !== '' && parseFloat(siQtyV) > 1) ? escHtml(siQtyV)+'-' : '';
            var siSpec   = escHtml(siFracV) + (siUncV ? '-'+escHtml(siUncV)+'UNC' : '');
            var siDepthStr = siDepthV ? ' x'+escHtml(siDepthV)+escHtml(sSfx) : '';
            txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+siQtyNum+siSpec+siDepthStr+'</em>';
        }
    } else if (sIsQtyDim) {
        var qtyV = (es.qty != null && es.qty !== '') ? _tf3(es.qty) : '';
        var qtyA = _tf3(es.value_min);
        var qtyB = _tf3(es.value_max);
        if (qtyA !== '' || qtyB !== '') {
            var qtyAB = escHtml(sPfx) + escHtml(qtyA) + '×' + escHtml(qtyB) + escHtml(sSfx);
            var qtyNum = (qtyV !== '' && parseFloat(qtyV) > 1) ? escHtml(qtyV)+'-' : '';
            txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+qtyNum+qtyAB+'</em>';
        }
    } else if (sIsQtyTripleDimSub) {
        var qt3V = (es.qty != null && es.qty !== '') ? _tf3(es.qty) : '';
        var qt3A = (es.value_min != null && es.value_min !== '') ? _tf3(es.value_min) : '';
        var qt3B = (es.value_max != null && es.value_max !== '') ? _tf3(es.value_max) : '';
        var qt3C = (es.draw_dim  != null && es.draw_dim  !== '') ? _tf3(es.draw_dim)  : '';
        if (qt3A !== '' || qt3B !== '' || qt3C !== '') {
            var qt3Body = (qt3A?escHtml(sPfx)+escHtml(qt3A):'')+(qt3B?'×'+escHtml(sPfx)+escHtml(qt3B):'')+(qt3C?'×'+escHtml(qt3C)+escHtml(sSfx):'');
            var qt3Num = (qt3V !== '' && parseFloat(qt3V) > 1) ? escHtml(qt3V)+'-' : '';
            txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+qt3Num+qt3Body+'</em>';
        }
    } else if (sIsDim) {
        var va = _tf3(es.value_min);
        var vb = _tf3(es.value_max);
        if (va !== '' || vb !== '') {
            txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(sPfx)+escHtml(va)+'×'+escHtml(vb)+escHtml(sSfx)+'</em>';
        }
    } else if (sIsRng && (es.value_min!=null&&es.value_min!=='' || es.value_max!=null&&es.value_max!=='')) {
        var vmin = _tf3(es.value_min);
        var vmax = _tf3(es.value_max);
        txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(vmin)+'~'+escHtml(vmax)+'</em>';
    } else if (sHasTol && es.input_value !== '') {
        var stv = _tf3(es.input_value);
        var stu = (es.tol_upper != null && es.tol_upper !== '') ? _tf3(es.tol_upper) : '';
        var stl = (es.tol_lower != null && es.tol_lower !== '') ? _tf3(es.tol_lower) : '';
        var tolStr = '';
        if (stu !== '') tolStr += (parseFloat(stu) >= 0 ? '+' : '') + escHtml(stu);
        if (stl !== '') tolStr += (parseFloat(stl) >= 0 ? '+' : '') + escHtml(stl);
        txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(stv)+tolStr+'</em>';
    } else if (es.input_value) {
        var _ivDisp = (sdef.input_type === 'text') ? es.input_value : _tf3(es.input_value);
        txt += '<em style="font-style:normal;font-weight:normal;opacity:.85;"> '+escHtml(_ivDisp)+'</em>';
    }
    chip.innerHTML = txt;
    if (canEdit) {
        var rm = document.createElement('span');
        rm.style.cssText = 'margin-left:3px;cursor:pointer;color:#aaa;font-size:10px;';
        rm.textContent   = '×';
        rm.onclick = function(e) {
            e.stopPropagation();
            var row2 = chip.parentNode;
            if (row2) {
                // Re-show matching enum option chip
                var optChipEl = row2.querySelector('.sub-enum-opt-chip[data-opt-val="'+chip.dataset.inputValue+'"]');
                if (optChipEl) {
                    optChipEl.style.display = '';
                } else {
                    var addBtnEl = row2.querySelector('.part-label-chip.no-input[data-sub-id="'+chip.dataset.subId+'"]') ||
                                   Array.from(row2.querySelectorAll('.part-label-chip.no-input')).find(function(b){ return b.style.display==='none'; });
                    if (addBtnEl) addBtnEl.style.display = '';
                }
            }
            chip.remove();
            if (onChange) onChange();
        };
        chip.appendChild(rm);
    }
    return chip;
}

function syncPartLabelsJson() {
    var wrap   = document.getElementById('pf-label-chips');
    var hidden = document.getElementById('pf-labels-json');
    if (!wrap || !hidden) return;
    var result = [];
    wrap.querySelectorAll('.label-inst-grp[data-applied="1"]').forEach(function(grp) {
        var mainChip = grp.querySelector('.part-label-chip.selected');
        if (!mainChip) return;
        var item = {
            label_id:    mainChip.dataset.labelId   ||grp.dataset.labelId,
            input_value: mainChip.dataset.inputValue||'',
            draw_dim:    mainChip.dataset.drawDim   ||'',
            lathe_dim:   mainChip.dataset.latheDim  ||'',
            value_min:   mainChip.dataset.valueMin  ||'',
            value_max:   mainChip.dataset.valueMax  ||'',
            tol_upper:   mainChip.dataset.tolUpper  ||'',
            tol_lower:   mainChip.dataset.tolLower  ||'',
            qty:         mainChip.dataset.qty       ||'',
            sub_labels:  []
        };
        var subRow = grp.querySelector('.sub-label-row');
        if (subRow) {
            subRow.querySelectorAll('.part-label-chip.selected[data-sub-id]').forEach(function(sc) {
                item.sub_labels.push({
                    sub_id:      sc.dataset.subId,
                    input_value: sc.dataset.inputValue||'',
                    draw_dim:    sc.dataset.drawDim   ||'',
                    lathe_dim:   sc.dataset.latheDim  ||'',
                    value_min:   sc.dataset.valueMin  ||'',
                    value_max:   sc.dataset.valueMax  ||'',
                    tol_upper:   sc.dataset.tolUpper  ||'',
                    tol_lower:   sc.dataset.tolLower  ||'',
                    qty:         sc.dataset.qty       ||''
                });
            });
        }
        result.push(item);
    });
    hidden.value = JSON.stringify(result);
}

// ── Gear data ─────────────────────────────────────────
var gearRows = [];
var bomRows  = [];
var gearTypeOptions = [];  // loaded from DB via reloadGearTypeOptions()
var _gearQualityRef = [];  // loaded from DB via loadGearQualityRef()

function gearTypeHasHelix(typeVal) {
    if (!typeVal && typeVal !== 0) return false;
    var sv = String(typeVal);  // convert int to string for comparison
    var found = gearTypeOptions.filter(function(o){ return o.value===sv; });
    if (found.length) return found[0].hasHelix;
    return typeVal.indexOf('斜')>=0 || typeVal.indexOf('螺旋')>=0 || typeVal.indexOf('蝸')>=0;
}

// ── Type change handler ───────────────────────────────
function onTypeChange(val, opts) {
    opts = opts || {};
    var gs = document.getElementById('gear-section');
    if (val === 'G') {
        $(gs).slideDown(200);
        if (gearRows.length === 0) addGearRow({});
        else renderGearRows();
    } else {
        $(gs).slideUp(200);
        gearRows = [];
    }
    // 依工件種類字典設定，顯示/隱藏 廠商 / 專用料號 / 專用機台 / 價格 欄位
    applyPartExtraFieldVisibility(val);
    // Load sub-types for selected type (not G)。
    // 編輯載入時(openPartModal)會帶入既有小類值，故傳 skipSubType 避免在這裡先以 0 重置而與後續請求競態。
    if (!opts.skipSubType) loadPartSubTypes(val, 0);
    // Load labels for this type (reset existing selections)
    if (!opts.skipLabels) loadPartLabels(val, []);
}

// 工件小類請求序號：避免編輯時多次非同步請求互相覆蓋（競態），只允許最後一次請求套用結果
var _partSubReqSeq = 0;
function loadPartSubTypes(typeCode, selectedId) {
    var grp   = document.getElementById('pf-subtype-group');
    var wrap  = document.getElementById('pf-sub-chips');
    var hidden= document.getElementById('pf-workpiece_sub_type_id');
    if (!grp || !wrap) return;
    var myReq = ++_partSubReqSeq;   // 記錄本次請求序號
    if (!typeCode || typeCode === 'G') {
        grp.style.display='none'; if (hidden) hidden.value=''; return;
    }
    api({ action:'manage_workpiece_sub_types', op:'list', type_code:typeCode }).done(function(r) {
        if (myReq !== _partSubReqSeq) return;   // 已有更新的請求發出，丟棄這個過時結果，避免把選取清掉
        if (!r.success || !r.data || !r.data.length) { grp.style.display='none'; return; }
        wrap.innerHTML = '';
        var selIds = selectedId ? [parseInt(selectedId)] : [];
        r.data.forEach(function(s) {
            var sel = selIds.indexOf(parseInt(s.sub_type_id)) >= 0;
            var chip = document.createElement('span');
            chip.style.cssText = 'display:inline-block;padding:2px 10px;border-radius:10px;font-size:12px;font-weight:600;cursor:pointer;user-select:none;transition:all .15s;'
                + (sel ? 'background:#5856d6;color:#fff;border:1.5px solid #5856d6;' : 'background:#eef2ff;color:#5856d6;border:1.5px solid #5856d655;');
            chip.dataset.id = s.sub_type_id;
            chip.textContent = s.sub_type_name;
            chip.onclick = function() {
                var isActive = this.style.background.includes('5856d6') && this.style.color === 'rgb(255, 255, 255)';
                if (isActive) {
                    this.style.cssText = 'display:inline-block;padding:2px 10px;border-radius:10px;font-size:12px;font-weight:600;cursor:pointer;user-select:none;transition:all .15s;background:#eef2ff;color:#5856d6;border:1.5px solid #5856d655;';
                } else {
                    this.style.cssText = 'display:inline-block;padding:2px 10px;border-radius:10px;font-size:12px;font-weight:600;cursor:pointer;user-select:none;transition:all .15s;background:#5856d6;color:#fff;border:1.5px solid #5856d6;';
                }
                syncPartSubChips();
            };
            wrap.appendChild(chip);
        });
        syncPartSubChips();
        grp.style.display = '';
    });
}

function syncPartSubChips() {
    var wrap   = document.getElementById('pf-sub-chips');
    var hidden = document.getElementById('pf-workpiece_sub_type_id');
    if (!wrap || !hidden) return;
    var sel = [];
    wrap.querySelectorAll('span').forEach(function(c) {
        if (c.style.color === 'rgb(255, 255, 255)') sel.push(c.dataset.id);
    });
    // Store first selected (or all as CSV for multi-select support)
    hidden.value = sel.join(',');
}

// ════════════════════════════════════════════════════════════════════════
// 料號表單：廠商 / 專用料號 / 專用機台 多選自動完成元件（廠商可含每廠商單價）
//   vendor  → d_setting_vendor_map (maker_id_no, price)
//   partno  → d_setting_dedicated_part_map (ref_d_id，來源 d_setting)
//   machine → d_setting_machine_map (machine_id)
// 顯示與否由工件種類字典(partTypeMeta)的 show_vendor/show_part_no/show_machine/show_price 決定
// ════════════════════════════════════════════════════════════════════════
var _pfAcCfg = {
    vendor:  { endpoint:'search_makers_ac',   hidden:'pf-vendor-map',        input:'pf-ac-vendor-input',  dropdown:'pf-ac-vendor-dropdown',  list:'pf-ac-vendor-list' },
    partno:  { endpoint:'search_dsetting_ac', hidden:'pf-dedicated-part-map',input:'pf-ac-partno-input',  dropdown:'pf-ac-partno-dropdown',  list:'pf-ac-partno-list' },
    machine: { endpoint:'search_machines_ac', hidden:'pf-machine-map',       input:'pf-ac-machine-input', dropdown:'pf-ac-machine-dropdown', list:'pf-ac-machine-list' }
};
var _pfAcData    = { vendor:[], partno:[], machine:[] }; // 已選清單
var _pfAcResults = { vendor:[], partno:[], machine:[] }; // 下拉暫存結果
var _pfAcTimer   = { vendor:null, partno:null, machine:null };
var _pfAcShowPrice = false; // 廠商是否顯示價格欄（依工件種類 show_price）

function _pfEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function _pfAcNormalize(field, row) {
    if (field==='vendor') {
        var nm = row.maker_short || row.maker_full || '';
        return { id:String(row.maker_id_no), label:(nm? nm+' ' : '')+'['+row.maker_id_no+']', price:'' };
    }
    if (field==='partno') {
        return { id:String(row.d_id), label:row.part_id + (row.spec_no? ' / '+row.spec_no : '') };
    }
    return { id:String(row.machine_id), label:row.machine_name + (row.machine_type? ' ('+row.machine_type+')':'') };
}

function pfAcSearch(field, kw) {
    var cfg = _pfAcCfg[field]; if (!cfg) return;
    kw = (kw||'').trim();
    var dd = document.getElementById(cfg.dropdown);
    if (_pfAcTimer[field]) clearTimeout(_pfAcTimer[field]);
    if (kw==='') { if(dd){dd.style.display='none';dd.innerHTML='';} return; }
    _pfAcTimer[field] = setTimeout(function(){
        var req = { action:cfg.endpoint, kw:kw };
        if (field==='partno') req.exclude_d_id = parseInt(document.getElementById('pf-d_id').value||0);
        api(req).done(function(r){
            if (!r.success) return;
            _pfAcResults[field] = (r.data||[]).map(function(row){ return _pfAcNormalize(field, row); });
            _pfAcRenderDropdown(field);
        });
    }, 200);
}

function _pfAcRenderDropdown(field) {
    var cfg=_pfAcCfg[field]; var dd=document.getElementById(cfg.dropdown); if(!dd) return;
    var chosen={}; _pfAcData[field].forEach(function(x){ chosen[x.id]=true; });
    var rows=_pfAcResults[field];
    if (!rows.length) { dd.innerHTML='<div style="padding:6px 10px;color:#999;font-size:12px;">查無資料</div>'; dd.style.display='block'; return; }
    var html='';
    rows.forEach(function(it, idx){
        var dup=chosen[it.id];
        html += '<div class="pf-ac-opt" style="padding:5px 10px;font-size:12px;cursor:'+(dup?'default':'pointer')+';'+(dup?'color:#bbb;':'')+'" '
             + (dup?'':'onmousedown="event.preventDefault();pfAcPick(\''+field+'\','+idx+')"')+'>'
             + _pfEsc(it.label) + (dup?' <span style="font-size:10px;">(已選)</span>':'') + '</div>';
    });
    dd.innerHTML=html; dd.style.display='block';
}

function pfAcPick(field, idx) {
    var it=_pfAcResults[field][idx]; if(!it) return;
    if (_pfAcData[field].some(function(x){return x.id===it.id;})) return;
    _pfAcData[field].push(field==='vendor'?{id:it.id,label:it.label,price:''}:{id:it.id,label:it.label});
    var cfg=_pfAcCfg[field];
    var inp=document.getElementById(cfg.input); if(inp){ inp.value=''; inp.focus(); }
    var dd=document.getElementById(cfg.dropdown); if(dd){ dd.style.display='none'; dd.innerHTML=''; }
    _pfAcResults[field]=[];
    _pfAcRenderList(field); _pfAcSync(field);
}

function pfAcRemove(field, idx) {
    _pfAcData[field].splice(idx,1);
    _pfAcRenderList(field); _pfAcSync(field);
}

function pfAcPriceChange(idx, val) {
    if (_pfAcData.vendor[idx]) { _pfAcData.vendor[idx].price = val; _pfAcSync('vendor'); }
}

function _pfAcRenderList(field) {
    var cfg=_pfAcCfg[field]; var box=document.getElementById(cfg.list); if(!box) return;
    var arr=_pfAcData[field];
    if (!arr.length) { box.innerHTML=''; return; }
    if (field==='vendor') {
        var html='';
        arr.forEach(function(it, idx){
            html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">';
            html += '<span style="flex:1;background:#eef2ff;color:#3949ab;border:1px solid #c5cae9;border-radius:4px;padding:2px 8px;font-size:12px;">'+_pfEsc(it.label)+'</span>';
            if (_pfAcShowPrice) {
                html += '<input type="number" class="form-control input-sm no-spin-input" style="width:100px;" step="any" min="0" placeholder="單價" value="'+_pfEsc(it.price)+'" oninput="pfAcPriceChange('+idx+',this.value)">';
            }
            html += '<span style="cursor:pointer;color:#e74c3c;font-weight:bold;padding:0 4px;" onclick="pfAcRemove(\'vendor\','+idx+')" title="移除">×</span>';
            html += '</div>';
        });
        box.innerHTML=html;
    } else {
        var h='';
        arr.forEach(function(it, idx){
            h += '<span style="display:inline-flex;align-items:center;gap:5px;background:#eef2ff;color:#3949ab;border:1px solid #c5cae9;border-radius:10px;padding:2px 8px;font-size:12px;margin:0 4px 4px 0;">'
               + _pfEsc(it.label)
               + '<span style="cursor:pointer;color:#e74c3c;font-weight:bold;" onclick="pfAcRemove(\''+field+'\','+idx+')" title="移除">×</span></span>';
        });
        box.innerHTML=h;
    }
}

function _pfAcSync(field) {
    var cfg=_pfAcCfg[field]; var hid=document.getElementById(cfg.hidden); if(!hid) return;
    var out;
    if (field==='vendor') {
        out = _pfAcData.vendor.map(function(x){ return { maker_id_no:x.id, price:(x.price===''||x.price==null)?null:x.price }; });
    } else if (field==='partno') {
        out = _pfAcData.partno.map(function(x){ return { ref_d_id:parseInt(x.id) }; });
    } else {
        out = _pfAcData.machine.map(function(x){ return { machine_id:parseInt(x.id) }; });
    }
    hid.value = JSON.stringify(out);
}

function pfAcInputKey(e, field) {
    if (e.key==='Enter') {
        e.preventDefault();   // 避免在自動完成輸入框按 Enter 觸發送出或跳欄
        var avail = _pfAcResults[field].filter(function(it){ return !_pfAcData[field].some(function(x){return x.id===it.id;}); });
        if (avail.length===1) { pfAcPick(field, _pfAcResults[field].indexOf(avail[0])); }
    }
}

// 依工件種類字典設定，顯示/隱藏 廠商 / 專用料號 / 專用機台 / 價格 欄位
function applyPartExtraFieldVisibility(typeCode) {
    var meta = partTypeMeta[typeCode] || {show_vendor:false,show_part_no:false,show_machine:false,show_price:false};
    _pfAcShowPrice = !!meta.show_price;
    // 價格依附於廠商（每廠商一價），只要開啟廠商或價格就顯示廠商區塊
    var vendorVisible = meta.show_vendor || meta.show_price;
    var vg=document.getElementById('pf-vendor-group');
    var pg=document.getElementById('pf-partno-group');
    var mg=document.getElementById('pf-machine-group');
    var wrap=document.getElementById('pf-extra-fields');
    if (vg) vg.style.display = vendorVisible ? '' : 'none';
    if (pg) pg.style.display = meta.show_part_no ? '' : 'none';
    if (mg) mg.style.display = meta.show_machine ? '' : 'none';
    if (wrap) wrap.style.display = (vendorVisible||meta.show_part_no||meta.show_machine) ? '' : 'none';
    _pfAcRenderList('vendor'); // 價格欄顯示狀態可能改變，重繪廠商清單
}

// 清空三個欄位（新增料號時呼叫）
function pfAcReset() {
    _pfAcData    = { vendor:[], partno:[], machine:[] };
    _pfAcResults = { vendor:[], partno:[], machine:[] };
    ['vendor','partno','machine'].forEach(function(f){
        var cfg=_pfAcCfg[f];
        var inp=document.getElementById(cfg.input); if(inp) inp.value='';
        var dd=document.getElementById(cfg.dropdown); if(dd){dd.style.display='none';dd.innerHTML='';}
        _pfAcRenderList(f); _pfAcSync(f);
    });
}

// 由 get_part 回傳資料載入既有選取（編輯料號時呼叫）
function pfAcLoadFromPart(d) {
    _pfAcData.vendor  = (d.vendor_map||[]).map(function(v){
        var nm=v.maker_short||v.maker_full||'';
        return { id:String(v.maker_id_no), label:(nm?nm+' ':'')+'['+v.maker_id_no+']', price:(v.price==null?'':String(v.price)) };
    });
    _pfAcData.partno  = (d.dedicated_part_map||[]).map(function(p){
        return { id:String(p.ref_d_id), label:p.part_id + (p.spec_no? ' / '+p.spec_no : '') };
    });
    _pfAcData.machine = (d.machine_map||[]).map(function(m){
        return { id:String(m.machine_id), label:m.machine_name + (m.machine_type? ' ('+m.machine_type+')':'') };
    });
    ['vendor','partno','machine'].forEach(function(f){ _pfAcRenderList(f); _pfAcSync(f); });
}

// 點擊輸入框與下拉以外的地方，關閉所有自動完成下拉
document.addEventListener('mousedown', function(e){
    ['vendor','partno','machine'].forEach(function(f){
        var cfg=_pfAcCfg[f];
        var dd=document.getElementById(cfg.dropdown); var inp=document.getElementById(cfg.input);
        if (!dd||!inp) return;
        if (e.target!==inp && !dd.contains(e.target)) dd.style.display='none';
    });
});

// ── Assembly change handler ───────────────────────────
function onAssemblyChange(checked) {
    var bs = document.getElementById('bom-section');
    if (checked) { $(bs).slideDown(200); renderBomRows(); }
    else         { $(bs).slideUp(200); bomRows = []; renderBomRows(); }
}

// ── Gear rows ─────────────────────────────────────────
function addGearRow(data) {
    data = data || {};
    gearRows.push({
        gear_id:              data.gear_id              || 0,
        Gear_Type:            data.Gear_Type             || '',
        Module:               data.Module                || '',
        Teeth:                data.Teeth                 || '',
        Face_Width:           data.Face_Width            || '',
        Helix_Direction:      data.Helix_Direction       || '',
        Helix_Angle_Str:      data.Helix_Angle_Str       || '',
        Helix_Angle:          data.Helix_Angle           || '',
        Pressure_Angle:       data.Pressure_Angle        || '',
        Profile_Shift_X:      data.Profile_Shift_X       || '',
        Workpiece_Length:     data.Workpiece_Length      || '',
        Spec_No:              data.Spec_No               || '',
        Remark_Gear:          data.Remark_Gear           || '',
        Gear_Quality_Std:     data.gear_quality_std      || '',
        Gear_Quality_Grade:   (data.gear_quality_grade !== null && data.gear_quality_grade !== undefined) ? String(data.gear_quality_grade) : '',
        module_input_type:    data.module_input_type      || 'M',
        module_display:       data.module_display         || '',
        spec_chain_size:      data.spec_chain_size       || '',
        spec_pitch:           data.spec_pitch            || '',
        spec_roller_dia:      data.spec_roller_dia       || '',
        spec_starts:          data.spec_starts           || '',
        spec_pulley_profile:  data.spec_pulley_profile   || '',
        spec_spline_type:        data.spec_spline_type         || '',
        spec_spline_major_dia:   data.spec_spline_major_dia    || '',
        spec_spline_minor_dia:   data.spec_spline_minor_dia    || '',
        spec_spline_width:       data.spec_spline_width        || '',
        spec_spline_std:         data.spec_spline_std          || '',
        spec_spline_nominal_dia: data.spec_spline_nominal_dia  || ''
    });
    renderGearRows();
}

function removeGearRow(idx) {
    gearRows.splice(idx, 1);
    renderGearRows();
}

function renderGearRows() {
    var wrap = document.getElementById('gear-rows-wrap');
    var canDeleteGearRow  = CAN_DELETE_GEAR;
    var dId = parseInt(document.getElementById('pf-d_id').value||'0');
    if (!gearRows.length) {
        wrap.innerHTML = '<div style="color:#aaa;font-size:12px;padding:6px 0;">尚未設定齒輪規格，點擊下方「新增齒型」</div>';
        return;
    }

    var html = '';
    gearRows.forEach(function(g, i) {
        var isExisting = !!(g.gear_id && dId > 0);
        var rowEditable = CAN_EDIT_GEAR && (!isExisting || CAN_MODIFY_EXISTING_GEAR);
        var hasHelix = gearTypeHasHelix(g.Gear_Type);
        var helixDisplay = hasHelix ? '' : 'display:none;';
        var specCat = getGearSpecCategory(g.Gear_Type);
        var isSprocket    = specCat === 'sprocket';
        var isTimingPulley= specCat === 'timing_pulley';
        var isSpline      = specCat === 'spline';
        var isWormGear    = specCat === 'worm_gear';
        var isStandard    = !isSprocket && !isTimingPulley && !isSpline;
        // 決定模數輸入類型和顯示值（有 module_display 才能正確還原 CP/DP）
        var mit = (g.module_display && g.module_display !== '')
            ? (String(g.module_display).match(/^(M|CP|DP)/i) || ['','M'])[1].toUpperCase()
            : 'M';
        var ro = rowEditable ? '' : 'disabled';

        // Build Gear_Type options
        var typeOpts = '<option value="">— 選擇 —</option>';
        gearTypeOptions.forEach(function(opt) {
            typeOpts += '<option value="'+opt.value+'"'+(String(g.Gear_Type)===opt.value?' selected':'')+'>'+opt.label+'</option>';
        });

        // DMS angle fields
        var dmsAngle = parseDMS(g.Helix_Angle_Str || String(g.Helix_Angle||''));

        html += '<div class="gear-row" id="gear-row-'+i+'"'+(isExisting&&!CAN_MODIFY_EXISTING_GEAR?' style="opacity:.72;background:#f8f8f8;"':'')+' >';
        html += '<div class="gear-row-title"><i class="fa fa-cog"></i> 齒型 ' + (i+1) + (isExisting&&!CAN_MODIFY_EXISTING_GEAR?' <span style="font-size:10px;color:#aaa;font-weight:normal;">(唯讀)</span>':'') + '</div>';
        if (rowEditable && !isExisting) {
            // new row: client-side remove
            html += '<button type="button" class="btn-remove-row" onclick="removeGearRow('+i+')" title="移除"><i class="fa fa-times"></i></button>';
        } else if (CAN_MODIFY_EXISTING_GEAR && isExisting) {
            // existing row with full permission: show remove (client-side) or delete (server-side)
            if (canDeleteGearRow && g.gear_id) {
                html += '<button type="button" class="btn-remove-row" onclick="deleteGearRow('+g.gear_id+','+dId+')" title="立即刪除此齒型" style="color:#e74c3c;"><i class="fa fa-trash"></i></button>';
            } else {
                html += '<button type="button" class="btn-remove-row" onclick="removeGearRow('+i+')" title="移除"><i class="fa fa-times"></i></button>';
            }
        }
        // CRU + existing row: no button at all

        html += '<div class="row">';
        // Gear Type (always visible)
        html += '<div class="col-md-3"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">齒輪類型</label>';
        html += '<select class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Gear_Type" onchange="onGearTypeChange('+i+',this.value)" '+ro+'>'+typeOpts+'</select>';
        html += '</div></div>';

        // ── 標準齒輪欄位（模數 M/CP/DP + 齒數 + 齒寬 + 壓力角）──────────────────
        html += '<div class="gear-standard-fields-'+i+'"'+(isStandard?'':' style="display:none;"')+'>';
        // Module with M/CP/DP toggle
        html += '<div class="col-md-3" data-field-col="Module" data-gear-row="'+i+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;" id="lbl-module-'+i+'">模數</label>';
        html += '<div style="display:flex;gap:3px;">';
        html += '<select class="form-control input-sm" id="module-type-'+i+'" style="width:60px;flex-shrink:0;" onchange="onModuleTypeChange('+i+',this.value)" '+ro+'>';
        html += '<option value="M"'+(mit==='M'?' selected':'')+'>M</option>';
        html += '<option value="CP"'+(mit==='CP'?' selected':'')+'>CP</option>';
        html += '<option value="DP"'+(mit==='DP'?' selected':'')+'>DP</option>';
        html += '</select>';
        var modDisplay;
        if (g.module_display && g.module_display !== '') {
            var _md2 = String(g.module_display).match(/^(?:M|CP|DP)(.+)$/i);
            modDisplay = _md2 ? _md2[1] : g.module_display;
        } else {
            modDisplay = g.Module ? String(g.Module).replace(/^[Mm]/,'') : '';
        }
        html += '<input type="text" class="form-control input-sm gear-field" id="module-val-'+i+'" data-idx="'+i+'" data-field="Module" value="'+escHtml(modDisplay)+'" placeholder="2.5" onblur="formatModuleNew('+i+')" '+ro+'>';
        html += '</div>';
        html += '<div id="module-m-display-'+i+'" style="font-size:10px;color:#888;margin-top:2px;display:none;"></div>';
        html += '</div></div>';
        // Teeth
        html += '<div class="col-md-2" data-field-col="Teeth" data-gear-row="'+i+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;" id="lbl-teeth-'+i+'">齒數</label>';
        html += '<input type="number" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Teeth" value="'+escHtml(String(g.Teeth||''))+'" placeholder="32" '+ro+'>';
        html += '</div></div>';
        // Face Width
        html += '<div class="col-md-2" data-field-col="Face_Width" data-gear-row="'+i+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">齒寬 (mm)</label>';
        html += '<input type="text" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Face_Width" value="'+escHtml(trimFloat(g.Face_Width))+'" placeholder="20" '+ro+'>';
        html += '</div></div>';
        // Pressure Angle
        html += '<div class="col-md-2" data-field-col="Pressure_Angle" data-gear-row="'+i+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">壓力角 (PA)</label>';
        html += '<input type="text" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Pressure_Angle" value="'+escHtml(trimFloat(g.Pressure_Angle))+'" placeholder="20°" '+ro+'>';
        html += '</div></div>';
        html += '</div>'; // end gear-standard-fields

        // ── 鏈輪欄位 ─────────────────────────────────────────────────────────────
        html += '<div class="gear-sprocket-fields-'+i+'"'+(isSprocket?'':' style="display:none;"')+'>';
        html += '<div class="col-md-3"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">鏈條規格</label>';
        html += '<select class="form-control input-sm gear-field" data-idx="'+i+'" data-field="spec_chain_size" onchange="onChainSizeChange('+i+',this.value)" '+ro+'>';
        html += '<option value="">— 選擇或自訂 —</option><option value="custom">自訂節距/滾子徑</option>';
        html += '</select>';
        html += '</div></div>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">節距 P (mm)</label>';
        html += '<input type="text" class="form-control input-sm gear-field" id="chain-pitch-'+i+'" data-idx="'+i+'" data-field="spec_pitch" value="'+escHtml(trimFloat(g.spec_pitch))+'" placeholder="12.7" oninput="calcSprocket('+i+')" '+ro+'>';
        html += '</div></div>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">滾子外徑 Dr (mm)</label>';
        html += '<input type="text" class="form-control input-sm gear-field" id="chain-roller-'+i+'" data-idx="'+i+'" data-field="spec_roller_dia" value="'+escHtml(trimFloat(g.spec_roller_dia))+'" placeholder="7.95" oninput="calcSprocket('+i+')" '+ro+'>';
        html += '</div></div>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;" data-field-col="Teeth">齒數</label>';
        html += '<input type="number" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Teeth" value="'+escHtml(String(g.Teeth||''))+'" placeholder="20" oninput="calcSprocket('+i+')" '+ro+'>';
        html += '</div></div>';
        html += '<div class="col-md-3"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">自動計算</label>';
        html += '<div id="sprocket-calc-'+i+'" style="font-size:11px;color:#1a5276;background:#f0f4fb;padding:4px 8px;border-radius:4px;line-height:1.6;min-height:28px;"></div>';
        html += '</div></div>';
        html += '</div>'; // end sprocket fields

        // ── 皮帶輪欄位 ───────────────────────────────────────────────────────────
        html += '<div class="gear-pulley-fields-'+i+'"'+(isTimingPulley?'':' style="display:none;"')+'>';
        html += '<div class="col-md-3"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">皮帶齒型</label>';
        html += '<select class="form-control input-sm gear-field" data-idx="'+i+'" data-field="spec_pulley_profile" onchange="onBeltProfileChange('+i+',this.value)" '+ro+'>';
        html += '<option value="">— 選擇 —</option>';
        html += '</select></div></div>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">齒數</label>';
        html += '<input type="number" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Teeth" value="'+escHtml(String(g.Teeth||''))+'" placeholder="32" oninput="calcTimingPulley('+i+')" '+ro+'>';
        html += '</div></div>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">節距 (mm)</label>';
        html += '<input type="text" class="form-control input-sm" id="pulley-pitch-'+i+'" value="'+escHtml(trimFloat(g.spec_pitch))+'" placeholder="自動" readonly style="background:#f5f5f5;">';
        html += '</div></div>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">自動計算 (PD/OD)</label>';
        html += '<div id="pulley-calc-'+i+'" style="font-size:11px;color:#1a5276;background:#f0f4fb;padding:4px 8px;border-radius:4px;line-height:1.6;min-height:28px;"></div>';
        html += '</div></div>';
        html += '</div>'; // end pulley fields

        // ── 蝸桿牙口數（worm_gear 才顯示，在 Row 1 末端）──────────────────────
        html += '<div class="gear-worm-starts-'+i+'"'+(isWormGear?'':' style="display:none;"')+'>';
        html += '<div class="col-md-2"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">牙口數（條）</label>';
        html += '<input type="number" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="spec_starts" value="'+escHtml(String(g.spec_starts||''))+'" placeholder="1" min="1" '+ro+'>';
        html += '</div></div>';
        html += '</div>'; // end worm-starts

        // ── 花鍵齒形（在 Row 1 末，僅花鍵顯示）─────────────────────────────────
        html += '<div class="gear-spline-type-'+i+'"'+(isSpline?'':' style="display:none;"')+'>';
        html += '<div class="col-md-3"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">花鍵標準</label>';
