        html += '<input type="text" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="spec_spline_major_dia" value="'+escHtml(trimFloat(g.spec_spline_major_dia))+'" placeholder="26" '+ro+'>';
        html += '</div></div>';
        html += '<div class="col-md-2 spline-rect-'+i+'" style="'+spRectDisplay+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">鍵寬 (mm)</label>';
        html += '<input type="text" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="spec_spline_width" value="'+escHtml(trimFloat(g.spec_spline_width))+'" placeholder="6" '+ro+'>';
        html += '</div></div>';
        html += '</div>'; // end spline-fields

        html += '</div>'; // end row 1

        // Row 2 - helix + extras
        html += '<div class="row">';
        // Helix group (show/hide based on type)
        html += '<div class="col-md-2 helix-group-'+i+'" style="'+helixDisplay+'">';
        html += '<div class="form-group" style="margin-bottom:6px;"><label style="font-size:11px;">旋向</label>';
        html += '<select class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Helix_Direction" '+ro+'>';
        html += '<option value="">—</option>';
        html += '<option value="RH"'+(g.Helix_Direction==='RH'?' selected':'')+'>RH 右旋</option>';
        html += '<option value="LH"'+(g.Helix_Direction==='LH'?' selected':'')+'>LH 左旋</option>';
        html += '</select></div></div>';

        // Helix angle
        html += '<div class="col-md-4 helix-group-'+i+'" style="'+helixDisplay+'">';
        html += '<div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">螺旋角 &nbsp;';
        html += '<label style="font-weight:normal;font-size:10px;cursor:pointer;margin:0;">';
        html += '<input type="radio" name="helix-mode-'+i+'" value="dec" '+(dmsAngle.mode!=='dms'?'checked':'')+' onchange="switchHelixMode('+i+',\'dec\')" style="margin-right:2px;">十進位</label> ';
        html += '<label style="font-weight:normal;font-size:10px;cursor:pointer;margin:0;">';
        html += '<input type="radio" name="helix-mode-'+i+'" value="dms" '+(dmsAngle.mode==='dms'?'checked':'')+' onchange="switchHelixMode('+i+',\'dms\')" style="margin-right:2px;">度分秒</label>';
        html += '</label>';
        // decimal mode
        html += '<div id="helix-dec-'+i+'" style="'+(dmsAngle.mode==='dms'?'display:none;':'')+'">';
        html += '<input type="text" class="form-control input-sm gear-field" id="helix-dec-val-'+i+'" data-idx="'+i+'" data-field="Helix_Angle_Str" value="'+escHtml(dmsAngle.mode!=='dms'?(g.Helix_Angle_Str||trimFloat(g.Helix_Angle)):'')+'" placeholder="15.5" '+ro+'>';
        html += '</div>';
        // DMS mode
        html += '<div id="helix-dms-'+i+'" style="'+(dmsAngle.mode==='dms'?'':'display:none;')+'">';
        html += '<div class="input-group" style="display:flex;gap:3px;">';
        html += '<input type="number" class="form-control input-sm" id="helix-d-'+i+'" placeholder="度" value="'+escHtml(String(dmsAngle.d||''))+'" style="width:50px;" '+ro+'>';
        html += '<input type="number" class="form-control input-sm" id="helix-m-'+i+'" placeholder="分" value="'+escHtml(String(dmsAngle.m||''))+'" style="width:50px;" onchange="syncDMS('+i+')" '+ro+'>';
        html += '<input type="number" class="form-control input-sm" id="helix-s-'+i+'" placeholder="秒" value="'+escHtml(String(dmsAngle.s||''))+'" style="width:50px;" onchange="syncDMS('+i+')" '+ro+'>';
        html += '</div></div>';
        html += '</div></div></div>';

        // Profile Shift X（僅標準齒輪類型顯示）
        html += '<div class="col-md-2 gear-shift-block-'+i+'"'+(isStandard?'':' style="display:none;"')+' data-field-col="Profile_Shift_X" data-gear-row="'+i+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">轉位係數 X</label>';
        html += '<input type="text" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Profile_Shift_X" value="'+escHtml(trimFloat(g.Profile_Shift_X))+'" placeholder="0" '+ro+'>';
        html += '</div></div>';
        // Remark
        html += '<div class="col-md-3" data-field-col="Remark_Gear" data-gear-row="'+i+'"><div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">備註</label>';
        html += '<input type="text" class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Remark_Gear" value="'+escHtml(g.Remark_Gear)+'" placeholder="備用說明" '+ro+'>';
        html += '</div></div>';
        // Gear Quality
        html += '<div class="col-md-3 gear-quality-block-'+i+'"'+(isSprocket?' style="display:none;"':'')+'>';
        html += '<div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;">齒輪等級</label>';
        html += '<div style="display:flex;gap:4px;">';
        html += '<select class="form-control input-sm gear-field" data-idx="'+i+'" data-field="Gear_Quality_Std" style="width:82px;" onchange="onGearQualityStdChange('+i+',this.value)" '+ro+'>';
        html += '<option value="">—</option>';
        ['JIS','ISO','DIN','AGMA'].forEach(function(s){ html += '<option value="'+s+'"'+(g.Gear_Quality_Std===s?' selected':'')+'>'+s+'</option>'; });
        html += '</select>';
        html += '<select class="form-control input-sm gear-field" id="gq-grade-'+i+'" data-idx="'+i+'" data-field="Gear_Quality_Grade" style="width:75px;" '+ro+'>';
        html += _buildGradeOpts(g.Gear_Quality_Std, g.Gear_Quality_Grade);
        html += '</select>';
        html += '</div></div></div>';
        html += '</div>'; // end row2


        html += '</div>'; // end gear-row
    });

    wrap.innerHTML = html;

    // bind live sync
    wrap.querySelectorAll('.gear-field').forEach(function(el) {
        ['change','input'].forEach(function(ev) {
            el.addEventListener(ev, function() {
                var idx = parseInt(this.dataset.idx);
                var field = this.dataset.field;
                if (!isNaN(idx) && gearRows[idx]) gearRows[idx][field] = this.value;
            });
        });
    });

    // 初始化鏈輪/皮帶輪下拉與計算
    gearRows.forEach(function(g, i) {
        // 初始化鏈輪/皮帶輪下拉與計算
        var cat = getGearSpecCategory(g.Gear_Type);
        if (cat === 'sprocket') _initChainSizeSelect(i, g.spec_chain_size);
        if (cat === 'timing_pulley') _initBeltProfileSelect(i, g.spec_pulley_profile);
    });
    _bindGearKeyNav();
}

// ── 齒輪類型切換：顯示/隱藏對應欄位區塊 ──────────────────────────────
function onGearTypeChange(idx, val) {
    gearRows[idx].Gear_Type = val;
    var hasHelix = gearTypeHasHelix(val);
    document.querySelectorAll('.helix-group-'+idx).forEach(function(el){ el.style.display = hasHelix?'':'none'; });
    var cat = getGearSpecCategory(val);
    var isSprocket = cat==='sprocket', isPulley = cat==='timing_pulley', isSpline = cat==='spline', isWorm = cat==='worm_gear';
    var isStd = !isSprocket && !isPulley && !isSpline;
    var stdEl = document.querySelector('.gear-standard-fields-'+idx);
    var spkEl = document.querySelector('.gear-sprocket-fields-'+idx);
    var puEl  = document.querySelector('.gear-pulley-fields-'+idx);
    var splEl = document.querySelector('.gear-spline-fields-'+idx);
    var gqEl  = document.querySelector('.gear-quality-block-'+idx);
    var gsEl  = document.querySelector('.gear-shift-block-'+idx);
    var gwEl  = document.querySelector('.gear-worm-starts-'+idx);
    var gstEl = document.querySelector('.gear-spline-type-'+idx);
    if (stdEl)  stdEl.style.display  = isStd ? '' : 'none';
    if (spkEl)  spkEl.style.display  = isSprocket ? '' : 'none';
    if (puEl)   puEl.style.display   = isPulley ? '' : 'none';
    if (splEl)  splEl.style.display  = isSpline ? '' : 'none';
    if (gqEl)   gqEl.style.display   = isSprocket ? 'none' : '';
    if (gsEl)   gsEl.style.display   = isStd ? '' : 'none';
    if (gwEl)   gwEl.style.display   = isWorm ? '' : 'none';
    if (gstEl)  gstEl.style.display  = isSpline ? '' : 'none';
    if (isSprocket) _initChainSizeSelect(idx, gearRows[idx].spec_chain_size||'');
    if (isPulley)   _initBeltProfileSelect(idx, gearRows[idx].spec_pulley_profile||'');
}

// ── 模數 M/CP/DP 切換 ─────────────────────────────────────────────────
function onModuleTypeChange(idx, mit) {
    gearRows[idx].module_input_type = mit;
    var inp = document.getElementById('module-val-'+idx);
    var disp = document.getElementById('module-m-display-'+idx);
    if (!inp) return;
    var v = parseFloat(inp.value);
    if (!isNaN(v) && v > 0) {
        var mVal;
        if (mit==='M')  mVal = v;
        else if (mit==='CP') mVal = v / Math.PI;
        else if (mit==='DP') mVal = 25.4 / v;
        gearRows[idx].module_display = mit + trimFloat(String(v));
        if (disp) {
            if (mit!=='M') {
                var mStr = trimFloat(mVal.toFixed(6));
                disp.textContent = '= M'+mStr;
                disp.style.display = '';
                gearRows[idx].Module = 'M'+mStr;
            } else {
                disp.style.display = 'none';
                gearRows[idx].Module = 'M'+(inp.value||'');
            }
        }
    }
}

function formatModuleNew(idx) {
    var mitSel = document.getElementById('module-type-'+idx);
    var inp    = document.getElementById('module-val-'+idx);
    var disp   = document.getElementById('module-m-display-'+idx);
    if (!inp) return;
    var mit = mitSel ? mitSel.value : 'M';
    var v   = parseFloat(inp.value);
    if (!isNaN(v) && v > 0) {
        var mVal;
        if (mit==='M')  mVal = v;
        else if (mit==='CP') mVal = v / Math.PI;
        else if (mit==='DP') mVal = 25.4 / v;
        var mStr = trimFloat(mVal.toPrecision(8));
        gearRows[idx].module_input_type = mit;
        gearRows[idx].Module = 'M'+mStr;
        gearRows[idx].module_display = mit + trimFloat(String(v));
        if (disp && mit!=='M') { disp.textContent = '= M'+mStr; disp.style.display = ''; }
        else if (disp) { disp.style.display = 'none'; }
    }
}

// ── 鏈輪：初始化下拉 & 事件 ─────────────────────────────────────────
function _initChainSizeSelect(idx, currentVal) {
    loadChainSizes(function(chains) {
        var sel = document.querySelector('.gear-sprocket-fields-'+idx+' select[data-field="spec_chain_size"]');
        if (!sel) return;
        var existing = sel.innerHTML.replace(/<option value="custom">.*<\/option>/,'');
        // rebuild options
        var opts = '<option value="">— 選擇或自訂 —</option>';
        var isCustom = currentVal && !chains.some(function(c){ return c.chain_size===currentVal; });
        chains.forEach(function(c) {
            opts += '<option value="'+escHtml(c.chain_size)+'"'+(c.chain_size===currentVal?' selected':'')+'>'+escHtml(c.chain_size)+' (P='+c.pitch_mm+', Dr='+c.roller_dia_mm+') '+c.chain_std+'</option>';
        });
        opts += '<option value="custom"'+(isCustom?' selected':'')+'>自訂節距/滾子徑</option>';
        sel.innerHTML = opts;
        if (currentVal && !isCustom) _fillChainSize(idx, currentVal, chains);
        if (isCustom) {
            var pitchEl2 = document.getElementById('chain-pitch-'+idx);
            var rollerEl2 = document.getElementById('chain-roller-'+idx);
            if (pitchEl2)  { pitchEl2.readOnly=false;  pitchEl2.style.background=''; }
            if (rollerEl2) { rollerEl2.readOnly=false; rollerEl2.style.background=''; }
        }
        calcSprocket(idx);
    });
}

function onChainSizeChange(idx, val) {
    gearRows[idx].spec_chain_size = val;
    if (val === 'custom') {
        var pitchEl = document.getElementById('chain-pitch-'+idx);
        var rollerEl = document.getElementById('chain-roller-'+idx);
        if (pitchEl)  { pitchEl.readOnly=false;  pitchEl.style.background=''; pitchEl.value=''; }
        if (rollerEl) { rollerEl.readOnly=false; rollerEl.style.background=''; rollerEl.value=''; }
        gearRows[idx].spec_pitch = '';
        gearRows[idx].spec_roller_dia = '';
        return;
    }
    loadChainSizes(function(chains){ _fillChainSize(idx, val, chains); });
}

function _fillChainSize(idx, val, chains) {
    var c = chains.filter(function(x){ return x.chain_size===val; })[0];
    if (!c) return;
    var pitchEl  = document.getElementById('chain-pitch-'+idx);
    var rollerEl = document.getElementById('chain-roller-'+idx);
    if (pitchEl)  { pitchEl.value=c.pitch_mm;    pitchEl.readOnly=true;  pitchEl.style.background='#f5f5f5'; }
    if (rollerEl) { rollerEl.value=c.roller_dia_mm; rollerEl.readOnly=true; rollerEl.style.background='#f5f5f5'; }
    gearRows[idx].spec_pitch = c.pitch_mm;
    gearRows[idx].spec_roller_dia = c.roller_dia_mm;
    calcSprocket(idx);
}

function calcSprocket(idx) {
    var P  = parseFloat(document.getElementById('chain-pitch-'+idx)  ? document.getElementById('chain-pitch-'+idx).value  : '');
    var Dr = parseFloat(document.getElementById('chain-roller-'+idx) ? document.getElementById('chain-roller-'+idx).value : '');
    var Z  = parseInt((document.querySelector('.gear-sprocket-fields-'+idx+' input[data-field="Teeth"]')||{}).value||'');
    var el = document.getElementById('sprocket-calc-'+idx);
    if (!el) return;
    if (!P || !Z || Z<=0) { el.innerHTML = '<span style="color:#aaa;">需要 P、Z 才能計算</span>'; return; }
    var PCD = P / Math.sin(Math.PI / Z);
    var OD  = P * (0.6 + 1/Math.tan(Math.PI/Z));
    var RD  = Dr ? (PCD - Dr) : null;
    el.innerHTML = '<b>PCD</b> = ' + PCD.toFixed(3) + ' mm'
        + (RD!==null ? '<br><b>根圓徑</b> = '+RD.toFixed(3)+' mm' : '')
        + '<br><b>OD ≈</b> ' + OD.toFixed(3) + ' mm';
}

// ── 皮帶輪：初始化下拉 & 事件 ────────────────────────────────────────
function _initBeltProfileSelect(idx, currentVal) {
    loadBeltProfiles(function(profiles) {
        var sel = document.querySelector('.gear-pulley-fields-'+idx+' select[data-field="spec_pulley_profile"]');
        if (!sel) return;
        var opts = '<option value="">— 選擇 —</option>';
        profiles.forEach(function(p){
            opts += '<option value="'+escHtml(p.profile_code)+'"'+(p.profile_code===currentVal?' selected':'')+'>'+escHtml(p.profile_code)+' (P='+p.pitch_mm+'mm '+p.belt_standard+')</option>';
        });
        sel.innerHTML = opts;
        if (currentVal) _fillBeltProfile(idx, currentVal, profiles);
    });
}

function onBeltProfileChange(idx, val) {
    gearRows[idx].spec_pulley_profile = val;
    loadBeltProfiles(function(profiles){ _fillBeltProfile(idx, val, profiles); });
}

function _fillBeltProfile(idx, val, profiles) {
    var p = profiles.filter(function(x){ return x.profile_code===val; })[0];
    var pitchEl = document.getElementById('pulley-pitch-'+idx);
    if (p) {
        if (pitchEl) pitchEl.value = p.pitch_mm;
        gearRows[idx].spec_pitch = p.pitch_mm;
        gearRows[idx].spec_pld   = p.pld_mm;
    }
    calcTimingPulley(idx);
}

function calcTimingPulley(idx) {
    var teethEl = document.querySelector('.gear-pulley-fields-'+idx+' input[data-field="Teeth"]');
    var Z = parseInt(teethEl ? teethEl.value : '');
    var pitchEl = document.getElementById('pulley-pitch-'+idx);
    var P = parseFloat(pitchEl ? pitchEl.value : '');
    var g = gearRows[idx]; var PLD = parseFloat(g ? g.spec_pld||0 : 0);
    var el = document.getElementById('pulley-calc-'+idx);
    if (!el) return;
    if (!P || !Z || Z<=0) { el.innerHTML = '<span style="color:#aaa;">需要齒型、齒數才能計算</span>'; return; }
    var PD = (Z * P) / Math.PI;
    var OD = PD - (2 * PLD);
    el.innerHTML = '<b>PD</b> = '+PD.toFixed(3)+' mm<br><b>OD</b> = '+OD.toFixed(3)+' mm';
}

function getGearTypeName(typeVal) {
    if (!typeVal) return '';
    var sv = String(typeVal);
    var found = gearTypeOptions.filter(function(o){ return o.value===sv; });
    return found.length ? found[0].label : '';
}

// ── 花鍵齒形切換 ──────────────────────────────────────────────────────
function onSplineTypeChange(idx, val) {
    gearRows[idx].spec_spline_type = val;
    var isRect = val==='矩形';
    document.querySelectorAll('.spline-inv-'+idx).forEach(function(el){ el.style.display=isRect?'none':''; });
    document.querySelectorAll('.spline-rect-'+idx).forEach(function(el){ el.style.display=isRect?'':'none'; });
}

function onSplineStdChange(idx, val) {
    gearRows[idx].spec_spline_std = val;
    var invStds = ['DIN5480','ISO4156','ANSI B92.1','JIS B1603'];
    var isInvStd = invStds.indexOf(val) >= 0;
    var typeBlock = document.querySelector('.spline-type-block-'+idx);
    if (typeBlock) typeBlock.style.display = isInvStd ? 'none' : '';
    if (isInvStd) {
        gearRows[idx].spec_spline_type = '漸開線';
        var typeEl = document.querySelector('[data-idx="'+idx+'"][data-field="spec_spline_type"]');
        if (typeEl) typeEl.value = '漸開線';
        // 確保顯示漸開線欄位組
        document.querySelectorAll('.spline-inv-'+idx).forEach(function(el){ el.style.display=''; });
        document.querySelectorAll('.spline-rect-'+idx).forEach(function(el){ el.style.display='none'; });
    }
}

function _bindGearKeyNav() {
    var wrap = document.getElementById('gear-rows-wrap');
    if (!wrap || wrap._keyNavBound) return;
    wrap._keyNavBound = true;
    wrap.addEventListener('keydown', function(e) {
        var el = e.target;
        // Radio buttons: left/right arrow cycles options in the same name group
        if (el.type === 'radio' && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
            e.preventDefault();
            var radios = Array.from(wrap.querySelectorAll('input[type=radio][name="'+el.name+'"]'));
            var idx = radios.indexOf(el);
            var next = e.key === 'ArrowRight' ? (idx + 1) % radios.length : (idx - 1 + radios.length) % radios.length;
            radios[next].click();
            radios[next].focus();
            return;
        }
        // Enter: advance to next visible+enabled input or select (not radio, not hidden, not button)
        if (e.key === 'Enter' && el.tagName !== 'BUTTON' && el.type !== 'radio') {
            e.preventDefault();
            var all = Array.from(wrap.querySelectorAll(
                'input:not([type=radio]):not([type=hidden]):not([disabled]), select:not([disabled])'
            )).filter(function(f) { return f.offsetParent !== null; });
            var cur = all.indexOf(el);
            if (cur >= 0 && cur < all.length - 1) all[cur + 1].focus();
        }
    });
}


// Gear type change → show/hide helix group + apply field config
// Module auto-format
function formatModule(el) {
    var v = el.value.trim();
    if (v && /^\d/.test(v) && v.toUpperCase().charAt(0) !== 'M') {
        el.value = 'M' + v;
        var idx = parseInt(el.dataset.idx);
        if (!isNaN(idx) && gearRows[idx]) gearRows[idx]['Module'] = el.value;
    }
}

// Float trim helper
function trimFloat(v) {
    if (v === '' || v === null || v === undefined) return '';
    var n = parseFloat(v);
    if (isNaN(n)) return String(v);
    return String(parseFloat(n.toPrecision(12)));
}

// DMS parsing
function parseDMS(str) {
    if (!str) return {mode:'dec', d:'', m:'', s:''};
    str = String(str);
    // pattern like 11°18'5" or 11d18m5s
    var dmsMatch = str.match(/^(\d+)[°d]\s*(\d+)[\'m]\s*(\d+(?:\.\d+)?)[\"s]?/);
    if (dmsMatch) {
        return {mode:'dms', d:dmsMatch[1], m:dmsMatch[2], s:dmsMatch[3]};
    }
    return {mode:'dec', d:'', m:'', s:''};
}

function dmsToDecimal(d, m, s) {
    return parseFloat(d||0) + parseFloat(m||0)/60 + parseFloat(s||0)/3600;
}

function switchHelixMode(idx, mode) {
    var decDiv = document.getElementById('helix-dec-'+idx);
    var dmsDiv = document.getElementById('helix-dms-'+idx);
    if (mode === 'dms') {
        decDiv.style.display = 'none';
        dmsDiv.style.display = '';
    } else {
        decDiv.style.display = '';
        dmsDiv.style.display = 'none';
    }
}

function syncDMS(idx) {
    var d = parseFloat(document.getElementById('helix-d-'+idx).value||0);
    var m = parseFloat(document.getElementById('helix-m-'+idx).value||0);
    var s = parseFloat(document.getElementById('helix-s-'+idx).value||0);
    var dec = dmsToDecimal(d,m,s);
    var str = d + '°' + m + '\'' + s + '"';
    if (gearRows[idx]) {
        gearRows[idx].Helix_Angle = dec;
        gearRows[idx].Helix_Angle_Str = str;
    }
}

// Collect gear data before submit
function collectGearRows() {
    gearRows.forEach(function(g, i) {
        // Sync all gear-fields
        var row = document.getElementById('gear-row-'+i);
        if (!row) return;
        row.querySelectorAll('.gear-field').forEach(function(el) {
            if (el.offsetParent !== null) g[el.dataset.field] = el.value;
        });
        // Check if DMS mode active
        var dmsDiv = document.getElementById('helix-dms-'+i);
        if (dmsDiv && dmsDiv.style.display !== 'none') {
            syncDMS(i);
        } else {
            var decVal = document.getElementById('helix-dec-val-'+i);
            if (decVal) {
                g.Helix_Angle_Str = decVal.value;
                g.Helix_Angle = parseFloat(decVal.value) || '';
            }
        }
    });
}

// ── BOM rows ──────────────────────────────────────────
function renderBomRows() {
    var wrap = document.getElementById('bom-rows-wrap');
    var canEdit = (CAN_CREATE || CAN_UPDATE);
    if (!bomRows.length) {
        wrap.innerHTML = '<tr><td colspan="4" style="color:#aaa;font-size:12px;padding:8px;">尚未加入子件，請使用下方搜尋框新增</td></tr>';
        return;
    }
    var html = '';
    bomRows.forEach(function(b, i) {
        html += '<tr>';
        html += '<td><span class="bom-row-part">'+escHtml(b.child_part_no)+'</span><br><small style="color:#aaa;">#'+b.child_d_id+'</small></td>';
        html += '<td style="text-align:center;"><input type="number" class="form-control input-sm" style="width:70px;text-align:center;display:inline-block;" min="0.01" step="0.01" value="'+escHtml(String(b.standard_qty||1))+'" onchange="bomRows['+i+'].standard_qty=parseFloat(this.value)||1" '+(canEdit?'':'disabled')+'></td>';
        html += '<td><input type="text" class="form-control input-sm" value="'+escHtml(b.Remark_Bom||'')+'" placeholder="替代料、說明…" maxlength="200" oninput="bomRows['+i+'].Remark_Bom=this.value" '+(canEdit?'':'disabled')+'></td>';
        if (canEdit) html += '<td><button type="button" class="btn-remove-row" style="position:static;font-size:14px;" onclick="bomRows.splice('+i+',1);renderBomRows();" title="移除"><i class="fa fa-times"></i></button></td>';
        else html += '<td></td>';
        html += '</tr>';
    });
    wrap.innerHTML = html;
}

// ── 舊料號 helpers ─────────────────────────────────────────────────────────
function fillOldPartLinks(links) {
    var area = document.getElementById('pf-old-parts-area');
    // 清除現有 rows
    area.querySelectorAll('.pf-old-part-row').forEach(function(r){ r.remove(); });
    // 有幾筆 link 建幾個 row，最少 1 個
    var count = (links && links.length > 0) ? links.length : 1;
    for (var i = 0; i < count; i++) {
        var row = createOldPartRow();
        area.appendChild(row);
        var link = links && links[i];
        if (link && link.old_d_id) {
            row.dataset.did    = link.old_d_id;
            row.dataset.partno = link.old_part_no || '';
            var bd = row.querySelector('.pf-old-bound');
            var cl = row.querySelector('.pf-old-clear');
            if (bd) bd.textContent = (link.old_part_no||'') + (link.old_client_name?' ('+link.old_client_name+')':'');
            if (cl) cl.style.display = '';
        }
    }
    syncOldPartLinksHidden();
    _updateOldPartAddBtn();
}

// ── 舊料號：動態新增/刪除 ──────────────────────────────────────────────────
var _oldPartTimer = null;

function createOldPartRow() {
    var row = document.createElement('div');
    row.className = 'pf-old-part-row';
    row.dataset.did = '0';
    row.dataset.partno = '';
    row.style.cssText = 'display:flex;align-items:center;gap:6px;margin-bottom:4px;';
    row.innerHTML =
        '<div style="position:relative;flex:1;max-width:340px;">' +
        '<input type="text" class="form-control input-sm pf-old-kw" placeholder="輸入料號搜尋…" autocomplete="off" style="width:100%;">' +
        '<div class="pf-old-dd" style="display:none;position:absolute;z-index:1050;width:420px;background:#fff;border:1px solid #ddd;max-height:200px;overflow-y:auto;border-radius:0 0 6px 6px;box-shadow:0 4px 12px rgba(0,0,0,.1);font-size:12px;"></div>' +
        '</div>' +
        '<span class="pf-old-bound" style="font-size:12px;color:#1ABB9C;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;"></span>' +
        '<button type="button" class="btn btn-xs btn-default pf-old-clear" style="display:none;flex-shrink:0;"><i class="fa fa-times"></i></button>' +
        '<button type="button" class="btn btn-xs btn-danger pf-old-remove" style="flex-shrink:0;"><i class="fa fa-minus"></i></button>';
    // 綁事件
    var kw = row.querySelector('.pf-old-kw');
    kw.addEventListener('input', function() { _searchOldPart(this); });
    kw.addEventListener('blur',  function() { setTimeout(function(){ var dd=row.querySelector('.pf-old-dd'); if(dd) dd.style.display='none'; }, 200); });
    row.querySelector('.pf-old-clear').addEventListener('click', function() { _clearOldPartRow(row); });
    row.querySelector('.pf-old-remove').addEventListener('click', function() { removeOldPartRow(row); });
    return row;
}

function addOldPartRow() {
    var area = document.getElementById('pf-old-parts-area');
    if (area.querySelectorAll('.pf-old-part-row').length >= 3) return;
    area.appendChild(createOldPartRow());
    _updateOldPartAddBtn();
}

function removeOldPartRow(rowEl) {
    rowEl.remove();
    syncOldPartLinksHidden();
    _updateOldPartAddBtn();
}

function _clearOldPartRow(row) {
    row.dataset.did = '0'; row.dataset.partno = '';
    var kw = row.querySelector('.pf-old-kw'); if (kw) kw.value = '';
    var bd = row.querySelector('.pf-old-bound'); if (bd) bd.textContent = '';
    var cl = row.querySelector('.pf-old-clear'); if (cl) cl.style.display = 'none';
    syncOldPartLinksHidden();
}

function _searchOldPart(inp) {
    clearTimeout(_oldPartTimer);
    var row = inp.closest('.pf-old-part-row');
    var dd = row ? row.querySelector('.pf-old-dd') : null;
    var kw = inp.value.trim();
    if (!kw) { if(dd) dd.style.display='none'; return; }
    var curDid = parseInt(document.getElementById('pf-d_id').value||'0');
    _oldPartTimer = setTimeout(function(){
        api({ action:'search_old_parts', keyword:kw, exclude_d_id:curDid }).done(function(r){
            if (!dd) return;
            if (!r.success || !r.data.length) { dd.innerHTML='<div style="padding:8px 12px;color:#aaa;">無符合料號</div>'; dd.style.display=''; return; }
            dd.innerHTML = r.data.map(function(d){
                var specStr = d.Spec_No    ? '<span style="color:#aaa;font-size:11px;margin-left:6px;">'+escHtml(d.Spec_No)+'</span>'    : '';
                var custStr = d.client_name? '<span style="color:#1ABB9C;font-size:11px;margin-left:6px;">'+escHtml(d.client_name)+'</span>':'';
                return '<div style="padding:6px 12px;cursor:pointer;border-bottom:1px solid #f5f5f5;line-height:1.4;" onmousedown="_selectOldPart(this,'+d.d_id+',\''+escAttr(d.D_Setting_Id)+'\',\''+escAttr(d.client_name||'')+'\')">'+
                    '<strong style="font-size:13px;">'+escHtml(d.D_Setting_Id)+'</strong>'+specStr+custStr+'</div>';
            }).join('');
            dd.style.display = '';
        });
    }, 280);
}

function _selectOldPart(ddItem, did, partNo, clientName) {
    var row = ddItem.closest('.pf-old-part-row');
    if (!row) return;
    row.dataset.did = did; row.dataset.partno = partNo;
    var kw = row.querySelector('.pf-old-kw'); if (kw) kw.value = '';
    var dd = row.querySelector('.pf-old-dd'); if (dd) dd.style.display = 'none';
    var bd = row.querySelector('.pf-old-bound'); if (bd) bd.textContent = partNo + (clientName?' ('+clientName+')':'');
    var cl = row.querySelector('.pf-old-clear'); if (cl) cl.style.display = '';
    syncOldPartLinksHidden();
}

function _updateOldPartAddBtn() {
    var area = document.getElementById('pf-old-parts-area');
    var btn  = document.getElementById('pf-old-add-btn');
    if (btn) btn.style.display = area.querySelectorAll('.pf-old-part-row').length >= 3 ? 'none' : '';
}

function syncOldPartLinksHidden() {
    var links = [];
    document.querySelectorAll('#pf-old-parts-area .pf-old-part-row').forEach(function(row, i) {
        var did = parseInt(row.dataset.did || '0');
        if (did > 0) links.push({ old_d_id: did, sort_order: i });
    });
    var h = document.getElementById('pf-old-part-links');
    if (h) h.value = JSON.stringify(links);
}

var childSearchTimer;
function searchChildPart(kw) {
    clearTimeout(childSearchTimer);
    var dd = document.getElementById('bom-child-dropdown');
    if (!kw.trim()) { dd.style.display='none'; return; }
    childSearchTimer = setTimeout(function() {
        var excl = parseInt(document.getElementById('pf-d_id').value) || 0;
        api({ action:'search_child_parts', keyword:kw, exclude_d_id:excl }).done(function(r) {
            if (!r.success || !r.data.length) { dd.style.display='none'; return; }
            var html = '';
            r.data.forEach(function(p) {
                html += '<div class="bom-child-item" onclick="addBomChild('+p.d_id+',\''+escAttr(p.D_Setting_Id)+'\')">';
                html += '<strong>'+escHtml(p.D_Setting_Id)+'</strong>';
                if (p.Spec_No) html += ' <small style="color:#888;">'+escHtml(p.Spec_No)+'</small>';
                if (p.client_name) html += '<small style="color:#aaa;float:right;">'+escHtml(p.client_name)+'</small>';
                html += '</div>';
            });
            dd.innerHTML = html;
            dd.style.display = 'block';
        });
    }, 250);
}
document.addEventListener('click', function(e) {
    if (!e.target.closest('#bom-search-input') && !e.target.closest('#bom-child-dropdown'))
        document.getElementById('bom-child-dropdown').style.display = 'none';
});

function addBomChild(d_id, part_no) {
    var already = bomRows.some(function(b){ return b.child_d_id === d_id; });
    if (already) { showToast('此子件已在清單中','error'); return; }
    bomRows.push({ child_d_id:d_id, child_part_no:part_no, standard_qty:1, Remark_Bom:'' });
    renderBomRows();
    document.getElementById('bom-search-input').value = '';
    document.getElementById('bom-child-dropdown').style.display = 'none';
}

// ── Open / Submit ─────────────────────────────────────
function _loadPartTypeOptions(currentVal, callback) {
    // Also reload gear types if not loaded
    if (!gearTypeOptions.length) {
        reloadGearTypeOptions(function(){});
    }
    api({ action:'manage_workpiece_types', op:'list' }).done(function(r) {
        var sel = document.getElementById('pf-Type');
        if (!sel) { if (callback) callback(); return; }
        var cur = currentVal || sel.value || 'N';
        sel.innerHTML = '';
        if (r.success && r.data && r.data.length) {
            r.data.forEach(function(t){
                sel.appendChild(new Option(t.type_code + ' — ' + t.type_name, t.type_code));
                typeLabel[t.type_code] = t.type_name;
                partTypeMeta[t.type_code] = {
                    show_vendor:  Number(t.show_vendor)===1,
                    show_part_no: Number(t.show_part_no)===1,
                    show_machine: Number(t.show_machine)===1,
                    show_price:   Number(t.show_price)===1
                };
            });
        } else {
            // fallback hardcoded
            [['N','一般'],['G','齒輪'],['H','滾刀']].forEach(function(x){
                sel.appendChild(new Option(x[0]+' — '+x[1], x[0]));
            });
        }
        sel.value = cur;
        if (!sel.value && sel.options.length) sel.value = sel.options[0].value;
        if (callback) callback();
    });
}

// ── Weight unit toggle ─────────────────────────────────
var _weightUnit = 'g';
function _setWeightUnit(unit) {
    _weightUnit = unit;
    var btn = document.getElementById('pf-weight-unit-btn');
    if (!btn) return;
    if (unit === 'g') {
        btn.textContent = 'g';
        btn.style.background = '#f0faf8'; btn.style.color = '#1ABB9C'; btn.style.borderColor = '#b2dfdb';
    } else {
        btn.textContent = 'kg';
        btn.style.background = '#e3f2fd'; btn.style.color = '#1565C0'; btn.style.borderColor = '#90caf9';
    }
}
function toggleWeightUnit() {
    var input = document.getElementById('pf-Weight_Kg');
    var v = input.value !== '' ? parseFloat(input.value) : null;
    if (_weightUnit === 'g') {
        if (v !== null && !isNaN(v)) input.value = String(trimFloat(v / 1000));
        _setWeightUnit('kg');
    } else {
        if (v !== null && !isNaN(v)) input.value = String(trimFloat(v * 1000));
        _setWeightUnit('g');
    }
}
function _fillWeightField(weightKg) {
    _setWeightUnit('g');
    var input = document.getElementById('pf-Weight_Kg');
    if (!input) return;
    var n = (weightKg != null && weightKg !== '') ? parseFloat(weightKg) : NaN;
    input.value = !isNaN(n) ? String(trimFloat(n * 1000)) : '';
}
function _getWeightKg() {
    var input = document.getElementById('pf-Weight_Kg');
    if (!input || input.value === '') return '';
    var v = parseFloat(input.value);
    if (isNaN(v)) return '';
    return _weightUnit === 'g' ? String(v / 1000) : String(v);
}

function openPartModal(d_id) {
    gearRows = []; bomRows = [];
    if (d_id > 0) {
        if (!CAN_UPDATE && !CAN_EDIT_GEAR && !CAN_DELETE_GEAR) { showToast('無修改權限','error'); return; }
        api({ action:'get_part', d_id:d_id }).done(function(r) {
            if (!r.success) { showToast(r.message,'error'); return; }
            var d = r.data;
            // // ── DEBUG: dump label data ──
            // console.group('[DEBUG] get_part labels — ' + d.D_Setting_Id);
            // (d.labels||[]).forEach(function(lbl) {
            //     var subInfo = (lbl.sub_labels||[]).map(function(s){
            //         return s.sub_name+'(sub_id='+s.sub_id+',val='+s.input_value+',rng='+s.is_range+',min='+s.value_min+',max='+s.value_max+')';
            //     }).join(' | ');
            //     console.log('  label_id='+lbl.label_id+' name='+lbl.label_name+' is_range='+lbl.is_range+' val='+lbl.input_value+' min='+lbl.value_min+' max='+lbl.value_max+' sub_labels=['+subInfo+']');
            // });
            // console.groupEnd();
            document.getElementById('partModal-title').textContent = '編輯料號';
            document.getElementById('pf-d_id').value           = d.d_id;
            document.getElementById('pf-D_Setting_Id').value   = d.D_Setting_Id;
            document.getElementById('pf-Drawing_No').value     = (d.Drawing_No && d.Drawing_No !== d.D_Setting_Id) ? d.Drawing_No : '';
            document.getElementById('pf-Spec_No').value        = d.Spec_No||'';
            document.getElementById('pf-Revision').value       = d.Revision||'';
            setIssueDateFields(d.Issue_Date||'');
            _loadPartTypeOptions(d.Type||'N', function(){
                // skipSubType/skipLabels：避免 onTypeChange 先以空值載入，造成與下面帶值請求競態（小類選取被清掉）
                onTypeChange(d.Type||'N', {skipSubType:true, skipLabels:true});
                loadPartSubTypes(d.Type||'N', parseInt(d.workpiece_sub_type_id||0));
                loadPartLabels(d.Type||'N', d.labels||[]);
                // 載入此料號既有的 廠商 / 專用料號 / 專用機台 / 價格
                pfAcLoadFromPart(d);
            });
            document.getElementById('pf-Is_Assembly').checked  = (d.Is_Assembly=='1');
            document.getElementById('pf-Remark').value         = d.Remark||'';
            _fillWeightField(d.Weight_Kg);
            // 重量來源標示
            var wsBadge = document.getElementById('pf-weight-source-badge');
            var wcBtn   = document.getElementById('btn-weight-calc');
            var cpBtn   = document.getElementById('btn-copy-labels');
            if (wsBadge) wsBadge.style.display = (d.weight_source==='calculated') ? '' : 'none';
            if (wcBtn)   wcBtn.style.display   = '';
            if (cpBtn)   cpBtn.style.display   = '';
            document.getElementById('pf-weight-source').value    = d.weight_source||'manual';
            document.getElementById('pf-weight-calc-json').value = '';
            fillOldPartLinks(d.old_part_links || []);
            document.getElementById('pf-Customer_Id').value    = d.Customer_Id||'';
            document.getElementById('pf-customer-display').value = d.client_name ? (d.client_name+' ('+d.Customer_Id+')') : (d.Customer_Id||'');
            document.getElementById('pf-cust-hint').textContent = d.Customer_Id ? ('目前綁定：'+d.Customer_Id) : '';
            // Gear
            var gs = document.getElementById('gear-section');
            var bs = document.getElementById('bom-section');
            gs.style.display = 'none'; bs.style.display = 'none';
            if (d.Type==='G') {
                $(gs).show();
                if (d.gears && d.gears.length) d.gears.forEach(function(g){ addGearRow(g); });
                else addGearRow({});
            } else { renderGearRows(); }
            // BOM
            if (d.Is_Assembly=='1') {
                $(bs).show();
                if (d.bom_children && d.bom_children.length) {
                    d.bom_children.forEach(function(b){
                        bomRows.push({ child_d_id:b.child_d_id, child_part_no:b.child_part_no, standard_qty:b.standard_qty||1, Remark_Bom:b.Remark_Bom||'' });
                    });
                }
                renderBomRows();
            } else { renderBomRows(); }
            // 設計備註已在列表有獨立按鈕，編輯視窗內不顯示
            var pdWrap = document.getElementById('part-design-note-wrap');
            if (pdWrap) pdWrap.style.display = 'none';
            var saveBtn = document.getElementById('part-save-btn');
            if (saveBtn) saveBtn.style.display = (CAN_UPDATE || CAN_EDIT_GEAR) ? '' : 'none';
            $('#partModal').modal('show');
        });
    } else {
        if (!CAN_CREATE) { showToast('無新增權限','error'); return; }
        document.getElementById('partModal-title').textContent = '新增料號';
        document.getElementById('partForm').reset();
        _setWeightUnit('g');
        document.getElementById('pf-d_id').value = '0';
        pfAcReset();   // 清空 廠商 / 專用料號 / 專用機台 / 價格
        _loadPartTypeOptions('N', function(){ onTypeChange('N'); });
        document.getElementById('pf-Customer_Id').value = '';
        document.getElementById('pf-customer-display').value = '';
        document.getElementById('pf-cust-hint').textContent = '';
        document.getElementById('gear-section').style.display = 'none';
        document.getElementById('bom-section').style.display = 'none';
        document.getElementById('pf-label-section').style.display = 'none';
        document.getElementById('pf-labels-json').value = '[]';
        var _nm_badge = document.getElementById('pf-weight-source-badge');
        var _nm_wcBtn = document.getElementById('btn-weight-calc');
        var _nm_cpBtn = document.getElementById('btn-copy-labels');
        if (_nm_badge) _nm_badge.style.display = 'none';
        if (_nm_wcBtn) _nm_wcBtn.style.display  = 'none';
        if (_nm_cpBtn) _nm_cpBtn.style.display  = '';
        document.getElementById('pf-weight-source').value    = 'manual';
        document.getElementById('pf-weight-calc-json').value = '';
        fillOldPartLinks([]);
        renderGearRows();
        renderBomRows();
        var pdWrap = document.getElementById('part-design-note-wrap');
        if (pdWrap) pdWrap.style.display = 'none';
        var saveBtn = document.getElementById('part-save-btn');
        if (saveBtn) saveBtn.style.display = '';
        $('#partModal').one('shown.bs.modal', function() {
            var el = document.getElementById('pf-D_Setting_Id');
            if (el) { el.focus(); el.select(); }
        });
        $('#partModal').modal('show');
    }
}

// ── 料號／圖面代號 重複即時檢查（輸入當下就顯示原因，不等到儲存）──────────
var _codeConflict = { D_Setting_Id:'', Drawing_No:'' };
function _setCodeErr(fid, msg) {
    _codeConflict[fid] = msg || '';
    var el = document.getElementById('pf-'+fid), box = document.getElementById('pf-'+fid+'-err');
    if (!el || !box) return;
    if (msg) { box.textContent = msg; box.classList.add('show'); el.classList.add('code-conflict'); }
    else     { box.textContent = '';  box.classList.remove('show'); el.classList.remove('code-conflict'); }
}
function clearCodeConflict() { _setCodeErr('D_Setting_Id',''); _setCodeErr('Drawing_No',''); }
function checkCodeConflict() {
    var pEl = document.getElementById('pf-D_Setting_Id'), dEl = document.getElementById('pf-Drawing_No');
    if (!pEl || !dEl) return;
    var part = pEl.value.trim(), dw = dEl.value.trim();
    if (!part && !dw) { clearCodeConflict(); return; }
    api({ action:'check_code_conflict', d_id:(document.getElementById('pf-d_id')||{value:0}).value,
          D_Setting_Id:part, Drawing_No:dw })
      .done(function(r){
          if (!r || !r.success) return;
          _setCodeErr('D_Setting_Id', (r.conflict && r.field === 'D_Setting_Id') ? r.message : '');
          _setCodeErr('Drawing_No',   (r.conflict && r.field === 'Drawing_No')   ? r.message : '');
      });
}
var _checkCodeConflictDebounced = debounce(checkCodeConflict, 350);
$(document).on('input',    '#pf-D_Setting_Id, #pf-Drawing_No', _checkCodeConflictDebounced);
$(document).on('focusout', '#pf-D_Setting_Id, #pf-Drawing_No', checkCodeConflict);
$(document).on('shown.bs.modal', '#partModal', checkCodeConflict);

function submitPartForm() {
    collectGearRows();
    // Validate
    var type = document.getElementById('pf-Type').value;
    if (type === 'G' && gearRows.length === 0) { showToast('齒輪料號至少需設定一筆齒輪規格','error'); return; }
    if (type === 'G') {
        for (var i=0; i<gearRows.length; i++) {
            var g = gearRows[i];
            var gCat = getGearSpecCategory(g.Gear_Type);
            if (!g.Gear_Type) { showToast('第 '+(i+1)+' 列齒型：請選擇齒輪類型','error'); return; }
            if (gCat === 'sprocket') {
                if (!g.Teeth || g.Teeth==='') { showToast('第 '+(i+1)+' 列齒型（鏈輪）：齒數不可為空','error'); return; }
            } else if (gCat === 'timing_pulley') {
                if (!g.Teeth || g.Teeth==='') { showToast('第 '+(i+1)+' 列齒型（皮帶輪）：齒數不可為空','error'); return; }
            } else {
                if (!g.Module || !g.Module.trim()) { showToast('第 '+(i+1)+' 列齒型：模數不可為空','error'); return; }
                if (!g.Teeth || g.Teeth==='') { showToast('第 '+(i+1)+' 列齒型：齒數不可為空','error'); return; }
            }
        }
    }
    var data = {
        action:       'save_part',
        d_id:         document.getElementById('pf-d_id').value,
        D_Setting_Id: document.getElementById('pf-D_Setting_Id').value.trim(),
        Drawing_No:   document.getElementById('pf-Drawing_No').value.trim(),
        Spec_No:      document.getElementById('pf-Spec_No').value,
        Revision:     document.getElementById('pf-Revision').value,
        Issue_Date:   document.getElementById('pf-Issue_Date').value,
        Type:         type,
        workpiece_sub_type_id: (document.getElementById('pf-workpiece_sub_type_id')||{value:''}).value,
        Is_Assembly:  document.getElementById('pf-Is_Assembly').checked ? 1 : 0,
        Customer_Id:  document.getElementById('pf-Customer_Id').value,
        Remark:       document.getElementById('pf-Remark').value,
        Weight_Kg:    _getWeightKg(),
        gears:        JSON.stringify(gearRows),
        bom_children: JSON.stringify(bomRows),
        labels:       (document.getElementById('pf-labels-json')||{value:'[]'}).value,
        old_part_links: (document.getElementById('pf-old-part-links')||{value:'[]'}).value,
        vendor_map:         (document.getElementById('pf-vendor-map')||{value:'[]'}).value,
        dedicated_part_map: (document.getElementById('pf-dedicated-part-map')||{value:'[]'}).value,
        machine_map:        (document.getElementById('pf-machine-map')||{value:'[]'}).value
    };
    if (!data.D_Setting_Id) { showToast('料號不可為空','error'); return; }
    if (!data.Customer_Id) { showToast('客戶為必填欄位','error'); var _ce=document.getElementById('pf-customer-display'); if(_ce){_ce.focus();_ce.select();} return; }
    if (_codeConflict.D_Setting_Id) { showToast(_codeConflict.D_Setting_Id,'error'); var _pe=document.getElementById('pf-D_Setting_Id'); if(_pe){_pe.focus();_pe.select();} return; }
    if (_codeConflict.Drawing_No)   { showToast(_codeConflict.Drawing_No,'error');   var _de=document.getElementById('pf-Drawing_No');   if(_de){_de.focus();_de.select();} return; }
    var btn = document.querySelector('#partModal .btn-success');
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> 儲存中…'; }
    var restore = function(){ if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa fa-save"></i> 儲存'; } };
    apiOnce('save_part', data,
        function(r) {
            restore();
            if (r.success) {
                showToast(r.message,'success');
                $('#partModal').one('hidden.bs.modal', function(){ loadParts(partsCurrent); });
                $('#partModal').modal('hide');
            } else showToast(r.message,'error');
        },
        function(){ restore(); showToast('網路錯誤','error'); }
    );
}

// ── 料號刪除 modal 狀態 ───────────────────────────────────
var _dpm_d_id = 0, _dpm_name = '', _dpm_tgt_d_id = 0;

function deletePart(d_id, name) {
    _dpm_d_id = d_id; _dpm_name = name; _dpm_tgt_d_id = 0;
    document.getElementById('dpm-title-name').textContent = name;
    document.getElementById('dpm-loading').style.display = '';
    ['dpm-blocked','dpm-confirm','dpm-transfer'].forEach(function(id){ document.getElementById(id).style.display='none'; });
    document.getElementById('dpm-ok-input').value = '';
    document.getElementById('dpm-transfer-ok').value = '';
    document.getElementById('dpm-tgt-input').value = '';
    document.getElementById('dpm-tgt-info').textContent = '尚未選擇目標料號';
    document.getElementById('dpm-tgt-info').style.color = '#aaa';
    document.getElementById('dpm-tgt-dd').style.display = 'none';
    $('#deletePartModal').modal('show');
    api({ action:'check_part_blocks', d_id:d_id }).done(function(r) {
        document.getElementById('dpm-loading').style.display = 'none';
        if (!r.success) { showToast(r.message,'error'); return; }
        if (r.blocks && r.blocks.length) {
            var ul = document.getElementById('dpm-blocks-list');
            ul.innerHTML = r.blocks.map(function(b){ return '<li>'+escHtml(b)+'</li>'; }).join('');
            document.getElementById('dpm-blocked').style.display = '';
            document.getElementById('dpm-transfer-btn-wrap').style.display = CAN_DELETE_ALL ? '' : 'none';
            // 填入來源料號資訊
            var p = r.part || {};
            document.getElementById('dpm-src-info').innerHTML =
                '<strong>' + escHtml(p.D_Setting_Id||'') + '</strong>'
                + ' <span style="color:#aaa;font-size:10px;">ID: ' + escHtml(String(p.d_id||'')) + '</span><br>'
                + '<span style="color:#555;">客戶：' + escHtml(p.customer_name||'—') + '</span>';
        } else {
            document.getElementById('dpm-confirm').style.display = '';
        }
    });
}

function showPartTransferSection() {
    document.getElementById('dpm-blocked').style.display = 'none';
    document.getElementById('dpm-transfer').style.display = '';
}

var _dpmTgtTimer = null;
function onDpmTgtInput(val) {
    clearTimeout(_dpmTgtTimer);
    _dpm_tgt_d_id = 0;
    document.getElementById('dpm-tgt-info').textContent = '尚未選擇目標料號';
    document.getElementById('dpm-tgt-info').style.color = '#aaa';
    var dd = document.getElementById('dpm-tgt-dd');
    if (!val.trim()) { dd.style.display='none'; return; }
    _dpmTgtTimer = setTimeout(function() {
        api({ action:'get_part_transfer_info', kw:val.trim() }).done(function(r) {
            if (!r.success || !r.data || !r.data.length) { dd.style.display='none'; return; }
            dd.innerHTML = r.data.map(function(p) {
                return '<div onclick="selectDpmTgt('+p.d_id+',\''+escAttr(p.D_Setting_Id)+'\',\''+escAttr(p.customer_name||'')+'\',\''+escAttr(p.bound_counts||'')+'\',this)" '
                    + 'style="padding:7px 10px;cursor:pointer;border-bottom:1px solid #f5f5f5;font-size:12px;">'
                    + '<strong>' + escHtml(p.D_Setting_Id) + '</strong>'
                    + ' <span style="color:#aaa;font-size:10px;">ID:'+p.d_id+'</span>'
                    + '<br><span style="color:#888;">客戶：' + escHtml(p.customer_name||'—') + '</span>'
                    + ' <span style="color:#1ABB9C;">'+escHtml(p.bound_counts)+'</span></div>';
            }).join('');
            dd.style.display = 'block';
        });
    }, 250);
}
function selectDpmTgt(d_id, partNo, custName, boundCounts, el) {
    _dpm_tgt_d_id = d_id;
    document.getElementById('dpm-tgt-input').value = partNo;
    document.getElementById('dpm-tgt-dd').style.display = 'none';
    var info = document.getElementById('dpm-tgt-info');
    info.style.color = '#333';
    info.innerHTML = '<strong>' + escHtml(partNo) + '</strong>'
        + ' <span style="color:#aaa;font-size:10px;">ID: ' + d_id + '</span><br>'
        + '<span style="color:#555;">客戶：' + escHtml(custName||'—') + '</span>'
        + (boundCounts ? '<br><span style="color:#1ABB9C;">目前綁定：' + escHtml(boundCounts) + '</span>' : '');
}
document.addEventListener('click', function(e) {
    if (!e.target.closest('#dpm-tgt-input') && !e.target.closest('#dpm-tgt-dd'))
        document.getElementById('dpm-tgt-dd').style.display = 'none';
});

function _afterPartOp() { $('#deletePartModal').modal('hide'); loadParts(partsCurrent); if ($('#dupCheckModal').hasClass('in')) openDupCheck('parts'); }
function doDeletePart() {
    if (document.getElementById('dpm-ok-input').value.trim().toUpperCase() !== 'OK') {
        showToast('請輸入大寫 OK 確認','error'); return;
    }
    api({ action:'delete_part', d_id:_dpm_d_id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _afterPartOp(); }
        else showToast(r.message,'error');
    });
}

function doTransferPart() {
    if (!_dpm_tgt_d_id) { showToast('請選擇目標料號','error'); return; }
    if (_dpm_tgt_d_id === _dpm_d_id) { showToast('來源與目標不可相同','error'); return; }
    if (document.getElementById('dpm-transfer-ok').value.trim().toUpperCase() !== 'OK') {
        showToast('請輸入大寫 OK 確認','error'); return;
    }
    api({ action:'transfer_part_binding', src_d_id:_dpm_d_id, tgt_d_id:_dpm_tgt_d_id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _afterPartOp(); }
        else showToast(r.message,'error');
    });
}

// ── 複製料號（預填資料到新增視窗，讓使用者確認後存檔）──
function copyPartModal(d_id) {
    if (!CAN_CREATE && !CAN_UPDATE) { showToast('無新增或編輯權限','error'); return; }
    api({ action:'get_part', d_id:d_id }).done(function(r) {
        if (!r.success) { showToast(r.message||'讀取失敗','error'); return; }
        var d = r.data;
        var _copyLabelsAndGears = confirm('是否一併複製來源料號的標籤與齒輪資料？\n按「取消」則只複製料號基本資料，標籤與齒輪資料需另行設定。');
        gearRows = []; bomRows = [];
        // 先 reset 避免殘留值或瀏覽器自動填充
        document.getElementById('partForm').reset();
        document.getElementById('partModal-title').textContent = '複製料號（來源：' + d.D_Setting_Id + '）';
        document.getElementById('pf-d_id').value = '0';  // 新增，非更新
        document.getElementById('pf-D_Setting_Id').value = d.D_Setting_Id||''; // 複製來源料號，供使用者修改
        document.getElementById('pf-D_Setting_Id').placeholder = '請修改料號（不可與來源重複）';
        document.getElementById('pf-Drawing_No').value  = '';
        document.getElementById('pf-Spec_No').value     = d.Spec_No||'';
        document.getElementById('pf-Revision').value    = d.Revision||'';
        setIssueDateFields(d.Issue_Date||'');
        _loadPartTypeOptions(d.Type||'N', function(){
            onTypeChange(d.Type||'N');
            loadPartSubTypes(d.Type||'N', parseInt(d.workpiece_sub_type_id||0));
            loadPartLabels(d.Type||'N', _copyLabelsAndGears ? (d.labels||[]) : []);
        });
        document.getElementById('pf-Is_Assembly').checked = (d.Is_Assembly=='1');
        onAssemblyChange(d.Is_Assembly=='1');
        document.getElementById('pf-Remark').value      = d.Remark||'';
        _fillWeightField(d.Weight_Kg);
        document.getElementById('pf-Customer_Id').value = d.Customer_Id||'';
        document.getElementById('pf-customer-display').value = d.client_name ? (d.client_name+' ('+d.Customer_Id+')') : (d.Customer_Id||'');
        document.getElementById('pf-cust-hint').textContent  = d.Customer_Id ? ('複製自：'+d.Customer_Id) : '';
        // 齒輪規格
        var gs = document.getElementById('gear-section');
        var bs = document.getElementById('bom-section');
        gs.style.display = 'none'; bs.style.display = 'none';
        if (d.Type==='G') {
            $(gs).show();
            if (_copyLabelsAndGears && d.gears && d.gears.length) d.gears.forEach(function(g){ addGearRow(g); });
            else addGearRow({});
        } else { renderGearRows(); }
        // 組合件子件
        if (d.Is_Assembly=='1') {
            $(bs).show();
            if (d.bom_children && d.bom_children.length) {
                d.bom_children.forEach(function(b){
                    bomRows.push({ child_d_id:b.child_d_id, child_part_no:b.child_part_no, standard_qty:b.standard_qty||1, Remark_Bom:b.Remark_Bom||'' });
                });
            }
            renderBomRows();
        } else { renderBomRows(); }
        // 設計備註不複製（屬於原料號，複製後再另行建立）
        var pdWrap = document.getElementById('part-design-note-wrap');
        if (pdWrap) pdWrap.style.display = 'none';
        var saveBtn = document.getElementById('part-save-btn');
        if (saveBtn) saveBtn.style.display = '';
        showToast('已預填複製資料，請修改料號後儲存');
        $('#partModal').modal('show');
    });
}

// ── 客戶下拉搜尋 ──────────────────────────────────────
var custDropTimer;
document.getElementById('pf-customer-display').addEventListener('input', function() {
    clearTimeout(custDropTimer);
    var kw = this.value.trim();
    var dd = document.getElementById('pf-customer-dropdown');
    if (!kw) {
        dd.style.display='none';
        document.getElementById('pf-Customer_Id').value = '';
        document.getElementById('pf-cust-hint').textContent = '';
        return;
    }
    custDropTimer = setTimeout(function() {
        api({ action:'search_customers_dropdown', keyword:kw }).done(function(r) {
