            var html = '';
            r.data.forEach(function(c) {
                html += '<div onclick="selectCust(\''+escAttr(c.customer_id)+'\',\''+escAttr(c.customer)+'\')" style="padding:7px 12px;cursor:pointer;font-size:13px;border-bottom:1px solid #f5f5f5;">';
                html += '<strong style="color:#2A3F54">'+escHtml(c.customer_id)+'</strong> — '+escHtml(c.customer);
                html += '</div>';
            });
