}

// ═══════════════════════════════════════════════════
// ──────────── 客戶 ─────────────────────────────────
// ═══════════════════════════════════════════════════
var customersLoaded=false, customersCurrent=1, customersTotal=1;
var industryCache = null;  // cache from API

function getCustKws() {
    var live = (document.getElementById('customers-search')||{}).value || '';
    var all = _custFilter.keywords.slice().concat(_custFilter.quickKws||[]); if (live.trim()) all.push(live.trim()); return all.join('||');
}
// 地址截斷至路/街
function _truncAddr(addr) {
    if (!addr) return '';
    var ri = addr.indexOf('路');
    var si = addr.indexOf('街');
    var idx = -1;
    if (ri >= 0 && si >= 0) idx = Math.min(ri, si);
    else if (ri >= 0) idx = ri;
    else if (si >= 0) idx = si;
    if (idx >= 0 && idx + 1 < addr.length) return addr.substring(0, idx + 1) + '…';
    return addr;
}
// 通用文字跳窗（標題 + 內容）
function showTextPopup(title, text) {
    var iconMap = {'完整地址':'fa-map-marker','出貨要求':'fa-truck'};
    var icon = iconMap[title] || 'fa-info-circle';
    var ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.35);z-index:19999;display:flex;align-items:center;justify-content:center;';
    ov.innerHTML = '<div style="background:#fff;border-radius:8px;padding:20px 24px;max-width:380px;width:90%;box-shadow:0 6px 24px rgba(0,0,0,.2);">'
        + '<div style="font-size:13px;font-weight:700;color:#333;margin-bottom:10px;"><i class="fa '+icon+'" style="color:#e67e22;margin-right:6px;"></i>'+escHtml(title)+'</div>'
        + '<div style="font-size:13px;color:#555;line-height:1.9;word-break:break-all;white-space:pre-wrap;">' + escHtml(text) + '</div>'
        + '<div style="text-align:right;margin-top:14px;"><button class="btn btn-sm btn-default" id="_tp-close-btn">關閉</button></div>'
        + '</div>';
    ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });
    ov.querySelector('#_tp-close-btn').addEventListener('click', function(){ ov.remove(); });
    document.body.appendChild(ov);
}
function showAddrPopup(addr) { showTextPopup('完整地址', addr); }
function loadCustomers(pg) {
    pg = pg || 1;
    customersCurrent = pg;
    document.getElementById('customers-table-wrap').innerHTML = '<div class="table-loading"><div class="spinner"></div> 載入中…</div>';
    api({ action:'list_customers', keywords_p:getCustKws(), page:pg,
          filter_grades_p:_custFilter.grades.join(','),
          filter_industries_p:_custFilter.industries.join(','),
          filter_industry_subs_p:_custFilter.industrySubs.join(','),
          filter_pinned_cust_ids:_custFilter.pinnedCustIds.join(','),
          filter_payment_method: _custFilter.payment_method,
          filter_settlement_mode: _custFilter.settlement_mode,
          filter_settlement_day: _custFilter.settlement_day !== null ? _custFilter.settlement_day : '' }).done(function(r) {
        if (!r.success) { showToast(r.message,'error'); return; }
        customersLoaded = true;
        customersTotal  = r.pages;
        renderCustomersTable(r.data, r.total, pg, r.pages);
    }).fail(function(){ showToast('網路錯誤','error'); });
}

// Settlement mode labels
var settleModeLabel = {FIXED:'固定日', EOM:'月底', VARIABLE:'不固定'};

function renderCustomersTable(rows, total, pg, pages) {
    var cols = 10 + (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS ? 1 : 0) + (CAN_SEE_DESIGN ? 1 : 0);
    var html = '<div style="overflow-x:auto;"><table class="table" style="font-size:12px;"><thead><tr>';
    html += '<th style="width:82px;white-space:nowrap;">客戶代碼</th>';
    html += '<th style="min-width:110px;">客戶名稱</th>';
    html += '<th style="width:30px;text-align:center;">等級</th>';
    html += '<th style="min-width:90px;">產業別</th>';
    html += '<th style="min-width:100px;white-space:nowrap;">主要業務 / 代理業務</th>';
    html += '<th style="width:95px;">電話</th>';
    html += '<th style="min-width:90px;">地址</th>';
    html += '<th style="min-width:80px;">出貨要求</th>';
    html += '<th style="width:70px;white-space:nowrap;">結帳日</th>';
    html += '<th style="width:50px;text-align:center;">狀態</th>';
    if (CAN_SEE_DESIGN) html += '<th style="min-width:120px;">設計備註</th>';
    if (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS) html += '<th style="text-align:center;width:90px;">操作</th>';
    html += '</tr></thead><tbody>';
    if (!rows.length) {
        html += '<tr><td colspan="'+cols+'"><div class="empty-state"><i class="fa fa-users"></i>查無資料</div></td></tr>';
    } else {
        rows.forEach(function(r) {
            var badge = (r.is_inactive=='1')
                ? '<span class="badge-type badge-inactive" style="font-size:10px;padding:1px 5px;">停用</span>'
                : '<span class="badge-type badge-active" style="font-size:10px;padding:1px 5px;">有效</span>';
            var settle = settleModeLabel[r.settlement_mode||'FIXED']||'—';
            if (r.settlement_mode==='FIXED'&&r.settlement_day) settle += ' '+r.settlement_day+'日';
            var gradeStyle = {S:'background:#7b1fa2;',A:'background:#1565c0;',B:'background:#1ABB9C;',C:'background:#f39c12;',D:'background:#aaa;'};
            // Industry tags with note tooltip
            var indHtml = '';
            if (r.industries && r.industries.length) {
                r.industries.forEach(function(i){
                    var tip = i.industry_note ? ' title="'+escAttr(i.industry_note)+'"' : '';
                    indHtml += '<span'+tip+' style="display:inline-block;background:#e8f5f2;color:var(--accent);border-radius:6px;padding:0 5px;font-size:10px;font-weight:600;margin:1px;cursor:default;">'+escHtml(i.industry_name||i)+'</span>';
                    if (i.industry_note) indHtml += '<small style="color:#aaa;font-size:10px;display:block;margin-left:2px;">'+escHtml(i.industry_note.substring(0,20))+(i.industry_note.length>20?'…':'')+'</small>';
                });
            } else { indHtml = '<span style="color:#ddd;font-size:11px;">—</span>'; }
            html += '<tr>';
            html += '<td><code style="background:#f0f4f8;border-radius:3px;padding:1px 5px;font-weight:700;font-size:11px;color:var(--primary);">'+escHtml(r.customer_id)+'</code></td>';
            var ownBadge = (r.is_own_company=='1'||r.is_own_company===1) ? '<span style="display:inline-block;background:#e67e22;color:#fff;border-radius:4px;font-size:9px;font-weight:700;padding:1px 5px;margin-left:4px;vertical-align:middle;">本公司</span>' : '';
            html += '<td><strong style="font-size:12px;">'+escHtml(r.customer)+'</strong>'+ownBadge+'</td>';
            html += '<td style="text-align:center;">'+(r.customer_grade?'<span style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;color:#fff;font-size:10px;font-weight:700;'+(gradeStyle[r.customer_grade]||'background:#eee;')+'">'+escHtml(r.customer_grade)+'</span>':'<span style="color:#ddd;">—</span>')+'</td>';
            html += '<td>'+indHtml+'</td>';
            var _spri = r.sales_primary ? escHtml(r.sales_primary) : '';
            var _sdep = r.sales_deputy  ? escHtml(r.sales_deputy)  : '';
            var _salesHtml = _spri && _sdep
                ? '<span style="color:#555;">'+_spri+'</span> <span style="color:#bbb;font-size:10px;">/</span> <span style="color:#999;font-size:11px;">'+_sdep+'</span>'
                : (_spri ? '<span style="color:#555;">'+_spri+'</span>' : (_sdep ? '<span style="color:#999;font-size:11px;">/ '+_sdep+'</span>' : '<span style="color:#ddd;">—</span>'));
            html += '<td style="white-space:nowrap;">'+_salesHtml+'</td>';
            html += '<td style="color:#555;white-space:nowrap;">'+(escHtml(r.customer_tel)||'<span style="color:#ddd;">—</span>')+'</td>';
            var _addr = r.customer_address || '';
            var _addrShort = _truncAddr(_addr);
            var _addrCell = _addr
                ? '<span style="cursor:pointer;color:#555;border-bottom:1px dashed #bbb;" onclick="showAddrPopup(\''+escAttr(_addr)+'\')" title="點擊查看完整地址">'+escHtml(_addrShort)+'</span>'
                : '<span style="color:#ddd;">—</span>';
            html += '<td style="white-space:nowrap;">'+_addrCell+'</td>';
            var _sreq = r.shipping_req || '';
            var _sreqTrunc = _sreq.length > 18;
            var _sreqShort = _sreqTrunc ? _sreq.substring(0, 18) + '…' : _sreq;
            var _sreqClick = _sreqTrunc ? ' style="font-size:11px;color:#555;cursor:pointer;border-bottom:1px dashed #bbb;" onclick="showTextPopup(\'出貨要求\',\''+escAttr(_sreq)+'\')"' : ' style="font-size:11px;color:#555;"';
            html += '<td'+_sreqClick+'>'+(_sreqShort ? escHtml(_sreqShort) : '<span style="color:#ddd;">—</span>')+'</td>';
            html += '<td style="white-space:nowrap;">'+escHtml(settle)+'</td>';
            html += '<td style="text-align:center;">'+badge+'</td>';
            if (CAN_SEE_DESIGN) {
                var dn = r.design_note;
                if (dn && dn.first_text) {
                    var dnHasMore = dn.first_text.length > 80 || dn.count > 1 || dn.has_images;
                    var dnExtra = '';
                    if (dn.has_images) dnExtra += '<i class="fa fa-picture-o" style="color:#3498db;margin-right:3px;" title="含圖片"></i>';
                    if (dn.count > 1)  dnExtra += '<span style="font-size:10px;color:#aaa;">共'+dn.count+'則</span>';
                    html += '<td style="font-size:11px;color:#555;max-width:160px;cursor:pointer;" onclick="openCustDesignModal(\''+escAttr(r.customer_id)+'\',\''+escAttr(r.customer)+'\')">';
                    html += '<div style="display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;white-space:pre-wrap;word-break:break-word;">'+escHtml(dn.first_text)+'</div>';
                    html += '<div style="display:flex;align-items:center;gap:4px;margin-top:2px;">'+dnExtra+(dnHasMore?'<span style="color:#3498db;font-size:10px;font-weight:700;">＋</span>':'')+'</div>';
                    html += '</td>';
                } else {
                    html += '<td style="color:#bbb;font-size:11px;">無備註</td>';
                }
            }
            if (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS||CAN_SEE_DESIGN) {
                html += '<td><div class="row-actions">';
                if (CAN_UPDATE) html += '<button class="btn-row btn-edit" onclick="openCustomerModal(\''+escAttr(r.customer_id)+'\')" title="編輯"><i class="fa fa-pencil"></i></button>';
                if (CAN_SEE_DESIGN) html += '<button class="btn-row" onclick="openCustDesignModal(\''+escAttr(r.customer_id)+'\',\''+escAttr(r.customer)+'\')" title="設計備註" style="color:#c0392b;font-size:11px;font-weight:600;padding:1px 5px;"><i class="fa fa-file-text-o"></i> 設計</button>';
                if (CAN_SET_STATUS) { var isInact=(r.is_inactive=='1'); html += '<button class="btn-row" onclick="toggleCustomerStatus(\''+escAttr(r.customer_id)+'\','+isInact+')" title="'+(isInact?'啟用':'停用')+'" style="color:'+(isInact?'#1ABB9C':'#e74c3c')+'"><i class="fa fa-toggle-'+(isInact?'on':'off')+'"></i></button>'; }
                if (CAN_DELETE_ALL) html += '<button class="btn-row btn-delete" onclick="deleteCustomer(\''+escAttr(r.customer_id)+'\',\''+escAttr(r.customer)+'\')" title="刪除"><i class="fa fa-trash"></i></button>';
                html += '</div></td>';
            }
            html += '</tr>';
        });
    }
    var pgHtml = paginationHTML(total, pg, pages, 'loadCustomers');
    document.getElementById('customers-table-wrap').innerHTML = pgHtml + html + '</tbody></table></div>';
}

// Load industry list (cached)
function loadIndustryList(callback) {
    if (industryCache) { callback(industryCache); return; }
    api({ action:'get_industry_list' }).done(function(r) {
        if (r.success) { industryCache = r.data; callback(r.data); }
        else callback([]);
    });
}

function renderIndustryCheckboxes(allIndustries, selectedIds, selectedSubData, selectedIndustriesData) {
    selectedSubData = selectedSubData || [];
    selectedIndustriesData = selectedIndustriesData || [];
    var chipsWrap = document.getElementById('cf-industry-chips');
    if (!chipsWrap) return;
    chipsWrap.innerHTML = '';
    if (!allIndustries.length) {
        chipsWrap.innerHTML = '<span style="color:#aaa;font-size:12px;">無產業別資料</span>'; return;
    }
    // normalise selectedIds：支援舊格式（純數字陣列）
    var selIds = [];
    if (Array.isArray(selectedIds)) {
        selectedIds.forEach(function(v){
            if (typeof v === 'object' && v !== null && v.industry_id !== undefined) selIds.push(parseInt(v.industry_id));
            else if (!isNaN(parseInt(v))) selIds.push(parseInt(v));
        });
    }
    allIndustries.forEach(function(ind) {
        var sel = selIds.indexOf(parseInt(ind.industry_id)) >= 0;
        var chip = document.createElement('span');
        chip.className = 'industry-tag';
        chip.dataset.id = ind.industry_id;
        chip.dataset.subTypes = JSON.stringify(ind.sub_types || []);
        chip.style.cssText = 'display:inline-flex;align-items:center;gap:4px;border-radius:16px;padding:3px 10px;cursor:pointer;font-size:12px;font-weight:600;transition:all .15s;'
            + (sel ? 'background:var(--accent);color:#fff;' : 'background:#f0f0f0;color:#555;');
        chip.innerHTML = '<input type="checkbox" '+(sel?'checked':'')+' style="display:none;" value="'+ind.industry_id+'">'
            + escHtml(ind.industry_name);
        chip.onclick = function(){ toggleIndustryTag(this, ind.industry_id); };
        chipsWrap.appendChild(chip);
    });
    renderIndustryMainNoteRows(selectedIndustriesData);
    renderIndustrySubSection(selectedSubData);
}

function toggleIndustryTag(el, id) {
    var cb = el.querySelector('input');
    cb.checked = !cb.checked;
    el.style.background = cb.checked ? 'var(--accent)' : '#f0f0f0';
    el.style.color      = cb.checked ? '#fff' : '#555';
    renderIndustryMainNoteRows([]);
    var existingSubs = collectCurrentSubs();
    renderIndustrySubSection(existingSubs);
}

function collectCurrentSubs() {
    var subs = [];
    document.querySelectorAll('#cf-industry-sub-wrap .ind-sub-item').forEach(function(item){
        var note = item.querySelector('.ind-sub-note');
        subs.push({ sub_id: String(item.dataset.subId), note: note ? note.value.trim() : '' });
    });
    return subs;
}

function renderIndustrySubSection(existingSubData) {
    var wrap = document.getElementById('cf-industry-sub-wrap');
    if (!wrap) return;
    var selChips = document.querySelectorAll('#cf-industry-chips .industry-tag input:checked');
    if (!selChips.length) { wrap.innerHTML = ''; syncIndSubsHidden(); return; }
    wrap.innerHTML = '';
    var subMap = {};
    (existingSubData||[]).forEach(function(s){ subMap[String(s.sub_id)] = s.note || ''; });
    selChips.forEach(function(cb) {
        var chip = cb.parentElement;
        var subTypes = chip.dataset.subTypes ? JSON.parse(chip.dataset.subTypes) : [];
        if (!subTypes.length) return;
        var indName = chip.textContent.trim();
        var sec = document.createElement('div');
        sec.style.cssText = 'margin-bottom:8px;padding:6px 8px;background:#f8f9fb;border-radius:6px;border-left:3px solid var(--accent);';
        var chipsHtml = '<div style="font-size:11px;color:var(--accent);font-weight:700;margin-bottom:5px;">'+escHtml(indName)+' — 小類</div>';
        chipsHtml += '<div class="ind-sub-chips-row" style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:4px;">';
        subTypes.forEach(function(s){
            var isSel = subMap.hasOwnProperty(String(s.sub_id));
            chipsHtml += '<span class="ind-sub-chip" data-sub-id="'+s.sub_id+'" data-sub-name="'+escAttr(s.sub_name)+'"'
                + ' onclick="toggleIndSubChip(this)"'
                + ' style="display:inline-block;padding:2px 9px;border-radius:10px;font-size:11px;font-weight:600;cursor:pointer;'
                + (isSel?'background:var(--accent);color:#fff;':'background:#e8f5f2;color:var(--accent);border:1px solid var(--accent)44;')+'">'+escHtml(s.sub_name)+'</span>';
        });
        chipsHtml += '</div><div class="ind-sub-notes-area">';
        subTypes.forEach(function(s){
            if (!subMap.hasOwnProperty(String(s.sub_id))) return;
            chipsHtml += '<div class="ind-sub-item" data-sub-id="'+s.sub_id+'" style="display:flex;align-items:center;gap:6px;margin-top:3px;">'
                + '<span style="font-size:11px;color:#888;min-width:60px;">'+escHtml(s.sub_name)+'：</span>'
                + '<input type="text" class="form-control input-sm ind-sub-note" placeholder="備註（選填）" maxlength="100" value="'+escAttr(subMap[String(s.sub_id)])+'" oninput="syncIndSubsHidden()"></div>';
        });
        chipsHtml += '</div>';
        sec.innerHTML = chipsHtml;
        wrap.appendChild(sec);
    });
    syncIndSubsHidden();
}

function toggleIndSubChip(el) {
    var isSel = el.style.color === 'rgb(255, 255, 255)';
    var subId   = el.dataset.subId;
    var subName = el.dataset.subName || el.textContent.trim();
    if (isSel) {
        el.style.cssText = 'display:inline-block;padding:2px 9px;border-radius:10px;font-size:11px;font-weight:600;cursor:pointer;background:#e8f5f2;color:var(--accent);border:1px solid var(--accent)44;';
        var notesArea = el.closest('div').nextElementSibling;
        if (notesArea && notesArea.classList.contains('ind-sub-notes-area')) {
            var item = notesArea.querySelector('.ind-sub-item[data-sub-id="'+subId+'"]');
            if (item) item.remove();
        }
    } else {
        el.style.cssText = 'display:inline-block;padding:2px 9px;border-radius:10px;font-size:11px;font-weight:600;cursor:pointer;background:var(--accent);color:#fff;';
        var notesArea = el.closest('div').nextElementSibling;
        if (notesArea && notesArea.classList.contains('ind-sub-notes-area')) {
            var noteRow = document.createElement('div');
            noteRow.className = 'ind-sub-item';
            noteRow.dataset.subId = subId;
            noteRow.style.cssText = 'display:flex;align-items:center;gap:6px;margin-top:3px;';
            noteRow.innerHTML = '<span style="font-size:11px;color:#888;min-width:60px;">'+escHtml(subName)+'：</span>'
                + '<input type="text" class="form-control input-sm ind-sub-note" placeholder="備註（選填）" maxlength="100" value="" oninput="syncIndSubsHidden()">';
            notesArea.appendChild(noteRow);
        }
    }
    syncIndSubsHidden();
}

function renderIndustryMainNoteRows(existingNotes) {
    // existingNotes: [{industry_id, industry_note}, ...] or [] from get_customer
    existingNotes = existingNotes || [];
    var noteMap = {};
    existingNotes.forEach(function(n){ noteMap[String(n.industry_id)] = n.industry_note || ''; });

    var wrap = document.getElementById('cf-industry-main-notes-wrap');
    if (!wrap) return;
    var selChips = document.querySelectorAll('#cf-industry-chips .industry-tag input:checked');
    if (!selChips.length) { wrap.innerHTML = ''; syncIndustriesHidden(); return; }

    // 保留已有的輸入值（切換 chip 時不清空）
    var curValues = {};
    wrap.querySelectorAll('.ind-main-note-item').forEach(function(item){
        var inp = item.querySelector('.ind-main-note-input');
        if (inp) curValues[item.dataset.industryId] = inp.value;
    });

    var html = '';
    selChips.forEach(function(cb){
        var iid = String(cb.value);
        var chip = cb.closest('.industry-tag');
        var name = chip ? chip.textContent.trim() : iid;
        var val = (curValues[iid] !== undefined) ? curValues[iid]
                 : (noteMap[iid] !== undefined ? noteMap[iid] : '');
        html += '<div class="ind-main-note-item" data-industry-id="'+iid+'" style="display:flex;align-items:center;gap:6px;margin-top:4px;">'
            + '<span style="font-size:11px;color:var(--accent);font-weight:600;min-width:72px;">'+escHtml(name)+'備註：</span>'
            + '<input type="text" class="form-control input-sm ind-main-note-input" placeholder="此產業別備註（選填）" maxlength="200" value="'+escAttr(val)+'" oninput="syncIndustriesHidden()">'
            + '</div>';
    });
    wrap.innerHTML = html;
    syncIndustriesHidden();
}

function syncIndustriesHidden() {
    var result = [];
    document.querySelectorAll('#cf-industry-chips .industry-tag input:checked').forEach(function(cb){
        var iid = parseInt(cb.value);
        var noteEl = document.querySelector('#cf-industry-main-notes-wrap .ind-main-note-item[data-industry-id="'+cb.value+'"] .ind-main-note-input');
        var note = noteEl ? noteEl.value.trim() : '';
        result.push({ id: iid, note: note });
    });
    var el = document.getElementById('cf-industries');
    if (el) el.value = JSON.stringify(result);
}

// Legacy alias
function syncIndustryHidden() { syncIndustriesHidden(); }

function syncIndSubsHidden() {
    var subs = [];
    document.querySelectorAll('#cf-industry-sub-wrap .ind-sub-item').forEach(function(item){
        var note = item.querySelector('.ind-sub-note');
        subs.push({ sub_id: item.dataset.subId, note: note ? note.value.trim() : '' });
    });
    var el = document.getElementById('cf-industry-subs');
    if (el) el.value = JSON.stringify(subs);
}

// Settlement mode logic
// ── Customer Contacts ──────────────────────────────────
function addContactRow(c) {
    c = c || {};
    var wrap = document.getElementById('cf-contacts-wrap');
    if (!wrap) return;
    var idx = wrap.querySelectorAll('.contact-row').length;
    var row = document.createElement('div');
    row.className = 'contact-row';
    row.style.cssText = 'display:flex;gap:5px;align-items:center;padding:5px 0;border-bottom:1px solid #f0f2f5;flex-wrap:wrap;margin-bottom:2px;';
    var isPrimary = (c.is_primary==1||idx===0) ? 'checked' : '';
    row.innerHTML =
        '<div style="flex-shrink:0;text-align:center;"><div style="font-size:10px;color:#aaa;">主要</div>'
        + '<input type="radio" name="contact_primary" value="'+idx+'" '+isPrimary+' onchange="syncContactsHidden()"></div>'
        + '<input type="text" class="form-control input-sm ct-name"       style="flex:1.5;min-width:70px;"  placeholder="姓名*"  maxlength="50"  value="'+escAttr(c.name||'')+'">'
        + '<input type="text" class="form-control input-sm ct-dept"       style="flex:1;min-width:60px;"    placeholder="部門"   maxlength="50"  value="'+escAttr(c.department||'')+'">'
        + '<input type="text" class="form-control input-sm ct-title"      style="flex:1;min-width:60px;"    placeholder="職稱"   maxlength="50"  value="'+escAttr(c.title||'')+'">'
        + '<input type="text" class="form-control input-sm ct-ext"        style="width:60px;"               placeholder="分機"   maxlength="20"  value="'+escAttr(c.phone_ext||'')+'">'
        + '<input type="text" class="form-control input-sm ct-mobile"     style="flex:1;min-width:85px;"    placeholder="手機"   maxlength="30"  value="'+escAttr(c.mobile||'')+'">'
        + '<input type="text" class="form-control input-sm ct-email"      style="flex:1.5;min-width:100px;" placeholder="Email"  maxlength="100" value="'+escAttr(c.email||'')+'">'
        + '<input type="text" class="form-control input-sm ct-note"       style="flex:1.2;min-width:80px;"  placeholder="備註"   maxlength="100" value="'+escAttr(c.note||'')+'">'
        + '<button type="button" class="btn btn-xs btn-default" style="flex-shrink:0;" onclick="this.closest(\'.contact-row\').remove();syncContactsHidden();"><i class="fa fa-times"></i></button>';
    wrap.appendChild(row);
    row.querySelectorAll('input[type=text]').forEach(function(i){ i.oninput = syncContactsHidden; });
}

function syncContactsHidden() {
    var rows = document.querySelectorAll('#cf-contacts-wrap .contact-row');
    var primaryEl = document.querySelector('input[name=contact_primary]:checked');
    var primaryIdx = primaryEl ? parseInt(primaryEl.value) : 0;
    var contacts = [];
    rows.forEach(function(row, i) {
        var name = row.querySelector('.ct-name').value.trim();
        if (!name) return;
        contacts.push({
            name:       name,
            department: (row.querySelector('.ct-dept')||{value:''}).value.trim(),
            title:      row.querySelector('.ct-title').value.trim(),
            phone_ext:  row.querySelector('.ct-ext').value.trim(),
            mobile:     row.querySelector('.ct-mobile').value.trim(),
            email:      row.querySelector('.ct-email').value.trim(),
            note:       (row.querySelector('.ct-note')||{value:''}).value.trim(),
            is_primary: (i===primaryIdx) ? 1 : 0
        });
    });
    var el = document.getElementById('cf-contacts');
    if (el) el.value = JSON.stringify(contacts);
}

function switchCustTab(name, el) {
    ['basic','payment','contacts','notes'].forEach(function(n){
        var p = document.getElementById('cust-tab-'+n);
        if (p) p.classList.remove('active');
    });
    document.querySelectorAll('#custModalTabs li').forEach(function(li){ li.classList.remove('active'); });
    var pane = document.getElementById('cust-tab-'+name);
    if (pane) pane.classList.add('active');
    if (el) {
        var li = el.closest ? el.closest('li') : el.parentNode;
        if (li) li.classList.add('active');
    }
}

// ── 業務設定 ──────────────────────────────────────────
var _salesUsersCache = null;

function loadSalesUsers(callback) {
    if (_salesUsersCache) { callback(_salesUsersCache); return; }
    api({ action:'get_sales_users' }).done(function(r) {
        if (r.success) { _salesUsersCache = r.data; callback(r.data); }
        else { callback([]); }
    });
}

function populateSalesSelects(primaryId, deputyId) {
    // Always reload fresh (dept grouping needs latest data)
    _salesUsersCache = null;
    loadSalesUsers(function(users) {
        ['cf-primary_user_id','cf-deputy_user_id'].forEach(function(id) {
            var sel = document.getElementById(id);
            if (!sel) return;
            var cur = (id === 'cf-primary_user_id') ? primaryId : deputyId;
            sel.innerHTML = '<option value="">— 請選擇 —</option>';
            var curDept = '';
            var curOg   = null;
            users.forEach(function(u) {
                if (u.dept_name && u.dept_name !== curDept) {
                    curOg = document.createElement('optgroup');
                    curOg.label = u.dept_name;
                    sel.appendChild(curOg);
                    curDept = u.dept_name;
                }
                var label = u.name + (u.position_name ? '（'+u.position_name+'）' : '');
                var opt = new Option(label, u.id);
                if (curOg) curOg.appendChild(opt);
                else sel.appendChild(opt);
            });
            if (cur) sel.value = cur;
        });
    });
}

function saveCustSales() {
    var cid = document.getElementById('cf-customer_id').value;
    if (!cid) { showToast('請先確認客戶代碼','error'); return; }
    var puid = document.getElementById('cf-primary_user_id').value;
    var duid = document.getElementById('cf-deputy_user_id').value;
    if (puid && duid && puid === duid) { showToast('主要業務與代理業務不可為同一人','error'); return; }
    api({ action:'save_customer_sales', customer_id:cid, primary_user_id:puid, deputy_user_id:duid }).done(function(r) {
        if (r.success) showToast(r.message,'success');
        else showToast(r.message,'error');
    });
}

function loadContactRows(list) {
    var wrap = document.getElementById('cf-contacts-wrap');
    if (!wrap) return;
    wrap.innerHTML = '';
    if (!list || !list.length) { addContactRow(); return; }
    list.forEach(function(c){ addContactRow(c); });
}

// ── 廠商聯絡人（多筆）─────────────────────────────────
function addMakerContactRow(c) {
    c = c || {};
    var wrap = document.getElementById('mf-contacts-wrap');
    if (!wrap) return;
    var idx = wrap.querySelectorAll('.maker-contact-row').length;
    var row = document.createElement('div');
    row.className = 'maker-contact-row';
    row.style.cssText = 'display:flex;gap:5px;align-items:center;padding:5px 0;border-bottom:1px solid #f0f2f5;flex-wrap:wrap;margin-bottom:2px;';
    var isPrimary = (c.is_primary==1||idx===0) ? 'checked' : '';
    row.innerHTML =
        '<div style="flex-shrink:0;text-align:center;"><div style="font-size:10px;color:#aaa;">主要</div>'
        + '<input type="radio" name="maker_contact_primary" value="'+idx+'" '+isPrimary+' onchange="syncMakerContactsHidden()"></div>'
        + '<input type="text" class="form-control input-sm mct-name"   style="flex:1.5;min-width:70px;"  placeholder="姓名*"  maxlength="50"  value="'+escAttr(c.name||'')+'">'
        + '<input type="text" class="form-control input-sm mct-dept"   style="flex:1;min-width:60px;"    placeholder="部門"   maxlength="50"  value="'+escAttr(c.department||'')+'">'
        + '<input type="text" class="form-control input-sm mct-title"  style="flex:1;min-width:60px;"    placeholder="職稱"   maxlength="50"  value="'+escAttr(c.title||'')+'">'
        + '<input type="text" class="form-control input-sm mct-ext"    style="width:60px;"               placeholder="分機"   maxlength="20"  value="'+escAttr(c.phone_ext||'')+'">'
        + '<input type="text" class="form-control input-sm mct-mobile" style="flex:1;min-width:85px;"    placeholder="手機"   maxlength="30"  value="'+escAttr(c.mobile||'')+'">'
        + '<input type="text" class="form-control input-sm mct-email"  style="flex:1.5;min-width:100px;" placeholder="Email"  maxlength="100" value="'+escAttr(c.email||'')+'">'
        + '<input type="text" class="form-control input-sm mct-note"   style="flex:1.2;min-width:80px;"  placeholder="備註"   maxlength="100" value="'+escAttr(c.note||'')+'">'
        + '<button type="button" class="btn btn-xs btn-default" style="flex-shrink:0;" onclick="this.closest(\'.maker-contact-row\').remove();syncMakerContactsHidden();"><i class="fa fa-times"></i></button>';
    wrap.appendChild(row);
    row.querySelectorAll('input[type=text]').forEach(function(i){ i.oninput = syncMakerContactsHidden; });
}

function syncMakerContactsHidden() {
    var rows = document.querySelectorAll('#mf-contacts-wrap .maker-contact-row');
    var primaryEl = document.querySelector('input[name=maker_contact_primary]:checked');
    var primaryIdx = primaryEl ? parseInt(primaryEl.value) : 0;
    var contacts = [];
    rows.forEach(function(row, i) {
        var name = row.querySelector('.mct-name').value.trim();
        if (!name) return;
        contacts.push({
            name:       name,
            department: (row.querySelector('.mct-dept')||{value:''}).value.trim(),
            title:      row.querySelector('.mct-title').value.trim(),
            phone_ext:  row.querySelector('.mct-ext').value.trim(),
            mobile:     row.querySelector('.mct-mobile').value.trim(),
            email:      row.querySelector('.mct-email').value.trim(),
            note:       row.querySelector('.mct-note').value.trim(),
            is_primary: (i===primaryIdx) ? 1 : 0
        });
    });
    var el = document.getElementById('mf-maker-contacts');
    if (el) el.value = JSON.stringify(contacts);
    // 同步主要聯絡人到 hidden 相容欄位
    var primary = contacts.find(function(c){ return c.is_primary; }) || contacts[0] || {};
    var cp = document.getElementById('mf-contact_person');  if (cp) cp.value = primary.name  || '';
    var ct = document.getElementById('mf-contact_title');   if (ct) ct.value = primary.title || '';
    var em = document.getElementById('mf-email');           if (em) em.value = primary.email || '';
}

function loadMakerContactRows(list) {
    var wrap = document.getElementById('mf-contacts-wrap');
    if (!wrap) return;
    wrap.innerHTML = '';
    if (!list || !list.length) { addMakerContactRow(); return; }
    list.forEach(function(c){ addMakerContactRow(c); });
    syncMakerContactsHidden();
}

function onSettlementModeChange(val) {
    var dg = document.getElementById('cf-day-group');
    var exBtn = document.getElementById('cf-exception-btn');
    dg.style.display = (val==='FIXED') ? '' : 'none';
    if (exBtn) exBtn.style.display = (val!=='VARIABLE') ? '' : 'none';
    updateSettlementDayHint();
}

function updateSettlementDayHint() {
    var day = parseInt(document.getElementById('cf-settlement_day').value||0);
    var hint = document.getElementById('cf-day-hint');
    if (day >= 29) hint.innerHTML = '<span style="color:#e67e22;"><i class="fa fa-info-circle"></i> 遇2月或小月將自動調整為該月最後一天</span>';
    else hint.textContent = '';
}
function _applyCustPaymentDefaultHints(mode, day, pay, nd, dbConfirmSettle, dbConfirmPay) {
    var settleSame = (mode === SYS_CUST_DEFAULT_SETTLEMENT_MODE &&
        (mode !== 'FIXED' || String(day||'') === String(SYS_CUST_DEFAULT_SETTLEMENT_DAY||'')));
    var paySame = (pay === SYS_CUST_DEFAULT_PAYMENT_METHOD &&
        String(nd||'') === String(SYS_CUST_DEFAULT_NET_DAYS||''));
    var sh = document.getElementById('cf-settlement-default-hint');
    var ph = document.getElementById('cf-payment-default-hint');
    var cs = document.getElementById('cf-confirmed_settlement');
    var cp = document.getElementById('cf-confirmed_payment');
    if (sh) sh.style.display = settleSame ? '' : 'none';
    if (ph) ph.style.display = paySame    ? '' : 'none';
    if (cs) cs.checked = settleSame ? (dbConfirmSettle==1) : true;
    if (cp) cp.checked = paySame    ? (dbConfirmPay==1)    : true;
}

// Settlement exception modal
var currentSettleCustId = '';
function openSettlementExceptionModal() {
    currentSettleCustId = document.getElementById('cf-customer_id').value;
    if (!currentSettleCustId) { showToast('請先確認客戶代碼','error'); return; }
    document.getElementById('sex-ym').value = '';
    document.getElementById('sex-date').value = '';
    document.getElementById('sex-reason').value = '';
    renderSettlementExList();
    $('#settlementExModal').modal('show');
}

function renderSettlementExList() {
    api({ action:'get_customer', customer_id:currentSettleCustId }).done(function(r) {
        var wrap = document.getElementById('sex-list-wrap');
        if (!r.success || !r.data.settlement_exceptions || !r.data.settlement_exceptions.length) {
            wrap.innerHTML = '<p style="color:#aaa;font-size:12px;">尚無結帳例外設定</p>';
            return;
        }
        var html = '<table class="table table-condensed" style="font-size:12px;"><thead><tr><th>年月</th><th>調整日</th><th>原因</th><th></th></tr></thead><tbody>';
        r.data.settlement_exceptions.forEach(function(ex) {
            html += '<tr><td>'+escHtml(ex.target_year_month)+'</td><td>'+escHtml(ex.adjusted_date)+'</td><td>'+escHtml(ex.reason||'')+'</td>';
            if (CAN_DELETE) html += '<td><button class="btn-row btn-delete" onclick="deleteSettlementEx('+ex.exception_id+')" title="刪除"><i class="fa fa-trash"></i></button></td>';
            html += '</tr>';
        });
        html += '</tbody></table>';
        wrap.innerHTML = html;
    });
}

function submitSettlementException() {
    var ym   = document.getElementById('sex-ym').value;
    var date = document.getElementById('sex-date').value;
    var reason = document.getElementById('sex-reason').value;
    if (!ym||!date) { showToast('請填寫年月與調整日期','error'); return; }
    api({ action:'save_settlement_exception', customer_id:currentSettleCustId,
          target_year_month:ym, adjusted_date:date, reason:reason
    }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); renderSettlementExList(); }
        else showToast(r.message,'error');
    });
}

function deleteSettlementEx(eid) {
    if (!confirmDeleteY('確定刪除此結帳例外？')) return;
    api({ action:'delete_settlement_exception', exception_id:eid }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); renderSettlementExList(); }
        else showToast(r.message,'error');
    });
}

function openCustomerModal(customer_id) {
    if (customer_id) {
        if (!CAN_UPDATE) { showToast('無修改權限','error'); return; }
        api({ action:'get_customer', customer_id:customer_id }).done(function(r) {
            if (!r.success) { showToast(r.message,'error'); return; }
            var d = r.data;
            document.getElementById('custModal-title').textContent = '編輯客戶';
            document.getElementById('cf-is_new').value = '0';
            var cidEl = document.getElementById('cf-customer_id');
            cidEl.value = d.customer_id; cidEl.readOnly = true; cidEl.style.background = '#f5f5f5';
            // Basic fields
            ['customer','customer_full','customer_tel','customer_fax','customer_address','tax_id',
             'quote_method','payment_method','net_days','bank_name','bank_branch','bank_account',
             'billing_contact','invoice_email'].forEach(function(f){
                var el = document.getElementById('cf-'+f);
                if (el) el.value = d[f]||'';
            });
            ['shipping_req','billing_note','general_note'].forEach(function(f){
                var el = document.getElementById('cf-'+f);
                if (el) el.value = d[f]||'';
            });
            document.getElementById('cf-is_inactive').checked    = (d.is_inactive=='1');
            document.getElementById('cf-is_own_company').checked = (d.is_own_company=='1' || d.is_own_company===1);
            var ad = document.getElementById('cf-allow_deduct');
            if (ad) ad.checked = (d.allow_deduct==1||d.allow_deduct=='1');
            // Grade
            var gsel = document.getElementById('cf-customer_grade');
            if (gsel) gsel.value = d.customer_grade||'';
            // Sales assignment
            var puid = '', duid = '';
            (d.sales||[]).forEach(function(s){ if(s.role==='primary') puid=s.user_id; if(s.role==='deputy') duid=s.user_id; });
            populateSalesSelects(puid, duid);
            // Settlement
            var mode = d.settlement_mode||'FIXED';
            document.getElementById('cf-settlement_mode').value = mode;
            document.getElementById('cf-settlement_day').value  = d.settlement_day||'25';
            onSettlementModeChange(mode);
            updateSettlementDayHint();
            var cDay = d.settlement_day||'25';
            var cPay = d.payment_method||'匯款';
            var cNd  = (d.net_days !== null && d.net_days !== undefined && d.net_days !== '') ? String(d.net_days) : '';
            _applyCustPaymentDefaultHints(mode, cDay, cPay, cNd, d.confirmed_settlement, d.confirmed_payment);
            var exBtn = document.getElementById('cf-exception-btn');
            if (exBtn) exBtn.style.display = '';
            // Contacts
            loadContactRows(d.contacts||[]);
            // Industries
            var selIndustries = d.industries || [];
            var selSubs = d.industry_subs || [];
            // 提取 industry_id 陣列（for chip 選取狀態）
            var selIndustryIds = selIndustries.map(function(i){ return parseInt(i.industry_id||i); });
            loadIndustryList(function(list){ renderIndustryCheckboxes(list, selIndustryIds, selSubs, selIndustries); });
            // 設計備註（有權限時顯示並載入）
            var cdWrap = document.getElementById('cust-design-note-wrap');
            if (cdWrap) { cdWrap.style.display = ''; }
            _designTarget = { type:'customer', id: d.customer_id };
            loadDesignNotes('customer', d.customer_id);
            // Reset to first tab
            switchCustTab('basic', document.querySelector('#custModalTabs li:first-child a'));
            $('#customerModal').modal('show');
        });
    } else {
        if (!CAN_CREATE) { showToast('無新增權限','error'); return; }
        document.getElementById('custModal-title').textContent = '新增客戶';
        document.getElementById('customerForm').reset();
        document.getElementById('cf-is_new').value = '1';
        var cidEl = document.getElementById('cf-customer_id');
        cidEl.readOnly = false; cidEl.style.background = '';
        document.getElementById('cf-settlement_mode').value = SYS_CUST_DEFAULT_SETTLEMENT_MODE || 'FIXED';
        document.getElementById('cf-settlement_day').value   = SYS_CUST_DEFAULT_SETTLEMENT_DAY  || '25';
        document.getElementById('cf-payment_method').value   = SYS_CUST_DEFAULT_PAYMENT_METHOD  || '匯款';
        document.getElementById('cf-net_days').value         = SYS_CUST_DEFAULT_NET_DAYS || '';
        onSettlementModeChange(SYS_CUST_DEFAULT_SETTLEMENT_MODE || 'FIXED');
        _applyCustPaymentDefaultHints(SYS_CUST_DEFAULT_SETTLEMENT_MODE, SYS_CUST_DEFAULT_SETTLEMENT_DAY, SYS_CUST_DEFAULT_PAYMENT_METHOD, SYS_CUST_DEFAULT_NET_DAYS, 0, 0);
        var exBtn = document.getElementById('cf-exception-btn');
        if (exBtn) exBtn.style.display = 'none';
        var ad = document.getElementById('cf-allow_deduct');
        if (ad) ad.checked = false;
        var gsel = document.getElementById('cf-customer_grade');
        if (gsel) gsel.value = '';
        populateSalesSelects('','');
        loadContactRows([]);
        var mainNotesWrap = document.getElementById('cf-industry-main-notes-wrap');
        if (mainNotesWrap) mainNotesWrap.innerHTML = '';
        loadIndustryList(function(list){ renderIndustryCheckboxes(list, [], [], []); });
        // 新增客戶時隱藏設計備註區塊
        var cdWrap = document.getElementById('cust-design-note-wrap');
        if (cdWrap) { cdWrap.style.display = 'none'; }
        switchCustTab('basic', document.querySelector('#custModalTabs li:first-child a'));
        $('#customerModal').modal('show');
    }
}

function submitCustomerForm() {
    syncContactsHidden();
    var gv = function(id){ var e=document.getElementById(id); return e?e.value:''; };
    var gc = function(id){ var e=document.getElementById(id); return e&&e.checked?1:0; };
    var data = {
        action:           'save_customer',
        is_new:           gv('cf-is_new'),
        customer_id:      gv('cf-customer_id').toUpperCase().trim(),
        customer:         gv('cf-customer').trim(),
        customer_full:    gv('cf-customer_full').trim(),
        customer_grade:   gv('cf-customer_grade'),
        customer_tel:     gv('cf-customer_tel'),
        customer_fax:     gv('cf-customer_fax'),
        customer_address: gv('cf-customer_address'),
        is_inactive:      gc('cf-is_inactive'),
        settlement_mode:  gv('cf-settlement_mode'),
        settlement_day:   gv('cf-settlement_day'),
        industries:       gv('cf-industries'),
        industry_subs:    gv('cf-industry-subs'),
        // Extended
        tax_id:           gv('cf-tax_id'),
        quote_method:     gv('cf-quote_method'),
        payment_method:   gv('cf-payment_method'),
        net_days:         gv('cf-net_days'),
        allow_deduct:     gc('cf-allow_deduct'),
        bank_name:        gv('cf-bank_name'),
        bank_branch:      gv('cf-bank_branch'),
        bank_account:     gv('cf-bank_account'),
        billing_contact:  gv('cf-billing_contact'),
        shipping_req:     gv('cf-shipping_req'),
        invoice_email:    gv('cf-invoice_email'),
        billing_note:     gv('cf-billing_note'),
        general_note:     gv('cf-general_note'),
        contacts:             gv('cf-contacts'),
        primary_user_id:      gv('cf-primary_user_id'),
        deputy_user_id:       gv('cf-deputy_user_id'),
        confirmed_settlement: gc('cf-confirmed_settlement'),
        confirmed_payment:    gc('cf-confirmed_payment'),
        is_own_company:       gc('cf-is_own_company')
    };
    if (!data.customer_id) { showToast('客戶代碼不可為空','error'); return; }
    if (!data.customer)    { showToast('客戶名稱不可為空','error'); return; }
    if (data.settlement_mode==='FIXED' && (!data.settlement_day||data.settlement_day<1||data.settlement_day>31)) {
        showToast('固定日請輸入 1~31','error'); return;
    }
    if (data.primary_user_id && data.deputy_user_id && data.primary_user_id === data.deputy_user_id) {
        showToast('主要業務與代理業務不可為同一人','error'); return;
    }
    var btn = document.querySelector('#customerModal .btn-success');
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> 儲存中…'; }
    var restore = function(){ if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa fa-save"></i> 儲存'; } };
    apiOnce('save_customer', data,
        function(r) {
            restore();
            if (r.success) { showToast(r.message,'success'); $('#customerModal').modal('hide'); loadCustomers(customersCurrent); }
            else showToast(r.message,'error');
        },
        function(){ restore(); showToast('網路錯誤','error'); }
    );
}

// ── 客戶刪除 modal 狀態 ───────────────────────────────────
var _dcm_id = '', _dcm_name = '', _dcm_tgt_id = '';

function deleteCustomer(id, name) {
    _dcm_id = id; _dcm_name = name; _dcm_tgt_id = '';
    document.getElementById('dcm-title-name').textContent = name + '（' + id + '）';
    document.getElementById('dcm-loading').style.display = '';
    ['dcm-blocked','dcm-confirm','dcm-transfer'].forEach(function(s){ document.getElementById(s).style.display='none'; });
    document.getElementById('dcm-ok-input').value = '';
    document.getElementById('dcm-transfer-ok').value = '';
    document.getElementById('dcm-tgt-input').value = '';
    document.getElementById('dcm-tgt-info').textContent = '尚未選擇目標客戶';
    document.getElementById('dcm-tgt-info').style.color = '#aaa';
    document.getElementById('dcm-tgt-dd').style.display = 'none';
    $('#deleteCustModal').modal('show');
    api({ action:'check_customer_blocks', customer_id:id }).done(function(r) {
        document.getElementById('dcm-loading').style.display = 'none';
        if (!r.success) { showToast(r.message,'error'); return; }
        if (r.blocks && r.blocks.length) {
            var ul = document.getElementById('dcm-blocks-list');
            ul.innerHTML = r.blocks.map(function(b){ return '<li>'+escHtml(b)+'</li>'; }).join('');
            document.getElementById('dcm-blocked').style.display = '';
            document.getElementById('dcm-transfer-btn-wrap').style.display = CAN_DELETE_ALL ? '' : 'none';
            // 填來源客戶資訊
            var c = r.customer || {};
            document.getElementById('dcm-src-info').innerHTML =
                '<strong>' + escHtml(c.customer||'') + '</strong>'
                + ' <span style="color:#aaa;font-size:10px;">' + escHtml(c.customer_id||'') + '</span>';
        } else {
            document.getElementById('dcm-confirm').style.display = '';
        }
    });
}

function showCustTransferSection() {
    document.getElementById('dcm-blocked').style.display = 'none';
    document.getElementById('dcm-transfer').style.display = '';
}

var _dcmTgtTimer = null;
function onDcmTgtInput(val) {
    clearTimeout(_dcmTgtTimer);
    _dcm_tgt_id = '';
    document.getElementById('dcm-tgt-info').textContent = '尚未選擇目標客戶';
    document.getElementById('dcm-tgt-info').style.color = '#aaa';
    var dd = document.getElementById('dcm-tgt-dd');
    if (!val.trim()) { dd.style.display='none'; return; }
    _dcmTgtTimer = setTimeout(function() {
        api({ action:'get_customer_transfer_info', kw:val.trim() }).done(function(r) {
            if (!r.success || !r.data || !r.data.length) { dd.style.display='none'; return; }
            dd.innerHTML = r.data.map(function(c) {
                return '<div onclick="selectDcmTgt(\''+escAttr(c.customer_id)+'\',\''+escAttr(c.customer)+'\',\''+escAttr(c.bound_counts||'')+'\',this)" '
                    + 'style="padding:7px 10px;cursor:pointer;border-bottom:1px solid #f5f5f5;font-size:12px;">'
                    + '<strong>' + escHtml(c.customer_id) + '</strong> — ' + escHtml(c.customer)
                    + '<br><span style="color:#1ABB9C;">'+escHtml(c.bound_counts)+'</span></div>';
            }).join('');
            dd.style.display = 'block';
        });
    }, 250);
}
function selectDcmTgt(custId, custName, boundCounts, el) {
    _dcm_tgt_id = custId;
    document.getElementById('dcm-tgt-input').value = custId + ' — ' + custName;
    document.getElementById('dcm-tgt-dd').style.display = 'none';
    var info = document.getElementById('dcm-tgt-info');
    info.style.color = '#333';
    info.innerHTML = '<strong>' + escHtml(custName) + '</strong>'
        + ' <span style="color:#aaa;font-size:10px;">' + escHtml(custId) + '</span>'
        + (boundCounts ? '<br><span style="color:#1ABB9C;">目前綁定：' + escHtml(boundCounts) + '</span>' : '');
}
document.addEventListener('click', function(e) {
    if (!e.target.closest('#dcm-tgt-input') && !e.target.closest('#dcm-tgt-dd'))
        { var d=document.getElementById('dcm-tgt-dd'); if(d) d.style.display='none'; }
});

function _afterCustOp() { $('#deleteCustModal').modal('hide'); loadCustomers(customersCurrent); if ($('#dupCheckModal').hasClass('in')) openDupCheck('customers'); }
function doDeleteCust() {
    if (document.getElementById('dcm-ok-input').value.trim().toUpperCase() !== 'OK') {
        showToast('請輸入大寫 OK 確認','error'); return;
    }
    api({ action:'delete_customer', customer_id:_dcm_id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _afterCustOp(); }
        else showToast(r.message,'error');
    });
}

function doTransferCust() {
    if (!_dcm_tgt_id) { showToast('請選擇目標客戶','error'); return; }
    if (_dcm_tgt_id === _dcm_id) { showToast('來源與目標不可相同','error'); return; }
    if (document.getElementById('dcm-transfer-ok').value.trim().toUpperCase() !== 'OK') {
        showToast('請輸入大寫 OK 確認','error'); return;
    }
    api({ action:'transfer_customer_binding', src_customer_id:_dcm_id, tgt_customer_id:_dcm_tgt_id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _afterCustOp(); }
        else showToast(r.message,'error');
    });
}

// ── 廠商刪除 modal 狀態 ───────────────────────────────────
var _dmkm_id = '', _dmkm_name = '', _dmkm_tgt_id = '';

