            document.getElementById('dmkm-blocked').style.display = '';
            document.getElementById('dmkm-transfer-btn-wrap').style.display = CAN_DELETE_ALL ? '' : 'none';
            var m = r.maker || {};
            document.getElementById('dmkm-src-info').innerHTML =
                '<strong>' + escHtml(m.maker_id||'') + '</strong>'
                + ' <span style="color:#aaa;font-size:10px;">' + escHtml(m.maker_id_no||'') + '</span>';
        } else {
            document.getElementById('dmkm-confirm').style.display = '';
        }
    });
}

function showMakerTransferSection() {
    document.getElementById('dmkm-blocked').style.display = 'none';
    document.getElementById('dmkm-transfer').style.display = '';
}

var _dmkmTgtTimer = null;
function onDmkmTgtInput(val) {
    clearTimeout(_dmkmTgtTimer);
    _dmkm_tgt_id = '';
    document.getElementById('dmkm-tgt-info').textContent = '尚未選擇目標廠商';
    document.getElementById('dmkm-tgt-info').style.color = '#aaa';
    var dd = document.getElementById('dmkm-tgt-dd');
    if (!val.trim()) { dd.style.display='none'; return; }
    _dmkmTgtTimer = setTimeout(function() {
        api({ action:'get_maker_transfer_info', kw:val.trim() }).done(function(r) {
            if (!r.success || !r.data || !r.data.length) { dd.style.display='none'; return; }
            dd.innerHTML = r.data.map(function(m) {
                return '<div onclick="selectDmkmTgt(\''+escAttr(m.maker_id_no)+'\',\''+escAttr(m.maker_id)+'\',\''+escAttr(m.bound_counts||'')+'\',this)" '
                    + 'style="padding:7px 10px;cursor:pointer;border-bottom:1px solid #f5f5f5;font-size:12px;">'
                    + '<strong>' + escHtml(m.maker_id_no) + '</strong> — ' + escHtml(m.maker_id)
                    + (m.maker_id_all ? '<small style="color:#aaa;"> （'+escHtml(m.maker_id_all)+'）</small>' : '')
                    + '<br><span style="color:#1ABB9C;">'+escHtml(m.bound_counts)+'</span></div>';
            }).join('');
            dd.style.display = 'block';
        });
    }, 250);
}
function selectDmkmTgt(mid, mname, boundCounts) {
    _dmkm_tgt_id = mid;
    document.getElementById('dmkm-tgt-input').value = mid + ' — ' + mname;
    document.getElementById('dmkm-tgt-dd').style.display = 'none';
    var info = document.getElementById('dmkm-tgt-info');
    info.style.color = '#333';
    info.innerHTML = '<strong>' + escHtml(mname) + '</strong>'
        + ' <span style="color:#aaa;font-size:10px;">' + escHtml(mid) + '</span>'
        + (boundCounts ? '<br><span style="color:#1ABB9C;">目前綁定：' + escHtml(boundCounts) + '</span>' : '');
}
document.addEventListener('click', function(e) {
    if (!e.target.closest('#dmkm-tgt-input') && !e.target.closest('#dmkm-tgt-dd'))
        { var d=document.getElementById('dmkm-tgt-dd'); if(d) d.style.display='none'; }
});

function _afterMakerOp() { $('#deleteMakerModal').modal('hide'); loadMakers(makersCurrent); if ($('#dupCheckModal').hasClass('in')) openDupCheck('makers'); }
function doDeleteMaker() {
    if (document.getElementById('dmkm-ok-input').value.trim().toUpperCase() !== 'OK') {
        showToast('請輸入大寫 OK 確認','error'); return;
    }
    api({ action:'delete_maker', maker_id_no:_dmkm_id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _afterMakerOp(); }
        else showToast(r.message,'error');
    });
}

function doTransferMaker() {
    if (!_dmkm_tgt_id) { showToast('請選擇目標廠商','error'); return; }
    if (_dmkm_tgt_id === _dmkm_id) { showToast('來源與目標不可相同','error'); return; }
    if (document.getElementById('dmkm-transfer-ok').value.trim().toUpperCase() !== 'OK') {
        showToast('請輸入大寫 OK 確認','error'); return;
    }
    api({ action:'transfer_maker_binding', src_maker_id_no:_dmkm_id, tgt_maker_id_no:_dmkm_tgt_id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _afterMakerOp(); }
        else showToast(r.message,'error');
    });
}

// ═══════════════════════════════════════════════════
// ──────────── 廠商 ─────────────────────────────────
// ═══════════════════════════════════════════════════
var makersLoaded=false, makersCurrent=1, makersTotal=1;
var makerMainCats = [];

function loadMakerMainCats(callback) {
    if (makerMainCats.length) { callback(makerMainCats); return; }
    api({ action:'get_maker_main_cats' }).done(function(r) {
        if (r.success) { makerMainCats = r.data; callback(r.data); }
        else callback([]);
    });
}
function refreshMakerMainCatsCache() {
    // Force refresh the main cats cache (call after dict changes)
    makerMainCats = [];
}

function getMakersKws() {
    var live = (document.getElementById('makers-search')||{}).value || '';
    var all = _makersFilter.keywords.slice().concat(_makersFilter.quickKws||[]); if (live.trim()) all.push(live.trim()); return all.join('||');
}
function loadMakers(pg) {
    pg = pg || 1;
    makersCurrent = pg;
    document.getElementById('makers-table-wrap').innerHTML = '<div class="table-loading"><div class="spinner"></div> 載入中…</div>';
    api({ action:'list_makers', keywords_p:getMakersKws(), page:pg,
          filter_main_cats_p:     _makersFilter.main_cats.join(','),
          filter_sub_cats_p:      _makersFilter.sub_cats.join(','),
          filter_pinned_maker_ids: _makersFilter.pinnedMakerIds.join(','),
          filter_payment_method:   _makersFilter.payment_method,
          filter_settlement_mode:  _makersFilter.settlement_mode,
          filter_settlement_day:   _makersFilter.settlement_day !== null ? _makersFilter.settlement_day : '',
          filter_proc_labels:      JSON.stringify(_makersFilter.proc_labels)
    }).done(function(r) {
        if (!r.success) { showToast(r.message,'error'); return; }
        makersLoaded = true;
        makersTotal  = r.pages;
        renderMakersTable(r.data, r.total, pg, r.pages);
    }).fail(function(){ showToast('網路錯誤','error'); });
}

var qualityBadge = {A:'<span class="badge-type badge-active">A級</span>', B:'<span class="badge-type" style="background:#fff3cd;color:#856404;">B級</span>', C:'<span class="badge-type" style="background:#f8d7da;color:#721c24;">C級</span>'};

function showMakerNoteModal(note) {
    document.getElementById('maker-note-view-content').textContent = note || '';
    $('#makerNoteViewModal').modal('show');
}
function renderMakersTable(rows, total, pg, pages) {
    var html = '<div style="overflow-x:auto;"><table class="table"><thead><tr>';
    html += '<th style="width:5.5%;">廠商編號</th>';
    html += '<th style="width:8%;">廠商</th>';
    html += '<th style="width:7%;">大類</th>';
    html += '<th style="width:12%;">加工項目</th>';
    html += '<th style="width:13%;">加工限制</th>';
    html += '<th style="width:7%;">付款條件</th>';
    html += '<th style="width:9%;">電話</th>';
    html += '<th style="width:11%;">備註</th>';
    html += '<th style="width:5%;text-align:center;">KPI</th>';
    html += '<th style="width:6%;">狀態</th>';
    if (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS) html += '<th style="width:7%;text-align:center;white-space:nowrap;">操作</th>';
    html += '</tr></thead><tbody>';

    if (!rows.length) {
        var cp = (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS) ? 11 : 10;
        html += '<tr><td colspan="'+cp+'"><div class="empty-state"><i class="fa fa-industry"></i>查無資料</div></td></tr>';
    } else {
        rows.forEach(function(r) {
            var badge = '';
            if (r.status==='X')     badge = '<span class="badge-type badge-inactive">停用</span>';
            else if (r.internal==1) badge = '<span class="badge-type badge-internal">廠內</span>';
            else                    badge = '<span class="badge-type badge-active">正常</span>';
            if (r.is_qualified==1)  badge += '<br><span class="badge-type" style="background:#cce5ff;color:#004085;margin-top:2px;">ISO</span>';
            var qr = qualityBadge[r.quality_rating||'']||'<span style="color:#ddd;">—</span>';

            // ── 大類欄：每個大類一個彩色 Chip ──
            var mainCatHtml = '';
            if (r.sub_cat_tags && r.sub_cat_tags.length) {
                var seenMain = {};
                r.sub_cat_tags.forEach(function(t) {
                    var mk = t.main_cat_id||'__none__';
                    if (!seenMain[mk] && t.main_cat_name) {
                        seenMain[mk] = true;
                        var pal = getMainCatColorById(t.main_cat_id||0);
                        mainCatHtml += '<span style="display:inline-block;background:'+pal.sel+';color:#fff;border-radius:10px;padding:1px 6px;font-size:10px;font-weight:700;margin:1px 2px 1px 0;white-space:nowrap;">'+escHtml(t.main_cat_name)+'</span>';
                    }
                });
            } else if (r.main_cat_name) {
                mainCatHtml = '<span style="display:inline-block;background:#5856d6;color:#fff;border-radius:10px;padding:1px 6px;font-size:10px;font-weight:700;">'+escHtml(r.main_cat_name)+'</span>';
            }

            // ── 加工項目欄：只顯示小類 chips（不含大類標籤）+ 說明灰字 ──
            var subTagHtml = '';
            if (r.sub_cat_tags && r.sub_cat_tags.length) {
                r.sub_cat_tags.forEach(function(t) {
                    var pal = getMainCatColorById(t.main_cat_id||0);
                    subTagHtml += '<span style="display:inline-block;background:'+pal.bg+';color:'+pal.fg+';border:1px solid '+pal.fg+'44;border-radius:8px;padding:0 6px;font-size:10px;font-weight:600;margin:1px 2px 1px 0;white-space:nowrap;">'+escHtml(t.sub_cat_name)+'</span>';
                });
                if (r.m_process_items) {
                    subTagHtml += '<div style="font-size:11px;color:#aaa;margin-top:3px;">'+escHtml(r.m_process_items)+'</div>';
                }
            } else if (r.m_process_items) {
                r.m_process_items.split('、').forEach(function(p) {
                    if (p.trim()) subTagHtml += '<span class="process-chip">'+escHtml(p.trim())+'</span>';
                });
            }

            var isInactive = (r.status === 'X');
            var rowStyle   = isInactive ? ' style="opacity:0.55;"' : '';
            html += '<tr'+rowStyle+'>';
            html += '<td><code style="background:#f0f4f8;border-radius:3px;padding:2px 5px;font-weight:700;color:var(--primary);font-size:11px;display:block;">'+escHtml(r.maker_id_no)+'</code></td>';
            // 廠商欄：簡稱 + 全稱（灰字）
            var makerInfoHtml = '<strong style="font-size:13px;">'+escHtml(r.maker_id)+'</strong>';
            if (r.maker_id_all) makerInfoHtml += '<br><small style="color:#aaa;font-size:11px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:160px;" title="'+escAttr(r.maker_id_all)+'">'+escHtml(r.maker_id_all)+'</small>';
            html += '<td title="'+escHtml(r.maker_id_all||r.maker_id)+'">'+makerInfoHtml+'</td>';
            // 大類欄：獨立 chips
            html += '<td style="white-space:nowrap;">'+(mainCatHtml||'<span style="color:#ddd;">—</span>')+'</td>';
            // 加工項目欄
            html += '<td>'+(subTagHtml||'<span style="color:#ddd;">—</span>')+'</td>';
            // 加工限制欄：按父子關係分組，仿編輯 modal chip 樣式
            var limitHtml = '';
            if (r.proc_labels && r.proc_labels.length) {
                var _plTops = [], _plSubs = {};
                r.proc_labels.forEach(function(pl) {
                    var pmid = parseInt(pl.parent_map_id, 10);
                    if (!pmid) { _plTops.push(pl); }
                    else { if (!_plSubs[pmid]) _plSubs[pmid] = []; _plSubs[pmid].push(pl); }
                });
                var _plVal = function(pl) {
                    var nt = pl.numeric_type || 'range';
                    var u  = (pl.unit && pl.unit !== 'mm') ? (' ' + pl.unit) : '';
                    var lup = (pl.label_name||'').toUpperCase();
                    var mn = (pl.value_min !== null && pl.value_min !== undefined && String(pl.value_min) !== '') ? fmtNum(pl.value_min) : '';
                    var mx = (pl.value_max !== null && pl.value_max !== undefined && String(pl.value_max) !== '') ? fmtNum(pl.value_max) : '';
                    if (pl.input_type === 'numeric') {
                        if (nt === 'range') return (mn || mx) ? (mn||'?')+'~'+(mx||'?')+u : '';
                        if (nt === 'MAX')   return mx ? (lup.indexOf('MAX')===-1 ? 'MAX ' : '')+mx+u : '';
                        if (nt === 'MIN')   return mn ? (lup.indexOf('MIN')===-1 ? 'MIN ' : '')+mn+u : '';
                    } else if (pl.input_type === 'text') {
                        return (pl.text_value !== null && pl.text_value !== undefined && pl.text_value !== '') ? String(pl.text_value) : '';
                    }
                    return '';
                };
                limitHtml = '<div style="display:flex;flex-wrap:wrap;gap:2px;align-items:flex-start;">';
                _plTops.forEach(function(pl) {
                    var mapId = parseInt(pl.map_id, 10);
                    var subs  = _plSubs[mapId] || [];
                    var ov    = _plVal(pl);
                    var parts = ['<span style="font-weight:700;color:#1ABB9C;">'+escHtml(pl.label_name)+'</span>'+(ov ? ' <span style="font-weight:normal;color:#444;">'+escHtml(ov)+'</span>' : '')];
                    subs.forEach(function(sub) {
                        var sv = _plVal(sub);
                        parts.push(escHtml(sub.label_name)+(sv ? ' <span style="font-weight:normal;color:#444;">'+escHtml(sv)+'</span>' : ''));
                    });
                    limitHtml += '<div style="display:inline-block;background:#f0faf8;border:1px solid #b2dfdb;border-radius:8px;padding:1px 6px;font-size:10px;font-weight:600;color:#555;white-space:nowrap;max-width:100%;overflow:hidden;text-overflow:ellipsis;">'+parts.join('<span style="color:#aad8d0;"> · </span>')+'</div>';
                });
                limitHtml += '</div>';
            }
            html += '<td>'+(limitHtml||'<span style="color:#ddd;">—</span>')+'</td>';
            // 付款條件欄
            var mSettleMap = {FIXED:'固定日',EOM:'月底',VARIABLE:'不固定'};
            var mPayHtml = '';
            if (r.payment_method) mPayHtml += '<span style="font-size:11px;color:#555;">'+escHtml(r.payment_method)+'</span>';
            if (r.settlement_mode) {
                var msl = mSettleMap[r.settlement_mode] || r.settlement_mode;
                if (r.settlement_mode === 'FIXED' && r.settlement_day) msl += ' '+r.settlement_day+'日';
                mPayHtml += (mPayHtml ? '<br>' : '') + '<span style="font-size:10px;color:#aaa;">'+escHtml(msl)+'</span>';
            }
            if (r.net_days) mPayHtml += '<br><span style="font-size:10px;color:#aaa;">月結'+escHtml(r.net_days)+'天</span>';
            html += '<td>'+(mPayHtml||'<span style="color:#ddd;">—</span>')+'</td>';
            html += '<td style="font-size:12px;white-space:nowrap;">'+(escHtml(r.m_tel)||'—')+'</td>';
            // 備註欄：預設顯示前兩行，超出顯示 + 跳窗
            var noteHtml = '';
            if (r.m_note) {
                var noteLines = r.m_note.split('\n');
                var isLong = noteLines.length > 2 || r.m_note.length > 60;
                if (isLong) {
                    var preview;
                    if (noteLines.length > 2) {
                        preview = noteLines.slice(0, 2).join('\n');
                    } else {
                        preview = r.m_note.substring(0, 60);
                    }
                    noteHtml = '<span style="font-size:11px;color:#555;white-space:pre-wrap;word-break:break-all;">'+escHtml(preview)+'…</span>'
                        + ' <span style="cursor:pointer;color:#1ABB9C;font-size:11px;" data-note="'+escHtml(r.m_note)+'" onclick="showMakerNoteModal(this.dataset.note)"><i class="fa fa-plus-circle"></i></span>';
                } else {
                    noteHtml = '<span style="font-size:11px;color:#555;white-space:pre-wrap;word-break:break-all;">'+escHtml(r.m_note)+'</span>';
                }
            } else {
                noteHtml = '<span style="color:#ddd;">—</span>';
            }
            html += '<td>'+noteHtml+'</td>';
            // KPI 欄：placeholder
            html += '<td id="kpi-'+escHtml(r.maker_id_no)+'" style="text-align:center;"><span style="color:#ddd;font-size:11px;">…</span></td>';
            html += '<td>'+badge+'</td>';
            if (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS) {
                html += '<td><div class="row-actions">';
                if (CAN_UPDATE) html += '<button class="btn-row btn-edit" onclick="openMakerModal(\''+escAttr(r.maker_id_no)+'\')" title="編輯"><i class="fa fa-pencil"></i></button>';
                // 廠商停用/啟用請透過編輯 modal 的廠商狀態欄位操作
                if (CAN_DELETE_ALL) html += '<button class="btn-row btn-delete" onclick="deleteMaker(\''+escAttr(r.maker_id_no)+'\',\''+escAttr(r.maker_id)+'\')" title="刪除"><i class="fa fa-trash"></i></button>';
                html += '</div></td>';
            }
            html += '</tr>';
            // 舊編號跨欄提示列（廠商～加工限制，共4欄）
            if (r.is_old_alias) {
                var totalCols = (CAN_UPDATE||CAN_DELETE_ALL||CAN_SET_STATUS) ? 11 : 10;
                html += '<tr><td></td>'
                    + '<td colspan="4" style="padding:2px 8px 4px;border-top:none;">'
                    + '<span style="display:inline-block;background:#fff3e0;color:#e65100;border:1px solid #ffcc80;border-radius:4px;font-size:10px;font-weight:700;padding:2px 8px;">'
                    + '<i class="fa fa-arrow-right"></i> 此廠商為舊編號，正式廠商：'
                    + escHtml(r.is_old_alias.new_name) + '（' + escHtml(r.is_old_alias.new_id) + '）'
                    + '</span></td>'
                    + '<td colspan="'+(totalCols-5)+'"></td></tr>';
            }
        });
    }
    var pgHtml = paginationHTML(total, pg, pages, 'loadMakers');
    document.getElementById('makers-table-wrap').innerHTML = pgHtml + html + '</tbody></table></div>';

    // 批次填入 KPI 評級（非同步不阻塞渲染）
    if (rows.length) {
        var ids = rows.map(function(r){ return r.maker_id_no; });
        api({ action:'get_kpi_grades', maker_ids:JSON.stringify(ids) }).done(function(r) {
            if (!r.success) return;
            Object.keys(r.data).forEach(function(mid) {
                var cell = document.getElementById('kpi-'+mid);
                if (!cell) return;
                var g = r.data[mid];
                if (g.grade === '—') {
                    cell.innerHTML = '<span style="color:#ccc;font-size:11px;" title="資料不足">—</span>';
                } else {
                    var colorMap = {green:'#1ABB9C',yellow:'#f39c12',red:'#e74c3c',purple:'#8e44ad',gray:'#aaa',blue:'#3498db'};
                    var c = colorMap[g.grade_color]||'#aaa';
                    var pct = g.ontime_pct !== null ? g.ontime_pct+'%' : '—';
                    cell.innerHTML = '<span title="準時率:'+pct+' NG率:'+g.ng_pct+'%" style="display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:'+c+'22;color:'+c+';font-size:11px;font-weight:700;border:1.5px solid '+c+';">'+escHtml(g.grade)+'</span>';
                }
            });
        });
    }
}

// Sub category logic
// Main-cat palette (distinct, no red)
var _mainCatPalette = [
    {bg:'#e3f2fd',fg:'#1565c0',sel:'#1565c0'},
    {bg:'#e8f5e9',fg:'#2e7d32',sel:'#2e7d32'},
    {bg:'#fff3e0',fg:'#e65100',sel:'#e65100'},
    {bg:'#f3e5f5',fg:'#6a1b9a',sel:'#6a1b9a'},
    {bg:'#e0f7fa',fg:'#00695c',sel:'#00695c'},
    {bg:'#fce4ec',fg:'#880e4f',sel:'#880e4f'},
    {bg:'#f9fbe7',fg:'#558b2f',sel:'#558b2f'},
    {bg:'#ede7f6',fg:'#4527a0',sel:'#4527a0'},
];
var _allMainCatsData = [];
var _makerAllSelSubIds = []; // 持久追蹤已勾選子類，不因大類切換而遺失

function getMainCatColor(idx) { return _mainCatPalette[idx % _mainCatPalette.length]; }
// Global map: main_cat_id → palette index (built when _allMainCatsData loads)
var _mainCatIdxMap = {};
function getMainCatColorById(main_cat_id) {
    var idx = (_mainCatIdxMap[String(main_cat_id)] !== undefined) ? _mainCatIdxMap[String(main_cat_id)] : (parseInt(main_cat_id)||0) % _mainCatPalette.length;
    return _mainCatPalette[idx % _mainCatPalette.length];
}

function loadMakerCatUI(selectedMainIds, selectedSubIds, existingProcessTags) {
    // selectedMainIds:    array of int (e.g. [2, 5])
    // selectedSubIds:     array of int (e.g. [3, 7, 12])
    // existingProcessTags: array of {main_cat_id, ref_type, ref_id}
    _makerProcTagsInitial = existingProcessTags || [];
    _makerAllSelSubIds = (selectedSubIds || []).slice(); // 初始化持久選取清單
    var wrap = document.getElementById('mf-main-cat-chips-wrap');
    if (wrap) wrap.innerHTML = '<span style="color:#aaa;font-size:12px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</span>';
    // 建立初始製程標籤對應表
    var initTagMap = {};
    (_makerProcTagsInitial||[]).forEach(function(t){
        var mcid = String(t.main_cat_id);
        if (!initTagMap[mcid]) initTagMap[mcid] = {};
        initTagMap[mcid][t.ref_type+':'+t.ref_id] = true;
    });
    $.when(
        api({ action:'get_maker_sub_cats' }),
        api({ action:'manage_maker_main_cat_process', op:'list_config' })
    ).done(function(r1, r2) {
        if (!r1[0].success) return;
        _allMainCatsData = r1[0].data || [];
        _makerMainCatProcessConfig = r2[0].success ? { main_cats: r2[0].main_cats||[], process_types: r2[0].process_types||[], process_nos: r2[0].process_nos||[] } : null;
        _mainCatIdxMap = {};
        _allMainCatsData.forEach(function(cat, i){ _mainCatIdxMap[String(cat.main_cat_id)] = i; });
        renderMainCatChips(selectedMainIds);
        renderGroupedSubCats(selectedMainIds, selectedSubIds, initTagMap);
    });
}
var _makerProcTagsInitial = [];
var _makerMainCatProcessConfig = null;

function renderMainCatChips(selectedMainIds) {
    var wrap = document.getElementById('mf-main-cat-chips-wrap');
    if (!wrap) return;
    if (!_allMainCatsData.length) {
        wrap.innerHTML = '<span style="color:#aaa;font-size:12px;">無大類資料（請先至字典設定新增）</span>'; return;
    }
    var html = '';
    _allMainCatsData.forEach(function(cat, idx) {
        var pal = getMainCatColor(idx);
        var sel = selectedMainIds.indexOf(parseInt(cat.main_cat_id)) >= 0;
        var bg = sel ? pal.sel : pal.bg;
        var fg = sel ? '#fff'  : pal.fg;
        var bd = sel ? pal.sel : pal.fg+'55';
        html += '<span class="main-cat-chip" data-id="'+cat.main_cat_id+'" data-idx="'+idx+'" data-active="'+(sel?'1':'0')+'"'
            + ' style="display:inline-block;padding:4px 13px;border-radius:14px;font-size:12px;font-weight:600;cursor:pointer;user-select:none;transition:all .15s;border:1.5px solid '+bd+';background:'+bg+';color:'+fg+';"'
            + ' onclick="toggleMainCatChip(this)">'+escHtml(cat.main_cat_name)+'</span>';
    });
    wrap.innerHTML = html;
}

function toggleMainCatChip(el) {
    var id  = parseInt(el.dataset.id);
    var idx = parseInt(el.dataset.idx);
    var pal = getMainCatColor(idx);
    var isActive = el.dataset.active === '1';
    if (isActive) {
        el.dataset.active = '0';
        el.style.background  = pal.bg;
        el.style.color       = pal.fg;
        el.style.borderColor = pal.fg+'55';
    } else {
        el.dataset.active = '1';
        el.style.background  = pal.sel;
        el.style.color       = '#fff';
        el.style.borderColor = pal.sel;
    }
    var selMain = [];
    document.querySelectorAll('#mf-main-cat-chips-wrap .main-cat-chip[data-active="1"]').forEach(function(c){ selMain.push(parseInt(c.dataset.id)); });
    document.getElementById('mf-main_category_id').value = selMain.length ? selMain[0] : '';
    // 使用持久清單作為子類選取來源，避免切換大類時遺失其他大類的勾選
    var selSub = _makerAllSelSubIds.slice();
    var tagMap = {};
    document.querySelectorAll('#mf-sub-cat-wrap .mf-proc-tag-cb:checked').forEach(function(cb){
        var mcid = String(cb.dataset.mcid);
        if (!tagMap[mcid]) tagMap[mcid]={};
        tagMap[mcid][cb.dataset.refType+':'+cb.dataset.refId]=true;
    });
    renderGroupedSubCats(selMain, selSub, tagMap);
}

function renderGroupedSubCats(selectedMainIds, selectedSubIds, procTagMap) {
    var wrap = document.getElementById('mf-sub-cat-wrap');
    if (!wrap) return;
    if (!selectedMainIds || !selectedMainIds.length) {
        wrap.innerHTML = '<span style="color:#aaa;font-size:12px;">請先選擇廠商大類</span>';
        syncSubCatHidden(); syncMakerProcTags(); return;
    }
    var html = ''; var hasSub = false;
    _allMainCatsData.forEach(function(cat, catIdx) {
        if (selectedMainIds.indexOf(parseInt(cat.main_cat_id)) < 0) return;
        var pal = getMainCatColor(catIdx);
        var hasSubs  = cat.sub_cats && cat.sub_cats.length;
        var mcid     = cat.main_cat_id;
        // 此大類是否有製程設定
        var mcConfig = null;
        if (_makerMainCatProcessConfig) {
            var mcCfgObj = (_makerMainCatProcessConfig.main_cats||[]).find(function(m){ return m.main_cat_id==mcid; });
            if (mcCfgObj && (mcCfgObj.process_config||[]).length) mcConfig = mcCfgObj;
        }
        if (!hasSubs && !mcConfig) return;
        hasSub = true;
        html += '<div style="margin-bottom:8px;">';
        html += '<div style="display:inline-block;padding:2px 10px;border-radius:8px 8px 0 0;font-size:10px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;background:'+pal.sel+';color:#fff;">'+escHtml(cat.main_cat_name)+'</div>';
        html += '<div style="display:flex;flex-wrap:wrap;gap:5px;padding:7px 8px;border-radius:0 8px 8px 8px;border:1.5px solid '+pal.sel+'33;background:'+pal.bg+';">';
        if (hasSubs) {
            cat.sub_cats.forEach(function(s) {
                var sel = selectedSubIds.indexOf(parseInt(s.sub_cat_id)) >= 0;
                html += '<label class="sub-cat-tag" style="display:inline-flex;align-items:center;gap:3px;background:'+(sel?pal.sel:pal.bg)+';color:'+(sel?'#fff':pal.fg)+';border:1.5px solid '+(sel?pal.sel:pal.fg+'44')+';border-radius:12px;padding:2px 10px;cursor:pointer;font-weight:'+(sel?'700':'normal')+';font-size:12px;transition:all .15s;" onclick="toggleSubCatTag(this,'+s.sub_cat_id+','+catIdx+')">'
                    + '<input type="checkbox" '+(sel?'checked':'')+' style="display:none;" value="'+s.sub_cat_id+'">'+escHtml(s.sub_cat_name)+'</label>';
            });
        }
        // 製程標籤（額外）
        if (mcConfig) {
            var ptCfg = _makerMainCatProcessConfig.process_types||[];
            var pnCfg = _makerMainCatProcessConfig.process_nos||[];
            var cfg   = mcConfig.process_config;
            var cfgTypeIds={}, cfgNoIds={};
            cfg.forEach(function(c){ if(c.ref_type==='type') cfgTypeIds[String(c.ref_id)]=true; else cfgNoIds[String(c.ref_id)]=true; });
            var tagMapForMc = (procTagMap||{})[String(mcid)] || {};
            var pts = ptCfg.filter(function(pt){ return cfgTypeIds[String(pt.process_type_id)]; });
            var pns = pnCfg.filter(function(pn){ return cfgNoIds[String(pn.ProcessNo)]; });
            if (pts.length || pns.length) {
                if (hasSubs) html += '<div style="width:100%;border-top:1px dashed '+pal.sel+'44;margin:5px 0 3px;"></div>';
                html += '<div style="display:flex;flex-wrap:wrap;gap:4px;width:100%;">';
                pts.forEach(function(pt) {
                    var key='type:'+pt.process_type_id; var ck=tagMapForMc[key]?true:false;
                    html += '<label style="display:inline-flex;align-items:center;gap:2px;padding:2px 9px;border-radius:10px;font-size:11px;cursor:pointer;margin:0;border:1px solid '+(ck?'#1565c0':'#bbdefb')+';background:'+(ck?'#e3f2fd':'#f5f9ff')+';color:'+(ck?'#1565c0':'#555')+';font-weight:'+(ck?'600':'normal')+';transition:all .1s;" onclick="toggleMakerProcTag(this)">';
                    html += '<input type="checkbox" class="mf-proc-tag-cb" data-mcid="'+mcid+'" data-ref-type="type" data-ref-id="'+pt.process_type_id+'" '+(ck?'checked':'')+' style="display:none;">'+escHtml(pt.process_type||'')+'</label>';
                });
                pns.forEach(function(pn) {
                    var key='no:'+pn.ProcessNo; var ck=tagMapForMc[key]?true:false;
                    html += '<label style="display:inline-flex;align-items:center;gap:2px;padding:2px 9px;border-radius:10px;font-size:11px;cursor:pointer;margin:0;border:1px solid '+(ck?'#2e7d32':'#c8e6c9')+';background:'+(ck?'#e8f5e9':'#f5fbf5')+';color:'+(ck?'#2e7d32':'#555')+';font-weight:'+(ck?'600':'normal')+';transition:all .1s;" onclick="toggleMakerProcTag(this)">';
                    html += '<input type="checkbox" class="mf-proc-tag-cb" data-mcid="'+mcid+'" data-ref-type="no" data-ref-id="'+pn.ProcessNo+'" '+(ck?'checked':'')+' style="display:none;">'+escHtml(pn.ProcessName||'')+'</label>';
                });
                html += '</div>';
            }
        }
        html += '</div></div>';
    });
    wrap.innerHTML = hasSub ? html : '<span style="color:#aaa;font-size:12px;">所選大類尚未綁定小類或製程設定</span>';
    syncSubCatHidden(); syncMakerProcTags();
}

function toggleSubCatTag(el, id, catIdx) {
    var cb = el.querySelector('input');
    var pal = getMainCatColor(catIdx);
    cb.checked = !cb.checked;
    el.style.background  = cb.checked ? pal.sel : pal.bg;
    el.style.color       = cb.checked ? '#fff'  : pal.fg;
    el.style.borderColor = cb.checked ? pal.sel : pal.fg+'44';
    el.style.fontWeight  = cb.checked ? '700'   : 'normal';
    // 同步更新持久清單
    var idx = _makerAllSelSubIds.indexOf(id);
    if (cb.checked && idx < 0) _makerAllSelSubIds.push(id);
    if (!cb.checked && idx >= 0) _makerAllSelSubIds.splice(idx, 1);
    syncSubCatHidden();
}

function toggleMakerProcTag(el) {
    var cb = el.querySelector('input.mf-proc-tag-cb');
    cb.checked = !cb.checked;
    var isT = cb.dataset.refType === 'type';
    el.style.borderColor = cb.checked ? (isT?'#1565c0':'#2e7d32') : (isT?'#bbdefb':'#c8e6c9');
    el.style.background  = cb.checked ? (isT?'#e3f2fd':'#e8f5e9') : (isT?'#f5f9ff':'#f5fbf5');
    el.style.color       = cb.checked ? (isT?'#1565c0':'#2e7d32') : '#555';
    el.style.fontWeight  = cb.checked ? '600' : 'normal';
    syncMakerProcTags();
}

function syncMakerProcTags() {
    var tags = [];
    document.querySelectorAll('#mf-sub-cat-wrap .mf-proc-tag-cb:checked').forEach(function(cb) {
        tags.push({ main_cat_id: parseInt(cb.dataset.mcid, 10), ref_type: cb.dataset.refType, ref_id: parseInt(cb.dataset.refId, 10) });
    });
    var h = document.getElementById('mf-main_cat_process_tags');
    if (h) h.value = JSON.stringify(tags);
}

// Legacy stub
function onMainCatChange(mainId) {
    var selMain = [parseInt(mainId)].filter(Boolean);
    renderGroupedSubCats(selMain, []);
}

function syncSubCatHidden() {
    var ids = [];
    document.querySelectorAll('#mf-sub-cat-wrap input[type=checkbox]:not(.mf-proc-tag-cb)').forEach(function(cb) {
        if (cb.checked) ids.push(parseInt(cb.value));
    });
    document.getElementById('mf-sub_cats').value = JSON.stringify(ids);
}

function openMakerModal(maker_id_no) {
    if (maker_id_no) {
        if (!CAN_UPDATE) { showToast('無修改權限','error'); return; }
        api({ action:'get_maker', maker_id_no:maker_id_no }).done(function(r) {
            if (!r.success) { showToast(r.message,'error'); return; }
            var d = r.data;
            document.getElementById('makerModal-title').textContent = '編輯廠商';
            document.getElementById('mf-is_new').value = '0';
            var midEl = document.getElementById('mf-maker_id_no');
            midEl.value = d.maker_id_no; midEl.readOnly = true; midEl.style.background = '#f5f5f5';
            var fields = ['maker_id','maker_id_all','m_tel','m_tel2','m_fax','invoice_address','factory_address','billing_address','postal_code','tax_id','contact_person','contact_title','email','m_category','m_process_items','limit_dia','limit_len','m_note'];
            fields.forEach(function(f){ var el=document.getElementById('mf-'+f); if(el) el.value=(d[f]!==null&&d[f]!==undefined)?d[f]:''; });
            document.getElementById('mf-status').value          = d.status||'';
            document.getElementById('mf-internal').checked      = (d.internal==1);
            document.getElementById('mf-quality_rating').value  = d.quality_rating||'';
            document.getElementById('mf-is_qualified').checked  = (d.is_qualified==1);
            // 已選大類 IDs（後端回傳 selected_main_cat_ids 陣列）
            var selMainIds = (d.selected_main_cat_ids||[]).map(Number);
            var selSubIds  = (d.sub_cats||[]).map(function(s){ return parseInt(s.sub_cat_id); });
            loadMakerCatUI(selMainIds, selSubIds, d.main_cat_process_tags || []);
            // 付款設定
            var mMode = d.settlement_mode || 'FIXED';
            var mDay  = d.settlement_day  || '';
            var mPay  = d.payment_method  || '匯款';
            var mNd   = (d.net_days !== null && d.net_days !== undefined && d.net_days !== '') ? String(d.net_days) : '';
            document.getElementById('mf-settlement_mode').value  = mMode;
            document.getElementById('mf-settlement_day').value   = mDay;
            document.getElementById('mf-payment_method').value   = mPay;
            document.getElementById('mf-net_days').value         = mNd;
            onMakerSettlementModeChange(mMode);
            _applyMakerPaymentDefaultHints(mMode, mDay, mPay, mNd, d.confirmed_settlement, d.confirmed_payment);
            // 舊編號提示
            var noticeEl = document.getElementById('mf-old-alias-notice');
            if (noticeEl) {
                if (d.is_old_alias) {
                    document.getElementById('mf-old-alias-new-name').textContent = d.is_old_alias.new_name || '';
                    document.getElementById('mf-old-alias-new-id').textContent   = d.is_old_alias.new_id   || '';
                    noticeEl.style.display = '';
                } else {
                    noticeEl.style.display = 'none';
                }
            }
            // 廠商聯絡人
            loadMakerContactRows(d.contacts || []);
            // 歷史廠商編號
            document.getElementById('mf-aliases-section').style.display = '';
            document.getElementById('mf-alias-input').value = '';
            renderMakerAliases(d.aliases || []);
            // 加工限制標籤
            loadMakerProcLabelUI(d.proc_labels || []);
            $('#makerModal').modal('show');
        });
    } else {
        if (!CAN_CREATE) { showToast('無新增權限','error'); return; }
        document.getElementById('makerModal-title').textContent = '新增廠商';
        document.getElementById('makerForm').reset();
        document.getElementById('mf-is_new').value = '1';
        var midEl = document.getElementById('mf-maker_id_no');
        midEl.readOnly = false; midEl.style.background = '';
        document.getElementById('mf-main_category_id').value = '';
        document.getElementById('mf-sub_cats').value = '[]';
        loadMakerCatUI([], []);
        // 新增：預填預設付款條件
        document.getElementById('mf-settlement_mode').value  = SYS_VENDOR_DEFAULT_SETTLEMENT_MODE || 'FIXED';
        document.getElementById('mf-settlement_day').value   = SYS_VENDOR_DEFAULT_SETTLEMENT_DAY  || '25';
        document.getElementById('mf-payment_method').value   = SYS_VENDOR_DEFAULT_PAYMENT_METHOD  || '匯款';
        document.getElementById('mf-net_days').value         = SYS_VENDOR_DEFAULT_NET_DAYS || '';
        onMakerSettlementModeChange(SYS_VENDOR_DEFAULT_SETTLEMENT_MODE || 'FIXED');
        _applyMakerPaymentDefaultHints(SYS_VENDOR_DEFAULT_SETTLEMENT_MODE, SYS_VENDOR_DEFAULT_SETTLEMENT_DAY, SYS_VENDOR_DEFAULT_PAYMENT_METHOD, SYS_VENDOR_DEFAULT_NET_DAYS, 0, 0);
        // 廠商聯絡人（新增時空）
        loadMakerContactRows([]);
        document.getElementById('mf-aliases-section').style.display = 'none';
        var _notice = document.getElementById('mf-old-alias-notice');
        if (_notice) _notice.style.display = 'none';
        // 加工限制標籤（新增時空）
        loadMakerProcLabelUI([]);
        $('#makerModal').modal('show');
    }
}

var _mplTmpCounter = 0;
var _mplSubDefsMap = {}; // parent_lid (int) → [sub-label defs]

function _mplNextTmpId() { return 't' + (++_mplTmpCounter); }

function loadMakerProcLabelUI(existingLabels) {
    var area = document.getElementById('mf-proc-label-area');
    if (!area) return;
    area.innerHTML = '<div style="color:#aaa;font-size:12px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</div>';
    api({ action:'manage_maker_proc_labels', op:'list' }).done(function(r) {
        if (!r.success || !r.data || !r.data.length) {
            area.innerHTML = '<span style="color:#aaa;font-size:12px;">尚未設定加工限制標籤（可在 類別字典設定 → 廠商加工限制 中新增）</span>';
            document.getElementById('mf-proc_labels').value = '[]';
            return;
        }
        _mplTmpCounter = 0;
        _mplSubDefsMap = {};
        var topLabels = [];
        r.data.forEach(function(d) {
            if (d.parent_label_ids) {
                // Sub-label: belongs to one or more parents
                String(d.parent_label_ids).split(',').forEach(function(pidStr) {
                    var pid = parseInt(pidStr, 10);
                    if (!pid) return;
                    if (!_mplSubDefsMap[pid]) _mplSubDefsMap[pid] = [];
                    _mplSubDefsMap[pid].push(d);
                });
            } else {
                topLabels.push(d);
            }
        });

        // Parse existing instance data
        var existTopInsts = [], existSubsByParentMapId = {};
        (existingLabels || []).forEach(function(el) {
            var pmid = parseInt(el.parent_map_id, 10);
            if (!pmid) { existTopInsts.push(el); }
            else {
                if (!existSubsByParentMapId[pmid]) existSubsByParentMapId[pmid] = [];
                existSubsByParentMapId[pmid].push(el);
            }
        });
        // Group top instances by proc_label_id
        var existInstByLid = {};
        existTopInsts.forEach(function(inst) {
            var lid = String(inst.proc_label_id);
            if (!existInstByLid[lid]) existInstByLid[lid] = [];
            var mapId = parseInt(inst.map_id, 10);
            existInstByLid[lid].push({ inst: inst, subs: mapId ? (existSubsByParentMapId[mapId] || []) : [] });
        });

        var html = '<div style="display:flex;flex-wrap:wrap;align-items:flex-start;gap:6px;">';
        topLabels.forEach(function(lbl) {
            var lid      = String(lbl.proc_label_id);
            var itype    = lbl.input_type || 'none';
            var ntype    = lbl.numeric_type || 'range';
            var unit     = lbl.unit || 'mm';
            var isRep    = !!parseInt(lbl.is_repeatable, 10);
            var subDefs  = _mplSubDefsMap[parseInt(lid, 10)] || [];
            var isComplex = isRep || subDefs.length > 0;
            var existInsts = existInstByLid[lid] || [];

            if (!isComplex) {
                // Simple label: old chip+input behavior
                var ex = existInsts.length > 0 ? existInsts[0].inst : null;
                var isSel = !!ex;
                var cs = isSel
                    ? 'background:#e8f5f2;color:#1ABB9C;border:1.5px solid #1ABB9C;cursor:pointer;border-radius:12px;padding:3px 10px;font-size:12px;font-weight:600;display:inline-flex;align-items:center;gap:4px;'
                    : 'background:#f5f7fa;color:#888;border:1.5px solid #ddd;cursor:pointer;border-radius:12px;padding:3px 10px;font-size:12px;display:inline-flex;align-items:center;gap:4px;';
                html += '<span style="display:inline-flex;align-items:center;flex-wrap:wrap;gap:4px;">';
                html += '<span class="mf-proc-chip" data-lid="'+lid+'" data-itype="'+escAttr(itype)+'" data-ntype="'+escAttr(ntype)+'" data-unit="'+escAttr(unit)+'" data-is-rep="0" data-has-subs="0" data-selected="'+(isSel?'1':'0')+'" style="'+cs+'" onclick="toggleMakerProcChip(this)">';
                html += '<i class="fa fa-'+(isSel?'check-circle':'circle-o')+'" style="font-size:11px;"></i> '+escHtml(lbl.label_name)+'</span>';
                var ds = isSel ? 'display:inline-flex' : 'display:none';
                if (itype === 'numeric') {
                    var vmx = ex && ex.value_max !== null && String(ex.value_max) !== '' ? fmtNum(ex.value_max) : '';
                    var vmn = ex && ex.value_min !== null && String(ex.value_min) !== '' ? fmtNum(ex.value_min) : '';
                    html += '<span class="mf-proc-inputs" data-lid="'+lid+'" style="'+ds+';flex-wrap:wrap;align-items:center;gap:4px;">';
                    var lblNameUp = lbl.label_name.toUpperCase();
                    if (ntype === 'range') {
                        html += '<input type="number" class="form-control input-sm mf-proc-min-val" data-lid="'+lid+'" step="0.001" placeholder="最小值" style="width:75px;" value="'+escAttr(String(vmn))+'" oninput="syncMakerProcLabels()">';
                        html += '<span style="color:#aaa;font-size:11px;">~</span>';
                        html += '<input type="number" class="form-control input-sm mf-proc-max-val" data-lid="'+lid+'" step="0.001" placeholder="最大值" style="width:75px;" value="'+escAttr(String(vmx))+'" oninput="syncMakerProcLabels()">';
                    } else if (ntype === 'MAX') {
                        if (lblNameUp.indexOf('MAX') === -1) html += '<span style="font-size:11px;color:#555;">MAX</span>';
                        html += '<input type="number" class="form-control input-sm mf-proc-max-val" data-lid="'+lid+'" step="0.001" placeholder="最大值" style="width:90px;" value="'+escAttr(String(vmx))+'" oninput="syncMakerProcLabels()">';
                    } else if (ntype === 'MIN') {
                        if (lblNameUp.indexOf('MIN') === -1) html += '<span style="font-size:11px;color:#555;">MIN</span>';
                        html += '<input type="number" class="form-control input-sm mf-proc-min-val" data-lid="'+lid+'" step="0.001" placeholder="最小值" style="width:90px;" value="'+escAttr(String(vmn))+'" oninput="syncMakerProcLabels()">';
                    }
                    html += '<span style="font-size:11px;color:#888;">'+escHtml(unit)+'</span></span>';
                } else if (itype === 'text') {
                    var vtxt = ex && ex.text_value !== null && ex.text_value !== undefined ? ex.text_value : '';
                    html += '<span class="mf-proc-inputs" data-lid="'+lid+'" style="'+ds+';align-items:center;">';
                    html += '<input type="text" class="form-control input-sm mf-proc-text-val" data-lid="'+lid+'" maxlength="100" placeholder="文字說明" style="width:140px;" value="'+escAttr(String(vtxt))+'" oninput="syncMakerProcLabels()">';
                    html += '</span>';
                }
                html += '</span>';
            } else {
                // Complex label: group box with instances
                var hasInsts = existInsts.length > 0;
                var chipActive = hasInsts;
                var hcs = chipActive
                    ? 'background:#e8f5f2;color:#1ABB9C;border:1.5px solid #1ABB9C;cursor:pointer;border-radius:12px;padding:3px 10px;font-size:12px;font-weight:600;display:inline-flex;align-items:center;gap:4px;'
                    : 'background:#f5f7fa;color:#888;border:1.5px solid #ddd;cursor:pointer;border-radius:12px;padding:3px 10px;font-size:12px;display:inline-flex;align-items:center;gap:4px;';
                html += '<div class="mpl-group" data-parent-lid="'+lid+'" style="background:#f9f9f9;border:1px solid #e0e0e0;border-radius:8px;padding:5px 8px;min-width:140px;">';
                html += '<div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap;">';
                html += '<span class="mf-proc-chip mpl-group-chip" data-lid="'+lid+'" data-label-name="'+escAttr(lbl.label_name)+'" data-itype="'+escAttr(itype)+'" data-ntype="'+escAttr(ntype)+'" data-unit="'+escAttr(unit)+'" data-is-rep="'+(isRep?'1':'0')+'" data-has-subs="'+(subDefs.length?'1':'0')+'" data-selected="'+(chipActive?'1':'0')+'" style="'+hcs+'" onclick="toggleMakerProcChip(this)">';
                html += '<i class="fa fa-'+(chipActive?'check-circle':'circle-o')+'" style="font-size:11px;"></i> '+escHtml(lbl.label_name);
                if (chipActive && isRep) html += '<span class="mpl-count" style="font-size:10px;background:rgba(0,0,0,0.12);border-radius:8px;padding:0 5px;margin-left:2px;">×'+existInsts.length+'</span>';
                html += '</span>';
                if (isRep && chipActive) html += '<button type="button" class="btn btn-xs btn-default mpl-add-btn" onclick="addProcInstance(\''+lid+'\')" style="padding:2px 7px;font-size:11px;">+ 新增一組</button>';
                html += '</div>';
                var instStyle = hasInsts ? 'display:flex;flex-direction:column;gap:4px;margin-top:5px;' : 'display:none;margin-top:5px;';
                html += '<div class="mpl-instances" data-parent-lid="'+lid+'" style="'+instStyle+'">';
                existInsts.forEach(function(ei, idx) {
                    var tmpId = _mplNextTmpId();
                    html += _buildProcInstanceHtml(lid, tmpId, itype, ntype, unit, subDefs, ei.inst, ei.subs, isRep, idx+1, lbl.label_name);
                });
                html += '</div></div>';
            }
        });
        html += '</div>';
        area.innerHTML = html;
        syncMakerProcLabels();
    });
}

function _buildProcInstanceHtml(parentLid, tmpId, itype, ntype, unit, subDefs, existInst, existSubs, isRep, instNum, labelName) {
    var html = '<div class="mpl-inst" data-lid="'+parentLid+'" data-tmp-id="'+tmpId+'" data-itype="'+escAttr(itype)+'" data-ntype="'+escAttr(ntype)+'" data-unit="'+escAttr(unit)+'" style="display:flex;align-items:center;flex-wrap:wrap;gap:4px;background:#fff;border:1px solid #e8e8e8;border-radius:5px;padding:3px 6px;">';
    if (isRep) html += '<span class="mpl-inst-num" style="font-size:10px;color:#bbb;min-width:16px;">#'+instNum+'</span>';
    if (itype === 'numeric') {
        var vmx = existInst && existInst.value_max !== null && String(existInst.value_max) !== '' ? fmtNum(existInst.value_max) : '';
        var vmn = existInst && existInst.value_min !== null && String(existInst.value_min) !== '' ? fmtNum(existInst.value_min) : '';
        var lblNameUp = (labelName||'').toUpperCase();
        if (ntype === 'range') {
            html += '<input type="number" class="form-control input-sm mpl-min-val" step="0.001" placeholder="最小" style="width:68px;" value="'+escAttr(String(vmn))+'" oninput="syncMakerProcLabels()">';
            html += '<span style="color:#aaa;font-size:11px;">~</span>';
            html += '<input type="number" class="form-control input-sm mpl-max-val" step="0.001" placeholder="最大" style="width:68px;" value="'+escAttr(String(vmx))+'" oninput="syncMakerProcLabels()">';
        } else if (ntype === 'MAX') {
            if (lblNameUp.indexOf('MAX') === -1) html += '<span style="font-size:11px;color:#555;">MAX</span>';
            html += '<input type="number" class="form-control input-sm mpl-max-val" step="0.001" placeholder="最大值" style="width:80px;" value="'+escAttr(String(vmx))+'" oninput="syncMakerProcLabels()">';
        } else if (ntype === 'MIN') {
            if (lblNameUp.indexOf('MIN') === -1) html += '<span style="font-size:11px;color:#555;">MIN</span>';
            html += '<input type="number" class="form-control input-sm mpl-min-val" step="0.001" placeholder="最小值" style="width:80px;" value="'+escAttr(String(vmn))+'" oninput="syncMakerProcLabels()">';
        }
        html += '<span style="font-size:11px;color:#888;">'+escHtml(unit)+'</span>';
    } else if (itype === 'text') {
        var vtxt = existInst && existInst.text_value !== null && existInst.text_value !== undefined ? existInst.text_value : '';
        html += '<input type="text" class="form-control input-sm mpl-text-val" maxlength="100" placeholder="文字說明" style="width:120px;" value="'+escAttr(String(vtxt))+'" oninput="syncMakerProcLabels()">';
    }
    (subDefs || []).forEach(function(sd) {
        var subTmpId = _mplNextTmpId();
        var exSub = (existSubs||[]).find(function(s){ return parseInt(s.proc_label_id,10)===parseInt(sd.proc_label_id,10); });
        html += _buildSubLabelInputHtml(sd, subTmpId, tmpId, exSub||null);
    });
    html += '<button type="button" class="mpl-remove-btn" onclick="removeProcInstance(this)" style="background:none;border:none;color:#c0392b;font-size:14px;padding:0 2px;cursor:pointer;line-height:1;" title="移除">×</button>';
    html += '</div>';
    return html;
}

function _buildSubLabelInputHtml(sd, subTmpId, parentTmpId, exSub) {
    var itype = sd.input_type || 'none';
    var ntype = sd.numeric_type || 'range';
    var unit  = sd.unit || 'mm';
    var html = '<span class="mpl-sub-row" data-lid="'+sd.proc_label_id+'" data-sub-tmp-id="'+subTmpId+'" data-parent-tmp-id="'+parentTmpId+'" data-itype="'+escAttr(itype)+'" data-ntype="'+escAttr(ntype)+'" data-unit="'+escAttr(unit)+'" style="display:inline-flex;align-items:center;gap:3px;">';
    html += '<span style="font-size:11px;color:#777;white-space:nowrap;margin-left:4px;">'+escHtml(sd.label_name)+':</span>';
    if (itype === 'numeric') {
        var vmx = exSub && exSub.value_max !== null && String(exSub.value_max) !== '' ? fmtNum(exSub.value_max) : '';
        var vmn = exSub && exSub.value_min !== null && String(exSub.value_min) !== '' ? fmtNum(exSub.value_min) : '';
        var subLblNameUp = (sd.label_name||'').toUpperCase();
        if (ntype === 'range') {
            html += '<input type="number" class="form-control input-sm mpl-min-val" step="0.001" placeholder="最小" style="width:58px;" value="'+escAttr(String(vmn))+'" oninput="syncMakerProcLabels()">';
            html += '<span style="color:#aaa;font-size:11px;">~</span>';
            html += '<input type="number" class="form-control input-sm mpl-max-val" step="0.001" placeholder="最大" style="width:58px;" value="'+escAttr(String(vmx))+'" oninput="syncMakerProcLabels()">';
        } else if (ntype === 'MAX') {
            if (subLblNameUp.indexOf('MAX') === -1) html += '<span style="font-size:11px;color:#555;">MAX</span>';
            html += '<input type="number" class="form-control input-sm mpl-max-val" step="0.001" placeholder="最大" style="width:70px;" value="'+escAttr(String(vmx))+'" oninput="syncMakerProcLabels()">';
        } else if (ntype === 'MIN') {
            if (subLblNameUp.indexOf('MIN') === -1) html += '<span style="font-size:11px;color:#555;">MIN</span>';
            html += '<input type="number" class="form-control input-sm mpl-min-val" step="0.001" placeholder="最小" style="width:70px;" value="'+escAttr(String(vmn))+'" oninput="syncMakerProcLabels()">';
        }
        html += '<span style="font-size:11px;color:#888;">'+escHtml(unit)+'</span>';
    } else if (itype === 'text') {
        var vtxt = exSub && exSub.text_value !== null && exSub.text_value !== undefined ? exSub.text_value : '';
        html += '<input type="text" class="form-control input-sm mpl-text-val" maxlength="100" placeholder="文字" style="width:100px;" value="'+escAttr(String(vtxt))+'" oninput="syncMakerProcLabels()">';
    }
    html += '</span>';
    return html;
}

function toggleMakerProcChip(chip) {
    if (!CAN_UPDATE && !CAN_CREATE) return;
    var lid    = chip.dataset.lid;
    var isRep  = chip.dataset.isRep === '1';
    var hasSubs = chip.dataset.hasSubs === '1';
    var isNow  = chip.dataset.selected === '1';

    if (!isRep && !hasSubs) {
        // Simple chip: toggle
        chip.dataset.selected = isNow ? '0' : '1';
        chip.querySelector('.fa').className = 'fa fa-' + (isNow ? 'circle-o' : 'check-circle');
        if (isNow) { chip.style.background='#f5f7fa'; chip.style.color='#888'; chip.style.borderColor='#ddd'; }
        else       { chip.style.background='#e8f5f2'; chip.style.color='#1ABB9C'; chip.style.borderColor='#1ABB9C'; }
        var inputs = document.querySelector('#mf-proc-label-area .mf-proc-inputs[data-lid="'+lid+'"]');
        if (inputs) {
            inputs.style.display = isNow ? 'none' : 'inline-flex';
            if (!isNow) { var fi = inputs.querySelector('input'); if (fi) setTimeout(function(){ fi.focus(); fi.select && fi.select(); },50); }
        }
    } else {
        // Complex chip: add instance
        var instArea = document.querySelector('#mf-proc-label-area .mpl-instances[data-parent-lid="'+lid+'"]');
        if (!isNow) {
            // Activate group
            chip.dataset.selected = '1';
            chip.querySelector('.fa').className = 'fa fa-check-circle';
            chip.style.background='#e8f5f2'; chip.style.color='#1ABB9C'; chip.style.borderColor='#1ABB9C';
            if (instArea) { instArea.style.display='flex'; instArea.style.flexDirection='column'; instArea.style.gap='4px'; }
        }
        _addProcInstanceToArea(lid, instArea, chip);
    }
    syncMakerProcLabels();
}

function _addProcInstanceToArea(lid, instArea, chip) {
    if (!instArea) return;
    var tmpId   = _mplNextTmpId();
    var itype   = chip ? (chip.dataset.itype||'none') : 'none';
    var ntype   = chip ? (chip.dataset.ntype||'range') : 'range';
    var unit    = chip ? (chip.dataset.unit||'mm') : 'mm';
    var isRep   = chip ? chip.dataset.isRep === '1' : false;
    var subDefs = _mplSubDefsMap[parseInt(lid,10)] || [];
    var instNum = instArea.querySelectorAll('.mpl-inst').length + 1;
    var div = document.createElement('div');
    var labelName = chip ? (chip.dataset.labelName||'') : '';
    div.innerHTML = _buildProcInstanceHtml(lid, tmpId, itype, ntype, unit, subDefs, null, [], isRep, instNum, labelName);
    instArea.appendChild(div.firstChild);
    _updateProcGroupChip(lid);
    if (isRep) {
        var grp = instArea.closest ? instArea.closest('.mpl-group') : null;
        if (grp && !grp.querySelector('.mpl-add-btn')) {
            var hdr = grp.querySelector('div');
            var btn = document.createElement('button');
            btn.type='button'; btn.className='btn btn-xs btn-default mpl-add-btn';
            btn.setAttribute('onclick',"addProcInstance('"+lid+"')");
            btn.style.cssText='padding:2px 7px;font-size:11px;'; btn.textContent='+ 新增一組';
            if (hdr) hdr.appendChild(btn);
        }
    }
    var fi = instArea.lastChild && instArea.lastChild.querySelector ? instArea.lastChild.querySelector('input') : null;
    if (fi) setTimeout(function(){ fi.focus(); fi.select && fi.select(); },50);
}

function addProcInstance(lid) {
    if (!CAN_UPDATE && !CAN_CREATE) return;
    var instArea = document.querySelector('#mf-proc-label-area .mpl-instances[data-parent-lid="'+lid+'"]');
    var chip = document.querySelector('#mf-proc-label-area .mf-proc-chip[data-lid="'+lid+'"]');
    _addProcInstanceToArea(String(lid), instArea, chip);
    syncMakerProcLabels();
}

function removeProcInstance(btn) {
    var inst = btn.closest ? btn.closest('.mpl-inst') : null;
    if (!inst) return;
    var instArea = inst.parentNode;
    var lid = inst.dataset.lid;
    instArea.removeChild(inst);
    if (!instArea.querySelector('.mpl-inst')) {
        instArea.style.display = 'none';
        var chip = document.querySelector('#mf-proc-label-area .mf-proc-chip[data-lid="'+lid+'"]');
        if (chip) {
            chip.dataset.selected = '0';
            chip.querySelector('.fa').className = 'fa fa-circle-o';
            chip.style.background='#f5f7fa'; chip.style.color='#888'; chip.style.borderColor='#ddd';
            var cnt = chip.querySelector('.mpl-count'); if (cnt) cnt.remove();
            var grp = chip.closest ? chip.closest('.mpl-group') : null;
            if (grp) { var ab = grp.querySelector('.mpl-add-btn'); if (ab) ab.remove(); }
        }
    } else {
        _updateProcGroupChip(lid);
        var nums = instArea.querySelectorAll('.mpl-inst-num');
        nums.forEach(function(n,i){ n.textContent='#'+(i+1); });
    }
    syncMakerProcLabels();
}

function _updateProcGroupChip(lid) {
    var chip = document.querySelector('#mf-proc-label-area .mf-proc-chip[data-lid="'+lid+'"]');
    if (!chip || chip.dataset.isRep !== '1') return;
    var instArea = document.querySelector('#mf-proc-label-area .mpl-instances[data-parent-lid="'+lid+'"]');
    var count = instArea ? instArea.querySelectorAll('.mpl-inst').length : 0;
    var cnt = chip.querySelector('.mpl-count');
    if (count > 0) {
        if (!cnt) { cnt=document.createElement('span'); cnt.className='mpl-count'; cnt.style.cssText='font-size:10px;background:rgba(0,0,0,0.12);border-radius:8px;padding:0 5px;margin-left:2px;'; chip.appendChild(cnt); }
        cnt.textContent='×'+count;
    } else if (cnt) { cnt.remove(); }
}

function syncMakerProcLabels() {
    var result = [];
    var autoN = 0;
    // Simple chips (not complex group chips)
    document.querySelectorAll('#mf-proc-label-area .mf-proc-chip[data-selected="1"]:not(.mpl-group-chip)').forEach(function(chip) {
        var lid   = chip.dataset.lid;
        var itype = chip.dataset.itype;
        var ntype = chip.dataset.ntype;
        var tmpId = 'ss'+(++autoN);
        var e = { proc_label_id: lid, tmp_id: tmpId, parent_tmp_id: null };
        if (itype === 'numeric') {
            var mn = document.querySelector('#mf-proc-label-area .mf-proc-min-val[data-lid="'+lid+'"]');
            var mx = document.querySelector('#mf-proc-label-area .mf-proc-max-val[data-lid="'+lid+'"]');
            if ((ntype==='range'||ntype==='MIN') && mn) e.value_min = mn.value;
            if ((ntype==='range'||ntype==='MAX') && mx) e.value_max = mx.value;
        } else if (itype === 'text') {
            var tv = document.querySelector('#mf-proc-label-area .mf-proc-text-val[data-lid="'+lid+'"]');
            if (tv) e.input_value = tv.value;
        }
        result.push(e);
    });
    // Complex instances
    document.querySelectorAll('#mf-proc-label-area .mpl-inst').forEach(function(inst) {
        var lid   = inst.dataset.lid;
        var itype = inst.dataset.itype;
        var ntype = inst.dataset.ntype;
        var tmpId = inst.dataset.tmpId;
        var e = { proc_label_id: lid, tmp_id: tmpId, parent_tmp_id: null };
        if (itype === 'numeric') {
            var pmn=null, pmx=null;
            inst.querySelectorAll('input').forEach(function(inp){
                if (inp.closest && inp.closest('.mpl-sub-row')) return;
                if (inp.classList.contains('mpl-min-val')) pmn=inp;
                if (inp.classList.contains('mpl-max-val')) pmx=inp;
            });
            if ((ntype==='range'||ntype==='MIN') && pmn) e.value_min = pmn.value;
            if ((ntype==='range'||ntype==='MAX') && pmx) e.value_max = pmx.value;
        } else if (itype === 'text') {
            var ptv=null;
            inst.querySelectorAll('input').forEach(function(inp){
                if (inp.closest && inp.closest('.mpl-sub-row')) return;
                if (inp.classList.contains('mpl-text-val')) ptv=inp;
            });
            if (ptv) e.input_value = ptv.value;
        }
        result.push(e);
        inst.querySelectorAll('.mpl-sub-row').forEach(function(sr) {
            var se = { proc_label_id: sr.dataset.lid, tmp_id: sr.dataset.subTmpId, parent_tmp_id: sr.dataset.parentTmpId };
            var sitype=sr.dataset.itype, sntype=sr.dataset.ntype;
            if (sitype==='numeric') {
                var smn=sr.querySelector('.mpl-min-val'), smx=sr.querySelector('.mpl-max-val');
                if ((sntype==='range'||sntype==='MIN') && smn) se.value_min=smn.value;
                if ((sntype==='range'||sntype==='MAX') && smx) se.value_max=smx.value;
            } else if (sitype==='text') {
                var stv=sr.querySelector('.mpl-text-val'); if(stv) se.input_value=stv.value;
            }
            result.push(se);
        });
    });
    var h = document.getElementById('mf-proc_labels');
    if (h) h.value = JSON.stringify(result);
}
function onMakerSettlementModeChange(val) {
    var dg = document.getElementById('mf-day-group');
    if (dg) dg.style.display = (val === 'FIXED') ? '' : 'none';
}
function _applyMakerPaymentDefaultHints(mode, day, pay, nd, dbConfirmSettle, dbConfirmPay) {
    var settleSame = (mode === SYS_VENDOR_DEFAULT_SETTLEMENT_MODE &&
        (mode !== 'FIXED' || String(day||'') === String(SYS_VENDOR_DEFAULT_SETTLEMENT_DAY||'')));
    var paySame = (pay === SYS_VENDOR_DEFAULT_PAYMENT_METHOD &&
        String(nd||'') === String(SYS_VENDOR_DEFAULT_NET_DAYS||''));
    var sh = document.getElementById('mf-settlement-default-hint');
    var ph = document.getElementById('mf-payment-default-hint');
    var cs = document.getElementById('mf-confirmed_settlement');
    var cp = document.getElementById('mf-confirmed_payment');
    if (sh) sh.style.display = settleSame ? '' : 'none';
    if (ph) ph.style.display = paySame    ? '' : 'none';
    if (cs) cs.checked = settleSame ? (dbConfirmSettle==1) : true;
    if (cp) cp.checked = paySame    ? (dbConfirmPay==1)    : true;
}

function submitMakerForm() {
    // 確保 sub_cats 與 proc_labels hidden 已同步
    syncSubCatHidden();
    syncMakerProcLabels();

    syncMakerContactsHidden();   // 確保 maker_contacts / contact_person 等 hidden 欄位同步
    var data = { action:'save_maker' };
    document.querySelectorAll('#makerForm input,#makerForm select,#makerForm textarea').forEach(function(el) {
        if (el.type==='checkbox') data[el.name] = el.checked ? 1 : 0;
        else data[el.name] = el.value;  // 包含所有 hidden fields
    });
    // sub_cats: 從持久清單取值（包含所有大類的勾選，即使某大類被切換隱藏也不遺失）
    data.sub_cats = JSON.stringify(_makerAllSelSubIds);

    // main_category_id: 取第一個選中的大類（存入 maker_list 欄位）
    var firstChip = document.querySelector('#mf-main-cat-chips-wrap .main-cat-chip[data-active="1"]');
    data.main_category_id = firstChip ? firstChip.dataset.id : '';

    if (!data.maker_id_no||!data.maker_id_no.trim()) { showToast('廠商編號不可為空','error'); return; }
    if (!data.maker_id||!data.maker_id.trim())        { showToast('廠商簡稱不可為空','error'); return; }

    var btn = document.querySelector('#makerModal .btn-success');
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> 儲存中…'; }
    var restore = function(){ if(btn){ btn.disabled=false; btn.innerHTML='<i class="fa fa-save"></i> 儲存'; } };
    apiOnce('save_maker', data,
        function(r) {
            restore();
            if (r.success) { showToast(r.message,'success'); $('#makerModal').modal('hide'); loadMakers(makersCurrent); }
            else showToast(r.message,'error');
        },
        function(){ restore(); showToast('網路錯誤','error'); }
    );
}

// deleteMaker() 已定義在客戶區塊後，此為舊版佔位，不再使用

// ── 廠商歷史編號管理 ─────────────────────────────────────────────────────
function renderMakerAliases(list) {
    var wrap = document.getElementById('mf-aliases-wrap');
    if (!wrap) return;
    if (!list || !list.length) {
        wrap.innerHTML = '<span style="color:#aaa;font-size:12px;">尚無歷史編號</span>';
        return;
    }
    wrap.innerHTML = list.map(function(a) {
        return '<span style="display:inline-flex;align-items:center;gap:5px;background:#f3e5f5;color:#8e44ad;border:1px solid #ce93d8;border-radius:14px;padding:2px 10px;font-size:12px;font-weight:600;">'
            + '<i class="fa fa-history" style="font-size:10px;opacity:.7;"></i>'
            + escHtml(a.old_id)
            + (a.old_name ? '<span style="font-weight:normal;color:#555;">（'+escHtml(a.old_name)+'）</span>' : '')
            + '<button type="button" onclick="removeMakerAlias('+a.alias_id+',this)" style="background:none;border:none;cursor:pointer;color:#8e44ad;padding:0;margin-left:2px;font-size:11px;" title="移除連結"><i class="fa fa-times"></i></button>'
            + '</span>';
    }).join('');
}

function addMakerAlias() {
    var mid = document.getElementById('mf-maker_id_no').value.trim();
    var old_id = document.getElementById('mf-alias-input').value.trim().toUpperCase();
    if (!mid) { showToast('請先儲存廠商後再連結歷史編號','error'); return; }
    if (!old_id) { showToast('請輸入舊廠商編號','error'); return; }
    api({ action:'add_maker_alias', maker_id_no:mid, old_id:old_id }).done(function(r) {
        if (!r.success) { showToast(r.message,'error'); return; }
        document.getElementById('mf-alias-input').value = '';
        // 加入新 chip
        var wrap = document.getElementById('mf-aliases-wrap');
        if (wrap.querySelector('span[style*="aaa"]')) wrap.innerHTML = '';
        var a = r.alias;
        var chip = document.createElement('span');
        chip.style.cssText = 'display:inline-flex;align-items:center;gap:5px;background:#f3e5f5;color:#8e44ad;border:1px solid #ce93d8;border-radius:14px;padding:2px 10px;font-size:12px;font-weight:600;';
        chip.innerHTML = '<i class="fa fa-history" style="font-size:10px;opacity:.7;"></i>'
            + escHtml(a.old_id)
            + (a.old_name ? '<span style="font-weight:normal;color:#555;">（'+escHtml(a.old_name)+'）</span>' : '')
            + '<button type="button" onclick="removeMakerAlias('+a.alias_id+',this)" style="background:none;border:none;cursor:pointer;color:#8e44ad;padding:0;margin-left:2px;font-size:11px;" title="移除連結"><i class="fa fa-times"></i></button>';
        wrap.appendChild(chip);
        showToast('已連結舊編號 '+a.old_id,'success');
    });
}

function removeMakerAlias(alias_id, btn) {
    if (!confirm('確定移除此歷史編號的連結？')) return;
    api({ action:'remove_maker_alias', alias_id:alias_id }).done(function(r) {
        if (r.success) {
            var chip = btn.closest ? btn.closest('span') : btn.parentNode;
            if (chip) chip.remove();
            var wrap = document.getElementById('mf-aliases-wrap');
            if (wrap && !wrap.querySelector('span[style]')) {
                wrap.innerHTML = '<span style="color:#aaa;font-size:12px;">尚無歷史編號</span>';
            }
        } else showToast(r.message,'error');
    });
}

// ─── 字典設定邏輯 ───────────────────────────────────
var currentDictType = 'workpiece';

// Config per dict type
var dictConfig = {
    'workpiece': {
        title: '工件種類',
        desc: '對應料號 Type 欄位',
        action: 'manage_workpiece_types',
        hint: '代碼須與資料庫 Type 欄位值一致（例：N、G、H）',
        getId:   function(d){ return d.type_code; },
        getName: function(d){ return d.type_name; },
        renderRow: function(d) {
            var badges = '';
            var f = [];
            if (Number(d.show_vendor))  f.push('廠商');
            if (Number(d.show_part_no)) f.push('專用料號');
            if (Number(d.show_machine)) f.push('專用機台');
            if (Number(d.show_price))   f.push('價格');
            if (f.length) badges = ' <span style="font-size:10px;color:#3949ab;background:#e8eaf6;border-radius:3px;padding:1px 5px;margin-left:4px;">'+f.join('、')+'</span>';
            return '<span class="dict-code-badge">'+escHtml(d.type_code)+'</span>'+escHtml(d.type_name)+badges;
        },
        renderForm: function() {
            var html = '';
            html += '<div><label style="font-size:11px;color:#888;margin-bottom:3px;">種類代碼 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-code" class="form-control input-sm" style="width:80px;" maxlength="10" placeholder="例：N" oninput="this.value=this.value.toUpperCase()"></div>';
            html += '<div style="flex:1;"><label style="font-size:11px;color:#888;margin-bottom:3px;">種類名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：一般、齒輪、滾刀" maxlength="50"></div>';
            html += dictSaveBtn();
            // 料號表單欄位顯示設定（此種類的料號才會出現這些欄位）
            html += '<div style="width:100%;flex-basis:100%;margin-top:8px;border-top:1px dashed #ddd;padding-top:8px;">';
            html += '<label style="font-size:11px;color:#888;margin-bottom:4px;display:block;">料號表單顯示欄位（勾選後，此工件種類的料號新增/編輯會出現對應欄位）</label>';
            html += '<div style="display:flex;flex-wrap:wrap;gap:14px;font-size:13px;">';
            html += '<label style="font-weight:normal;cursor:pointer;"><input type="checkbox" id="dict-f-show_vendor" style="vertical-align:-1px;margin-right:4px;">廠商<span style="color:#aaa;">（可多選）</span></label>';
            html += '<label style="font-weight:normal;cursor:pointer;"><input type="checkbox" id="dict-f-show_part_no" style="vertical-align:-1px;margin-right:4px;">專用料號<span style="color:#aaa;">（可多選）</span></label>';
            html += '<label style="font-weight:normal;cursor:pointer;"><input type="checkbox" id="dict-f-show_machine" style="vertical-align:-1px;margin-right:4px;">專用機台<span style="color:#aaa;">（可多選）</span></label>';
            html += '<label style="font-weight:normal;cursor:pointer;"><input type="checkbox" id="dict-f-show_price" style="vertical-align:-1px;margin-right:4px;">價格<span style="color:#aaa;">（每廠商一價）</span></label>';
            html += '</div></div>';
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-code').val(d.type_code).prop('readonly',true).css('background','#f5f5f5');
            $('#dict-f-name').val(d.type_name);
            $('#dict-f-show_vendor').prop('checked', Number(d.show_vendor)===1);
            $('#dict-f-show_part_no').prop('checked', Number(d.show_part_no)===1);
            $('#dict-f-show_machine').prop('checked', Number(d.show_machine)===1);
            $('#dict-f-show_price').prop('checked', Number(d.show_price)===1);
        },
        getData: function() {
            var code = $('#dict-f-code').val().trim();
            var name = $('#dict-f-name').val().trim();
            if (!code) { showToast('請填寫種類代碼','error'); return null; }
            if (!name) { showToast('請填寫種類名稱','error'); return null; }
            return {
                action:'manage_workpiece_types', op:'save', type_code:code, type_name:name,
                show_vendor:  $('#dict-f-show_vendor').prop('checked')  ? 1 : 0,
                show_part_no: $('#dict-f-show_part_no').prop('checked') ? 1 : 0,
                show_machine: $('#dict-f-show_machine').prop('checked') ? 1 : 0,
                show_price:   $('#dict-f-show_price').prop('checked')   ? 1 : 0
            };
        },
        getDeleteId: function(d){ return d.type_code; }
    },
    'workpiece-sub': {
        title: '工件小類',
        desc:  '每個工件種類可設定多個小類',
        action:'manage_workpiece_sub_types',
        hint:  '先選擇所屬工件種類，再新增小類名稱。小類可用於料號快篩。',
        getId:   function(d){ return d.sub_type_id; },
        getName: function(d){ return d.sub_type_name; },
        renderRow: function(d) {
            var pal = _wpPalette[0];
            return '<span style="font-size:10px;background:'+pal.sel+';color:#fff;border-radius:3px;padding:1px 5px;margin-right:4px;">'+escHtml(d.type_code||'')+'</span>'+escHtml(d.sub_type_name);
        },
        renderForm: function() {
            var html = '<div style="width:100%;">';
            html += '<div style="display:flex;gap:8px;margin-bottom:8px;">';
            html += '<div><label style="font-size:11px;color:#888;margin-bottom:3px;">所屬工件種類 <span style="color:red;">*</span></label>';
            html += '<select id="dict-f-wp-type" class="form-control input-sm" style="min-width:130px;" onchange="onWpSubTypeChange(this.value)">';
            html += '<option value="">— 選擇種類 —</option>';
            html += '</select></div>';
            html += '<div style="flex:1;"><label style="font-size:11px;color:#888;margin-bottom:3px;">小類名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：外齒輪、內齒輪、蝸桿" maxlength="50"></div>';
            html += dictSaveBtn();
            html += '</div></div>';
            // Load workpiece types into select
            api({ action:'manage_workpiece_types', op:'list' }).done(function(r) {
                if (!r.success) return;
                var s = document.getElementById('dict-f-wp-type');
                if (!s) return;
                r.data.forEach(function(t) {
                    s.appendChild(new Option(t.type_code + ' — ' + t.type_name, t.type_code));
                });
            });
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-name').val(d.sub_type_name);
            setTimeout(function(){
                var s = document.getElementById('dict-f-wp-type');
                if (s) { s.value = d.type_code||''; s.disabled = true; s.style.background='#f5f5f5'; }
            }, 300);
        },
        getData: function() {
            var name     = $('#dict-f-name').val().trim();
            var typeCode = (document.getElementById('dict-f-wp-type')||{}).value||'';
            if (!name)     { showToast('請填寫小類名稱','error'); return null; }
            if (!typeCode) { showToast('請選擇所屬工件種類','error'); return null; }
            var id = $('#dict-edit-id').val();
            return { action:'manage_workpiece_sub_types', op:'save', sub_type_id:id, sub_type_name:name, type_code:typeCode };
        },
        getDeleteId: function(d){ return d.sub_type_id; }
    },
    'gear': {
        title: '齒輪類型',
        desc: '控制前端螺旋角欄位顯示，並可設定各欄位的顯示/必填',
        action: 'manage_gear_types',
        hint: '勾選「有螺旋角」後料號設定中顯示旋向與螺旋角',
        getId:   function(d){ return d.gear_type_id; },
        getName: function(d){ return d.type_name||''; },
        renderRow: function(d) {
            var name = d.type_name||'';
            var helix = (d.has_helix_angle=='1'||d.has_helix_angle===1)
                ? '<span class="dict-helix-badge"><i class="fa fa-refresh"></i> 有螺旋角</span>' : '';
            return escHtml(name) + helix;
        },
        renderForm: function() {
            var html = '<div style="display:flex;flex-wrap:wrap;gap:8px;width:100%;">';
            html += '<div style="flex:1;min-width:150px;"><label style="font-size:11px;color:#888;margin-bottom:3px;">齒輪類型名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：直齒、螺旋齒、鏈輪" maxlength="50"></div>';
            html += '<div style="flex:0 0 auto;"><label style="font-size:11px;color:#888;margin-bottom:3px;">欄位類別</label>';
            html += '<select id="dict-f-spec-cat" class="form-control input-sm" style="width:130px;" onchange="updateTmplVarChips()">';
            html += '<option value="standard">standard（標準齒輪）</option>';
            html += '<option value="sprocket">sprocket（鏈輪）</option>';
            html += '<option value="timing_pulley">timing_pulley（皮帶輪）</option>';
            html += '<option value="spline">spline（花鍵）</option>';
            html += '<option value="worm_gear">worm_gear（蝸桿）</option>';
            html += '<option value="worm_wheel">worm_wheel（蝸輪）</option>';
            html += '<option value="rack">rack（齒條）</option>';
            html += '</select></div>';
            html += '<div style="display:flex;align-items:flex-end;padding-bottom:2px;">';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;">';
            html += '<input type="checkbox" id="dict-f-helix" style="margin-right:4px;" onchange="updateTmplVarChips()"> 有螺旋角';
            html += '</label></div>';
            html += '</div>'; // end flex row 1
            html += '<div style="margin-top:6px;">';
            html += '<label style="font-size:11px;color:#888;margin-bottom:3px;">規格短字串模板</label>';
            html += '<div style="display:flex;gap:4px;align-items:center;">';
            html += '<input type="text" id="dict-f-display-tmpl" class="form-control input-sm" maxlength="300" placeholder="{Module}×{Teeth}T PA{Pressure_Angle}°" style="flex:1;">';
            html += '<button type="button" class="btn btn-default btn-xs" onclick="$(\'#dict-f-display-tmpl\').val(\'\').focus()" title="清除模板" style="white-space:nowrap;flex-shrink:0;">清除</button>';
            html += '</div>';
            html += '<div id="tmpl-var-chips" style="display:flex;flex-wrap:wrap;gap:4px;margin-top:5px;"></div>';
            html += '</div>';
            html += '<div style="margin-top:6px;">';
            html += dictSaveBtn();
            html += '</div>';
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-name').val(d.type_name||'');
            $('#dict-f-helix').prop('checked', d.has_helix_angle=='1'||d.has_helix_angle===1);
            $('#dict-f-spec-cat').val(d.spec_category||'standard');
            $('#dict-f-display-tmpl').val(d.display_template||'');
            updateTmplVarChips();
        },
        getData: function() {
            var name = $('#dict-f-name').val().trim();
            if (!name) { showToast('請填寫齒輪類型名稱','error'); return null; }
            var helix = $('#dict-f-helix').is(':checked') ? 1 : 0;
            var id = $('#dict-edit-id').val();
            var specCat = ($('#dict-f-spec-cat').val()||'standard');
            var tmpl    = ($('#dict-f-display-tmpl').val()||'').trim();
            return { action:'manage_gear_types', op:'save', gear_type_id:id, type_name:name, has_helix_angle:helix, spec_category:specCat, display_template:tmpl };
        },
        getDeleteId: function(d){ return d.gear_type_id; }
    },
    'label': {
        title: '料號標籤',
        desc:  '依料號種類設定可選標籤',
        action: 'manage_labels',
        hint:  '標籤可同時屬於多個料號種類；可設定輸入類型、圖面與車床尺寸；並可在新增時直接設定子標籤',
        getId:   function(d){ return d.label_id; },
        getName: function(d){ return d.label_name||''; },
        renderRow: function(d) {
            var itMap = {none:'無輸入', number:'數字', text:'文字'};
            var itBadge = '<span style="font-size:10px;background:#e8f5f2;color:#1ABB9C;border-radius:3px;padding:1px 4px;margin-left:3px;">'+(itMap[d.input_type]||d.input_type)+'</span>';
            var repBadge = (d.is_repeatable=='1'||d.is_repeatable===1)
                ? '<span style="font-size:10px;background:#fff3cd;color:#856404;border-radius:3px;padding:1px 4px;margin-left:3px;">多次</span>' : '';
            var dlBadge  = (d.has_draw_lathe=='1'||d.has_draw_lathe===1)
                ? '<span style="font-size:10px;background:#e8eeff;color:#5856d6;border-radius:3px;padding:1px 4px;margin-left:3px;">圖+車</span>' : '';
            var latheOptBadge = ((d.has_draw_lathe=='1'||d.has_draw_lathe===1) && (d.lathe_optional=='1'||d.lathe_optional===1))
                ? '<span style="font-size:10px;background:#ede8ff;color:#5856d6;border-radius:3px;padding:1px 4px;margin-left:2px;">車可省略</span>' : '';
            var rngBadge = (d.is_range=='1'||d.is_range===1)
                ? '<span style="font-size:10px;background:#fff0f6;color:#c0392b;border-radius:3px;padding:1px 4px;margin-left:3px;">範圍</span>' : '';
            var tolBadge = (d.has_tolerance=='1'||d.has_tolerance===1)
                ? '<span style="font-size:10px;background:#fff8e1;color:#f57f17;border-radius:3px;padding:1px 4px;margin-left:3px;">公差</span>' : '';
            var calcBadge = (d.is_calc_diff=='1'||d.is_calc_diff===1)
                ? '<span style="font-size:10px;background:#f3e5f5;color:#7b1fa2;border-radius:3px;padding:1px 4px;margin-left:3px;">計算差異</span>' : '';
            var exclBadge = (d.is_exclude_calc=='1'||d.is_exclude_calc===1)
                ? '<span style="font-size:10px;background:#fbe9e7;color:#bf360c;border-radius:3px;padding:1px 4px;margin-left:3px;">不計算</span>' : '';
            var dimBadge  = (d.is_dimension=='1'||d.is_dimension===1)
                ? '<span style="font-size:10px;background:#e3f2fd;color:#1565C0;border-radius:3px;padding:1px 4px;margin-left:3px;">長×寬</span>' : '';
            var qtyDimBadge = (d.is_qty_dim=='1'||d.is_qty_dim===1)
                ? '<span style="font-size:10px;background:#f3e5f5;color:#6a1a9a;border-radius:3px;padding:1px 4px;margin-left:3px;">數量-長×寬</span>' : '';
            var hiddenBadge = (d.is_hidden_frontend=='1'||d.is_hidden_frontend===1)
                ? '<span style="font-size:10px;background:#eceff1;color:#78909c;border-radius:3px;padding:1px 4px;margin-left:3px;">隱藏</span>' : '';
            var pfxBadge  = (d.prefix_char) ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">前'+escHtml(d.prefix_char)+'</span>' : '';
            var sfxBadge  = (d.suffix_char) ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">後'+escHtml(d.suffix_char)+'</span>' : '';
            return '<strong style="font-size:12px;">'+escHtml(d.label_name||'')+'</strong>' + itBadge + repBadge + dlBadge + latheOptBadge + rngBadge + tolBadge + calcBadge + exclBadge + dimBadge + qtyDimBadge + pfxBadge + sfxBadge + hiddenBadge;
        },
        renderForm: function() {
            var html = '<div style="width:100%;">';
            // Row 1: name + input type + save/clear
            html += '<div style="display:flex;gap:8px;align-items:flex-end;margin-bottom:6px;">';
            html += '<div style="flex:1;min-width:0;"><label style="font-size:11px;color:#888;margin-bottom:2px;">標籤名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：軸鍵、滾齒、厚度" maxlength="50" style="width:100%;" onblur="checkLabelNameSimilar(this.value)">';
            html += '<div style="font-size:10px;color:#999;margin-top:2px;"><i class="fa fa-info-circle" style="color:#e67e22;"></i> 名稱中 <code style="background:#f5f5f5;padding:0 3px;border-radius:2px;">[提示文字]</code> 不顯示於前端（料號列表、新增修改畫面）</div></div>';
            html += '<div><label style="font-size:11px;color:#888;margin-bottom:2px;">輸入類型</label>';
            html += '<select id="dict-f-lbl-input" class="form-control input-sm" style="width:72px;" onchange="onLblInputTypeChange(this.value)"><option value="none">無</option><option value="number">數字</option><option value="text">文字</option></select></div>';
            html += dictSaveBtn();
            html += '</div>';
            // Row 2: checkboxes only
            html += '<div style="display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin-bottom:8px;">';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;"><input type="checkbox" id="dict-f-lbl-rep" style="margin-right:3px;"> 可多次</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;"><input type="checkbox" id="dict-f-lbl-dl" style="margin-right:3px;" onchange="onLblDlChange(this.checked)"> 圖面+車床</label>';
            html += '<label id="dict-f-lbl-lathe-opt-lbl" style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#5856d6;display:none;"><input type="checkbox" id="dict-f-lbl-lathe-opt" style="margin-right:3px;"> 車可省略</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#00695c;"><input type="checkbox" id="dict-f-lbl-dl-depth" style="margin-right:3px;" onchange="onLblDlDepthChange(this.checked)"> 圖面+車床×深度</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#5d4037;"><input type="checkbox" id="dict-f-lbl-triple-dim" style="margin-right:3px;" onchange="onLblTripleDimChange(this.checked)"> 前綴小圓x前綴大圓x深度後綴</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;"><input type="checkbox" id="dict-f-lbl-range" style="margin-right:3px;" onchange="onLblRangeChange(this.checked)"> 範圍</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#f57f17;"><input type="checkbox" id="dict-f-lbl-tol" style="margin-right:3px;" onchange="onLblTolChange(this.checked)"> 公差</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#7b1fa2;"><input type="checkbox" id="dict-f-lbl-calc" style="margin-right:3px;" onchange="onLblCalcChange(this.checked)"> 計算差異</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#bf360c;"><input type="checkbox" id="dict-f-lbl-excl-calc" style="margin-right:3px;"> 不列入計算用</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#1565C0;"><input type="checkbox" id="dict-f-lbl-dim" style="margin-right:3px;" onchange="onLblDimChange(this.checked)"> 長×寬(圓×深)</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#6a1a9a;"><input type="checkbox" id="dict-f-lbl-qty-dim" style="margin-right:3px;" onchange="onLblQtyDimChange(this.checked)"> 數量-長×寬</label>';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;white-space:nowrap;margin:0;color:#546e7a;"><input type="checkbox" id="dict-f-lbl-hidden-fe" style="margin-right:3px;"> 不顯示於前端</label>';
            html += '</div>';
            html += '<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:flex-end;margin-bottom:4px;">';
            html += '<div><label style="font-size:10px;color:#888;margin-bottom:2px;">前綴字元 <span style="font-size:9px;color:#aaa;">(適用長×寬/數量-長×寬)</span></label>';
            html += '<input type="text" id="dict-f-lbl-prefix" class="form-control input-sm" style="width:80px;" placeholder="例：M" maxlength="10"></div>';
            html += '<div><label style="font-size:10px;color:#888;margin-bottom:2px;">後綴字元</label>';
            html += '<input type="text" id="dict-f-lbl-suffix" class="form-control input-sm" style="width:80px;" placeholder="" maxlength="10"></div>';
            html += '</div>';
            // 計算差異設定面板
            html += '<div id="dict-f-calc-panel" style="display:none;margin-top:2px;margin-bottom:8px;padding:8px;background:#f9f0ff;border:1px solid #ce93d8;border-radius:6px;">';
            html += '<div style="font-size:11px;font-weight:600;color:#7b1fa2;margin-bottom:6px;"><i class="fa fa-calculator"></i> 計算差異設定</div>';
            html += '<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:flex-end;">';
            html += '<div style="flex:1;min-width:130px;"><label style="font-size:10px;color:#888;">基準項名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-calc-base-name" class="form-control input-sm" placeholder="例：粗滾" maxlength="50" style="font-size:11px;"></div>';
            html += '<div style="flex:1;min-width:130px;"><label style="font-size:10px;color:#888;">減項名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-calc-sub-name" class="form-control input-sm" placeholder="例：齒研" maxlength="50" style="font-size:11px;"></div>';
            html += '<div style="flex:1;min-width:120px;"><label style="font-size:10px;color:#888;">減項上公差標準值</label>';
            html += '<input type="number" id="dict-f-tol-std-upper" class="form-control input-sm" step="0.0001" placeholder="例：-0.02" style="font-size:11px;"></div>';
            html += '</div></div>';
            // Row 2: type_code checkboxes
            html += '<div style="margin-top:8px;"><label style="font-size:11px;color:#888;margin-bottom:4px;display:block;">所屬料號種類 <span style="color:red;">*</span> <span style="font-size:10px;color:#aaa;">（可多選，標籤將同時出現在所選種類）</span></label>';
            html += '<div id="dict-f-lbl-type-wrap" style="display:flex;flex-wrap:wrap;gap:6px;padding:6px 8px;background:#f9f9f9;border:1px solid #e5e5e5;border-radius:4px;min-height:32px;"><span style="color:#aaa;font-size:11px;">載入中…</span></div></div>';
            // 子標籤切換列
            html += '<div style="margin-top:8px;">';
            html += '<label style="font-weight:normal;cursor:pointer;font-size:12px;margin:0;color:#1ABB9C;">';
            html += '<input type="checkbox" id="dict-f-lbl-has-sub" style="margin-right:5px;" onchange="toggleLabelSubPanel(this.checked)">';
            html += '<i class="fa fa-sitemap"></i> 設定子標籤</label></div>';
            html += '</div>';
            // load type checkboxes async
            api({ action:'manage_workpiece_types', op:'list' }).done(function(r) {
                var w = document.getElementById('dict-f-lbl-type-wrap');
                if (!w || !r.success) return;
                w.innerHTML = '';
                r.data.forEach(function(t) {
                    var lbl = document.createElement('label');
                    lbl.style.cssText = 'font-weight:normal;cursor:pointer;font-size:12px;margin:0;display:inline-flex;align-items:center;gap:3px;background:#fff;border:1px solid #ddd;border-radius:3px;padding:2px 8px;';
                    lbl.innerHTML = '<input type="checkbox" class="lbl-type-cb" value="'+t.type_code+'" style="margin:0;"> <span>'+escHtml(t.type_code+' '+t.type_name)+'</span>';
                    w.appendChild(lbl);
                });
            });
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-name').val(d.label_name||'');
            var hasDl       = (d.has_draw_lathe=='1'||d.has_draw_lathe===1);
            var hasDlDepth  = (d.has_draw_lathe_depth=='1'||d.has_draw_lathe_depth===1);
            var isTripleDim = (d.is_triple_dim=='1'||d.is_triple_dim===1);
            var isRng      = (d.is_range=='1'||d.is_range===1);
            var hasTol     = (d.has_tolerance=='1'||d.has_tolerance===1);
            var isCalc     = (d.is_calc_diff=='1'||d.is_calc_diff===1);
            var isDim      = (d.is_dimension=='1'||d.is_dimension===1);
            var isQtyDim   = (d.is_qty_dim=='1'||d.is_qty_dim===1);
            var itVal  = (hasDl||hasDlDepth||isTripleDim||isRng||hasTol||isDim||isQtyDim) ? 'number' : (d.input_type||'none');
            $('#dict-f-lbl-input').val(itVal);
            $('#dict-f-lbl-rep').prop('checked', d.is_repeatable=='1'||d.is_repeatable===1);
            var latheOpt = (d.lathe_optional=='1'||d.lathe_optional===1);
            $('#dict-f-lbl-dl').prop('checked', hasDl);
            $('#dict-f-lbl-dl-depth').prop('checked', hasDlDepth);
            $('#dict-f-lbl-triple-dim').prop('checked', isTripleDim);
            $('#dict-f-lbl-lathe-opt').prop('checked', hasDl && latheOpt);
            $('#dict-f-lbl-lathe-opt-lbl').toggle(hasDl);
            $('#dict-f-lbl-range').prop('checked', isRng);
            $('#dict-f-lbl-tol').prop('checked', hasTol);
            $('#dict-f-lbl-calc').prop('checked', isCalc);
            $('#dict-f-lbl-excl-calc').prop('checked', d.is_exclude_calc=='1'||d.is_exclude_calc===1);
            $('#dict-f-lbl-dim').prop('checked', isDim);
            $('#dict-f-lbl-qty-dim').prop('checked', isQtyDim);
            $('#dict-f-lbl-hidden-fe').prop('checked', d.is_hidden_frontend=='1'||d.is_hidden_frontend===1);
            $('#dict-f-lbl-prefix').val(d.prefix_char||'');
            $('#dict-f-lbl-suffix').val(d.suffix_char||'');
            if (hasDl) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-range').prop('disabled', true);
                $('#dict-f-lbl-dim').prop('disabled', true);
                $('#dict-f-lbl-dl-depth').prop('disabled', true);
            } else if (hasDlDepth) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-dl').prop('disabled', true);
                $('#dict-f-lbl-range').prop('disabled', true);
                $('#dict-f-lbl-tol').prop('disabled', true);
                $('#dict-f-lbl-calc').prop('disabled', true);
                $('#dict-f-lbl-dim').prop('disabled', true);
                $('#dict-f-lbl-qty-dim').prop('disabled', true);
                $('#dict-f-lbl-triple-dim').prop('disabled', true);
            } else if (isTripleDim) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-dl').prop('disabled', true);
                $('#dict-f-lbl-dl-depth').prop('disabled', true);
                $('#dict-f-lbl-range').prop('disabled', true);
                $('#dict-f-lbl-tol').prop('disabled', true);
                $('#dict-f-lbl-calc').prop('disabled', true);
                $('#dict-f-lbl-dim').prop('disabled', true);
                $('#dict-f-lbl-qty-dim').prop('disabled', true);
            } else if (isRng) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-tol').prop('checked', false).prop('disabled', true);
                $('#dict-f-lbl-dim').prop('disabled', true);
            } else if (hasTol) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-range').prop('checked', false).prop('disabled', true);
                $('#dict-f-lbl-calc').prop('disabled', true);
                $('#dict-f-lbl-dim').prop('disabled', true);
            } else if (isDim) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-dl').prop('disabled', true);
                $('#dict-f-lbl-range').prop('disabled', true);
                $('#dict-f-lbl-tol').prop('disabled', true);
                $('#dict-f-lbl-calc').prop('disabled', true);
                $('#dict-f-lbl-qty-dim').prop('disabled', true);
            } else if (isQtyDim) {
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-lbl-dl').prop('disabled', true);
                $('#dict-f-lbl-range').prop('disabled', true);
                $('#dict-f-lbl-tol').prop('disabled', true);
                $('#dict-f-lbl-calc').prop('disabled', true);
                $('#dict-f-lbl-dim').prop('disabled', true);
            } else {
                $('#dict-f-lbl-input').prop('disabled', false);
                $('#dict-f-lbl-range').prop('disabled', false);
                $('#dict-f-lbl-dim').prop('disabled', false);
                $('#dict-f-lbl-qty-dim').prop('disabled', false);
            }
            if (isCalc) {
                $('#dict-f-lbl-tol').prop('checked', false).prop('disabled', true);
                $('#dict-f-lbl-input').prop('disabled', true).val('number');
                $('#dict-f-calc-panel').show();
                $('#dict-f-calc-base-name').val(d.calc_base_name||'');
                $('#dict-f-calc-sub-name').val(d.calc_sub_name||'');
                $('#dict-f-tol-std-upper').val(d.tolerance_std_upper||'');
            } else {
                $('#dict-f-lbl-tol').prop('disabled', false);
                $('#dict-f-calc-panel').hide();
            }
            // Set type checkboxes (multi-value comma-separated)
            var types = (d.type_code||'').split(',').map(function(s){ return s.trim(); });
            setTimeout(function(){
                document.querySelectorAll('.lbl-type-cb').forEach(function(cb) {
                    cb.checked = types.indexOf(cb.value) >= 0;
                });
            }, 350);
            // Load sub-labels (edit mode)
            _pendingSubLabels = [];
            $('#dict-sub-mode-hint').text('');
            $('#dict-f-sub-id').val('');
            loadLabelSubs(d.label_id);
        },
        getData: function() {
            var name  = $('#dict-f-name').val().trim();
            var types = [];
            document.querySelectorAll('.lbl-type-cb:checked').forEach(function(cb){ types.push(cb.value); });
            var tc     = types.join(',');
            var hasDl        = $('#dict-f-lbl-dl').is(':checked') ? 1 : 0;
            var hasDlDepth   = (!hasDl && $('#dict-f-lbl-dl-depth').is(':checked')) ? 1 : 0;
            var isTripleDimG = (!hasDl && !hasDlDepth && $('#dict-f-lbl-triple-dim').is(':checked')) ? 1 : 0;
            var latheOpt   = (hasDl && $('#dict-f-lbl-lathe-opt').is(':checked')) ? 1 : 0;
            var isRng  = (!hasDl && !hasDlDepth && !isTripleDimG && $('#dict-f-lbl-range').is(':checked')) ? 1 : 0;
            var hasTol = (!isRng && $('#dict-f-lbl-tol').is(':checked')) ? 1 : 0;
            var isCalc = (!hasDlDepth && !isTripleDimG && $('#dict-f-lbl-calc').is(':checked')) ? 1 : 0;
            var isDim    = (!hasDl && !hasDlDepth && !isTripleDimG && !isRng && !hasTol && !isCalc && $('#dict-f-lbl-dim').is(':checked')) ? 1 : 0;
            var isQtyDim = (!hasDl && !hasDlDepth && !isTripleDimG && !isRng && !hasTol && !isCalc && !isDim && $('#dict-f-lbl-qty-dim').is(':checked')) ? 1 : 0;
            var isHidFe  = $('#dict-f-lbl-hidden-fe').is(':checked') ? 1 : 0;
            var pfxChar  = ($('#dict-f-lbl-prefix').val()||'').trim();
            var sfxChar  = ($('#dict-f-lbl-suffix').val()||'').trim();
            var it       = (hasDl || hasDlDepth || isTripleDimG || isRng || hasTol || isCalc || isDim || isQtyDim) ? 'number' : ($('#dict-f-lbl-input').val()||'none');
            var rep    = $('#dict-f-lbl-rep').is(':checked') ? 1 : 0;
            var id     = $('#dict-edit-id').val();
            if (!name) { showToast('請填寫標籤名稱','error'); return null; }
            if (!tc)   { showToast('請至少選擇一個料號種類','error'); return null; }
            var calcBaseName = isCalc ? ($('#dict-f-calc-base-name').val()||'').trim() : '';
            var calcSubName  = isCalc ? ($('#dict-f-calc-sub-name').val()||'').trim() : '';
            var tolStd       = isCalc ? ($('#dict-f-tol-std-upper').val()||'') : '';
            // Include pending subs (for new label creation)
            var subsJson = (!id && _pendingSubLabels.length) ? JSON.stringify(_pendingSubLabels.map(function(s){
                s.is_range = s.is_range||0; return s;
            })) : '[]';
            var exclCalc = $('#dict-f-lbl-excl-calc').is(':checked') ? 1 : 0;
            return { action:'manage_labels', op:'save', label_id:id, label_name:name, type_code:tc, input_type:it,
                     is_repeatable:rep, has_draw_lathe:hasDl, lathe_optional:latheOpt, has_draw_lathe_depth:hasDlDepth, is_triple_dim:isTripleDimG,
                     is_range:isRng, has_tolerance:hasTol, is_calc_diff:isCalc,
                     calc_base_name:calcBaseName, calc_sub_name:calcSubName,
                     tolerance_std_upper:tolStd, is_exclude_calc:exclCalc, is_dimension:isDim,
                     is_qty_dim:isQtyDim, prefix_char:pfxChar, suffix_char:sfxChar,
                     is_hidden_frontend:isHidFe, subs_json:subsJson };
        },
        getDeleteId: function(d){ return d.label_id; }
    },
    'industry': {
        title: '客戶產業別',
        desc: '客戶多選標籤，可設定子項目',
        action: 'manage_industries',
        hint: '儲存產業別後可管理子項目',
        getId:   function(d){ return d.industry_id; },
        getName: function(d){ return d.industry_name; },
        renderRow: function(d) {
            var subBadges = (d.sub_types||[]).map(function(s){
                return '<span style="font-size:10px;background:#e8f5f2;color:var(--accent);border-radius:3px;padding:1px 5px;margin:1px 2px;display:inline-block;">'+escHtml(s.sub_name)+'</span>';
            }).join('');
            return '<span class="dict-tag-badge">'+escHtml(d.industry_name)+'</span>'
                + (subBadges ? '<div style="margin-top:4px;display:flex;flex-wrap:wrap;gap:2px;">'+subBadges+'</div>' : '');
        },
        renderForm: function() {
            var html = '<div style="width:100%;">';
            html += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
            html += '<div style="flex:1;"><label style="font-size:11px;color:#888;margin-bottom:3px;">產業別名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：汽車、航太、醫療" maxlength="50"></div>';
            html += dictSaveBtn();
            html += '</div>';
            html += '<div style="border-top:1px solid #e8f5f2;padding-top:8px;">';
            html += '<div style="font-size:12px;font-weight:600;color:#1ABB9C;margin-bottom:6px;"><i class="fa fa-list-ul"></i> 子項目 <span style="font-size:10px;font-weight:normal;color:#aaa;">（儲存後可管理子項目）</span></div>';
            html += '<div style="display:flex;gap:6px;margin-bottom:6px;">';
            html += '<input type="text" id="dict-ind-sub-name" class="form-control input-sm" placeholder="子項目名稱" maxlength="50" style="flex:1;" onkeydown="if(event.key===\'Enter\')addIndustrySub()">';
            html += '<button class="btn btn-xs btn-primary" onclick="addIndustrySub()" style="white-space:nowrap;padding:3px 10px;"><i class="fa fa-plus"></i> 加入</button>';
            html += '</div>';
            html += '<table class="table table-condensed" style="margin:0;font-size:11px;"><tbody id="dict-ind-sub-tbody"><tr><td style="color:#aaa;text-align:center;padding:6px;">請先儲存產業別</td></tr></tbody></table>';
            html += '</div></div>';
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-name').val(d.industry_name);
            loadIndustrySubsForDict(d.industry_id);
        },
        getData: function() {
            var name = $('#dict-f-name').val().trim();
            if (!name) { showToast('請填寫產業別名稱','error'); return null; }
            var id = $('#dict-edit-id').val();
            return { action:'manage_industries', op:'save', industry_id:id, industry_name:name, industry_note:'',
                     _onSuccess: function(r) {
                         if (r.industry_id) {
                             $('#dict-edit-id').val(r.industry_id);
                             loadIndustrySubsForDict(r.industry_id);
                         }
                         industryCache = null;
                     }
            };
        },
        getDeleteId: function(d){ return d.industry_id; }
    },
    'maker-main': {
        title: '廠商大類',
        desc: '可設定綁定小類 · 支援拖曳排序',
        action: 'manage_maker_main_cats',
        hint: '大類排序可直接拖曳左側列表調整；每個大類可綁定多個小類標籤',
        getId:   function(d){ return d.main_cat_id; },
        getName: function(d){ return d.main_cat_name; },
        renderRow: function(d) {
            var sub = (d.sub_cats && d.sub_cats.length)
                ? d.sub_cats.map(function(s){
                    return '<span class="sub-tag-chip sub-group-'+s.sub_cat_group+'">'+escHtml(s.sub_cat_name)+'</span>';
                  }).join('')
                : '<span style="color:#ccc;font-size:11px;">尚未綁定小類</span>';
            return '<strong style="color:#5856d6;">'+escHtml(d.main_cat_name)+'</strong>'
                + '<div style="margin-top:5px;display:flex;flex-wrap:wrap;gap:3px;">'+sub+'</div>';
        },
        renderForm: function() {
            var html = '<div style="width:100%;">';
            html += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
            html += '<div style="flex:1;"><label style="font-size:11px;color:#888;margin-bottom:3px;">大類名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：外協加工、原物料、工具" maxlength="50"></div>';
            html += dictSaveBtn();
            html += '</div>';
            // Sub-binding section
            html += '<label style="font-size:11px;color:#888;margin-bottom:4px;display:block;">';
            html += '綁定小類標籤（可多選；拖曳右側已選區塊可調整順序）';
            html += '</label>';
            html += '<div style="display:flex;gap:8px;">';
            // Left: available pool
            html += '<div style="flex:1;border:1px solid #e4e8ed;border-radius:6px;background:#f8f9fb;padding:6px;">';
            html += '<div style="font-size:10px;color:#aaa;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px;">可用小類</div>';
            html += '<input type="text" id="dict-sub-search" class="form-control input-sm" placeholder="關鍵字篩選…" oninput="filterSubPool(this.value)" style="margin-bottom:5px;">';
            html += '<div style="display:flex;gap:4px;margin-bottom:4px;">';
            html += '<button type="button" class="btn btn-xs sub-grp-btn active" data-grp="" onclick="filterSubGroup(this,\'\')">全部</button>';
            html += '<button type="button" class="btn btn-xs sub-grp-btn" data-grp="PROCESS" onclick="filterSubGroup(this,\'PROCESS\')">加工</button>';
            html += '<button type="button" class="btn btn-xs sub-grp-btn" data-grp="CONSUMABLE" onclick="filterSubGroup(this,\'CONSUMABLE\')">耗材</button>';
            html += '<button type="button" class="btn btn-xs sub-grp-btn" data-grp="TOOL" onclick="filterSubGroup(this,\'TOOL\')">工具</button>';
            html += '<button type="button" class="btn btn-xs sub-grp-btn" data-grp="OTHER" onclick="filterSubGroup(this,\'OTHER\')">其他</button>';
            html += '</div>';
            html += '<div id="sub-pool-list" style="max-height:160px;overflow-y:auto;display:flex;flex-wrap:wrap;gap:3px;"></div>';
            html += '</div>';
            // Right: selected + sortable
            html += '<div style="flex:1;border:1px solid #c7d2fe;border-radius:6px;background:#f0ebff;padding:6px;">';
            html += '<div style="font-size:10px;color:#5856d6;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px;">已綁定（拖曳排序）</div>';
            html += '<div id="sub-selected-list" style="min-height:80px;max-height:200px;overflow-y:auto;display:flex;flex-wrap:wrap;gap:3px;align-content:flex-start;"></div>';
            html += '</div>';
            html += '</div>';
            html += '<input type="hidden" id="dict-f-sub-ids" value="">';
            html += '</div>';
            // Load sub pool
            setTimeout(function(){ loadSubPool([]); }, 50);
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-name').val(d.main_cat_name);
            var selIds = (d.sub_cats||[]).map(function(s){ return parseInt(s.sub_cat_id); });
            setTimeout(function(){ loadSubPool(selIds); }, 300);
        },
        getData: function() {
            var name = $('#dict-f-name').val().trim();
            if (!name) { showToast('請填寫大類名稱','error'); return null; }
            var id = $('#dict-edit-id').val();
            var subIds = [];
            document.querySelectorAll('#sub-selected-list .sub-sel-chip').forEach(function(el){
                subIds.push(el.dataset.subId);
            });
            return { action:'manage_maker_main_cats', op:'save', main_cat_id:id, main_cat_name:name, sub_cat_ids:subIds.join(',') };
        },
        getDeleteId: function(d){ return d.main_cat_id; }
    },
