    'maker-sub': {
        title: '廠商小類',
        desc: '標籤池 · 支援拖曳排序',
        action: 'manage_maker_sub_cats',
        hint: '小類為原子標籤，可同時屬於多個大類。PROCESS=加工類；CONSUMABLE=耗材；TOOL=工具；OTHER=其他。',
        getId:   function(d){ return d.sub_cat_id; },
        getName: function(d){ return d.sub_cat_name; },
        renderRow: function(d) {
            var grpLabel = {PROCESS:'加工',CONSUMABLE:'耗材',TOOL:'工具',OTHER:'其他'};
            var grpColor = {PROCESS:'var(--accent)',CONSUMABLE:'#e67e22',TOOL:'#3498db',OTHER:'#aaa'};
            var g = d.sub_cat_group||'PROCESS';
            var grpBadge = '<span style="font-size:10px;background:'+grpColor[g]+';color:#fff;border-radius:3px;padding:1px 5px;margin-right:4px;">'+(grpLabel[g]||g)+'</span>';
            var syncBadge = (d.ref_process_type_id && d.ref_process_type_id!='0' && d.ref_process_type_id!='')
                ? '<span title="唯讀同步項：名稱與群組由製程類別控制" style="font-size:10px;background:#fff3cd;color:#856404;border-radius:3px;padding:1px 5px;margin-right:4px;cursor:help;"><i class="fa fa-link"></i> 同步</span>'
                : '';
            var cats = d.main_cat_names
                ? d.main_cat_names.split(', ').map(function(n){
                    return '<span style="font-size:10px;background:#eef2ff;color:#5856d6;padding:1px 5px;border-radius:3px;">'+escHtml(n)+'</span>';
                  }).join(' ')
                : '<span style="color:#ccc;font-size:11px;">未綁定</span>';
            return grpBadge + syncBadge + escHtml(d.sub_cat_name) + '<div style="margin-top:3px;">'+cats+'</div>';
        },
        renderForm: function() {
            var html = '<div style="width:100%;">';
            html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px;">';
            html += '<div style="flex:1;min-width:150px;"><label style="font-size:11px;color:#888;margin-bottom:3px;">小類名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：CNC車、外圓研磨、切削油" maxlength="50"></div>';
            html += '<div><label style="font-size:11px;color:#888;margin-bottom:3px;">分類組別</label>';
            html += '<select id="dict-f-group" class="form-control input-sm">';
            html += '<option value="PROCESS">⚙ 加工類 (PROCESS)</option>';
            html += '<option value="CONSUMABLE">🔧 耗材類 (CONSUMABLE)</option>';
            html += '<option value="TOOL">🔩 工具類 (TOOL)</option>';
            html += '<option value="OTHER">📦 其他 (OTHER)</option>';
            html += '</select></div>';
            html += dictSaveBtn();
            html += '</div>';
            html += '<label style="font-size:11px;color:#888;margin-bottom:4px;display:block;">綁定大類（可多選）</label>';
            html += '<div id="dict-sub-main-checkboxes" style="display:flex;flex-wrap:wrap;gap:5px;padding:7px;background:#f7f8fb;border-radius:6px;border:1px solid #e4e8ed;min-height:32px;">';
            html += '<span style="color:#aaa;font-size:11px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</span>';
            html += '</div>';
            html += '</div>';
            api({ action:'get_maker_main_cats' }).done(function(r) {
                if (!r.success) return;
                var wrap = document.getElementById('dict-sub-main-checkboxes');
                if (!wrap) return;
                if (!r.data.length) { wrap.innerHTML = '<span style="color:#aaa;font-size:11px;">無大類資料</span>'; return; }
                var h = '';
                r.data.forEach(function(m) {
                    h += '<label class="sub-main-chk-label" style="display:inline-flex;align-items:center;gap:4px;background:#fff;border:1px solid #dde;border-radius:14px;padding:3px 10px;cursor:pointer;font-weight:normal;font-size:12px;transition:all .15s;" onclick="toggleSubMainChk(this)">';
                    h += '<input type="checkbox" value="'+m.main_cat_id+'" style="display:none;">'+escHtml(m.main_cat_name)+'</label>';
                });
                wrap.innerHTML = h;
            });
            return html;
        },
        fillForm: function(d) {
            var isSync = d.ref_process_type_id && d.ref_process_type_id != '0' && d.ref_process_type_id !== '';
            var nameEl = document.getElementById('dict-f-name');
            var groupEl = document.getElementById('dict-f-group');
            if (nameEl) {
                nameEl.value = d.sub_cat_name;
                nameEl.readOnly = isSync;
                nameEl.style.background = isSync ? '#fffbf0' : '';
                nameEl.title = isSync ? '唯讀同步項：名稱由製程類別控制' : '';
            }
            if (groupEl) {
                groupEl.value = d.sub_cat_group||'PROCESS';
                groupEl.disabled = isSync;
                groupEl.title = isSync ? '唯讀同步項：群組由製程類別控制' : '';
            }
            if (isSync) {
                // Show sync notice above form
                var notice = document.createElement('div');
                notice.id = 'sync-notice';
                notice.style.cssText = 'background:#fff3cd;border:1px solid #ffc107;border-radius:4px;padding:5px 10px;font-size:12px;color:#856404;margin-bottom:8px;';
                notice.innerHTML = '<i class="fa fa-link"></i> <strong>唯讀同步項</strong>：此標籤同步自製程類別，名稱與群組不可修改。僅可調整綁定大類。';
                var fa = document.getElementById('dict-form-area').querySelector('div');
                if (fa && !document.getElementById('sync-notice')) fa.insertBefore(notice, fa.firstChild);
            } else {
                var old = document.getElementById('sync-notice');
                if (old) old.remove();
            }
            var ids = (d.main_cat_ids||'').split(',').map(function(x){ return x.trim(); }).filter(Boolean);
            setTimeout(function() {
                document.querySelectorAll('#dict-sub-main-checkboxes .sub-main-chk-label').forEach(function(el) {
                    var cb = el.querySelector('input');
                    var checked = ids.indexOf(String(cb.value)) >= 0;
                    cb.checked = checked;
                    el.style.background  = checked ? '#5856d6' : '#fff';
                    el.style.color       = checked ? '#fff' : '';
                    el.style.borderColor = checked ? '#5856d6' : '#dde';
                });
            }, 380);
        },
        getData: function() {
            var name = $('#dict-f-name').val().trim();
            if (!name) { showToast('請填寫小類名稱','error'); return null; }
            var group = ($('#dict-f-group').val()||'PROCESS');
            var ids = [];
            document.querySelectorAll('#dict-sub-main-checkboxes input[type=checkbox]').forEach(function(cb){ if(cb.checked) ids.push(cb.value); });
            var id = $('#dict-edit-id').val();
            return { action:'manage_maker_sub_cats', op:'save', sub_cat_id:id, sub_cat_name:name, sub_cat_group:group, main_cat_ids:ids.join(',') };
        },
        getDeleteId: function(d){ return d.sub_cat_id; }
    },
    'maker-proc-label': {
        title:  '廠商加工限制',
        desc:   '定義廠商加工能力的標籤，可附加數值',
        action: 'manage_maker_proc_labels',
        hint:   '新增/編輯/排序需 A/CDRU/CRU 權限；刪除需 A/CDRU 權限',
        getId:   function(d){ return d.proc_label_id; },
        getName: function(d){ return d.label_name; },
        renderRow: function(d) {
            var badge;
            if (d.input_type === 'numeric') {
                var ntMap = { range:'範圍', MAX:'MAX', MIN:'MIN' };
                var ntLabel = ntMap[d.numeric_type] || '範圍';
                badge = '<span style="font-size:10px;background:#e3f2fd;color:#1565c0;border-radius:3px;padding:1px 5px;margin-left:5px;">數值·'+ntLabel+'</span>';
            } else if (d.input_type === 'text') {
                badge = '<span style="font-size:10px;background:#fff3e0;color:#e65100;border-radius:3px;padding:1px 5px;margin-left:5px;">文字</span>';
            } else {
                badge = '<span style="font-size:10px;background:#f0f0f0;color:#888;border-radius:3px;padding:1px 5px;margin-left:5px;">無</span>';
            }
            var unit = d.input_type === 'numeric' ? '<span style="font-size:10px;color:#888;margin-left:4px;">('+escHtml(d.unit||'mm')+')</span>' : '';
            var prefix = '';
            if (d.parent_label_ids) {
                var pnames = String(d.parent_label_names||'').split(',').filter(Boolean);
                prefix = '<span style="color:#bbb;margin-right:3px;">↳</span>'
                    + pnames.map(function(n){ return '<span style="font-size:10px;background:#fff3e0;color:#e65100;border-radius:3px;padding:1px 4px;margin-right:3px;">'+escHtml(n.trim())+'</span>'; }).join('');
            }
            var repBadge = (!d.parent_label_ids && parseInt(d.is_repeatable,10)) ? '<span style="font-size:10px;background:#e8f5e9;color:#2e7d32;border-radius:3px;padding:1px 5px;margin-left:5px;">可多組</span>' : '';
            return prefix + escHtml(d.label_name) + badge + unit + repBadge;
        },
        renderForm: function() {
            var html = '<div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;width:100%;">';
            html += '<div style="flex:1;min-width:150px;"><label style="font-size:11px;color:#888;margin-bottom:3px;">標籤名稱 <span style="color:red;">*</span></label>';
            html += '<input type="text" id="dict-f-name" class="form-control input-sm" placeholder="例：最大加工直徑" maxlength="50"></div>';
            html += '<div><label style="font-size:11px;color:#888;margin-bottom:3px;">輸入類型</label>';
            html += '<select id="dict-f-input-type" class="form-control input-sm" style="width:70px;" onchange="dictProcLabelTypeChange(this.value)"><option value="none">無</option><option value="numeric">數值</option><option value="text">文字</option></select></div>';
            html += '<div id="dict-f-ntype-wrap" style="display:none;"><label style="font-size:11px;color:#888;margin-bottom:3px;">數值類型</label>';
            html += '<select id="dict-f-numeric-type" class="form-control input-sm" style="width:70px;"><option value="range">範圍</option><option value="MAX">MAX</option><option value="MIN">MIN</option></select></div>';
            html += '<div id="dict-f-unit-wrap" style="display:none;"><label style="font-size:11px;color:#888;margin-bottom:3px;">單位</label>';
            html += '<select id="dict-f-unit" class="form-control input-sm" style="width:70px;"><option value="mm">mm</option><option value="kg">kg</option></select></div>';
            html += '<div id="dict-f-rep-wrap" style="display:flex;align-items:flex-end;padding-bottom:5px;"><label style="font-size:11px;color:#888;display:flex;align-items:center;gap:4px;cursor:pointer;margin:0;">';
            html += '<input type="checkbox" id="dict-f-is-rep" style="margin:0;"> 可多組</label></div>';
            html += dictSaveBtn('maker-proc-label');
            html += '</div>';
            html += '<div style="width:100%;margin-top:8px;">';
            html += '<label style="font-size:11px;color:#888;margin-bottom:4px;display:block;">所屬頂層標籤（可多選；不選則為頂層）</label>';
            html += '<div id="dict-proc-parent-checkboxes" style="display:flex;flex-wrap:wrap;gap:5px;padding:6px 8px;background:#f7f8fb;border-radius:6px;border:1px solid #e4e8ed;min-height:28px;">';
            html += '<span style="color:#aaa;font-size:11px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</span>';
            html += '</div></div>';
            return html;
        },
        fillForm: function(d) {
            $('#dict-f-name').val(d.label_name);
            var editId = String(d.proc_label_id || '');
            var parentIds = d.parent_label_ids ? String(d.parent_label_ids).split(',').filter(Boolean) : [];
            setTimeout(function(){
                // Update parent checkboxes
                document.querySelectorAll('#dict-proc-parent-checkboxes .dpl-parent-chk').forEach(function(lbl) {
                    var cb = lbl.querySelector('input');
                    if (!cb) return;
                    lbl.style.display = (String(cb.value) === editId) ? 'none' : '';
                    var ck = parentIds.indexOf(String(cb.value)) >= 0;
                    cb.checked = ck;
                    lbl.style.background = ck ? '#1ABB9C' : '';
                    lbl.style.color = ck ? '#fff' : '';
                    lbl.style.borderColor = ck ? '#1ABB9C' : '#dde';
                });
                dictProcLabelParentChange();
                var s = document.getElementById('dict-f-input-type');
                if (s) { s.value = d.input_type||'none'; dictProcLabelTypeChange(s.value); }
                var nt = document.getElementById('dict-f-numeric-type');
                if (nt) nt.value = d.numeric_type||'range';
                var u = document.getElementById('dict-f-unit');
                if (u) u.value = d.unit||'mm';
                var rep = document.getElementById('dict-f-is-rep');
                if (rep) rep.checked = !!parseInt(d.is_repeatable,10);
            }, 50);
        },
        getData: function() {
            var name  = $('#dict-f-name').val().trim();
            var itype = (document.getElementById('dict-f-input-type')||{}).value||'none';
            var ntype = itype === 'numeric' ? ((document.getElementById('dict-f-numeric-type')||{}).value||'range') : 'range';
            var unit  = itype === 'numeric' ? ((document.getElementById('dict-f-unit')||{}).value||'mm') : 'mm';
            var parentIds = [];
            document.querySelectorAll('#dict-proc-parent-checkboxes .dpl-parent-chk input:checked').forEach(function(cb){ parentIds.push(cb.value); });
            var isRep = parentIds.length ? 0 : ((document.getElementById('dict-f-is-rep')||{}).checked ? 1 : 0);
            var id = $('#dict-edit-id').val();
            if (!name) { showToast('請填寫標籤名稱','error'); return null; }
            return { action:'manage_maker_proc_labels', op:'save', proc_label_id:id, label_name:name, input_type:itype, numeric_type:ntype, unit:unit, parent_label_ids:parentIds.join(','), is_repeatable:isRep };
        },
        getDeleteId: function(d){ return d.proc_label_id; }
    },
    'maker-main-process': {
