var _DICT_PART_TYPES = ['workpiece','workpiece-sub','gear','label','label-sub','process-type'];
var _DICT_UPDATE_TYPES = ['maker-proc-label', 'maker-main-process'];
function _canEditDict(type) {
    if (CAN_DICT_EDIT) return true;
    var t = type || _dictCurrentType;
    if (_DICT_UPDATE_TYPES.indexOf(t) >= 0) return CAN_UPDATE;
    return CAN_DICT_PART && _DICT_PART_TYPES.indexOf(t) >= 0;
}
var _dictCurrentType = '';
function dictSaveBtn(type) {
    if (!_canEditDict(type)) return '';
    return '<div style="display:flex;align-items:flex-end;gap:6px;padding-bottom:1px;">'
        + '<button type="button" class="btn btn-success btn-sm" onclick="saveDictEntry()" style="white-space:nowrap;"><i class="fa fa-save"></i> 儲存</button>'
        + '<button type="button" class="btn btn-default btn-sm" onclick="clearDictForm()" style="white-space:nowrap;">清除</button>'
        + '</div>';
}

function dictProcLabelTypeChange(val) {
    var nw = document.getElementById('dict-f-ntype-wrap');
    var uw = document.getElementById('dict-f-unit-wrap');
    if (nw) nw.style.display = (val === 'numeric') ? '' : 'none';
    if (uw) uw.style.display = (val === 'numeric') ? '' : 'none';
}
function dictProcLabelParentChange() {
    var anyChecked = !!document.querySelector('#dict-proc-parent-checkboxes .dpl-parent-chk input:checked');
    var rw = document.getElementById('dict-f-rep-wrap');
    if (rw) {
        rw.style.display = anyChecked ? 'none' : '';
        if (anyChecked) { var rep = document.getElementById('dict-f-is-rep'); if (rep) rep.checked = false; }
    }
}
function dictProcLabelParentCheck(cb) {
    var lbl = cb.closest('.dpl-parent-chk');
    if (lbl) {
        lbl.style.background  = cb.checked ? '#1ABB9C' : '';
        lbl.style.color       = cb.checked ? '#fff' : '';
        lbl.style.borderColor = cb.checked ? '#1ABB9C' : '#dde';
    }
    dictProcLabelParentChange();
}
function dictLoadProcLabelParents(data) {
    var wrap = document.getElementById('dict-proc-parent-checkboxes');
    if (!wrap) return;
    var editId = String($('#dict-edit-id').val() || '');
    var existChecked = [];
    wrap.querySelectorAll('.dpl-parent-chk input:checked').forEach(function(cb){ existChecked.push(cb.value); });
    // Only top-level labels (no parent_label_ids) can be parents
    var topLabels = (data || []).filter(function(d){ return !d.parent_label_ids; });
    if (!topLabels.length) {
        wrap.innerHTML = '<span style="color:#aaa;font-size:11px;">尚無頂層標籤可選</span>';
        return;
    }
    var h = '';
    topLabels.forEach(function(l) {
        if (String(l.proc_label_id) === editId) return;
        var ck = existChecked.indexOf(String(l.proc_label_id)) >= 0;
        h += '<label class="dpl-parent-chk" style="display:inline-flex;align-items:center;gap:4px;border:1px solid '+(ck?'#1ABB9C':'#dde')+';border-radius:14px;padding:3px 10px;cursor:pointer;font-size:12px;background:'+(ck?'#1ABB9C':'')+';color:'+(ck?'#fff':'')+';transition:all .15s;">';
        h += '<input type="checkbox" value="'+l.proc_label_id+'" style="position:absolute;opacity:0;width:0;height:0;" '+(ck?'checked':'')+' onchange="dictProcLabelParentCheck(this)">'+escHtml(l.label_name);
        h += '</label>';
    });
    wrap.innerHTML = h || '<span style="color:#aaa;font-size:11px;">尚無頂層標籤可選</span>';
}
// ── 廠商大類製程設定 UI helpers ────────────────────────────────────────────────
var _mmpData = null; // { main_cats, process_types, process_nos }

function loadMakerMainProcessPanel() {
    var panel = document.getElementById('dict-maker-main-process-panel');
    var content = document.getElementById('dict-mmp-content');
    if (!panel) return;
    panel.style.display = '';
    if (content) content.innerHTML = '<span style="color:#aaa;font-size:12px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</span>';
    api({ action:'manage_maker_main_cat_process', op:'list_config' }).done(function(r) {
        if (!r.success) { if(content) content.innerHTML='<span style="color:red;">載入失敗</span>'; return; }
        _mmpData = { main_cats: r.main_cats||[], process_types: r.process_types||[], process_nos: r.process_nos||[] };
        renderMakerMainProcessPanel();
    });
}

function renderMakerMainProcessPanel() {
    var content = document.getElementById('dict-mmp-content');
    if (!content || !_mmpData) return;
    var d = _mmpData;
    if (!d.main_cats.length) { content.innerHTML='<span style="color:#aaa;font-size:12px;">尚無廠商大類</span>'; return; }
    // 找出目前有設定的大類（只有一個）
    var activeMcId = 0;
    d.main_cats.forEach(function(mc){ if ((mc.process_config||[]).length) activeMcId = mc.main_cat_id; });
    // 下拉選單
    var html = '<div style="display:flex;gap:8px;align-items:flex-end;margin-bottom:14px;flex-wrap:wrap;">';
    html += '<div><label style="font-size:12px;color:#555;display:block;margin-bottom:4px;">使用製程設定的廠商大類</label>';
    html += '<select id="mmp-main-cat-sel" class="form-control input-sm" style="width:200px;" onchange="onMmpMainCatChange(this.value)">';
    html += '<option value="">（不使用）</option>';
    d.main_cats.forEach(function(mc) {
        html += '<option value="'+mc.main_cat_id+'"'+(mc.main_cat_id==activeMcId?' selected':'')+'>'+escHtml(mc.main_cat_name)+'</option>';
    });
    html += '</select></div>';
    if (CAN_UPDATE) html += '<button type="button" class="btn btn-sm btn-success" onclick="saveMakerMainProcessConfig()"><i class="fa fa-save"></i> 儲存設定</button>';
    html += '</div>';
    html += '<div id="mmp-process-checkboxes" style="background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:12px 16px;'+(activeMcId?'':'display:none;')+'">';
    html += _buildMmpCheckboxes(activeMcId);
    html += '</div>';
    content.innerHTML = html;
}

function _buildMmpCheckboxes(mcid) {
    if (!_mmpData || !mcid) return '';
    var d = _mmpData;
    var cfg = [];
    d.main_cats.forEach(function(mc){ if (mc.main_cat_id==mcid) cfg = mc.process_config||[]; });
    var cfgMap = {}; cfg.forEach(function(c){ cfgMap[c.ref_type+':'+c.ref_id]=true; });
    var html = '';
    if (d.process_types.length) {
        html += '<div style="font-size:11px;font-weight:600;color:#1565c0;background:#e3f2fd;display:inline-block;padding:1px 8px;border-radius:3px;margin-bottom:6px;">製程大類（勾選整個大類）</div>';
        html += '<div style="display:flex;flex-wrap:wrap;gap:5px;margin-bottom:12px;">';
        d.process_types.forEach(function(pt) {
            var key='type:'+pt.process_type_id; var ck=cfgMap[key]?' checked':'';
            html += '<label class="mmp-chk-lbl" style="font-weight:normal;cursor:pointer;font-size:12px;margin:0;display:inline-flex;align-items:center;gap:3px;padding:3px 10px;border-radius:12px;border:1px solid '+(ck?' #1565c0':'#bbdefb')+';background:'+(ck?' #e3f2fd':'#f5f9ff')+';color:'+(ck?' #1565c0':'#555')+';transition:all .1s;">';
            html += '<input type="checkbox" data-ref-type="type" data-ref-id="'+pt.process_type_id+'"'+ck+' onchange="onMmpChkChange(this)"> '+escHtml(pt.process_type||'')+'</label>';
        });
        html += '</div>';
    }
    if (d.process_nos.length) {
        html += '<div style="font-size:11px;font-weight:600;color:#2e7d32;background:#e8f5e9;display:inline-block;padding:1px 8px;border-radius:3px;margin-bottom:6px;">製程小類（勾選具體製程）</div>';
        var byType = {}; var noType = [];
        d.process_nos.forEach(function(pn){ var tid=pn.process_type_id; if(tid){if(!byType[tid])byType[tid]=[];byType[tid].push(pn);}else noType.push(pn); });
        html += '<div style="display:flex;flex-direction:column;gap:6px;">';
        d.process_types.forEach(function(pt) {
            var pns = byType[pt.process_type_id]||[]; if(!pns.length) return;
            html += '<div style="display:flex;flex-wrap:wrap;gap:4px;align-items:center;">';
            html += '<span style="font-size:10px;color:#888;white-space:nowrap;min-width:60px;">'+escHtml(pt.process_type||'')+'</span>';
            pns.forEach(function(pn) {
                var key='no:'+pn.ProcessNo; var ck=cfgMap[key]?' checked':'';
                html += '<label class="mmp-chk-lbl" style="font-weight:normal;cursor:pointer;font-size:11px;margin:0;display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:10px;border:1px solid '+(ck?' #2e7d32':'#c8e6c9')+';background:'+(ck?' #e8f5e9':'#f5fbf5')+';color:'+(ck?' #2e7d32':'#555')+';transition:all .1s;">';
                html += '<input type="checkbox" data-ref-type="no" data-ref-id="'+pn.ProcessNo+'"'+ck+' onchange="onMmpChkChange(this)"> '+escHtml(pn.ProcessName||'')+'</label>';
            });
            html += '</div>';
        });
        if (noType.length) {
            html += '<div style="display:flex;flex-wrap:wrap;gap:4px;">';
            noType.forEach(function(pn) {
                var key='no:'+pn.ProcessNo; var ck=cfgMap[key]?' checked':'';
                html += '<label class="mmp-chk-lbl" style="font-weight:normal;cursor:pointer;font-size:11px;margin:0;display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:10px;border:1px solid '+(ck?' #2e7d32':'#c8e6c9')+';background:'+(ck?' #e8f5e9':'#f5fbf5')+';color:'+(ck?' #2e7d32':'#555')+';transition:all .1s;">';
                html += '<input type="checkbox" data-ref-type="no" data-ref-id="'+pn.ProcessNo+'"'+ck+' onchange="onMmpChkChange(this)"> '+escHtml(pn.ProcessName||'')+'</label>';
            });
            html += '</div>';
        }
        html += '</div>';
    }
    return html;
}

function onMmpMainCatChange(val) {
    var box = document.getElementById('mmp-process-checkboxes');
    if (!box) return;
    if (!val) { box.style.display='none'; box.innerHTML=''; return; }
    box.style.display='';
    box.innerHTML = _buildMmpCheckboxes(parseInt(val,10));
}

function onMmpChkChange(cb) {
    var lbl = cb.closest('label');
    if (!lbl) return;
    var isT = cb.dataset.refType === 'type';
    lbl.style.borderColor = cb.checked ? (isT?'#1565c0':'#2e7d32') : (isT?'#bbdefb':'#c8e6c9');
    lbl.style.background  = cb.checked ? (isT?'#e3f2fd':'#e8f5e9') : (isT?'#f5f9ff':'#f5fbf5');
    lbl.style.color       = cb.checked ? (isT?'#1565c0':'#2e7d32') : '#555';
}

function saveMakerMainProcessConfig() {
    var sel = document.getElementById('mmp-main-cat-sel');
    var mainCatId = sel ? parseInt(sel.value||'0', 10) : 0;
    var items = [];
    if (mainCatId) {
        document.querySelectorAll('#mmp-process-checkboxes input[type=checkbox]:checked').forEach(function(cb) {
            items.push({ ref_type: cb.dataset.refType, ref_id: parseInt(cb.dataset.refId, 10) });
        });
    }
    // 後端：清除所有大類的設定後只儲存選定的那一個（main_cat_id=0 表示清除全部）
    api({ action:'manage_maker_main_cat_process', op:'save_config', main_cat_id:mainCatId, config_items:JSON.stringify(items), clear_all:1 }).done(function(r) {
        if (r.success) {
            showToast('已儲存');
            if (_mmpData) {
                _mmpData.main_cats.forEach(function(mc){ mc.process_config = []; });
                if (mainCatId) {
                    var mc = _mmpData.main_cats.find(function(m){ return m.main_cat_id==mainCatId; });
                    if (mc) mc.process_config = items.map(function(i){ return { ref_type:i.ref_type, ref_id:i.ref_id }; });
                }
            }
        } else { showToast(r.message||'儲存失敗','error'); }
    });
}

function openDictModal() {
    $('#dictModal').modal('show');
    loadDict('workpiece', document.querySelector('.dict-nav-btn'));
}

// Init row reorder on dict table for main/sub
function initDictTableSortable(type) {
    var sortableTypes = ['workpiece', 'gear', 'label', 'industry', 'maker-main', 'maker-sub', 'process-type', 'maker-proc-label'];
    if (sortableTypes.indexOf(type) < 0) return;
    var tbody = document.getElementById('dict-table-body');
    if (!tbody || typeof Sortable === 'undefined') return;
    if (tbody._sortable) tbody._sortable.destroy();
    tbody._sortable = Sortable.create(tbody, {
        animation: 150, ghostClass: 'sortable-ghost', handle: 'tr',
        onEnd: function() { saveDictOrder(type); }
    });
}

function loadDict(type, navBtn) {
    currentDictType = type;
    _dictCurrentType = type;

    // update nav highlight
    if (navBtn) {
        document.querySelectorAll('.dict-nav-btn').forEach(function(b){ b.classList.remove('active'); });
        navBtn.classList.add('active');
    }

    // Clean up type-specific UI elements when switching types
    var oldSearchBar = document.getElementById('dict-label-searchbar');
    if (oldSearchBar) oldSearchBar.remove();
    var oldPg = document.getElementById('dict-label-pagination');
    if (oldPg) oldPg.remove();
    var oldPgBar = document.getElementById('dict-pg-searchbar');
    if (oldPgBar) oldPgBar.remove();
    var oldPgPg = document.getElementById('dict-pg-pagination');
    if (oldPgPg) oldPgPg.remove();

    var cfg = dictConfig[type];
    $('#dict-panel-title').text(cfg.title);
    $('#dict-panel-desc').text(cfg.desc ? '— ' + cfg.desc : '');
    $('#dict-footer-hint').html(cfg.hint ? '<i class="fa fa-info-circle" style="color:#e67e22;"></i> ' + cfg.hint : '');

    // render form (read-only users see sub-label view for label type only)
    $('#dict-edit-id').remove();
    var dictFormArea = document.getElementById('dict-form-area');
    if (!_canEditDict(type)) {
        if (type === 'label') {
            dictFormArea.style.display = '';
            var roHtml = '<input type="hidden" id="dict-edit-id" value="">'
                + '<div id="dict-ro-hint" style="font-size:11px;color:#aaa;padding:4px 0;"><i class="fa fa-eye"></i> 點擊列表中的 <i class="fa fa-list"></i> 可查看子標籤</div>';
            $('#dict-form-area > div').html(roHtml);
        } else {
            dictFormArea.style.display = 'none';
        }
    } else {
        dictFormArea.style.display = '';
        var formHtml = '<input type="hidden" id="dict-edit-id" value="">' + cfg.renderForm();
        $('#dict-form-area > div').html(formHtml);
        if (document.getElementById('tmpl-var-chips')) updateTmplVarChips();
    }

    // update table head
    $('#dict-table-head').html(dictTableHead[type] || '<th>名稱</th><th style="width:90px;">操作</th>');

    // Show/hide panels
    var settingsPanel = document.getElementById('dict-settings-extra');
    var basicPanel    = document.getElementById('dict-basic-settings-panel');
    var tableArea     = document.getElementById('dict-table-area');
    var formArea      = document.getElementById('dict-form-area');

    if (type === 'maker-main-process') {
        if (settingsPanel) settingsPanel.style.display = 'none';
        if (basicPanel)    basicPanel.style.display    = 'none';
        var _gqP = document.getElementById('dict-gear-quality-panel'); if (_gqP) _gqP.style.display = 'none';
        var _acPm = document.getElementById('dict-attach-cat-panel'); if (_acPm) _acPm.style.display = 'none';
        if (tableArea)     tableArea.style.display     = 'none';
        if (formArea)      formArea.style.display      = 'none';
        loadMakerMainProcessPanel();
        return;
    }

    if (type === 'attach-cat') {
        if (settingsPanel) settingsPanel.style.display = 'none';
        if (basicPanel)    basicPanel.style.display    = 'none';
        var _gqPa = document.getElementById('dict-gear-quality-panel'); if (_gqPa) _gqPa.style.display = 'none';
        var _mmpPa = document.getElementById('dict-maker-main-process-panel'); if (_mmpPa) _mmpPa.style.display = 'none';
        if (tableArea)     tableArea.style.display     = 'none';
        if (formArea)      formArea.style.display      = 'none';
        var acPanel = document.getElementById('dict-attach-cat-panel');
        if (acPanel) { acPanel.style.display = 'flex'; }
        loadAttachCatPanel();
        return;
    }

    if (type === 'gear-quality') {
        if (settingsPanel) settingsPanel.style.display = 'none';
        if (basicPanel)    basicPanel.style.display    = 'none';
        var _acP = document.getElementById('dict-attach-cat-panel'); if (_acP) _acP.style.display = 'none';
        var _mmpPg = document.getElementById('dict-maker-main-process-panel'); if (_mmpPg) _mmpPg.style.display = 'none';
        if (tableArea)     tableArea.style.display     = 'none';
        if (formArea)      formArea.style.display      = 'none';
        var gqPanel = document.getElementById('dict-gear-quality-panel');
        if (gqPanel) { gqPanel.style.display = 'flex'; }
        loadGearQualityPanel();
        return;
    }

    if (type === 'basic-settings') {
        if (settingsPanel) settingsPanel.style.display = 'none';
        if (basicPanel)    basicPanel.style.display    = '';
        var _gqP2 = document.getElementById('dict-gear-quality-panel'); if (_gqP2) _gqP2.style.display = 'none';
        var _acP2 = document.getElementById('dict-attach-cat-panel'); if (_acP2) _acP2.style.display = 'none';
        var _mmpP2 = document.getElementById('dict-maker-main-process-panel'); if (_mmpP2) _mmpP2.style.display = 'none';
        if (tableArea)     tableArea.style.display     = 'none';
        if (formArea)      formArea.style.display      = 'none';
        api({ action:'manage_system_settings', op:'get' }).done(function(r) {
            if (!r.success || !r.data) return;
            var d = r.data;
            var vSm = document.getElementById('dict-vendor-settlement_mode');
            var vSd = document.getElementById('dict-vendor-settlement_day');
            var vPm = document.getElementById('dict-vendor-payment_method');
            var vNd = document.getElementById('dict-vendor-net_days');
            if (vSm) vSm.value = d.vendor_default_settlement_mode || 'FIXED';
            if (vSd) vSd.value = d.vendor_default_settlement_day  || '25';
            if (vPm) vPm.value = d.vendor_default_payment_method  || '匯款';
            if (vNd) vNd.value = d.vendor_default_net_days        || '';
            var cSm = document.getElementById('dict-cust-settlement_mode');
            var cSd = document.getElementById('dict-cust-settlement_day');
            var cPm = document.getElementById('dict-cust-payment_method');
            var cNd = document.getElementById('dict-cust-net_days');
            if (cSm) cSm.value = d.cust_default_settlement_mode || 'FIXED';
            if (cSd) cSd.value = d.cust_default_settlement_day  || '25';
            if (cPm) cPm.value = d.cust_default_payment_method  || '匯款';
            if (cNd) cNd.value = d.cust_default_net_days        || '';
        });
        return;
    }

    if (basicPanel)    basicPanel.style.display = 'none';
    var mmpPanel = document.getElementById('dict-maker-main-process-panel');
    if (mmpPanel) mmpPanel.style.display = 'none';
    var gqPanel = document.getElementById('dict-gear-quality-panel');
    if (gqPanel) gqPanel.style.display = 'none';
    var acPanelX = document.getElementById('dict-attach-cat-panel');
    if (acPanelX) acPanelX.style.display = 'none';
    if (tableArea)     tableArea.style.display  = '';

    if (settingsPanel) {
        if (type === 'process-type') {
            settingsPanel.style.display = '';
            api({ action:'manage_system_settings', op:'get' }).done(function(r) {
                if (r.success && r.data) {
                    var nasEl = document.getElementById('dict-nas-path');
                    var urlEl = document.getElementById('dict-url-path');
                    if (nasEl) nasEl.value = r.data.notes_nas_dir || '';
                    if (urlEl) urlEl.value = r.data.notes_url_dir || '';
                }
            });
        } else {
            settingsPanel.style.display = 'none';
        }
    }

    // load data
    $('#dict-table-body').html('<tr><td colspan="3" class="text-center" style="padding:24px;color:#aaa;"><i class="fa fa-spinner fa-spin"></i> 載入中…</td></tr>');
    var listReq = (type === 'workpiece-sub')
        ? api({ action:'manage_workpiece_sub_types', op:'list', type_code:'__ALL__' })
        : api({ action: cfg.action, op: 'list' });
    listReq.done(function(r) {
        if (!r.success) { showToast('載入失敗','error'); return; }
        var data = r.data || [];
        if (type === 'label') {
            renderLabelDictFull(data);
        } else if (type === 'maker-main' || type === 'maker-sub') {
            initPaginatedDict(type, data);
        } else {
            $('#dict-count-badge').text(data.length + ' 筆');
            renderDictTable(type, data);
            if (type === 'maker-proc-label') dictLoadProcLabelParents(data);
        }
    }).fail(function(){ showToast('網路錯誤','error'); });
}

function saveNasPathSetting() {
    var nasPath = (document.getElementById('dict-nas-path')||{}).value || '';
    var urlPath = (document.getElementById('dict-url-path')||{}).value || '';
    if (!nasPath || !urlPath) { showToast('路徑不可為空','error'); return; }
    api({ action:'manage_system_settings', op:'save', notes_nas_dir:nasPath, notes_url_dir:urlPath }).done(function(r) {
        if (r.success) { showToast('設定已儲存'); NAS_URL_DIR = urlPath; }
        else showToast(r.message||'儲存失敗','error');
    });
}
function saveVendorPaymentSetting() {
    var sm = (document.getElementById('dict-vendor-settlement_mode')||{}).value || 'FIXED';
    var sd = (document.getElementById('dict-vendor-settlement_day')||{}).value || '';
    var pm = (document.getElementById('dict-vendor-payment_method')||{}).value || '匯款';
    var nd = (document.getElementById('dict-vendor-net_days')||{}).value || '';
    if (sm === 'FIXED' && (!sd || parseInt(sd) < 1 || parseInt(sd) > 31)) { showToast('固定結帳日需為 1~31','error'); return; }
    api({ action:'manage_system_settings', op:'save', vendor_default_settlement_mode:sm, vendor_default_settlement_day:sd, vendor_default_payment_method:pm, vendor_default_net_days:nd }).done(function(r) {
        if (r.success) {
            showToast('廠商預設付款條件已儲存');
            SYS_VENDOR_DEFAULT_SETTLEMENT_MODE = sm;
            SYS_VENDOR_DEFAULT_SETTLEMENT_DAY  = sd;
            SYS_VENDOR_DEFAULT_PAYMENT_METHOD  = pm;
            SYS_VENDOR_DEFAULT_NET_DAYS        = nd;
        } else showToast(r.message||'儲存失敗','error');
    });
}
function saveCustPaymentSetting() {
    var sm = (document.getElementById('dict-cust-settlement_mode')||{}).value || 'FIXED';
    var sd = (document.getElementById('dict-cust-settlement_day')||{}).value || '';
    var pm = (document.getElementById('dict-cust-payment_method')||{}).value || '匯款';
    var nd = (document.getElementById('dict-cust-net_days')||{}).value || '';
    if (sm === 'FIXED' && (!sd || parseInt(sd) < 1 || parseInt(sd) > 31)) { showToast('固定結帳日需為 1~31','error'); return; }
    api({ action:'manage_system_settings', op:'save', cust_default_settlement_mode:sm, cust_default_settlement_day:sd, cust_default_payment_method:pm, cust_default_net_days:nd }).done(function(r) {
        if (r.success) {
            showToast('客戶預設付款條件已儲存');
            SYS_CUST_DEFAULT_SETTLEMENT_MODE = sm;
            SYS_CUST_DEFAULT_SETTLEMENT_DAY  = sd;
            SYS_CUST_DEFAULT_PAYMENT_METHOD  = pm;
            SYS_CUST_DEFAULT_NET_DAYS        = nd;
        } else showToast(r.message||'儲存失敗','error');
    });
}

// Store current dict data for edit access
var _dictDataCache = {};

function renderDictTable(type, data) {
    var cfg = dictConfig[type];
    _dictDataCache = {};  // reset cache
    var html = '';
    if (!data.length) {
        html = '<tr><td colspan="3" class="text-center" style="padding:32px;color:#aaa;"><i class="fa fa-inbox" style="font-size:24px;display:block;margin-bottom:8px;"></i>目前無資料，請使用上方表單新增</td></tr>';
    } else {
        data.forEach(function(d, idx) {
            var id = cfg.getId(d);
            _dictDataCache[String(idx)] = d;  // cache by index
            html += '<tr>';
            if (type === 'maker-sub') {
                var grpLabel = {PROCESS:'加工',CONSUMABLE:'耗材',TOOL:'工具',OTHER:'其他'};
                var grpColor = {PROCESS:'var(--accent)',CONSUMABLE:'#e67e22',TOOL:'#3498db',OTHER:'#aaa'};
                var g = d.sub_cat_group||'PROCESS';
                html += '<td><span style="font-size:10px;background:'+grpColor[g]+';color:#fff;border-radius:3px;padding:1px 5px;">'+(grpLabel[g]||g)+'</span></td>';
                var cats = d.main_cat_names
                    ? d.main_cat_names.split(', ').map(function(n){ return '<span style="font-size:10px;background:#eef2ff;color:#5856d6;padding:1px 5px;border-radius:3px;">'+escHtml(n)+'</span>'; }).join(' ')
                    : '<span style="color:#ccc;font-size:11px;">未綁定</span>';
                html += '<td><strong>'+escHtml(d.sub_cat_name)+'</strong><br><span style="font-size:11px;">'+cats+'</span></td>';
            } else if (type === 'workpiece') {
                html += '<td><span class="dict-code-badge">'+escHtml(d.type_code)+'</span></td>';
                html += '<td>'+escHtml(d.type_name)+'</td>';
            } else if (type === 'workpiece-sub') {
                var wpal = _wpPalette[0];
                html += '<td><span class="dict-code-badge" style="background:#eef2ff;color:#5856d6;">'+escHtml(d.type_code||'')+'</span></td>';
                html += '<td>'+escHtml(d.sub_type_name||'')+'</td>';
            } else if (type === 'label') {
                html += '<td><span class="dict-code-badge">'+escHtml(d.type_code||'')+'</span>'+(d.type_name?'<br><span style="font-size:10px;color:#aaa;">'+escHtml(d.type_name)+'</span>':'')+'</td>';
                html += '<td>'+cfg.renderRow(d)+'</td>';
            } else {
                html += '<td>'+cfg.renderRow(d)+'</td>';
            }
            html += '<td style="text-align:center;">';
            if (_canEditDict(type)) html += '<button class="btn btn-xs btn-default" onclick="editDictEntry('+idx+')" title="編輯" style="margin-right:3px;"><i class="fa fa-pencil"></i></button>';
            var canDelThis = (type === 'maker-proc-label') ? CAN_DELETE_ALL : _canEditDict(type);
            if (canDelThis) html += '<button class="btn btn-xs btn-danger"  onclick="deleteDictEntry(\''+escAttr(String(id))+'\')" title="刪除"><i class="fa fa-trash"></i></button>';
            html += '</td></tr>';
        });
    }
    $('#dict-table-body').html(html);
    // Add data-row-id for sortable reorder
    document.querySelectorAll('#dict-table-body tr').forEach(function(tr, i) {
        var id = data[i] ? dictConfig[type].getId(data[i]) : null;
        if (id) tr.dataset.rowId = id;
    });
    initDictTableSortable(type);
}

function viewLabelSubs(idx) {
    var d = _dictDataCache[String(idx)];
    if (!d || !d.label_id) return;
    if (_canEditDict('label')) {
        editDictEntry(idx);
    }
    openSubSlideout(d.label_name || '');
    loadLabelSubs(d.label_id);
}

function editDictEntry(idx) {
    var d = _dictDataCache[String(idx)];
    if (!d) { showToast('找不到資料，請重新載入','error'); return; }
    var cfg = dictConfig[currentDictType];
    $('#dict-edit-id').val(cfg.getId(d));
    cfg.fillForm(d);
    // scroll form into view & highlight
    var formArea = document.getElementById('dict-form-area');
    formArea.scrollIntoView({behavior:'smooth', block:'nearest'});
    formArea.style.background = '#fffbf0';
    setTimeout(function(){ formArea.style.background = ''; }, 800);
}


// ── 規格模板變數 Chips ────────────────────────────────────────────────────
var _tmplVarMap = {
    standard:     [{v:'Module',l:'模數'},{v:'Teeth',l:'齒數'},{v:'Face_Width',l:'齒寬'},{v:'Pressure_Angle',l:'壓力角'},{v:'X_PART',l:'轉位係數'},{v:'GRADE',l:'等級'},{v:'Remark_Gear',l:'備註'}],
    worm_gear:    [{v:'Module',l:'模數'},{v:'spec_starts',l:'牙口數'},{v:'Face_Width',l:'齒寬'},{v:'Pressure_Angle',l:'壓力角'},{v:'Remark_Gear',l:'備註'}],
    worm_wheel:   [{v:'Module',l:'模數'},{v:'Teeth',l:'齒數'},{v:'Face_Width',l:'齒寬'},{v:'Pressure_Angle',l:'壓力角'},{v:'X_PART',l:'轉位係數'},{v:'GRADE',l:'等級'},{v:'Remark_Gear',l:'備註'}],
    rack:         [{v:'Module',l:'模數'},{v:'Teeth',l:'齒數'},{v:'Face_Width',l:'齒寬'},{v:'Pressure_Angle',l:'壓力角'},{v:'GRADE',l:'等級'},{v:'Remark_Gear',l:'備註'}],
    sprocket:     [{v:'spec_chain_size',l:'鏈條規格'},{v:'Teeth',l:'齒數'},{v:'spec_pitch',l:'節距 P'},{v:'spec_roller_dia',l:'滾子外徑 Dr'},{v:'Remark_Gear',l:'備註'}],
    timing_pulley:[{v:'spec_pulley_profile',l:'皮帶齒型'},{v:'Teeth',l:'齒數'},{v:'spec_pitch',l:'節距'},{v:'Remark_Gear',l:'備註'}],
    spline:       [{v:'Module',l:'模數'},{v:'Teeth',l:'鍵數'},{v:'Pressure_Angle',l:'壓力角'},{v:'spec_spline_type',l:'花鍵齒形'},{v:'spec_spline_major_dia',l:'大徑'},{v:'spec_spline_minor_dia',l:'小徑'},{v:'spec_spline_width',l:'鍵寬'},{v:'Remark_Gear',l:'備註'}]
};

function updateTmplVarChips() {
    var wrap = document.getElementById('tmpl-var-chips');
    if (!wrap) return;
    var cat = (document.getElementById('dict-f-spec-cat')||{}).value || 'standard';
    var hasHelix = !!(document.getElementById('dict-f-helix')||{}).checked;
    var vars = (_tmplVarMap[cat] || _tmplVarMap['standard']).slice();
    if (hasHelix) {
        vars = [{v:'Helix_Direction',l:'旋向'},{v:'Helix_Angle_Str',l:'螺旋角'}].concat(vars);
    }
    wrap.innerHTML = vars.map(function(item) {
        return '<button type="button" onclick="insertTmplVar(\''+item.v+'\')" style="'
            +'font-size:11px;padding:2px 7px;border:1px solid #d0d7de;border-radius:3px;background:#f6f8fa;'
            +'cursor:pointer;white-space:nowrap;color:#24292f;line-height:1.6;" title="插入 {'+item.v+'}">'
            +escHtml(item.l)+'<span style="color:#888;font-size:10px;margin-left:3px;">{'+item.v+'}</span>'
            +'</button>';
    }).join('');
}

function insertTmplVar(token) {
    var inp = document.getElementById('dict-f-display-tmpl');
    if (!inp) return;
    var s = inp.selectionStart, e = inp.selectionEnd;
    var v = inp.value;
    var ins = '{'+token+'}';
    inp.value = v.substring(0,s) + ins + v.substring(e);
    var pos = s + ins.length;
    inp.focus();
    inp.setSelectionRange(pos, pos);
}

// ── Attach Category helpers ────────────────────────────────────────────────
var _attachCats = [];  // [{id,category_name,show_in_list,tag_variables,is_active}]

function loadAttachCatPanel() {
    api({ action:'manage_attach_categories', op:'get_path' }).done(function(r) {
        if (r.success) {
            var n = document.getElementById('acat-nas-path'), u = document.getElementById('acat-url-path');
            if (n) n.value = r.nas_dir || ''; if (u) u.value = r.url_dir || '';
        }
    });
    loadAttachCatTable();
}

function loadAttachCatTable() {
    api({ action:'manage_attach_categories', op:'list' }).done(function(r) {
        if (!r.success) return;
        _attachCats = r.data || [];
        var tbody = document.getElementById('acat-table-body');
        if (!tbody) return;
        var html = '';
        _attachCats.forEach(function(c) {
            var badge = c.is_active=='1'||c.is_active===1
                ? '<span class="label label-success" style="font-size:9px;">啟用</span>'
                : '<span class="label label-default" style="font-size:9px;">停用</span>';
            var vars = [];
            try { vars = JSON.parse(c.tag_variables || '[]'); } catch(e) { vars = []; }
            var varBadge = vars.length ? '<span style="font-size:9px;background:#e8f4fd;color:#1a5276;border-radius:3px;padding:1px 4px;margin-left:3px;">'+vars.length+'變數</span>' : '';
            var showBadge = (c.show_in_list=='1'||c.show_in_list===1) ? '<i class="fa fa-eye" style="color:#27ae60;" title="列表顯示"></i>' : '<i class="fa fa-eye-slash" style="color:#ccc;"></i>';
            html += '<tr data-cat-id="'+c.id+'">';
            html += '<td style="cursor:grab;color:#bbb;text-align:center;" class="acat-drag-handle">&#9776;</td>';
            var odBadge = (c.is_own_drawing=='1'||c.is_own_drawing===1)
                ? '<span style="font-size:9px;background:#FFF3E2;color:#C77C1A;border:1px solid #E4D3BC;border-radius:3px;padding:1px 4px;margin-left:3px;" title="自家出的圖：上傳需填發行章日期，並參與圖面變更判定">自家圖</span>' : '';
            var extBadge = (c.is_external_doc=='1'||c.is_external_doc===1)
                ? '<span style="font-size:9px;background:#F0A24B;color:#fff;border-radius:3px;padding:1px 4px;margin-left:3px;" title="列入外來文件清單'+(c.external_doc_name?'：'+escHtml(c.external_doc_name):'')+'">外來文件</span>' : '';
            html += '<td>'+escHtml(c.category_name)+varBadge+odBadge+extBadge+'&nbsp;'+badge+'</td>';
            html += '<td style="text-align:center;">'+showBadge+'</td>';
            html += '<td style="text-align:right;">'+badge+'</td>';
            if (CAN_ATTACH_CAT_EDIT) {
                html += '<td style="text-align:right;white-space:nowrap;">';
                html += '<button class="btn btn-xs btn-warning" onclick="editAttachCat('+c.id+')"><i class="fa fa-pencil"></i></button> ';
                if (c.is_active=='1'||c.is_active===1) {
                    html += '<button class="btn btn-xs btn-danger" onclick="deactivateAttachCat('+c.id+')" title="停用"><i class="fa fa-ban"></i></button>';
                } else {
                    html += '<button class="btn btn-xs btn-default" onclick="reactivateAttachCat('+c.id+')" title="啟用"><i class="fa fa-check"></i></button>';
                }
                html += '</td>';
            }
            html += '</tr>';
        });
        tbody.innerHTML = html || '<tr><td colspan="5" class="text-center text-muted">無資料</td></tr>';
        initAcatTableDrag();
    });
}

function initAcatTableDrag() {
    if (!CAN_ATTACH_CAT_EDIT) return;
    var tbody = document.getElementById('acat-table-body');
    if (!tbody) return;
    var dragging = null;
    tbody.querySelectorAll('tr').forEach(function(tr) {
        var handle = tr.querySelector('.acat-drag-handle');
        if (!handle) return;
        handle.addEventListener('mousedown', function() { tr.setAttribute('draggable','true'); });
        tr.addEventListener('dragend',   function() { tr.setAttribute('draggable','false'); dragging = null; });
        tr.addEventListener('dragstart', function(e) { dragging = tr; e.dataTransfer.effectAllowed='move'; setTimeout(function(){$(tr).css('opacity','0.4');},0); });
        tr.addEventListener('dragover',  function(e) { e.preventDefault(); if (!dragging||dragging===tr) return; var rect=tr.getBoundingClientRect(); if(e.clientY<rect.top+rect.height/2) tbody.insertBefore(dragging,tr); else tbody.insertBefore(dragging,tr.nextSibling); });
        tr.addEventListener('drop', function(e) {
            e.preventDefault(); $(dragging).css('opacity','');
            var ids = Array.from(tbody.querySelectorAll('tr[data-cat-id]')).map(function(r){ return r.dataset.catId; });
            api({ action:'manage_attach_categories', op:'reorder', ids:JSON.stringify(ids) }).done(function(){ _attachCatsCache = null; loadAttachCatTable(); });
        });
    });
}

function saveAttachCatPath() {
    var nas = (document.getElementById('acat-nas-path')||{}).value||'';
    var url = (document.getElementById('acat-url-path')||{}).value||'';
    if (!nas||!url) { showToast('路徑不可為空','error'); return; }
    api({ action:'manage_attach_categories', op:'save_path', nas_dir:nas, url_dir:url }).done(function(r) {
        if (r.success) showToast('路徑已儲存');
        else showToast(r.message||'儲存失敗','error');
    });
}

function editAttachCat(id) {
    var c = _attachCats.find(function(x){ return x.id==id; });
    if (!c) return;
    document.getElementById('acat-edit-id').value = id;
    document.getElementById('acat-name-input').value = c.category_name||'';
    var silChk = document.getElementById('acat-show-in-list');
    if (silChk) silChk.checked = (c.show_in_list=='1'||c.show_in_list===1);
    var odChk = document.getElementById('acat-own-drawing');
    if (odChk) odChk.checked = (c.is_own_drawing=='1'||c.is_own_drawing===1);
    var extChk = document.getElementById('acat-external-doc');
    if (extChk) {
        extChk.checked = (c.is_external_doc=='1'||c.is_external_doc===1);
        var extWrap = document.getElementById('acat-extdoc-name-wrap');
        if (extWrap) extWrap.style.display = extChk.checked ? '' : 'none';
        var extName = document.getElementById('acat-extdoc-name');
        if (extName) extName.value = c.external_doc_name || '';
    }
    document.getElementById('acat-form-title').textContent = '修改類別';
    // Render vars
    var varsList = document.getElementById('acat-vars-list');
    if (varsList) {
        varsList.innerHTML = '';
        var vars = [];
        try { vars = JSON.parse(c.tag_variables||'[]'); } catch(e) { vars = []; }
        vars.forEach(function(v) { varsList.appendChild(buildAttachVarRow(v)); });
    }
}

function resetAttachCatForm() {
    document.getElementById('acat-edit-id').value = '';
    document.getElementById('acat-name-input').value = '';
    var silChk = document.getElementById('acat-show-in-list');
    if (silChk) silChk.checked = false;
    var odChk = document.getElementById('acat-own-drawing');
    if (odChk) odChk.checked = false;
    var extChk = document.getElementById('acat-external-doc');
    if (extChk) extChk.checked = false;
    var extWrap = document.getElementById('acat-extdoc-name-wrap');
    if (extWrap) extWrap.style.display = 'none';
    var extName = document.getElementById('acat-extdoc-name');
    if (extName) extName.value = '';
    document.getElementById('acat-form-title').textContent = '新增類別';
    var varsList = document.getElementById('acat-vars-list');
    if (varsList) varsList.innerHTML = '';
}

function getAttachCatVars() {
    var rows = document.querySelectorAll('#acat-vars-list .acat-var-row');
    var vars = [];
    rows.forEach(function(row) {
        var k = (row.querySelector('.acat-var-key')||{}).value||'';
        var h = (row.querySelector('.acat-var-hint')||{}).value||'';
        if (k) vars.push({ key:k, hint:h });
    });
    return vars;
}

function buildAttachVarRow(v) {
    var key  = v ? escHtml(v.key||'') : '';
    var hint = v ? escHtml(v.hint||'') : '';
    var div = document.createElement('div');
    div.className = 'acat-var-row';
    div.style.cssText = 'display:flex;gap:4px;margin-bottom:4px;align-items:center;';
    div.innerHTML = '<span style="color:#888;font-size:13px;">{</span>'
        + '<input type="text" class="form-control input-sm acat-var-key" style="width:70px;" placeholder="變數名" maxlength="20" value="'+key+'">'
        + '<span style="color:#888;font-size:13px;">}</span>'
        + '<input type="text" class="form-control input-sm acat-var-hint" style="flex:1;" placeholder="填寫提示" maxlength="50" value="'+hint+'">'
        + '<button type="button" class="btn btn-xs btn-danger" onclick="$(this).closest(\'.acat-var-row\').remove()"><i class="fa fa-times"></i></button>';
    return div;
}

function addAttachCatVar() {
    var varsList = document.getElementById('acat-vars-list');
    if (varsList) varsList.appendChild(buildAttachVarRow(null));
}

function saveAttachCategory() {
    var id   = parseInt(document.getElementById('acat-edit-id').value)||0;
    var name = (document.getElementById('acat-name-input').value||'').trim();
    var sil  = document.getElementById('acat-show-in-list');
    var showInList = (sil && sil.checked) ? 1 : 0;
    var od   = document.getElementById('acat-own-drawing');
    var ownDrawing = (od && od.checked) ? 1 : 0;
    var ext  = document.getElementById('acat-external-doc');
    var isExtDoc = (ext && ext.checked) ? 1 : 0;
    var extDocName = ((document.getElementById('acat-extdoc-name')||{}).value||'').trim();
    if (!name) { showToast('請填寫類別名稱','error'); return; }
    var vars = getAttachCatVars();
    var tagVarsJson = vars.length ? JSON.stringify(vars) : '';
    api({ action:'manage_attach_categories', op:'save', cat_id:id, category_name:name, sort_order:0, show_in_list:showInList, is_own_drawing:ownDrawing, is_external_doc:isExtDoc, external_doc_name:extDocName, tag_variables:tagVarsJson }).done(function(r) {
        if (r.success) { _attachCatsCache = null; showToast(r.message||'已儲存'); resetAttachCatForm(); loadAttachCatTable(); }
        else showToast(r.message||'儲存失敗','error');
    });
}

function deactivateAttachCat(id) {
    if (!confirm('確定停用此類別？')) return;
    api({ action:'manage_attach_categories', op:'deactivate', cat_id:id }).done(function(r) {
        if (r.success) { _attachCatsCache = null; showToast('已停用'); loadAttachCatTable(); }
        else showToast(r.message||'失敗','error');
    });
}

function reactivateAttachCat(id) {
    api({ action:'manage_attach_categories', op:'save', cat_id:id, category_name:'__reactivate__', reactivate:1 }).done(function(r) {
        if (r.success) { _attachCatsCache = null; showToast('已重新啟用'); loadAttachCatTable(); }
        else showToast(r.message||'失敗','error');
    });
}

// ── 料號附件操作 ───────────────────────────────────────────────────────────
var _palCurrentDId    = 0;
var _palCurrentPartNo = '';
var _attachCatsCache  = null;  // 快取活躍類別

function loadActiveCatsForUpload(cb) {
    if (_attachCatsCache !== null) { cb(_attachCatsCache); return; }
    api({ action:'manage_attach_categories', op:'list' }).done(function(r) {
        _attachCatsCache = (r.success && r.data) ? r.data.filter(function(c){ return c.is_active=='1'||c.is_active===1; }) : [];
        cb(_attachCatsCache);
    }).fail(function() {
        _attachCatsCache = [];
        cb(_attachCatsCache);
    });
}

// ── 附件瀏覽器 Modal ───────────────────────────────────────────────────────
var _pav = { dId:0, partNo:'', mode:'all', catId:0, allFiles:[], filteredFiles:[], currentFile:null, quoteSummaries:{} };
var _pav3dViewer = null;

function _pavShowUploadBtn(show) {
    var upLabel = document.querySelector('#partAttachViewModal label[title="上傳附件"]');
    if (upLabel) upLabel.style.display = show ? '' : 'none';
}

function openAttachTagView(dId, partNo, catId, catName) {
    _pav.dId=dId; _pav.partNo=partNo; _pav.mode='all'; _pav.catId=0;
    document.getElementById('pav-part-no').textContent = partNo;
    document.getElementById('pav-list-title').textContent = '全部附件';
    _pavShowUploadBtn(true);
    _pavOpen();
    _pavLoadFiles(function(files) {
        _pavBuildCatTabs(files);
        _pav.filteredFiles = files.filter(function(f){ return f.source !== 'quote'; });
        _pavRenderList();
        // 自動切換到指定標籤
        if (catId) {
            var targetBtn = document.querySelector('#pav-cat-tabs .pav-tab[data-cat="'+catId+'"]');
            if (targetBtn) { setTimeout(function(){ pavSwitchTab(targetBtn, String(catId)); }, 50); }
        }
    });
}

function openAttachAllView(dId, partNo) {
    _pav.dId=dId; _pav.partNo=partNo; _pav.mode='all'; _pav.catId=0;
    document.getElementById('pav-part-no').textContent = partNo;
    document.getElementById('pav-list-title').textContent = '全部附件';
    _pavShowUploadBtn(true);
    _pavOpen();
    _pavLoadFiles(function(files) {
        _pavBuildCatTabs(files);
        _pav.filteredFiles = files.filter(function(f){ return f.source !== 'quote'; });
        _pavRenderList();
    });
}

function openAttachQuoteView(dId, partNo) {
    _pav.dId=dId; _pav.partNo=partNo; _pav.mode='quote'; _pav.catId=0;
    _pav.quoteSummaries = {};
    document.getElementById('pav-part-no').textContent = partNo;
    document.getElementById('pav-list-title').textContent = '報價單（唯讀）';
    document.getElementById('pav-cat-tabs').style.display = 'none';
    _pavShowUploadBtn(false);
    _pavOpen();
    _pavLoadFiles(function(files) {
        _pav.filteredFiles = files.filter(function(f){ return f.source === 'quote'; });
        // 收集所有 quote_no，批次取報價單摘要（無附件時由後端依 d_id 撈）
        var qNos = [];
        _pav.filteredFiles.forEach(function(f){ if (f.quote_no && qNos.indexOf(f.quote_no)<0) qNos.push(f.quote_no); });
        $.post(PART_ATTACH_API_URL, { action:'get_quote_summaries', quote_nos:JSON.stringify(qNos), d_id:_pav.dId }, function(r) {
            _pav.quoteSummaries = (r.success && r.data && typeof r.data === 'object' && !Array.isArray(r.data)) ? r.data : {};
            _pavRenderList();
        }).fail(function(){ _pavRenderList(); });
    });
}

function _pavOpen() {
    document.getElementById('pav-file-list').innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;font-size:12px;"><i class="fa fa-spinner fa-spin"></i></div>';
    document.getElementById('pav-preview').innerHTML   = '<div style="color:#aaa;font-size:13px;">← 點擊左側檔案預覽</div>';
    document.getElementById('pav-actions').style.display = 'none';
    _pav.currentFile = null;
    $('#partAttachViewModal').modal('show');
}

function _pavLoadFiles(cb) {
    $.get(PART_ATTACH_API_URL, { action:'list', d_id:_pav.dId }, function(r) {
        _pav.allFiles = (r.success && r.data) ? r.data : [];
        cb(_pav.allFiles);
    }).fail(function(){ _pav.allFiles=[]; cb([]); });
}

function _pavBuildCatTabs(files) {
    var tabBar = document.getElementById('pav-cat-tabs');
    if (!tabBar) return;
    var cats   = _attachCatsCache || [];
    // Collect cat IDs present in files
    var usedCats = {};
    files.forEach(function(f) {
        if (f.source === 'quote') return;
        if (!f.category_ids) { usedCats['__none__'] = '未分類'; return; }
        f.category_ids.split(',').forEach(function(cid) {
            var c = cats.find(function(x){ return String(x.id)===cid.trim(); });
            if (c) usedCats[cid.trim()] = c.category_name;
        });
    });
    var html = '<button class="pav-tab active" data-cat="__all__" onclick="pavSwitchTab(this,\'__all__\')" style="font-size:11px;background:#fff;color:#1a5276;border:1px solid #aed6f1;border-radius:10px;padding:2px 10px;cursor:pointer;margin-right:3px;">全部</button>';
    Object.keys(usedCats).forEach(function(cid) {
        html += '<button class="pav-tab" data-cat="'+cid+'" onclick="pavSwitchTab(this,\''+cid+'\')" style="font-size:11px;background:rgba(255,255,255,.2);color:#fff;border:1px solid rgba(255,255,255,.5);border-radius:10px;padding:2px 10px;cursor:pointer;margin-right:3px;">'+escHtml(usedCats[cid])+'</button>';
    });
    tabBar.innerHTML = html;
    tabBar.style.cssText = 'display:flex;flex:1;gap:4px;flex-wrap:wrap;align-items:center;min-width:0;';
}

function pavSwitchTab(btn, catId) {
    document.querySelectorAll('.pav-tab').forEach(function(b){
        b.style.background = 'rgba(255,255,255,.2)'; b.style.color='#fff'; b.classList.remove('active');
    });
    btn.style.background='#fff'; btn.style.color='#1a5276'; btn.classList.add('active');
    if (catId === '__all__') {
        _pav.filteredFiles = _pav.allFiles.filter(function(f){ return f.source !== 'quote'; });
    } else if (catId === '__none__') {
        _pav.filteredFiles = _pav.allFiles.filter(function(f){ return f.source !== 'quote' && !f.category_ids; });
    } else {
        _pav.filteredFiles = _pav.allFiles.filter(function(f){
            return f.source !== 'quote' && f.category_ids && f.category_ids.split(',').map(function(x){ return x.trim(); }).indexOf(catId) >= 0;
        });
    }
    _pavRenderList();
}

function _pavRenderQuoteGroupList(files, wrap) {
    // 依 quote_no 分組，每組按最新附件時間排序（由新到舊）
    var groups = {};  // quote_no → [files...]
    files.forEach(function(f) {
        var qno = f.quote_no || '__unknown__';
        if (!groups[qno]) groups[qno] = [];
        groups[qno].push(f);
    });
    // quoteSummaries 裡的報價單號也加入（無附件時仍需顯示）
    if (_pav.quoteSummaries) {
        Object.keys(_pav.quoteSummaries).forEach(function(qno) {
            if (!groups[qno]) groups[qno] = [];
        });
    }
    // 每組取最新 uploaded_at，用於組間排序；無附件的以 quote_date 排序
    var sortedQnos = Object.keys(groups).filter(function(q){ return q !== '__unknown__'; }).sort(function(a, b) {
        var aMax = groups[a].reduce(function(m, f){ return f.uploaded_at > m ? f.uploaded_at : m; }, (_pav.quoteSummaries&&_pav.quoteSummaries[a]) ? (_pav.quoteSummaries[a].quote_date||'') : '');
        var bMax = groups[b].reduce(function(m, f){ return f.uploaded_at > m ? f.uploaded_at : m; }, (_pav.quoteSummaries&&_pav.quoteSummaries[b]) ? (_pav.quoteSummaries[b].quote_date||'') : '');
        return bMax > aMax ? 1 : (bMax < aMax ? -1 : b.localeCompare(a));
    });
    if (groups['__unknown__'] && groups['__unknown__'].length) sortedQnos.push('__unknown__');

    var html = '';
    sortedQnos.forEach(function(qno) {
        var grpFiles = groups[qno];
        var qs = (_pav.quoteSummaries && _pav.quoteSummaries[qno]) || null;

        // ── 報價單標題 ──────────────────────────────────────────────
        // 彙整此報價中所有品項的製程（主製程 + sub-tags）
        var qProcs = [];
        if (qs && qs.items) {
            qs.items.forEach(function(it) {
                var procParts = (it.processes || []).map(function(p){ return p.name; });
                var subParts  = (it.subtags  || []);
                var allParts  = procParts.concat(subParts);
                if (!allParts.length) return;
                var key   = allParts.join('|');
                var label = procParts.map(escHtml).join('・');
                if (subParts.length) label += '<span style="color:#555;font-weight:400;">・' + subParts.map(escHtml).join('・') + '</span>';
                if (qProcs.findIndex(function(x){ return x.key===key; }) < 0) qProcs.push({key:key, label:label});
            });
        }
        html += '<div data-qno="'+escAttr(qno)+'" style="background:#f0f4fb;border-bottom:2px solid #b8d0f0;padding:8px 10px;cursor:pointer;position:sticky;top:0;z-index:1;transition:background .15s;" onclick="pavShowQuoteDetail(\''+escAttr(qno)+'\')">';
        html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;">';
        html += '<div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;min-width:0;">';
        html += '<span style="font-size:12px;font-weight:700;color:#1a5276;font-family:Consolas,monospace;white-space:nowrap;">'+escHtml(qno)+'</span>';
        if (qProcs.length) {
            html += '<span style="display:inline-flex;flex-direction:column;gap:1px;">';
            qProcs.forEach(function(p) {
                html += '<span style="font-size:10px;font-weight:600;color:#1b5e20;background:#e8f5e9;border-radius:3px;padding:0 5px;white-space:nowrap;line-height:1.7;">'+p.label+'</span>';
            });
            html += '</span>';
        }
        html += '</div>';
        if (qs && qs.total_amount) {
            html += '<span style="font-size:11px;color:#e74c3c;font-weight:600;white-space:nowrap;margin-left:4px;">$'+Number(qs.total_amount).toLocaleString()+'</span>';
        }
        html += '</div>';
        if (qs) {
            html += '<div style="font-size:11px;color:#555;margin-top:2px;display:flex;gap:8px;flex-wrap:wrap;">';
            if (qs.quote_date) html += '<span><i class="fa fa-calendar" style="color:#aaa;margin-right:2px;"></i>'+escHtml(qs.quote_date)+'</span>';
            if (qs.client_name) html += '<span><i class="fa fa-building-o" style="color:#aaa;margin-right:2px;"></i>'+escHtml(qs.client_name)+'</span>';
            if (qs.handler_name) html += '<span><i class="fa fa-user" style="color:#aaa;margin-right:2px;"></i>'+escHtml(qs.handler_name)+'</span>';
            html += '</div>';
            // 品項摘要
            if (qs.items && qs.items.length) {
                html += '<div style="margin-top:4px;border-top:1px dashed #d0ddef;padding-top:4px;">';
                qs.items.forEach(function(it) {
                    var priceStr = it.is_tiered ? '(階梯)' : (it.unit_price ? '$'+Number(it.unit_price).toLocaleString() : '');
                    html += '<div style="font-size:10px;color:#555;line-height:1.5;">';
                    html += '<span style="color:#1a5276;font-weight:600;">'+escHtml(it.product_id||'')+'</span>';
                    if (it.specification) html += ' <span style="color:#888;">'+escHtml(it.specification)+'</span>';
                    html += ' &times;'+escHtml(String(it.quantity||''))+' '+(it.unit||'');
                    if (priceStr) html += ' <span style="color:#e74c3c;">'+escHtml(priceStr)+'</span>';
                    html += '</div>';
                });
                html += '</div>';
            }
        }
        html += '</div>';

        // ── 此報價的附件列表（顯示標籤、日期、上傳者） ─────────────
        var cats = _attachCatsCache || [];
        var catMap = {};
        cats.forEach(function(c){ catMap[String(c.id)] = c.category_name; });
        grpFiles.forEach(function(f) {
            var globalIdx = files.indexOf(f);
            var dt = (f.uploaded_at||'').replace('T',' ').substring(0,16);
            // 取標籤名稱
            var tagLabels = [];
            if (f.category_ids) {
                f.category_ids.split(',').forEach(function(cid) {
                    var cn = catMap[cid.trim()];
                    if (cn) tagLabels.push(cn);
                });
            }
            var tagDisplay = tagLabels.length
                ? tagLabels.map(function(t){ return '<span style="font-size:10px;background:#e8f4fd;color:#1a5276;border-radius:3px;padding:1px 6px;margin-right:2px;">'+escHtml(t)+'</span>'; }).join('')
                : '<span style="font-size:10px;color:#aaa;">未分類</span>';
            html += '<div class="pav-file-item" data-idx="'+globalIdx+'" onclick="pavSelectFile('+globalIdx+')" '
                  + 'style="padding:5px 10px 5px 18px;cursor:pointer;border-bottom:1px solid #f0f0f0;transition:background .1s;display:flex;align-items:center;gap:6px;">';
            html += '<div style="flex:1;min-width:0;">';
            html += '<div>'+tagDisplay+'</div>';
            html += '<div style="font-size:10px;color:#aaa;margin-top:2px;display:flex;gap:8px;">';
            html += '<span>'+escHtml(dt)+'</span>';
            if (f.uploaded_by) html += '<span><i class="fa fa-user" style="opacity:.5;margin-right:2px;"></i>'+escHtml(f.uploaded_by)+'</span>';
            html += '</div></div>';
            html += '</div>';
        });
    });
    wrap.innerHTML = html;
    // 預設顯示最新報價單內容
    if (sortedQnos.length) pavShowQuoteDetail(sortedQnos[0]);
}

function pavShowQuoteDetail(qno) {
    var qs = (_pav.quoteSummaries && _pav.quoteSummaries[qno]) || null;
    var preview = document.getElementById('pav-preview');
    if (!preview) return;
    // 隱藏動作列（純報價資訊不需要）
    var actions = document.getElementById('pav-actions');
    if (actions) actions.style.display = 'none';
    _pav.currentFile = null;
    // 高亮對應的報價標題列
    document.querySelectorAll('.pav-file-item').forEach(function(el){ el.style.background=''; });
    document.querySelectorAll('[data-qno]').forEach(function(el){ el.style.background = el.dataset.qno===qno ? '#ddeeff' : ''; });

    var html = '<div style="width:100%;height:100%;overflow-y:auto;padding:16px;background:#fff;">';
    html += '<div style="font-size:15px;font-weight:700;color:#1a5276;margin-bottom:12px;padding-bottom:8px;border-bottom:2px solid #d6eaf8;">';
    html += '<i class="fa fa-file-text-o" style="margin-right:6px;"></i>'+escHtml(qno)+'</div>';
    if (!qs) {
        html += '<div style="color:#aaa;font-size:12px;">報價資料載入中…</div>';
    } else {
        html += '<table style="font-size:12px;width:100%;max-width:480px;margin-bottom:16px;border-collapse:collapse;">';
        var rows = [
            ['報價日期', qs.quote_date],
            ['客戶名稱', qs.client_name],
            ['有效日期', qs.valid_date],
            ['負責人員', qs.handler_name],
            ['總金額',   qs.total_amount ? '$'+Number(qs.total_amount).toLocaleString() : '—'],
        ];
        rows.forEach(function(r) {
            if (!r[1]) return;
            html += '<tr><td style="color:#888;padding:3px 8px 3px 0;white-space:nowrap;">'+escHtml(r[0])+'</td>'
                  + '<td style="padding:3px 0;font-weight:600;color:#2c3e50;">'+escHtml(String(r[1]))+'</td></tr>';
        });
        if (qs.quote_note) {
            html += '<tr><td style="color:#888;padding:3px 8px 3px 0;white-space:nowrap;">報價單備註</td>'
                  + '<td style="padding:3px 0;color:#7d3c98;">'+escHtml(qs.quote_note)+'</td></tr>';
        }
        html += '</table>';
        if (qs.items && qs.items.length) {
            html += '<div style="font-size:12px;font-weight:700;color:#2c3e50;margin-bottom:6px;">報價品項</div>';
            html += '<table style="width:100%;font-size:11px;border-collapse:collapse;">';
            html += '<thead><tr style="background:#f5f7fa;">';
            html += '<th style="padding:4px 6px;text-align:left;border-bottom:1px solid #e4e8ed;">料號</th>';
            html += '<th style="padding:4px 6px;text-align:left;border-bottom:1px solid #e4e8ed;">製程／備註</th>';
            html += '<th style="padding:4px 6px;text-align:right;border-bottom:1px solid #e4e8ed;">數量</th>';
            html += '<th style="padding:4px 6px;text-align:right;border-bottom:1px solid #e4e8ed;">單價</th>';
            html += '</tr></thead><tbody>';
            qs.items.forEach(function(it) {
                // 製程行：主製程名稱
                var procParts = (it.processes || []).map(function(p){ return escHtml(p.name); });
                // sub-tag 行
                var subParts  = (it.subtags   || []).map(escHtml);
                // 合併顯示
                var combined = '';
                if (procParts.length || subParts.length) {
                    var mainLine = procParts.join('・');
                    if (subParts.length) mainLine += '<span style="color:#555;">・' + subParts.join('・') + '</span>';
                    combined += '<div style="color:#1b5e20;font-weight:600;">'+mainLine+'</div>';
                }
                if (it.specification) {
                    combined += '<div style="color:#7d3c98;font-size:10px;">'+escHtml(it.specification)+'</div>';
                }
                if (!combined) combined = '<span style="color:#ccc;">—</span>';
                html += '<tr style="border-bottom:1px solid #f0f0f0;">';
                html += '<td style="padding:4px 6px;color:#1a5276;font-weight:600;">'+escHtml(it.product_id||'')+'</td>';
                html += '<td style="padding:4px 6px;line-height:1.6;">'+combined+'</td>';
                html += '<td style="padding:4px 6px;text-align:right;">'+escHtml(String(it.quantity||''))+' '+(it.unit||'')+'</td>';
                html += '<td style="padding:4px 6px;text-align:right;color:'+(it.is_tiered?'#888':'#e74c3c')+';">'
                      + (it.is_tiered ? '(階梯)' : (it.unit_price ? '$'+Number(it.unit_price).toLocaleString() : '—'))+'</td>';
                html += '</tr>';
            });
            html += '</tbody></table>';
        }
    }
    html += '</div>';
    preview.innerHTML = html;
}

function _pavIsObsolete(file) {
    if (!file || !file.category_ids) return false;
    var cats = _attachCatsCache || [];
    for (var i = 0; i < cats.length; i++) {
        if (cats[i].category_name === '作廢') {
            var ids = String(file.category_ids).split(',');
            for (var j = 0; j < ids.length; j++) {
                if (ids[j].trim() === String(cats[i].id)) return true;
            }
        }
    }
    return false;
}

function _pavRenderList() {
    var wrap = document.getElementById('pav-file-list');
    if (!wrap) return;
    var files = _pav.filteredFiles;
    // ── 報價模式：依 quote_no 分組，顯示報價摘要 ────────────────────
    if (_pav.mode === 'quote') {
        var hasQS = _pav.quoteSummaries && Object.keys(_pav.quoteSummaries).length > 0;
        if (!files.length && !hasQS) {
            wrap.innerHTML = '<div style="color:#aaa;font-size:12px;text-align:center;padding:24px;"><i class="fa fa-inbox"></i><br>無報價單</div>';
            return;
        }
        _pavRenderQuoteGroupList(files, wrap);
        return;
    }
    if (!files.length) {
        wrap.innerHTML = '<div style="color:#aaa;font-size:12px;text-align:center;padding:24px;"><i class="fa fa-inbox"></i><br>無附件</div>';
        return;
    }
    var cats = _attachCatsCache || [];
    var catMap = {};
    cats.forEach(function(c){ catMap[String(c.id)] = c.category_name; });
    var html = '';
    files.forEach(function(f, idx) {
        var ext  = (f.filename||'').split('.').pop().toLowerCase();
        var icon = _fileIcon(ext);
        var name = escHtml(f.original_name || f.filename || '');
        var dt   = (f.uploaded_at||'').replace('T',' ').substring(0,16);
        var tags = '';
        if (f.source === 'quote') {
            tags = '<span style="font-size:12px;font-weight:600;background:#f3e8ff;color:#6e2fa3;border-radius:4px;padding:1px 7px;">報價</span>';
        } else if (f.category_ids) {
            f.category_ids.split(',').forEach(function(cid) {
                var cn = catMap[cid.trim()];
                // 「作廢」已用紅色標記顯示，不重複以一般標籤呈現
                if (cn && cn !== '作廢') tags += '<span style="font-size:12px;font-weight:600;background:#e8f4fd;color:#1a5276;border-radius:4px;padding:1px 7px;margin-right:2px;">'+escHtml(cn)+'</span>';
            });
        }
        // Encode file ref for onclick
        var fIdx = idx;
        var isObs = _pavIsObsolete(f);
        var itemStyle = 'padding:4px 8px;cursor:pointer;border-bottom:1px solid #f0f0f0;transition:background .1s;'
                      + (isObs ? 'background:#fff0f0;border-left:3px solid #e74c3c;' : '');
        html += '<div class="pav-file-item" data-idx="'+fIdx+'" data-obsolete="'+(isObs?'1':'0')+'" onclick="pavSelectFile('+fIdx+')" style="'+itemStyle+'">';
        // 第一行：圖示 + 檔名 +（行內作廢標記 / 版次）
        html += '<div style="display:flex;align-items:center;gap:5px;">';
        html += '<i class="fa '+icon+'" style="color:'+(isObs?'#c0392b':'#888')+';flex-shrink:0;font-size:12px;"></i>';
        html += '<span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;'+(isObs?'color:#c0392b;text-decoration:line-through;':'')+'">'+name+'</span>';
        if (isObs) html += '<span style="flex-shrink:0;background:#e74c3c;color:#fff;font-size:9px;font-weight:700;padding:0 5px;border-radius:3px;letter-spacing:1px;">作廢</span>';
        // 版次 0 也要顯示：不可用 if(f.revision) 判斷（0 / "0" 會被當成沒填）
        if (f.revision !== null && f.revision !== undefined && String(f.revision) !== '')
            html += '<span style="flex-shrink:0;background:#eef4fb;color:#1a5276;font-size:10px;font-weight:600;padding:0 5px;border-radius:3px;" title="版次">Rev.'+escHtml(f.revision)+'</span>';
        html += '</div>';
        // 第二行：日期 · 上傳者 · 標籤（單行）
        html += '<div style="display:flex;gap:5px;margin-top:1px;align-items:center;flex-wrap:wrap;font-size:10px;color:#aaa;line-height:1.3;">';
        html += '<span>'+escHtml(dt)+'</span>';
        if (f.uploaded_by) html += '<span style="color:#888;">'+escHtml(f.uploaded_by)+'</span>';
        if (tags) html += tags;
        if (f.note) html += '<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#666;" title="'+escHtml(f.note)+'"><i class="fa fa-comment-o" style="opacity:.5;margin-right:2px;"></i>'+escHtml(f.note)+'</span>';
        html += '</div>';
        html += '</div>';
    });
    wrap.innerHTML = html;
    // Auto-select first
    if (files.length) pavSelectFile(0);
}

function pavSelectFile(idx) {
    var file = _pav.filteredFiles[idx];
    if (!file) return;
    _pav.currentFile = file;
    // Highlight selected
    var isObsFile = _pavIsObsolete(file);
    document.querySelectorAll('.pav-file-item').forEach(function(el){
        el.style.background = el.dataset.obsolete === '1' ? '#fff0f0' : '';
    });
    var sel = document.querySelector('.pav-file-item[data-idx="'+idx+'"]');
    if (sel) sel.style.background = isObsFile ? '#ffd5d5' : '#e8f4fd';
    // Action bar
    var actions = document.getElementById('pav-actions');
    if (actions) actions.style.display = '';
    var nameBar = document.getElementById('pav-file-name-bar');
    if (nameBar) nameBar.textContent = file.original_name || file.filename || '';
    var btnSave = document.getElementById('pav-btn-save');
    if (btnSave) { btnSave.href = file.url; btnSave.download = file.original_name || file.filename || 'file'; }
    var ext = (file.filename||'').split('.').pop().toLowerCase();
    var imgExts = ['jpg','jpeg','png','gif','webp','bmp','svg'];
    var isImg = imgExts.indexOf(ext) >= 0;
    var btnPaint  = document.getElementById('pav-btn-paint');
    var btnMarkup = document.getElementById('pav-btn-markup');
    if (btnPaint)  { btnPaint.href = file.url; btnPaint.style.display  = isImg ? '' : 'none'; }
    if (btnMarkup) { btnMarkup.style.display = isImg ? '' : 'none'; }
    // 報價附件唯讀：隱藏刪除/編輯鈕
    var isQuote = file.source === 'quote';
    var btnDel  = document.getElementById('pav-btn-delete');
    var btnEdit = document.getElementById('pav-btn-edit');
    if (btnDel)  btnDel.style.display  = isQuote ? 'none' : '';
    if (btnEdit) btnEdit.style.display = isQuote ? 'none' : '';
    // Preview
    var preview = document.getElementById('pav-preview');
    if (!preview) return;
    if (_pav3dViewer) { try { _pav3dViewer.Destroy(); } catch(e){} _pav3dViewer = null; }
    var d3Exts = ['stp','step','stl','obj','igs','iges'];
    // Reset any 3D-mode style overrides（還原為置中的 flex；3D 模式才會改成 block）
    preview.style.display = 'flex';
    preview.style.position = '';
    preview.style.overflow = '';
    // 隱藏縮放工具列（圖片時才顯示）
    _pavCleanupImgZoom();
    var _zc = document.getElementById('pav-zoom-controls');
    if (_zc) _zc.style.display = 'none';
    if (imgExts.indexOf(ext) >= 0) {
        _pavZoom.scale = 1; _pavZoom.tx = 0; _pavZoom.ty = 0;
        preview.style.overflow = 'hidden';
        preview.innerHTML = '<img id="pav-preview-img" src="'+escHtml(file.url)+'" style="max-width:100%;max-height:100%;object-fit:contain;display:block;user-select:none;-webkit-user-drag:none;">';
        if (_zc) _zc.style.display = 'inline-flex';
        setTimeout(_pavInitImgZoom, 30);
    } else if (ext === 'pdf') {
        preview.innerHTML = '<iframe id="pav-preview-frame" src="'+escHtml(file.url)+'" style="width:100%;height:100%;border:none;"></iframe>';
    } else if (d3Exts.indexOf(ext) >= 0) {
        preview.style.display = 'block';
        preview.style.position = 'relative';
        preview.innerHTML = '<div id="pav-3d-viewer" style="position:absolute;top:0;left:0;right:0;bottom:0;"></div>'
            + '<div id="pav-3d-loading" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);color:#aaa;font-size:13px;z-index:2;pointer-events:none;">'
            + '<i class="fa fa-spinner fa-spin" style="margin-right:6px;"></i>載入中...</div>'
            + '<div style="position:absolute;bottom:8px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,.45);color:#fff;font-size:11px;padding:3px 10px;border-radius:4px;pointer-events:none;white-space:nowrap;z-index:1;">'
            + '<i class="fa fa-mouse-pointer"></i> 左鍵旋轉 &nbsp;|&nbsp; 右鍵平移 &nbsp;|&nbsp; 滾輪縮放'
            + '</div>';
        if (typeof OV !== 'undefined') {
            var container3d = document.getElementById('pav-3d-viewer');
            _pav3dViewer = new OV.EmbeddedViewer(container3d, {
                backgroundColor: new OV.RGBAColor(248, 249, 250, 255),
                defaultColor:    new OV.RGBColor(180, 180, 180),
                edgeSettings:    new OV.EdgeSettings(false, new OV.RGBColor(0,0,0), 1)
            });
            var _v3ref = _pav3dViewer;
            var fname3d = file.original_name || file.filename || 'model.stp';
            var url3d = file.url;
            fetch(url3d, { credentials: 'same-origin' })
                .then(function(r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.blob(); })
                .then(function(blob) {
                    var lEl = document.getElementById('pav-3d-loading');
                    if (lEl) lEl.style.display = 'none';
                    if (_v3ref === _pav3dViewer) _v3ref.LoadModelFromFileList([new File([blob], fname3d)]);
                })
                .catch(function() {
                    if (_v3ref !== _pav3dViewer) return;
                    var el = document.getElementById('pav-3d-viewer');
                    if (el) el.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;flex-direction:column;gap:10px;color:#888;">'
                        + '<i class="fa fa-exclamation-triangle" style="font-size:30px;color:#e74c3c;"></i>'
                        + '<div style="font-size:13px;">3D 模型載入失敗</div>'
                        + '<a href="'+escHtml(url3d)+'" target="_blank" download="'+escHtml(fname3d)+'" class="btn btn-sm btn-default"><i class="fa fa-download"></i> 下載開啟</a>'
                        + '</div>';
                });
        } else {
            document.getElementById('pav-3d-loading').style.display = 'none';
            document.getElementById('pav-3d-viewer').innerHTML =
                '<div style="display:flex;align-items:center;justify-content:center;height:100%;flex-direction:column;gap:10px;color:#888;">'
                + '<i class="fa fa-cube" style="font-size:40px;color:#ccc;"></i>'
                + '<div style="font-size:13px;">3D 檢視器尚未載入，請稍後再試</div>'
                + '<a href="'+escHtml(file.url)+'" target="_blank" download="'+escHtml(file.original_name||file.filename||'')+'" class="btn btn-sm btn-default"><i class="fa fa-download"></i> 下載開啟</a>'
                + '</div>';
        }
    } else {
        var fIcon = _fileIcon(ext);
        preview.innerHTML = '<div style="text-align:center;color:#555;">'
            + '<i class="fa '+fIcon+'" style="font-size:64px;color:#aaa;display:block;margin-bottom:12px;"></i>'
            + '<div style="font-size:13px;font-weight:600;">'+escHtml(file.original_name||file.filename||'')+'</div>'
            + '<div style="font-size:12px;color:#aaa;margin:6px 0;">'+escHtml((file.file_size||''))+'</div>'
            + '<a href="'+escHtml(file.url)+'" target="_blank" download="'+escHtml(file.original_name||file.filename||'')+'" class="btn btn-sm btn-primary" style="margin-top:8px;"><i class="fa fa-download"></i> 下載開啟</a>'
            + '</div>';
    }
    // ── 作廢 overlay ──────────────────────────────────────────────
    var existOv = preview.querySelector('.pav-obsolete-overlay');
    if (existOv) existOv.parentNode.removeChild(existOv);
    if (isObsFile) {
        preview.style.position = 'relative';
        var ovDiv = document.createElement('div');
        ovDiv.className = 'pav-obsolete-overlay';
        ovDiv.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:10;';
        var ovTxt = document.createElement('div');
        ovTxt.style.cssText = 'color:rgba(220,53,69,0.45);font-size:88px;font-weight:900;letter-spacing:12px;text-shadow:0 2px 16px rgba(220,53,69,.15);user-select:none;transform:rotate(-20deg);';
        ovTxt.textContent = '作廢';
        ovDiv.appendChild(ovTxt);
        preview.appendChild(ovDiv);
    }
}

// ── PAV 圖片縮放/平移 ───────────────────────────────────────────
var _pavZoom = { scale:1, tx:0, ty:0, on:false, sx:0, sy:0, stx:0, sty:0 };

function _pavApplyZoom() {
    var img = document.getElementById('pav-preview-img');
    if (!img) return;
    img.style.transform = 'translate('+_pavZoom.tx+'px,'+_pavZoom.ty+'px) scale('+_pavZoom.scale+')';
    var lbl = document.getElementById('pav-zoom-label');
    if (lbl) lbl.textContent = Math.round(_pavZoom.scale * 100) + '%';
    img.style.cursor = _pavZoom.scale > 1.05 ? (_pavZoom.on ? 'grabbing' : 'grab') : 'default';
}

function _pavImgWheel(e) {
    e.preventDefault();
    var factor = e.deltaY < 0 ? 1.2 : (1 / 1.2);
    _pavZoom.scale = Math.min(20, Math.max(0.05, _pavZoom.scale * factor));
    if (_pavZoom.scale < 1.05) { _pavZoom.tx = 0; _pavZoom.ty = 0; }
    _pavApplyZoom();
}
function _pavImgDown(e) {
    if (e.button !== 0) return;
    _pavZoom.on = true;
    _pavZoom.sx = e.clientX; _pavZoom.sy = e.clientY;
    _pavZoom.stx = _pavZoom.tx; _pavZoom.sty = _pavZoom.ty;
    e.preventDefault();
    _pavApplyZoom();
}
function _pavImgMove(e) {
    if (!_pavZoom.on) return;
    _pavZoom.tx = _pavZoom.stx + (e.clientX - _pavZoom.sx);
    _pavZoom.ty = _pavZoom.sty + (e.clientY - _pavZoom.sy);
    _pavApplyZoom();
}
function _pavImgUp() {
    if (!_pavZoom.on) return;
    _pavZoom.on = false;
    _pavApplyZoom();
}
function _pavInitImgZoom() {
    var img = document.getElementById('pav-preview-img');
    if (!img) return;
    img.style.transformOrigin = 'center center';
    img.addEventListener('wheel', _pavImgWheel, { passive:false });
    img.addEventListener('mousedown', _pavImgDown);
    document.addEventListener('mousemove', _pavImgMove);
    document.addEventListener('mouseup',   _pavImgUp);
    _pavApplyZoom();
}
function _pavCleanupImgZoom() {
    var img = document.getElementById('pav-preview-img');
    if (img) {
        img.removeEventListener('wheel', _pavImgWheel);
        img.removeEventListener('mousedown', _pavImgDown);
    }
    document.removeEventListener('mousemove', _pavImgMove);
    document.removeEventListener('mouseup',   _pavImgUp);
}
function pavZoomIn()  { _pavZoom.scale = Math.min(20, _pavZoom.scale * 1.3); _pavApplyZoom(); }
function pavZoomOut() { _pavZoom.scale = Math.max(0.05, _pavZoom.scale / 1.3); if (_pavZoom.scale < 1.05) { _pavZoom.tx=0; _pavZoom.ty=0; } _pavApplyZoom(); }
function pavZoomFit() { _pavZoom.scale = 1; _pavZoom.tx = 0; _pavZoom.ty = 0; _pavApplyZoom(); }

function pavPrint() {
    var frame = document.getElementById('pav-preview-frame');
    var img   = document.getElementById('pav-preview-img');
    if (frame) {
        // PDF 列印：嘗試在新視窗加浮水印（PDF 本身限制，僅顯示提示）
        if (_pavIsObsolete(_pav.currentFile)) {
            if (!confirm('此為「作廢」附件，確定要列印？')) return;
        }
        frame.contentWindow.print();
        return;
    }
    if (img && _pav.currentFile) {
        var isObs = _pavIsObsolete(_pav.currentFile);
        if (isObs) {
            // 開新視窗，在圖片上疊加作廢浮水印再列印
            var fname = escHtml(_pav.currentFile.original_name || _pav.currentFile.filename || '');
            var _pc = '@page{margin:0;}html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;}body{display:flex;align-items:center;justify-content:center;}img{display:block;max-width:100%;max-height:100%;object-fit:contain;}';
            var w = window.open('', '_blank');
            if (w) {
                w.document.write(
                    '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>列印 - ' + fname + '</title>'
                    + '<style>' + _pc
                    + '.wm{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-20deg);'
                    +     'color:rgba(220,53,69,0.38);font-size:130px;font-weight:900;letter-spacing:16px;'
                    +     'pointer-events:none;white-space:nowrap;z-index:999;user-select:none;font-family:Arial,sans-serif;}'
                    + '</style></head><body>'
                    + '<img src="' + escHtml(_pav.currentFile.url) + '" onload="window.print();">'
                    + '<div class="wm">作廢</div>'
                    + '</body></html>'
                );
                w.document.close();
            }
            return;
        }
        var _pc2 = '@page{margin:0;}html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;}body{display:flex;align-items:center;justify-content:center;}img{display:block;max-width:100%;max-height:100%;object-fit:contain;}';
        var w = window.open('', '_blank');
        if (w) {
            w.document.write(
                '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>列印</title>'
                + '<style>' + _pc2 + '</style></head><body>'
                + '<img src="' + escHtml(_pav.currentFile.url) + '" onload="window.print();">'
                + '</body></html>'
            );
            w.document.close();
        }
        return;
    }
    if (_pav.currentFile) window.open(_pav.currentFile.url, '_blank');
}

function pavDeleteCurrent() {
    var f = _pav.currentFile;
    if (!f || f.source === 'quote') { showToast('報價單附件請至報價單頁面管理','warning'); return; }
    var ans = prompt('確認刪除「'+(f.original_name||f.filename||'')+'」\n\n刪除後可在「刪除紀錄」中30天內還原。\n請輸入大寫 Y 確認：');
    if (ans !== 'Y') { if (ans !== null) showToast('未輸入 Y，已取消','warning'); return; }
    $.post(PART_ATTACH_API_URL, { action:'delete', id:f.id, d_id:_pav.dId }, function(r) {
        if (r.success) {
            showToast('已刪除');
            _refreshPartAttachCell(_pav.dId);
            _pavLoadFiles(function(files) {
                // 重建 tabs（刪除後 tab 可能消失）
                if (_pav.mode !== 'quote') _pavBuildCatTabs(files);
                if (_pav.mode==='quote') _pav.filteredFiles = files.filter(function(x){ return x.source==='quote'; });
                else _pav.filteredFiles = files.filter(function(x){ return x.source!=='quote'; });
                _pavRenderList();
            });
        } else showToast(r.message||'刪除失敗','error');
    });
}

function pavOpenDeleteLog() {
    var dId = _pav.dId;
    if (!dId) return;
    document.getElementById('padl-part-no').textContent = _pav.partNo || '';
    document.getElementById('padl-list').innerHTML = '<div style="text-align:center;padding:20px;color:#aaa;"><i class="fa fa-spinner fa-spin"></i></div>';
    $('#partAttachDeleteLogModal').modal('show');
    $.post(PART_ATTACH_API_URL, { action:'list_deleted', d_id:dId }, function(r) {
        var el = document.getElementById('padl-list');
        if (!el) return;
        if (!r.success) { el.innerHTML = '<div style="color:red;padding:10px;">'+escHtml(r.message||'載入失敗')+'</div>'; return; }
        if (!r.data || !r.data.length) {
            el.innerHTML = '<div style="text-align:center;color:#aaa;padding:20px;font-size:12px;"><i class="fa fa-check-circle" style="color:#27ae60;"></i> 無刪除紀錄</div>';
            return;
        }
        var cats = _attachCatsCache || [];
        var html = '<table style="width:100%;font-size:11px;border-collapse:collapse;">';
        html += '<thead><tr style="background:#fdf2f2;border-bottom:2px solid #e74c3c;">';
        html += '<th style="padding:5px 8px;text-align:left;">檔案名稱</th>';
        html += '<th style="padding:5px 8px;text-align:left;">類別標籤</th>';
        html += '<th style="padding:5px 8px;text-align:left;white-space:nowrap;">刪除時間</th>';
        html += '<th style="padding:5px 8px;text-align:left;white-space:nowrap;">刪除人員</th>';
        html += '<th style="padding:5px 8px;text-align:center;white-space:nowrap;">操作</th>';
        html += '</tr></thead><tbody>';
        r.data.forEach(function(rec) {
            html += '<tr style="border-bottom:1px solid #f0e0e0;">';
            html += '<td style="padding:5px 8px;color:#333;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+escHtml(rec.original_name||rec.filename||'')+'">'+escHtml(rec.original_name||rec.filename||'')+'</td>';
            html += '<td style="padding:5px 8px;color:#1a5276;">'+escHtml(rec.category_names||'—')+'</td>';
            html += '<td style="padding:5px 8px;color:#888;white-space:nowrap;">'+escHtml((rec.deleted_at||'').substring(0,16))+'</td>';
            html += '<td style="padding:5px 8px;color:#555;">'+escHtml(rec.deleted_by||'—')+'</td>';
            html += '<td style="padding:5px 8px;text-align:center;">';
            html += '<button type="button" class="btn btn-xs btn-success" onclick="pavRestoreAttach('+rec.id+')" style="white-space:nowrap;"><i class="fa fa-undo"></i> 還原</button>';
            html += '</td></tr>';
        });
        html += '</tbody></table>';
        el.innerHTML = html;
    }).fail(function(){ document.getElementById('padl-list').innerHTML = '<div style="color:red;padding:10px;">網路錯誤</div>'; });
}

function pavRestoreAttach(id) {
    $.post(PART_ATTACH_API_URL, { action:'restore', id:id, d_id:_pav.dId }, function(r) {
        if (!r.success) { showToast(r.message||'還原失敗','error'); return; }
        showToast('已還原');
        _refreshPartAttachCell(_pav.dId);
        pavOpenDeleteLog(); // 重新整理刪除紀錄列表
        _pavLoadFiles(function(files) {
            if (_pav.mode !== 'quote') _pavBuildCatTabs(files);
            _pav.filteredFiles = files.filter(function(x){ return x.source !== 'quote'; });
            _pavRenderList();
        });
    });
}

function openPartAttachUploadFromView(input) {
    if (!input || !input.files || !input.files.length) return;
    var files = Array.from(input.files);
    _openPartAttachUploadModal(_pav.dId, _pav.partNo, files);
    input.value = '';
}

function openPartAttachListModal(dId, partNo) { openAttachAllView(dId, partNo); }  // 向後相容

function deletePartAttach(id) {
    if (!confirm('確定刪除此附件？')) return;
    $.post(PART_ATTACH_API_URL, { action:'delete', id:id, d_id:_pav.dId || _palCurrentDId }, function(r) {
        if (r.success) { showToast('已刪除'); _refreshPartAttachCell(_pav.dId || _palCurrentDId); }
        else showToast(r.message||'刪除失敗','error');
    });
}

function _fileIcon(ext) {
    var m = { doc:'fa-file-word-o',docx:'fa-file-word-o',xls:'fa-file-excel-o',xlsx:'fa-file-excel-o',
              ppt:'fa-file-powerpoint-o',pptx:'fa-file-powerpoint-o',txt:'fa-file-text-o',csv:'fa-file-text-o',
              zip:'fa-file-zip-o',rar:'fa-file-zip-o','7z':'fa-file-zip-o',
              mp4:'fa-file-video-o',avi:'fa-file-video-o',dwg:'fa-file-code-o',dxf:'fa-file-code-o',step:'fa-file-code-o' };
    return m[ext] || 'fa-file-o';
}

function openPartAttachUpload(dId, partNo) {
    _openPartAttachUploadModal(dId, partNo, null);
}

// 建立單一檔案列的類別 chips HTML
function _pauBuildFileCatChips(fileIdx, cats, checkedIds) {
    var html = '<div style="display:flex;flex-wrap:wrap;gap:3px;">';
    cats.forEach(function(c) {
        var ck = (checkedIds||[]).indexOf(String(c.id)) >= 0 ? 'checked' : '';
        html += '<label style="display:inline-flex;align-items:center;gap:3px;background:#f0f8ff;color:#1a5276;border:1px solid #aed6f1;border-radius:8px;padding:1px 8px;cursor:pointer;font-weight:normal;font-size:11px;margin-bottom:2px;">'
              + '<input type="checkbox" value="'+c.id+'" class="pau-row-cat" data-fidx="'+fileIdx+'" '+ck+' onchange="refreshPauIssueRow()" style="cursor:pointer;">'
              + escHtml(c.category_name)+'</label>';
    });
    html += '</div>';
    return html;
}

function _pauRenderFileRows(fileArr, cats) {
    var rows = document.getElementById('pau-file-rows');
    var single = document.getElementById('pau-single-mode');
    if (!rows) return;
    if (fileArr.length <= 1) {
        rows.style.display = 'none';
        if (single) single.style.display = '';
        return;
    }
    if (single) single.style.display = 'none';
    var html = '<table style="width:100%;border-collapse:collapse;font-size:12px;">';
    html += '<thead><tr style="background:#f0f4fb;border-bottom:2px solid #d6eaf8;">';
    html += '<th style="padding:5px 8px;text-align:left;width:22%;">檔案名稱</th>';
    html += '<th style="padding:5px 8px;text-align:left;">類別標籤</th>';
    html += '<th style="padding:5px 8px;text-align:left;width:90px;">版次</th>';
    html += '<th style="padding:5px 8px;text-align:left;width:18%;">備註</th>';
    html += '</tr></thead><tbody>';
    fileArr.forEach(function(f, idx) {
        var ext = (f.name||'').split('.').pop().toLowerCase();
        html += '<tr style="border-bottom:1px solid #e4e8ed;'+(idx%2===1?'background:#fafbfc;':'')+'vertical-align:top;">';
        html += '<td style="padding:5px 8px;color:#1a5276;word-break:break-all;font-weight:600;" title="'+escHtml(f.name)+'">'
              + '<i class="fa '+_fileIcon(ext)+'" style="color:#888;margin-right:4px;"></i>'+escHtml(f.name)+'</td>';
        html += '<td style="padding:5px 8px;">'+_pauBuildFileCatChips(idx, cats, [])+'</td>';
        html += '<td style="padding:5px 8px;"><input type="text" class="form-control input-sm pau-row-rev" data-fidx="'+idx+'" maxlength="50" placeholder="版次" style="font-size:11px;"></td>';
        html += '<td style="padding:5px 8px;"><input type="text" class="form-control input-sm pau-row-note" data-fidx="'+idx+'" maxlength="200" placeholder="備註（選填）" style="font-size:11px;"></td>';
        html += '</tr>';
    });
    html += '</tbody></table>';
    // 套用到全部按鈕（在第一列上方）
    var wrapHtml = '<div style="padding:6px 8px;background:#eef4fb;border-bottom:1px solid #d6eaf8;font-size:11px;color:#555;display:flex;align-items:center;gap:8px;">'
        + '<span><i class="fa fa-info-circle"></i> 每個檔案可個別設定類別標籤與備註</span>'
        + '<button type="button" class="btn btn-xs btn-default" onclick="pauApplyFirstToAll()" style="margin-left:auto;"><i class="fa fa-copy"></i> 以第一個為準套用全部</button>'
        + '</div>' + html;
    rows.innerHTML = wrapHtml;
    rows.style.display = '';
}

// 多檔上傳表格：↑↓ 在同一欄的上下列之間移動（版次／備註），比照多列輸入表格的操作習慣
$(document).on('keydown', '#pau-file-rows input.pau-row-rev, #pau-file-rows input.pau-row-note', function(e) {
    var key = e.key || '';
    if (key !== 'ArrowUp' && key !== 'ArrowDown') return;
    var cls = this.classList.contains('pau-row-rev') ? 'pau-row-rev' : 'pau-row-note';
    var idx = parseInt(this.getAttribute('data-fidx') || '0', 10);
    var tgt = document.querySelector('#pau-file-rows input.' + cls + '[data-fidx="' + (idx + (key === 'ArrowDown' ? 1 : -1)) + '"]');
    if (!tgt) return;
    e.preventDefault();
    tgt.focus();
    tgt.select();
});

function pauApplyFirstToAll() {
    var allRows = document.querySelectorAll('tbody tr', document.getElementById('pau-file-rows'));
    // 取第一列的勾選狀態
    var firstCats = [];
    document.querySelectorAll('.pau-row-cat[data-fidx="0"]:checked').forEach(function(cb){ firstCats.push(cb.value); });
    var firstNote = '';
    var noteEl = document.querySelector('.pau-row-note[data-fidx="0"]');
    if (noteEl) firstNote = noteEl.value;
    var firstRev = '';
    var revEl = document.querySelector('.pau-row-rev[data-fidx="0"]');
    if (revEl) firstRev = revEl.value;
    var total = (window._pauFiles||[]).length;
    for (var i = 1; i < total; i++) {
        // 同步勾選
        document.querySelectorAll('.pau-row-cat[data-fidx="'+i+'"]').forEach(function(cb){
            cb.checked = firstCats.indexOf(cb.value) >= 0;
        });
        var n = document.querySelector('.pau-row-note[data-fidx="'+i+'"]');
        if (n) n.value = firstNote;
        var rv = document.querySelector('.pau-row-rev[data-fidx="'+i+'"]');
        if (rv) rv.value = firstRev;
    }
    showToast('已套用到全部 '+total+' 個檔案');
}

function _openPartAttachUploadModal(dId, partNo, preselectedFiles) {
    document.getElementById('pau-d-id').value = dId;
    document.getElementById('pau-note').value = '';
    var _pauRev = document.getElementById('pau-revision'); if (_pauRev) _pauRev.value = '';
    var _pauIss = document.getElementById('pau-issue-date'); if (_pauIss) _pauIss.value = '';
    var _pauIw  = document.getElementById('pau-issue-wrap'); if (_pauIw) _pauIw.style.display = 'none';
    document.getElementById('pau-vars-section').style.display = 'none';
    document.getElementById('pau-vars-inputs').innerHTML = '';
    document.getElementById('pau-file-rows').style.display = 'none';
    document.getElementById('pau-file-rows').innerHTML = '';
    var single = document.getElementById('pau-single-mode');
    if (single) single.style.display = '';
    var fileArr = Array.isArray(preselectedFiles) ? preselectedFiles : (preselectedFiles ? [preselectedFiles] : []);
    window._pauFiles = fileArr;
    var cntEl = document.getElementById('pau-file-count');
    if (cntEl) cntEl.textContent = !fileArr.length ? '未選擇' : fileArr.length + ' 個檔案';
    loadActiveCatsForUpload(function(cats) {
        if (fileArr.length > 1) {
            _pauRenderFileRows(fileArr, cats);
        } else {
            // 單檔：原有的 chips
            var chips = document.getElementById('pau-cat-chips');
            if (chips) {
                chips.innerHTML = '';
                cats.forEach(function(c) {
                    var lbl = document.createElement('label');
                    lbl.style.cssText = 'display:inline-flex;align-items:center;gap:4px;background:#f0f8ff;color:#1a5276;border:1px solid #aed6f1;border-radius:10px;padding:2px 10px;cursor:pointer;font-weight:normal;font-size:12px;margin-bottom:3px;';
                    lbl.innerHTML = '<input type="checkbox" value="'+c.id+'" class="pau-cat-chk" style="cursor:pointer;" onchange="onPauCatChange()"> '+escHtml(c.category_name);
                    chips.appendChild(lbl);
                });
            }
        }
    });
    $('#partAttachViewModal').modal('hide');
    $('#partAttachUploadModal').modal('show');
}

function onPauFileChange(input) {
    var fileArr = Array.from(input.files || []);
    window._pauFiles = fileArr;
    var cntEl = document.getElementById('pau-file-count');
    if (cntEl) cntEl.textContent = !fileArr.length ? '未選擇' : fileArr.length + ' 個檔案';
    // 重建 rows / single mode
    loadActiveCatsForUpload(function(cats) {
        document.getElementById('pau-note').value = '';
        document.getElementById('pau-vars-section').style.display = 'none';
        var single = document.getElementById('pau-single-mode');
        if (fileArr.length > 1) {
            _pauRenderFileRows(fileArr, cats);
        } else {
            document.getElementById('pau-file-rows').style.display = 'none';
            if (single) single.style.display = '';
            // 清除舊勾選
            document.querySelectorAll('.pau-cat-chk').forEach(function(cb){ cb.checked = false; });
        }
    });
}

/* ── 發行章日期：只有勾到「自家出的圖」標籤才要求填 ──────────────────────
   判準與適用標籤見 ai-rules/15-圖面變更判定依據.md。哪些標籤算自家出的圖，
   由 quotation_file_categories.is_own_drawing 決定（附件類別設定可調），不寫死 id。 */
function _pauOwnDrawingCatIds() {
    return (_attachCatsCache||[]).filter(function(c){ return c.is_own_drawing==1||c.is_own_drawing==='1'; })
                                 .map(function(c){ return String(c.id); });
}
function _pauSelectedCatIds() {
    var ids = [];
    // 單檔用 chips，多檔用每列 checkbox；兩種模式共用同一個發行章日期
    document.querySelectorAll('.pau-cat-chk:checked').forEach(function(cb){ ids.push(cb.value); });
    document.querySelectorAll('.pau-row-cat:checked').forEach(function(cb){ ids.push(cb.value); });
    return ids;
}
function refreshPauIssueRow() {
    var wrap = document.getElementById('pau-issue-wrap');
    if (!wrap) return;
    var own = _pauOwnDrawingCatIds();
    var need = _pauSelectedCatIds().some(function(id){ return own.indexOf(String(id))>=0; });
    wrap.style.display = need ? '' : 'none';
    if (!need) return;
    var inp = document.getElementById('pau-issue-date');
    if (inp && !inp.value) inp.value = _todayStr();          // 預設帶今天（上傳日），可改
    validatePauIssue();
}
function _todayStr() {
    var d = new Date();
    return d.getFullYear() + '-' + ('0'+(d.getMonth()+1)).slice(-2) + '-' + ('0'+d.getDate()).slice(-2);
}
/* 錯誤即時偵測並顯示原因（CLAUDE.md 表單三總則③） */
function validatePauIssue() {
    var inp = document.getElementById('pau-issue-date'), hint = document.getElementById('pau-issue-hint');
    if (!inp || !hint) return true;
    if (document.getElementById('pau-issue-wrap').style.display === 'none') return true;
    if (!inp.value) {
        inp.style.borderColor = '#e74c3c';
        hint.style.color = '#e74c3c';
        hint.textContent = '請填發行章日期——這是判斷「這張圖是不是改過」的唯一依據，不填就無法自動偵測圖面變更';
        return false;
    }
    if (inp.value > _todayStr()) {
        inp.style.borderColor = '#e74c3c';
        hint.style.color = '#e74c3c';
        hint.textContent = '發行章日期不可以是未來日期';
        return false;
    }
    inp.style.borderColor = '';
    hint.style.color = '#7f8c8d';
    hint.textContent = '上傳後會自動跟這個料號既有的自家圖面比對：比較新＝圖面變更（會請你填變更內容），第一次＝首次發行。';
    return true;
}

function onPauCatChange() {
    refreshPauIssueRow();
    var selectedIds = [];
    document.querySelectorAll('.pau-cat-chk:checked').forEach(function(cb){ selectedIds.push(cb.value); });
    var varSec = document.getElementById('pau-vars-section');
    var varInp = document.getElementById('pau-vars-inputs');
    if (!varSec || !varInp) return;
    var allVars = [];
    selectedIds.forEach(function(cid) {
        var cat = (_attachCatsCache||[]).find(function(c){ return String(c.id)===String(cid); });
        if (!cat) return;
        var vars = [];
        try { vars = JSON.parse(cat.tag_variables||'[]'); } catch(e) { vars = []; }
        vars.forEach(function(v) {
            if (v.key && !allVars.find(function(x){ return x.key===v.key; })) {
                allVars.push({ key:v.key, hint:v.hint||'', cat_id:cid });
            }
        });
    });
    if (!allVars.length) { varSec.style.display='none'; varInp.innerHTML=''; return; }
    varSec.style.display = '';
    var html = '';
    allVars.forEach(function(v) {
        html += '<div class="form-group" style="margin-bottom:6px;">';
        html += '<label style="font-size:11px;color:#2980b9;">{'+escHtml(v.key)+'}</label>';
        if (v.hint) html += ' <small style="color:#aaa;">'+escHtml(v.hint)+'</small>';
        html += '<input type="text" class="form-control input-sm pau-var-input" data-key="'+escHtml(v.key)+'" data-cat="'+escHtml(v.cat_id)+'" maxlength="200">';
        html += '</div>';
    });
    varInp.innerHTML = html;
}

function submitPartAttachUpload() {
    var dId   = parseInt(document.getElementById('pau-d-id').value)||0;
    var files = (window._pauFiles && window._pauFiles.length) ? window._pauFiles
              : (document.getElementById('pau-file-input').files ? Array.from(document.getElementById('pau-file-input').files) : []);
    if (!dId)          { showToast('缺少料號 ID','error'); return; }
    if (!files.length) { showToast('請選擇檔案','error'); return; }
    if (!validatePauIssue()) { document.getElementById('pau-issue-date').focus(); showToast('請先填寫發行章日期','error'); return; }
    var issueDate = (document.getElementById('pau-issue-wrap').style.display !== 'none')
                  ? (document.getElementById('pau-issue-date').value||'') : '';
    var isMulti = files.length > 1;
    // 收集每個檔案的設定
    var fileSettings = files.map(function(f, idx) {
        if (isMulti) {
            var catIds = [];
            document.querySelectorAll('.pau-row-cat[data-fidx="'+idx+'"]:checked').forEach(function(cb){ catIds.push(cb.value); });
            var noteEl = document.querySelector('.pau-row-note[data-fidx="'+idx+'"]');
            var revEl  = document.querySelector('.pau-row-rev[data-fidx="'+idx+'"]');
            return { catStr: catIds.join(','), note: noteEl ? noteEl.value.trim() : '', revision: revEl ? revEl.value.trim() : '', tagVarStr: '' };
        } else {
            var selectedCatIds = [];
            document.querySelectorAll('.pau-cat-chk:checked').forEach(function(cb){ selectedCatIds.push(cb.value); });
            var tagVarValues = {};
            document.querySelectorAll('.pau-var-input').forEach(function(inp) {
                var key = inp.dataset.key, cat = inp.dataset.cat, val = inp.value.trim();
                if (key && val) { if (!tagVarValues[cat]) tagVarValues[cat]={}; tagVarValues[cat][key]=val; }
            });
            return { catStr: selectedCatIds.join(','), note: (document.getElementById('pau-note').value||'').trim(),
                     revision: (document.getElementById('pau-revision').value||'').trim(),
                     tagVarStr: Object.keys(tagVarValues).length ? JSON.stringify(tagVarValues) : '' };
        }
    });
    var btn = document.getElementById('pau-submit-btn');
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> 上傳中…'; }
    var total = files.length, done = 0, failed = 0, lastErr = '';
    // 一批只會有一次「圖面變更」——同一次出圖的 BOSS圖/++圖 是同一件事，記第一個判定為變更的附件即可
    var changeHit = null;
    function uploadNext(idx) {
        if (idx >= files.length) {
            if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-upload"></i> 上傳'; }
            var msg = total === 1 ? '附件已上傳' : (done + '/' + total + ' 個附件已上傳' + (failed ? '，' + failed + ' 個失敗' : ''));
            showToast(msg + (failed && lastErr ? '（' + lastErr + '）' : ''), failed ? 'warning' : 'success');
            if (done > 0) {
                $('#partAttachUploadModal').modal('hide');
                _refreshPartAttachCell(dId);
                if (changeHit) { openDwgChangeModal(changeHit); return; }   // 先讓設計填變更，填完再回附件檢視
                setTimeout(function(){ openAttachAllView(dId, _pav.partNo||''); }, 200);
            }
            return;
        }
        var s = fileSettings[idx];
        var fd = new FormData();
        fd.append('action','upload'); fd.append('d_id',dId);
        fd.append('file', files[idx]);
        fd.append('category_ids', s.catStr);
        fd.append('tag_var_values', s.tagVarStr||'');
        fd.append('note', s.note||'');
        fd.append('revision', s.revision||'');
        fd.append('issue_stamp_date', issueDate);
        $.ajax({ url:PART_ATTACH_API_URL, type:'POST', data:fd, processData:false, contentType:false, success:function(r) {
            if (r.success) {
                done++;
                var v = r.dwg_verdict || {};
                if (!changeHit && v.kind === 'change') {
                    changeHit = { attachId:r.id, dId:dId, fileName:r.original_name||'', verdict:v };
                } else if (total === 1 && v.kind === 'first') {
                    showToast('已記錄為首次發行（此料號第一張帶發行章日期的自家圖面），不需登錄圖面變更','success');
                } else if (total === 1 && (v.kind === 'same' || v.kind === 'older')) {
                    showToast(v.message || '', 'success');
                }
            } else { failed++; lastErr = r.message || ''; }
            uploadNext(idx + 1);
        }, error:function(){ failed++; uploadNext(idx + 1); }});
    }
    uploadNext(0);
}

/* ── 圖面變更登錄跳窗（附件上傳判定為「變更」時自動跳出）────────────────── */
var _dwgCtx = null, _dwgPeople = null;
function openDwgChangeModal(ctx) {
    _dwgCtx = ctx;
    document.getElementById('dwg-attach-id').value = ctx.attachId;
    document.getElementById('dwg-why').innerHTML =
        '<b>' + escHtml(ctx.fileName) + '</b> 的發行章日期是 <b>' + escHtml(ctx.verdict.issue_date || '') + '</b>，'
        + '比這個料號現有最新的自家圖面（' + escHtml(ctx.verdict.prev_name||'') + '，'
        + escHtml(ctx.verdict.prev_date||'') + '）新，所以判定為<b>圖面變更</b>。<br>'
        + '只有你知道這次改了什麼、哪些製程受影響，請填一下；送出後會自動把檢驗標準複製成新版次並通知簽收。';
    document.getElementById('dwg-summary').value = '';
    document.getElementById('dwg-detail').value  = '';
    document.getElementById('dwg-oldrev').value  = '';
    document.getElementById('dwg-newrev').value  = '';
    document.getElementById('dwg-cdoc').value    = '';
    document.getElementById('dwg-source').value  = '客戶';
    document.getElementById('dwg-people-q').value = '';
    document.getElementById('dwg-summary-err').style.display = 'none';
    document.getElementById('dwg-summary').style.borderColor = '';
    $.post(PART_ATTACH_API_URL, { action:'dwg_lookups' }, function(r) {
        if (!r || !r.success) return;
        document.getElementById('dwg-fromproc').innerHTML = '<option value="">（全部製程都提醒）</option>'
            + (r.processes||[]).map(function(p){ return '<option value="'+p.ProcessNo+'">'+escHtml(p.ProcessName)+'</option>'; }).join('');
        _dwgPeople = r.people || [];
        renderDwgPeople();
    }, 'json');
    $('#dwgChangeModal').modal('show');
}
function renderDwgPeople() {
    if (!_dwgPeople) return;
    var q = (document.getElementById('dwg-people-q').value||'').trim();
    var list = q ? _dwgPeople.filter(function(p){ return p.label.indexOf(q) >= 0; }) : _dwgPeople;
    var box = document.getElementById('dwg-people');
    var picked = {};
    document.querySelectorAll('.dwg-ack:checked').forEach(function(cb){ picked[cb.value] = 1; });
    box.innerHTML = list.length ? list.map(function(p) {
        return '<label style="display:inline-block;width:48%;font-weight:normal;font-size:12px;margin:2px 0;cursor:pointer;">'
             + '<input type="checkbox" class="dwg-ack" value="'+p.id+'"'+(picked[p.id]?' checked':'')+'> ' + escHtml(p.label) + '</label>';
    }).join('') : '<span style="color:#aaa;font-size:12px;">查無符合人員</span>';
}
function submitDwgChange() {
    var summary = (document.getElementById('dwg-summary').value||'').trim();
    if (!summary) {
        document.getElementById('dwg-summary-err').style.display = '';
        document.getElementById('dwg-summary').style.borderColor = '#e74c3c';
        document.getElementById('dwg-summary').focus();
        return;
    }
    var acks = [];
    document.querySelectorAll('.dwg-ack:checked').forEach(function(cb){ acks.push(cb.value); });
    var btn = document.getElementById('dwg-save-btn');
    btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> 建立中…';
    $.post(PART_ATTACH_API_URL, {
        action:'create_dwg_change',
        attachment_id: document.getElementById('dwg-attach-id').value,
        summary: summary,
        detail:  (document.getElementById('dwg-detail').value||'').trim(),
        old_revision: (document.getElementById('dwg-oldrev').value||'').trim(),
        new_revision: (document.getElementById('dwg-newrev').value||'').trim(),
        source: document.getElementById('dwg-source').value,
        customer_doc_no: (document.getElementById('dwg-cdoc').value||'').trim(),
        from_process_no: document.getElementById('dwg-fromproc').value,
        ack_users: acks
    }, function(r) {
        btn.disabled = false; btn.innerHTML = '<i class="fa fa-check"></i> 建立變更紀錄並通知簽收';
        if (!r || !r.success) { showToast((r && r.message) || '建立失敗','error'); return; }
        showToast('已建立圖面變更 ' + r.change_no + (r.new_version_id ? '，檢驗標準已複製成新版次' : ''), 'success');
        $('#dwgChangeModal').modal('hide');
        if (_dwgCtx) setTimeout(function(){ openAttachAllView(_dwgCtx.dId, _pav.partNo||''); }, 200);
    }, 'json');
}
function dwgSkipChange() {
    // 附件已經存好了，跳過只是沒建變更紀錄；到「圖面變更紀錄」頁仍可手動補登
    if (!confirm('附件已上傳完成。跳過的話這次改圖不會有變更紀錄，檢驗人員也不會收到提醒。\n\n之後可到「圖面變更紀錄」頁手動補登。確定跳過？')) return;
    $('#dwgChangeModal').modal('hide');
    if (_dwgCtx) setTimeout(function(){ openAttachAllView(_dwgCtx.dId, _pav.partNo||''); }, 200);
}

function pavEditMeta() {
    var f = _pav.currentFile;
    if (!f || f.source === 'quote') return;
    document.getElementById('pae-id').value = f.id;
    document.getElementById('pae-note').value = (f.note === null || f.note === undefined) ? '' : String(f.note);
    // 版次 0 也要帶回編輯框（不可用 || ''）
    document.getElementById('pae-revision').value = (f.revision === null || f.revision === undefined) ? '' : String(f.revision);
    document.getElementById('pae-issue-date').value = (f.issue_stamp_date || '').substring(0,10);
    loadActiveCatsForUpload(function(cats) {
        var chips = document.getElementById('pae-cat-chips');
        if (!chips) return;
        chips.innerHTML = '';
        var checked = (f.category_ids||'').split(',').map(function(x){ return x.trim(); });
        cats.forEach(function(c) {
            var lbl = document.createElement('label');
            var isObsCat = c.category_name === '作廢';
            lbl.style.cssText = 'display:inline-flex;align-items:center;gap:4px;border-radius:10px;padding:2px 10px;cursor:pointer;font-weight:normal;font-size:12px;margin-bottom:3px;'
                + (isObsCat
                    ? 'background:#fff0f0;color:#c0392b;border:1.5px solid #e74c3c;font-weight:600;'
                    : 'background:#f0f8ff;color:#1a5276;border:1px solid #aed6f1;');
            var ck = checked.indexOf(String(c.id)) >= 0 ? 'checked' : '';
            var label = isObsCat ? '⊘ 作廢' : escHtml(c.category_name);
            lbl.innerHTML = '<input type="checkbox" value="'+c.id+'" class="pae-cat-chk" '+ck+' onchange="refreshPaeIssueRow()" style="cursor:pointer;accent-color:#e74c3c;"> '+label;
            chips.appendChild(lbl);
        });
        refreshPaeIssueRow();
    });
    $('#partAttachEditModal').modal('show');
}

/* 編輯附件時的發行章日期：勾到「自家出的圖」才要求填（與上傳同一套判準） */
function refreshPaeIssueRow() {
    var wrap = document.getElementById('pae-issue-wrap');
    if (!wrap) return;
    var own = _pauOwnDrawingCatIds(), ids = [];
    document.querySelectorAll('.pae-cat-chk:checked').forEach(function(cb){ ids.push(String(cb.value)); });
    var need = ids.some(function(id){ return own.indexOf(id)>=0; });
    wrap.style.display = need ? '' : 'none';
    if (!need) return;
    var inp = document.getElementById('pae-issue-date');
    if (inp && !inp.value) inp.value = _todayStr();
    validatePaeIssue();
}
function validatePaeIssue() {
    var inp = document.getElementById('pae-issue-date'), hint = document.getElementById('pae-issue-hint');
    if (!inp || !hint || document.getElementById('pae-issue-wrap').style.display === 'none') return true;
    if (!inp.value) {
        inp.style.borderColor = '#e74c3c'; hint.style.color = '#e74c3c';
        hint.textContent = '請填發行章日期——這是判斷「這張圖是不是改過」的唯一依據';
        return false;
    }
    if (inp.value > _todayStr()) {
        inp.style.borderColor = '#e74c3c'; hint.style.color = '#e74c3c';
        hint.textContent = '發行章日期不可以是未來日期';
        return false;
    }
    inp.style.borderColor = ''; hint.style.color = '#7f8c8d'; hint.textContent = '';
    return true;
}

function submitAttachEdit() {
    var id   = parseInt(document.getElementById('pae-id').value)||0;
    if (!id) return;
    var catIds = [];
    document.querySelectorAll('.pae-cat-chk:checked').forEach(function(cb){ catIds.push(cb.value); });
    var note = (document.getElementById('pae-note').value||'').trim();
    var revision = (document.getElementById('pae-revision').value||'').trim();
    if (!validatePaeIssue()) { document.getElementById('pae-issue-date').focus(); return; }
    var issueDate = (document.getElementById('pae-issue-wrap').style.display !== 'none')
                  ? (document.getElementById('pae-issue-date').value||'') : '';
    $.post(PART_ATTACH_API_URL, { action:'update_meta', id:id, category_ids:catIds.join(','), note:note, revision:revision, issue_stamp_date:issueDate }, function(r) {
        if (!r.success) { showToast(r.message||'儲存失敗','error'); return; }
        // 更新本地資料
        var f = _pav.currentFile;
        if (f) { f.category_ids = catIds.join(','); f.note = note; f.revision = revision; f.issue_stamp_date = issueDate; }
        showToast('已儲存');
        $('#partAttachEditModal').modal('hide');
        _refreshPartAttachCell(_pav.dId);
        _pavLoadFiles(function(files) {
            _pav.allFiles = files;
            _pav.filteredFiles = _pav.mode==='tag'
                ? files.filter(function(x){ return x.category_ids && x.category_ids.split(',').map(function(y){ return y.trim(); }).indexOf(String(_pav.catId))>=0; })
                : files.filter(function(x){ return x.source!=='quote'; });
            _pavRenderList();
        });
    });
}

// 刷新單一料號列表的附件欄
var _partAttachData = {};  // d_id → {latest:[], total:N, url_base:str}

function _refreshPartAttachCell(dId) {
    $.post(PART_ATTACH_API_URL, { action:'list_latest_for_parts', d_ids:JSON.stringify([dId]) }, function(r) {
        if (r.success && r.data) {
            _partAttachData[dId] = r.data[dId] || null;
            _renderAttachCellForDId(dId);
        }
    });
}

function _renderAttachCellForDId(dId) {
    var cell = document.querySelector('.part-attach-cell[data-did="'+dId+'"]');
    if (!cell) return;
    var data    = _partAttachData[dId];
    var partNo  = cell.dataset.partNo || '';
    cell.innerHTML = _buildAttachCellHtml(dId, partNo, data);
}

function _buildAttachCellHtml(dId, partNo, data) {
    var pno = partNo || '';
    var hasQuoteFlag = data && data.has_quote;

    // 無附件且無報價 → 僅顯示小圖示（若有權限可點擊上傳）
    if (!data || (data.total === 0 && !hasQuoteFlag)) {
        if (!CAN_PART_ATTACH || !MD_CAN_OTHER) return '<span style="color:#ddd;font-size:10px;">—</span>';
        return '<button class="btn btn-xs" onclick="openAttachAllView('+dId+',\''+escAttr(pno)+'\')" style="font-size:10px;color:#bbb;background:none;border:none;padding:1px 4px;" title="無附件，點擊新增"><i class="fa fa-paperclip"></i></button>';
    }

    var cats = _attachCatsCache || [];
    var showCats = cats.filter(function(c){ return c.show_in_list=='1'||c.show_in_list===1; });
    var files    = data.latest || [];
    var html     = '<div style="display:flex;flex-wrap:wrap;gap:3px;align-items:center;">';

    // ── 有勾選「顯示在列表」的標籤 → 顯示標籤按鈕（有對應附件才顯示）
    var anyShowTag = false;
    showCats.forEach(function(cat) {
        var hasFile = files.some(function(f){
            return f.category_ids && f.category_ids.split(',').map(function(x){ return x.trim(); }).indexOf(String(cat.id)) >= 0;
        });
        if (!hasFile) return;
        if (!MD_CAN_OTHER) return;   // 無其他附件檢視權限：不顯示標籤分頁入口
        anyShowTag = true;
        html += '<button class="btn btn-xs" onclick="openAttachTagView('+dId+',\''+escAttr(pno)+'\','+cat.id+',\''+escAttr(cat.category_name)+'\')" '
              + 'style="font-size:10px;color:#1a5276;background:#ddeeff;border:1px solid #aed6f1;border-radius:10px;padding:1px 7px;" '
              + 'title="'+escHtml(cat.category_name)+'"><i class="fa fa-tag" style="margin-right:2px;"></i>'+escHtml(cat.category_name)+'</button>';
    });

    // ── 有報價單（含無附件的情況）→ 顯示「報價」按鈕
    var hasQuote = hasQuoteFlag || files.some(function(f){ return f.source === 'quote'; });
    if (hasQuote && MD_CAN_QUOTE) {   // 無報價查閱權限：隱藏「報價」入口
        html += '<button class="btn btn-xs" onclick="openAttachQuoteView('+dId+',\''+escAttr(pno)+'\')" '
              + 'style="font-size:10px;color:#6e2fa3;background:#f3e8ff;border:1px solid #d4a8f0;border-radius:10px;padding:1px 7px;" '
              + 'title="報價單"><i class="fa fa-file-text-o" style="margin-right:2px;"></i>報價</button>';
    }

    // ── + 號按鈕 → 所有附件（非顯示標籤的、或無標籤）
    if (MD_CAN_OTHER && data.total > 0) {
        var nonShowCount = files.filter(function(f){
            if (f.source === 'quote') return false;
            if (!f.category_ids) return true;
            var catIds = f.category_ids.split(',').map(function(x){ return x.trim(); });
            return !catIds.some(function(cid){ return showCats.some(function(sc){ return String(sc.id)===cid; }); });
        }).length;
        var plusTotal = data.total - files.filter(function(f){ return f.source==='quote'; }).length;
        if (!anyShowTag || nonShowCount > 0) {
            var plusLabel = anyShowTag ? ('+'+nonShowCount) : ('+'+plusTotal);
            html += '<button class="btn btn-xs" onclick="openAttachAllView('+dId+',\''+escAttr(pno)+'\')" '
                  + 'style="font-size:10px;color:#555;background:#f5f5f5;border:1px solid #ddd;border-radius:10px;padding:1px 7px;" '
                  + 'title="全部附件 ('+data.total+')">'+plusLabel+'</button>';
        }
    } else if (MD_CAN_OTHER && CAN_PART_ATTACH) {
        // 有報價但無一般附件 → 顯示新增按鈕
        html += '<button class="btn btn-xs" onclick="openAttachAllView('+dId+',\''+escAttr(pno)+'\')" style="font-size:10px;color:#bbb;background:none;border:none;padding:1px 4px;" title="無附件，點擊新增"><i class="fa fa-paperclip"></i></button>';
    }

    html += '</div>';
    return html;
}

function rawEncode(s) { try { return encodeURIComponent(s); } catch(e) { return s; } }

// ── 圖面線上標記（Canvas 畫布）──────────────────────────────────────────
(function() {
    var _mc = {
        canvas: null, ctx: null, container: null,
        isDrawing: false, currentTool: 'pen', currentScale: 1.0,
        startX: 0, startY: 0, snapshot: null, history: [],
        rectStartX: 0, rectStartY: 0
    };

    function _init() {
        _mc.canvas    = document.getElementById('mdm-paint-canvas');
        _mc.ctx       = _mc.canvas ? _mc.canvas.getContext('2d') : null;
        _mc.container = document.getElementById('mdm-canvas-container');
        if (!_mc.canvas || !_mc.ctx) return;

        // Tool buttons
        document.querySelectorAll('.mdm-tool-btn').forEach(function(btn) {
            btn.addEventListener('click', function() {
                document.querySelectorAll('.mdm-tool-btn').forEach(function(b){ b.classList.remove('active'); });
                this.classList.add('active');
                _mc.currentTool = this.dataset.tool;
                _mc.container.style.cursor = _mc.currentTool === 'pan' ? 'grab' : 'crosshair';
            });
        });

        ['input','change'].forEach(function(ev) {
            var pc = document.getElementById('mdm-pen-color');
            var pw = document.getElementById('mdm-pen-width');
            if (pc) pc.addEventListener(ev, _updatePen);
            if (pw) pw.addEventListener(ev, _updatePen);
        });

        _mc.container.addEventListener('mousedown', _onMouseDown);
        _mc.container.addEventListener('mousemove', _onMouseMove);
        document.addEventListener('mouseup', _onMouseUp);

        var zOut = document.getElementById('mdm-btn-zoom-out');
        var zIn  = document.getElementById('mdm-btn-zoom-in');
        if (zOut) zOut.addEventListener('click', function(){ if (_mc.currentScale > 0.2) { _mc.currentScale -= 0.1; _updateZoom(); } });
        if (zIn)  zIn.addEventListener('click',  function(){ _mc.currentScale += 0.1; _updateZoom(); });

        var undo  = document.getElementById('mdm-btn-undo');
        var clear = document.getElementById('mdm-btn-clear');
        var print = document.getElementById('mdm-btn-print');
        if (undo)  undo.addEventListener('click',  _doUndo);
        if (clear) clear.addEventListener('click',  _doClear);
        if (print) print.addEventListener('click',  _doPrint);
    }

    function _updatePen() {
        if (!_mc.ctx) return;
        _mc.ctx.strokeStyle = (document.getElementById('mdm-pen-color')||{}).value || '#ff0000';
        _mc.ctx.fillStyle   = _mc.ctx.strokeStyle;
        _mc.ctx.lineWidth   = parseInt((document.getElementById('mdm-pen-width')||{}).value) || 3;
        _mc.ctx.lineCap     = 'round';
        _mc.ctx.lineJoin    = 'round';
    }

    function _getPos(e) {
        var rect = _mc.canvas.getBoundingClientRect();
        return {
            x: (e.clientX - rect.left) * (_mc.canvas.width  / rect.width),
            y: (e.clientY - rect.top)  * (_mc.canvas.height / rect.height)
        };
    }

    function _onMouseDown(e) {
        _mc.isDrawing = true;
        var pos = _getPos(e);
        _mc.startX = pos.x; _mc.startY = pos.y;
        _updatePen();
        if (_mc.currentTool === 'pen') {
            _mc.ctx.beginPath(); _mc.ctx.moveTo(pos.x, pos.y);
        } else if (_mc.currentTool === 'pan') {
            _mc.container.style.cursor = 'grabbing';
            _mc.startX = e.clientX; _mc.startY = e.clientY;
            _mc._scrollLeft = _mc.container.scrollLeft;
            _mc._scrollTop  = _mc.container.scrollTop;
        } else if (_mc.currentTool === 'rect' || _mc.currentTool === 'circle') {
            _mc.snapshot = _mc.ctx.getImageData(0, 0, _mc.canvas.width, _mc.canvas.height);
        } else if (_mc.currentTool === 'eraser_rect') {
            var cRect = _mc.container.getBoundingClientRect();
            _mc.rectStartX = e.clientX; _mc.rectStartY = e.clientY;
            var sel = document.getElementById('mdm-selection-box');
            if (sel) sel.style.cssText = 'display:block;left:'+(e.clientX - cRect.left + _mc.container.scrollLeft)+'px;top:'+(e.clientY - cRect.top + _mc.container.scrollTop)+'px;width:0;height:0;';
        }
    }

    function _onMouseMove(e) {
        if (!_mc.isDrawing) return;
        var pos = _getPos(e);
        if (_mc.currentTool === 'pen') {
            _mc.ctx.lineTo(pos.x, pos.y); _mc.ctx.stroke();
        } else if (_mc.currentTool === 'pan') {
            _mc.container.scrollLeft = _mc._scrollLeft - (e.clientX - _mc.startX);
            _mc.container.scrollTop  = _mc._scrollTop  - (e.clientY - _mc.startY);
        } else if (_mc.currentTool === 'rect') {
            _mc.ctx.putImageData(_mc.snapshot, 0, 0);
            _mc.ctx.beginPath(); _mc.ctx.rect(_mc.startX, _mc.startY, pos.x - _mc.startX, pos.y - _mc.startY); _mc.ctx.stroke();
        } else if (_mc.currentTool === 'circle') {
            _mc.ctx.putImageData(_mc.snapshot, 0, 0);
            var w = pos.x - _mc.startX, h = pos.y - _mc.startY;
            _mc.ctx.beginPath(); _mc.ctx.ellipse(_mc.startX + w/2, _mc.startY + h/2, Math.abs(w/2), Math.abs(h/2), 0, 0, 2*Math.PI); _mc.ctx.stroke();
        } else if (_mc.currentTool === 'eraser_rect') {
            var cRect2 = _mc.container.getBoundingClientRect();
            var w2 = e.clientX - _mc.rectStartX, h2 = e.clientY - _mc.rectStartY;
            var sel2 = document.getElementById('mdm-selection-box');
            if (sel2) sel2.style.cssText = 'display:block;position:absolute;border:2px dashed red;pointer-events:none;'
                + 'left:'+((w2<0?e.clientX:_mc.rectStartX) - cRect2.left + _mc.container.scrollLeft)+'px;'
                + 'top:' +((h2<0?e.clientY:_mc.rectStartY) - cRect2.top  + _mc.container.scrollTop)+'px;'
                + 'width:'+Math.abs(w2)+'px;height:'+Math.abs(h2)+'px;';
        }
    }

    function _onMouseUp(e) {
        if (!_mc.isDrawing) return;
        _mc.isDrawing = false;
        if (_mc.currentTool === 'eraser_rect') {
            var sel3 = document.getElementById('mdm-selection-box');
            if (sel3) sel3.style.display = 'none';
            var pos2 = _getPos(e);
            _mc.ctx.fillStyle = '#fff';
            _mc.ctx.fillRect(_mc.startX, _mc.startY, pos2.x - _mc.startX, pos2.y - _mc.startY);
            _updatePen();
        } else if (_mc.currentTool === 'pan') {
            _mc.container.style.cursor = 'grab';
        }
        if (_mc.currentTool !== 'pan') _saveHistory();
    }

    function _updateZoom() {
        var zl = document.getElementById('mdm-zoom-level');
        if (zl) zl.textContent = Math.round(_mc.currentScale * 100) + '%';
        _mc.canvas.style.width  = (_mc.canvas.width  * _mc.currentScale) + 'px';
        _mc.canvas.style.height = (_mc.canvas.height * _mc.currentScale) + 'px';
    }

    function _saveHistory() {
        if (_mc.history.length > 15) _mc.history.shift();
        _mc.history.push(_mc.canvas.toDataURL());
    }

    function _doUndo() {
        if (_mc.history.length <= 1) return;
        _mc.history.pop();
        var img2 = new Image();
        img2.onload = function(){ _mc.ctx.clearRect(0,0,_mc.canvas.width,_mc.canvas.height); _mc.ctx.drawImage(img2, 0, 0); };
        img2.src = _mc.history[_mc.history.length - 1];
    }

    function _doClear() {
        if (!_mc.history.length) return;
        var img3 = new Image();
        img3.onload = function(){ _mc.ctx.clearRect(0,0,_mc.canvas.width,_mc.canvas.height); _mc.ctx.drawImage(img3, 0, 0); _saveHistory(); };
        img3.src = _mc.history[0];
        _mc.history = [_mc.history[0]];
    }

    function _doPrint() {
        var url = _mc.canvas.toDataURL('image/png');
        var win = window.open('', '_blank');
        if (!win) return;
        var _pc = '@page{margin:0;}html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;}body{display:flex;align-items:center;justify-content:center;}img{display:block;max-width:100%;max-height:100%;object-fit:contain;}';
        win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>列印標記圖檔</title><style>' + _pc + '</style></head><body>');
        win.document.write('<img src="' + url + '" onload="window.print();">');
        win.document.write('</body></html>');
        win.document.close();
    }

    // ── 公開：小畫家開啟（同 bom_viewer.php 的 open-paint:// 協議）─────────
    window.pavOpenWithPaint = function() {
        var f = _pav.currentFile;
        if (!f || !f.url) return;
        // 取 url 的 host+path，格式：open-paint://HOST/PATH（VBScript 端補回 http://）
        var url  = f.url;
        var a    = document.createElement('a');
        a.href   = url;
        var host = a.hostname + (a.port ? ':' + a.port : '');
        var path = a.pathname + a.search;
        window.location.href = 'open-paint://' + host + path;
        document.getElementById('pav-paint-hint').style.display = 'block';
    };

    // ── 公開：開啟標記 Modal（保留，不再顯示按鈕）─────────────────────────
    window.pavOpenMarkup = function() {
        var f = _pav.currentFile;
        if (!f) return;
        var ext = (f.filename||'').split('.').pop().toLowerCase();
        var imgExts = ['jpg','jpeg','png','gif','webp','bmp','svg'];
        if (imgExts.indexOf(ext) < 0) { showToast('目前僅支援圖片格式的線上標記','warning'); return; }

        // 初始化 canvas（首次）
        if (!_mc.canvas) { _init(); }
        _mc.history       = [];
        _mc.currentScale  = 1.0;
        _mc.currentTool   = 'pen';
        document.querySelectorAll('.mdm-tool-btn').forEach(function(b){ b.classList.remove('active'); });
        var penBtn = document.querySelector('.mdm-tool-btn[data-tool="pen"]');
        if (penBtn) penBtn.classList.add('active');
        if (_mc.container) _mc.container.style.cursor = 'crosshair';
        var fnEl = document.getElementById('mdm-markup-filename');
        if (fnEl) fnEl.textContent = f.original_name || f.filename || '';

        var img = new Image();
        img.crossOrigin = 'Anonymous';
        img.onload = function() {
            _mc.canvas.width  = img.naturalWidth;
            _mc.canvas.height = img.naturalHeight;
            _mc.canvas.style.width  = img.naturalWidth  + 'px';
            _mc.canvas.style.height = img.naturalHeight + 'px';
            _mc.ctx.drawImage(img, 0, 0);
            _updatePen();
            _saveHistory();
        };
        img.onerror = function() { showToast('無法載入圖片（可能為跨來源限制）','error'); };
        img.src = f.url;

        $('#partAttachViewModal').css('z-index','1050');
        $('#mdmImageEditModal').modal('show');
    };

    // 關閉標記 Modal 時恢復父 Modal z-index
    $(document).on('hidden.bs.modal', '#mdmImageEditModal', function() {
        $('#partAttachViewModal').css('z-index','');
    });

    // 關閉附件 Modal 時清除 3D Viewer
    $(document).on('hidden.bs.modal', '#partAttachViewModal', function() {
        if (_pav3dViewer) { try { _pav3dViewer.Destroy(); } catch(e){} _pav3dViewer = null; }
    });
})();

// 載入料號列表時批次取附件資料
function loadPartAttachDataForRows(dIds) {
    if (!dIds || !dIds.length) return;
    loadActiveCatsForUpload(function() {
        $.post(PART_ATTACH_API_URL, { action:'list_latest_for_parts', d_ids:JSON.stringify(dIds) }, function(r) {
            if (!r.success) {
                // 清除 spinner（無附件）
                dIds.forEach(function(did) { _renderAttachCellForDId(did); });
                return;
            }
            Object.keys(r.data).forEach(function(did) { _partAttachData[parseInt(did)] = r.data[did]; });
            dIds.forEach(function(did) { _renderAttachCellForDId(did); });
        }).fail(function() {
            dIds.forEach(function(did) { _renderAttachCellForDId(did); });
        });
    });
}

// ── Gear Quality helpers ───────────────────────────────────────────────────
function loadGearQualityPanel() {
    api({ action:'manage_gear_quality', op:'get_default' }).done(function(r) {
        if (r.success && r.data) {
            var stdEl   = document.getElementById('dict-gq-def-std');
            var gradeEl = document.getElementById('dict-gq-def-grade');
            if (stdEl)   stdEl.value   = r.data.std   || '';
            if (gradeEl) gradeEl.value = r.data.grade || '';
        }
    });
    loadGearQualityRefTable();
}

function loadGearQualityRefTable() {
    var wrap = document.getElementById('dict-gq-ref-table-wrap');
    if (!wrap) return;
    wrap.innerHTML = '<div style="color:#aaa;font-size:12px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</div>';
    api({ action:'manage_gear_quality', op:'get_ref' }).done(function(r) {
        if (!r.success) { wrap.innerHTML = '<div style="color:#e74c3c;font-size:12px;">載入失敗</div>'; return; }
        var data = r.data || [];
        if (!data.length) { wrap.innerHTML = '<div style="color:#aaa;font-size:12px;">尚無對照資料</div>'; return; }
        var ro = !CAN_DICT_EDIT;
        var html = '<table class="table table-condensed table-bordered" style="font-size:12px;max-width:520px;">';
        html += '<thead><tr style="background:#f5f7fa;">';
        html += '<th style="text-align:center;width:90px;">ISO</th>';
        html += '<th style="text-align:center;width:90px;">DIN</th>';
        html += '<th style="text-align:center;width:90px;">JIS</th>';
        html += '<th style="text-align:center;width:90px;">AGMA</th>';
        if (!ro) html += '<th style="width:90px;text-align:center;">操作</th>';
        html += '</tr></thead><tbody>';
        data.forEach(function(row) {
            html += '<tr data-rid="'+row.quality_ref_id+'">';
            html += '<td><input type="number" class="form-control input-sm gq-iso" value="'+(row.iso_grade!==null?row.iso_grade:'')+'" min="1" max="12"'+(ro?' readonly':'')+'></td>';
            html += '<td><input type="number" class="form-control input-sm gq-din" value="'+(row.din_grade!==null?row.din_grade:'')+'" min="1" max="12"'+(ro?' readonly':'')+'></td>';
            html += '<td><input type="number" class="form-control input-sm gq-jis" value="'+(row.jis_grade!==null?row.jis_grade:'')+'" min="0" max="12"'+(ro?' readonly':'')+'></td>';
            html += '<td><input type="number" class="form-control input-sm gq-agma" value="'+(row.agma_grade!==null?row.agma_grade:'')+'" min="3" max="15"'+(ro?' readonly':'')+'></td>';
            if (!ro) {
                html += '<td style="text-align:center;white-space:nowrap;">';
                html += '<button type="button" class="btn btn-xs btn-primary" onclick="saveGearQualityRefRow(this,'+row.quality_ref_id+')" title="儲存"><i class="fa fa-save"></i></button> ';
                html += '<button type="button" class="btn btn-xs btn-danger" onclick="deleteGearQualityRefRow('+row.quality_ref_id+')" title="刪除"><i class="fa fa-trash"></i></button>';
                html += '</td>';
            }
            html += '</tr>';
        });
        html += '</tbody></table>';
        wrap.innerHTML = html;
        // 同步更新全域快取，讓齒輪規格設定的等級下拉即時反映
        _gearQualityRef = data;
    });
}

function saveGearQualityDefault() {
    var stdEl   = document.getElementById('dict-gq-def-std');
    var gradeEl = document.getElementById('dict-gq-def-grade');
    var std   = stdEl   ? stdEl.value   : '';
    var grade = gradeEl ? gradeEl.value : '';
    api({ action:'manage_gear_quality', op:'save_default', std:std, grade:grade }).done(function(r) {
        if (r.success) showToast('預設等級已儲存');
        else showToast(r.message||'儲存失敗','error');
    });
}

function addGearQualityRefRow() {
    api({ action:'manage_gear_quality', op:'save_ref_row', quality_ref_id:0, iso_grade:'', din_grade:'', jis_grade:'', agma_grade:'', sort_order:99 }).done(function(r) {
        if (r.success) loadGearQualityRefTable();
        else showToast(r.message||'新增失敗','error');
    });
}

function saveGearQualityRefRow(btn, rid) {
    var tr = btn.closest('tr');
    var iso  = tr.querySelector('.gq-iso').value;
    var din  = tr.querySelector('.gq-din').value;
    var jis  = tr.querySelector('.gq-jis').value;
    var agma = tr.querySelector('.gq-agma').value;
    api({ action:'manage_gear_quality', op:'save_ref_row', quality_ref_id:rid, iso_grade:iso, din_grade:din, jis_grade:jis, agma_grade:agma, sort_order:0 }).done(function(r) {
        if (r.success) showToast('已儲存');
        else showToast(r.message||'儲存失敗','error');
    });
}

function deleteGearQualityRefRow(rid) {
    if (!confirm('確定刪除此對照列？')) return;
    api({ action:'manage_gear_quality', op:'delete_ref_row', quality_ref_id:rid }).done(function(r) {
        if (r.success) loadGearQualityRefTable();
        else showToast(r.message||'刪除失敗','error');
    });
}

