    } else {
        $('#dict-f-lbl-input').prop('disabled', false);
        $('#dict-f-lbl-dl').prop('disabled', false);
        $('#dict-f-lbl-range').prop('disabled', false);
        $('#dict-f-lbl-tol').prop('disabled', false);
        $('#dict-f-lbl-qty-dim').prop('disabled', false);
        $('#dict-f-lbl-calc').prop('disabled', false);
    }
}
function onCalcSubLabelChange(value) {
    var labelId = parseInt(value)||0;
    if (!labelId) { $('#dict-f-tol-std-wrap').hide(); return; }
    var allLabels = window._allNumberLabels || [];
    var found = null;
    for (var i = 0; i < allLabels.length; i++) {
        if (parseInt(allLabels[i].label_id) === labelId) { found = allLabels[i]; break; }
    }
    if (found && (found.has_tolerance == '1' || found.has_tolerance === 1)) {
        $('#dict-f-tol-std-wrap').show();
    } else {
        $('#dict-f-tol-std-wrap').hide();
        $('#dict-f-tol-std-upper').val('');
    }
}
function populateCalcLabelDropdowns(currentLabelId, selBaseId, selSubId, tolStdUpper) {
    api({ action:'manage_labels', op:'list', type_code:'', page:1, page_size:999, search:'' }).done(function(r) {
        if (!r.success) return;
        var labels = (r.data||[]).filter(function(l) {
            return parseInt(l.label_id) !== currentLabelId
                && (l.input_type === 'number' || l.is_range == '1' || l.is_range === 1)
                && l.is_calc_diff != '1' && l.is_calc_diff !== 1;
        });
        window._allNumberLabels = labels;
        var makeOpts = function(selId) {
            var opts = '<option value="">— 選擇標籤 —</option>';
            labels.forEach(function(l) {
                opts += '<option value="' + l.label_id + '"' + (parseInt(l.label_id) === selId ? ' selected' : '') + '>' + escHtml(l.label_name) + '</option>';
            });
            return opts;
        };
        $('#dict-f-lbl-base').html(makeOpts(selBaseId));
        $('#dict-f-lbl-sub-calc').html(makeOpts(selSubId));
        if (tolStdUpper !== null && tolStdUpper !== '' && tolStdUpper !== undefined) {
            $('#dict-f-tol-std-upper').val(tolStdUpper);
        }
        onCalcSubLabelChange(selSubId || '');
    });
}
