function loadSubOptions(subId) {
    var listEl = document.getElementById('dict-sub-enum-opts-list');
    if (!listEl) return;
    api({ action:'manage_labels', op:'list_sub_options', sub_id:subId }).done(function(r) {
        renderSubOptionsInline(r.success ? (r.data||[]) : [], subId);
    });
}
function renderSubOptionsInline(opts, subId) {
    var listEl = document.getElementById('dict-sub-enum-opts-list');
    if (!listEl) return;
    listEl.innerHTML = '';
    if (!opts.length) { listEl.innerHTML = '<span style="font-size:11px;color:#aaa;">尚無選項</span>'; return; }
    opts.forEach(function(opt) {
        var tag = document.createElement('span');
        tag.style.cssText = 'display:inline-flex;align-items:center;background:#e3f2fd;color:#1565C0;border:1px solid #bbdefb;border-radius:12px;padding:2px 8px;font-size:11px;gap:4px;';
        tag.innerHTML = escHtml(opt.option_value);
        var rm = document.createElement('span');
        rm.style.cssText = 'cursor:pointer;color:#aaa;font-size:10px;margin-left:2px;';
        rm.textContent = '×';
        rm.onclick = (function(oid, sv) {
            return function() {
                if (!confirm('刪除選項「'+opt.option_value+'」？')) return;
                api({ action:'manage_labels', op:'delete_sub_option', option_id:oid }).done(function(r) {
                    if (!r.success) { showToast(r.message||'刪除失敗','error'); return; }
                    loadSubOptions(sv);
                    delete _subLabelCache[String($('#dict-edit-id').val()||'')];
                });
            };
        })(opt.option_id, subId);
        tag.appendChild(rm);
        listEl.appendChild(tag);
    });
}
function addSubOptionInline() {
    var subId = $('#dict-f-sub-id').val();
    if (!subId) { showToast('請先儲存子標籤後再管理選項','warning'); return; }
    var val = (document.getElementById('dict-f-sub-opt-val').value||'').trim();
    if (!val) { showToast('請輸入選項值','error'); return; }
    api({ action:'manage_labels', op:'save_sub_option', sub_id:subId, option_value:val }).done(function(r) {
        if (!r.success) { showToast(r.message||'新增失敗','error'); return; }
        document.getElementById('dict-f-sub-opt-val').value = '';
        loadSubOptions(subId);
        delete _subLabelCache[String($('#dict-edit-id').val()||'')];
        var _st = _partsFilter.types.length===1?_partsFilter.types[0]:''; if(_st) buildLabelFilterRow(_st);
    });
}
function openSubSlideout(labelName) {
