function toggleLabelSubPanel(show) {
    if (show) {
        var lname = ($('#dict-f-name').val()||'').trim() || '新標籤';
        openSubSlideout(lname);
        var labelId = $('#dict-edit-id').val();
        if (labelId) loadLabelSubs(labelId);
        else renderPendingSubsTable();
    } else {
        closeSubSlideout();
    }
}
// ── 產業別子項目管理 ────────────────────────────────────────────
function loadIndustrySubsForDict(industryId) {
    var tbody = document.getElementById('dict-ind-sub-tbody');
    if (!tbody) return;
    if (!industryId) {
        tbody.innerHTML = '<tr><td style="color:#aaa;text-align:center;padding:6px;">請先儲存產業別後再管理子項目</td></tr>';
        return;
    }
    api({ action:'manage_industry_sub_types', op:'list', industry_id:industryId }).done(function(r) {
        renderIndSubsTable(r.success ? (r.data||[]) : [], industryId);
    }).fail(function(){ renderIndSubsTable([], industryId); });
}
function renderIndSubsTable(subs, industryId) {
    var tbody = document.getElementById('dict-ind-sub-tbody');
    if (!tbody) return;
    if (!subs.length) {
        tbody.innerHTML = '<tr><td colspan="2" style="color:#aaa;text-align:center;padding:6px;">尚無子項目</td></tr>';
        return;
    }
    tbody.innerHTML = subs.map(function(s) {
        return '<tr>'
            + '<td style="padding:3px 6px;">'+escHtml(s.sub_name)+'</td>'
            + '<td style="padding:3px 6px;text-align:right;">'
            + (CAN_DELETE_ALL ? '<button class="btn btn-xs btn-danger" onclick="deleteIndustrySub('+parseInt(s.sub_id)+','+parseInt(industryId)+')"><i class="fa fa-trash"></i></button>' : '')
            + '</td></tr>';
    }).join('');
}
function addIndustrySub() {
    var industryId = $('#dict-edit-id').val();
    if (!industryId) { showToast('請先儲存產業別後再新增子項目','warning'); return; }
    var nm = ($('#dict-ind-sub-name').val()||'').trim();
    if (!nm) { showToast('請輸入子項目名稱','error'); return; }
    api({ action:'manage_industry_sub_types', op:'save', industry_id:industryId, sub_id:'', sub_name:nm }).done(function(r) {
        if (!r.success) { showToast(r.message||'儲存失敗','error'); return; }
        $('#dict-ind-sub-name').val('');
        loadIndustrySubsForDict(industryId);
        refreshDictListOnly('industry');
        industryCache = null;
    });
}
function deleteIndustrySub(subId, industryId) {
    if (!confirmDeleteY('確定刪除此子項目？')) return;
    api({ action:'manage_industry_sub_types', op:'delete', sub_id:subId }).done(function(r) {
        if (!r.success) { showToast(r.message||'刪除失敗','error'); return; }
        loadIndustrySubsForDict(industryId);
        refreshDictListOnly('industry');
        industryCache = null;
    });
}

function loadLabelSubs(labelId) {
    if (!labelId) { $('#dict-label-sub-tbody').html(''); return; }
    api({ action:'manage_labels', op:'list_subs', label_id:labelId }).done(function(r) {
        var subs = r.success ? (r.data||[]) : [];
        renderLabelSubsTable(subs);
        if (subs.length > 0) {
            $('#dict-f-lbl-has-sub').prop('checked', true);
            // Auto-open slideout if not already open
            var slideout = document.getElementById('dict-sub-slideout');
            if (slideout && slideout.style.right !== '0px' && slideout.style.right !== '0') {
                var lname = ($('#dict-f-name').val()||'').trim();
                openSubSlideout(lname);
            }
        }
    });
}
function renderLabelSubsTable(subs) {
    var itMap = {none:'無',number:'數字',text:'文字'};
    var html = '';
    if (!subs.length) { html = '<tr><td colspan="4" style="text-align:center;color:#aaa;padding:8px;">尚無子標籤</td></tr>'; }
    subs.forEach(function(s, i) {
        var hasDlB  = (s.has_draw_lathe=='1'||s.has_draw_lathe===1)
            ? '<span style="font-size:10px;background:#e8eeff;color:#5856d6;border-radius:3px;padding:1px 4px;margin-left:3px;">圖面+車床</span>' : '';
        var repB    = (s.is_repeatable=='1'||s.is_repeatable===1)
            ? '<span style="font-size:10px;background:#fff3cd;color:#856404;border-radius:3px;padding:1px 4px;margin-left:3px;">可多次</span>' : '';
        var rngB    = (s.is_range=='1'||s.is_range===1)
            ? '<span style="font-size:10px;background:#fdecea;color:#c0392b;border-radius:3px;padding:1px 4px;margin-left:3px;">範圍</span>' : '';
        var tolB    = (s.has_tolerance=='1'||s.has_tolerance===1)
            ? '<span style="font-size:10px;background:#fff3e0;color:#f57f17;border-radius:3px;padding:1px 4px;margin-left:3px;">公差</span>' : '';
        var dimB    = (s.is_dimension=='1'||s.is_dimension===1)
            ? '<span style="font-size:10px;background:#e3f2fd;color:#1565C0;border-radius:3px;padding:1px 4px;margin-left:3px;">長×寬</span>' : '';
        var qtyDimB = (s.is_qty_dim=='1'||s.is_qty_dim===1)
            ? '<span style="font-size:10px;background:#f3e5f5;color:#6a1a9a;border-radius:3px;padding:1px 4px;margin-left:3px;">數量-長×寬</span>' : '';
        var qtyTripleB = (s.is_qty_triple_dim=='1'||s.is_qty_triple_dim===1)
            ? '<span style="font-size:10px;background:#ede7f6;color:#4527a0;border-radius:3px;padding:1px 4px;margin-left:3px;">數量-長×寬×高</span>' : '';
        var imperialDimB = (s.is_imperial_dim=='1'||s.is_imperial_dim===1)
            ? '<span style="font-size:10px;background:#e0f2f1;color:#00695c;border-radius:3px;padding:1px 4px;margin-left:3px;">數量-英制圓×深</span>' : '';
        var countersinkB = (s.is_countersink=='1'||s.is_countersink===1)
            ? '<span style="font-size:10px;background:#fbe9e7;color:#bf360c;border-radius:3px;padding:1px 4px;margin-left:3px;">沉頭孔</span>' : '';
        var dlDepthB = (s.has_draw_lathe_depth=='1'||s.has_draw_lathe_depth===1)
            ? '<span style="font-size:10px;background:#e0f2f1;color:#004d40;border-radius:3px;padding:1px 4px;margin-left:3px;">圖+車×深</span>' : '';
        var tripleDimB = (s.is_triple_dim=='1'||s.is_triple_dim===1)
            ? '<span style="font-size:10px;background:#efebe9;color:#5d4037;border-radius:3px;padding:1px 4px;margin-left:3px;">小圓×大圓×深</span>' : '';
        var enumB    = (s.is_enum=='1'||s.is_enum===1)
            ? '<span style="font-size:10px;background:#e3f2fd;color:#1565C0;border-radius:3px;padding:1px 4px;margin-left:3px;">列舉</span>' : '';
        var hideNmB  = (s.hide_name_in_display=='1'||s.hide_name_in_display===1)
            ? '<span style="font-size:10px;background:#f5f5f5;color:#888;border-radius:3px;padding:1px 4px;margin-left:2px;">省略名稱</span>' : '';
        var pfxB    = s.prefix_char ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">前'+escHtml(s.prefix_char)+'</span>' : '';
        var sfxB    = s.suffix_char ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">後'+escHtml(s.suffix_char)+'</span>' : '';
        html += '<tr data-sub-row="'+s.sub_id+'">';
        html += '<td style="width:28px;padding:4px 6px;cursor:grab;color:#bbb;text-align:center;"><i class="fa fa-bars"></i></td>';
        html += '<td style="padding:3px 6px;"><strong>'+escHtml(s.sub_name)+'</strong> <span style="color:#aaa;font-size:10px;">'+(itMap[s.input_type]||s.input_type)+'</span>'+hasDlB+repB+rngB+tolB+dimB+qtyDimB+qtyTripleB+imperialDimB+countersinkB+dlDepthB+tripleDimB+enumB+hideNmB+pfxB+sfxB+'</td>';
        html += '<td style="padding:3px 6px;text-align:center;white-space:nowrap;">';
        if (_canEditDict('label-sub')) html += '<button class="btn btn-xs btn-default" onclick="editLabelSub('+i+')" style="margin-right:3px;"><i class="fa fa-pencil"></i></button>';
        if (_canEditDict('label-sub')) html += '<button class="btn btn-xs btn-danger" onclick="deleteLabelSub('+s.sub_id+')"><i class="fa fa-trash"></i></button>';
        html += '</td></tr>';
    });
    // Cache for edit
    window._dictLabelSubsCache = subs;
    $('#dict-label-sub-tbody').html(html);
    initSubLabelSortable();
}
function editLabelSub(idx) {
    var s = (window._dictLabelSubsCache||[])[idx];
    if (!s) return;
    $('#dict-f-sub-id').val(s.sub_id);
    $('#dict-f-sub-name').val(s.sub_name||'');
    var hasDl        = (s.has_draw_lathe=='1'||s.has_draw_lathe===1);
    var isRng        = (s.is_range=='1'||s.is_range===1);
    var hasTol       = (s.has_tolerance=='1'||s.has_tolerance===1);
    var isDim        = (s.is_dimension=='1'||s.is_dimension===1);
    var isQtyDim     = (s.is_qty_dim=='1'||s.is_qty_dim===1);
    var isImperialDim  = (s.is_imperial_dim=='1'||s.is_imperial_dim===1);
    var isCountersink  = (s.is_countersink=='1'||s.is_countersink===1);
    var isDlDepth      = (s.has_draw_lathe_depth=='1'||s.has_draw_lathe_depth===1);
    var isTripleDimS   = (s.is_triple_dim=='1'||s.is_triple_dim===1);
    var isEnum         = (s.is_enum=='1'||s.is_enum===1);
    var hideNm         = (s.hide_name_in_display=='1'||s.hide_name_in_display===1);
    var isQtyTriple    = (s.is_qty_triple_dim=='1'||s.is_qty_triple_dim===1);
    var anySpecial     = hasDl||isDlDepth||isTripleDimS||isRng||hasTol||isDim||isQtyDim||isQtyTriple||isImperialDim||isCountersink||isEnum;
    $('#dict-f-sub-dl').prop('checked', hasDl);
    $('#dict-f-sub-dl-depth').prop('checked', isDlDepth).prop('disabled', hasDl || isTripleDimS || isRng || hasTol || isDim || isQtyDim || isQtyTriple || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-triple-dim').prop('checked', isTripleDimS).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isDim || isQtyDim || isQtyTriple || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-range').prop('checked', isRng && !hasDl).prop('disabled', hasDl || isDlDepth || hasTol || isDim || isQtyDim || isQtyTriple || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-tol').prop('checked', hasTol && !isRng).prop('disabled', isRng || isDlDepth || isDim || isQtyDim || isQtyTriple || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-dim').prop('checked', isDim).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isQtyDim || isQtyTriple || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-qty-dim').prop('checked', isQtyDim).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isDim || isQtyTriple || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-qty-triple-dim').prop('checked', isQtyTriple).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isDim || isQtyDim || isImperialDim || isCountersink || isEnum);
    $('#dict-f-sub-imperial-dim').prop('checked', isImperialDim).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isDim || isQtyDim || isQtyTriple || isCountersink || isEnum);
    $('#dict-f-sub-countersink').prop('checked', isCountersink).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isDim || isQtyDim || isQtyTriple || isImperialDim || isEnum);
    $('#dict-f-sub-enum').prop('checked', isEnum).prop('disabled', hasDl || isDlDepth || isRng || hasTol || isDim || isQtyDim || isQtyTriple || isImperialDim || isCountersink);
    $('#dict-f-sub-hide-name').prop('checked', hideNm);
    $('#dict-f-sub-input').val(anySpecial ? ((isImperialDim||isCountersink||isDlDepth||isTripleDimS||isEnum)?'none':'number') : (s.input_type||'none')).prop('disabled', anySpecial);
    var enumArea = document.getElementById('dict-sub-enum-opts-area');
    if (enumArea) { enumArea.style.display = isEnum ? 'block' : 'none'; if (isEnum) loadSubOptions(s.sub_id); }
    $('#dict-f-sub-rep').prop('checked', s.is_repeatable=='1'||s.is_repeatable===1);
    $('#dict-f-sub-prefix').val(s.prefix_char||'');
    $('#dict-f-sub-suffix').val(s.suffix_char||'');
}
function saveLabelSub() {
    var labelId = $('#dict-edit-id').val();
    if (!labelId) { showToast('請先儲存標籤後再新增子標籤','warning'); return; }
    var subId   = $('#dict-f-sub-id').val()||0;
    var subName = $('#dict-f-sub-name').val().trim();
    var hasDl    = $('#dict-f-sub-dl').is(':checked') ? 1 : 0;
    var isRng    = (!hasDl && $('#dict-f-sub-range').is(':checked')) ? 1 : 0;
    var hasTol   = (!isRng && $('#dict-f-sub-tol').is(':checked')) ? 1 : 0;
    var isDim    = (!hasDl && !isRng && !hasTol && $('#dict-f-sub-dim').is(':checked')) ? 1 : 0;
    var isQtyDim     = (!hasDl && !isRng && !hasTol && !isDim && $('#dict-f-sub-qty-dim').is(':checked')) ? 1 : 0;
    var isQtyTriple  = (!hasDl && !isRng && !hasTol && !isDim && !isQtyDim && $('#dict-f-sub-qty-triple-dim').is(':checked')) ? 1 : 0;
    var isImperialDim  = (!hasDl && !isRng && !hasTol && !isDim && !isQtyDim && !isQtyTriple && $('#dict-f-sub-imperial-dim').is(':checked')) ? 1 : 0;
    var isCountersink  = (!hasDl && !isRng && !hasTol && !isDim && !isQtyDim && !isQtyTriple && !isImperialDim && $('#dict-f-sub-countersink').is(':checked')) ? 1 : 0;
    var isDlDepth      = (!hasDl && !isRng && !hasTol && !isDim && !isQtyDim && !isQtyTriple && !isImperialDim && !isCountersink && $('#dict-f-sub-dl-depth').is(':checked')) ? 1 : 0;
    var isTripleDimSv  = (!hasDl && !isDlDepth && !isRng && !hasTol && !isDim && !isQtyDim && !isQtyTriple && !isImperialDim && !isCountersink && $('#dict-f-sub-triple-dim').is(':checked')) ? 1 : 0;
    var isEnum         = (!hasDl && !isDlDepth && !isTripleDimSv && !isRng && !hasTol && !isDim && !isQtyDim && !isQtyTriple && !isImperialDim && !isCountersink && $('#dict-f-sub-enum').is(':checked')) ? 1 : 0;
    var hideNm         = $('#dict-f-sub-hide-name').is(':checked') ? 1 : 0;
    var inpType  = (isImperialDim||isCountersink||isDlDepth||isTripleDimSv||isEnum) ? 'none' : ((hasDl || isRng || hasTol || isDim || isQtyDim || isQtyTriple) ? 'number' : ($('#dict-f-sub-input').val()||'none'));
    var isRep    = $('#dict-f-sub-rep').is(':checked') ? 1 : 0;
    var pfxChar  = ($('#dict-f-sub-prefix').val()||'').trim();
    var sfxChar  = ($('#dict-f-sub-suffix').val()||'').trim();
    if (!subName) { showToast('請輸入子標籤名稱','error'); return; }
    api({ action:'manage_labels', op:'save_sub', label_id:labelId, sub_id:subId, sub_name:subName, input_type:inpType, is_repeatable:isRep, has_draw_lathe:hasDl, is_range:isRng, has_tolerance:hasTol, is_dimension:isDim, is_qty_dim:isQtyDim, is_qty_triple_dim:isQtyTriple, is_imperial_dim:isImperialDim, is_countersink:isCountersink, has_draw_lathe_depth:isDlDepth, is_triple_dim:isTripleDimSv, is_enum:isEnum, hide_name_in_display:hideNm, prefix_char:pfxChar, suffix_char:sfxChar }).done(function(r) {
        if (!r.success) { showToast(r.message||'儲存失敗','error'); return; }
        showToast('已儲存','success');
        $('#dict-f-sub-id').val(''); $('#dict-f-sub-name').val('');
        $('#dict-f-sub-input').val('none').prop('disabled',false);
        $('#dict-f-sub-rep').prop('checked',false);
        $('#dict-f-sub-dl').prop('checked',false);
        $('#dict-f-sub-dl-depth').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-range').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-tol').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-qty-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-qty-triple-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-imperial-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-countersink').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-triple-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-enum').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-hide-name').prop('checked',false);
        $('#dict-f-sub-prefix').val('');
        $('#dict-f-sub-suffix').val('');
        var _ea = document.getElementById('dict-sub-enum-opts-area'); if(_ea) _ea.style.display='none';
        document.getElementById('dict-sub-enum-opts-list').innerHTML='';
        loadLabelSubs(labelId);
        delete _subLabelCache[String(labelId)];
        var _st = _partsFilter.types.length===1?_partsFilter.types[0]:''; if(_st) buildLabelFilterRow(_st);
    });
}
function deleteLabelSub(subId) {
    var labelId = $('#dict-edit-id').val();
    api({ action:'manage_labels', op:'check_delete_sub', sub_id:subId }).done(function(cr) {
        if (!cr.can_delete) { showToast(cr.reason || '此子標籤已被使用，無法刪除', 'error'); return; }
        if (!confirmDeleteY('確定刪除此子標籤？')) return;
        api({ action:'manage_labels', op:'delete_sub', sub_id:subId }).done(function(r) {
            if (!r.success) { showToast(r.message||'刪除失敗','error'); return; }
            showToast('已刪除','success');
            loadLabelSubs(labelId);
            delete _subLabelCache[String(labelId)];
            var _st = _partsFilter.types.length===1?_partsFilter.types[0]:''; if(_st) buildLabelFilterRow(_st);
        });
    });
}

function checkLabelNameSimilar(name) {
    name = (name||'').trim();
    if (!name) return;
    var labelId = $('#dict-edit-id').val() || 0;
    api({ action:'manage_labels', op:'check_name', label_name:name, label_id:labelId }).done(function(r) {
        if (!r.success) return;
        if (r.exact) {
            showToast('已存在相同名稱「'+name+'」的標籤，請使用不同名稱', 'error');
        } else if (r.similar && r.similar.length) {
            var names = r.similar.map(function(s){ return '「'+s.label_name+'」'; }).join('、');
            showToast('注意：存在類似名稱 '+names+'，請確認是否重複', 'warning');
        }
    });
}

function addOrSaveLabelSub() {
    var subName  = $('#dict-f-sub-name').val().trim();
    if (!subName) { showToast('請輸入子標籤名稱','error'); return; }
    var hasDl    = $('#dict-f-sub-dl').is(':checked') ? 1 : 0;
    var isRng    = (!hasDl && $('#dict-f-sub-range').is(':checked')) ? 1 : 0;
    var hasTol   = (!isRng && $('#dict-f-sub-tol').is(':checked')) ? 1 : 0;
    var isDim    = (!hasDl && !isRng && !hasTol && $('#dict-f-sub-dim').is(':checked')) ? 1 : 0;
    var isQtyDim = (!hasDl && !isRng && !hasTol && !isDim && $('#dict-f-sub-qty-dim').is(':checked')) ? 1 : 0;
    var isQtyTriple = (!hasDl && !isRng && !hasTol && !isDim && !isQtyDim && $('#dict-f-sub-qty-triple-dim').is(':checked')) ? 1 : 0;
    var inpType  = (hasDl || isRng || hasTol || isDim || isQtyDim || isQtyTriple) ? 'number' : ($('#dict-f-sub-input').val()||'none');
    var isRep    = $('#dict-f-sub-rep').is(':checked') ? 1 : 0;
    var pfxChar  = ($('#dict-f-sub-prefix').val()||'').trim();
    var sfxChar  = ($('#dict-f-sub-suffix').val()||'').trim();
    var labelId  = $('#dict-edit-id').val();
    if (labelId) {
        saveLabelSub();
    } else {
        var subIdxStr = $('#dict-f-sub-id').val();
        var subObj = { sub_name:subName, input_type:inpType, is_repeatable:isRep, has_draw_lathe:hasDl, is_range:isRng, has_tolerance:hasTol, is_dimension:isDim, is_qty_dim:isQtyDim, is_qty_triple_dim:isQtyTriple, prefix_char:pfxChar, suffix_char:sfxChar };
        if (subIdxStr !== '') {
            var idx = parseInt(subIdxStr, 10);
            _pendingSubLabels[idx] = subObj;
        } else {
            _pendingSubLabels.push(subObj);
        }
        $('#dict-f-sub-id').val('');
        $('#dict-f-sub-name').val('');
        $('#dict-f-sub-input').val('none').prop('disabled', false);
        $('#dict-f-sub-rep').prop('checked', false);
        $('#dict-f-sub-dl').prop('checked', false);
        $('#dict-f-sub-range').prop('checked', false).prop('disabled', false);
        $('#dict-f-sub-tol').prop('checked', false).prop('disabled', false);
        $('#dict-f-sub-dim').prop('checked', false).prop('disabled', false);
        $('#dict-f-sub-qty-dim').prop('checked', false).prop('disabled', false);
        $('#dict-f-sub-qty-triple-dim').prop('checked', false).prop('disabled', false);
        $('#dict-f-sub-prefix').val('');
        $('#dict-f-sub-suffix').val('');
        renderPendingSubsTable();
    }
}

function renderPendingSubsTable() {
    var itMap = {none:'無',number:'數字',text:'文字'};
    var html = '';
    if (!_pendingSubLabels.length) {
        html = '<tr><td colspan="3" style="text-align:center;color:#aaa;padding:6px;font-size:11px;">尚無子標籤（儲存標籤後可繼續新增）</td></tr>';
    } else {
        _pendingSubLabels.forEach(function(s, i) {
            var hasDlB  = s.has_draw_lathe ? '<span style="font-size:10px;background:#e8eeff;color:#5856d6;border-radius:3px;padding:1px 4px;margin-left:3px;">圖+車</span>' : '';
            var repB    = s.is_repeatable  ? '<span style="font-size:10px;background:#fff3cd;color:#856404;border-radius:3px;padding:1px 4px;margin-left:2px;">多次</span>' : '';
            var rngB    = s.is_range       ? '<span style="font-size:10px;background:#fdecea;color:#c0392b;border-radius:3px;padding:1px 4px;margin-left:2px;">範圍</span>' : '';
            var tolB    = s.has_tolerance  ? '<span style="font-size:10px;background:#fff3e0;color:#f57f17;border-radius:3px;padding:1px 4px;margin-left:2px;">公差</span>' : '';
            var dimB    = s.is_dimension   ? '<span style="font-size:10px;background:#e3f2fd;color:#1565C0;border-radius:3px;padding:1px 4px;margin-left:2px;">長×寬</span>' : '';
            var qtyDimB = s.is_qty_dim     ? '<span style="font-size:10px;background:#f3e5f5;color:#6a1a9a;border-radius:3px;padding:1px 4px;margin-left:2px;">數量-長×寬</span>' : '';
            var qtyTripleB = s.is_qty_triple_dim ? '<span style="font-size:10px;background:#ede7f6;color:#4527a0;border-radius:3px;padding:1px 4px;margin-left:2px;">數量-長×寬×高</span>' : '';
            var pfxB    = s.prefix_char    ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">前'+escHtml(s.prefix_char)+'</span>' : '';
            var sfxB    = s.suffix_char    ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">後'+escHtml(s.suffix_char)+'</span>' : '';
            html += '<tr data-pending-idx="'+i+'">';
            html += '<td style="width:28px;padding:4px 6px;cursor:grab;color:#bbb;text-align:center;"><i class="fa fa-bars"></i></td>';
            html += '<td style="padding:3px 6px;"><strong>'+escHtml(s.sub_name)+'</strong> <span style="color:#aaa;font-size:10px;">'+(itMap[s.input_type]||s.input_type)+'</span>'+hasDlB+repB+rngB+tolB+dimB+qtyDimB+qtyTripleB+pfxB+sfxB+'</td>';
            html += '<td style="padding:3px 6px;text-align:center;white-space:nowrap;">';
            html += '<button class="btn btn-xs btn-default" onclick="editPendingSub('+i+')" style="margin-right:3px;"><i class="fa fa-pencil"></i></button>';
            html += '<button class="btn btn-xs btn-danger" onclick="deletePendingSub('+i+')"><i class="fa fa-trash"></i></button>';
            html += '</td></tr>';
        });
    }
    $('#dict-label-sub-tbody').html(html);
    initSubLabelSortable();
}

function editPendingSub(idx) {
    var s = _pendingSubLabels[idx];
    if (!s) return;
    $('#dict-f-sub-id').val(idx);
    $('#dict-f-sub-name').val(s.sub_name||'');
    var hasDl    = !!s.has_draw_lathe;
    var isRng    = !!s.is_range && !hasDl;
    var hasTol   = !!s.has_tolerance && !isRng;
    var isDim    = !!s.is_dimension && !hasDl && !isRng && !hasTol;
    var isQtyDim = !!s.is_qty_dim && !hasDl && !isRng && !hasTol && !isDim;
    var isQtyTriple = !!s.is_qty_triple_dim && !hasDl && !isRng && !hasTol && !isDim && !isQtyDim;
    $('#dict-f-sub-dl').prop('checked', hasDl);
    $('#dict-f-sub-range').prop('checked', isRng).prop('disabled', hasDl || hasTol || isDim || isQtyDim || isQtyTriple);
    $('#dict-f-sub-tol').prop('checked', hasTol).prop('disabled', isRng || isDim || isQtyDim || isQtyTriple);
    $('#dict-f-sub-dim').prop('checked', isDim).prop('disabled', hasDl || isRng || hasTol || isQtyDim || isQtyTriple);
    $('#dict-f-sub-qty-dim').prop('checked', isQtyDim).prop('disabled', hasDl || isRng || hasTol || isDim || isQtyTriple);
    $('#dict-f-sub-qty-triple-dim').prop('checked', isQtyTriple).prop('disabled', hasDl || isRng || hasTol || isDim || isQtyDim);
    $('#dict-f-sub-input').val((hasDl||isRng||hasTol||isDim||isQtyDim||isQtyTriple) ? 'number' : (s.input_type||'none')).prop('disabled', hasDl||isRng||hasTol||isDim||isQtyDim||isQtyTriple);
    $('#dict-f-sub-rep').prop('checked', !!s.is_repeatable);
    $('#dict-f-sub-prefix').val(s.prefix_char||'');
    $('#dict-f-sub-suffix').val(s.suffix_char||'');
}

function deletePendingSub(idx) {
    _pendingSubLabels.splice(idx, 1);
    renderPendingSubsTable();
}

function initSubLabelSortable() {
    var tbody = document.getElementById('dict-label-sub-tbody');
    if (!tbody || typeof Sortable === 'undefined') return;
    if (tbody._sortable) tbody._sortable.destroy();
    tbody._sortable = Sortable.create(tbody, {
        animation: 150, ghostClass: 'sortable-ghost',
        filter: '.btn',
        onEnd: function() {
            var labelId = $('#dict-edit-id').val();
            if (labelId) {
                var ids = [];
                tbody.querySelectorAll('tr[data-sub-row]').forEach(function(tr){ ids.push(tr.dataset.subRow); });
                if (ids.length) {
                    api({ action:'manage_labels', op:'reorder_subs', ids:ids.join(',') }).done(function(r){
                        if (!r.success) showToast('排序儲存失敗','error');
                    });
                }
            } else {
                var newOrder = [];
                tbody.querySelectorAll('tr[data-pending-idx]').forEach(function(tr){
                    var i = parseInt(tr.dataset.pendingIdx, 10);
                    if (!isNaN(i) && _pendingSubLabels[i]) newOrder.push(_pendingSubLabels[i]);
                });
                _pendingSubLabels = newOrder;
                renderPendingSubsTable();
            }
        }
    });
}

// ── Generic paginated dict (maker-main, maker-sub) ────────────────────────
var _paginatedDictData = {};  // type → {allData, page, pageSize, search}

function initPaginatedDict(type, data) {
    var state = _paginatedDictData[type] || { page:1, pageSize:20, search:'' };
    state.allData = data;
    _paginatedDictData[type] = state;
    var tbl = document.getElementById('dict-table');
    if (tbl && !document.getElementById('dict-pg-searchbar')) {
        var bar = document.createElement('div');
        bar.id = 'dict-pg-searchbar';
        bar.style.cssText = 'display:flex;gap:6px;align-items:center;margin:8px 0 2px;flex-wrap:wrap;';
        bar.innerHTML = '<input type="text" id="dict-pg-q" class="form-control input-sm" placeholder="搜尋名稱…" style="max-width:200px;" oninput="onDictPgSearch()">'
            + '<span id="dict-pg-info" style="font-size:11px;color:#aaa;"></span>';
        tbl.parentNode.insertBefore(bar, tbl);
    }
    if (tbl && !document.getElementById('dict-pg-pagination')) {
        var pg = document.createElement('div');
        pg.id = 'dict-pg-pagination';
        pg.style.cssText = 'display:flex;gap:3px;justify-content:center;margin-top:4px;flex-wrap:wrap;';
        tbl.parentNode.appendChild(pg);
    }
    // Restore search input if switching back to same type
    if (document.getElementById('dict-pg-q')) {
        document.getElementById('dict-pg-q').value = state.search;
    }
    renderPaginatedDictPage(type);
}

function onDictPgSearch() {
    var state = _paginatedDictData[currentDictType];
    if (!state) return;
    state.search = (document.getElementById('dict-pg-q').value||'').trim().toLowerCase();
    state.page = 1;
    renderPaginatedDictPage(currentDictType);
}

function setDictPgPage(type, p) {
    var state = _paginatedDictData[type];
    if (!state) return;
    state.page = p;
    renderPaginatedDictPage(type);
}

function renderPaginatedDictPage(type) {
    var state = _paginatedDictData[type];
    if (!state) return;
    var searchField = (type === 'maker-sub') ? 'sub_cat_name' : 'main_cat_name';
    var filtered = state.allData.filter(function(d) {
        if (!state.search) return true;
        return ((d[searchField]||'').toLowerCase().indexOf(state.search) >= 0);
    });
    var total = filtered.length;
    var pages = Math.max(1, Math.ceil(total / state.pageSize));
    if (state.page > pages) state.page = pages;
    var start = (state.page - 1) * state.pageSize;
    var pageData = filtered.slice(start, start + state.pageSize);

    $('#dict-count-badge').text(total + ' 筆');
    var pgInfo = document.getElementById('dict-pg-info');
    if (pgInfo) pgInfo.textContent = pages > 1 ? ('第 ' + state.page + ' / ' + pages + ' 頁') : '';

    renderDictTable(type, pageData);

    var pgEl = document.getElementById('dict-pg-pagination');
    if (pgEl) {
        var pgHtml = '';
        if (pages > 1) {
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setDictPgPage(\''+type+'\',1)"'+(state.page===1?' disabled':'')+'>«</button>';
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setDictPgPage(\''+type+'\','+(state.page-1)+')"'+(state.page===1?' disabled':'')+'>‹</button>';
            var pstart = Math.max(1, state.page-2), pend = Math.min(pages, pstart+4);
            for (var p = pstart; p <= pend; p++) {
                pgHtml += '<button class="btn btn-xs '+(p===state.page?'btn-primary':'btn-default')+'" onclick="setDictPgPage(\''+type+'\','+p+')">'+p+'</button>';
            }
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setDictPgPage(\''+type+'\','+(state.page+1)+')"'+(state.page===pages?' disabled':'')+'>›</button>';
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setDictPgPage(\''+type+'\','+pages+')"'+(state.page===pages?' disabled':'')+'>»</button>';
        }
        pgEl.innerHTML = pgHtml;
    }
}

// ── Label list search / pagination ─────────────────────────────────────────
function renderLabelDictFull(data) {
    _labelDictAllData = data;
    _labelDictPage = 1;
    _labelDictSearch = ($('#dict-label-q').length ? $('#dict-label-q').val() : '');
    var tbl = document.getElementById('dict-table');
    if (tbl && !document.getElementById('dict-label-searchbar')) {
        var bar = document.createElement('div');
        bar.id = 'dict-label-searchbar';
        bar.style.cssText = 'display:flex;gap:6px;align-items:center;margin:8px 0 2px;flex-wrap:wrap;';
        bar.innerHTML = '<input type="text" id="dict-label-q" class="form-control input-sm" placeholder="搜尋標籤名稱…" style="max-width:200px;" oninput="onLabelDictSearch(this.value)">'
            + '<span id="dict-label-pg-info" style="font-size:11px;color:#aaa;"></span>';
        tbl.parentNode.insertBefore(bar, tbl);
    }
    if (tbl && !document.getElementById('dict-label-pagination')) {
        var pg = document.createElement('div');
        pg.id = 'dict-label-pagination';
        pg.style.cssText = 'display:flex;gap:3px;justify-content:center;margin-top:4px;flex-wrap:wrap;';
        tbl.parentNode.appendChild(pg);
    }
    renderLabelDictPage();
}

function onLabelDictSearch(val) {
    _labelDictSearch = (val||'').trim().toLowerCase();
    _labelDictPage = 1;
    renderLabelDictPage();
}

function setLabelDictPage(p) {
    _labelDictPage = p;
    renderLabelDictPage();
}

function renderLabelDictPage() {
    var allFiltered = _labelDictAllData.filter(function(d) {
        if (!_labelDictSearch) return true;
        return (d.label_name||'').toLowerCase().indexOf(_labelDictSearch) >= 0;
    });
    // Sort: normal labels first, hidden_frontend labels at bottom
    var filtered = allFiltered.filter(function(d){ return !(d.is_hidden_frontend=='1'||d.is_hidden_frontend===1); })
        .concat(allFiltered.filter(function(d){ return (d.is_hidden_frontend=='1'||d.is_hidden_frontend===1); }));
    var total = filtered.length;
    var pages = Math.max(1, Math.ceil(total / _labelDictPageSize));
    if (_labelDictPage > pages) _labelDictPage = pages;
    var start = (_labelDictPage - 1) * _labelDictPageSize;
    var pageData = filtered.slice(start, start + _labelDictPageSize);

    $('#dict-count-badge').text(total + ' 筆');
    var pgInfo = document.getElementById('dict-label-pg-info');
    if (pgInfo) pgInfo.textContent = pages > 1 ? ('第 ' + _labelDictPage + ' / ' + pages + ' 頁') : '';

    // Render table rows
    _dictDataCache = {};
    var html = '';
    if (!pageData.length) {
        html = '<tr><td colspan="3" class="text-center" style="padding:20px;color:#aaa;">' + (_labelDictSearch ? '無符合「'+escHtml(_labelDictSearch)+'」的標籤' : '目前無資料') + '</td></tr>';
    } else {
        var itMap = {none:'無輸入', number:'數字', text:'文字'};
        pageData.forEach(function(d) {
            var realIdx = _labelDictAllData.indexOf(d);
            _dictDataCache[String(realIdx)] = d;
            var typeCodes = (d.type_code||'').split(',').map(function(s){ return s.trim(); }).filter(Boolean);
            var typeBadges = typeCodes.map(function(tc){
                return '<span style="font-size:10px;background:#eef2ff;color:#5856d6;border-radius:3px;padding:1px 5px;margin:0 1px;">'+escHtml(tc)+'</span>';
            }).join('');
            var itBadge   = '<span style="font-size:10px;background:#e8f5f2;color:#1ABB9C;border-radius:3px;padding:1px 4px;margin-left:3px;">'+(itMap[d.input_type]||d.input_type)+'</span>';
            var repBadge  = (d.is_repeatable=='1'||d.is_repeatable===1)   ? '<span style="font-size:10px;background:#fff3cd;color:#856404;border-radius:3px;padding:1px 4px;margin-left:2px;">多次</span>' : '';
            var dlBadge   = (d.has_draw_lathe=='1'||d.has_draw_lathe===1)  ? '<span style="font-size:10px;background:#e8eeff;color:#5856d6;border-radius:3px;padding:1px 4px;margin-left:2px;">圖+車</span>' : '';
            var rngBadge  = (d.is_range=='1'||d.is_range===1)              ? '<span style="font-size:10px;background:#fff0f6;color:#c0392b;border-radius:3px;padding:1px 4px;margin-left:2px;">範圍</span>' : '';
            var tolBadge  = (d.has_tolerance=='1'||d.has_tolerance===1)    ? '<span style="font-size:10px;background:#fff8e1;color:#f57f17;border-radius:3px;padding:1px 4px;margin-left:2px;">公差</span>' : '';
            var calcBadge = (d.is_calc_diff=='1'||d.is_calc_diff===1)      ? '<span style="font-size:10px;background:#f3e5f5;color:#7b1fa2;border-radius:3px;padding:1px 4px;margin-left:2px;">計算差異</span>' : '';
            var exclBadge = (d.is_exclude_calc=='1'||d.is_exclude_calc===1) ? '<span style="font-size:10px;background:#fbe9e7;color:#bf360c;border-radius:3px;padding:1px 4px;margin-left:2px;">不計算</span>' : '';
            var dimBadge2    = (d.is_dimension=='1'||d.is_dimension===1) ? '<span style="font-size:10px;background:#e3f2fd;color:#1565C0;border-radius:3px;padding:1px 4px;margin-left:2px;">長×寬</span>' : '';
            var qtyDimBadge2 = (d.is_qty_dim=='1'||d.is_qty_dim===1) ? '<span style="font-size:10px;background:#f3e5f5;color:#6a1a9a;border-radius:3px;padding:1px 4px;margin-left:2px;">數量-長×寬</span>' : '';
            var pfxBadge2    = (d.prefix_char) ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">前'+escHtml(d.prefix_char)+'</span>' : '';
            var sfxBadge2    = (d.suffix_char) ? '<span style="font-size:10px;background:#f9fbe7;color:#827717;border-radius:3px;padding:1px 4px;margin-left:2px;">後'+escHtml(d.suffix_char)+'</span>' : '';
            var hidBadge2    = (d.is_hidden_frontend=='1'||d.is_hidden_frontend===1) ? '<span style="font-size:10px;background:#eceff1;color:#78909c;border-radius:3px;padding:1px 4px;margin-left:2px;">隱藏</span>' : '';
            // Add separator before first hidden item
            var isHiddenRow = (d.is_hidden_frontend=='1'||d.is_hidden_frontend===1);
            var rowIdx = pageData.indexOf(d);
            if (isHiddenRow && rowIdx > 0 && !(pageData[rowIdx-1].is_hidden_frontend=='1'||pageData[rowIdx-1].is_hidden_frontend===1)) {
                html += '<tr><td colspan="3" style="padding:2px 6px;border:none;"><hr style="margin:3px 0;border-color:#cfd8dc;"></td></tr>';
            }
            html += '<tr data-row-id="'+d.label_id+'"'+(isHiddenRow?' style="opacity:0.7;"':'')+'>';
            html += '<td style="padding:3px 6px;vertical-align:middle;">'+(typeBadges||'<span style="color:#ccc;font-size:10px;">—</span>')+'</td>';
            html += '<td style="padding:3px 6px;vertical-align:middle;"><strong style="font-size:12px;">'+escHtml(d.label_name||'')+'</strong>'+itBadge+repBadge+dlBadge+rngBadge+tolBadge+calcBadge+exclBadge+dimBadge2+qtyDimBadge2+pfxBadge2+sfxBadge2+hidBadge2+'</td>';
            html += '<td style="padding:3px 6px;text-align:center;white-space:nowrap;">';
            html += '<button class="btn btn-xs btn-info" onclick="viewLabelSubs('+realIdx+')" title="查看子標籤" style="margin-right:2px;"><i class="fa fa-list"></i></button>';
            if (_canEditDict('label')) html += '<button class="btn btn-xs btn-default" onclick="editDictEntry('+realIdx+')" title="編輯" style="margin-right:2px;"><i class="fa fa-pencil"></i></button>';
            if (_canEditDict('label')) html += '<button class="btn btn-xs btn-danger" onclick="deleteDictEntry(\''+d.label_id+'\')" title="刪除"><i class="fa fa-trash"></i></button>';
            html += '</td></tr>';
        });
    }
    $('#dict-table-body').html(html);

    // Pagination controls
    var pgEl = document.getElementById('dict-label-pagination');
    if (pgEl) {
        var pgHtml = '';
        if (pages > 1) {
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setLabelDictPage(1)"'+((_labelDictPage===1)?' disabled':'')+'>«</button>';
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setLabelDictPage('+(_labelDictPage-1)+')"'+((_labelDictPage===1)?' disabled':'')+'>‹</button>';
            var pstart = Math.max(1, _labelDictPage - 2);
            var pend   = Math.min(pages, pstart + 4);
            for (var p = pstart; p <= pend; p++) {
                pgHtml += '<button class="btn btn-xs '+(p===_labelDictPage?'btn-primary':'btn-default')+'" onclick="setLabelDictPage('+p+')">'+p+'</button>';
            }
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setLabelDictPage('+(_labelDictPage+1)+')"'+((_labelDictPage===pages)?' disabled':'')+'>›</button>';
            pgHtml += '<button class="btn btn-xs btn-default" onclick="setLabelDictPage('+pages+')"'+((_labelDictPage===pages)?' disabled':'')+'>»</button>';
        }
        pgEl.innerHTML = pgHtml;
    }

    // Drag-reorder for label dict (page-aware)
    var ltbody = document.getElementById('dict-table-body');
    if (ltbody && typeof Sortable !== 'undefined') {
        if (ltbody._sortable) ltbody._sortable.destroy();
        ltbody._sortable = Sortable.create(ltbody, {
            animation: 150, ghostClass: 'sortable-ghost', handle: 'tr',
            onEnd: function() { saveLabelDictOrder(); }
        });
    }
}

function saveLabelDictOrder() {
    if (_labelDictSearch) {
        showToast('篩選狀態下無法排序，請清除搜尋後再排序', 'warning');
        renderLabelDictPage();
        return;
    }
    var pageStart = (_labelDictPage - 1) * _labelDictPageSize;
    var domIds = [];
    document.querySelectorAll('#dict-table-body tr[data-row-id]').forEach(function(tr) {
        domIds.push(parseInt(tr.dataset.rowId, 10));
    });
    if (!domIds.length) return;
    var idMap = {};
    _labelDictAllData.forEach(function(d) { idMap[d.label_id] = d; });
    var newPageItems = domIds.map(function(id) { return idMap[id]; }).filter(Boolean);
    var newAll = _labelDictAllData.slice();
    for (var i = 0; i < newPageItems.length; i++) { newAll[pageStart + i] = newPageItems[i]; }
    _labelDictAllData = newAll;
    var allIds = _labelDictAllData.map(function(d) { return d.label_id; });
    api({ action:'manage_labels', op:'reorder', ids: allIds.join(',') }).done(function(r) {
        if (!r.success) showToast('排序儲存失敗', 'error');
    });
}

function clearDictForm() {
    $('#dict-edit-id').val('');
    $('#dict-f-name').val('');
    if (currentDictType==='process-type') {
        var ptIdEl = document.getElementById('dict-f-pt-id');
        if (ptIdEl) { ptIdEl.value=''; ptIdEl.readOnly=false; ptIdEl.style.background=''; ptIdEl.title='新增時可手動指定，留空則自動；編輯時不可更改'; }
    }
    if (currentDictType==='workpiece') {
        $('#dict-f-code').val('').prop('readonly',false).css('background','');
        $('#dict-f-show_vendor,#dict-f-show_part_no,#dict-f-show_machine,#dict-f-show_price').prop('checked',false);
    }
    if (currentDictType==='gear') {
        $('#dict-f-helix').prop('checked',false);
        $('#dict-gear-field-panel').hide();
        $('#dict-gear-field-tbody .gf-vis').prop('checked', true);
        $('#dict-gear-field-tbody .gf-req').prop('checked', false);
    }
    if (currentDictType==='label') {
        $('#dict-f-lbl-input').val('none').prop('disabled', false);
        $('#dict-f-lbl-rep').prop('checked',false);
        $('#dict-f-lbl-dl').prop('checked',false);
        $('#dict-f-lbl-range').prop('checked',false).prop('disabled',false);
        $('#dict-f-lbl-tol').prop('checked',false).prop('disabled',false);
        $('#dict-f-lbl-calc').prop('checked',false).prop('disabled',false);
        $('#dict-f-calc-panel').hide();
        $('#dict-f-lbl-has-sub').prop('checked',false);
        document.querySelectorAll('.lbl-type-cb').forEach(function(cb){ cb.checked = false; });
        closeSubSlideout();
        _pendingSubLabels = [];
        $('#dict-f-sub-id').val('');
        $('#dict-f-sub-name').val('');
        $('#dict-f-sub-input').val('none').prop('disabled', false);
        $('#dict-f-sub-rep').prop('checked',false);
        $('#dict-f-sub-dl').prop('checked',false);
        $('#dict-f-sub-range').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-tol').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-qty-dim').prop('checked',false).prop('disabled',false);
        $('#dict-f-sub-prefix').val('');
        $('#dict-f-sub-suffix').val('');
        $('#dict-sub-mode-hint').text('（儲存標籤後可直接管理；或先在下方設定後一起儲存）');
    }
    if (currentDictType==='workpiece-sub') {
        var wpSel = document.getElementById('dict-f-wp-type');
        if (wpSel) { wpSel.value=''; wpSel.disabled=false; wpSel.style.background=''; }
    }
    if (currentDictType==='maker-sub') {
        document.querySelectorAll('#dict-sub-main-checkboxes .sub-main-chk-label').forEach(function(el) {
            var cb = el.querySelector('input');
            cb.checked = false;
            el.style.cssText = 'background:#fff;color:;border-color:#dde;display:inline-flex;align-items:center;gap:4px;border:1px solid #dde;border-radius:14px;padding:3px 10px;cursor:pointer;font-weight:normal;font-size:12px;transition:all .15s;';
        });
        $('#dict-f-group').val('PROCESS').prop('disabled', false);
        var fn = document.getElementById('dict-f-name');
        if (fn) { fn.readOnly = false; fn.style.background = ''; fn.title = ''; }
        var sn = document.getElementById('sync-notice');
        if (sn) sn.remove();
    }
    if (currentDictType==='maker-proc-label') {
        document.querySelectorAll('#dict-proc-parent-checkboxes .dpl-parent-chk').forEach(function(lbl) {
            var cb = lbl.querySelector('input');
            if (cb) cb.checked = false;
            lbl.style.background = ''; lbl.style.color = ''; lbl.style.borderColor = '#dde'; lbl.style.display = '';
        });
        var ntw = document.getElementById('dict-f-ntype-wrap');
        var uw  = document.getElementById('dict-f-unit-wrap');
        if (ntw) ntw.style.display = 'none';
        if (uw)  uw.style.display  = 'none';
        dictProcLabelParentChange();
    }
    if (currentDictType==='maker-main') {
        var sel = document.getElementById('sub-selected-list');
        var pool = document.getElementById('sub-pool-list');
        if (sel) {
            // move all chips back to pool
            Array.from(sel.querySelectorAll('.sub-sel-chip')).forEach(function(chip) {
                sel.removeChild(chip);
                var np = document.createElement('span');
                np.className = 'sub-pool-chip sub-group-' + (chip.dataset.subGroup||'PROCESS');
                np.dataset.subId    = chip.dataset.subId;
                np.dataset.subName  = chip.dataset.subName;
                np.dataset.subGroup = chip.dataset.subGroup||'PROCESS';
                np.textContent      = chip.dataset.subName;
                np.onclick = function(){ moveToSelected(this); };
                if (pool) pool.appendChild(np);
            });
        }
    }
}

function toggleSubMainChk(el) {
    var cb = el.querySelector('input');
    cb.checked = !cb.checked;
    el.style.background  = cb.checked ? '#5856d6' : '#fff';
    el.style.color       = cb.checked ? '#fff' : '';
    el.style.borderColor = cb.checked ? '#5856d6' : '#dde';
}

function onSubGroupChange(val) { /* group field updated, no extra action needed */ }

function onWpSubTypeChange(typeCode) {
    // When type is changed in workpiece-sub form, reload the list filtered by type
    if (currentDictType === 'workpiece-sub' && typeCode) {
        api({ action:'manage_workpiece_sub_types', op:'list', type_code:typeCode }).done(function(r) {
            if (r.success) renderDictTable('workpiece-sub', r.data);
        });
    }
}

// ── Sub-pool (for maker-main binding) ──────────────────
var _subPoolData   = [];
var _subGroupFilter = '';
var _subKeyword    = '';

function loadSubPool(selectedIds) {
    api({ action:'manage_maker_sub_cats', op:'list' }).done(function(r) {
        if (!r.success) return;
        _subPoolData = r.data;
        renderSubPool(selectedIds);
        // Init SortableJS on selected list
        var selEl = document.getElementById('sub-selected-list');
        if (selEl && typeof Sortable !== 'undefined') {
            if (selEl._sortable) selEl._sortable.destroy();
            selEl._sortable = Sortable.create(selEl, {
                animation: 150,
                ghostClass: 'sortable-ghost',
                handle: '.sub-sel-chip'
            });
        }
    });
}

function renderSubPool(selectedIds) {
    var pool = document.getElementById('sub-pool-list');
    var sel  = document.getElementById('sub-selected-list');
    if (!pool || !sel) return;
    // Clear
    pool.innerHTML = ''; sel.innerHTML = '';
    var kw = (_subKeyword||'').toLowerCase();
    _subPoolData.forEach(function(d) {
        if (_subGroupFilter && d.sub_cat_group !== _subGroupFilter) return;
        if (kw && d.sub_cat_name.toLowerCase().indexOf(kw) < 0) return;
        var inSel = selectedIds.indexOf(parseInt(d.sub_cat_id)) >= 0;
        var chip = document.createElement('span');
        chip.className    = 'sub-' + (inSel ? 'sel' : 'pool') + '-chip sub-group-' + (d.sub_cat_group||'PROCESS');
        chip.dataset.subId    = d.sub_cat_id;
        chip.dataset.subName  = d.sub_cat_name;
        chip.dataset.subGroup = d.sub_cat_group||'PROCESS';
        chip.textContent  = d.sub_cat_name;
        if (inSel) {
            chip.onclick = function(){ moveToPool(this); };
            sel.appendChild(chip);
        } else {
            chip.onclick = function(){ moveToSelected(this); };
            pool.appendChild(chip);
        }
    });
}

function moveToSelected(chip) {
    var sel = document.getElementById('sub-selected-list');
    if (!sel) return;
    chip.className = 'sub-sel-chip sub-group-' + (chip.dataset.subGroup||'PROCESS');
    chip.onclick = function(){ moveToPool(this); };
    sel.appendChild(chip);
}
function moveToPool(chip) {
    var pool = document.getElementById('sub-pool-list');
    if (!pool) return;
    chip.className = 'sub-pool-chip sub-group-' + (chip.dataset.subGroup||'PROCESS');
    chip.onclick = function(){ moveToSelected(this); };
    pool.appendChild(chip);
}

function filterSubPool(kw) {
    _subKeyword = kw;
    var selIds = [];
    document.querySelectorAll('#sub-selected-list .sub-sel-chip').forEach(function(c){ selIds.push(parseInt(c.dataset.subId)); });
    renderSubPool(selIds); // renderSubPool 已正確將 selIds 放入 sub-selected-list，不需再次加入
}

function filterSubGroup(btn, grp) {
    _subGroupFilter = grp;
    document.querySelectorAll('.sub-grp-btn').forEach(function(b){ b.classList.remove('active'); });
    btn.classList.add('active');
    filterSubPool(_subKeyword);
}

// Reorder: maker-main drag
function saveDictOrder(type) {
    var ids = [];
    document.querySelectorAll('#dict-table-body tr').forEach(function(tr) {
        var id = tr.dataset.rowId;
        if (id) ids.push(id);
    });
    if (!ids.length) return;
    api({ action: dictConfig[type].action, op:'reorder', ids: ids.join(',') }).done(function(r) {
        if (!r.success) showToast('排序儲存失敗','error');
    });
}

function refreshDictListOnly(type) {
    var cfg = dictConfig[type];
    var listReq = (type === 'workpiece-sub')
        ? api({ action:'manage_workpiece_sub_types', op:'list', type_code:'__ALL__' })
        : api({ action: cfg.action, op: 'list' });
    listReq.done(function(r) {
        if (!r.success) return;
        var data = r.data || [];
        if (type === 'label') {
            renderLabelDictFull(data);
        } else if (type === 'maker-main' || type === 'maker-sub') {
            initPaginatedDict(type, data);
        } else {
            $('#dict-count-badge').text(data.length + ' 筆');
            renderDictTable(type, data);
        }
    });
}

function saveDictEntry() {
    if (!_canEditDict()) { showToast('無新增/修改權限','error'); return; }
    var cfg = dictConfig[currentDictType];
    var data = cfg.getData();
    if (!data) return;
    var _onSuccessCb = data._onSuccess || null;
    delete data._onSuccess;
    api(data).done(function(r) {
        if (r.success) {
            if (currentDictType === 'label' && !data.label_id && r.label_id) {
                // New label saved: switch to edit mode for sub-label management
                showToast('標籤儲存成功，可繼續管理子標籤', 'success');
                $('#dict-edit-id').val(r.label_id);
                _pendingSubLabels = [];
                $('#dict-sub-mode-hint').text('');
                // Open sub slideout after save
                $('#dict-f-lbl-has-sub').prop('checked', true);
                openSubSlideout(($('#dict-f-name').val()||'').trim());
                loadLabelSubs(r.label_id);
                refreshDictListOnly('label');
                // Refresh filter bar if the saved label's type_code includes the currently selected type
                (function(tc){ var st=_partsFilter.types.length===1?_partsFilter.types[0]:''; if(st&&tc&&tc.split(',').indexOf(st)>=0) buildLabelFilterRow(st); })(data.type_code||'');
            } else if (currentDictType === 'industry' && r.industry_id) {
                showToast('儲存成功', 'success');
                if (_onSuccessCb) _onSuccessCb(r);
                refreshDictListOnly('industry');
            } else {
                showToast('儲存成功', 'success');
                clearDictForm();
                loadDict(currentDictType, null);
                // If a label was updated, refresh filter bar and bust sub-label cache
                if (currentDictType === 'label') {
                    var _lid = data.label_id ? String(data.label_id) : '';
                    if (_lid) delete _subLabelCache[_lid];
                    (function(tc){ var st=_partsFilter.types.length===1?_partsFilter.types[0]:''; if(st&&tc&&tc.split(',').indexOf(st)>=0) buildLabelFilterRow(st); })(data.type_code||'');
                }
                if (currentDictType === 'maker-proc-label') initMakerProcLabelFilter(true);
            }
            industryCache = null;
            makerMainCats = [];
        } else {
            showToast(r.message || '儲存失敗','error');
        }
    }).fail(function(){ showToast('網路錯誤','error'); });
}

function deleteDictEntry(id) {
    if (!CAN_DELETE_ALL) { showToast('無刪除權限','error'); return; }
    var cfg = dictConfig[currentDictType];
    var isSub = (currentDictType === 'maker-sub');
    // Pre-check: confirm item is deletable before prompting user
    api({ action: cfg.action, op: 'check_delete', id: id }).done(function(cr) {
        if (!cr.can_delete) {
            showToast(cr.reason || '此項目已被使用，無法刪除', 'error');
            return;
        }
        var confirmMsg = isSub
            ? '確定停用此小類標籤？\n若有廠商綁定，資料將保留（軟刪除）。'
            : '確定刪除此項目？';
        if (!confirmDeleteY(confirmMsg)) return;
        api({ action: cfg.action, op: 'delete', id: id }).done(function(r) {
            if (r.success) {
                var msg = r.message || (isSub ? '已停用' : '已刪除');
                showToast(msg, 'success');
                loadDict(currentDictType, null);
                if (currentDictType === 'label') {
                    _subLabelCache = {};
                    var _st = _partsFilter.types.length===1?_partsFilter.types[0]:''; if(_st) buildLabelFilterRow(_st);
                }
                if (currentDictType === 'maker-proc-label') initMakerProcLabelFilter(true);
                industryCache = null;
                makerMainCats = [];
            } else {
                showToast(r.message||'操作失敗','error');
            }
        }).fail(function(){ showToast('網路錯誤','error'); });
    }).fail(function(){ showToast('網路錯誤','error'); });
}

