var _custBatchData = [];

function openCustBatchModal() {
    $('#custBatchModal').modal('show');
    // Load customer list for selection (current filter/search)
    var kw = document.getElementById('customers-search').value;
    api({ action:'list_customers', keywords_p:getCustKws(), page:1, lmt:999, filter_grades_p:_custFilter.grades.join(','), filter_industries_p:_custFilter.industries.join(',') }).done(function(r) {
        if (!r.success) return;
        _custBatchData = r.data || [];
        renderCustBatchList(_custBatchData);
    });
    // Load industry list for selects
    api({ action:'get_industry_list' }).done(function(r) {
        if (!r.success) return;
        ['cb-add-industry','cb-rm-industry'].forEach(function(id) {
            var sel = document.getElementById(id);
            if (!sel) return;
            sel.innerHTML = '<option value="">— 不變更 —</option>';
            r.data.forEach(function(i){ sel.appendChild(new Option(i.industry_name, i.industry_id)); });
        });
    });
}

function renderCustBatchList(data) {
    var html = '';
    data.forEach(function(c) {
        var grade = c.customer_grade ? '<span style="font-size:10px;color:#888;">['+c.customer_grade+']</span> ' : '';
        html += '<label style="display:flex;align-items:center;gap:6px;padding:3px 4px;cursor:pointer;border-radius:4px;" onmouseover="this.style.background=\'#f5f7ff\'" onmouseout="this.style.background=\'\'">'
            + '<input type="checkbox" class="cust-batch-cb" value="'+escAttr(c.customer_id)+'">'
            + grade + '<span style="font-size:12px;">'+escHtml(c.customer_id)+' — '+escHtml(c.customer)+'</span>'
            + '</label>';
    });
    var el = document.getElementById('cust-batch-list');
    if (el) el.innerHTML = html || '<p style="color:#aaa;font-size:12px;text-align:center;padding:10px;">無資料</p>';
}

function custBatchFilter(kw) {
    var lw = (kw||'').toLowerCase();
    var filtered = lw ? _custBatchData.filter(function(c){ return (c.customer||'').toLowerCase().includes(lw)||(c.customer_id||'').toLowerCase().includes(lw); }) : _custBatchData;
    renderCustBatchList(filtered);
}

function custBatchSelectAll(v) {
    document.querySelectorAll('#cust-batch-list .cust-batch-cb').forEach(function(cb){ cb.checked = v; });
}

function executeCustBatch() {
    var ids = [];
    document.querySelectorAll('#cust-batch-list .cust-batch-cb:checked').forEach(function(cb){ ids.push(cb.value); });
    if (!ids.length) { showToast('請先勾選客戶','error'); return; }
    var ops = [];
    var grade = document.getElementById('cb-grade').value;
    var day   = document.getElementById('cb-settle-day').value;
    var addInd= document.getElementById('cb-add-industry').value;
    var rmInd = document.getElementById('cb-rm-industry').value;
    if (grade) ops.push({field:'customer_grade', value:grade});
    if (day)   ops.push({field:'settlement_day', value:day});
    if (addInd) ops.push({field:'add_industry',  value:addInd});
    if (rmInd)  ops.push({field:'remove_industry',value:rmInd});
    if (!ops.length) { showToast('請設定至少一個變更項目','error'); return; }
    if (!confirm('確定對 '+ids.length+' 筆客戶套用 '+ops.length+' 項設定？')) return;
    var done = 0;
    ops.forEach(function(op) {
        api({ action:'batch_update_customers', customer_ids:JSON.stringify(ids), field:op.field, value:op.value }).done(function(r) {
            done++;
            if (!r.success) showToast(r.message,'error');
            if (done === ops.length) {
                showToast('批次設定完成','success');
                $('#custBatchModal').modal('hide');
                loadCustomers(customersCurrent);
            }
        });
    });
}

