function pbSyncSubChips() {
    var wrap = document.getElementById('pb-sub-chips');
    var hid  = document.getElementById('pb-subtype');
    if (!wrap || !hid) return;
    var sel = [];
    wrap.querySelectorAll('span').forEach(function(c){
        if (c.style.color === 'rgb(255, 255, 255)') sel.push(c.dataset.id);
    });
    hid.value = sel.join(',');
