function executePartsBatch() {
    var ids = [];
    document.querySelectorAll('#parts-batch-list .parts-batch-cb:checked').forEach(function(cb){ ids.push(cb.value); });
    if (!ids.length) { showToast('請先勾選料號','error'); return; }
    var ops = [];
    var typ = document.getElementById('pb-type').value;
    var sub = document.getElementById('pb-subtype').value;
    if (typ) ops.push({field:'Type', value:typ});
    if (sub) {
        // sub may be CSV for multi — split and push each
        sub.split(',').filter(Boolean).forEach(function(s){
            ops.push({field:'workpiece_sub_type_id', value:s});
        });
    }
    if (!ops.length) { showToast('請設定至少一個變更項目','error'); return; }
    if (!confirm('確定對 '+ids.length+' 筆料號套用設定？')) return;
    var done = 0;
    ops.forEach(function(op) {
        api({ action:'batch_update_parts', d_ids:JSON.stringify(ids), field:op.field, value:op.value }).done(function(r) {
            done++;
            if (!r.success) showToast(r.message,'error');
            if (done === ops.length) {
                showToast('批次設定完成','success');
                $('#partsBatchModal').modal('hide');
                loadParts(partsCurrent);
            }
        });
    });
}

