var _dupType = '';

function openDupCheck(type) {
    _dupType = type;
    var titles = {parts:'重複料號',customers:'重複/相似客戶',makers:'重複/相似廠商'};
    var subtitles = {
        parts:     '偵測：d_setting（D_Setting_Id 相同）　綁定檢查：訂單、生產批次、出貨單、報價單、退貨單、庫存',
        customers: '偵測：customer_list（名稱相同/相似）　綁定檢查：料號、訂單、出貨單、報價單、庫存',
        makers:    '偵測：maker_list（簡稱或全稱相同/相似）　綁定檢查：加工單'
    };
    document.getElementById('dup-modal-title').textContent = titles[type]||type;
    document.getElementById('dup-modal-subtitle').textContent = subtitles[type]||'';
    document.getElementById('dup-modal-body').innerHTML = '<div style="text-align:center;padding:40px;color:#aaa;"><i class="fa fa-spinner fa-spin fa-2x"></i><br>分析中…</div>';
    $('#dupCheckModal').modal('show');
    api({ action:'check_duplicates', type:type }).done(function(r) {
        if (!r.success) { document.getElementById('dup-modal-body').innerHTML = '<div style="padding:20px;color:red;">'+escHtml(r.message)+'</div>'; return; }
        if (type === 'parts')     renderDupParts(r.data);
        if (type === 'customers') renderDupCustomers(r.exact, r.similar);
        if (type === 'makers')    renderDupMakers(r.exact_name, r.exact_full, r.similar);
    }).fail(function(){ document.getElementById('dup-modal-body').innerHTML = '<div style="padding:20px;color:red;">網路錯誤</div>'; });
}

function renderDupParts(data) {
    var body = document.getElementById('dup-modal-body');
    if (!data.length) { body.innerHTML = '<div style="padding:30px;text-align:center;color:#1ABB9C;"><i class="fa fa-check-circle fa-2x"></i><br><strong>沒有發現重複料號</strong></div>'; return; }
    var html = '<div style="padding:12px 16px 4px;font-size:12px;color:#888;">共發現 <strong style="color:#e67e22;">'+data.length+'</strong> 組重複料號（料號相同、版次不同算重複）</div>';
    data.forEach(function(g) {
        html += '<div class="dup-group">';
        html += '<div class="dup-group-header"><i class="fa fa-exclamation-triangle"></i> 料號：<strong>'+escHtml(g.key)+'</strong> — 共 '+g.count+' 筆</div>';
        g.rows.forEach(function(r) {
            var hasRel = r.relations && r.relations.length > 0;
            html += '<div class="dup-row" style="flex-direction:column;align-items:stretch;gap:4px;">';
            html += '<div style="display:flex;flex-wrap:wrap;align-items:center;gap:6px;">';
            html += '<span style="font-family:Consolas;font-weight:700;color:var(--primary);min-width:110px;">'+escHtml(r.D_Setting_Id)+'</span>';
            html += '<span class="dup-field">版次：'+(r.Revision?escHtml(r.Revision):'<em style="color:#ccc">無</em>')+'</span>';
            html += '<span class="dup-field">規格：'+(r.Spec_No?escHtml(r.Spec_No):'<em style="color:#ccc">無</em>')+'</span>';
            html += '<span class="dup-field">發行日：'+(r.Issue_Date?escHtml(r.Issue_Date):'<em style="color:#ccc">無</em>')+'</span>';
            html += '<span class="dup-field">種類：'+escHtml(r.Type||'N')+'</span>';
            if (r.client_name) html += '<span class="dup-field">客戶：'+escHtml(r.client_name)+'</span>';
            if (r.Remark)      html += '<span class="dup-field" style="color:#aaa;">'+escHtml(r.Remark.substring(0,20))+'</span>';
            html += '<span style="color:#aaa;font-size:10px;">id='+r.d_id+'</span>';
            // 操作按鈕（A/CDRU）
            if (CAN_DELETE_ALL) {
                if (!hasRel) {
                    html += '<button class="btn btn-xs btn-danger" onclick="dupQuickDeletePart('+r.d_id+',\''+escAttr(r.D_Setting_Id)+'\',this)" title="刪除"><i class="fa fa-trash"></i> 刪除</button>';
                } else {
                    html += '<button class="btn btn-xs btn-warning" onclick="deletePart('+r.d_id+',\''+escAttr(r.D_Setting_Id)+'\')" title="有關聯資料，查看移轉選項"><i class="fa fa-exchange"></i> 移轉</button>';
                }
            }
            html += '</div>';
            // 綁定資料列
            if (hasRel) {
                html += '<div style="padding:3px 0 0 4px;font-size:11px;">';
                r.relations.forEach(function(rel){
                    html += '<span style="background:#fff3cd;color:#856404;border-radius:4px;padding:1px 7px;margin-right:4px;font-weight:600;"><i class="fa fa-link"></i> '+escHtml(rel)+'</span>';
                });
                html += '</div>';
            } else {
                html += '<div style="padding:2px 0 0 4px;font-size:11px;color:#aaa;"><i class="fa fa-check-circle" style="color:#1ABB9C;"></i> 無綁定資料</div>';
            }
            html += '</div>';
        });
        html += '</div>';
    });
    body.innerHTML = html;
}

// ── 自動除錯：快速刪除（無綁定資料者）─ Y 確認 + 只移除該 row ──────────
function _dupRemoveRow(btn) {
    var row   = btn.closest ? btn.closest('.dup-row')   : null;
    var group = row ? (row.closest('.dup-group') || row.closest('.dup-pair')) : null;
    if (row) row.remove();
    if (group) {
        var remaining = group.querySelectorAll('.dup-row').length;
        if (remaining <= 1) group.remove();
        // 若整個 modal body 已無 dup-group，顯示全清訊息
        var body = document.getElementById('dup-modal-body');
        if (body && !body.querySelector('.dup-group') && !body.querySelector('.dup-pair')) {
            body.innerHTML = '<div style="padding:30px;text-align:center;color:#1ABB9C;"><i class="fa fa-check-circle fa-2x"></i><br><strong>無重複項目</strong></div>';
        }
    }
}
function dupQuickDeletePart(d_id, name, btn) {
    if (!confirmDeleteY('確定刪除料號「'+name+'」（d_id='+d_id+'）？此操作不可復原。')) return;
    api({ action:'delete_part_by_id', d_id:d_id }).done(function(r) {
        if (r.success) { showToast('已刪除 '+name,'success'); _dupRemoveRow(btn); loadParts(partsCurrent); }
        else showToast(r.message,'error');
    });
}
function dupQuickDeleteCustomer(id, name, btn) {
    if (!confirmDeleteY('確定永久刪除客戶「'+name+'（'+id+'）」？此操作不可復原。')) return;
    api({ action:'dup_delete_customer', customer_id:id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _dupRemoveRow(btn); loadCustomers(customersCurrent); }
        else showToast(r.message,'error');
    });
}
function dupQuickDeleteMaker(id, name, btn) {
    if (!confirmDeleteY('確定永久刪除廠商「'+name+'（'+id+'）」？此操作不可復原。')) return;
    api({ action:'dup_delete_maker', maker_id_no:id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); _dupRemoveRow(btn); loadMakers(makersCurrent); }
        else showToast(r.message,'error');
    });
}

function dupDeletePart(d_id, name, relInfo) {
    var msg = '確定刪除 d_id='+d_id+' 的料號「'+name+'」？\n\n此操作不可復原，請確認此筆是舊版或重複版本。';
    if (relInfo) msg += '\n\n⚠ 關聯資料：' + relInfo;
    if (!confirmDeleteY(msg)) return;
    api({ action:'delete_part_by_id', d_id:d_id }).done(function(r) {
        if (r.success) {
            showToast('已刪除 d_id='+d_id, 'success');
            openDupCheck('parts');
            loadParts(partsCurrent);
        } else { alert('刪除失敗：'+r.message); }
    });
}

// ── 共用：建立錨點導覽列 ──────────────────────────────
function buildDupNav(sections) {
    var nav = '<div id="dup-nav" style="display:flex;flex-wrap:wrap;gap:6px;padding:10px 16px;border-bottom:1px solid #eee;background:#fafbfc;position:sticky;top:0;z-index:10;">';
    sections.forEach(function(s) {
        var c = s.color||'#555';
        nav += '<a href="#dup-sec-'+s.id+'" onclick="dupScrollTo(\'dup-sec-'+s.id+'\')" style="display:inline-block;padding:3px 12px;border-radius:12px;font-size:12px;font-weight:600;background:'+c+'22;color:'+c+';border:1px solid '+c+'44;text-decoration:none;white-space:nowrap;cursor:pointer;">'+escHtml(s.label)+' <span style="opacity:.7;">('+s.count+')</span></a>';
    });
    nav += '</div>';
    return nav;
}
function dupScrollTo(id) {
    var el = document.getElementById(id);
    if (el) el.scrollIntoView({behavior:'smooth', block:'start'});
}

// ── 共用：建立一筆詳細 row（客戶或廠商）────────────────
function buildDupEntityRow(item, type) {
    var html = '<div class="dup-row">';

    if (type === 'customer') {
        // 客戶資訊
        html += '<div style="flex:1;min-width:0;">';
        html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">';
        html += '<code style="background:#f0f4f8;padding:1px 6px;border-radius:3px;font-weight:700;color:var(--primary);">'+escHtml(item.customer_id)+'</code>';
        html += '<strong style="font-size:13px;">'+escHtml(item.customer)+'</strong>';
        if (item.is_inactive=='1') html += '<span class="badge-type badge-inactive" style="font-size:10px;">停用</span>';
        html += '</div>';
        var info = [];
        if (item.customer_tel) info.push('<i class="fa fa-phone"></i> '+escHtml(item.customer_tel));
        if (item.customer_address) info.push('<i class="fa fa-map-marker"></i> '+escHtml(item.customer_address.substring(0,30))+'…');
        if (info.length) html += '<div style="font-size:11px;color:#888;margin-bottom:3px;">'+info.join(' &nbsp; ')+'</div>';
        // 關聯資訊
        if (item.relations && item.relations.length) {
            html += '<div style="font-size:11px;">';
            item.relations.forEach(function(r) {
                html += '<span style="background:#fff3cd;color:#856404;border-radius:4px;padding:1px 7px;margin-right:4px;font-weight:600;"><i class="fa fa-link"></i> '+escHtml(r)+'</span>';
            });
            html += '</div>';
        } else {
            html += '<div style="font-size:11px;color:#aaa;"><i class="fa fa-check-circle" style="color:#1ABB9C;"></i> 無關聯資料</div>';
        }
        html += '</div>';
        // 操作
        html += '<div class="dup-del-btn" style="display:flex;flex-direction:column;gap:4px;align-items:flex-end;">';
        var hasRel = item.relations && item.relations.length > 0;
        if (CAN_SET_STATUS && item.is_inactive != '1') {
            html += '<button class="btn btn-xs btn-warning" onclick="dupDeactivateCustomer(\''+escAttr(item.customer_id)+'\',\''+escAttr(item.customer)+'\')"><i class="fa fa-pause"></i> 停用</button>';
        }
        if (CAN_DELETE_ALL) {
            if (!hasRel) {
                html += '<button class="btn btn-xs btn-danger" onclick="dupQuickDeleteCustomer(\''+escAttr(item.customer_id)+'\',\''+escAttr(item.customer)+'\',this)" title="刪除"><i class="fa fa-trash"></i> 刪除</button>';
            } else {
                html += '<button class="btn btn-xs btn-warning" onclick="deleteCustomer(\''+escAttr(item.customer_id)+'\',\''+escAttr(item.customer)+'\')" title="有關聯資料，查看移轉選項"><i class="fa fa-exchange"></i> 移轉</button>';
            }
        }
        html += '</div>';

    } else { // maker
        html += '<div style="flex:1;min-width:0;">';
        html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">';
        html += '<code style="background:#f0f4f8;padding:1px 6px;border-radius:3px;font-weight:700;color:var(--primary);">'+escHtml(item.maker_id_no)+'</code>';
        html += '<strong style="font-size:13px;">'+escHtml(item.maker_id)+'</strong>';
        if (item.maker_id_all) html += '<small style="color:#aaa;">（'+escHtml(item.maker_id_all)+'）</small>';
        if (item.status==='X') html += '<span class="badge-type badge-inactive" style="font-size:10px;">停用</span>';
        html += '</div>';
        var info = [];
        if (item.m_tel) info.push('<i class="fa fa-phone"></i> '+escHtml(item.m_tel));
        if (item.m_category) info.push('<i class="fa fa-sitemap"></i> '+escHtml(item.m_category));
        if (info.length) html += '<div style="font-size:11px;color:#888;margin-bottom:3px;">'+info.join(' &nbsp; ')+'</div>';
        if (item.relations && item.relations.length) {
            html += '<div style="font-size:11px;">';
            item.relations.forEach(function(r) {
                html += '<span style="background:#fff3cd;color:#856404;border-radius:4px;padding:1px 7px;margin-right:4px;font-weight:600;"><i class="fa fa-link"></i> '+escHtml(r)+'</span>';
            });
            html += '</div>';
        } else {
            html += '<div style="font-size:11px;color:#aaa;"><i class="fa fa-check-circle" style="color:#1ABB9C;"></i> 無關聯資料</div>';
        }
        html += '</div>';
        html += '<div class="dup-del-btn" style="display:flex;flex-direction:column;gap:4px;align-items:flex-end;">';
        var hasRel = item.relations && item.relations.length > 0;
        if (CAN_SET_STATUS && item.status !== 'X') {
            html += '<button class="btn btn-xs btn-warning" onclick="dupDeactivateMaker(\''+escAttr(item.maker_id_no)+'\',\''+escAttr(item.maker_id)+'\')"><i class="fa fa-pause"></i> 停用</button>';
        }
        if (CAN_DELETE_ALL) {
            if (!hasRel) {
                html += '<button class="btn btn-xs btn-danger" onclick="dupQuickDeleteMaker(\''+escAttr(item.maker_id_no)+'\',\''+escAttr(item.maker_id)+'\',this)" title="刪除"><i class="fa fa-trash"></i> 刪除</button>';
            } else {
                html += '<button class="btn btn-xs btn-warning" onclick="deleteMaker(\''+escAttr(item.maker_id_no)+'\',\''+escAttr(item.maker_id)+'\')" title="有關聯資料，查看移轉選項"><i class="fa fa-exchange"></i> 移轉</button>';
            }
        }
        html += '</div>';
    }

    html += '</div>';
    return html;
}

// ── 停用/刪除動作（需按確定才執行）─────────────────────
function dupDeactivateCustomer(id, name) {
    if (!confirm('確定將客戶「'+name+'（'+id+'）」設為停用？\n\n停用後不再列入有效客戶，資料保留。')) return;
    api({ action:'dup_deactivate_customer', customer_id:id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); loadCustomers(customersCurrent); openDupCheck('customers'); }
        else showToast('操作失敗：'+r.message,'error');
    });
}
function dupDeleteCustomer(id, name) {
    if (!confirmDeleteY('確定永久刪除客戶「'+name+'（'+id+'）」？\n\n此操作不可復原。確認此客戶無關聯訂單/料號後才可刪除。')) return;
    api({ action:'dup_delete_customer', customer_id:id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); openDupCheck('customers'); loadCustomers(customersCurrent); }
        else alert('操作失敗：'+r.message);
    });
}
function dupDeactivateMaker(id, name) {
    if (!confirm('確定將廠商「'+name+'（'+id+'）」設為停用？\n\n停用後不再列入有效廠商，歷史資料保留。')) return;
    api({ action:'dup_deactivate_maker', maker_id_no:id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); loadMakers(makersCurrent); openDupCheck('makers'); }
        else showToast('操作失敗：'+r.message,'error');
    });
}
function dupDeleteMaker(id, name) {
    if (!confirmDeleteY('確定永久刪除廠商「'+name+'（'+id+'）」？\n\n此操作不可復原。確認無加工單關聯後才可刪除。')) return;
    api({ action:'dup_delete_maker', maker_id_no:id }).done(function(r) {
        if (r.success) { showToast(r.message,'success'); openDupCheck('makers'); loadMakers(makersCurrent); }
        else alert('操作失敗：'+r.message);
    });
}

// ── 跳轉篩選 ──────────────────────────────────────────
function dupJumpToEdit(type, searchVal) {
    $('#dupCheckModal').modal('hide');
    setTimeout(function() {
        var tab    = type === 'customer' ? 'customers' : 'makers';
        var input  = type === 'customer' ? 'customers-search' : 'makers-search';
        var loadFn = type === 'customer' ? loadCustomers : loadMakers;
        var tabBtn = document.querySelector('.master-tab-btn[onclick*="\''+tab+'\'"]');
        if (!tabBtn) tabBtn = document.querySelectorAll('.master-tab-btn')[type==='customer'?1:2];
        if (tabBtn) switchTab(tab, tabBtn);
        document.getElementById(input).value = searchVal;
        loadFn(1);
    }, 350);
}

// ── 渲染：客戶 ────────────────────────────────────────
function renderDupCustomers(exact, similar) {
    var body = document.getElementById('dup-modal-body');
    var sections = [];
    var exactTotal = 0, simTotal = 0;
    (exact||[]).forEach(function(g){ exactTotal += g.rows.length; });
    if (exact && exact.length)   { sections.push({id:'exact',   label:'完全相同名稱', count:exactTotal, color:'#c0392b'}); }
    if (similar && similar.length){ sections.push({id:'similar', label:'疑似重複',    count:similar.length*2, color:'#e67e22'}); simTotal = similar.length; }
    if (!sections.length) {
        body.innerHTML = '<div style="padding:40px;text-align:center;color:#1ABB9C;"><i class="fa fa-check-circle fa-2x"></i><br><br><strong>沒有發現重複或相似客戶</strong><br><small style="color:#aaa;">（停用客戶已排除）</small></div>';
        return;
    }
    var html = buildDupNav(sections) + '<div style="padding:12px 16px;">';

    if (exact && exact.length) {
        html += '<div id="dup-sec-exact" style="margin-bottom:24px;">';
        html += '<div style="font-size:14px;font-weight:700;color:#c0392b;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid #fde8e8;"><i class="fa fa-clone"></i> 完全相同名稱 <span style="font-size:11px;background:#fde8e8;color:#c0392b;border-radius:8px;padding:1px 8px;margin-left:4px;">'+exact.length+' 組</span></div>';
        exact.forEach(function(g) {
            html += '<div class="dup-group">';
            html += '<div class="dup-group-header"><i class="fa fa-exclamation-circle"></i> 客戶名稱：<strong>'+escHtml(g.key)+'</strong> — 共 '+g.count+' 筆</div>';
            g.rows.forEach(function(r) { html += buildDupEntityRow(r, 'customer'); });
            html += '</div>';
        });
        html += '</div>';
    }
    if (similar && similar.length) {
        html += '<div id="dup-sec-similar" style="margin-bottom:24px;">';
        html += '<div style="font-size:14px;font-weight:700;color:#e67e22;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid #fde8c0;"><i class="fa fa-search-plus"></i> 疑似重複 <span style="font-size:11px;background:#fde8c0;color:#e67e22;border-radius:8px;padding:1px 8px;margin-left:4px;">'+simTotal+' 組</span></div>';
        similar.forEach(function(g) {
            html += '<div class="dup-group">';
            html += '<div class="dup-group-header" style="background:#fff3e0;color:#e65100;">疑似重複（名稱相似）</div>';
            html += buildDupEntityRow(g.a, 'customer');
            html += '<div style="text-align:center;color:#ccc;font-size:18px;padding:2px 0;">≈</div>';
            html += buildDupEntityRow(g.b, 'customer');
            html += '</div>';
        });
        html += '</div>';
    }
    html += '</div>';
    body.innerHTML = html;
}

// ── 渲染：廠商 ────────────────────────────────────────
function renderDupMakers(exactName, exactFull, similar) {
    var body = document.getElementById('dup-modal-body');
    var sections = [];
    var enTotal = 0, efTotal = 0, simTotal = 0;
    (exactName||[]).forEach(function(g){ enTotal += g.rows.length; });
    (exactFull||[]).forEach(function(g){ efTotal += g.rows.length; });
    if (exactName && exactName.length) sections.push({id:'exact_name', label:'相同簡稱', count:enTotal, color:'#c0392b'});
    if (exactFull && exactFull.length) sections.push({id:'exact_full', label:'相同全稱', count:efTotal, color:'#8e44ad'});
    if (similar && similar.length)     { simTotal = similar.length; sections.push({id:'similar', label:'疑似重複', count:simTotal*2, color:'#e67e22'}); }
    if (!sections.length) {
        body.innerHTML = '<div style="padding:40px;text-align:center;color:#1ABB9C;"><i class="fa fa-check-circle fa-2x"></i><br><br><strong>沒有發現重複或相似廠商</strong><br><small style="color:#aaa;">（停用廠商已排除）</small></div>';
        return;
    }
    var html = buildDupNav(sections) + '<div style="padding:12px 16px;">';

    function renderGroup(grpList, secId, label, color, borderColor) {
        if (!grpList || !grpList.length) return '';
        var h = '<div id="dup-sec-'+secId+'" style="margin-bottom:24px;">';
        h += '<div style="font-size:14px;font-weight:700;color:'+color+';margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid '+borderColor+';"><i class="fa fa-clone"></i> '+label+' <span style="font-size:11px;background:'+borderColor+';color:'+color+';border-radius:8px;padding:1px 8px;margin-left:4px;">'+grpList.length+' 組</span></div>';
        grpList.forEach(function(g) {
            h += '<div class="dup-group">';
            h += '<div class="dup-group-header"><i class="fa fa-exclamation-circle"></i> <strong>'+escHtml(g.key)+'</strong> — 共 '+g.count+' 筆</div>';
            g.rows.forEach(function(r) { h += buildDupEntityRow(r, 'maker'); });
            h += '</div>';
        });
        return h + '</div>';
    }

    html += renderGroup(exactName, 'exact_name', '相同簡稱', '#c0392b', '#fde8e8');
    html += renderGroup(exactFull, 'exact_full', '相同全稱', '#8e44ad', '#f3e5f5');

    if (similar && similar.length) {
        html += '<div id="dup-sec-similar" style="margin-bottom:24px;">';
        html += '<div style="font-size:14px;font-weight:700;color:#e67e22;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid #fde8c0;"><i class="fa fa-search-plus"></i> 疑似重複 <span style="font-size:11px;background:#fde8c0;color:#e67e22;border-radius:8px;padding:1px 8px;margin-left:4px;">'+simTotal+' 組</span></div>';
        similar.forEach(function(g) {
            html += '<div class="dup-group">';
            html += '<div class="dup-group-header" style="background:#fff3e0;color:#e65100;">疑似重複（名稱相似）</div>';
            html += buildDupEntityRow(g.a, 'maker');
            html += '<div style="text-align:center;color:#ccc;font-size:18px;padding:2px 0;">≈</div>';
            html += buildDupEntityRow(g.b, 'maker');
            html += '</div>';
        });
        html += '</div>';
    }
    html += '</div>';
    body.innerHTML = html;
}

// ═══════════════════════════════════════════════════════
// ─── Customer Batch ─────────────────────────────────────
// ═══════════════════════════════════════════════════════
var _custBatchData = [];

function openCustBatchModal() {
    $('#custBatchModal').modal('show');
    // Load customer list for selection (current filter/search)
    var kw = document.getElementById('customers-search').value;
    api({ action:'list_customers', keywords_p:getCustKws(), page:1, lmt:999, filter_grades_p:_custFilter.grades.join(','), filter_industries_p:_custFilter.industries.join(',') }).done(function(r) {
        if (!r.success) return;
        _custBatchData = r.data || [];
        renderCustBatchList(_custBatchData);
    });
    // Load industry list for selects
    api({ action:'get_industry_list' }).done(function(r) {
        if (!r.success) return;
        ['cb-add-industry','cb-rm-industry'].forEach(function(id) {
            var sel = document.getElementById(id);
            if (!sel) return;
            sel.innerHTML = '<option value="">— 不變更 —</option>';
            r.data.forEach(function(i){ sel.appendChild(new Option(i.industry_name, i.industry_id)); });
        });
    });
}

function renderCustBatchList(data) {
    var html = '';
    data.forEach(function(c) {
        var grade = c.customer_grade ? '<span style="font-size:10px;color:#888;">['+c.customer_grade+']</span> ' : '';
        html += '<label style="display:flex;align-items:center;gap:6px;padding:3px 4px;cursor:pointer;border-radius:4px;" onmouseover="this.style.background=\'#f5f7ff\'" onmouseout="this.style.background=\'\'">'
            + '<input type="checkbox" class="cust-batch-cb" value="'+escAttr(c.customer_id)+'">'
            + grade + '<span style="font-size:12px;">'+escHtml(c.customer_id)+' — '+escHtml(c.customer)+'</span>'
            + '</label>';
    });
    var el = document.getElementById('cust-batch-list');
    if (el) el.innerHTML = html || '<p style="color:#aaa;font-size:12px;text-align:center;padding:10px;">無資料</p>';
}

function custBatchFilter(kw) {
    var lw = (kw||'').toLowerCase();
    var filtered = lw ? _custBatchData.filter(function(c){ return (c.customer||'').toLowerCase().includes(lw)||(c.customer_id||'').toLowerCase().includes(lw); }) : _custBatchData;
    renderCustBatchList(filtered);
}

function custBatchSelectAll(v) {
    document.querySelectorAll('#cust-batch-list .cust-batch-cb').forEach(function(cb){ cb.checked = v; });
}

function executeCustBatch() {
    var ids = [];
    document.querySelectorAll('#cust-batch-list .cust-batch-cb:checked').forEach(function(cb){ ids.push(cb.value); });
    if (!ids.length) { showToast('請先勾選客戶','error'); return; }
    var ops = [];
    var grade = document.getElementById('cb-grade').value;
    var day   = document.getElementById('cb-settle-day').value;
    var addInd= document.getElementById('cb-add-industry').value;
    var rmInd = document.getElementById('cb-rm-industry').value;
    if (grade) ops.push({field:'customer_grade', value:grade});
    if (day)   ops.push({field:'settlement_day', value:day});
    if (addInd) ops.push({field:'add_industry',  value:addInd});
    if (rmInd)  ops.push({field:'remove_industry',value:rmInd});
    if (!ops.length) { showToast('請設定至少一個變更項目','error'); return; }
    if (!confirm('確定對 '+ids.length+' 筆客戶套用 '+ops.length+' 項設定？')) return;
    var done = 0;
    ops.forEach(function(op) {
        api({ action:'batch_update_customers', customer_ids:JSON.stringify(ids), field:op.field, value:op.value }).done(function(r) {
            done++;
            if (!r.success) showToast(r.message,'error');
            if (done === ops.length) {
                showToast('批次設定完成','success');
                $('#custBatchModal').modal('hide');
                loadCustomers(customersCurrent);
            }
        });
    });
}

// ─── Parts Batch ──────────────────────────────────────────
var _partsBatchData = [];

function openPartsBatchModal() {
    $('#partsBatchModal').modal('show');
    var kw = document.getElementById('parts-search').value;
    api({ action:'list_parts', keyword:kw, page:1, lmt:999, filter_type:_partsFilter.types.join(','), filter_gear:_partsFilter.gear, filter_sub:_partsFilter.sub }).done(function(r) {
        if (!r.success) return;
        _partsBatchData = r.data || [];
        renderPartsBatchList(_partsBatchData);
    });
    // Load workpiece types
    api({ action:'manage_workpiece_types', op:'list' }).done(function(r) {
        if (!r.success) return;
        var sel = document.getElementById('pb-type');
        if (!sel) return;
        sel.innerHTML = '<option value="">— 不變更 —</option>';
        r.data.forEach(function(t) {
            if (t.type_code !== 'G') sel.appendChild(new Option(t.type_code+' — '+t.type_name, t.type_code));
        });
    });
}

function renderPartsBatchList(data) {
    var html = '';
    data.forEach(function(r) {
        html += '<label style="display:flex;align-items:center;gap:6px;padding:3px 4px;cursor:pointer;border-radius:4px;" onmouseover="this.style.background=\'#f5f7ff\'" onmouseout="this.style.background=\'\'">'
            + '<input type="checkbox" class="parts-batch-cb" value="'+r.d_id+'">'
            + '<span style="font-size:11px;font-family:Consolas;color:var(--primary);">'+escHtml(r.D_Setting_Id)+'</span>'
            + '<span style="font-size:11px;color:#888;">'+escHtml(r.Spec_No||'')+'</span>'
            + '</label>';
    });
    var el = document.getElementById('parts-batch-list');
    if (el) el.innerHTML = html || '<p style="color:#aaa;font-size:12px;text-align:center;padding:10px;">無資料</p>';
}

function partsBatchFilter(kw) {
    var lw = (kw||'').toLowerCase();
    var filtered = lw ? _partsBatchData.filter(function(r){ return (r.D_Setting_Id||'').toLowerCase().includes(lw); }) : _partsBatchData;
    renderPartsBatchList(filtered);
}

function partsBatchSelectAll(v) {
    document.querySelectorAll('#parts-batch-list .parts-batch-cb').forEach(function(cb){ cb.checked = v; });
}

function pbLoadSubTypes(typeCode) {
    var row  = document.getElementById('pb-subtype-row');
    var wrap = document.getElementById('pb-sub-chips');
    var hid  = document.getElementById('pb-subtype');
    if (!row || !wrap) return;
    if (!typeCode) { row.style.display='none'; if (hid) hid.value=''; return; }
    api({ action:'manage_workpiece_sub_types', op:'list', type_code:typeCode }).done(function(r) {
        if (!r.success || !r.data.length) { row.style.display='none'; return; }
        wrap.innerHTML = '';
        r.data.forEach(function(s) {
            var chip = document.createElement('span');
            chip.dataset.id = s.sub_type_id;
            chip.style.cssText = 'display:inline-block;padding:2px 10px;border-radius:10px;font-size:12px;font-weight:600;cursor:pointer;transition:all .15s;background:#eef2ff;color:#5856d6;border:1.5px solid #5856d644;';
            chip.textContent = s.sub_type_name;
            chip.onclick = function(){
                var on = this.style.background.includes('5856d6') && this.style.color.includes('255, 255, 255');
                if (!on) {
                    this.style.background='#5856d6'; this.style.color='#fff'; this.style.borderColor='#5856d6';
                } else {
                    this.style.background='#eef2ff'; this.style.color='#5856d6'; this.style.borderColor='#5856d644';
                }
                pbSyncSubChips();
            };
            wrap.appendChild(chip);
        });
        pbSyncSubChips();
        row.style.display = 'flex';
    });
}

function pbSyncSubChips() {
    var wrap = document.getElementById('pb-sub-chips');
    var hid  = document.getElementById('pb-subtype');
    if (!wrap || !hid) return;
    var sel = [];
    wrap.querySelectorAll('span').forEach(function(c){
        if (c.style.color === 'rgb(255, 255, 255)') sel.push(c.dataset.id);
    });
    hid.value = sel.join(',');
}

function executePartsBatch() {
    var ids = [];
    document.querySelectorAll('#parts-batch-list .parts-batch-cb:checked').forEach(function(cb){ ids.push(cb.value); });
    if (!ids.length) { showToast('請先勾選料號','error'); return; }
    var ops = [];
    var typ = document.getElementById('pb-type').value;
    var sub = document.getElementById('pb-subtype').value;
    if (typ) ops.push({field:'Type', value:typ});
    if (sub) {
        // sub may be CSV for multi — split and push each
        sub.split(',').filter(Boolean).forEach(function(s){
            ops.push({field:'workpiece_sub_type_id', value:s});
        });
    }
    if (!ops.length) { showToast('請設定至少一個變更項目','error'); return; }
    if (!confirm('確定對 '+ids.length+' 筆料號套用設定？')) return;
    var done = 0;
    ops.forEach(function(op) {
        api({ action:'batch_update_parts', d_ids:JSON.stringify(ids), field:op.field, value:op.value }).done(function(r) {
            done++;
            if (!r.success) showToast(r.message,'error');
            if (done === ops.length) {
                showToast('批次設定完成','success');
                $('#partsBatchModal').modal('hide');
                loadParts(partsCurrent);
            }
        });
    });
}

// ─── Double-click search input to clear ───────────
function bindSearchClear(inputId, loadFn) {
    document.getElementById(inputId).addEventListener('dblclick', function() {
        if (this.value) {
            this.value = '';
            loadFn(1);
            this.blur();
        }
    });
}

// ═══════════════════════════════════════════════════
//  製程分頁
// ═══════════════════════════════════════════════════
var processLoaded    = false;
var _processAll      = [];   // all process_no rows
var _processTypes    = [];   // all process_type rows
var _procKwChips     = [];   // multi-keyword chips (action bar)
var _procQuickKws    = [];   // quick-filter chips (filter bar)
var _procTypeFilter  = 0;    // 0=all, else process_type_id
var _procSortMode    = 'id'; // 'id' | 'type-id'
var _procPageSize    = 10;   // items per page
var _procCurrentPage = 1;    // current page (1-based)
var _procFilteredList = [];  // current filtered+sorted list
var _noteCache       = {};   // note_id → {text, noteType, subjectType, subjectId}

function loadProcessList() {
    document.getElementById('process-list-wrap').innerHTML = '<div class="table-loading"><div class="spinner"></div> 載入中…</div>';
    $.post(SELF_URL, {action:'get_process_types'}, function(r) {
        if (r.success) { _processTypes = r.data; renderProcTypeFilterBtns(); }
    });
    $.post(SELF_URL, {action:'list_process'}, function(r) {
        if (r.success) {
            _processAll = r.data;
            processLoaded = true;
            filterProcessList();
        } else {
            document.getElementById('process-list-wrap').innerHTML = '<div style="padding:24px;color:#e74c3c;text-align:center;">載入失敗：' + escHtml(r.message||'') + '</div>';
        }
    });
}

// ── 大類篩選按鈕 ────────────────────────────────────────────────────
function renderProcTypeFilterBtns() {
    var grp = document.getElementById('proc-type-filter-group');
    if (!grp) return;
    var activeStyle = 'background:var(--accent);color:#fff;border-color:var(--accent);';
    var inactiveStyle = 'background:#dce8f5;color:#1a3a5c;border-color:#b0cce4;';
    var html = '<span class="filter-group-label">大類</span>';
    var a0 = (_procTypeFilter===0);
    html += '<span class="fc '+(a0?'active':'')+'" style="'+( a0?activeStyle:inactiveStyle)+'" data-ptid="0" onclick="setProcTypeFilter(0,this)">全部</span>';
    _processTypes.forEach(function(t) {
        var tid = parseInt(t.process_type_id);
        var act = (_procTypeFilter===tid);
        html += '<span class="fc '+(act?'active':'')+'" style="'+(act?activeStyle:inactiveStyle)+'" data-ptid="'+tid+'" onclick="setProcTypeFilter('+tid+',this)">'+escHtml(t.process_type||'(未命名)')+'</span>';
    });
    grp.innerHTML = html;
}

function setProcTypeFilter(tid, el) {
    _procTypeFilter = tid;
    document.querySelectorAll('#proc-type-filter-group .fc').forEach(function(b){
        b.classList.remove('active');
        b.style.background = '#dce8f5'; b.style.color = '#1a3a5c'; b.style.borderColor = '#b0cce4';
    });
    if (el) {
        el.classList.add('active');
        el.style.background = 'var(--accent)'; el.style.color = '#fff'; el.style.borderColor = 'var(--accent)';
    }
    filterProcessList();
    updateProcClearBtn();
}

function setProcSort(mode, btn) {
    _procSortMode = mode;
    document.querySelectorAll('#tab-process .btn-group .btn').forEach(function(b){ b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    filterProcessList();
}

function onProcKwKeydown(event) {
    var input = document.getElementById('proc-search-input');
    if (!input) return;
    if (event.key === 'Enter' || event.key === ',') {
        event.preventDefault();
        var val = input.value.trim();
        if (val && _procKwChips.indexOf(val) < 0) {
            _procKwChips.push(val);
            input.value = '';
            renderProcKwChips();
            filterProcessList();
            updateProcClearBtn();
        }
    } else if (event.key === 'Backspace' && !input.value && _procKwChips.length) {
        _procKwChips.pop();
        renderProcKwChips();
        filterProcessList();
        updateProcClearBtn();
    }
}

function renderProcKwChips() {
    var wrap = document.getElementById('proc-search-chips');
    if (!wrap) return;
    wrap.innerHTML = _procKwChips.map(function(kw, i) {
        return '<span class="kw-chip">' + escHtml(kw) + '<button onclick="removeProcKwChip(' + i + ')" style="background:none;border:none;cursor:pointer;padding:0 0 0 4px;color:#888;font-size:11px;">✕</button></span>';
    }).join('');
}

function removeProcKwChip(i) {
    _procKwChips.splice(i, 1);
    renderProcKwChips();
    filterProcessList();
    updateProcClearBtn();
}

function updateProcClearBtn() {
    var btn = document.getElementById('proc-clear-filter-btn');
    if (!btn) return;
    btn.style.display = (_procKwChips.length || _procQuickKws.length || _procTypeFilter !== 0) ? '' : 'none';
}

function onProcQuickKeydown(event) {
    var input = document.getElementById('proc-quick-input');
    if (!input) return;
    if (event.key === 'Enter' || event.key === ',') {
        event.preventDefault();
        var val = input.value.trim();
        if (val && _procQuickKws.indexOf(val) < 0) {
            _procQuickKws.push(val);
            input.value = '';
            renderProcQuickChips();
            filterProcessList();
            updateProcClearBtn();
        }
    } else if (event.key === 'Backspace' && !input.value && _procQuickKws.length) {
        _procQuickKws.pop();
        renderProcQuickChips();
        filterProcessList();
        updateProcClearBtn();
    }
}

function renderProcQuickChips() {
    var wrap = document.getElementById('proc-quick-chips');
    if (!wrap) return;
    wrap.innerHTML = _procQuickKws.map(function(kw, i) {
        return '<span style="'+_kwChipStyle+'">'
            + '<i class="fa fa-search" style="font-size:9px;opacity:.7;"></i> '
            + escHtml(kw)
            + ' <span style="cursor:pointer;margin-left:2px;opacity:.7;" onclick="removeProcQuickKw('+i+')">×</span>'
            + '</span>';
    }).join('');
}

function removeProcQuickKw(i) {
    _procQuickKws.splice(i, 1);
    renderProcQuickChips();
    filterProcessList();
    updateProcClearBtn();
}

function clearProcFilter() {
    _procKwChips = [];
    _procQuickKws = [];
    _procTypeFilter = 0;
    var input = document.getElementById('proc-search-input');
    if (input) input.value = '';
    var qi = document.getElementById('proc-quick-input');
    if (qi) qi.value = '';
    renderProcKwChips();
    renderProcQuickChips();
    renderProcTypeFilterBtns();
    filterProcessList();
    updateProcClearBtn();
}

function filterProcessList() {
    var kws = _procKwChips.concat(_procQuickKws).map(function(k){ return k.toLowerCase(); });
    var liveKw = ((document.getElementById('proc-search-input')||{}).value||'').trim().toLowerCase();
    if (liveKw) kws = kws.concat([liveKw]);
    var list = _processAll.filter(function(p) {
        if (_procTypeFilter !== 0) {
            var typeIds = (p.type_ids||'').split(',').map(function(x){ return parseInt(x)||0; }).filter(Boolean);
            if (typeIds.indexOf(_procTypeFilter) < 0) return false;
        }
        if (!kws.length) return true;
        var searchable = [
            String(p.ProcessNo||''),
            (p.ProcessName||'').toLowerCase(),
            (p.type_names||'').toLowerCase(),
            (p.oper_text||'').toLowerCase(),
            (p.design_text||'').toLowerCase()
        ].join(' ');
        return kws.every(function(kw){ return searchable.indexOf(kw) >= 0; });
    });
    if (_procSortMode === 'type-id') {
        list.sort(function(a, b) {
            var ta = (a.type_names||'').toLowerCase(), tb = (b.type_names||'').toLowerCase();
            if (ta < tb) return -1; if (ta > tb) return 1;
            return (a.ProcessNo||0) - (b.ProcessNo||0);
        });
    } else {
        list.sort(function(a, b){ return (a.ProcessNo||0) - (b.ProcessNo||0); });
    }
    _procFilteredList = list;
    _procCurrentPage = 1;
    renderProcessList(list);
}

function procGoPage(pg) {
    var pages = Math.ceil(_procFilteredList.length / _procPageSize) || 1;
    _procCurrentPage = Math.max(1, Math.min(pg, pages));
    renderProcessList(_procFilteredList);
}

function setProcPageSize(size) {
    _procPageSize = size;
    _procCurrentPage = 1;
    renderProcessList(_procFilteredList);
}

function _procPaginationHTML(total, pg, pageSize) {
    if (!total) return '';
    var pages = Math.ceil(total / pageSize);
    var from = (pg-1)*pageSize+1, to = Math.min(pg*pageSize, total);
    var btns = '';
    var start = Math.max(1, pg-3), end = Math.min(pages, pg+3);
    if (end-start < 6) start = Math.max(1, end-6);
    if (start > 1) btns += '<button onclick="procGoPage(1)">1</button>'+(start>2?'<button disabled>…</button>':'');
    for (var i=start; i<=end; i++) btns += '<button class="'+(i===pg?'active':'')+'" onclick="procGoPage('+i+')">'+i+'</button>';
    if (end < pages) btns += (end<pages-1?'<button disabled>…</button>':'')+'<button onclick="procGoPage('+pages+')">'+pages+'</button>';
    return '<div class="pagination-row">'
        + '<span class="pagination-info">共 <strong>'+total+'</strong> 筆，顯示 '+from+'–'+to
        + ' &nbsp; 每頁 <select onchange="setProcPageSize(parseInt(this.value))" style="font-size:11px;padding:1px 4px;border:1px solid #ddd;border-radius:3px;">'
        + '<option value="10"'+(pageSize===10?' selected':'')+'> 10 筆</option>'
        + '<option value="20"'+(pageSize===20?' selected':'')+'> 20 筆</option>'
        + '<option value="50"'+(pageSize===50?' selected':'')+'> 50 筆</option>'
        + '</select></span>'
        + '<div class="pg-btns">'
        + '<button '+(pg<=1?'disabled':'')+' onclick="procGoPage('+(pg-1)+')"><i class="fa fa-chevron-left"></i></button>'
        + btns
        + '<button '+(pg>=pages?'disabled':'')+' onclick="procGoPage('+(pg+1)+')"><i class="fa fa-chevron-right"></i></button>'
        + '</div></div>';
}

function _procNotesCellHtml(notes) {
    if (!notes || !notes.length) return '<span style="color:#ccc;font-size:11px;">—</span>';
    var html = '';
    notes.forEach(function(n, idx) {
        if (idx > 0) html += '<div style="border-top:1px solid #f0f0f0;margin-top:5px;padding-top:5px;"></div>';
        var txt = (n.text||'').trim();
        if (txt) {
            var disp = txt.length > 120 ? txt.substring(0, 120) + '…' : txt;
            html += '<div style="font-size:12px;color:#2c3e50;line-height:1.5;white-space:pre-wrap;word-break:break-word;">' + escHtml(disp) + '</div>';
        }
        if (n.imgs && n.imgs.length) {
            html += '<div style="display:flex;flex-wrap:wrap;gap:3px;margin-top:4px;">';
            var maxShow = Math.min(n.imgs.length, 4);
            for (var i = 0; i < maxShow; i++) {
                var url = NAS_URL_DIR + encodeURIComponent(n.imgs[i].f);
                html += '<a href="' + url + '" target="_blank" onclick="event.stopPropagation()"><img src="' + url + '" style="max-width:140px;max-height:80px;width:auto;height:auto;object-fit:contain;border-radius:3px;border:1px solid #ddd;vertical-align:middle;" onerror="this.parentNode.style.display=\'none\'"></a>';
            }
            if (n.imgs.length > 4) html += '<span style="font-size:10px;color:#aaa;align-self:center;">+' + (n.imgs.length - 4) + '</span>';
            html += '</div>';
        }
    });
    return html;
}

function renderProcessList(list) {
    if (!list) { filterProcessList(); return; }
    if (!list.length) {
        document.getElementById('process-list-wrap').innerHTML = '<div style="padding:32px;text-align:center;color:#aaa;"><i class="fa fa-inbox" style="font-size:28px;display:block;margin-bottom:8px;"></i>無符合條件的製程</div>';
        return;
    }
    var total = list.length;
    var pages = Math.ceil(total / _procPageSize) || 1;
    if (_procCurrentPage > pages) _procCurrentPage = pages;
    var startIdx = (_procCurrentPage - 1) * _procPageSize;
    var pageList = list.slice(startIdx, startIdx + _procPageSize);
    var pgHtml = _procPaginationHTML(total, _procCurrentPage, _procPageSize);
    var html = pgHtml + '<table class="table table-condensed table-hover" style="margin:0;table-layout:fixed;width:100%;">';
    html += '<colgroup>';
    html += '<col style="width:60px;">';
    html += '<col style="width:160px;">';
    html += '<col style="width:150px;">';
    html += '<col>';
    if (CAN_SEE_DESIGN) html += '<col>';
    html += '<col style="width:70px;">';
    html += '</colgroup>';
    html += '<thead><tr style="background:#f7f9fb;">';
    html += '<th style="width:60px;">製程ID</th>';
    html += '<th style="width:160px;">製程名稱</th>';
    html += '<th style="width:150px;">製程大類</th>';
    html += '<th><i class="fa fa-file-text-o" style="color:#27ae60;margin-right:3px;"></i>作業備註</th>';
    if (CAN_SEE_DESIGN) html += '<th><i class="fa fa-lock" style="color:#c0392b;margin-right:3px;"></i>技術備註</th>';
    html += '<th style="width:70px;text-align:right;">操作</th>';
    html += '</tr></thead><tbody>';
    pageList.forEach(function(p) {
        var pno = p.ProcessNo;
        var typeTags = '';
        if (p.type_names) {
            p.type_names.split(',').forEach(function(tname) {
                tname = tname.trim();
                if (tname) typeTags += '<span style="font-size:10px;background:#e8f5f2;color:#1ABB9C;border:1px solid #1ABB9C44;border-radius:10px;padding:1px 7px;margin-right:3px;margin-bottom:2px;display:inline-block;white-space:nowrap;">' + escHtml(tname) + '</span>';
            });
        }
        if (!typeTags) typeTags = '<span style="color:#ccc;font-size:11px;">—</span>';
        html += '<tr style="vertical-align:top;">';
        var excludeQcBadge = (p.is_exclude_qc=='1'||p.is_exclude_qc===1||p.is_exclude_qc==='1')
            ? '<span style="font-size:10px;background:#fff0f0;color:#c0392b;border:1px solid #f5c6cb;border-radius:10px;padding:1px 6px;margin-left:5px;white-space:nowrap;vertical-align:middle;"><i class="fa fa-ban" style="margin-right:2px;"></i>排除QC</span>'
            : '';
        html += '<td style="font-weight:600;color:#888;font-size:12px;white-space:nowrap;padding-top:10px;">' + pno + '</td>';
        html += '<td style="font-weight:600;color:#2c3e50;overflow:hidden;text-overflow:ellipsis;padding-top:10px;" title="' + escHtml(p.ProcessName||'') + '">' + escHtml(p.ProcessName||'（未命名）') + excludeQcBadge + '</td>';
        html += '<td style="overflow:hidden;padding-top:8px;">' + typeTags + '</td>';
        html += '<td style="padding:6px 8px;">' + _procNotesCellHtml(p.oper_notes) + '</td>';
        if (CAN_SEE_DESIGN) html += '<td style="padding:6px 8px;">' + _procNotesCellHtml(p.design_notes) + '</td>';
        html += '<td style="text-align:right;white-space:nowrap;padding-top:8px;">';
        if (CAN_PROC_EDIT) {
            html += '<button class="btn btn-xs btn-default" onclick="openProcessModal(' + pno + ')" title="編輯"><i class="fa fa-pencil"></i></button> ';
            html += '<button class="btn btn-xs btn-danger" onclick="_deleteProcConfirm(' + pno + ')" title="刪除"><i class="fa fa-trash"></i></button>';
        }
        html += '</td></tr>';
    });
    html += '</tbody></table>';
    document.getElementById('process-list-wrap').innerHTML = html;
}

// ── 製程 Modal ────────────────────────────────────────────────────────
var _pmPno = null;

function openProcessModal(pno) {
    _pmPno = pno;
    var isNew = (pno === null);
    document.getElementById('processModal-title').innerHTML = '<i class="fa fa-gears"></i> ' + (isNew ? '新增製程' : '編輯製程');
    document.getElementById('pm-is-new').value = isNew ? '1' : '0';
    var noInput = document.getElementById('pm-process-no');
    noInput.value = '';
    noInput.readOnly = !isNew;
    noInput.style.background = isNew ? '' : '#f5f5f5';
    document.getElementById('pm-process-no-hint').textContent = isNew ? '新增時可手動指定ID' : '（編輯時不可修改ID）';
    document.getElementById('pm-process-name').value = '';
    var exQcEl = document.getElementById('pm-exclude-qc');
    if (exQcEl) exQcEl.checked = false;
    document.getElementById('pm-type-picker').innerHTML = '<span style="color:#aaa;font-size:12px;"><i class="fa fa-spinner fa-spin"></i> 載入中…</span>';
    document.getElementById('pm-oper-notes-list').innerHTML = isNew ? '<div style="color:#bbb;font-size:12px;padding:4px 0;">儲存後才能新增備註</div>' : '<div style="color:#aaa;font-size:12px;padding:4px 0;">載入中…</div>';
    var dList = document.getElementById('pm-design-notes-list');
    if (dList) dList.innerHTML = isNew ? '<div style="color:#bbb;font-size:12px;padding:4px 0;">儲存後才能新增備註</div>' : '';
    var addOperBtn = document.getElementById('pm-add-oper-btn');
    var addDsnBtn  = document.getElementById('pm-add-design-btn');
    var copyBtn    = document.getElementById('pm-copy-notes-btn');
    var linkBtn    = document.getElementById('pm-set-link-btn');
    if (addOperBtn) addOperBtn.style.display = isNew ? 'none' : '';
    if (addDsnBtn)  addDsnBtn.style.display  = isNew ? 'none' : '';
    if (copyBtn)    copyBtn.style.display    = isNew ? 'none' : '';
    if (linkBtn)    linkBtn.style.display    = isNew ? 'none' : '';
    if (!isNew) {
        $.post(SELF_URL, {action:'get_process_detail', process_no:pno}, function(r) {
            if (r.success && r.data) {
                var d = r.data;
                document.getElementById('pm-process-no').value = d.ProcessNo;
                document.getElementById('pm-process-name').value = d.ProcessName||'';
                var exQcEl2 = document.getElementById('pm-exclude-qc');
                if (exQcEl2) exQcEl2.checked = (d.is_exclude_qc=='1'||d.is_exclude_qc===1);
                _renderProcTypePicker(d.type_ids||[]);
            }
        });
        loadProcModalNotes(pno);
    } else {
        _renderProcTypePicker([]);
    }
    $('#processModal').modal('show');
}

function _renderProcTypePicker(selectedIds) {
    var picker = document.getElementById('pm-type-picker');
    if (!picker) return;
    var ids = (selectedIds||[]).map(function(x){ return parseInt(x)||0; });
    var doRender = function(types) {
        var html = '';
        types.forEach(function(t) {
            var tid = parseInt(t.process_type_id);
            var checked = ids.indexOf(tid) >= 0;
            html += '<label class="proc-type-chip-label" style="display:inline-flex;align-items:center;gap:4px;background:' + (checked?'#1ABB9C':'#fff') + ';color:' + (checked?'#fff':'#555') + ';border:1px solid ' + (checked?'#1ABB9C':'#ddd') + ';border-radius:12px;padding:3px 10px;cursor:pointer;font-weight:normal;font-size:12px;margin-bottom:3px;transition:all .15s;" onclick="toggleProcTypeChip(this)">';
            html += '<input type="checkbox" value="' + tid + '" ' + (checked?'checked':'') + ' style="display:none;">' + escHtml(t.process_type||'(未命名)') + '</label>';
        });
        if (!html) html = '<span style="color:#aaa;font-size:12px;">（尚無製程大類，請先至字典設定）</span>';
        picker.innerHTML = html;
    };
    if (_processTypes.length) { doRender(_processTypes); return; }
    $.post(SELF_URL, {action:'get_process_types'}, function(r) {
        if (r.success) { _processTypes = r.data; }
        doRender(_processTypes);
    });
}

function toggleProcTypeChip(el) {
    var cb = el.querySelector('input');
    cb.checked = !cb.checked;
    el.style.background  = cb.checked ? '#1ABB9C' : '#fff';
    el.style.color       = cb.checked ? '#fff' : '#555';
    el.style.borderColor = cb.checked ? '#1ABB9C' : '#ddd';
}

function submitProcessModal() {
    var isNew = document.getElementById('pm-is-new').value === '1';
    var pno = parseInt(document.getElementById('pm-process-no').value)||0;
    var pname = (document.getElementById('pm-process-name').value||'').trim();
    if (!pname) { showToast('請填寫製程名稱','error'); return; }
    if (isNew && !pno) { showToast('請填寫製程ID','error'); return; }
    var typeIds = [];
    document.querySelectorAll('#pm-type-picker input[type=checkbox]:checked').forEach(function(cb){ typeIds.push(parseInt(cb.value)||0); });
    var exQcChk = document.getElementById('pm-exclude-qc');
    var isExcludeQc = (exQcChk && exQcChk.checked) ? 1 : 0;
    var btn = document.getElementById('processModal-save-btn');
    if (btn) btn.disabled = true;
    $.post(SELF_URL, {action:'save_process', is_new:isNew?1:0, process_no:pno, process_name:pname, type_ids:JSON.stringify(typeIds), is_exclude_qc:isExcludeQc}, function(r) {
        if (btn) btn.disabled = false;
        if (r.success) {
            showToast('製程已儲存');
            _pmPno = pno;
            if (isNew) {
                document.getElementById('pm-is-new').value = '0';
                var noInput = document.getElementById('pm-process-no');
                noInput.readOnly = true; noInput.style.background = '#f5f5f5';
                document.getElementById('pm-process-no-hint').textContent = '（編輯時不可修改ID）';
                document.getElementById('pm-oper-notes-list').innerHTML = '';
                var dList = document.getElementById('pm-design-notes-list');
                if (dList) dList.innerHTML = '';
                var addOperBtn = document.getElementById('pm-add-oper-btn');
                var addDsnBtn  = document.getElementById('pm-add-design-btn');
                var copyBtn2   = document.getElementById('pm-copy-notes-btn');
                var linkBtn2   = document.getElementById('pm-set-link-btn');
                if (addOperBtn) addOperBtn.style.display = '';
                if (addDsnBtn)  addDsnBtn.style.display  = '';
                if (copyBtn2)   copyBtn2.style.display   = '';
                if (linkBtn2)   linkBtn2.style.display   = '';
            }
            loadProcessList();
        } else {
            showToast(r.message||'儲存失敗','error');
        }
    });
}

function _deleteProcConfirm(pno) {
    var proc = _processAll.filter(function(p){ return p.ProcessNo == pno; })[0];
    var pname = proc ? (proc.ProcessName||'') : ('ID:'+pno);
    var ans = window.prompt('確定刪除製程「' + pname + '」（ID:' + pno + '）？\n請輸入大寫 Y 確認：');
    if (ans !== 'Y') { if (ans !== null) showToast('已取消'); return; }
    $.post(SELF_URL, {action:'delete_process', process_no:pno}, function(r) {
        if (r.success) { showToast('製程已刪除'); loadProcessList(); }
        else showToast(r.message||'刪除失敗','error');
    });
}

// ── 製程 Modal 備註 ────────────────────────────────────────────────────
function loadProcModalNotes(pno) {
    $.post(SELF_URL, {action:'get_process_notes', process_no:pno}, function(r) {
        if (!r.success) return;
        var oper       = (r.data||[]).filter(function(n){ return n.note_type==='oper'; });
        var design     = (r.data||[]).filter(function(n){ return n.note_type==='design'; });
        var linksAsDst = r.links_as_dst || [];
        var linksAsSrc = r.links_as_src || [];
        _renderProcModalNoteList('pm-oper-notes-list', oper, pno, 'oper', linksAsDst, linksAsSrc);
        if (CAN_SEE_DESIGN) _renderProcModalNoteList('pm-design-notes-list', design, pno, 'design', linksAsDst, linksAsSrc);
        // Show/hide add buttons: locked types can't add new notes
        var operLink   = linksAsDst.filter(function(l){ return l.link_type==='oper'; })[0];
        var designLink = linksAsDst.filter(function(l){ return l.link_type==='design'; })[0];
        var addOperBtn = document.getElementById('pm-add-oper-btn');
        var addDsnBtn  = document.getElementById('pm-add-design-btn');
        if (addOperBtn) addOperBtn.style.display = operLink   ? 'none' : '';
        if (addDsnBtn)  addDsnBtn.style.display  = designLink ? 'none' : '';
    });
}

function _renderProcModalNoteList(wrapId, notes, pno, noteType, linksAsDst, linksAsSrc) {
    var wrap = document.getElementById(wrapId);
    if (!wrap) return;
    var borderColor = noteType === 'design' ? '#f5c6cb' : '#c3e6cb';
    var dstLink = (linksAsDst||[]).filter(function(l){ return l.link_type===noteType; })[0];
    var srcLinks = (linksAsSrc||[]).filter(function(l){ return l.link_type===noteType; });
    var isLocked = !!dstLink;
    var html = '';

    // Source indicator: this process is a link source for this type
    if (srcLinks.length) {
        html += '<div style="background:#fffbea;border:1px solid #ffeaa7;border-radius:6px;padding:8px 10px;margin-bottom:8px;font-size:12px;">';
        html += '<i class="fa fa-link" style="color:#f39c12;"></i> <strong style="color:#b7860a;">此備註為連動來源</strong>，以下製程使用此備註：';
        srcLinks.forEach(function(l, i) {
            if (i > 0) html += '、';
            html += '<span style="color:#2980b9;">' + escHtml(String(l.dst_pno) + (l.dst_name ? ' ' + l.dst_name : '')) + '</span>';
        });
        html += '</div>';
    }

    // Lock indicator: this process is linked to a source
    if (dstLink) {
        html += '<div style="background:#f3f6fb;border:1px solid #bad3f8;border-radius:6px;padding:8px 10px;margin-bottom:8px;font-size:12px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px;">';
        html += '<span><i class="fa fa-lock" style="color:#3498db;"></i> 備註已連動自製程 <strong style="color:#2980b9;">' + dstLink.src_pno + (dstLink.src_name ? ' ' + escHtml(dstLink.src_name) : '') + '</strong>（唯讀）</span>';
        if (CAN_PROC_EDIT) {
            html += '<button class="btn btn-xs btn-default" onclick="confirmUnlink(' + dstLink.link_id + ',' + pno + ',\'' + noteType + '\')"><i class="fa fa-unlink"></i> 取消連動</button>';
        }
        html += '</div>';
    }

    if (!notes.length) {
        html += '<div style="color:#bbb;font-size:12px;padding:4px 0;">（尚無備註）</div>';
        wrap.innerHTML = html;
        return;
    }
    notes.forEach(function(n) {
        var imgNoteType = 'process_' + n.note_type;
        _noteCache[n.note_id] = { text: n.note_text||'', noteType: n.note_type, subjectType:'process', subjectId: pno, createdById: n.created_by_id };
        var canEditThis = !isLocked;
        html += '<div data-creator-id="' + (n.created_by_id||0) + '" style="background:#fff;border:1px solid ' + borderColor + ';border-radius:6px;padding:10px;margin-bottom:8px;' + (isLocked ? 'opacity:.88;' : '') + '">';
        html += '<div style="font-size:13px;line-height:1.7;white-space:pre-wrap;word-break:break-word;">' + escHtml(n.note_text||'') + '</div>';
        if (n.images && n.images.length) {
            html += '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;">';
            n.images.forEach(function(img) {
                var url = NAS_URL_DIR + encodeURIComponent(img.file_name||'');
                var delCall = 'deleteNoteImage(' + img.img_id + ',' + n.note_id + ',\'process\',' + pno + ')';
                html += _noteFileHtml(img, url, (CAN_EDIT_DESIGN && canEditThis), delCall);
            });
            html += '</div>';
        }
        html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px;font-size:10px;color:#aaa;">';
        var _pnDispTime   = (n.updated_by && n.updated_at) ? escHtml(n.updated_at) : escHtml(n.created_at||'');
        var _pnDispPerson = n.updated_by ? ('<span style="color:#e67e22;">✎ '+escHtml(n.updated_by)+'</span>') : (n.created_by ? escHtml(n.created_by) : '');
        html += '<span>' + _pnDispTime + (_pnDispPerson ? ' &nbsp; ' + _pnDispPerson : '') + '</span>';
        html += '<div style="display:flex;gap:4px;">';
        if (CAN_EDIT_DESIGN && canEditThis) {
            html += '<label class="btn btn-xs btn-default" style="margin:0;padding:1px 6px;cursor:pointer;" title="上傳附件"><i class="fa fa-paperclip"></i>';
            html += '<input type="file" accept="*" style="display:none;" onchange="uploadNoteImage(this,' + n.note_id + ',\'' + imgNoteType + '\',\'process\',' + pno + ')"></label>';
            html += '<button class="btn btn-xs btn-default" onclick="editNoteFromCache(' + n.note_id + ')"><i class="fa fa-pencil"></i></button>';
            html += '<button class="btn btn-xs btn-danger" onclick="_deleteProcNote(' + n.note_id + ',' + pno + ')"><i class="fa fa-trash"></i></button>';
        }
        html += '</div></div></div>';
    });
    wrap.innerHTML = html;
}

function openProcNoteModal(noteType) {
    if (!_pmPno) { showToast('請先儲存製程後再新增備註','error'); return; }
    openProcessNoteModal(_pmPno, noteType, 0, '');
}

function _deleteProcNote(noteId, pno) {
    if (!confirm('確定刪除此備註？圖片也會一併刪除。')) return;
    $.post(SELF_URL, {action:'delete_process_note', note_id:noteId}, function(r) {
        if (r.success) { showToast('已刪除'); loadProcModalNotes(pno); loadProcessList(); }
        else showToast(r.message||'刪除失敗','error');
    });
}

// ── 複製備註 ──────────────────────────────────────────────────────────
var _cnDstPno = null;

function openCopyNotesModal() {
    if (!_pmPno) { showToast('請先儲存製程','error'); return; }
    _cnDstPno = _pmPno;
    document.getElementById('cn-src-input').value = '';
    document.getElementById('cn-src-pno').value   = '';
    document.getElementById('cn-src-selected').textContent = '';
    document.getElementById('cn-src-dropdown').style.display = 'none';
    document.getElementById('cn-type-oper').checked = true;
    var cdEl = document.getElementById('cn-type-design');
    if (cdEl) cdEl.checked = false;
    document.querySelector('input[name="cn-mode"][value="append"]').checked = true;
    document.getElementById('cn-replace-confirm').style.display = 'none';
    document.getElementById('cn-ok-input').value = '';
    // 預設允許取代，A 權限直接允許；其他異步判斷
    _cnReplaceAllowed = IS_ADMIN_PERM;
    _updateCnReplaceUI();
    $('#copyNotesModal').modal('show');
    if (!IS_ADMIN_PERM) {
        $.post(SELF_URL, {action:'get_process_notes', process_no:_cnDstPno}, function(r) {
            if (r.success) {
                var notes = r.data || [];
                var hasOthers = notes.some(function(n){ return n.created_by_id && parseInt(n.created_by_id) !== CURRENT_USER_ID; });
                _cnReplaceAllowed = !hasOthers;
                _updateCnReplaceUI();
            }
        });
    }
}

function _updateCnReplaceUI() {
    var replaceRadio = document.querySelector('input[name="cn-mode"][value="replace"]');
    var hintEl = document.getElementById('cn-replace-restrict-hint');
    if (!replaceRadio) return;
    if (_cnReplaceAllowed) {
        replaceRadio.disabled = false;
        replaceRadio.parentNode.style.opacity = '';
        if (hintEl) hintEl.style.display = 'none';
    } else {
        replaceRadio.disabled = true;
        replaceRadio.parentNode.style.opacity = '0.45';
        // 若目前選的是 replace，切回 append
        if (replaceRadio.checked) {
            document.querySelector('input[name="cn-mode"][value="append"]').checked = true;
            document.getElementById('cn-replace-confirm').style.display = 'none';
            document.getElementById('cn-ok-input').value = '';
        }
        if (hintEl) hintEl.style.display = '';
    }
}

function cnSearchProcess(kw) {
    var dd = document.getElementById('cn-src-dropdown');
    kw = (kw||'').trim().toLowerCase();
    if (!kw) { dd.style.display='none'; return; }
    var list = _processAll.filter(function(p){
        return String(p.ProcessNo).indexOf(kw)>=0 || (p.ProcessName||'').toLowerCase().indexOf(kw)>=0;
    }).slice(0, 20);
    if (!list.length) { dd.innerHTML='<div style="padding:8px;font-size:12px;color:#aaa;">無符合製程</div>'; dd.style.display='block'; return; }
    var html = '';
    list.forEach(function(p) {
        var isSelf = (p.ProcessNo == _cnDstPno);
        html += '<div style="padding:6px 10px;cursor:'+(isSelf?'not-allowed':'pointer')+';font-size:12px;border-bottom:1px solid #f0f0f0;'+(isSelf?'color:#bbb;':'')+'" '+(isSelf?'':'onclick="cnSelectProcess('+p.ProcessNo+',\''+escAttr(p.ProcessName||'')+'\')"')+'>';
        html += '<strong>'+p.ProcessNo+'</strong> '+escHtml(p.ProcessName||'');
        if (isSelf) html += ' <span style="font-size:10px;color:#e74c3c;">（目標製程不可選）</span>';
        html += '</div>';
    });
    dd.innerHTML = html; dd.style.display='block';
}

function cnSelectProcess(pno, pname) {
    document.getElementById('cn-src-pno').value     = pno;
    document.getElementById('cn-src-input').value   = pno+' - '+pname;
    document.getElementById('cn-src-selected').textContent = '已選擇：'+pno+' - '+pname;
    document.getElementById('cn-src-dropdown').style.display = 'none';
}

$(document).on('change','input[name="cn-mode"]',function(){
    var show = this.value==='replace';
    document.getElementById('cn-replace-confirm').style.display = show?'':'none';
    if (!show) document.getElementById('cn-ok-input').value='';
});

function submitCopyNotes() {
    var srcPno = parseInt(document.getElementById('cn-src-pno').value)||0;
    if (!srcPno) { showToast('請選擇來源製程','error'); return; }
    var copyOper   = document.getElementById('cn-type-oper').checked;
    var cdEl = document.getElementById('cn-type-design');
    var copyDesign = CAN_SEE_DESIGN && cdEl && cdEl.checked;
    if (!copyOper && !copyDesign) { showToast('請選擇至少一種備註類型','error'); return; }
    var copyTypes = (copyOper && copyDesign) ? 'both' : (copyOper ? 'oper' : 'design');
    var mode = document.querySelector('input[name="cn-mode"]:checked').value;
    if (mode==='replace') {
        var okVal = (document.getElementById('cn-ok-input').value||'').trim();
        if (okVal !== 'OK') { showToast('請輸入大寫 OK 確認取代操作','error'); return; }
    }
    $.post(SELF_URL, {action:'copy_process_notes', src_pno:srcPno, dst_pno:_cnDstPno, copy_types:copyTypes, copy_mode:mode}, function(r) {
        if (r.success) {
            showToast('複製成功，共 '+r.copied+' 筆備註');
            $('#copyNotesModal').modal('hide');
            loadProcModalNotes(_cnDstPno);
            loadProcessList();
        } else { showToast(r.message||'複製失敗','error'); }
    });
}

// ── 設定備註連動 ──────────────────────────────────────────────────────
var _cnReplaceAllowed = true;
var _slDstPno = null;

function openSetLinkModal() {
    if (!_pmPno) { showToast('請先儲存製程','error'); return; }
    _slDstPno = _pmPno;
    document.getElementById('sl-src-input').value = '';
    document.getElementById('sl-src-pno').value   = '';
    document.getElementById('sl-src-selected').textContent = '';
    document.getElementById('sl-src-dropdown').style.display = 'none';
    document.getElementById('sl-link-type-oper').checked = true;
    var sdEl = document.getElementById('sl-link-type-design');
    if (sdEl) sdEl.checked = true;
    $('#setLinkModal').modal('show');
}

function slSearchProcess(kw) {
    var dd = document.getElementById('sl-src-dropdown');
    kw = (kw||'').trim().toLowerCase();
    if (!kw) { dd.style.display='none'; return; }
    var list = _processAll.filter(function(p){
        return String(p.ProcessNo).indexOf(kw)>=0 || (p.ProcessName||'').toLowerCase().indexOf(kw)>=0;
    }).slice(0, 20);
    if (!list.length) { dd.innerHTML='<div style="padding:8px;font-size:12px;color:#aaa;">無符合製程</div>'; dd.style.display='block'; return; }
    var html = '';
    list.forEach(function(p) {
        var isSelf = (p.ProcessNo == _slDstPno);
        html += '<div style="padding:6px 10px;cursor:'+(isSelf?'not-allowed':'pointer')+';font-size:12px;border-bottom:1px solid #f0f0f0;'+(isSelf?'color:#bbb;':'')+'" '+(isSelf?'':'onclick="slSelectProcess('+p.ProcessNo+',\''+escAttr(p.ProcessName||'')+'\')"')+'>';
        html += '<strong>'+p.ProcessNo+'</strong> '+escHtml(p.ProcessName||'');
        if (isSelf) html += ' <span style="font-size:10px;color:#e74c3c;">（目標製程不可選）</span>';
        html += '</div>';
    });
    dd.innerHTML = html; dd.style.display='block';
}

function slSelectProcess(pno, pname) {
    document.getElementById('sl-src-pno').value     = pno;
    document.getElementById('sl-src-input').value   = pno+' - '+pname;
    document.getElementById('sl-src-selected').textContent = '已選擇：'+pno+' - '+pname;
    document.getElementById('sl-src-dropdown').style.display = 'none';
}

function submitSetLink() {
    var srcPno = parseInt(document.getElementById('sl-src-pno').value)||0;
    if (!srcPno) { showToast('請選擇來源製程','error'); return; }
    var linkOper   = document.getElementById('sl-link-type-oper').checked;
    var sdEl = document.getElementById('sl-link-type-design');
    var linkDesign = CAN_SEE_DESIGN && sdEl && sdEl.checked;
    if (!linkOper && !linkDesign) { showToast('請選擇至少一種備註類型','error'); return; }
    var linkTypes = (linkOper && linkDesign) ? 'both' : (linkOper ? 'oper' : 'design');
    $.post(SELF_URL, {action:'manage_process_links', op:'set', src_pno:srcPno, dst_pno:_slDstPno, link_types:linkTypes}, function(r) {
        if (r.success) {
            showToast('連動設定成功');
            $('#setLinkModal').modal('hide');
            loadProcModalNotes(_slDstPno);
            loadProcessList();
        } else { showToast(r.message||'設定失敗','error'); }
    });
}

function confirmUnlink(linkId, dstPno, linkType) {
    var typeLabel = linkType==='design' ? '技術備註' : '作業備註';
    if (!confirm('確定取消「'+typeLabel+'」連動？\n取消後來源備註將複製到此製程，並開放編輯。')) return;
    $.post(SELF_URL, {action:'manage_process_links', op:'unlink', link_id:linkId, dst_pno:dstPno}, function(r) {
        if (r.success) { showToast('已取消連動，備註已複製至此製程'); loadProcModalNotes(dstPno); loadProcessList(); }
        else showToast(r.message||'操作失敗','error');
    });
}

// Close dropdowns on outside click
$(document).on('click', function(e) {
    if (!$(e.target).closest('#cn-src-input,#cn-src-dropdown').length) {
        var d=document.getElementById('cn-src-dropdown'); if(d) d.style.display='none';
    }
    if (!$(e.target).closest('#sl-src-input,#sl-src-dropdown').length) {
        var d=document.getElementById('sl-src-dropdown'); if(d) d.style.display='none';
    }
});

// ── 批次修改製程大類 ────────────────────────────────────────────────────
var _procBatchAll = [];

function openProcBatchTypeModal() {
    _procBatchAll = _processAll.slice().sort(function(a,b){ return (a.ProcessNo||0)-(b.ProcessNo||0); });
    _renderProcBatchList('');
    // populate type selects
    var addSel = document.getElementById('pbt-add-type');
    var rmSel  = document.getElementById('pbt-rm-type');
    [addSel, rmSel].forEach(function(sel) {
        if (!sel) return;
        sel.innerHTML = '<option value="">— 不修改 —</option>';
        _processTypes.forEach(function(t) { sel.innerHTML += '<option value="' + t.process_type_id + '">' + escHtml(t.process_type||'') + '</option>'; });
    });
    document.getElementById('proc-batch-search').value = '';
    $('#procBatchTypeModal').modal('show');
}

function _renderProcBatchList(kw) {
    var wrap = document.getElementById('proc-batch-list');
    if (!wrap) return;
    var kl = (kw||'').toLowerCase();
    var html = '';
    _procBatchAll.forEach(function(p) {
        if (kl && (p.ProcessName||'').toLowerCase().indexOf(kl) < 0 && String(p.ProcessNo).indexOf(kl) < 0) return;
        html += '<label style="display:flex;align-items:center;gap:6px;padding:3px 4px;cursor:pointer;border-radius:4px;font-weight:normal;font-size:12px;">';
        html += '<input type="checkbox" class="proc-batch-cb" value="' + p.ProcessNo + '"> ';
        html += '<span style="color:#888;min-width:30px;">' + p.ProcessNo + '</span> ' + escHtml(p.ProcessName||'');
        html += '</label>';
    });
    if (!html) html = '<div style="color:#aaa;padding:8px;font-size:12px;">無符合項目</div>';
    wrap.innerHTML = html;
}

function procBatchSelectAll(val) {
    document.querySelectorAll('#proc-batch-list .proc-batch-cb').forEach(function(cb){ cb.checked = val; });
}

function procBatchFilter(kw) { _renderProcBatchList(kw); }

function executeProcBatchType() {
    var selected = [];
    document.querySelectorAll('#proc-batch-list .proc-batch-cb:checked').forEach(function(cb){ selected.push(parseInt(cb.value)); });
    if (!selected.length) { showToast('請選擇至少一個製程','error'); return; }
    var addTid = parseInt(document.getElementById('pbt-add-type').value)||0;
    var rmTid  = parseInt(document.getElementById('pbt-rm-type').value)||0;
    if (!addTid && !rmTid) { showToast('請選擇要新增或移除的大類','error'); return; }
    $.post(SELF_URL, {action:'batch_process_type', process_nos:JSON.stringify(selected), add_type_id:addTid, rm_type_id:rmTid}, function(r) {
        if (r.success) {
            showToast('批次修改完成');
            $('#procBatchTypeModal').modal('hide');
            loadProcessList();
        } else {
            showToast(r.message||'操作失敗','error');
        }
    });
}

// ── 製程備註 Modal（共用） ─────────────────────────────────────────────
var _nm = { subjectType:'process', subjectId:0, noteType:'oper', noteId:0 };

function openProcessNoteModal(pno, noteType, noteId, noteText) {
    _nm = { subjectType:'process', subjectId:pno, noteType:noteType, noteId:noteId };
    var typeLabel = (noteType==='design') ? '技術備註' : '作業備註';
    var headerBg = (noteType==='design')
        ? 'linear-gradient(135deg,#7f1c1c,#c0392b)'
        : 'linear-gradient(135deg,#1a5c2c,#27ae60)';
    var hdr = document.getElementById('noteModal-header');
    if (hdr) hdr.style.background = headerBg;
    document.getElementById('noteModal-title').textContent = (noteId ? '編輯' : '新增') + typeLabel;
    document.getElementById('nm-note_text').value = noteText || '';
    document.getElementById('nm-images-section').style.display = 'none';
    var hint = document.getElementById('nm-new-note-hint');
    if (hint) hint.style.display = noteId ? 'none' : '';
    document.getElementById('noteModal').style.zIndex = '1060';
    $('#noteModal').modal('show');
    setTimeout(function() { $('.modal-backdrop').last().css('z-index', 1055); }, 50);
}

function editNoteFromCache(noteId) {
    var c = _noteCache[noteId];
    if (!c) { showToast('找不到備註資料','error'); return; }
    if (c.subjectType === 'process') {
        openProcessNoteModal(c.subjectId, c.noteType, noteId, c.text);
    } else {
        openDesignNoteModal(c.subjectType, c.subjectId, noteId, c.text);
    }
}

function submitNoteModal() {
    var text = document.getElementById('nm-note_text').value.trim();
    var btn = document.getElementById('noteModal-save-btn');
    btn.disabled = true;
    var postData = { note_text: text, note_id: _nm.noteId };
    if (_nm.subjectType === 'process') {
        postData.action = 'save_process_note';
        postData.process_no = _nm.subjectId;
        postData.note_type = _nm.noteType;
    } else {
        postData.action = 'save_design_note';
        postData.target_type = _nm.subjectType;
        postData.target_id = _nm.subjectId;
    }
    $.post(SELF_URL, postData, function(r) {
        btn.disabled = false;
        if (r.success) {
            $('#noteModal').modal('hide');
            showToast('備註已儲存');
            if (_nm.subjectType === 'process') {
                loadProcModalNotes(_nm.subjectId);
                loadProcessList();
            } else if (_nm.subjectType === 'part') {
                loadDesignNotes('part', _nm.subjectId);
            } else if (_nm.subjectType === 'customer') {
                loadDesignNotes('customer', _nm.subjectId);
            }
        } else {
            showToast(r.message||'儲存失敗', 'error');
        }
    });
}

function _noteFileHtml(img, url, canEdit, deleteCall) {
    var fname = img.file_name || '';
    var ext   = fname.split('.').pop().toLowerCase();
    var imgExts = ['jpg','jpeg','png','gif','webp','bmp','tif','tiff','svg'];
    var html = '<span style="position:relative;display:inline-block;">';
    if (imgExts.indexOf(ext) >= 0) {
        html += '<a href="'+url+'" target="_blank"><img src="'+url+'" style="max-width:220px;max-height:180px;width:auto;height:auto;object-fit:contain;border:1px solid #ddd;border-radius:4px;" onerror="this.parentNode.parentNode.style.display=\'none\'"></a>';
    } else if (ext === 'pdf') {
        html += '<a href="'+url+'" target="_blank" style="display:inline-flex;flex-direction:column;align-items:center;justify-content:center;width:90px;height:90px;border:1px solid #f5c6c6;border-radius:4px;background:#fff5f5;color:#c0392b;text-decoration:none;padding:4px;">';
        html += '<i class="fa fa-file-pdf-o" style="font-size:28px;"></i>';
        html += '<span style="font-size:9px;margin-top:5px;max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center;">'+escHtml(img.original_name||fname)+'</span>';
        html += '</a>';
    } else {
        var iconMap = { doc:'fa-file-word-o',docx:'fa-file-word-o',xls:'fa-file-excel-o',xlsx:'fa-file-excel-o',ppt:'fa-file-powerpoint-o',pptx:'fa-file-powerpoint-o',txt:'fa-file-text-o',csv:'fa-file-text-o',zip:'fa-file-zip-o',rar:'fa-file-zip-o','7z':'fa-file-zip-o',mp4:'fa-file-video-o',avi:'fa-file-video-o',mov:'fa-file-video-o',dwg:'fa-file-code-o',dxf:'fa-file-code-o',step:'fa-file-code-o',stp:'fa-file-code-o' };
        var icon = iconMap[ext] || 'fa-file-o';
        html += '<a href="'+url+'" target="_blank" style="display:inline-flex;flex-direction:column;align-items:center;justify-content:center;width:90px;height:90px;border:1px solid #ddd;border-radius:4px;background:#f8f9fa;color:#555;text-decoration:none;padding:4px;">';
        html += '<i class="fa '+icon+'" style="font-size:28px;"></i>';
        html += '<span style="font-size:9px;margin-top:5px;max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center;">'+escHtml(img.original_name||fname)+'</span>';
        html += '</a>';
    }
    if (canEdit) {
        html += '<button onclick="'+deleteCall+'" style="position:absolute;top:-6px;right:-6px;width:16px;height:16px;border-radius:50%;border:1px solid #ccc;background:#fff;cursor:pointer;padding:0;line-height:14px;text-align:center;font-size:9px;color:#e74c3c;" title="刪除附件">✕</button>';
    }
    html += '</span>';
    return html;
}

function uploadNoteImage(input, noteId, noteType, subjectType, subjectId) {
    var file = input.files[0];
    if (!file) return;
    var fd = new FormData();
    fd.append('action', 'upload_note_image');
    fd.append('note_id', noteId);
    fd.append('note_type', noteType);
    fd.append('image', file);
    $.ajax({ url:SELF_URL, type:'POST', data:fd, processData:false, contentType:false, success:function(r) {
        if (r.success) { showToast('附件已上傳'); _reloadNoteContext(subjectType, subjectId); }
        else showToast(r.message||'上傳失敗','error');
    }});
    input.value = '';
}

function deleteNoteImage(imgId, noteId, subjectType, subjectId) {
    if (!confirm('確定刪除此附件？')) return;
    $.post(SELF_URL, {action:'delete_note_image', img_id:imgId}, function(r) {
        if (r.success) { showToast('已刪除'); _reloadNoteContext(subjectType, subjectId); }
        else showToast(r.message||'刪除失敗','error');
    });
}

function _reloadNoteContext(subjectType, subjectId) {
    if (subjectType === 'process') loadProcModalNotes(subjectId);
    else if (subjectType === 'part') loadDesignNotes('part', subjectId);
    else if (subjectType === 'customer') loadDesignNotes('customer', subjectId);
}

// ═══════════════════════════════════════════════════
//  設計備註（料號 / 客戶）
// ═══════════════════════════════════════════════════
var _designTarget = { type:'', id:'' };

function openDesignNoteModal(targetType, targetId, noteId, noteText) {
    var tid = targetId || _designTarget.id;
    _nm = { subjectType: targetType, subjectId: tid, noteType: 'design', noteId: noteId||0 };
    var hdr = document.getElementById('noteModal-header');
    if (hdr) hdr.style.background = 'linear-gradient(135deg,#7f1c1c,#c0392b)';
    document.getElementById('noteModal-title').textContent = (noteId ? '編輯' : '新增') + '設計備註';
    document.getElementById('nm-note_text').value = noteText || '';
    document.getElementById('nm-images-section').style.display = 'none';
    var hint = document.getElementById('nm-new-note-hint');
    if (hint) hint.style.display = noteId ? 'none' : '';
    document.getElementById('noteModal').style.zIndex = '1060';
    $('#noteModal').modal('show');
    setTimeout(function() { $('.modal-backdrop').last().css('z-index', 1055); }, 50);
}

// ── 零件設計備註獨立跳窗 ──────────────────────────────────────────────
function openPartDesignModal(dId, partNo) {
    _designTarget = { type: 'part', id: partNo };
    document.getElementById('partDesignModal-title').innerHTML = '<i class="fa fa-file-text-o"></i> 設計備註 — ' + escHtml(partNo);
    var wrap = document.getElementById('partDesignModal-notes-list');
    if (wrap) wrap.innerHTML = '<div style="color:#aaa;font-size:12px;padding:8px 0;">載入中…</div>';
    $('#partDesignModal').one('shown.bs.modal', function() {
        loadDesignNotes('part', partNo);
    }).modal('show');
}

function loadDesignNotes(targetType, targetId) {
    if (!CAN_SEE_DESIGN) return;
    var wraps = [];
    if (targetType === 'part') {
        var w  = document.getElementById('part-design-notes-list');
        var w2 = document.getElementById('partDesignModal-notes-list');
        if (w  && $('#partModal').hasClass('in'))       wraps.push(w);
        if (w2 && $('#partDesignModal').hasClass('in')) wraps.push(w2);
        if (!wraps.length && w) wraps.push(w);
    } else {
        var w1 = document.getElementById('cust-design-notes-list');
        var w2 = document.getElementById('custDesignModal-notes-list');
        if (w1 && $('#customerModal').hasClass('in')) wraps.push(w1);
        if (w2 && $('#custDesignModal').hasClass('in')) wraps.push(w2);
        if (!wraps.length && w1) wraps.push(w1);
    }
    if (!wraps.length) return;
    wraps.forEach(function(w){ w.innerHTML='<div style="color:#aaa;font-size:12px;padding:4px 0;">載入中…</div>'; });
    $.post(SELF_URL, {action:'get_design_notes', target_type:targetType, target_id:targetId}, function(r) {
        wraps.forEach(function(w){
            if (!r.success) { w.innerHTML='<div style="color:#e74c3c;font-size:12px;">'+escHtml(r.message||'')+'</div>'; return; }
            renderDesignNotes(w, r.data, targetType, targetId);
        });
    });
}

// ── 客戶設計備註獨立跳窗 ──────────────────────────────────────────────
function openCustDesignModal(customerId, customerName) {
    _designTarget = { type: 'customer', id: customerId };
    document.getElementById('custDesignModal-title').innerHTML = '<i class="fa fa-file-text-o"></i> 設計備註 — ' + escHtml(customerName);
    var wrap = document.getElementById('custDesignModal-notes-list');
    if (wrap) wrap.innerHTML = '<div style="color:#aaa;font-size:12px;padding:8px 0;">載入中…</div>';
    $('#custDesignModal').one('shown.bs.modal', function() {
        loadDesignNotes('customer', customerId);
    }).modal('show');
}

function renderDesignNotes(wrap, notes, targetType, targetId) {
    if (!notes.length) {
        wrap.innerHTML = '<div style="color:#bbb;font-size:12px;padding:4px 0;">（尚無設計備註）</div>';
        return;
    }
    var html = '';
    notes.forEach(function(n) { html += renderDesignNoteItem(n, targetType, targetId); });
    wrap.innerHTML = html;
}

function renderDesignNoteItem(n, targetType, targetId) {
    var imgNoteType = targetType === 'part' ? 'part_design' : 'customer_design';
    // Safe single-quoted id for inline onclick (IDs should not contain single quotes)
    var tidSafe = String(targetId).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    // Cache note data for edit lookup
    _noteCache[n.note_id] = { text: n.note_text||'', noteType:'design', subjectType:targetType, subjectId:targetId };
    var html = '<div style="background:#fff;border:1px solid #f5c6cb;border-radius:6px;padding:10px;margin-bottom:8px;">';
    html += '<div style="font-size:13px;line-height:1.7;white-space:pre-wrap;word-break:break-word;">'+escHtml(n.note_text||'')+'</div>';
    if (n.images && n.images.length) {
        html += '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;">';
        n.images.forEach(function(img) {
            var url = NAS_URL_DIR+encodeURIComponent(img.file_name||'');
            var delCall = 'deleteNoteImage('+img.img_id+','+n.note_id+',\''+targetType+'\',\''+tidSafe+'\')';
            html += _noteFileHtml(img, url, CAN_EDIT_DESIGN, delCall);
        });
        html += '</div>';
    }
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px;font-size:10px;color:#aaa;">';
    var _dnDispTime   = (n.updated_by && n.updated_at) ? escHtml(n.updated_at) : escHtml(n.created_at||'');
    var _dnDispPerson = n.updated_by ? ('<span style="color:#e67e22;">✎ '+escHtml(n.updated_by)+'</span>') : (n.created_by ? escHtml(n.created_by) : '');
    html += '<span>' + _dnDispTime + (_dnDispPerson ? ' &nbsp; ' + _dnDispPerson : '') + '</span>';
    html += '<div style="display:flex;gap:4px;">';
    if (CAN_EDIT_DESIGN) {
        html += '<label class="btn btn-xs btn-default" style="margin:0;padding:1px 6px;cursor:pointer;" title="上傳附件">';
        html += '<i class="fa fa-paperclip"></i>';
        html += '<input type="file" accept="*" style="display:none;" onchange="uploadNoteImage(this,'+n.note_id+',\''+imgNoteType+'\',\''+targetType+'\',\''+tidSafe+'\')">';
        html += '</label>';
        html += '<button class="btn btn-xs btn-default" onclick="editNoteFromCache('+n.note_id+')"><i class="fa fa-pencil"></i></button>';
        html += '<button class="btn btn-xs btn-danger" onclick="confirmDeleteDesignNote('+n.note_id+',\''+targetType+'\',\''+tidSafe+'\')"><i class="fa fa-trash"></i></button>';
    }
    html += '</div></div></div>';
    return html;
}

function confirmDeleteDesignNote(noteId, targetType, targetId) {
    if (!confirm('確定刪除此設計備註？圖片也會一併刪除。')) return;
    $.post(SELF_URL, {action:'delete_design_note', note_id:noteId, target_type:targetType}, function(r) {
        if (r.success) { showToast('已刪除'); loadDesignNotes(targetType, targetId); }
        else showToast(r.message||'刪除失敗','error');
    });
}

// ─── Init ─────────────────────────────────────────
$(function() {
    reloadGearTypeOptions(function(){});  // pre-load gear types
    loadGearQualityRef(function(){});     // pre-load gear quality ref table

    // ── PAV 附件彈窗可拖移 ─────────────────────────────────────
    (function() {
        var _md = { on:false, sx:0, sy:0, ox:0, oy:0 };
        var $modal = $('#partAttachViewModal');

        $modal.on('shown.bs.modal', function() {
            var dlg = this.querySelector('.modal-dialog');
            if (!dlg) return;
            dlg.style.position = 'absolute';
            dlg.style.margin   = '0';
            if (!dlg.style.left) {
                var vw = window.innerWidth, vh = window.innerHeight;
                dlg.style.left = Math.max(0, (vw - dlg.offsetWidth)  / 2) + 'px';
                dlg.style.top  = Math.max(10, (vh - dlg.offsetHeight) / 4) + 'px';
            }
        });

        $modal.on('hide.bs.modal', function() {
            _md.on = false;
            var dlg = this.querySelector('.modal-dialog');
            if (dlg) { dlg.style.position=''; dlg.style.margin=''; dlg.style.left=''; dlg.style.top=''; }
        });

        var hdr = document.querySelector('#partAttachViewModal .modal-header');
        if (hdr) {
            hdr.addEventListener('mousedown', function(e) {
                if (e.button !== 0 || e.target.closest('button,a,input,label')) return;
                var dlg = document.querySelector('#partAttachViewModal .modal-dialog');
                if (!dlg) return;
                _md.on = true; _md.sx = e.clientX; _md.sy = e.clientY;
                _md.ox = dlg.offsetLeft; _md.oy = dlg.offsetTop;
                e.preventDefault();
            });
        }
        document.addEventListener('mousemove', function(e) {
            if (!_md.on) return;
            var dlg = document.querySelector('#partAttachViewModal .modal-dialog');
            if (!dlg) return;
            var nx = _md.ox + (e.clientX - _md.sx);
            var ny = _md.oy + (e.clientY - _md.sy);
            var vw = window.innerWidth, vh = window.innerHeight;
            nx = Math.max(0, Math.min(vw - dlg.offsetWidth,  nx));
            ny = Math.max(0, Math.min(vh - dlg.offsetHeight, ny));
            dlg.style.left = nx + 'px';
            dlg.style.top  = ny + 'px';
        });
        document.addEventListener('mouseup', function() { _md.on = false; });
    })();
    loadActiveCatsForUpload(function(){ initAttachFilterBar(); }); // pre-load attach cats + init filter
    // ── URL 參數自動搜尋（?search=<關鍵字>），設定後由 loadParts(1) 一併帶入 ──
    (function() {
        var autoSearch = new URLSearchParams(window.location.search).get('search') || '';
        if (autoSearch) {
            var el = document.getElementById('parts-search');
            if (el) el.value = autoSearch;
        }
    })();
    loadParts(1);
    initPartsFilterBar();
    initPartsCustomerFilters();
    initCustFilterBar();
    initMakersFilterBar();
    initMakerProcLabelFilter();
    // search debounce bind
    $('#parts-search').on('input', debounce(function(){ loadParts(1); }, 350));
    $('#customers-search').on('input', debounce(function(){ loadCustomers(1); }, 350));
    $('#makers-search').on('input', debounce(function(){ loadMakers(1); }, 350));
    // double-click to clear
    bindSearchClear('parts-search', loadParts);
    bindSearchClear('customers-search', loadCustomers);
    bindSearchClear('makers-search', loadMakers);
    // settlement day hint
    var sdEl = document.getElementById('cf-settlement_day');
    if (sdEl) sdEl.addEventListener('input', updateSettlementDayHint);

    // ── 料號 modal：ENTER 自動跳下一個輸入框（跳過舊料號區）──────────
    var _partEnterOrder = ['pf-D_Setting_Id','pf-Spec_No','pf-Revision','pf-Issue_Date','pf-customer-display','pf-Weight_Kg'];
    document.getElementById('partForm').addEventListener('keydown', function(e) {
        if (e.key !== 'Enter') return;
        var el = e.target;
        if (el.tagName === 'TEXTAREA' || el.tagName === 'SELECT') return;
        var idx = _partEnterOrder.indexOf(el.id);
        if (idx < 0) return;
        e.preventDefault();
        var next = idx < _partEnterOrder.length - 1 ? document.getElementById(_partEnterOrder[idx + 1]) : null;
        if (next) { next.focus(); if (next.select) next.select(); }
    });

    // ── 規格快速按鈕初始化 ───────────────────────────────────────────
    loadSpecBtns();

    // ── URL 參數自動開啟料號編輯（?open_part=<d_id 整數>）+篩選清單（?part_search=<料號>）───
    (function() {
        var params    = new URLSearchParams(window.location.search);
        var autoId    = parseInt(params.get('open_part') || '0', 10);
        var partSearch = (params.get('part_search') || '').trim();

        if (partSearch) {
            // 預填搜尋欄並載入篩選後的料號清單
            var searchEl = document.getElementById('parts-search');
            if (searchEl) {
                searchEl.value = partSearch;
                // 稍微延遲確保 loadParts 函式已就緒
                setTimeout(function() { if (typeof loadParts === 'function') loadParts(1); }, 100);
            }
        }

        // ?customer_search=<關鍵字>：切換到客戶分頁並篩選清單
        var custSearch = (params.get('customer_search') || '').trim();
        if (custSearch) {
            var custEl = document.getElementById('customers-search');
            if (custEl) custEl.value = custSearch;
            setTimeout(function() {
                if (typeof switchTab !== 'function') return;
                var btn = document.querySelector('.master-tab-btn[onclick*="customers"]');
                switchTab('customers', btn);   // switchTab 內會依搜尋欄內容 loadCustomers(1)
            }, 100);
        }

        if (autoId > 0) {
            // openPartModal 自有 AJAX，不需等 loadParts 完成
            setTimeout(function() { openPartModal(autoId); }, 500);
        }
    })();

    // ── 設計備註通知輪詢（頁面載入即開始）──
    startDnNotifPolling();
});

// ═══════════════════════════════════════════════════════════════════════════
// 規格快速按鈕
// ═══════════════════════════════════════════════════════════════════════════
var _SPEC_BTN_KEY = 'eg_spec_quick_btns';
var _specBtnLabels = [];

function loadSpecBtns() {
    // localStorage 僅當快取先畫一次；DB 才是正本（避免瀏覽器清資料後按鈕消失）
    try {
        var stored = localStorage.getItem(_SPEC_BTN_KEY);
        _specBtnLabels = stored ? JSON.parse(stored) : [];
    } catch(e) { _specBtnLabels = []; }
    while (_specBtnLabels.length < 12) _specBtnLabels.push('');
    renderSpecBtns();
    api({ action:'get_spec_quick_btns' }).done(function(r) {
        if (!r.success) return;
        if (r.data && r.data.length) {
            _specBtnLabels = r.data;
            while (_specBtnLabels.length < 12) _specBtnLabels.push('');
            try { localStorage.setItem(_SPEC_BTN_KEY, JSON.stringify(_specBtnLabels)); } catch(e) {}
            renderSpecBtns();
        } else if (_specBtnLabels.some(function(l){ return l && l.trim(); })) {
            // DB 尚無設定但本機有舊設定 → 一次性遷移上 DB
            api({ action:'save_spec_quick_btns', labels: JSON.stringify(_specBtnLabels) });
        }
    });
}

function renderSpecBtns() {
    var row = document.getElementById('spec-quick-btns-row');
    if (!row) return;
    row.innerHTML = '';
    var hasAny = false;
    _specBtnLabels.forEach(function(lbl) {
        if (!lbl || !lbl.trim()) return;
        hasAny = true;
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = lbl.trim();
        btn.style.cssText = 'padding:2px 10px;font-size:12px;background:#f0f4fb;border:1px solid #c5d5e8;color:#2c5f8a;border-radius:3px;cursor:pointer;white-space:nowrap;';
        btn.addEventListener('mouseover', function(){ this.style.background='#ddeeff'; });
        btn.addEventListener('mouseout',  function(){ this.style.background='#f0f4fb'; });
        btn.addEventListener('click', function(){ appendSpecQuickBtn(lbl.trim()); });
        row.appendChild(btn);
    });
    row.style.display = hasAny ? 'flex' : 'none';
}

function appendSpecQuickBtn(text) {
    var el = document.getElementById('pf-Spec_No');
    if (!el) return;
    el.value = el.value + text;
    el.focus();
}

function openSpecBtnSettings() {
    var grid = document.getElementById('spec-btn-settings-grid');
    if (!grid) return;
    var html = '';
    for (var i = 0; i < 12; i++) {
        html += '<div>';
        html += '<label style="font-size:11px;color:#888;margin-bottom:2px;">按鈕 '+(i+1)+'</label>';
        html += '<input type="text" class="form-control input-sm" id="spec-btn-inp-'+i+'" value="'+escHtml(_specBtnLabels[i]||'')+'" maxlength="12" placeholder="留空不顯示">';
        html += '</div>';
    }
    grid.innerHTML = html;
    $('#specBtnSettingsModal').modal('show');
}

function saveSpecBtnSettings() {
    var labels = [];
    for (var i = 0; i < 12; i++) {
        var el = document.getElementById('spec-btn-inp-'+i);
        labels.push(el ? el.value.trim() : '');
    }
    _specBtnLabels = labels;
    try { localStorage.setItem(_SPEC_BTN_KEY, JSON.stringify(labels)); } catch(e) {}
    api({ action:'save_spec_quick_btns', labels: JSON.stringify(labels) }).done(function(r) {
        if (!r.success) showToast('快速按鈕儲存到資料庫失敗：' + (r.message||''), 'error');
    }).fail(function() { showToast('快速按鈕儲存到資料庫失敗（連線錯誤）', 'error'); });
    renderSpecBtns();
    $('#specBtnSettingsModal').modal('hide');
}

// ═══════════════════════════════════════════════════════════════════════════
// 發行日回填（date input 只接受 YYYY-MM-DD，含時間的字串取前 10 碼）
// ═══════════════════════════════════════════════════════════════════════════
function setIssueDateFields(dateStr) {
    var v = String(dateStr || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) v = '';
    var el = document.getElementById('pf-Issue_Date');
    if (el) el.value = v;
}

// ═══════════════════════════════════════════════════════════════════════════
// 重量計算器
// ═══════════════════════════════════════════════════════════════════════════
var _wcPartDId   = 0;
var _wcCalcType  = 'shaft';
var _wcDensityG  = 0;
var _wcDensityId = 0;
var _wcSections  = [];
var _wcBindings  = {};
var _wcDensities = [];
var _wcPartLabels= {};
var _wcAllLabels = [];
var _wcSettingsOpen = false;
var _wcLastTotal_g = 0;
var _wcHoleInstances    = [];
var _wcInnerInstances   = [];
var _wcAllHoleBindings  = [];
var _wcAllInnerBindings = [];
var _wcAutoDensityId    = 0;
var _wcAutoDensityG     = 0;

var WCP_BINDING_DEFS = [
    {role:'material',   label:'材質',                 noSub:true},
    {role:'length',     label:'長度 (軸件用)'},
    {role:'thickness',  label:'厚度 (片狀用)'},
    // 孔 handled separately as dynamic list (_wcAllHoleBindings)
    {role:'keyway_w',   label:'鍵槽寬 (深自動=寬/2)', groupId:'keyway', groupLabel:'鍵', groupFirst:true},
    {role:'keyway_l',   label:'鍵槽長',               groupId:'keyway', groupLast:true}
];

var _origEnforceFocus = null;
function openWeightCalcPanel() {
    var d_id = parseInt(document.getElementById('pf-d_id').value || '0');
    if (!d_id) { showToast('請先儲存料號後再使用計算器', 'warning'); return; }
    _wcPartDId = d_id;
    document.getElementById('wcp-loading').style.display = '';
    document.getElementById('wcp-content').style.display = 'none';
    document.getElementById('weight-calc-panel').style.right = '0';
    document.getElementById('wcp-overlay').style.display = 'block';
    // Disable Bootstrap modal focus trap so panel inputs can receive keyboard events
    $(document).off('focusin.bs.modal');
    api({ action: 'get_part_for_weight_calc', d_id: d_id }).done(function(r) {
        document.getElementById('wcp-loading').style.display = 'none';
        document.getElementById('wcp-content').style.display = '';
        if (!r.success) { showToast(r.message || '讀取失敗', 'error'); return; }
        _wcBindings        = r.bindings        || {};
        _wcDensities       = r.densities       || [];
        _wcPartLabels      = r.part_labels     || {};
        _wcAllLabels       = r.all_labels      || [];
        _wcHoleInstances    = r.hole_instances   || [];
        _wcInnerInstances   = r.inner_instances  || [];
        _wcAllHoleBindings  = r.hole_bindings    || [];
        _wcAllInnerBindings = r.inner_bindings   || [];
        _wcAutoDensityId    = r.auto_density_id  || 0;
        _wcAutoDensityG     = r.auto_density_g   || 0;
        // 密度診斷：若未比對到，顯示此料號找到哪些子標籤
        if (!_wcAutoDensityId && r.mat_debug && r.mat_debug.length) {
            var dbgLines = (r.mat_debug || []).map(function(x){ return x.sub_name + (x.val ? '=' + x.val : ''); }).join(' / ');
            console.warn('[密度未比對] 材質標籤子標籤資料：', dbgLines);
            showToast('密度未自動比對。材質子標籤：' + dbgLines + '　→ 請在密度表設定對應關鍵字', 'warning');
        } else if (!_wcAutoDensityId && r.mat_debug && !r.mat_debug.length) {
            console.warn('[密度未比對] 材質標籤無子標籤資料（可能料號尚未設定材質）');
        }
        renderWcpDensityDropdown();
        renderWcpBindingRows();
        if (r.existing_calc) {
            wcRestoreFromJson(r.existing_calc);
        } else {
            _wcSections = [];
            if (_wcAutoDensityId) {
                _wcDensityId = _wcAutoDensityId;
                _wcDensityG  = _wcAutoDensityG;
                var aDSel = document.getElementById('wcp-density');
                if (aDSel) aDSel.value = String(_wcAutoDensityId);
                wcOnDensityChange();
            }
            wcPopulateFromLabels();
        }
        wcCalcTotal();
    }).fail(function() { showToast('讀取失敗', 'error'); });
}

function closeWeightCalcPanel() {
    document.getElementById('weight-calc-panel').style.right = '-520px';
    document.getElementById('wcp-overlay').style.display = 'none';
    // Re-enable focus trap for any active modal
    $('.modal.in').each(function() {
        var m = $(this).data('bs.modal') || $(this).data('modal');
        if (m && m.enforceFocus) m.enforceFocus();
    });
}

function toggleWcpSettings() {
    _wcSettingsOpen = !_wcSettingsOpen;
    document.getElementById('wcp-settings-body').style.display = _wcSettingsOpen ? '' : 'none';
    document.getElementById('wcp-settings-arrow').className = 'fa fa-chevron-' + (_wcSettingsOpen ? 'up' : 'down');
}

function renderWcpDensityDropdown() {
    var sel = document.getElementById('wcp-density');
    if (!sel) return;
    var html = '<option value="">-- 選擇材質密度 --</option>';
    (_wcDensities || []).forEach(function(d) {
        var sel_attr = (d.density_id == _wcDensityId) ? ' selected' : '';
        html += '<option value="' + d.density_id + '" data-g="' + d.density_g + '"' + sel_attr + '>' + escHtml(d.keyword) + ' (' + trimFloat(d.density_g) + ' g/cm³)</option>';
    });
    sel.innerHTML = html;
}

function wcOnDensityChange() {
    var sel = document.getElementById('wcp-density');
    if (!sel || !sel.value) { _wcDensityId = 0; _wcDensityG = 0; }
    else {
        _wcDensityId = parseInt(sel.value);
        var opt = sel.options[sel.selectedIndex];
        _wcDensityG = parseFloat(opt.getAttribute('data-g') || '0');
    }
    wcCalcTotal();
}

function wcLoadFromLabels() {
    // 重新套用 server 端比對的密度（依材質子標籤名稱對應 kpi_material_density.keyword）
    if (!_wcAutoDensityId) { showToast('找不到匹配的密度（請確認材質標籤子標籤名稱與密度對照表關鍵字是否一致）', 'warning'); return; }
    _wcDensityId = _wcAutoDensityId;
    _wcDensityG  = _wcAutoDensityG;
    var dSel = document.getElementById('wcp-density');
    if (dSel) dSel.value = String(_wcAutoDensityId);
    wcOnDensityChange();
    var matchedKw = '';
    (_wcDensities || []).forEach(function(d) { if (d.density_id == _wcAutoDensityId) matchedKw = d.keyword; });
    showToast('已帶入：' + matchedKw + ' (' + trimFloat(_wcAutoDensityG) + ' g/cm³)', 'success');
    wcCalcTotal();
}

function wcSetType(type) {
    _wcCalcType = type;
    wcCalcTotal();
}

function renderWcpBindingRows() {
    var wrap = document.getElementById('wcp-binding-rows');
    if (!wrap) return;
    var html = '';
    var SS = 'font-size:12px;height:26px;flex:1;min-width:100px;border:1px solid #ccc;border-radius:3px;padding:0 4px;';
    var lblOpts = '<option value="">-- 不綁定 --</option>';
    (_wcAllLabels || []).forEach(function(l) {
        lblOpts += '<option value="' + l.label_id + '">' + escHtml(l.label_name) + '</option>';
    });
    WCP_BINDING_DEFS.forEach(function(def) {
        if (def.groupId) {
            if (def.groupFirst) {
                var grpLid = (_wcBindings[def.role] || {}).label_id || '';
                // Also check other group roles for a lid (in case this first role isn't bound)
                WCP_BINDING_DEFS.forEach(function(d2) { if (d2.groupId===def.groupId && !grpLid) grpLid = (_wcBindings[d2.role]||{}).label_id||''; });
                var grpOpts = lblOpts.replace('value="' + grpLid + '"', 'value="' + grpLid + '" selected');
                html += '<div style="border:1px solid #dee2e6;border-radius:3px;padding:6px 8px;margin:3px 0;">';
                html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;">';
                html += '<span style="font-size:11px;font-weight:700;color:#555;min-width:30px;">' + escHtml(def.groupLabel) + '</span>';
                html += '<select id="grp-' + def.groupId + '-parent" onchange="wcOnGroupParentChange(\'' + def.groupId + '\')" style="' + SS + 'min-width:120px;"></select>';
                html += '</div>';
                html += '<div style="display:grid;grid-template-columns:auto 1fr;gap:3px 6px;align-items:center;padding-left:6px;">';
                // Will fill grp parent select after setting innerHTML
            }
            html += '<label style="font-size:12px;white-space:nowrap;">' + escHtml(def.label) + '</label>';
            html += '<select data-role="' + def.role + '" data-btype="sub" style="' + SS + '"><option value="0">-- 選子標籤 --</option></select>';
            if (def.groupLast) html += '</div></div>';
        } else if (def.noSub) {
            var bind0 = _wcBindings[def.role] || {};
            var opts0 = lblOpts.replace('value="' + (bind0.label_id||'') + '"', 'value="' + (bind0.label_id||'') + '" selected');
            html += '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;">';
            html += '<label style="font-size:12px;white-space:nowrap;min-width:80px;">' + escHtml(def.label) + '</label>';
            html += '<select data-role="' + def.role + '" data-btype="parent" onchange="wcOnBindingLabelChange(this)" style="' + SS + 'min-width:120px;">' + opts0 + '</select>';
            html += '</div>';
        } else {
            var bind1 = _wcBindings[def.role] || {};
            var opts1 = lblOpts.replace('value="' + (bind1.label_id||'') + '"', 'value="' + (bind1.label_id||'') + '" selected');
            html += '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;flex-wrap:wrap;">';
            html += '<label style="font-size:12px;white-space:nowrap;min-width:80px;">' + escHtml(def.label) + '</label>';
            html += '<select data-role="' + def.role + '" data-btype="parent" onchange="wcOnBindingLabelChange(this)" style="' + SS + 'min-width:120px;">' + opts1 + '</select>';
            html += '<select data-role="' + def.role + '" data-btype="sub" style="' + SS + 'display:none;"><option value="0">主標籤值</option></select>';
            html += '</div>';
        }
    });
    wrap.innerHTML = html;
    // Fill group parent selects with options (done post-innerHTML to avoid escaping issues)
    var groupsSeen = {};
    WCP_BINDING_DEFS.forEach(function(def) {
        if (def.groupId && def.groupFirst && !groupsSeen[def.groupId]) {
            groupsSeen[def.groupId] = true;
            var grpSel = document.getElementById('grp-' + def.groupId + '-parent');
            if (grpSel) {
                var grpLid2 = '';
                WCP_BINDING_DEFS.forEach(function(d2) { if (d2.groupId===def.groupId && !grpLid2) grpLid2 = String((_wcBindings[d2.role]||{}).label_id||''); });
                grpSel.innerHTML = lblOpts;
                if (grpLid2) {
                    for (var i=0;i<grpSel.options.length;i++) { if (grpSel.options[i].value===grpLid2){grpSel.options[i].selected=true;break;} }
                }
            }
        }
    });
    // Restore sub-labels for normal (non-grouped, non-material) roles
    WCP_BINDING_DEFS.forEach(function(def) {
        if (!def.groupId && !def.noSub) {
            var bind2 = _wcBindings[def.role] || {};
            if (bind2.label_id) {
                var pSel = wrap.querySelector('select[data-role="' + def.role + '"][data-btype="parent"]');
                if (pSel) wcLoadSubsForBinding(pSel, bind2.sub_id || 0);
            }
        }
    });
    // Restore sub-labels for groups
    var grpDone = {};
    WCP_BINDING_DEFS.forEach(function(def) {
        if (def.groupId && def.groupFirst && !grpDone[def.groupId]) {
            grpDone[def.groupId] = true;
            var preSids = {};
            WCP_BINDING_DEFS.forEach(function(d2) { if (d2.groupId===def.groupId) preSids[d2.role] = (_wcBindings[d2.role]||{}).sub_id||0; });
            var firstLid = '';
            WCP_BINDING_DEFS.forEach(function(d2) { if (d2.groupId===def.groupId && !firstLid) firstLid = String((_wcBindings[d2.role]||{}).label_id||''); });
            if (firstLid) wcOnGroupParentChange(def.groupId, preSids);
        }
    });
    // 孔：動態清單
    wcRenderHoleBindings();
    // 內孔：動態清單
    wcRenderInnerBindings();
}

function wcRenderHoleBindings() {
    var wrap = document.getElementById('wcp-binding-rows');
    if (!wrap) return;
    var existing = wrap.querySelector('#wcp-hole-section');
    if (existing) existing.remove();
    var lblOpts2 = '<option value="">-- 不綁定 --</option>';
    (_wcAllLabels || []).forEach(function(l) { lblOpts2 += '<option value="' + l.label_id + '">' + escHtml(l.label_name) + '</option>'; });
    var SS2 = 'font-size:12px;height:26px;flex:1;min-width:100px;border:1px solid #ccc;border-radius:3px;padding:0 4px;';
    var sec = document.createElement('div');
    sec.id = 'wcp-hole-section';
    sec.style.cssText = 'border:1px solid #dee2e6;border-radius:3px;padding:6px 8px;margin:3px 0;';
    var hdr = '<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;">';
    hdr += '<span style="font-size:11px;font-weight:700;color:#555;">孔（依序：數量、孔徑、深度）</span>';
    hdr += '<button type="button" onclick="wcAddHoleBinding()" style="margin-left:auto;padding:1px 8px;font-size:11px;background:#eef2ff;border:1px solid #5856d6;color:#5856d6;border-radius:3px;cursor:pointer;">+ 新增</button>';
    hdr += '</div>';
    hdr += '<div id="wcp-hole-rows"></div>';
    sec.innerHTML = hdr;
    wrap.appendChild(sec);
    // Render existing hole bindings
    (_wcAllHoleBindings || []).forEach(function(hb, idx) { wcRenderOneHoleRow(hb, idx); });
}

function wcRenderOneHoleRow(hb, idx) {
    var container = document.getElementById('wcp-hole-rows');
    if (!container) return;
    var lblOpts2 = '<option value="">-- 不綁定 --</option>';
    (_wcAllLabels || []).forEach(function(l) { lblOpts2 += '<option value="' + l.label_id + '"' + (l.label_id==hb.label_id?' selected':'') + '>' + escHtml(l.label_name) + '</option>'; });
    var SS2 = 'font-size:12px;height:26px;flex:1;min-width:100px;border:1px solid #ccc;border-radius:3px;padding:0 4px;';
    var row = document.createElement('div');
    row.className = 'wcp-hole-row';
    row.setAttribute('data-idx', idx);
    row.style.cssText = 'display:flex;align-items:center;gap:5px;margin-bottom:4px;flex-wrap:wrap;';
    row.innerHTML =
        '<select class="wcp-hole-parent" style="' + SS2 + 'min-width:120px;" onchange="wcOnHoleParentChange(this)">' + lblOpts2 + '</select>' +
        '<select class="wcp-hole-sub" style="' + SS2 + '"><option value="0">-- 選子標籤 --</option></select>' +
        '<button type="button" onclick="wcRemoveHoleRow(this)" style="background:none;border:none;color:#e74c3c;cursor:pointer;font-size:15px;line-height:1;">×</button>';
    container.appendChild(row);
    // Load sub-labels if already bound
    if (hb.label_id) {
        _ensureSubLabelCache(hb.label_id, function(subs) {
            var subSel = row.querySelector('.wcp-hole-sub');
            if (!subs || !subs.length) return;
            var html = '<option value="0">-- 選子標籤 --</option>';
            subs.forEach(function(s) { html += '<option value="' + s.sub_id + '"' + (s.sub_id==hb.sub_id?' selected':'') + '>' + escHtml(s.sub_name) + '</option>'; });
            subSel.innerHTML = html;
        });
    }
}

function wcAddHoleBinding() {
    _wcAllHoleBindings.push({label_id:0, sub_id:0, label_name:'', sub_name:''});
    wcRenderHoleBindings();
}

function wcOnHoleParentChange(parentSel) {
    var lid = parentSel.value;
    var row = parentSel.closest('.wcp-hole-row');
    if (!row) return;
    var subSel = row.querySelector('.wcp-hole-sub');
    if (!subSel) return;
    if (!lid) { subSel.innerHTML = '<option value="0">-- 選子標籤 --</option>'; return; }
    _ensureSubLabelCache(lid, function(subs) {
        var html = '<option value="0">-- 選子標籤 --</option>';
        (subs || []).forEach(function(s) { html += '<option value="' + s.sub_id + '">' + escHtml(s.sub_name) + '</option>'; });
        subSel.innerHTML = html;
    });
}

function wcRemoveHoleRow(btn) {
    var row = btn.closest('.wcp-hole-row');
    if (row) row.remove();
}

function wcRenderInnerBindings() {
    var wrap = document.getElementById('wcp-binding-rows');
    if (!wrap) return;
    var existing = wrap.querySelector('#wcp-inner-section');
    if (existing) existing.remove();
    var SS2 = 'font-size:12px;height:26px;flex:1;min-width:100px;border:1px solid #ccc;border-radius:3px;padding:0 4px;';
    var sec = document.createElement('div');
    sec.id = 'wcp-inner-section';
    sec.style.cssText = 'border:1px solid #dee2e6;border-radius:3px;padding:6px 8px;margin:3px 0;';
    sec.innerHTML =
        '<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;">' +
        '<span style="font-size:11px;font-weight:700;color:#555;">內孔（子標籤：圖面尺寸=孔徑、深度）</span>' +
        '<button type="button" onclick="wcAddInnerBinding()" style="margin-left:auto;padding:1px 8px;font-size:11px;background:#fdf0ee;border:1px solid #e74c3c;color:#e74c3c;border-radius:3px;cursor:pointer;">+ 新增</button>' +
        '</div><div id="wcp-inner-rows"></div>';
    wrap.appendChild(sec);
    (_wcAllInnerBindings || []).forEach(function(hb, idx) { wcRenderOneInnerRow(hb, idx); });
}

function wcRenderOneInnerRow(hb, idx) {
    var container = document.getElementById('wcp-inner-rows');
    if (!container) return;
    var lblOpts2 = '<option value="">-- 不綁定 --</option>';
    (_wcAllLabels || []).forEach(function(l) { lblOpts2 += '<option value="' + l.label_id + '"' + (l.label_id==hb.label_id?' selected':'') + '>' + escHtml(l.label_name) + '</option>'; });
    var SS2 = 'font-size:12px;height:26px;flex:1;min-width:100px;border:1px solid #ccc;border-radius:3px;padding:0 4px;';
    var row = document.createElement('div');
    row.className = 'wcp-inner-row';
    row.style.cssText = 'display:flex;align-items:center;gap:5px;margin-bottom:4px;flex-wrap:wrap;';
    // 內孔無子標籤，只選父標籤
    row.innerHTML =
        '<select class="wcp-inner-parent" style="' + SS2 + 'min-width:160px;">' + lblOpts2 + '</select>' +
        '<span style="font-size:11px;color:#888;">讀 draw_dim=孔徑, lathe_dim=深度</span>' +
        '<button type="button" onclick="this.closest(\'.wcp-inner-row\').remove()" style="background:none;border:none;color:#e74c3c;cursor:pointer;font-size:15px;line-height:1;">×</button>';
    container.appendChild(row);
}

function wcAddInnerBinding() {
    _wcAllInnerBindings.push({label_id:0, sub_id:0, label_name:'', sub_name:''});
    wcRenderInnerBindings();
}

function wcOnBindingLabelChange(parentSel) {
    wcLoadSubsForBinding(parentSel, 0);
}

function wcLoadSubsForBinding(parentSel, preSelectSid) {
    var lid = parentSel.value;
    var wrap = parentSel.closest('div');
    if (!wrap) return;
    var subSel = wrap.querySelector('select[data-btype="sub"]');
    if (!subSel) return;
    if (!lid) { subSel.style.display = 'none'; return; }
    _ensureSubLabelCache(lid, function(subs) {
        if (!subs || !subs.length) { subSel.style.display = 'none'; return; }
        var html = '<option value="0">主標籤值</option>';
        subs.forEach(function(s) {
            var sel = (s.sub_id == preSelectSid) ? ' selected' : '';
            html += '<option value="' + s.sub_id + '"' + sel + '>' + escHtml(s.sub_name) + '</option>';
        });
        subSel.innerHTML = html;
        subSel.style.display = '';
    });
}

// sub_id 9901 = 第1欄(input_value), 9902 = 第2欄(draw_dim)，用於無子標籤的標籤（如：鍵）
var WCP_SLOT_OPTS = [
    {v:'9901', label:'第1個數值（一般輸入欄）'},
    {v:'9902', label:'第2個數值（圖面尺寸欄）'}
];

function wcOnGroupParentChange(groupId, preSelectSids) {
    var grpSel = document.getElementById('grp-' + groupId + '-parent');
    if (!grpSel) return;
    var lid = grpSel.value;
    WCP_BINDING_DEFS.forEach(function(def) {
        if (def.groupId !== groupId) return;
        var subSel = document.querySelector('select[data-role="' + def.role + '"][data-btype="sub"]');
        if (!subSel) return;
        if (!lid) { subSel.innerHTML = '<option value="0">-- 選 --</option>'; return; }
        var preSid = preSelectSids ? (preSelectSids[def.role] || 0) : 0;
        _ensureSubLabelCache(lid, function(subs) {
            var html;
            if (subs && subs.length) {
                html = '<option value="0">-- 選子標籤 --</option>';
                subs.forEach(function(s) {
                    html += '<option value="' + s.sub_id + '"' + (s.sub_id==preSid?' selected':'') + '>' + escHtml(s.sub_name) + '</option>';
                });
            } else {
                // 無子標籤：顯示值1/值2選項
                html = '<option value="0">-- 選數值欄 --</option>';
                WCP_SLOT_OPTS.forEach(function(o) {
                    html += '<option value="' + o.v + '"' + (String(preSid)==o.v?' selected':'') + '>' + o.label + '</option>';
                });
            }
            subSel.innerHTML = html;
        });
    });
}

function saveWeightBindings() {
    var wrap = document.getElementById('wcp-binding-rows');
    if (!wrap) return;
    var roles = {};
    WCP_BINDING_DEFS.forEach(function(def) {
        if (def.groupId) {
            var grpSel = document.getElementById('grp-' + def.groupId + '-parent');
            var subSel = document.querySelector('select[data-role="' + def.role + '"][data-btype="sub"]');
            if (grpSel && grpSel.value) {
                roles[def.role] = { lid: grpSel.value, sid: subSel ? (subSel.value || '0') : '0' };
            }
        } else if (def.noSub) {
            var pSel0 = wrap.querySelector('select[data-role="' + def.role + '"][data-btype="parent"]');
            if (pSel0 && pSel0.value) roles[def.role] = { lid: pSel0.value, sid: '0' };
        } else {
            var pSel1 = wrap.querySelector('select[data-role="' + def.role + '"][data-btype="parent"]');
            var sSel1 = wrap.querySelector('select[data-role="' + def.role + '"][data-btype="sub"]');
            if (pSel1 && pSel1.value) {
                roles[def.role] = { lid: pSel1.value, sid: (sSel1 && sSel1.style.display !== 'none') ? (sSel1.value || '0') : '0' };
            }
        }
    });
    // 收集孔綁定
    var holeBindings = [];
    document.querySelectorAll('#wcp-hole-rows .wcp-hole-row').forEach(function(row) {
        var pSel = row.querySelector('.wcp-hole-parent');
        var sSel = row.querySelector('.wcp-hole-sub');
        if (pSel && pSel.value) {
            holeBindings.push({ lid: pSel.value, sid: sSel ? (sSel.value || '0') : '0' });
        }
    });
    // 收集內孔綁定（只有父標籤，無子標籤）
    var innerBindings = [];
    document.querySelectorAll('#wcp-inner-rows .wcp-inner-row').forEach(function(row) {
        var pSel = row.querySelector('.wcp-inner-parent');
        if (pSel && pSel.value) innerBindings.push({ lid: pSel.value, sid: '0' });
    });
    api({ action: 'save_weight_binding', bindings: JSON.stringify(roles), hole_bindings: JSON.stringify(holeBindings), inner_bindings: JSON.stringify(innerBindings) }).done(function(r) {
        if (r.success) {
            showToast('綁定設定已儲存', 'success');
            WCP_BINDING_DEFS.forEach(function(def) {
                if (roles[def.role]) {
                    _wcBindings[def.role] = { label_id: parseInt(roles[def.role].lid), sub_id: parseInt(roles[def.role].sid||'0'), label_name: '', sub_name: '' };
                } else delete _wcBindings[def.role];
            });
            _wcAllHoleBindings  = holeBindings.map(function(h)  { return {label_id:parseInt(h.lid), sub_id:parseInt(h.sid||'0'), label_name:'', sub_name:''}; });
            _wcAllInnerBindings = innerBindings.map(function(h) { return {label_id:parseInt(h.lid), sub_id:parseInt(h.sid||'0'), label_name:'', sub_name:''}; });
        } else showToast(r.message || '儲存失敗', 'error');
    });
}

function wcBoundKey(role) {
    var b = _wcBindings[role]; if (!b) return null;
    return String(b.label_id) + (b.sub_id > 0 ? ':' + b.sub_id : '');
}
function wcGetBoundValues(role) {
    var k = wcBoundKey(role); return k ? (_wcPartLabels[k] || []) : [];
}
function wcPopulateFromLabels() {
    var bindings = _wcBindings;
    var lenKey   = (_wcCalcType === 'disc') ? 'thickness' : 'length';
    var odInst   = wcGetBoundValues('od');
    var idInst   = wcGetBoundValues('id');
    var lenInst  = wcGetBoundValues(lenKey);
    var kwWInst  = wcGetBoundValues('keyway_w');
    var kwLInst  = wcGetBoundValues('keyway_l');

    // 外型段
    if (odInst.length > 0) {
        odInst.forEach(function(od, i) {
            var li = lenInst[i] || null;
            _wcSections.push({ type:'outer', d: od.value!==null?od.value:'', l: li&&li.value!==null?li.value:'',
                from_d: (bindings['od']||{}).label_name||'', from_l: li?(bindings[lenKey]||{}).label_name||'':'',
                from_draw_d: od.from_draw, from_draw_l: li?li.from_draw:false });
        });
    } else {
        _wcSections.push({ type:'outer', d:'', l:'', from_d:'', from_l:'', from_draw_d:false, from_draw_l:false });
    }
    // 內徑段
    if (idInst.length > 0) {
        idInst.forEach(function(id, i) {
            var li = lenInst[i] || null;
            _wcSections.push({ type:'inner', d: id.value!==null?id.value:'', l: li&&li.value!==null?li.value:'',
                from_d: (bindings['id']||{}).label_name||'', from_l: li?(bindings[lenKey]||{}).label_name||'':'',
                from_draw_d: id.from_draw, from_draw_l: li?li.from_draw:false });
        });
    }
    // 孔群（子標籤三欄依序：數量、孔徑、深度）
    (_wcHoleInstances || []).forEach(function(h) {
        if (h.dia === null && h.depth === null) return;
        _wcSections.push({ type:'hole',
            d:   h.dia   !== null ? h.dia   : '',
            l:   h.depth !== null ? h.depth : '',
            qty: (h.qty !== null && h.qty !== 1) ? h.qty : '1',
            from_d: '孔標籤', from_draw_d: true });
    });
    // 內孔（子標籤：draw_dim=圖面尺寸/孔徑、lathe_dim=深度）
    (_wcInnerInstances || []).forEach(function(h) {
        if (h.dia === null) return;
        _wcSections.push({ type:'inner',
            d: h.dia   !== null ? h.dia   : '',
            l: h.depth !== null ? h.depth : '',
            from_d: '內孔標籤', from_l: '', from_draw_d: true, from_draw_l: false });
    });
    // 鍵槽（深度自動 = 寬/2）
    kwWInst.forEach(function(kw, i) {
        var kl = kwLInst[i]||null;
        _wcSections.push({ type:'keyway', w: kw.value!==null?kw.value:'',
            l: kl&&kl.value!==null?kl.value:'', from_w: (bindings['keyway_w']||{}).label_name||'', from_draw_w: kw.from_draw });
    });
    renderWcpSections();
}

function wcRestoreFromJson(calc) {
    _wcCalcType = calc.type || 'shaft';
    document.querySelectorAll('input[name="wcp-type"]').forEach(function(r) { r.checked = (r.value === _wcCalcType); });
    _wcDensityId = calc.density_id || 0;
    _wcDensityG  = parseFloat(calc.density_g || 0);
    renderWcpDensityDropdown();
    _wcSections = (calc.sections || []);
    renderWcpSections();
}

function wcAddSection(type) {
    if (type === 'outer')  _wcSections.push({ type:'outer',  d:'', l:'', from_d:'', from_l:'', from_draw_d:false, from_draw_l:false });
    if (type === 'inner')  _wcSections.push({ type:'inner',  d:'', l:'', from_d:'', from_l:'', from_draw_d:false, from_draw_l:false });
    if (type === 'hole')   _wcSections.push({ type:'hole',   d:'', l:'', qty:'1', from_d:'', from_draw_d:false });
    if (type === 'keyway') _wcSections.push({ type:'keyway', w:'', l:'', from_w:'', from_draw_w:false });
    renderWcpSections();
    wcCalcTotal();
}

function wcRemoveSection(idx) {
    _wcSections.splice(idx, 1);
    renderWcpSections();
    wcCalcTotal();
}

function wcUpdateSection(idx, field, val) {
    if (_wcSections[idx]) { _wcSections[idx][field] = val; wcCalcTotal(); }
}

function renderWcpSections() {
    var outerWrap = document.getElementById('wcp-outer-sections');
    var innerWrap = document.getElementById('wcp-inner-sections');
    var otherWrap = document.getElementById('wcp-other-sections');
    if (!outerWrap || !innerWrap || !otherWrap) return;
    outerWrap.innerHTML = ''; innerWrap.innerHTML = ''; otherWrap.innerHTML = '';

    _wcSections.forEach(function(sec, idx) {
        var row = document.createElement('div');
        row.style.cssText = 'display:flex;align-items:center;gap:5px;margin-bottom:5px;background:#f8f9fa;border-radius:3px;padding:5px 7px;flex-wrap:wrap;';
        var html = '';
        var fromHint = '';

        if (sec.type === 'outer' || sec.type === 'inner') {
            var dLabel = sec.type === 'outer' ? 'Ø外' : 'Ø內';
            var dFrom  = sec.from_d ? (' <small style="color:#27ae60;font-size:10px;" title="來自標籤: ' + escHtml(sec.from_d) + (sec.from_draw_d ? '（圖面尺寸）' : '') + '">🏷</small>') : '';
            var lFrom  = sec.from_l ? (' <small style="color:#27ae60;font-size:10px;" title="來自標籤: ' + escHtml(sec.from_l) + (sec.from_draw_l ? '（圖面尺寸）' : '') + '">🏷</small>') : '';
            html += '<span style="font-size:11px;font-weight:600;color:' + (sec.type==='outer'?'#27ae60':'#e74c3c') + ';min-width:24px;">' + dLabel + '</span>';
            html += '<input type="number" class="form-control no-spin-input" style="width:68px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.d||'')) + '" placeholder="mm" oninput="wcUpdateSection(' + idx + ',\'d\',this.value)">' + dFrom;
            html += '<span style="font-size:11px;color:#888;">× 長</span>';
            html += '<input type="number" class="form-control no-spin-input" style="width:68px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.l||'')) + '" placeholder="mm" oninput="wcUpdateSection(' + idx + ',\'l\',this.value)">' + lFrom;
        } else if (sec.type === 'hole') {
            var dFrom = sec.from_d ? (' <small style="color:#9b59b6;font-size:10px;" title="來自標籤: ' + escHtml(sec.from_d) + '">🏷</small>') : '';
            html += '<span style="font-size:11px;font-weight:600;color:#9b59b6;min-width:24px;">孔Ø</span>';
            html += '<input type="number" class="form-control no-spin-input" style="width:58px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.d||'')) + '" placeholder="mm" oninput="wcUpdateSection(' + idx + ',\'d\',this.value)">' + dFrom;
            html += '<span style="font-size:11px;color:#888;">深</span>';
            html += '<input type="number" class="form-control no-spin-input" style="width:58px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.l||'')) + '" placeholder="mm" oninput="wcUpdateSection(' + idx + ',\'l\',this.value)">';
            html += '<span style="font-size:11px;color:#888;">×</span>';
            html += '<input type="number" class="form-control no-spin-input" style="width:44px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.qty||'1')) + '" placeholder="個" oninput="wcUpdateSection(' + idx + ',\'qty\',this.value)">';
            html += '<span style="font-size:11px;color:#888;">個</span>';
        } else if (sec.type === 'keyway') {
            var wFrom = sec.from_w ? (' <small style="color:#9b59b6;font-size:10px;" title="來自標籤: ' + escHtml(sec.from_w) + '">🏷</small>') : '';
            var autoH = sec.w ? trimFloat(parseFloat(sec.w)/2) : '?';
            html += '<span style="font-size:11px;font-weight:600;color:#9b59b6;min-width:24px;">鍵槽</span>';
            html += '<span style="font-size:11px;color:#888;">寬</span><input type="number" class="form-control no-spin-input" style="width:52px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.w||'')) + '" placeholder="mm" oninput="wcUpdateSection(' + idx + ',\'w\',this.value)">' + wFrom;
            html += '<span style="font-size:11px;color:#aaa;margin:0 4px;">深=' + autoH + '</span>';
            html += '<span style="font-size:11px;color:#888;">長</span><input type="number" class="form-control no-spin-input" style="width:52px;height:26px;font-size:12px;padding:2px 6px;display:inline-block;" value="' + escHtml(String(sec.l||'')) + '" placeholder="mm" oninput="wcUpdateSection(' + idx + ',\'l\',this.value)">';
        }

        html += '<button type="button" onclick="wcRemoveSection(' + idx + ')" style="background:none;border:none;color:#e74c3c;cursor:pointer;padding:0 2px;font-size:13px;" title="刪除">×</button>';
        row.innerHTML = html;

        if (sec.type === 'outer') outerWrap.appendChild(row);
        else if (sec.type === 'inner') innerWrap.appendChild(row);
        else otherWrap.appendChild(row);
    });
}

function wcCalcTotal() {
    var rho = parseFloat(_wcDensityG) || 0;
    var total_vol = 0;
    var lines = [];

    _wcSections.forEach(function(sec) {
        if (sec.type === 'outer' || sec.type === 'inner') {
            var D = parseFloat(sec.d); var L = parseFloat(sec.l);
            if (!isNaN(D) && D > 0 && !isNaN(L) && L > 0) {
                var vol = Math.PI / 4 * D * D * L;
                var sign = (sec.type === 'outer') ? 1 : -1;
                total_vol += sign * vol;
                var w = trimFloat(vol * rho / 1000);
                var op = (sec.type === 'outer') ? '+' : '－';
                var col = (sec.type === 'outer') ? '#27ae60' : '#e74c3c';
                var fromNote = sec.from_d ? (' <span style="color:#aaa;font-size:10px;">[來自: ' + escHtml(sec.from_d) + (sec.from_draw_d ? ' 圖面' : '') + ']</span>') : '';
                lines.push('<div style="color:' + col + ';">' + op + ' π/4×' + trimFloat(D) + '²×' + trimFloat(L) + '×' + trimFloat(rho) + '/1000 = <b>' + w + 'g</b>' + fromNote + '</div>');
            }
        } else if (sec.type === 'hole') {
            var D = parseFloat(sec.d); var L = parseFloat(sec.l); var Q = parseFloat(sec.qty)||1;
            if (!isNaN(D) && D > 0 && !isNaN(L) && L > 0) {
                var vol = Math.PI / 4 * D * D * L * Q;
                total_vol -= vol;
                var w = trimFloat(vol * rho / 1000);
                lines.push('<div style="color:#9b59b6;">－ 孔群(×' + trimFloat(Q) + '): π/4×' + trimFloat(D) + '²×' + trimFloat(L) + '×' + trimFloat(Q) + '×' + trimFloat(rho) + '/1000 = <b>' + w + 'g</b></div>');
            }
        } else if (sec.type === 'keyway') {
            var W = parseFloat(sec.w); var L = parseFloat(sec.l);
            var H = W / 2; // 深度自動 = 寬/2
            if (!isNaN(W) && W > 0 && !isNaN(L) && L > 0) {
                var vol = W * H * L;
                total_vol -= vol;
                var w = trimFloat(vol * rho / 1000);
                lines.push('<div style="color:#9b59b6;">－ 鍵槽: ' + trimFloat(W) + '×(寬/2=' + trimFloat(H) + ')×' + trimFloat(L) + '×' + trimFloat(rho) + '/1000 = <b>' + w + 'g</b></div>');
            }
        }
    });

    var formulaEl = document.getElementById('wcp-formula');
    if (formulaEl) formulaEl.innerHTML = lines.length ? lines.join('') : '<span style="color:#aaa;">尚未填入尺寸</span>';

    var total_g = total_vol * rho / 1000;
    _wcLastTotal_g = total_g;
    var totalEl = document.getElementById('wcp-total');
    if (totalEl) {
        if (total_g > 0) {
            var tg = trimFloat(total_g); var tkg = trimFloat(total_g / 1000);
            totalEl.innerHTML = '合計：<span style="font-size:16px;color:#1ABB9C;">' + tg + ' g</span> <span style="color:#888;font-size:12px;">(' + tkg + ' kg)</span>';
            var cl = document.getElementById('wcp-confirm-label');
            if (cl) cl.textContent = '帶入重量 ' + tg + 'g';
        } else {
            totalEl.innerHTML = '<span style="color:#aaa;">—</span>';
            var cl = document.getElementById('wcp-confirm-label');
            if (cl) cl.textContent = '帶入重量';
        }
    }
}

function wcInsertGearOD() {
    var ods = [];
    (gearRows || []).forEach(function(g) {
        var mStr = (g.Module || '').toString().replace(/^M/i, '').trim();
        var m = parseFloat(mStr);
        var z = parseInt(g.Teeth || '');
        if (!isNaN(m) && m > 0 && !isNaN(z) && z > 0) {
            var od, label, fromNote;
            var cat = getGearSpecCategory(g.Gear_Type);
            var typeName = getGearTypeName(g.Gear_Type);
            if (cat === 'spline' && g.spec_spline_std === 'DIN5480') {
                var db = parseFloat(g.spec_spline_nominal_dia || '');
                var x  = parseFloat(g.Profile_Shift_X || 0) || 0;
                var isInternal = typeName.indexOf('內') >= 0; // 含「內」(U+5167) → 內花鍵
                if (!isNaN(db) && db > 0) {
                    if (!isInternal) {
                        od = db - 0.2 * m;
                        fromNote = 'DIN5480 外花鍵 da=D_B-0.2m';
                        label = 'DIN5480 花鍵 D_B=' + trimFloat(db) + ' M' + trimFloat(m) + ' → 齒頂圓 Ø' + trimFloat(od);
                    } else {
                        od = db - 2 * m;
                        fromNote = 'DIN5480 內花鍵 di=D_B-2m';
                        label = 'DIN5480 內花鍵 D_B=' + trimFloat(db) + ' M' + trimFloat(m) + ' → 小徑 Ø' + trimFloat(od);
                    }
                } else {
                    if (!isInternal) {
                        od = m * z + 2 * m * (0.4 + x);
                        fromNote = 'DIN5480 外花鍵 da=mz+2m(0.4+x)';
                        label = 'DIN5480 花鍵 M' + trimFloat(m) + '×Z' + z + ' → 齒頂圓 Ø' + trimFloat(od);
                    } else {
                        od = m * z - 2 * m * (1 + x);
                        fromNote = 'DIN5480 內花鍵 di=mz-2m(1+x)';
                        label = 'DIN5480 內花鍵 M' + trimFloat(m) + '×Z' + z + ' → 小徑 Ø' + trimFloat(od);
                    }
                }
            } else {
                od = m * (z + 2);
                fromNote = '齒頂圓自動計算 (M×(Z+2))';
                label = 'M' + trimFloat(m) + ' × Z' + z + ' → 齒頂圓 Ø' + trimFloat(od);
            }
            ods.push({ od: od, label: label, fromNote: fromNote });
        }
    });
    if (!ods.length) { showToast('此料號尚未設定齒輪規格（模數/齒數）', 'warning'); return; }
    if (ods.length === 1) {
        _wcSections.push({ type:'outer', d: String(trimFloat(ods[0].od)), l:'', from_d: ods[0].fromNote, from_l:'', from_draw_d:false, from_draw_l:false });
        renderWcpSections();
        wcCalcTotal();
        showToast('已帶入齒頂圓：Ø' + trimFloat(ods[0].od) + ' mm', 'success');
    } else {
        var html = '<div style="font-size:12px;margin-bottom:6px;color:#555;">選擇齒型：</div>';
        ods.forEach(function(o, i) {
            html += '<button type="button" onclick="wcApplyGearOD(' + trimFloat(o.od) + ',\'' + escHtml(o.fromNote) + '\')" style="display:block;width:100%;text-align:left;padding:5px 10px;margin-bottom:3px;background:#fff3e0;border:1px solid #e67e22;color:#e67e22;border-radius:3px;cursor:pointer;font-size:12px;">' + escHtml(o.label) + '</button>';
        });
        var existing = document.getElementById('wcp-gear-picker');
        if (existing) existing.remove();
        var picker = document.createElement('div');
        picker.id = 'wcp-gear-picker';
        picker.style.cssText = 'background:#fff;border:1px solid #e67e22;border-radius:4px;padding:10px;margin-bottom:8px;';
        picker.innerHTML = html;
        var outerWrap = document.getElementById('wcp-outer-sections');
        if (outerWrap) outerWrap.parentNode.insertBefore(picker, outerWrap);
    }
}

function wcApplyGearOD(od, fromNote) {
    _wcSections.push({ type:'outer', d: String(trimFloat(od)), l:'', from_d: fromNote||'齒頂圓自動計算 (M×(Z+2))', from_l:'', from_draw_d:false, from_draw_l:false });
    var picker = document.getElementById('wcp-gear-picker');
    if (picker) picker.remove();
    renderWcpSections();
    wcCalcTotal();
    showToast('已帶入齒頂圓：Ø' + trimFloat(od) + ' mm', 'success');
}

function wcConfirm() {
    var g = _wcLastTotal_g || 0;
    if (g <= 0) { showToast('重量計算結果為零或無效，請檢查輸入', 'warning'); return; }
    var calcJson = {
        type: _wcCalcType, density_id: _wcDensityId, density_g: _wcDensityG,
        sections: _wcSections, calc_weight_g: g, calc_at: new Date().toISOString()
    };
    // Save to DB directly
    api({ action: 'save_weight_calc', d_id: _wcPartDId, weight_g: g, calc_json: JSON.stringify(calcJson) }).done(function(r) {
        if (!r.success) { showToast(r.message || '儲存失敗', 'error'); return; }
        // Update form fields
        _setWeightUnit('g');
        document.getElementById('pf-Weight_Kg').value = String(trimFloat(g));
        document.getElementById('pf-weight-source').value    = 'calculated';
        document.getElementById('pf-weight-calc-json').value = JSON.stringify(calcJson);
        var badge = document.getElementById('pf-weight-source-badge');
        if (badge) badge.style.display = '';
        closeWeightCalcPanel();
        showToast('重量已帶入：' + trimFloat(g) + 'g（計算值）', 'success');
    });
}

function onWeightManualChange() {
    document.getElementById('pf-weight-source').value    = 'manual';
    document.getElementById('pf-weight-calc-json').value = '';
    var badge = document.getElementById('pf-weight-source-badge');
    if (badge) badge.style.display = 'none';
}

// ═══════════════════════════════════════════════════════════════════════════
// 複製標籤 & 齒輪資料
// ═══════════════════════════════════════════════════════════════════════════
var _copySearchTimer;

function openCopyLabelsModal() {
    var d_id = parseInt(document.getElementById('pf-d_id').value || '0');
    document.getElementById('cls-keyword').value  = '';
    document.getElementById('cls-customer').value = '';
    document.getElementById('cls-type').value     = '';
    // Trigger backdrop fix for nested modal
    $('#copyLabelsModal').modal('show');
    setTimeout(function() { $('.modal-backdrop').last().css('z-index', 1055); }, 50);
    searchCopySource();
}

function debouncedCopySearch() {
    clearTimeout(_copySearchTimer);
    _copySearchTimer = setTimeout(searchCopySource, 300);
}

function searchCopySource() {
    var d_id = parseInt(document.getElementById('pf-d_id').value || '0');
    var kw   = document.getElementById('cls-keyword').value.trim();
    var cust = document.getElementById('cls-customer').value.trim();
    var type = document.getElementById('cls-type').value;
    var res  = document.getElementById('cls-results');
    res.innerHTML = '<div style="padding:16px;text-align:center;color:#aaa;font-size:13px;"><i class="fa fa-spinner fa-spin"></i> 搜尋中…</div>';
    api({ action: 'search_parts_for_copy', keyword: kw, customer: cust, type_code: type, exclude_d_id: d_id }).done(function(r) {
        if (!r.success) { res.innerHTML = '<div style="padding:16px;color:#e74c3c;">' + escHtml(r.message || '搜尋失敗') + '</div>'; return; }
        if (!r.data || !r.data.length) {
            res.innerHTML = '<div style="padding:20px;text-align:center;color:#aaa;font-size:13px;">無符合的料號（只顯示有標籤或齒輪資料的料號）</div>';
            return;
        }
        var html = '<table class="table table-condensed table-hover" style="margin:0;font-size:12px;">';
        html += '<thead><tr style="background:#f8f9fa;"><th>料號</th><th>客戶</th><th>種類</th><th>標籤</th><th>齒輪規格</th><th></th></tr></thead><tbody>';
        r.data.forEach(function(p) {
            var tl = p.Type === 'G' ? '齒輪' : p.Type === 'H' ? '滾刀' : '一般';
            var li = p.label_count > 0
                ? '<span style="color:#1ABB9C;">' + p.label_count + '項</span>' + (p.label_names ? '<br><small style="color:#888;">' + escHtml(p.label_names) + '</small>' : '')
                : '<span style="color:#ccc;">無</span>';
            var gi = p.gear_summary ? '<small style="color:#e67e22;">' + escHtml(p.gear_summary) + '</small>' : '<span style="color:#ccc;">—</span>';
            html += '<tr><td><strong>' + escHtml(p.D_Setting_Id) + '</strong></td>';
            html += '<td>' + escHtml(p.client_name || '—') + '</td>';
            html += '<td>' + tl + '</td><td>' + li + '</td><td>' + gi + '</td>';
            html += '<td><button class="btn btn-xs btn-success" onclick="applyCopySource(' + p.d_id + ')"><i class="fa fa-check"></i> 套用</button></td></tr>';
        });
        html += '</tbody></table>';
        res.innerHTML = html;
    }).fail(function() { res.innerHTML = '<div style="padding:16px;color:#e74c3c;">搜尋失敗</div>'; });
}

function applyCopySource(src_d_id) {
    api({ action: 'get_part', d_id: src_d_id }).done(function(r) {
        if (!r.success) { showToast(r.message || '讀取失敗', 'error'); return; }
        var src = r.data;
        var copied_labels = 0; var copied_gear = false; var copied_type = false;

        // 1. Merge labels: only add if label_id not already in _partLabelData
        var existIds = {};
        (_partLabelData || []).forEach(function(l) { existIds[String(l.label_id)] = true; });
        (src.labels || []).forEach(function(lbl) {
            if (!existIds[String(lbl.label_id)]) { _partLabelData.push(lbl); copied_labels++; }
        });

        // 2. Merge gear: only if current has no gear rows
        if (gearRows.length === 0 && src.gears && src.gears.length) {
            src.gears.forEach(function(g) { addGearRow(g); });
            copied_gear = true;
        }

        // 3. Copy workpiece type (N/G/H) and sub-type
        var typeEl = document.getElementById('pf-Type');
        var curType = typeEl ? typeEl.value : 'N';
        if (typeEl && src.Type && typeEl.value !== src.Type) {
            typeEl.value = src.Type;
            curType = src.Type;
            copied_type = true;
            // Update gear section visibility without resetting gear data
            var gs = document.getElementById('gear-section');
            if (gs) { src.Type === 'G' ? $(gs).slideDown(200) : $(gs).slideUp(200); }
        }
        // Copy workpiece sub-type regardless (may change even if Type is same)
        if (src.workpiece_sub_type_id) {
            loadPartSubTypes(curType, src.workpiece_sub_type_id);
        }

        // 4. Re-render labels
        if (copied_type) {
            // Reload label definitions for the new type, preserving merged label data
            loadPartLabels(curType, _partLabelData);
        } else {
            if (_labelDefs && _labelDefs.length) renderPartLabelChips(_labelDefs, _partLabelData);
            syncPartLabelsJson();
        }

        var parts = [];
        if (copied_labels > 0) parts.push(copied_labels + ' 個標籤');
        if (copied_gear) parts.push('齒輪規格');
        if (copied_type) parts.push('工件種類(' + src.Type + ')');
        var msg = parts.length
            ? '已複製 ' + parts.join(' + ')
            : '來源料號的標籤/齒輪/工件種類資料已全部相同，無需複製';
        showToast(msg, parts.length ? 'success' : 'info');
        $('#copyLabelsModal').modal('hide');
    });
}

// 由其他頁面連結帶入 hash 自動開啟跳窗
window.addEventListener('load', function() {
    var hash = window.location.hash;
    history.replaceState(null, '', window.location.pathname + window.location.search);
    if (hash === '#open-customer') {
        openCustomerModal(null);
    } else if (hash === '#open-part') {
        openPartModal(null);
    } else {
        var m = hash.match(/^#edit-part-(\d+)$/);
        if (m) { openPartModal(parseInt(m[1])); return; }
        var mc = hash.match(/^#edit-customer-(.+)$/);
        if (mc) openCustomerModal(decodeURIComponent(mc[1]));
    }
});
</script>
</body>
</html>